import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { Club } from "@/services/clubs";
import { communityApi } from "@/services/community";
import { getSession } from "@/services/auth";

type FieldDef = Club["registrationFields"][number];

/**
 * The unique per-club registration form. Each club defines its own fields
 * (see the clubs catalogue).
 */
export default function ClubRegistrationModal({
  club,
  onClose,
  presetAnswers,
  initialAnswers,
  onRegistered,
}: {
  club: Club;
  onClose: () => void;
  /** Extra hidden answers merged into the submission (e.g. the activity being joined). */
  presetAnswers?: Record<string, string>;
  /** Visible field values to start from (e.g. the member's previous registration). */
  initialAnswers?: Record<string, string>;
  /** Called after a successful submission — lets the host screen refresh. */
  onRegistered?: () => void;
}) {
  const insets = useSafeAreaInsets();
  const [answers, setAnswers] = useState<Record<string, string>>(
    initialAnswers ?? {},
  );
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const setAnswer = (key: string, value: string) =>
    setAnswers((prev) => ({ ...prev, [key]: value }));

  const submit = async () => {
    setError(null);
    const session = await getSession();
    if (!session?.user) {
      setError("Please sign in first to register for this club.");
      return;
    }
    const missing = club.registrationFields.filter(
      (f) => !(answers[f.key] || "").trim(),
    );
    if (missing.length > 0) {
      setError(`Please fill in: ${missing.map((f) => f.label).join(", ")}`);
      return;
    }
    setSubmitting(true);
    try {
      await communityApi.registerForClub(club.slug, {
        ...(presetAnswers || {}),
        ...answers,
      });
      setDone(true);
    } catch (e: any) {
      setError(e?.message || "Could not submit your registration. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal visible animationType="slide" statusBarTranslucent onRequestClose={onClose}>
      <View style={[s.safe, { paddingTop: insets.top }]}>
        <LinearGradient
          colors={[club.color, club.colorDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.head}
        >
          <View style={s.headRow}>
            <View style={s.headIcon}>
              <Ionicons name={club.icon as any} size={20} color={colors.white} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.headEyebrow}>JOIN {club.group.toUpperCase()}</Text>
              <Text style={s.headTitle}>{club.name} registration</Text>
            </View>
            <TouchableOpacity onPress={onClose} style={s.closeBtn} accessibilityLabel="Close">
              <Ionicons name="close" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>
          <Text style={s.headSub}>
            Fill in this {club.name}-specific form to complete your club
            registration.
          </Text>
        </LinearGradient>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          {done ? (
            <ScrollView contentContainerStyle={s.doneWrap}>
              <View style={[s.doneIcon, { backgroundColor: `${club.color}22` }]}>
                <Ionicons name="checkmark-circle" size={44} color={club.colorDark} />
              </View>
              <Text style={s.doneTitle}>You&rsquo;re registered! 🎉</Text>
              <Text style={s.doneText}>
                Your {club.name} registration is in. Your leader will be in
                touch with everything you need to know.
              </Text>
              <TouchableOpacity
                onPress={() => {
                  onRegistered?.();
                  onClose();
                }}
                style={s.doneClose}
              >
                <Text style={s.doneCloseText}>Done</Text>
              </TouchableOpacity>
            </ScrollView>
          ) : (
            <ScrollView
              contentContainerStyle={s.form}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              {club.registrationFields.map((field: FieldDef) => (
                <View key={field.key} style={s.field}>
                  <Text style={s.label}>{field.label}</Text>
                  <TextInput
                    style={[s.input, field.multiline && s.inputMultiline]}
                    placeholder={field.placeholder || ""}
                    placeholderTextColor={colors.muted}
                    value={answers[field.key] || ""}
                    onChangeText={(t) => setAnswer(field.key, t)}
                    multiline={field.multiline}
                    textAlignVertical={field.multiline ? "top" : "center"}
                    autoCapitalize="none"
                    keyboardType={
                      field.key === "phone" ? "phone-pad" : "default"
                    }
                  />
                </View>
              ))}

              {error ? (
                <View style={s.errorRow}>
                  <Ionicons name="alert-circle" size={14} color={colors.error} />
                  <Text style={s.errorText}>{error}</Text>
                </View>
              ) : null}

              <TouchableOpacity
                style={[s.submitBtn, { backgroundColor: club.colorDark }]}
                activeOpacity={0.85}
                onPress={submit}
                disabled={submitting}
              >
                {submitting ? (
                  <ActivityIndicator size="small" color={colors.white} />
                ) : (
                  <>
                    <Text style={s.submitText}>Register for {club.name}</Text>
                    <Ionicons name="arrow-forward" size={16} color={colors.white} />
                  </>
                )}
              </TouchableOpacity>
              <Text style={s.consent}>
                By registering you agree to be contacted about {club.name}{" "}
                activities. We&rsquo;ll never share your details.
              </Text>
            </ScrollView>
          )}
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

