import { cachedFetch, SHORT_TTL, type CachedFetchOptions } from "./cache";
import { fetchMobileBadges } from "./mobile-badges";

export type HelpMessage = {
  from: "user" | "admin" | "system";
  fromName: string;
  text: string;
  createdAt: string;
};

export type HelpRequestStatus = "open" | "in_progress" | "resolved" | "archived";

export type HelpRequest = {
  _id: string;
  name: string;
  email: string;
  phone: string;
  area?: string;
  ageGroup?: string;
  contactMethod?: string;
  urgency?: string;
  whoFor?: string;
  helpType: string;
  description: string;
  userId: string | null;
  status?: HelpRequestStatus;
  messages?: HelpMessage[];
  recordId?: string | null;
  assignedTo?: string | null;
  assignedToName?: string | null;
  assignedAt?: string | null;
  lastUserReadAt?: string | null;
  lastAdminReadAt?: string | null;
  createdAt: string;
  updatedAt?: string;
};

export type HelpRequestInput = {
  name: string;
  email: string;
  phone: string;
  area?: string;
  ageGroup?: string;
  contactMethod?: string;
  urgency?: string;
  whoFor?: string;
  helpType: string;
  description: string;
};

export type HelpEditFields = Partial<
  Pick<
    HelpRequest,
    | "name"
    | "email"
    | "phone"
    | "area"
    | "ageGroup"
    | "contactMethod"
    | "urgency"
    | "whoFor"
    | "helpType"
    | "description"
  >
>;

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/help-requests", "/api/mobile/badges"]);
}

export const helpApi = {
  /** Authenticated users submit a help request. */
  create: (data: HelpRequestInput) =>
    apiFetch<{ data: HelpRequest }>("/api/help-requests", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  /** Admin only: list all help requests, newest first. Optionally filter by status and/or "assigned=me". */
  list: (status?: HelpRequestStatus, assigned?: boolean) => {
    const params = new URLSearchParams();
    if (status) params.set("status", status);
    if (assigned) params.set("assigned", "me");
    const qs = params.toString();
    return apiFetch<{ data: HelpRequest[] }>(
      `/api/help-requests${qs ? `?${qs}` : ""}`,
    );
  },

  /** Authenticated user: list their own requests. */
  mine: () => apiFetch<{ data: HelpRequest[] }>("/api/help-requests/mine"),

  /** Owner or admin: fetch a single request (with messages). */
  get: (id: string, options?: { cacheTtl?: number }) =>
    apiFetch<{ data: HelpRequest }>(`/api/help-requests/${id}`, {
      cacheTtl: options?.cacheTtl ?? SHORT_TTL,
    }),

  /** Owner edits request fields (while open); admin can pass { status }. */
  update: (id: string, data: { field?: HelpEditFields; status?: HelpRequestStatus }) =>
    apiFetch<{ data: HelpRequest }>(`/api/help-requests/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  /** Admin convenience: change request status. */
  updateStatus: (id: string, status: HelpRequestStatus) =>
    apiFetch<{ data: HelpRequest }>(`/api/help-requests/${id}`, {
      method: "PATCH",
      body: JSON.stringify({ status }),
    }),

  /** Admin only: assign (true) or unassign (false) the request to the acting admin. */
  assign: (id: string, assign: boolean) =>
    apiFetch<{ data: HelpRequest }>(`/api/help-requests/${id}/assign`, {
      method: "POST",
      body: JSON.stringify({ assign }),
    }),

  /** Owner (open requests) or admin: delete a request. */
  remove: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/help-requests/${id}`, {
      method: "DELETE",
    }),

  /** Owner or admin: send a message on the request thread. */
  sendMessage: (id: string, text: string) =>
    apiFetch<{ data: { message: HelpMessage; request: HelpRequest } }>(
      `/api/help-requests/${id}/messages`,
      {
        method: "POST",
        body: JSON.stringify({ text }),
      },
    ),

  /** Admin only: create a family record from the request. */
  convert: (id: string) =>
    apiFetch<{ data: { recordId: string; alreadyCreated: boolean } }>(
      `/api/help-requests/${id}/convert`,
      { method: "POST" },
    ),

  /** Owner or admin: mark a request as read by the current viewer. */
  markRead: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/help-requests/${id}/read`, {
      method: "POST",
    }),

  /** Unread counts: userUnread for the requester, adminUnread for admins. */
  unreadCounts: async () => {
    const res = await fetchMobileBadges();
    return {
      data: {
        userUnread: res.data.userUnread,
        adminUnread: res.data.adminUnread,
      },
    };
  },
};
