import { type SQLiteDatabase } from "expo-sqlite";
import { API_BASE } from "@/services/config";
import { getCachedUserId, getRequestHeaders } from "@/services/auth";

/**
 * Minimal, serializable card data for the home "What's new" rail — only the
 * fields the cards render. Full events/groups/skills stay server-side; the app
 * shows this snapshot offline and refreshes it only when the server version
 * bumps (create/edit/delete).
 */

export type DiscoverEventCard = {
  _id: string;
  title: string;
  date: string;
  time: string;
  dateTo?: string;
  timeTo?: string;
  location: string;
  imageUrl: string | null;
  createdAt: string;
};

export type DiscoverGroupCard = {
  _id: string;
  name: string;
  imageUrl: string | null;
  members: number;
  maxMembers: number;
  meetingTime: string;
  live: boolean;
  createdAt: string;
};

export type DiscoverSkillCard = {
  _id: string;
  title: string;
  category: string;
  offering: boolean;
  createdAt: string;
};

export type DiscoverBookmarkCard = {
  section: string;
  itemId: string;
};

export type DiscoverSnapshot = {
  events: DiscoverEventCard[];
  groups: DiscoverGroupCard[];
  skills: DiscoverSkillCard[];
  bookmarks: DiscoverBookmarkCard[];
  version: string;
  /** Which account this snapshot's bookmarks belong to, or null if signed out. */
  ownerId: string | null;
  /** When this snapshot was pulled (ms epoch). Backs the refresh throttle. */
  fetchedAt: number;
};

/** SQLite datetime('now') is UTC with no zone marker, so parse it as such. */
function parseSqlUtc(value?: string | null): number {
  if (!value) return 0;
  const ms = Date.parse(`${value.replace(" ", "T")}Z`);
  return Number.isFinite(ms) ? ms : 0;
}

export function loadDiscoverSnapshot(db: SQLiteDatabase): DiscoverSnapshot | null {
  try {
    const row = db.getFirstSync<{
      cards_json: string;
      version: string;
      fetched_at: string | null;
    }>(
      `SELECT cards_json, version, fetched_at FROM discover_snapshot WHERE id = 1`,
    );
    if (!row) return null;
    const parsed = JSON.parse(row.cards_json || "{}");
    return {
      events: Array.isArray(parsed.events) ? parsed.events : [],
      groups: Array.isArray(parsed.groups) ? parsed.groups : [],
      skills: Array.isArray(parsed.skills) ? parsed.skills : [],
      bookmarks: Array.isArray(parsed.bookmarks) ? parsed.bookmarks : [],
      version: String(row.version ?? "0"),
      ownerId: typeof parsed.ownerId === "string" ? parsed.ownerId : null,
      fetchedAt: parseSqlUtc(row.fetched_at),
    };
  } catch {
    return null;
  }
}

function saveDiscoverSnapshot(db: SQLiteDatabase, snapshot: DiscoverSnapshot): void {
  try {
    const stamp = new Date(snapshot.fetchedAt || Date.now())
      .toISOString()
      .slice(0, 19)
      .replace("T", " ");
    db.runSync(
      `INSERT INTO discover_snapshot (id, cards_json, version, fetched_at)
       VALUES (1, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         cards_json = excluded.cards_json,
         version = excluded.version,
         fetched_at = excluded.fetched_at`,
      [
        JSON.stringify({
          events: snapshot.events,
          groups: snapshot.groups,
          skills: snapshot.skills,
          bookmarks: snapshot.bookmarks,
          ownerId: snapshot.ownerId,
        }),
        String(snapshot.version),
        stamp,
      ],
    );
  } catch {}
}

/**
 * Persists a bookmark toggle without moving `fetchedAt`, so saving a card
 * survives the next refocus but doesn't postpone the content refresh.
 */
export function setDiscoverBookmark(
  db: SQLiteDatabase,
  section: string,
  itemId: string,
  saved: boolean,
): void {
  const local = loadDiscoverSnapshot(db);
  if (!local) return;
  const rest = local.bookmarks.filter(
    (b) => !(b.section === section && b.itemId === itemId),
  );
  saveDiscoverSnapshot(db, {
    ...local,
    bookmarks: saved ? [...rest, { section, itemId }] : rest,
  });
}

async function fetchDiscoverVersion(): Promise<string> {
  try {
    const res = await fetch(`${API_BASE}/api/discover/version`);
    if (!res.ok) return "0";
    const json = (await res.json()) as { version?: number | string };
    return String(json?.version ?? "0");
  } catch {
    return "0";
  }
}

async function apiJson<T = { data: unknown[] | null }>(
  path: string,
): Promise<T | null> {
  try {
    const res = await fetch(`${API_BASE}${path}`, {
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
    });
    if (!res.ok) return null;
    return (await res.json()) as T;
  } catch {
    return null;
  }
}

function toEventCard(e: any): DiscoverEventCard {
  return {
    _id: e?._id ?? "",
    title: e?.title ?? "",
    date: e?.date ?? "",
    time: e?.time ?? "",
    ...(e?.dateTo ? { dateTo: e.dateTo } : {}),
    ...(e?.timeTo ? { timeTo: e.timeTo } : {}),
    location: e?.location ?? "",
    imageUrl: e?.imageUrl ?? null,
    createdAt: e?.createdAt ?? "",
  };
}

function toGroupCard(g: any): DiscoverGroupCard {
  return {
    _id: g?._id ?? "",
    name: g?.name ?? "",
    imageUrl: g?.imageUrl ?? null,
    members: g?.members ?? 0,
    maxMembers: g?.maxMembers ?? 0,
    meetingTime: g?.meetingTime ?? "",
    live: !!g?.live,
    createdAt: g?.createdAt ?? "",
  };
}

function toSkillCard(s: any): DiscoverSkillCard {
  return {
    _id: s?._id ?? "",
    title: s?.title ?? "",
    category: s?.category ?? "",
    offering: s?.offering ?? true,
    createdAt: s?.createdAt ?? "",
  };
}

async function fetchBookmarkRefs(): Promise<DiscoverBookmarkCard[]> {
  const res = await apiJson<{ data: unknown[] }>("/api/bookmarks?view=ref");
  const bookmarks: DiscoverBookmarkCard[] = [];
  for (const b of res?.data ?? []) {
    const row = b as { section?: string; itemId?: string };
    if (row?.section && row.itemId) {
      bookmarks.push({ section: row.section, itemId: row.itemId });
    }
  }
  return bookmarks;
}

async function fetchDiscoverData(): Promise<
  Pick<DiscoverSnapshot, "events" | "groups" | "skills" | "bookmarks"> | null
> {
  // ?view=card returns only the fields the rail renders, so the server skips
  // participant, registration and comment joins. Skills are capped at the 3
  // the rail shows; bookmarks come back as refs with no document hydration.
  const [eventsRes, groupsRes, skillsRes, bookmarks] = await Promise.all([
    apiJson<{ data: unknown[] }>("/api/community/events?view=card"),
    apiJson<{ data: unknown[] }>("/api/community/groups?view=card"),
    apiJson<{ data: unknown[] }>("/api/community/skills?view=card&limit=3"),
    fetchBookmarkRefs(),
  ]);

  return {
    events: (eventsRes?.data ?? []).map(toEventCard),
    groups: (groupsRes?.data ?? []).map(toGroupCard),
    skills: (skillsRes?.data ?? []).map(toSkillCard),
    bookmarks,
  };
}

// At most one version probe per window. Refocusing Home or remounting the rail
// paints the SQLite snapshot instead of going to the server.
const SYNC_THROTTLE = 5 * 60_000;
let inFlight: Promise<DiscoverSnapshot | null> | null = null;

/**
 * Refreshes the snapshot only when the throttle window has elapsed and the
 * server's content version moved. `force` (pull-to-refresh) skips the window
 * but still compares versions, so an unchanged feed costs one small probe.
 * Resolves to the new snapshot, or null when the cached one is still current.
 * Concurrent callers share a single request.
 */
export function syncDiscover(
  db: SQLiteDatabase,
  force = false,
): Promise<DiscoverSnapshot | null> {
  if (inFlight) return inFlight;
  inFlight = runSync(db, force).finally(() => {
    inFlight = null;
  });
  return inFlight;
}

async function runSync(
  db: SQLiteDatabase,
  force: boolean,
): Promise<DiscoverSnapshot | null> {
  try {
    const ownerId = await getCachedUserId();
    const local = loadDiscoverSnapshot(db);
    const now = Date.now();

    // Bookmarks are the only per-account part of the snapshot, so an identity
    // change reconciles those alone. A null id can mean "signed out" or "the
    // secure store hasn't answered yet" — neither is worth re-pulling the
    // public feed for, and signed out means no bookmarks by definition.
    if (local && local.ownerId !== ownerId) {
      const bookmarks = ownerId ? await fetchBookmarkRefs() : [];
      const next: DiscoverSnapshot = { ...local, bookmarks, ownerId };
      // fetchedAt is left untouched: the content is exactly as fresh as it was.
      saveDiscoverSnapshot(db, next);
      return next;
    }

    if (!force && local?.fetchedAt && now - local.fetchedAt < SYNC_THROTTLE) {
      return null;
    }

    const version = await fetchDiscoverVersion();

    // "0" also means the probe failed. Either way, stamp the attempt so an
    // unreachable or unchanged feed isn't re-probed on every focus.
    if (version === "0" && local) {
      saveDiscoverSnapshot(db, { ...local, fetchedAt: now });
      return null;
    }
    if (local && version === local.version) {
      saveDiscoverSnapshot(db, { ...local, fetchedAt: now });
      return null;
    }

    const fresh = await fetchDiscoverData();
    if (!fresh) return null;
    const snapshot: DiscoverSnapshot = {
      ...fresh,
      version,
      ownerId,
      fetchedAt: Date.now(),
    };
    saveDiscoverSnapshot(db, snapshot);
    return snapshot;
  } catch {
    return null;
  }
}

/**
 * Warms the snapshot while the welcome screen is up, so the home "Up Coming"
 * rail paints from cache on entry. Shares the rail's throttle and in-flight
 * request, so a launch right after a pull costs nothing.
 */
export async function prefetchDiscover(db: SQLiteDatabase): Promise<void> {
  await syncDiscover(db);
}