import { API_BASE, IS_WEB } from "@/services/config";
import { appStorage } from "@/services/app-storage";
import { getRequestHeaders, getSessionToken } from "@/services/auth";
import { cachedFetch, invalidateCache } from "@/services/cache";
import { type SQLiteDatabase } from "expo-sqlite";

const STREAKS_PATH = "/api/streaks";
const STREAK_SUMMARY_PATH = "/api/streaks/summary";
const READING_PATH = "/api/reading-streak";

export type PrayerKey = "dawn" | "sunrise" | "noon" | "afternoon" | "sunset" | "evening";

export type DayRecord = Record<string, boolean | string>;

export type StreakData = Record<string, DayRecord>;

export type PrayerRequestEntry = {
  id?: number;
  text: string;
  done: boolean;
  createdAt: string;
  name?: string;
  topic?: string;
};

function getDateKey(date?: Date) {
  const d = date || new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

export function getTodayKey() {
  return getDateKey();
}

async function apiHeaders() {
  return getRequestHeaders({ "Content-Type": "application/json" });
}

// throttle: at most one server pull per window unless forced (pull-to-refresh)
let lastFetch = 0;
let forceNextFetch = false;
const FETCH_THROTTLE = 60_000;

/** Force the next loadStreakData() to pull from the server (pull-to-refresh). */
export function resetStreakFetchThrottle() {
  lastFetch = 0;
  forceNextFetch = true;
}

let serverStreakCache: StreakData = {};
// Which session the cached streaks belong to. A different cookie means a
// different account (or no account), so the cache must not carry over.
let cacheToken: string | null = null;

export async function loadStreakData(force = false): Promise<StreakData> {
  const token = await getSessionToken();
  // Signed out: never hand back the previous account's streak.
  if (!token) {
    serverStreakCache = {};
    cacheToken = null;
    return {};
  }

  // Account switch: drop the old streak and skip the throttle so the new
  // user's streak is fetched right away.
  if (token !== cacheToken) {
    serverStreakCache = {};
    cacheToken = token;
    lastFetch = 0;
    forceNextFetch = true;
  }

  const shouldRefresh = force || forceNextFetch;
  forceNextFetch = false;
  const now = Date.now();
  if (!shouldRefresh && now - lastFetch < FETCH_THROTTLE) return serverStreakCache;
  lastFetch = now;

  try {
    const summary = await cachedFetch<{
      data: { streaks?: unknown; days?: unknown };
    }>(STREAK_SUMMARY_PATH, {
      cacheTtl: FETCH_THROTTLE,
      forceRefresh: shouldRefresh,
    });
    const serverStreaks: StreakData =
      summary.data.streaks && typeof summary.data.streaks === "object"
        ? (summary.data.streaks as StreakData)
        : {};
    const serverDays = Array.isArray(summary.data.days)
      ? summary.data.days.filter((d): d is string => typeof d === "string")
      : [];

    const merged: StreakData = { ...serverStreaks };
    for (const d of serverDays) {
      merged[d] = { ...(merged[d] || createEmptyDay()), readMagazine: d };
    }
    serverStreakCache = merged;
    return merged;
  } catch {
    return serverStreakCache;
  }
}

async function pushStreaksApi(data: StreakData): Promise<boolean> {
  try {
    const res = await fetch(`${API_BASE}${STREAKS_PATH}`, {
      method: "PUT",
      headers: await apiHeaders(),
      body: JSON.stringify({ streaks: data }),
    });
    if (res.ok) invalidateCache(STREAK_SUMMARY_PATH, await getSessionToken());
    return res.ok;
  } catch {
    return false;
  }
}

async function pushReadingApi(days: string[]): Promise<boolean> {
  try {
    await cachedFetch(
      READING_PATH,
      {
        method: "POST",
        body: JSON.stringify({ days }),
      },
      [READING_PATH, STREAK_SUMMARY_PATH],
    );
    return true;
  } catch {
    return false;
  }
}

export async function togglePrayer(
  dateKey: string,
  prayer: string,
  existingData?: StreakData,
): Promise<StreakData> {
  const data: StreakData = existingData ? { ...existingData } : { ...serverStreakCache };
  const day = data[dateKey] || createEmptyDay();
  day[prayer] = !day[prayer];
  data[dateKey] = day;
  serverStreakCache = data;

  await pushStreaksApi(data);
  return data;
}

export function createEmptyDay(): DayRecord {
  return {
    dawn: false,
    sunrise: false,
    noon: false,
    afternoon: false,
    sunset: false,
    evening: false,
  };
}

const STREAK_THRESHOLD = 3;

export function calcStreak(data: StreakData): number {
  let streak = 0;
  const today = new Date();
  const todayKey = getDateKey(today);
  const todayDay = data[todayKey];
  if (todayDay) {
    const completed = Object.values(todayDay).filter((v) => v === true).length;
    if (completed >= STREAK_THRESHOLD) streak++;
  }
  for (let i = 1; ; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    const key = getDateKey(d);
    const day = data[key];
    if (!day) break;
    const completed = Object.keys(day).filter((p) => day[p] === true).length;
    if (completed < STREAK_THRESHOLD) break;
    streak++;
  }
  return streak;
}

export function calcPrayersLeftToday(data: StreakData): number {
  const today = new Date();
  const key = getDateKey(today);
  const day = data[key];
  if (!day) return STREAK_THRESHOLD;
  const completed = Object.values(day).filter((v) => v === true).length;
  return Math.max(0, STREAK_THRESHOLD - completed);
}

export function calcBibleStreak(data: StreakData): number {
  let streak = 0;
  const today = new Date();
  if (data[getDateKey(today)]?.readBible) streak++;
  for (let i = 1; ; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    const key = getDateKey(d);
    const day = data[key];
    if (!day || !day.readBible) break;
    streak++;
  }
  return streak;
}

export function isBibleReadToday(data: StreakData): boolean {
  return !!data[getDateKey()]?.readBible;
}

export function calcMagazineStreak(data: StreakData): number {
  let streak = 0;
  const today = new Date();
  if (data[getDateKey(today)]?.readMagazine) streak++;
  for (let i = 1; ; i++) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    const key = getDateKey(d);
    const day = data[key];
    if (!day || !day.readMagazine) break;
    streak++;
  }
  return streak;
}

export function isMagazineReadToday(data: StreakData): boolean {
  return !!data[getDateKey()]?.readMagazine;
}

export async function markBibleRead(
  dateKey: string,
  existingData?: StreakData,
): Promise<StreakData> {
  const data: StreakData = existingData ? { ...existingData } : { ...serverStreakCache };
  const day = data[dateKey] || createEmptyDay();
  if (day.readBible) return data;
  day.readBible = dateKey;
  data[dateKey] = day;
  serverStreakCache = data;

  await pushStreaksApi(data);
  return data;
}

/**
 * Records that the user completed a magazine/study-guide reading on `dateKey`.
 * This is the streak that drives the home "reading track" badge — the reading
 * days are mirrored to the server so the streak survives an app reinstall.
 */
export async function markMagazineRead(
  dateKey: string,
  existingData?: StreakData,
): Promise<StreakData> {
  const data: StreakData = existingData ? { ...existingData } : { ...serverStreakCache };
  const day = data[dateKey] || createEmptyDay();
  if (day.readMagazine) return data;
  day.readMagazine = dateKey;
  data[dateKey] = day;
  serverStreakCache = data;

  const readingDays = Object.keys(data)
    .filter((k) => data[k].readMagazine)
    .sort();

  await Promise.all([
    pushStreaksApi(data),
    pushReadingApi(readingDays),
  ]);
  return data;
}

export async function resetStreakData() {
  serverStreakCache = {};
  await pushStreaksApi({});
  await pushReadingApi([]);
}

// Prayer focus — local SQLite storage of "what I want to pray for" per
// session (keyed `${dateKey}_${prayerKey}`). Every call is async and
// self-healing: a device with an older prayer_requests schema is repaired
// here instead of throwing, so no screen can be taken down by a read.
export type PrayerFocusMap = Record<string, PrayerRequestEntry[]>;

export type PrayerFocusWrite = {
  ok: boolean;
  all: PrayerFocusMap;
  /** Underlying SQLite error when a write failed (shown as a detail line). */
  reason?: string;
};

const PRAYER_FOCUS_TABLE = `
  CREATE TABLE IF NOT EXISTS prayer_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT NOT NULL DEFAULT 'local',
    day_key TEXT NOT NULL DEFAULT '',
    text TEXT NOT NULL DEFAULT '',
    done INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    name TEXT NOT NULL DEFAULT '',
    topic TEXT NOT NULL DEFAULT ''
  );
`;

// Every column a legacy `prayer_requests` table may lack. All carry defaults,
// so they can be added in place without touching existing rows. `id` is a
// primary key and cannot be added by ALTER — a table without it is rebuilt.
const FOCUS_COLUMN_ADDITIONS: [string, string][] = [
  ["user_id", "TEXT NOT NULL DEFAULT 'local'"],
  ["day_key", "TEXT NOT NULL DEFAULT ''"],
  ["text", "TEXT NOT NULL DEFAULT ''"],
  ["done", "INTEGER NOT NULL DEFAULT 0"],
  ["created_at", "TEXT NOT NULL DEFAULT ''"],
  ["name", "TEXT NOT NULL DEFAULT ''"],
  ["topic", "TEXT NOT NULL DEFAULT ''"],
];

async function focusColumns(db: SQLiteDatabase): Promise<Set<string>> {
  const cols = await db.getAllAsync<{ name: string }>(
    "PRAGMA table_info(prayer_requests)",
  );
  return new Set(cols.map((c) => c.name));
}

// expo-sqlite's `execAsync` is a raw `sqlite3_exec` call and rejects with a
// native NullPointerException on some Android builds. Prepared statements
// (`runAsync`) are the path every other write in the app uses, so all DDL in
// this module goes through them too.
function execSql(db: SQLiteDatabase, sql: string): Promise<unknown> {
  return db.runAsync(sql);
}

// Last resort: replace the table with the canonical shape. Old installs may
// carry a `prayer_requests` table with required columns we don't know about;
// rebuilding guarantees the INSERT below can succeed. Data is carried over
// only when the legacy columns line up.
async function rebuildPrayerFocusTable(db: SQLiteDatabase): Promise<void> {
  const present = await focusColumns(db);
  if (present.size === 0) {
    // No table at all — nothing to carry over or drop.
    await execSql(db, PRAYER_FOCUS_TABLE);
    return;
  }
  const keyCol = present.has("day_key")
    ? "day_key"
    : present.has("date_key")
      ? "date_key"
      : null;
  const textCol = present.has("text")
    ? "text"
    : present.has("body")
      ? "body"
      : null;
  const copyable = keyCol && textCol;
  // Legacy rows can hold NULLs the new NOT NULL columns would reject — the
  // copy must sanitise every value or the rebuild aborts and saving stays
  // broken forever. The source is the renamed table: after the RENAME below,
  // `prayer_requests` is the fresh empty one.
  const legacySelect = copyable
    ? `SELECT ${keyCol}, COALESCE(${textCol}, ''), 0, datetime('now'),
        ${present.has("name") ? "COALESCE(name, '')" : "''"},
        ${present.has("topic") ? "COALESCE(topic, '')" : "''"}
       FROM prayer_requests_legacy
       WHERE ${keyCol} IS NOT NULL AND ${keyCol} <> ''`
    : null;

  // A half-finished earlier repair can leave the connection inside a
  // transaction; clear it so BEGIN below can't fail on that.
  await execSql(db, "ROLLBACK;").catch(() => {});
  await execSql(db, "BEGIN;");
  try {
    await execSql(db, "DROP TABLE IF EXISTS prayer_requests_legacy;");
    await execSql(db, "ALTER TABLE prayer_requests RENAME TO prayer_requests_legacy;");
    await execSql(db, PRAYER_FOCUS_TABLE);
    if (legacySelect) {
      // Carrying the old rows over is best-effort: unusable legacy data must
      // never stop the table from being replaced.
      await execSql(db, "SAVEPOINT focus_copy;");
      try {
        await execSql(
          db,
          `INSERT INTO prayer_requests (day_key, text, done, created_at, name, topic)
           ${legacySelect};`,
        );
        await execSql(db, "RELEASE focus_copy;");
      } catch {
        await execSql(db, "ROLLBACK TO focus_copy;").catch(() => {});
        await execSql(db, "RELEASE focus_copy;").catch(() => {});
      }
    }
    await execSql(db, "DROP TABLE IF EXISTS prayer_requests_legacy;");
    await execSql(
      db,
      "CREATE INDEX IF NOT EXISTS idx_prayer_requests_day ON prayer_requests(user_id, day_key);",
    );
    await execSql(db, "COMMIT;");
  } catch (err) {
    await execSql(db, "ROLLBACK;").catch(() => {});
    throw err;
  }
}

// One schema check per DB handle; a failed attempt is forgotten so the next
// call retries instead of caching the failure.
const focusSchemaReady = new WeakMap<SQLiteDatabase, Promise<void>>();
const focusLocks = new WeakMap<SQLiteDatabase, Promise<unknown>>();

function serializeFocus<R>(db: SQLiteDatabase, task: () => Promise<R>): Promise<R> {
  const previous = focusLocks.get(db) ?? Promise.resolve();
  const next = previous.then(task, task);
  focusLocks.set(db, next.then(() => undefined, () => undefined));
  return next;
}

function ensurePrayerFocusSchema(db: SQLiteDatabase): Promise<void> {
  const cached = focusSchemaReady.get(db);
  if (cached) return cached;
  const ready = (async () => {
    await execSql(db, PRAYER_FOCUS_TABLE);
    const present = await focusColumns(db);
    for (const [col, decl] of FOCUS_COLUMN_ADDITIONS) {
      if (!present.has(col)) {
        await execSql(db, `ALTER TABLE prayer_requests ADD COLUMN ${col} ${decl}`);
      }
    }
    // A table without the primary key can't take inserts; start it over.
    if (!present.has("id")) await rebuildPrayerFocusTable(db);
  })();
  const guarded = ready.catch((err) => {
    focusSchemaReady.delete(db);
    throw err;
  });
  focusSchemaReady.set(db, guarded);
  return guarded;
}

function errorText(err: unknown): string {
  if (err instanceof Error) return err.message;
  return String(err);
}

const PRAYER_FOCUS_WEB_KEY = "relate:prayer-focus:v1";

function normalizePrayerFocusMap(value: unknown): PrayerFocusMap {
  const map: PrayerFocusMap = {};
  if (!value || typeof value !== "object" || Array.isArray(value)) return map;
  for (const [key, rawList] of Object.entries(value)) {
    if (!key || !Array.isArray(rawList)) continue;
    const list: PrayerRequestEntry[] = [];
    for (const raw of rawList) {
      if (!raw || typeof raw !== "object") continue;
      const item = raw as Record<string, unknown>;
      if (typeof item.text !== "string") continue;
      list.push({
        id: typeof item.id === "number" ? item.id : undefined,
        text: item.text,
        done: item.done === true,
        createdAt:
          typeof item.createdAt === "string" ? item.createdAt : new Date().toISOString(),
        name: typeof item.name === "string" && item.name ? item.name : undefined,
        topic: typeof item.topic === "string" && item.topic ? item.topic : undefined,
      });
    }
    if (list.length) map[key] = list;
  }
  return map;
}

async function readWebPrayerFocus(): Promise<PrayerFocusMap> {
  try {
    const raw = await appStorage.getItemAsync(PRAYER_FOCUS_WEB_KEY);
    return raw ? normalizePrayerFocusMap(JSON.parse(raw)) : {};
  } catch (err) {
    console.warn("[prayer-focus] web read failed", errorText(err));
    return {};
  }
}

async function writeWebPrayerFocus(all: PrayerFocusMap): Promise<PrayerFocusWrite> {
  try {
    await appStorage.setItemAsync(PRAYER_FOCUS_WEB_KEY, JSON.stringify(all));
    return { ok: true, all: await readWebPrayerFocus() };
  } catch (err) {
    return { ok: false, all: await readWebPrayerFocus(), reason: errorText(err) };
  }
}

function nextWebPrayerFocusId(all: PrayerFocusMap): number {
  let max = 0;
  for (const list of Object.values(all)) {
    for (const entry of list) {
      if (typeof entry.id === "number" && entry.id > max) max = entry.id;
    }
  }
  return max + 1;
}

async function savePrayerFocusWeb(
  key: string,
  text: string,
  name: string,
  topic: string,
): Promise<PrayerFocusWrite> {
  const all = await readWebPrayerFocus();
  const list = all[key] ? [...all[key]] : [];
  list.push({
    id: nextWebPrayerFocusId(all),
    text,
    done: false,
    createdAt: new Date().toISOString(),
    name: name || undefined,
    topic: topic || undefined,
  });
  all[key] = list;
  return writeWebPrayerFocus(all);
}

async function updatePrayerFocusWeb(
  id: number,
  text: string,
  name: string,
  topic: string,
  fallbackKey: string,
): Promise<PrayerFocusWrite> {
  const all = await readWebPrayerFocus();
  for (const [key, list] of Object.entries(all)) {
    const index = list.findIndex((entry) => entry.id === id);
    if (index < 0) continue;
    list[index] = {
      ...list[index],
      text,
      name: name || undefined,
      topic: topic || undefined,
    };
    all[key] = list;
    return writeWebPrayerFocus(all);
  }
  if (fallbackKey) return savePrayerFocusWeb(fallbackKey, text, name, topic);
  return { ok: false, all, reason: "The saved focus no longer exists." };
}

async function removePrayerFocusWeb(id: number): Promise<PrayerFocusWrite> {
  const all = await readWebPrayerFocus();
  let found = false;
  for (const [key, list] of Object.entries(all)) {
    const next = list.filter((entry) => entry.id !== id);
    if (next.length === list.length) continue;
    found = true;
    if (next.length) all[key] = next;
    else delete all[key];
  }
  if (!found) return { ok: true, all };
  return writeWebPrayerFocus(all);
}

async function insertPrayerFocus(
  db: SQLiteDatabase,
  key: string,
  text: string,
  name: string,
  topic: string,
): Promise<void> {
  // Every column is written explicitly: legacy tables may have NOT NULL
  // columns without defaults, which an omitted column would trip over.
  await db.runAsync(
    `INSERT INTO prayer_requests (user_id, day_key, text, name, topic, done, created_at)
     VALUES ('local', ?, ?, ?, ?, 0, datetime('now'))`,
    [key, text, name, topic],
  );
}

async function readPrayerFocus(db: SQLiteDatabase): Promise<PrayerFocusMap> {
  try {
    await ensurePrayerFocusSchema(db);
    // SELECT * tolerates any older column set; missing fields fall back below.
    const rows = await db.getAllAsync<Record<string, unknown>>(
      "SELECT * FROM prayer_requests ORDER BY id ASC",
    );
    const result: PrayerFocusMap = {};
    for (const r of rows) {
      const key = typeof r.day_key === "string" ? r.day_key : "";
      if (!key) continue;
      (result[key] ??= []).push({
        id: typeof r.id === "number" ? r.id : undefined,
        text: typeof r.text === "string" ? r.text : "",
        done: r.done === 1 || r.done === true,
        createdAt: typeof r.created_at === "string" ? r.created_at : "",
        name: typeof r.name === "string" && r.name ? r.name : undefined,
        topic: typeof r.topic === "string" && r.topic ? r.topic : undefined,
      });
    }
    return result;
  } catch (err) {
    console.warn("[prayer-focus] read failed", errorText(err));
    return {};
  }
}

/** All saved focuses, grouped by `${dateKey}_${prayerKey}`. Never throws. */
export function loadPrayerFocus(db: SQLiteDatabase): Promise<PrayerFocusMap> {
  if (IS_WEB) return readWebPrayerFocus();
  return serializeFocus(db, () => readPrayerFocus(db));
}

export function savePrayerFocus(
  db: SQLiteDatabase,
  key: string,
  text: string,
  name = "",
  topic = "",
): Promise<PrayerFocusWrite> {
  if (IS_WEB) return savePrayerFocusWeb(key, text, name, topic);
  return serializeFocus(db, () => savePrayerFocusUnlocked(db, key, text, name, topic));
}

async function savePrayerFocusUnlocked(
  db: SQLiteDatabase,
  key: string,
  text: string,
  name = "",
  topic = "",
): Promise<PrayerFocusWrite> {
  try {
    await ensurePrayerFocusSchema(db);
    await insertPrayerFocus(db, key, text, name, topic);
    return { ok: true, all: await readPrayerFocus(db) };
  } catch (first) {
    // An unknown legacy constraint can still reject the insert — rebuild the
    // table and retry once before giving up.
    try {
      await rebuildPrayerFocusTable(db);
      focusSchemaReady.delete(db);
      await insertPrayerFocus(db, key, text, name, topic);
      return { ok: true, all: await readPrayerFocus(db) };
    } catch (second) {
      // Last resort: start the table over from scratch. Losing old focuses
      // beats a screen where saving never works.
      try {
        await execSql(db, "DROP TABLE IF EXISTS prayer_requests;");
        await execSql(db, PRAYER_FOCUS_TABLE);
        focusSchemaReady.delete(db);
        await insertPrayerFocus(db, key, text, name, topic);
        return { ok: true, all: await readPrayerFocus(db) };
      } catch (third) {
        console.warn(
          "[prayer-focus] save failed",
          errorText(first),
          errorText(second),
          errorText(third),
        );
        return {
          ok: false,
          all: await readPrayerFocus(db),
          // The first error is the root cause; later ones are repair fallout.
          reason: `${errorText(first)} (retry: ${errorText(third)})`,
        };
      }
    }
  }
}

export function updatePrayerFocus(
  db: SQLiteDatabase,
  id: number,
  text: string,
  name = "",
  topic = "",
  fallbackKey = "",
): Promise<PrayerFocusWrite> {
  if (IS_WEB) return updatePrayerFocusWeb(id, text, name, topic, fallbackKey);
  return serializeFocus(db, () =>
    updatePrayerFocusUnlocked(db, id, text, name, topic, fallbackKey),
  );
}

async function updatePrayerFocusUnlocked(
  db: SQLiteDatabase,
  id: number,
  text: string,
  name = "",
  topic = "",
  fallbackKey = "",
): Promise<PrayerFocusWrite> {
  const applyEdit = async (): Promise<number> => {
    const res = await db.runAsync(
      `UPDATE prayer_requests SET text = ?, name = ?, topic = ? WHERE id = ?`,
      [text, name, topic, id],
    );
    return res.changes;
  };
  try {
    await ensurePrayerFocusSchema(db);
    if ((await applyEdit()) > 0) return { ok: true, all: await readPrayerFocus(db) };
  } catch (first) {
    // Same self-healing as a first save: repair the table, then retry.
    try {
      await rebuildPrayerFocusTable(db);
      focusSchemaReady.delete(db);
      if ((await applyEdit()) > 0) {
        return { ok: true, all: await readPrayerFocus(db) };
      }
    } catch (second) {
      console.warn(
        "[prayer-focus] update failed",
        errorText(first),
        errorText(second),
      );
      return {
        ok: false,
        all: await readPrayerFocus(db),
        reason: errorText(second),
      };
    }
  }
  // The edited row is gone (e.g. a rebuild renumbered ids) — keep the edit as
  // a fresh entry rather than failing the save.
  if (fallbackKey) return savePrayerFocusUnlocked(db, fallbackKey, text, name, topic);
  return {
    ok: false,
    all: await readPrayerFocus(db),
    reason: "The saved focus no longer exists.",
  };
}

export function removePrayerFocus(
  db: SQLiteDatabase,
  id: number,
): Promise<PrayerFocusWrite> {
  if (IS_WEB) return removePrayerFocusWeb(id);
  return serializeFocus(db, () => removePrayerFocusUnlocked(db, id));
}

async function removePrayerFocusUnlocked(
  db: SQLiteDatabase,
  id: number,
): Promise<PrayerFocusWrite> {
  try {
    await ensurePrayerFocusSchema(db);
    await db.runAsync(`DELETE FROM prayer_requests WHERE id = ?`, [id]);
    return { ok: true, all: await readPrayerFocus(db) };
  } catch (err) {
    console.warn("[prayer-focus] remove failed", errorText(err));
    return { ok: false, all: await readPrayerFocus(db), reason: errorText(err) };
  }
}