import { type SQLiteDatabase } from "expo-sqlite";

export type ReaderFontKey = "eczar" | "dmsans" | "fraunces" | "lora" | "andika";

export type ReaderThemeKey =
  | "system"
  | "light"
  | "dark"
  | "sepia"
  | "paper";

export type ReaderLayoutKey = "verses" | "paragraph" | "poetry" | "focus";

export type FontWeightOption = {
  key: string;
  label: string;
  family: string;
};

