export const READER_LAYOUTS: {
  key: ReaderLayoutKey;
  label: string;
  description: string;
}[] = [
  { key: "verses", label: "Verse list", description: "One verse per line" },
  { key: "paragraph", label: "Paragraph", description: "Continuous prose" },
  { key: "poetry", label: "Poetry", description: "Indented poetic lines" },
  { key: "focus", label: "Focus", description: "One verse at a time" },
];

export type ReaderSettings = {
  fontFamily: ReaderFontKey;
  fontSize: number;
  fontWeight: string;
  theme: ReaderThemeKey;
  /** Reading layout: verse list, paragraph, poetry, or one-verse focus mode. */
  layout: ReaderLayoutKey;
  /** Last opened book name — the reader reopens here, like YouVersion. */
  lastBook?: string | null;
  /** Last opened chapter number. */
  lastChapter?: number;
};

export const DEFAULT_SETTINGS: ReaderSettings = {
  fontFamily: "eczar",
  fontSize: 18,
  fontWeight: "Eczar_500Medium",
  theme: "system",
  layout: "verses",
  lastBook: null,
  lastChapter: 1,
};

const THEME_KEYS: ReaderThemeKey[] = ["system", "light", "dark", "sepia", "paper"];

const LAYOUT_KEYS: ReaderLayoutKey[] = ["verses", "paragraph", "poetry", "focus"];

export async function getReaderSettings(
  db: SQLiteDatabase,
): Promise<ReaderSettings> {
  const rows = await db.getAllAsync<{ key: string; value: string }>(
    `SELECT key, value FROM settings WHERE key IN
       ('reader_font_family', 'reader_font_size', 'reader_font_weight', 'reader_theme',
        'reader_layout', 'reader_last_book', 'reader_last_chapter')`,
  );
  const map = new Map(rows.map((r) => [r.key, r.value]));

  const storedKey = map.get("reader_font_family") as ReaderFontKey;
  const fontKey: ReaderFontKey = READER_FONTS.some((f) => f.key === storedKey)
    ? storedKey
    : DEFAULT_SETTINGS.fontFamily;

  const font = READER_FONTS.find((f) => f.key === fontKey) ?? READER_FONTS[0];
  const storedWeight = map.get("reader_font_weight") || "";
  const fontWeight = font.weights.some((w) => w.family === storedWeight)
    ? storedWeight
    : font.defaultWeight;

  const storedTheme = map.get("reader_theme") as ReaderThemeKey;
  const theme = THEME_KEYS.includes(storedTheme)
    ? storedTheme
    : DEFAULT_SETTINGS.theme;

  const storedLayout = map.get("reader_layout") as ReaderLayoutKey;
  const layout: ReaderLayoutKey = LAYOUT_KEYS.includes(storedLayout)
    ? storedLayout
    : DEFAULT_SETTINGS.layout;

  const fontSize = parseInt(map.get("reader_font_size") || "", 10);
  const lastChapter = parseInt(map.get("reader_last_chapter") || "", 10);
  return {
    fontFamily: fontKey,
    fontWeight,
    theme,
    layout,
    fontSize: Number.isFinite(fontSize)
      ? Math.min(28, Math.max(14, fontSize))
      : DEFAULT_SETTINGS.fontSize,
    lastBook: map.get("reader_last_book") || null,
    lastChapter: Number.isFinite(lastChapter) && lastChapter > 0 ? lastChapter : 1,
  };
}

export async function saveReaderSettings(
  db: SQLiteDatabase,
  settings: ReaderSettings,
): Promise<void> {
  await db.runAsync(
    `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_font_family', ?)`,
    [settings.fontFamily],
  );
  await db.runAsync(
    `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_font_size', ?)`,
    [String(settings.fontSize)],
  );
  await db.runAsync(
    `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_font_weight', ?)`,
    [settings.fontWeight],
  );
  await db.runAsync(
    `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_theme', ?)`,
    [settings.theme],
  );
  await db.runAsync(
    `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_layout', ?)`,
    [settings.layout],
  );
  if (settings.lastBook != null) {
    await db.runAsync(
      `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_last_book', ?)`,
      [settings.lastBook],
    );
  }
  if (settings.lastChapter != null) {
    await db.runAsync(
      `INSERT OR REPLACE INTO settings (key, value) VALUES ('reader_last_chapter', ?)`,
      [String(settings.lastChapter)],
    );
  }
}