import { Ionicons } from "@expo/vector-icons";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  InteractionManager,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { router } from "expo-router";
import { SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { API_BASE } from "@/services/config";
import { getSession, getRequestHeaders } from "@/services/auth";

export const unstable_settings = {
  headerShown: false,
};

type AccountResult = {
  id: string;
  account_type: "personal" | "relate";
  display_name: string;
  club_slug: string;
  club_code: string;
  account_number: string;
  owner_name: string | null;
  owner_email: string | null;
};

type MasterAccount = {
  id: string;
  display_name: string | null;
  owner_email: string;
  is_master: boolean | null;
};

export default function MasterAccountScreen() {
  const insets = useSafeAreaInsets();
  const [search, setSearch] = useState("");
  const [accounts, setAccounts] = useState<AccountResult[]>([]);
  const [amount, setAmount] = useState("");
  const [description, setDescription] = useState("");
  const [recipient, setRecipient] = useState<AccountResult | null>(null);
  const [checking, setChecking] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [masterBalance, setMasterBalance] = useState<number | null>(null);
  const [masterAccount, setMasterAccount] = useState<MasterAccount | null>(null);
  const [paymentModalVisible, setPaymentModalVisible] = useState(false);

  const authenticatedHeaders = async (json = false) =>
    getRequestHeaders(json ? { "Content-Type": "application/json" } : undefined);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user || session.user.role !== "admin") {
        router.replace("/(tabs)");
        return;
      }
      setLoading(false);
    })();
  }, []);

  const loadAccounts = async () => {
    setChecking(true);
    setError(null);
    try {
      const response = await fetch(
        `${API_BASE}/api/smart-saver/accounts`,
        { headers: await authenticatedHeaders() },
      );
      const body = await response.json();
      if (!response.ok) {
        const details =
          typeof body.details?.message === "string"
            ? `: ${body.details.message}`
            : typeof body.details === "string"
              ? `: ${body.details}`
              : "";
        throw new Error(`${body.error || "Account lookup failed"}${details}`);
      }
      setAccounts(Array.isArray(body.data) ? body.data : []);
      setMasterBalance(
        typeof body.masterBalance === "number" ? body.masterBalance : null,
      );
      setMasterAccount(
        body.masterAccount && typeof body.masterAccount.id === "string"
          ? body.masterAccount
          : null,
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "Account not found");
    } finally {
      setChecking(false);
    }
  };

  useEffect(() => {
    if (loading) return;
    const task = InteractionManager.runAfterInteractions(() => {
      void loadAccounts();
    });
    return () => task.cancel();
  }, [loading]);

  const filteredAccounts = accounts.filter((account) => {
    if (account.account_type !== "relate") return false;
    const query = search.trim().toLowerCase();
    if (!query) return true;
    return [
      account.display_name,
      account.club_slug,
      account.club_code,
      account.account_number,
      account.account_type,
      account.owner_name,
      account.owner_email,
    ].some((value) => value?.toLowerCase().includes(query));
  });

  const transfer = async () => {
    if (!recipient) return;
    const numericAmount = Number(amount);
    if (!Number.isFinite(numericAmount) || numericAmount <= 0) {
      setError("Enter a valid amount.");
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      const response = await fetch(`${API_BASE}/api/smart-saver/settlements`, {
        method: "POST",
        headers: await authenticatedHeaders(true),
        body: JSON.stringify({
          accountId: recipient.id,
          amount: numericAmount,
          description: description.trim() || "Relate World payment",
        }),
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || "Transfer failed");
      Alert.alert(
        "Transfer complete",
        `R${numericAmount.toFixed(2)} credited: R${(numericAmount * 0.6).toFixed(2)} Vault and R${(numericAmount * 0.4).toFixed(2)} Wallet.`,
        [{ text: "OK" }],
      );
      setAmount("");
      setDescription("");
      await loadAccounts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Transfer failed");
    } finally {
      setSubmitting(false);
    }
  };

  const openPaymentModal = (account: AccountResult) => {
    setRecipient(account);
    setAmount("");
    setDescription("");
    setError(null);
    setPaymentModalVisible(true);
  };

  const closePaymentModal = () => {
    if (submitting) return;
    setPaymentModalVisible(false);
    setRecipient(null);
  };

  if (loading) {
    return (
      <SafeAreaView style={styles.center}>
        <ActivityIndicator color={colors.gold} />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView
        style={styles.flex}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <View style={styles.header}>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <Ionicons name="arrow-back" size={24} color={colors.ink} />
          </Pressable>
          <View>
            <Text style={styles.title}>Master Account</Text>
            <Text style={styles.subtitle}>Relate World settlement</Text>
          </View>
        </View>

        <ScrollView contentContainerStyle={styles.content}>
          <View style={styles.balanceCard}>
            <Text style={styles.balanceLabel}>Available master balance</Text>
            <Text style={styles.balanceAmount}>
              {masterBalance === null
                ? "Unavailable"
                : `R${masterBalance.toFixed(2)}`}
            </Text>
            <Text style={styles.balanceNote}>
              {masterAccount
                ? `Linked to ${masterAccount.owner_email}`
                : "No Smart Saver account found for info@relateworld.org"}
            </Text>
            {masterAccount?.is_master === false ? (
              <Text style={styles.balanceWarning}>
                Smart Saver still settles from its flagged master account — flag
                this account there to move the funds source.
              </Text>
            ) : null}
          </View>

          <View style={styles.card}>
            <Text style={styles.label}>Find a Relate account</Text>
            <View style={styles.searchRow}>
              <TextInput
                value={search}
                onChangeText={setSearch}
                placeholder="Search name, club code or account number"
                placeholderTextColor={colors.muted}
                style={styles.input}
                autoCapitalize="characters"
              />
            </View>
          </View>

          <View style={styles.accountList}>
            {checking ? <ActivityIndicator color={colors.gold} /> : null}
            {!checking && filteredAccounts.length === 0 ? (
              <Text style={styles.empty}>No matching accounts.</Text>
            ) : null}
            {filteredAccounts.map((account) => (
              <Pressable
                key={account.id}
                style={[
                  styles.accountRow,
                  recipient?.id === account.id ? styles.accountRowSelected : null,
                ]}
                onPress={() => openPaymentModal(account)}
              >
                <View style={styles.recipientText}>
                  <Text style={styles.recipientName}>{account.display_name}</Text>
                  {account.owner_name ? (
                    <Text style={styles.ownerName}>{account.owner_name}</Text>
                  ) : null}
                  {account.owner_email ? (
                    <Text style={styles.ownerEmail}>{account.owner_email}</Text>
                  ) : null}
                  <Text style={styles.recipientCode}>{account.club_code}</Text>
                  <Text style={styles.recipientCode}>{account.account_number}</Text>
                  <Text style={styles.accountType}>
                    {account.account_type === "relate" ? "Relate account" : "Personal account"}
                  </Text>
                </View>
                <Ionicons
                  name={recipient?.id === account.id ? "checkmark-circle" : "chevron-forward"}
                  size={20}
                  color={recipient?.id === account.id ? colors.success : colors.muted}
                />
              </Pressable>
            ))}
          </View>

          {error ? <Text style={styles.error}>{error}</Text> : null}
        </ScrollView>
      </KeyboardAvoidingView>
      <Modal
        animationType="slide"
        transparent
        visible={paymentModalVisible && recipient !== null}
        onRequestClose={closePaymentModal}
      >
        <View style={styles.modalBackdrop}>
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            style={styles.flex}
          >
            <ScrollView
              contentContainerStyle={styles.modalScroll}
              keyboardShouldPersistTaps="handled"
              keyboardDismissMode="none"
              showsVerticalScrollIndicator={false}
            >
              <View
                style={[
                  styles.modalSheet,
                  { paddingBottom: Math.max(insets.bottom, 20) + 16 },
                ]}
              >
                <View style={styles.modalHeader}>
                  <View style={styles.recipientText}>
                    <Text style={styles.modalTitle}>Make payment</Text>
                    <Text style={styles.recipientName}>{recipient?.display_name}</Text>
                    {recipient?.owner_name ? (
                      <Text style={styles.ownerName}>{recipient.owner_name}</Text>
                    ) : null}
                    {recipient?.owner_email ? (
                      <Text style={styles.ownerEmail}>{recipient.owner_email}</Text>
                    ) : null}
                    <Text style={styles.recipientCode}>{recipient?.account_number}</Text>
                  </View>
                  <Pressable onPress={closePaymentModal} hitSlop={12}>
                    <Ionicons name="close-circle" size={28} color={colors.muted} />
                  </Pressable>
                </View>
                <Text style={styles.label}>Payment amount</Text>
                <TextInput
                  value={amount}
                  onChangeText={setAmount}
                  placeholder="0.00"
                  keyboardType="decimal-pad"
                  style={styles.fullInput}
                />
                <Text style={styles.label}>Description</Text>
                <TextInput
                  value={description}
                  onChangeText={setDescription}
                  placeholder="Task or service payment"
                  style={styles.fullInput}
                />
                <View style={styles.split}>
                  <Text style={styles.splitText}>Vault 60%</Text>
                  <Text style={styles.splitText}>Wallet 40%</Text>
                </View>
                {error ? <Text style={styles.error}>{error}</Text> : null}
                <Pressable style={styles.submit} onPress={transfer} disabled={submitting}>
                  <Text style={styles.submitText}>
                    {submitting ? "Transferring..." : "Transfer funds"}
                  </Text>
                </Pressable>
              </View>
            </ScrollView>
          </KeyboardAvoidingView>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  center: { flex: 1, alignItems: "center", justifyContent: "center" },
  header: { flexDirection: "row", alignItems: "center", gap: 14, padding: 20 },
  title: { fontFamily: fonts.serif, fontSize: 20, color: colors.ink },
  subtitle: { fontFamily: fonts.sans, fontSize: 12, color: colors.muted },
  content: { paddingHorizontal: 20, paddingBottom: 40 },
  card: { borderWidth: 1, borderColor: colors.border, borderRadius: 16, padding: 16, backgroundColor: colors.card },
  balanceCard: { borderRadius: 16, padding: 16, marginBottom: 14, backgroundColor: colors.gold },
  balanceLabel: { fontFamily: fonts.sansSemiBold, fontSize: 12, color: "#fff" },
  balanceAmount: { fontFamily: fonts.serif, fontSize: 30, color: "#fff", marginVertical: 4 },
  balanceNote: { fontFamily: fonts.sans, fontSize: 11, color: "#fff" },
  balanceWarning: { fontFamily: fonts.sansSemiBold, fontSize: 11, color: "#fff", marginTop: 8 },
  label: { fontFamily: fonts.sansSemiBold, fontSize: 12, color: colors.ink, marginBottom: 8 },
  row: { flexDirection: "row", gap: 10 },
  searchRow: { flexDirection: "row" },
  input: { flex: 1, borderWidth: 1, borderColor: colors.border, borderRadius: 12, paddingHorizontal: 12, height: 46, color: colors.ink },
  accountList: { gap: 10, marginTop: 14 },
  accountRow: { flexDirection: "row", alignItems: "center", gap: 10, borderWidth: 1, borderColor: colors.border, borderRadius: 14, padding: 14, backgroundColor: colors.card },
  accountRowSelected: { borderColor: colors.gold, backgroundColor: `${colors.gold}12` },
  empty: { fontFamily: fonts.sans, textAlign: "center", color: colors.muted, paddingVertical: 20 },
  ownerName: { fontFamily: fonts.sansSemiBold, fontSize: 13, color: colors.ink },
  ownerEmail: { fontFamily: fonts.sans, fontSize: 12, color: colors.muted },
  accountType: { fontFamily: fonts.sans, fontSize: 11, color: colors.muted },
  fullInput: { borderWidth: 1, borderColor: colors.border, borderRadius: 12, paddingHorizontal: 12, height: 46, color: colors.ink, marginBottom: 16 },
  lookup: { height: 46, minWidth: 58, alignItems: "center", justifyContent: "center", borderRadius: 12, backgroundColor: colors.gold },
  lookupText: { color: "#fff", fontFamily: fonts.sansSemiBold },
  recipient: { flexDirection: "row", alignItems: "center", gap: 10, marginVertical: 14, padding: 14, borderRadius: 14, backgroundColor: `${colors.success}18` },
  recipientText: { flex: 1 },
  recipientName: { fontFamily: fonts.sansSemiBold, color: colors.ink },
  recipientCode: { fontFamily: fonts.sans, fontSize: 11, color: colors.muted, marginTop: 2 },
  error: { fontFamily: fonts.sans, color: colors.error, marginVertical: 12 },
  split: { flexDirection: "row", justifyContent: "space-between", padding: 12, borderRadius: 12, backgroundColor: colors.bg },
  splitText: { fontFamily: fonts.sansSemiBold, fontSize: 12, color: colors.ink },
  submit: { marginTop: 16, height: 48, borderRadius: 14, alignItems: "center", justifyContent: "center", backgroundColor: colors.gold },
  submitText: { fontFamily: fonts.sansSemiBold, color: "#fff" },
  modalBackdrop: { flex: 1, backgroundColor: "rgba(0,0,0,0.45)" },
  modalScroll: { flexGrow: 1, justifyContent: "flex-end" },
  modalSheet: { borderTopLeftRadius: 24, borderTopRightRadius: 24, padding: 20, backgroundColor: colors.card },
  modalHeader: { flexDirection: "row", alignItems: "flex-start", gap: 12, marginBottom: 18 },
  modalTitle: { fontFamily: fonts.serif, fontSize: 20, color: colors.ink, marginBottom: 8 },
});
