import { useEffect, useState } from "react";
import { API_BASE } from "@/services/config";
import { cachedFetch } from "@/services/cache";

/**
 * Program calendar — GET /api/clubs/<slug>/calendar.
 *
 * The backend owns every club's year plan (the March → November dates shown
 * under Programs & Activities on web and mobile); nothing about the calendar
 * is bundled in the app. A club with no calendar comes back with an empty
 * entry list, which screens read as "no section to show".
 *
 * One request per club per session, cached at module level.
 */

export type ProgramCalendarEntry = {
  id: string;
  /** ISO date (YYYY-MM-DD) the session runs on. */
  date: string;
  endDate?: string;
  title: string;
  description?: string;
  term?: string;
  time?: string;
  location?: string;
  setting?: string;
};

export type ProgramCalendar = {
  clubSlug: string;
  year: number;
  entries: ProgramCalendarEntry[];
};

let requestCache = new Map<string, Promise<ProgramCalendar>>();

export function fetchProgramCalendar(clubSlug: string): Promise<ProgramCalendar> {
  const cached = requestCache.get(clubSlug);
  if (cached) return cached;

  const promise = fetch(
    `${API_BASE}/api/clubs/${encodeURIComponent(clubSlug)}/calendar`,
    { headers: { Accept: "application/json" } },
  )
    .then(async (res) => {
      if (!res.ok) throw new Error(`calendar api ${res.status}`);
      const raw = (await res.json()) as Partial<ProgramCalendar>;
      if (!raw || !Array.isArray(raw.entries)) {
        throw new Error("unexpected calendar payload");
      }
      return {
        clubSlug:
          typeof raw.clubSlug === "string" && raw.clubSlug ? raw.clubSlug : clubSlug,
        year: typeof raw.year === "number" ? raw.year : 0,
        entries: raw.entries as ProgramCalendarEntry[],
      };
    })
    .catch((err: unknown) => {
      requestCache.delete(clubSlug);
      throw err;
    });

  requestCache.set(clubSlug, promise);
  return promise;
}

export type ProgramCalendarState = {
  calendar: ProgramCalendar | null;
  loading: boolean;
  error: string | null;
};

const LOADING: ProgramCalendarState = { calendar: null, loading: true, error: null };

/** The club's year calendar for a screen — empty list means no section. */
export function useProgramCalendar(clubSlug: string): ProgramCalendarState {
  const [state, setState] = useState<ProgramCalendarState>(() => LOADING);

  useEffect(() => {
    let cancelled = false;

    if (!clubSlug) {
      // Deferred a tick — setState straight in an effect body is disallowed.
      Promise.resolve().then(() => {
        if (!cancelled) setState({ calendar: null, loading: false, error: null });
      });
      return () => {
        cancelled = true;
      };
    }

    fetchProgramCalendar(clubSlug)
      .then((calendar) => {
        if (!cancelled) setState({ calendar, loading: false, error: null });
      })
      .catch(() => {
        if (!cancelled) setState({ calendar: null, loading: false, error: null });
      });

    return () => {
      cancelled = true;
    };
  }, [clubSlug]);

  return state;
}

/**
 * The Calendar screen's access layer — GET /api/program-calendar.
 *
 * Unlike the club-page reader above this covers the organization-wide year
 * ("relate") as well as any club, and it is the side admins write through.
 */

/** Scope reserved for the whole organization; never a real club slug. */
export const ORGANIZATION_SCOPE = "relate";

export type ScopedCalendar = {
  scope: string;
  /** Display name of the owner: "Relate" or the club's name. */
  name: string;
  year: number;
  entries: ProgramCalendarEntry[];
};

export function fetchScopedCalendar(scope: string, year?: number): Promise<ScopedCalendar> {
  const query = `scope=${encodeURIComponent(scope)}${year ? `&year=${year}` : ""}`;
  return cachedFetch<ScopedCalendar>(`/api/program-calendar?${query}`, { cacheTtl: 0 });
}

/**
 * Replace one scope+year wholesale — the admin API has no per-entry write, so
 * callers always send the full list they are showing.
 */
export async function saveCalendarEntries(
  scope: string,
  year: number,
  entries: ProgramCalendarEntry[],
): Promise<void> {
  await cachedFetch<{ success: boolean }>("/api/admin/program-calendar", {
    method: "PUT",
    body: JSON.stringify({ clubSlug: scope, year, entries }),
  });
  // Club pages read through the module-level cache above; drop it so an edit
  // made here is visible there without an app restart.
  invalidateProgramCalendar(scope);
}

export async function deleteCalendarYear(scope: string, year: number): Promise<void> {
  await cachedFetch<{ success: boolean }>(
    `/api/admin/program-calendar/${encodeURIComponent(scope)}?year=${year}`,
    { method: "DELETE" },
  );
  invalidateProgramCalendar(scope);
}

/** Drop the club-page reader's cached year plan (all clubs when omitted). */
export function invalidateProgramCalendar(clubSlug?: string): void {
  if (clubSlug) requestCache.delete(clubSlug);
  else requestCache = new Map();
}

/** Opens in the device's browser, which hands the file to the calendar app. */
export function calendarFeedIcsUrl(year: number, scope: string, entryId?: string): string {
  const entry = entryId ? `&entry=${encodeURIComponent(entryId)}` : "";
  return `${API_BASE}/api/calendar-feed?year=${year}&scope=${encodeURIComponent(scope)}&format=ics${entry}`;
}

/** Matches the backend's id shape so a new entry has a stable key before saving. */
export function newCalendarEntryId(): string {
  return `cal-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

/**
 * The whole-app agenda — GET /api/calendar-feed.
 *
 * The Calendar screen shows everything Relate runs, read from the records that
 * already own it: the published programme, community and club events, and (for
 * admins) board meetings and trainings. Nothing is copied into the calendar, so
 * a date changed in the Events manager or the board portal moves here too.
 *
 * Read-only by design. The only rows the calendar authors itself are programme
 * dates, written through saveCalendarEntries above.
 */

/** Every scope at once; the server resolves it, never a stored club slug. */
export const ALL_SCOPES = "all";

export type CalendarFeedSource = "program" | "event" | "board" | "training";

export type CalendarFeedItem = {
  id: string;
  source: CalendarFeedSource;
  /** Badge text: "Programme", the event's category, "Board meeting", "Training". */
  kind: string;
  title: string;
  date: string;
  endDate?: string;
  time?: string;
  location?: string;
  description?: string;
  scope: string;
  scopeName: string;
  term?: string;
  setting?: string;
  /** Id in the owning collection, for opening the record at its source. */
  refId: string;
};

export type CalendarFeed = {
  year: number;
  scope: string;
  scopeName: string;
  /** True when the server recognised an admin, so governance rows are present. */
  isAdmin: boolean;
  /** Years with a published plan, so an empty year can point at a full one. */
  programmeYears: number[];
  items: CalendarFeedItem[];
};

export function fetchCalendarFeed(year: number, scope: string): Promise<CalendarFeed> {
  return cachedFetch<CalendarFeed>(
    `/api/calendar-feed?year=${year}&scope=${encodeURIComponent(scope)}`,
    { cacheTtl: 0 },
  );
}

/** Governance rows live in the app only — the browser export can't fetch them. */
export function isExportable(item: CalendarFeedItem): boolean {
  return item.source === "program" || item.source === "event";
}
