const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
};

/** Where the gate chain currently stands — one state, advanced by one effect. */
type Gate =
  | { phase: "session-loading" }
  | { phase: "checking" }
  | { phase: "session-out" }
  | { phase: "error"; message: string }
  | { phase: "no-membership" }
  | { phase: "on-team"; reg: MyRegistration; membership: ClubMembership }
  | { phase: "picker"; clubSlug: string };

/**
 * The "Join a Team" flow, mirroring Join a Club: a member needs a Membership
 * ID before a team seat, existing players see their squad details, everyone
 * else picks one of their club's teams and drops into the registration form.
 */
export default function JoinTeamScreen() {
  const [gate, setGate] = useState<Gate>({ phase: "session-loading" });
  const [attempt, setAttempt] = useState(0);

  // Gate chain: session → membership (Membership ID) → my team registration.
  // Every setGate runs after an await (or in a handler), never synchronously
  // in the effect body.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const s = await getSession().catch(() => null);
        if (cancelled) return;
        if (!s) {
          setGate({ phase: "session-out" });
          return;
        }
        setGate({ phase: "checking" });

        const json = await clubJoinApi.me();
        if (cancelled) return;
        const m = json?.data ?? null;
        // Same rule as Join a Club: graduated members aren't active members,
        // and a missing Membership ID sends them to Join a Club first.
        const active = m && m.reference && m.status !== "graduated" ? m : null;
        if (!active) {
          setGate({ phase: "no-membership" });
          return;
        }

        const mine = await myRegistration();
        if (cancelled) return;
        if (mine) {
          setGate({ phase: "on-team", reg: mine, membership: active });
        } else {
          setGate({ phase: "picker", clubSlug: effectiveClubSlug(active) });
        }
      } catch (e: any) {
        if (!cancelled) {
          setGate({
            phase: "error",
            message: e?.message || "Could not reach the server.",
          });
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [attempt]);

  // Reset lives in the event handler, where setState is allowed.
  const retry = () => {
    setGate({ phase: "checking" });
    setAttempt((a) => a + 1);
  };

  switch (gate.phase) {
    case "session-loading":
      return <CenterScreen text="Loading…" accent={colors.gold} />;
    case "checking":
      return <CenterScreen text="Checking your membership…" accent={colors.gold} />;
    case "session-out":
      return <SignInGate />;
    case "error":
      return <ErrorGate message={gate.message} onRetry={retry} />;
    case "no-membership":
      return <NoMembershipGate />;
    case "on-team":
      return <AlreadyOnTeam reg={gate.reg} membership={gate.membership} />;
    case "picker":
      return <TeamPicker clubSlug={gate.clubSlug} />;
  }
}

/** Spinner screen shared by the loading gates. */
function CenterScreen({ text, accent }: { text: string; accent: string }) {
  return (
    <SafeAreaProvider>
      <SafeAreaView style={t.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <View style={t.center}>
          <ActivityIndicator size="small" color={accent} />
          <Text style={t.centerText}>{text}</Text>
        </View>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

/** Signed out — the membership check needs an account. */
function SignInGate() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  return (
    <SafeAreaProvider>
      <SafeAreaView style={t.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <ScrollView
          contentContainerStyle={[t.gateWrap, { paddingBottom: 40 + insets.bottom }]}
        >
          <View style={t.gateIcon}>
            <Ionicons name="lock-closed-outline" size={30} color={colors.gold} />
          </View>
          <Text style={t.gateTitle}>Join a team</Text>
          <Text style={t.gateBlurb}>
            Sign in first — your team seat and Membership ID stay with your
            account, so they show up on any device.
          </Text>
          <TouchableOpacity
            style={t.gateBtn}
            activeOpacity={0.88}
            onPress={() =>
              router.push({ pathname: "/login", params: { next: "/join-team" } })
            }
            accessibilityRole="button"
          >
            <GradientBox gradient="limeReversed" style={t.gateBtnInner}>
              <Text style={t.gateBtnText}>Sign in</Text>
              <Ionicons name="arrow-forward" size={16} color={colors.white} />
            </GradientBox>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => router.back()} accessibilityRole="button">
            <Text style={t.gateBack}>Go back</Text>
          </TouchableOpacity>
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

/** No Membership ID — teams are for club members, so point at Join a Club. */
