import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import { router } from "expo-router";
import { Modal, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { MyRegistration } from "@/services/sports";
import { SPORT_THEME } from "@/services/sports-catalog";

const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
};

/**
 * The "already on a team" status sheet shown instead of the registration form
 * when a Join / Register CTA is tapped by a member who already holds a squad
 * spot (one member, one team). Shared by the team page, player page and the
 * sports index's register CTAs.
 */
export default function AlreadyOnTeamModal({
  registration,
  currentTeamId,
  onClose,
}: {
  /** null hides the sheet; otherwise the registration to display. */
  registration: MyRegistration | null;
  /** The team the tapped CTA belongs to — same-team CTAs get a closer CTA. */
  currentTeamId?: string;
  onClose: () => void;
}) {
  const insets = useSafeAreaInsets();
  const reg = registration;
  const sameTeam = !!reg && !!currentTeamId && reg.teamId === currentTeamId;
  const theme = reg ? SPORT_THEME[reg.sport] ?? SPORT_THEME.Football : null;
  const statusValue = reg
    ? reg.status === "waitlist"
      ? `Waitlist #${reg.order}`
      : "Active in the squad"
    : "";
  const statusColor = reg?.status === "waitlist" ? "#b45309" : "#065f46";

  return (
    <Modal
      visible={!!registration}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <TouchableOpacity
        style={m.backdrop}
        activeOpacity={1}
        onPress={onClose}
        accessibilityLabel="Close"
      >
        <TouchableOpacity
          style={[m.card, { paddingBottom: 12 + insets.bottom }]}
          activeOpacity={1}
        >
          <View style={m.head}>
            <View
              style={[
                m.headIcon,
                { backgroundColor: theme ? `${theme.accent}18` : colors.bg },
              ]}
            >
              <MaterialCommunityIcons
                name={(theme?.icon ?? "football") as any}
                size={24}
                color={theme?.accent ?? colors.forest}
              />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={m.title}>
                {sameTeam
                  ? "You’re already on this team"
                  : `You’re already on ${reg?.teamName || "a Relate team"}`}
              </Text>
              <Text style={m.sub}>
                One member, one team — so there’s no second team to join.
              </Text>
            </View>
            <TouchableOpacity
              onPress={onClose}
              style={m.close}
              accessibilityRole="button"
              accessibilityLabel="Close"
            >
              <Ionicons name="close" size={18} color={colors.muted} />
            </TouchableOpacity>
          </View>

          <View style={m.rows}>
            <Row
              icon="people-outline"
              label="Team"
              value={
                reg?.clubName && reg?.teamName
                  ? `${reg.teamName} · ${reg.clubName}`
                  : reg?.teamName ?? ""
              }
            />
            <Row
              icon="medal-outline"
              label="Position"
              value={reg ? `${reg.position} (${reg.positionCode})` : ""}
            />
            <Row
              icon={
                reg?.status === "waitlist" ? "time-outline" : "checkmark-circle-outline"
              }
              label="Status"
              value={statusValue}
              valueColor={statusColor}
            />
            <Row
              icon="calendar-outline"
              label="Joined"
              value={fmtDate(reg?.createdAt) || "—"}
            />
          </View>

          <TouchableOpacity
            style={m.primary}
            activeOpacity={0.9}
            onPress={() => {
              if (sameTeam || !reg) {
                onClose();
                return;
              }
              onClose();
              router.push(`/sports/${reg.teamId}`);
            }}
            accessibilityRole="button"
          >
            <Text style={m.primaryText}>
              {sameTeam ? "View the squad" : "Open my team"}
            </Text>
            <Ionicons name="arrow-forward" size={15} color={colors.forestDark} />
          </TouchableOpacity>
          <TouchableOpacity onPress={onClose} style={m.notNow}>
            <Text style={m.notNowText}>Not now</Text>
          </TouchableOpacity>
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

function Row({
  icon,
  label,
  value,
  valueColor,
}: {
  icon: keyof typeof Ionicons.glyphMap;
  label: string;
  value: string;
  valueColor?: string;
}) {
  return (
    <View style={m.row}>
      <View style={m.rowIcon}>
        <Ionicons name={icon} size={14} color={colors.forest} />
      </View>
      <Text style={m.rowLabel}>{label}</Text>
      <Text
        style={[m.rowValue, valueColor ? { color: valueColor } : null]}
        numberOfLines={1}
      >
        {value}
      </Text>
    </View>
  );
}

