import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useCallback, useEffect, useState } from "react";
import {
  Alert,
  BackHandler,
  FlatList,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { GradientBox } from "@/constants/gradients";
import { SkeletonList, SkeletonPulse } from "@/components/Skeleton";
import EmptyState from "@/components/EmptyState";
import { API_BASE } from "@/services/config";
import { getSession, getRequestHeaders } from "@/services/auth";
import { router, useFocusEffect } from "expo-router";

type FamilyRecord = {
  _id: string;
  recordId: string;
  dateOfIntake: string;
  caseManager: string;
  headOfHousehold: string;
  contactNumber: string;
  emailAddress?: string;
  physicalAddress: string;
  urgencyLevel: "High" | "Medium" | "Low";
  status: "Active" | "Closed" | "Draft";
  summary: string;
  immediateNeeds: string[];
  longTermNeeds: string[];
  householdMembers: { name: string; age: number; relationship: string }[];
  actionLog: {
    date: string;
    actionTaken: string;
    byWhom: string;
    amountsUsed?: string;
    nextStep?: string;
  }[];
  caseClosedDate?: string;
  finalOutcome?: string;
  createdAt: string;
};

const URGENCY_COLORS: Record<string, { bg: string; border: string; text: string }> = {
  High: { bg: "#fef2f2", border: "#fecaca", text: "#b91c1c" },
  Medium: { bg: "#fef3c7", border: "#fde68a", text: "#92400e" },
  Low: { bg: "#d1fae5", border: "#a7f3d0", text: colors.emeraldDark },
};

const STATUS_COLORS: Record<string, { bg: string; text: string }> = {
  Active: { bg: "#d4eef5", text: "#0e7490" },
  Closed: { bg: "#e2e8f0", text: "#1d2a4d" },
  Draft: { bg: "#fef3c7", text: "#92400e" },
};

export default function RecordsScreen() {
  useEffect(() => {
    const onBackPress = () => { router.back(); return true; };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, []);

  const insets = useSafeAreaInsets();
  const [records, setRecords] = useState<FamilyRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<FamilyRecord | null>(null);
  const [authorized, setAuthorized] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  const fetchRecords = useCallback(async (silent = false) => {
    try {
      if (!silent) setError(null);
      const headers = await getRequestHeaders();
      const res = await fetch(`${API_BASE}/api/records`, { headers });
      const data = await res.json();

      if (!res.ok) {
        if (!silent) {
          setError(typeof data?.error === "string" ? data.error : `Request failed (${res.status})`);
          setRecords([]);
        }
        return;
      }

      const next = Array.isArray(data) ? data : [];
      setRecords(next);
      setSelected((cur) =>
        cur && cur._id
          ? next.find((r: FamilyRecord) => r._id === cur._id) ?? cur
          : cur,
      );
    } catch {
      if (!silent) {
        setError("Network error — could not reach the server.");
        setRecords([]);
      }
    }
  }, []);

  const load = useCallback(async () => {
    const session = await getSession();
    if (!session?.user || session.user.role !== "admin") {
      setAuthorized(false);
      setLoading(false);
      return;
    }
    setAuthorized(true);
    await fetchRecords();
    setLoading(false);
  }, [fetchRecords]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    await fetchRecords(true);
    setRefreshing(false);
  }, [fetchRecords]);

  const handleDelete = (record: FamilyRecord) => {
    Alert.alert(
      "Delete Record",
      `Delete ${record.recordId} (${record.headOfHousehold})?`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: async () => {
            try {
              const headers = await getRequestHeaders({ "Content-Type": "application/json" });
              await fetch(`${API_BASE}/api/records`, {
                method: "DELETE",
                headers,
                body: JSON.stringify({ id: record._id }),
              });
              setRecords((prev) => prev.filter((r) => r._id !== record._id));
              if (selected?._id === record._id) setSelected(null);
              Alert.alert("Deleted", "Record deleted.");
            } catch {
              Alert.alert("Error", "Failed to delete record.");
            }
          },
        },
      ],
    );
  };

  const urgencyColor = (level: string) => URGENCY_COLORS[level] || URGENCY_COLORS.Medium;
  const statusColor = (status: string) => STATUS_COLORS[status] || STATUS_COLORS.Active;

  const initials = (name: string) =>
    name
      .trim()
      .split(/\s+/)
      .map((w) => w[0])
      .slice(0, 2)
      .join("")
      .toUpperCase() || "?";

  if (selected) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.header}>
            <TouchableOpacity onPress={() => setSelected(null)}>
              <Ionicons name="chevron-back" size={24} color={colors.darkGreen} />
            </TouchableOpacity>
            <Text style={styles.headerTitle} numberOfLines={1}>
              {selected.recordId}
            </Text>
            <View style={styles.headerActions}>
              <TouchableOpacity onPress={() => router.push({ pathname: "/record-form", params: { recordId: selected._id } })} style={styles.headerBtn}>
                <Ionicons name="pencil" size={20} color={colors.green} />
              </TouchableOpacity>
              <TouchableOpacity onPress={() => handleDelete(selected)} style={styles.headerBtn}>
                <Ionicons name="trash-outline" size={20} color="#dc2626" />
              </TouchableOpacity>
            </View>
          </View>

          <ScrollView contentContainerStyle={styles.detailScroll}>
            {/* Record Header Card */}
            <LinearGradient
              colors={[colors.forestDark, colors.forestSoft]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.recordHeaderCard}
            >
              <Text style={styles.recordId}>{selected.recordId}</Text>
              <Text style={styles.householdName}>{selected.headOfHousehold}</Text>
              <View style={styles.badgeRow}>
                <View style={[styles.badge, { backgroundColor: urgencyColor(selected.urgencyLevel).bg }]}>
                  <Text style={[styles.badgeText, { color: urgencyColor(selected.urgencyLevel).text }]}>
                    {selected.urgencyLevel}
                  </Text>
                </View>
                <View style={[styles.badge, { backgroundColor: statusColor(selected.status).bg }]}>
                  <Text style={[styles.badgeText, { color: statusColor(selected.status).text }]}>
                    {selected.status}
                  </Text>
                </View>
              </View>
            </LinearGradient>

            {/* Contact Info */}
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Contact Information</Text>
              <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                <InfoRow icon="call-outline" label="Phone" value={selected.contactNumber} />
                {selected.emailAddress ? (
                  <InfoRow icon="mail-outline" label="Email" value={selected.emailAddress} />
                ) : null}
                <InfoRow icon="location-outline" label="Address" value={selected.physicalAddress} />
                <InfoRow icon="person-outline" label="Case Manager" value={selected.caseManager} />
                <InfoRow icon="calendar-outline" label="Intake Date" value={selected.dateOfIntake ? new Date(selected.dateOfIntake).toLocaleDateString() : "N/A"} />
              </GradientBox>
            </View>

            {/* Summary */}
            {selected.summary ? (
              <View style={styles.section}>
                <Text style={styles.sectionTitle}>Summary</Text>
                <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                  <Text style={styles.summaryText}>{selected.summary}</Text>
                </GradientBox>
              </View>
            ) : null}

            {/* Household Members */}
            {selected.householdMembers && selected.householdMembers.length > 0 ? (
              <View style={styles.section}>
                <Text style={styles.sectionTitle}>Household Members ({selected.householdMembers.length})</Text>
                <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                  {selected.householdMembers.map((m, i) => (
                    <View key={i} style={[styles.memberRow, i < selected.householdMembers.length - 1 && styles.memberBorder]}>
                      <View style={styles.memberIcon}>
                        <Ionicons name="person" size={16} color={colors.white} />
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={styles.memberName}>{m.name}</Text>
                        <Text style={styles.memberMeta}>{m.relationship} · Age {m.age}</Text>
                      </View>
                    </View>
                  ))}
                </GradientBox>
              </View>
            ) : null}

            {/* Needs */}
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Needs Assessment</Text>
              <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                {selected.immediateNeeds && selected.immediateNeeds.length > 0 ? (
                  <View style={{ marginBottom: 12 }}>
                    <Text style={styles.needLabel}>Immediate Needs</Text>
                    <View style={styles.chipRow}>
                      {selected.immediateNeeds.map((n, i) => (
                        <View key={i} style={styles.needChip}>
                          <Text style={styles.needChipText}>{n}</Text>
                        </View>
                      ))}
                    </View>
                  </View>
                ) : null}
                {selected.longTermNeeds && selected.longTermNeeds.length > 0 ? (
                  <View>
                    <Text style={styles.needLabel}>Long-Term Needs</Text>
                    <View style={styles.chipRow}>
                      {selected.longTermNeeds.map((n, i) => (
                        <View key={i} style={[styles.needChip, { backgroundColor: colors.forestSoft }]}>
                          <Text style={[styles.needChipText, { color: colors.white }]}>{n}</Text>
                        </View>
                      ))}
                    </View>
                  </View>
                ) : null}
                {(!selected.immediateNeeds || selected.immediateNeeds.length === 0) &&
                 (!selected.longTermNeeds || selected.longTermNeeds.length === 0) ? (
                  <Text style={styles.noData}>No needs recorded</Text>
                ) : null}
              </GradientBox>
            </View>

            {/* Action Log */}
            {selected.actionLog && selected.actionLog.length > 0 ? (
              <View style={styles.section}>
                <Text style={styles.sectionTitle}>Action Log ({selected.actionLog.length})</Text>
                <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                  {selected.actionLog.map((log, i) => (
                    <View key={i} style={[styles.actionRow, i < selected.actionLog.length - 1 && styles.memberBorder]}>
                      <View style={styles.actionDot} />
                      <View style={{ flex: 1 }}>
                        <Text style={styles.actionText}>{log.actionTaken}</Text>
                        <Text style={styles.actionMeta}>
                          {log.byWhom} · {log.date ? new Date(log.date).toLocaleDateString() : ""}
                        </Text>
                        {log.amountsUsed ? (
                          <Text style={styles.actionMeta}>Amount: R {Number(log.amountsUsed).toLocaleString("en-US")}</Text>
                        ) : null}
                        {log.nextStep ? (
                          <Text style={styles.actionNext}>Next: {log.nextStep}</Text>
                        ) : null}
                      </View>
                    </View>
                  ))}
                </GradientBox>
              </View>
            ) : null}

            {/* Closure Info */}
            {selected.caseClosedDate ? (
              <View style={styles.section}>
                <Text style={styles.sectionTitle}>Case Closure</Text>
                <GradientBox gradient="bgToWhite" style={styles.sectionCard}>
                  <InfoRow icon="checkmark-circle-outline" label="Closed" value={new Date(selected.caseClosedDate).toLocaleDateString()} />
                  {selected.finalOutcome ? (
                    <InfoRow icon="flag-outline" label="Outcome" value={selected.finalOutcome} />
                  ) : null}
                </GradientBox>
              </View>
            ) : null}
          </ScrollView>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()}>
            <Ionicons name="close" size={24} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Records</Text>
          <View style={{ width: 24 }} />
        </View>

        {!authorized ? (
          <EmptyState
            icon="lock-closed-outline"
            color={colors.error}
            eyebrow="Restricted"
            title="Admin access required"
            subtitle="Only authorised staff can view family records."
          />
        ) : loading ? (
          <SkeletonList count={5} render={RecordCardSkeleton} />
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load records"
            subtitle={error}
          />
        ) : records.length === 0 ? (
          <EmptyState
            icon="folder-open-outline"
            color={colors.info}
            eyebrow="Records"
            title="No records found"
            subtitle="Intake records will appear here once they're added."
          />
        ) : (
          <>
            <FlatList
              data={records}
              keyExtractor={(item) => item._id}
              contentContainerStyle={styles.list}
              refreshControl={
                <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} tintColor={colors.gold} colors={[colors.gold]} />
              }
              renderItem={({ item }) => {
                const urg = urgencyColor(item.urgencyLevel);
                const st = statusColor(item.status);
                const intake = item.dateOfIntake
                  ? new Date(item.dateOfIntake).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })
                  : "";
                const needs = item.immediateNeeds ?? [];
                const shownNeeds = needs.slice(0, 3);
                const extraNeeds = needs.length - shownNeeds.length;
                const lastAction = item.actionLog?.length
                  ? item.actionLog[item.actionLog.length - 1]
                  : null;
                const nextStep = lastAction?.nextStep?.trim();
                return (
                  <TouchableOpacity onPress={() => setSelected(item)} activeOpacity={0.85}>
                    <View style={styles.recordCard}>
                      <View style={[styles.cardHero, { backgroundColor: urg.bg }]}>
                        <View style={[styles.cardAvatar, { backgroundColor: urg.text }]}>
                          <Text style={styles.cardAvatarText}>
                            {initials(item.headOfHousehold)}
                          </Text>
                        </View>
                        <View style={{ flex: 1 }}>
                          <Text style={[styles.cardRecordId, { color: urg.text }]}>
                            {item.recordId}
                          </Text>
                          <Text style={styles.cardName} numberOfLines={1}>
                            {item.headOfHousehold}
                          </Text>
                        </View>
                        <View style={styles.urgencyPill}>
                          <View style={[styles.urgencyDot, { backgroundColor: urg.text }]} />
                          <Text style={[styles.urgencyText, { color: urg.text }]}>
                            {item.urgencyLevel}
                          </Text>
                        </View>
                      </View>

                      <View style={styles.cardBody}>
                        {item.contactNumber || intake || item.caseManager ? (
                          <View style={styles.cardMetaRow}>
                            {item.contactNumber ? (
                              <View style={styles.metaItem}>
                                <Ionicons name="call-outline" size={13} color={colors.muted} />
                                <Text style={styles.metaText}>{item.contactNumber}</Text>
                              </View>
                            ) : null}
                            {intake ? (
                              <View style={styles.metaItem}>
                                <Ionicons name="calendar-outline" size={13} color={colors.muted} />
                                <Text style={styles.metaText}>{intake}</Text>
                              </View>
                            ) : null}
                            {item.caseManager ? (
                              <View style={styles.metaItem}>
                                <Ionicons name="person-outline" size={13} color={colors.muted} />
                                <Text style={styles.metaText} numberOfLines={1}>
                                  {item.caseManager}
                                </Text>
                              </View>
                            ) : null}
                          </View>
                        ) : null}
                        {shownNeeds.length > 0 ? (
                          <View style={styles.needRow}>
                            {shownNeeds.map((need, i) => (
                              <View key={i} style={styles.needTag}>
                                <Text style={styles.needTagText} numberOfLines={1}>
                                  {need}
                                </Text>
                              </View>
                            ))}
                            {extraNeeds > 0 ? (
                              <Text style={styles.needMore}>+{extraNeeds} more</Text>
                            ) : null}
                          </View>
                        ) : null}
                        {nextStep ? (
                          <View style={styles.nextStrip}>
                            <Ionicons name="arrow-forward-circle" size={15} color="#0e7490" />
                            <Text style={styles.nextText} numberOfLines={1}>
                              Next: {nextStep}
                            </Text>
                          </View>
                        ) : null}
                        <View style={styles.cardFooter}>
                          <View
                            style={[
                              styles.statusBadge,
                              { backgroundColor: st.bg, borderColor: `${st.text}33` },
                            ]}
                          >
                            <Text style={[styles.statusText, { color: st.text }]}>
                              {item.status}
                            </Text>
                          </View>
                          <View style={styles.footerRight}>
                            <View style={styles.hhChip}>
                              <Ionicons name="people" size={13} color="#0e7490" />
                              <Text style={styles.hhChipText}>
                                {item.householdMembers?.length ?? 0}
                              </Text>
                            </View>
                            <View style={styles.chevronCircle}>
                              <Ionicons name="chevron-forward" size={15} color={colors.darkGreen} />
                            </View>
                          </View>
                        </View>
                      </View>
                    </View>
                  </TouchableOpacity>
                );
              }}
            />
            <View style={styles.totalRow}>
              <Text style={styles.totalText}>Total Records: {records.length}</Text>
            </View>
          </>
        )}

        {/* Create FAB */}
        {authorized && (
          <TouchableOpacity style={[styles.fab, { bottom: insets.bottom + 24 }]} onPress={() => router.push("/record-form")}>
            <GradientBox gradient="darkGreen" style={styles.fabGradient}>
              <Ionicons name="add" size={28} color={colors.white} />
            </GradientBox>
          </TouchableOpacity>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

function RecordCardSkeleton() {
  return (
    <View style={styles.recordCard}>
      <View style={[styles.cardHero, { backgroundColor: "#eef6f9" }]}>
        <SkeletonPulse style={{ width: 46, height: 46, borderRadius: 23 }} />
        <View style={{ flex: 1 }}>
          <SkeletonPulse style={{ width: 96, height: 11 }} />
          <SkeletonPulse style={{ width: "62%", height: 16, marginTop: 6 }} />
        </View>
        <SkeletonPulse style={{ width: 72, height: 24, borderRadius: 12 }} />
      </View>
      <View style={styles.cardBody}>
        <SkeletonPulse style={{ width: "70%", height: 12, marginTop: 12 }} />
        <View style={styles.needRow}>
          <SkeletonPulse style={{ width: 84, height: 22, borderRadius: 8 }} />
          <SkeletonPulse style={{ width: 66, height: 22, borderRadius: 8 }} />
          <SkeletonPulse style={{ width: 52, height: 22, borderRadius: 8 }} />
        </View>
        <SkeletonPulse style={{ width: "88%", height: 30, borderRadius: 10, marginTop: 10 }} />
        <View style={styles.cardFooter}>
          <SkeletonPulse style={{ width: 76, height: 22, borderRadius: 11 }} />
          <View style={styles.footerRight}>
            <SkeletonPulse style={{ width: 40, height: 22, borderRadius: 11 }} />
            <SkeletonPulse style={{ width: 24, height: 24, borderRadius: 12 }} />
          </View>
        </View>
      </View>
    </View>
  );
}

function InfoRow({ icon, label, value }: { icon: string; label: string; value: string }) {
  return (
    <View style={styles.infoRow}>
      <Ionicons name={icon as any} size={18} color={colors.gold} />
      <View style={{ flex: 1 }}>
        <Text style={styles.infoLabel}>{label}</Text>
        <Text style={styles.infoValue}>{value || "N/A"}</Text>
      </View>
    </View>
  );
}

