import { cachedFetch, type CachedFetchOptions } from "./cache";

const PREFIX = "/api/onboarding-induction";

export type OnboardingStatus =
  | "assigned"
  | "pending"
  | "approved"
  | "rejected"
  | "retake";

export type OnboardingAnswers = {
  foundApp: boolean;
  installedApp: boolean;
  createdAccount: boolean;
  loggedIn: boolean;
  canLoginAgain: boolean;
  joinedClub: boolean;
  joinedTeam: boolean;
  foundTraining: boolean;
  registeredAttendance: boolean;
  readMinutes: boolean;
  markedTaskComplete: boolean;
  knowsWhoToAsk: boolean;
  secretarySetupMeeting: boolean;
  secretaryAddedMinutes: boolean;
  secretaryCheckedAttendance: boolean;
  secretaryTrackedTasks: boolean;
  secretaryFoundOldMinutes: boolean;
  treasurerStartedReport: boolean;
  treasurerCheckedReport: boolean;
  treasurerSharedReport: boolean;
  treasurerKnowsCorrection: boolean;
  treasurerKnowsMemberView: boolean;
  watchedVideos: boolean;
  canDoRoleTasks: boolean;
  willAskForHelp: boolean;
  note: string;
  reasons: Record<string, string>;
};

export type OnboardingSubmission = {
  id: string;
  userId: string;
  userName: string;
  userEmail: string;
  answers: OnboardingAnswers;
  status: OnboardingStatus;
  startDate: string | null;
  dueDate: string | null;
  assignedBy: string | null;
  assignedAt: string | null;
  attempt: number;
  reviewNote: string;
  reviewedBy: string | null;
  reviewedAt: string | null;
  submittedAt: string | null;
  createdAt: string | null;
  updatedAt: string | null;
};

export type AdminOnboardingRow = {
  userId: string;
  userName: string;
  userEmail: string;
  startDate: string | null;
  dueDate: string | null;
  status: OnboardingStatus | null;
  attempt: number;
  submittedAt: string | null;
  submissionId: string | null;
};

export function emptyOnboardingAnswers(): OnboardingAnswers {
  return {
    foundApp: false,
    installedApp: false,
    createdAccount: false,
    loggedIn: false,
    canLoginAgain: false,
    joinedClub: false,
    joinedTeam: false,
    foundTraining: false,
    registeredAttendance: false,
    readMinutes: false,
    markedTaskComplete: false,
    knowsWhoToAsk: false,
    secretarySetupMeeting: false,
    secretaryAddedMinutes: false,
    secretaryCheckedAttendance: false,
    secretaryTrackedTasks: false,
    secretaryFoundOldMinutes: false,
    treasurerStartedReport: false,
    treasurerCheckedReport: false,
    treasurerSharedReport: false,
    treasurerKnowsCorrection: false,
    treasurerKnowsMemberView: false,
    watchedVideos: false,
    canDoRoleTasks: false,
    willAskForHelp: false,
    note: "",
    reasons: {},
  };
}

function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, [PREFIX]);
}

export const onboardingApi = {
  get: () =>
    apiFetch<{ data: OnboardingSubmission | null; canApprove: boolean }>(PREFIX, {
      cacheTtl: 0,
    }),

  queue: () =>
    apiFetch<{ data: OnboardingSubmission[]; canApprove: boolean }>(
      `${PREFIX}?queue=1`,
      { cacheTtl: 0 },
    ),

  admins: () =>
    apiFetch<{ data: AdminOnboardingRow[]; canApprove: boolean }>(
      `${PREFIX}?admins=1`,
      { cacheTtl: 0 },
    ),

  assign: (userId: string, startDate: string, dueDate: string) =>
    apiFetch<{ data: OnboardingSubmission }>(`${PREFIX}/assignments`, {
      method: "POST",
      body: JSON.stringify({ userId, startDate, dueDate }),
    }),

  submit: (answers: OnboardingAnswers) =>
    apiFetch<{ data: OnboardingSubmission }>(PREFIX, {
      method: "POST",
      body: JSON.stringify({ answers }),
    }),

  review: (
    id: string,
    action: "approve" | "reject" | "retake",
    reviewNote: string,
  ) =>
    apiFetch<{ data: OnboardingSubmission }>(`${PREFIX}/${id}`, {
      method: "PATCH",
      body: JSON.stringify({ action, reviewNote }),
    }),
};
