import { SafeAreaProvider } from "react-native-safe-area-context";
import { useEffect } from "react";
import { useRouter } from "expo-router";
import { CreateModal } from "@/app/(tabs)/community";
import { getSession } from "@/services/auth";

export default function CreateEventScreen() {
  const router = useRouter();

  useEffect(() => {
    let active = true;
    getSession()
      .then((session) => {
        if (active && session?.user?.role !== "admin") router.back();
      })
      .catch((error) => {
        console.error("Failed to check event creation access:", error);
        if (active) router.back();
      });
    return () => {
      active = false;
    };
  }, [router]);

  return (
    <SafeAreaProvider>
      <CreateModal
        visible
        type="event"
        onClose={() => router.back()}
        nativePresentation
      />
    </SafeAreaProvider>
  );
}
