import { getRequestHeaders } from "./auth";
import { API_BASE } from "./config";

export type NotificationPreferencesPatch = {
  enabled?: boolean;
  advanceMinutes?: number;
  lat?: number;
  lng?: number;
  tzOffset?: number;
  readingEnabled?: boolean;
  readingTime?: string;
  votdEnabled?: boolean;
};

export async function syncNotificationPreferences(
  patch: NotificationPreferencesPatch,
): Promise<void> {
  try {
    const res = await fetch(`${API_BASE}/api/prayer-preferences`, {
      method: "PUT",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      credentials: "include",
      body: JSON.stringify(patch),
    });
    if (!res.ok) {
      console.warn(`[notifications] preferences sync failed ${res.status}`);
    }
  } catch {}
}
