import { useState, useCallback, useEffect } from "react";
import {
  FlatList,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useRouter } from "expo-router";
import { useSQLiteContext } from "expo-sqlite";
import { StatusBar } from "expo-status-bar";
import { SafeAreaView } from "react-native-safe-area-context";
import { searchVerses, type VerseRow } from "@/lib/bible-queries";
import { colors } from "@/constants/colors";
import { IS_WEB } from "@/services/config";
import BibleDatabaseProvider from "@/components/bible/BibleDatabaseProvider";

type Result = VerseRow & { rank: number };

function SearchInner() {
  const db = useSQLiteContext();
  const router = useRouter();
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Result[]>([]);

  const handleSearch = useCallback(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    const found = searchVerses(db, query.trim());
    setResults(found);
  }, [db, query]);

  const handleResultPress = (item: Result) => {
    router.push({
      pathname: "/(tabs)/bible",
      params: { book: item.book_name, chapter: String(item.chapter) },
    });
  };

  return (
    <SafeAreaView style={styles.root} edges={["top", "bottom"]}>
      <StatusBar style="light" />
      <View style={styles.header}>
        <TouchableOpacity onPress={() => router.back()} style={styles.backBtn}>
          <Text style={styles.backText}>← Back</Text>
        </TouchableOpacity>
        <Text style={styles.title}>Search Scripture</Text>
      </View>

      <View style={styles.searchRow}>
        <TextInput
          style={styles.input}
          value={query}
          onChangeText={setQuery}
          onSubmitEditing={handleSearch}
          placeholder="Search verses..."
          placeholderTextColor="rgba(255,255,255,0.3)"
          returnKeyType="search"
          autoCapitalize="none"
        />
        <TouchableOpacity style={styles.searchBtn} onPress={handleSearch}>
          <Text style={styles.searchBtnText}>Search</Text>
        </TouchableOpacity>
      </View>

      <FlatList
        data={results}
        keyExtractor={(item) => String(item.id)}
        contentContainerStyle={styles.list}
        ListEmptyComponent={
          query.length > 0 ? (
            <Text style={styles.empty}>No results found</Text>
          ) : (
            <Text style={styles.empty}>Type to search across all translations</Text>
          )
        }
        renderItem={({ item }) => (
          <TouchableOpacity
            style={styles.resultItem}
            onPress={() => handleResultPress(item)}
          >
            <View style={styles.resultHeader}>
              <Text style={styles.resultRef}>
                {item.book_name} {item.chapter}:{item.verse}
              </Text>
              <Text style={styles.resultVersion}>{item.version}</Text>
            </View>
            <Text style={styles.resultText} numberOfLines={3}>
              {item.text}
            </Text>
          </TouchableOpacity>
        )}
      />
    </SafeAreaView>
  );
}

export default function SearchScreen() {
  const router = useRouter();

  useEffect(() => {
    if (IS_WEB) router.replace("/");
  }, [router]);

  if (IS_WEB) return null;

  return (
    <BibleDatabaseProvider label="Opening Search…">
      <SearchInner />
    </BibleDatabaseProvider>
  );
}

