import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  BackHandler,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import EmptyState from "@/components/EmptyState";
import {
  appraisalApi,
  type AppraisalAnswers,
  type AppraisalDetail,
  type AppraisalField,
  type AppraisalStatus,
} from "@/services/appraisals";
import { GradientBox } from "@/constants/gradients";

const STATUS_TONE: Record<AppraisalStatus, { bg: string; color: string }> = {
  assigned: { bg: "#fef3c7", color: "#b45309" },
  submitted: { bg: "#d4eef5", color: "#1d2a4d" },
  approved: { bg: "#d1fae5", color: "#047857" },
  rejected: { bg: "#ffe4e6", color: "#be123c" },
};

const BAND_TONE: Record<string, { bg: string; color: string }> = {
  Excellent: { bg: "#d1fae5", color: "#047857" },
  Strong: { bg: "#d4eef5", color: "#0e7490" },
  Meets: { bg: "#e2e8f0", color: "#1d2a4d" },
  Developing: { bg: "#fef3c7", color: "#b45309" },
  Intervention: { bg: "#ffe4e6", color: "#be123c" },
};

const BAND_FALLBACK = { bg: "#e2e8f0", color: "#1d2a4d" };

function ratioColor(ratio: number) {
  if (ratio >= 0.8) return "#047857";
  if (ratio >= 0.6) return "#0fa3c4";
  if (ratio >= 0.4) return "#b45309";
  return "#be123c";
}

function pctOf(score: number, weight: number) {
  if (weight <= 0) return 0;
  return Math.max(0, Math.min(100, Math.round((score / weight) * 100)));
}

function formatAnswer(field: AppraisalField, value: string | number | undefined) {
  if (value === undefined || value === null || value === "") return "—";
  if (field.kind === "currency") {
    const num = Number(value);
    return Number.isFinite(num) ? `R ${num.toLocaleString("en-US")}` : String(value);
  }
  if (field.kind === "percent") return `${value}%`;
  return String(value);
}

export default function AppraisalDetailScreen() {
  const { id } = useLocalSearchParams<{ id?: string }>();
  const insets = useSafeAreaInsets();
  const [data, setData] = useState<AppraisalDetail | null>(null);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    if (!id) {
      setError("No appraisal selected.");
      return;
    }
    try {
      const res = await appraisalApi.get(id);
      setData(res.data);
      setNotes(res.data.reviewNotes || "");
      setError("");
      const next: Record<string, string> = {};
      for (const section of res.data.form.sections) {
        for (const field of section.fields) {
          const value = res.data.answers[field.id];
          next[field.id] = value === undefined || value === null ? "" : String(value);
        }
      }
      setAnswers(next);
    } catch (e: any) {
      setError(e?.message || "Failed to load the appraisal.");
    }
  }, [id]);

  useEffect(() => {
    (async () => {
      await load();
    })();
  }, [load]);

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      router.back();
      return true;
    });
    return () => sub.remove();
  }, []);

  const setAnswer = (fieldId: string, value: string) => {
    setAnswers((prev) => ({ ...prev, [fieldId]: value }));
  };

  const submit = async () => {
    if (!data) return;
    setBusy(true);
    try {
      const payload: AppraisalAnswers = { ...answers };
      await appraisalApi.submit(data._id, payload);
      await load();
      Alert.alert("Appraisal submitted", "Your admin has been notified to review it.");
    } catch (e: any) {
      Alert.alert("Could not submit", e?.message || "Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const review = async (action: "approve" | "reject") => {
    if (!data) return;
    if (action === "reject" && !notes.trim()) {
      Alert.alert("Add notes", "Explain what needs to change before sending it back.");
      return;
    }
    setBusy(true);
    try {
      await appraisalApi.review(data._id, action, notes.trim());
      await load();
      Alert.alert(
        action === "approve" ? "Appraisal approved" : "Sent back",
        action === "approve"
          ? "The score is now part of organisation performance."
          : "The member has been notified with your notes.",
      );
    } catch (e: any) {
      Alert.alert("Could not update", e?.message || "Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const tone = data ? STATUS_TONE[data.status] : STATUS_TONE.assigned;
  const band = (data && BAND_TONE[data.band || ""]) || BAND_FALLBACK;

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.headerBtn}
            accessibilityLabel="Close appraisal"
          >
            <Ionicons name="close" size={22} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Appraisal</Text>
          <View style={{ width: 36 }} />
        </View>

        {!data && !error ? (
          <View style={styles.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn’t load this appraisal"
            subtitle={error}
            actionLabel="Retry"
            onAction={load}
          />
        ) : data ? (
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            style={styles.flex}
          >
            <ScrollView
              contentContainerStyle={[styles.list, { paddingBottom: 36 + insets.bottom }]}
              showsVerticalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              keyboardDismissMode="none"
            >
              <LinearGradient
                colors={["#FFE9D6", "#FFCBA4"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.hero}
              >
                <View style={styles.heroTop}>
                  <View style={styles.heroHead}>
                    <Ionicons name="clipboard" size={16} color="#9A3412" />
                    <Text style={styles.heroEyebrow}>
                      {data.type === "department" ? "DEPARTMENT" : "INDIVIDUAL"}
                    </Text>
                  </View>
                  <View
                    style={[
                      styles.pill,
                      { backgroundColor: tone.bg, borderColor: `${tone.color}33` },
                    ]}
                  >
                    <Text style={[styles.pillText, { color: tone.color }]}>
                      {data.statusLabel}
                    </Text>
                  </View>
                </View>
                <Text style={styles.heroTitle}>
                  {data.type === "department" ? data.department : data.subjectName}
                </Text>
                <Text style={styles.heroSub}>
                  {data.season} {data.seasonYear}
                  {data.type === "department" ? ` · lead ${data.subjectName}` : ""}
                </Text>
                {data.assignedByName ? (
                  <Text style={styles.heroHint}>Allocated by {data.assignedByName}</Text>
                ) : null}

                {data.score != null && data.status !== "assigned" ? (
                  <View style={styles.scoreBlock}>
                    <View style={styles.scoreRow}>
                      <View style={{ flex: 1 }}>
                        <Text style={styles.scoreLabel}>{"SEASON SCORE"}</Text>
                        <Text style={styles.scoreValue}>{Math.round(data.score)}%</Text>
                      </View>
                      <View
                        style={[
                          styles.bandPill,
                          { backgroundColor: band.bg, borderColor: `${band.color}33` },
                        ]}
                      >
                        <Text style={[styles.bandText, { color: band.color }]}>
                          {data.band || "Scored"}
                        </Text>
                      </View>
                    </View>
                    <View style={styles.barTrack}>
                      <View
                        style={[
                          styles.barFill,
                          {
                            width: `${pctOf(data.score, 100)}%`,
                            backgroundColor: "#C2410C",
                          },
                        ]}
                      />
                    </View>
                  </View>
                ) : null}
              </LinearGradient>

              {data.status === "rejected" && data.reviewNotes ? (
                <View style={styles.backCard}>
                  <View style={styles.cardHead}>
                    <Ionicons name="return-down-back-outline" size={16} color="#be123c" />
                    <Text style={styles.backTitle}>Sent back with notes</Text>
                  </View>
                  <Text style={styles.backBody}>{data.reviewNotes}</Text>
                </View>
              ) : null}

              {data.canSubmit ? (
                <>
                  <Text style={styles.formHint}>
                    Fill in every figure for {data.season} {data.seasonYear}. Your score is
                    calculated from these figures when you submit.
                  </Text>
                  {data.form.sections.map((section) => {
                    const filled = section.fields.filter(
                      (field) => (answers[field.id] ?? "").trim() !== "",
                    ).length;
                    return (
                      <View key={section.id} style={styles.card}>
                        <View style={styles.sectionHead}>
                          <View style={styles.cardHead}>
                            <Text style={styles.cardTitle}>{section.title}</Text>
                            {section.weight > 0 ? (
                              <Text style={styles.weight}>{section.weight}%</Text>
                            ) : (
                              <Text style={styles.optional}>Optional</Text>
                            )}
                          </View>
                          <View style={styles.progressRow}>
                            <View style={[styles.sectionTrack, styles.flex]}>
                              <View
                                style={[
                                  styles.sectionFill,
                                  {
                                    width: `${pctOf(filled, section.fields.length)}%`,
                                    backgroundColor: colors.gold,
                                  },
                                ]}
                              />
                            </View>
                            <Text style={styles.progressText}>
                              {filled}/{section.fields.length}
                            </Text>
                          </View>
                        </View>
                        {section.fields.map((field) => (
                          <View key={field.id} style={styles.field}>
                            <Text style={styles.fieldLabel}>{field.label}</Text>
                            {field.kind === "choice" ? (
                              <View style={styles.choiceRow}>
                                {(field.options || []).map((option) => {
                                  const on = answers[field.id] === option;
                                  return (
                                    <TouchableOpacity
                                      key={option}
                                      style={[styles.choice, on && styles.choiceOn]}
                                      onPress={() => setAnswer(field.id, option)}
                                      activeOpacity={0.85}
                                    >
                                      <Text
                                        style={[styles.choiceText, on && styles.choiceTextOn]}
                                      >
                                        {option}
                                      </Text>
                                    </TouchableOpacity>
                                  );
                                })}
                              </View>
                            ) : field.kind === "text" ? (
                              <TextInput
                                style={[styles.input, styles.textArea]}
                                multiline
                                textAlignVertical="top"
                                maxLength={field.maxLength ?? 2000}
                                placeholder={field.hint || "Write your answer"}
                                placeholderTextColor={colors.muted}
                                value={answers[field.id] ?? ""}
                                onChangeText={(text) => setAnswer(field.id, text)}
                              />
                            ) : (
                              <TextInput
                                style={styles.input}
                                keyboardType="numeric"
                                placeholder={field.hint || "0"}
                                placeholderTextColor={colors.muted}
                                value={answers[field.id] ?? ""}
                                onChangeText={(text) => setAnswer(field.id, text)}
                              />
                            )}
                          </View>
                        ))}
                      </View>
                    );
                  })}

                  <TouchableOpacity
                    style={[styles.primaryBtn, busy && styles.busy]}
                    onPress={submit}
                    disabled={busy}
                    activeOpacity={0.9}
                  >
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                    {busy ? (
                      <ActivityIndicator color={colors.white} />
                    ) : (
                      <>
                        <Ionicons name="cloud-upload-outline" size={18} color={colors.white} />
                        <Text style={styles.primaryText}>Submit appraisal</Text>
                      </>
                    )}
                  </TouchableOpacity>
                </>
              ) : (
                <>
                  {data.sections.map((section) => {
                    const form = data.form.sections.find((s) => s.id === section.id);
                    if (!form) return null;
                    const fields = form.fields.filter((field) => {
                      if (field.kind === "text") return !!data.answers[field.id];
                      return true;
                    });
                    return (
                      <View key={section.id} style={styles.card}>
                        <View style={styles.sectionHead}>
                          <View style={styles.cardHead}>
                            <Text style={styles.cardTitle}>{section.title}</Text>
                            {section.weight > 0 ? (
                              <Text style={styles.sectionScore}>
                                {section.score}/{section.weight}
                              </Text>
                            ) : null}
                          </View>
                          {section.weight > 0 ? (
                            <View style={styles.sectionTrack}>
                              <View
                                style={[
                                  styles.sectionFill,
                                  {
                                    width: `${pctOf(section.score, section.weight)}%`,
                                    backgroundColor: ratioColor(
                                      section.weight > 0 ? section.score / section.weight : 0,
                                    ),
                                  },
                                ]}
                              />
                            </View>
                          ) : null}
                        </View>
                        {fields.map((field) => (
                          <View key={field.id} style={styles.answerRow}>
                            <Text style={styles.answerLabel}>{field.label}</Text>
                            <Text style={styles.answerValue}>
                              {formatAnswer(field, data.answers[field.id])}
                            </Text>
                          </View>
                        ))}
                        {fields.length === 0 ? (
                          <Text style={styles.answerEmpty}>No commentary provided.</Text>
                        ) : null}
                      </View>
                    );
                  })}

                  {data.status === "approved" && data.reviewNotes ? (
                    <View style={styles.card}>
                      <View style={styles.cardHead}>
                        <Ionicons name="chatbubble-ellipses-outline" size={16} color={colors.goldDark} />
                        <Text style={styles.cardTitle}>Reviewer notes</Text>
                      </View>
                      <Text style={styles.notesBody}>{data.reviewNotes}</Text>
                    </View>
                  ) : null}
                </>
              )}

              {data.canReview ? (
                <View style={styles.card}>
                  <View style={styles.cardHead}>
                    <Ionicons name="shield-checkmark-outline" size={16} color={colors.goldDark} />
                    <Text style={styles.cardTitle}>Review</Text>
                  </View>
                  <Text style={styles.cardSub}>
                    Approving publishes this score to organisation performance. Sending it
                    back lets the member correct their figures.
                  </Text>
                  <Text style={styles.fieldLabel}>Notes to the member</Text>
                  <TextInput
                    style={[styles.input, styles.textArea]}
                    multiline
                    textAlignVertical="top"
                    maxLength={2000}
                    placeholder="What should change, or context for the score"
                    placeholderTextColor={colors.muted}
                    value={notes}
                    onChangeText={setNotes}
                  />
                  <View style={styles.reviewActions}>
                    <TouchableOpacity
                      style={[styles.rejectBtn, busy && styles.busy]}
                      onPress={() => review("reject")}
                      disabled={busy}
                      activeOpacity={0.9}
                    >
                      <Ionicons name="return-down-back" size={17} color="#be123c" />
                      <Text style={styles.rejectText}>Send back</Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={[styles.approveBtn, busy && styles.busy]}
                      onPress={() =>
                        Alert.alert(
                          "Approve appraisal?",
                          `This publishes ${Math.round(data.score || 0)}% to organisation performance.`,
                          [
                            { text: "Cancel", style: "cancel" },
                            {
                              text: "Approve",
                              onPress: () => {
                                review("approve");
                              },
                            },
                          ],
                        )
                      }
                      disabled={busy}
                      activeOpacity={0.9}
                    >
                      <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      {busy ? (
                        <ActivityIndicator color={colors.white} />
                      ) : (
                        <>
                          <Ionicons name="checkmark" size={18} color={colors.white} />
                          <Text style={styles.approveText}>Approve</Text>
                        </>
                      )}
                    </TouchableOpacity>
                  </View>
                </View>
              ) : null}
            </ScrollView>
          </KeyboardAvoidingView>
        ) : null}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

