import { appStorage } from "./app-storage";
import { IS_WEB } from "./config";
import { syncNotificationPreferences } from "./notification-settings";
import {
  scheduleReadingReminderNotification,
  cancelReadingReminderNotification,
} from "./notifications";

// Daily reading-reminder preference: when the app should nudge the user to
// open today's magazine reading. Mirrors the prayer-notification pattern —
// stored on-device, rescheduled whenever the toggle or time changes (and
// self-healed on app open / new-day focus).
const ENABLED_KEY = "reading_reminder_enabled";
const TIME_KEY = "reading_reminder_time";

export type ReadingReminderPref = {
  enabled: boolean;
  hour: number;
  minute: number;
};

const DEFAULT_REMINDER: ReadingReminderPref = {
  enabled: true,
  hour: 19,
  minute: 0,
};

export async function getReadingReminder(): Promise<ReadingReminderPref> {
  let enabled = DEFAULT_REMINDER.enabled;
  let hour = DEFAULT_REMINDER.hour;
  let minute = DEFAULT_REMINDER.minute;
  try {
    const enabledVal = await appStorage.getItemAsync(ENABLED_KEY);
    if (enabledVal !== null) enabled = enabledVal !== "false";
    const time = await appStorage.getItemAsync(TIME_KEY);
    if (time) {
      const parts = time.split(":").map((n) => parseInt(n, 10));
      if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        hour = Math.min(23, Math.max(0, parts[0]));
        minute = Math.min(59, Math.max(0, parts[1]));
      }
    }
  } catch {}
  return { enabled, hour, minute };
}

export async function setReadingReminderEnabled(enabled: boolean): Promise<void> {
  await appStorage.setItemAsync(ENABLED_KEY, enabled ? "true" : "false");
  await syncNotificationPreferences({ readingEnabled: enabled });
}

export async function setReadingReminderTime(hour: number, minute: number): Promise<void> {
  await appStorage.setItemAsync(TIME_KEY, `${hour}:${minute}`);
  await syncNotificationPreferences({ readingTime: `${hour}:${minute}` });
}

/**
 * Applies the stored reminder preference: schedules the daily notification at
 * the chosen time when enabled, otherwise cancels it. Safe to call on every
 * app open / day change — it replace-reschedules and never doubles up.
 */
export async function rescheduleReadingReminder(): Promise<void> {
  if (IS_WEB) return;
  try {
    const pref = await getReadingReminder();
    if (!pref.enabled) {
      await cancelReadingReminderNotification();
      return;
    }
    await scheduleReadingReminderNotification(pref.hour, pref.minute);
  } catch {}
}