import {
  ActivityIndicator,
  Alert,
  Animated,
  Easing,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  useWindowDimensions,
} from "react-native";
import { router } from "expo-router";
import { colors } from "@/constants/colors";
import { formatEventBadge, eventDateRange } from "@/utils/event-dates";
import { formatFee } from "@/utils/fees";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import {
  communityApi,
  type EventAgendaItem,
  type ParticipantUser,
} from "@/services/community";
import { PaymentFormInline } from "@/components/EventPayments";
import { getOptimizedImageUrl } from "@/services/cloudinary";

export type EventDetailLike = {
  id: string;
  title: string;
  date: string;
  time: string;
  dateTo?: string;
  timeTo?: string;
  agenda?: EventAgendaItem[];
  notes?: string;
  location: string;
  description: string;
  fee: string;
  feeAmount: number;
  feeSymbol: string;
  amountPaid: number;
  pendingAmount: number;
  totalDue: number;
  myPartner?: boolean;
  remaining: number;
  imageUrl: string | null;
  author: string;
  attending: number;
  hasRsvpd: boolean;
  isOwner: boolean;
  rsvpUsers: ParticipantUser[];
};

const AVATAR_GRADIENTS: [string, string][] = [
  [colors.gold, colors.goldDark],
  [colors.lightGreen, colors.goldLight],
  [colors.forestSoft, colors.forestDark],
  [colors.goldLight, colors.gold],
];

function agendaChipColors(category?: string): { bg: string; text: string } {
  const c = (category || "").toLowerCase();
  if (c.includes("wor") || c.includes("pray")) return { bg: "#fef3c7", text: "#b45309" };
  if (c.includes("workshop") || c.includes("session")) return { bg: "#e0e7ff", text: "#3730a3" };
  if (c.includes("meal") || c.includes("dinner") || c.includes("lunch") || c.includes("breakfast"))
    return { bg: "#fce7f3", text: "#9d174d" };
  if (c.includes("free") || c.includes("travel") || c.includes("break")) return { bg: "#f3f4f6", text: "#4b5563" };
  return { bg: "#ccfbf1", text: "#115e59" };
}

function HeroImage({ uri, style }: { uri: string; style?: any }) {
  return <RNImage source={{ uri }} style={style} contentFit="cover" />;
}

/**
 * Attendee's own payment summary + self-service payment form. Shown to anyone
 * who has joined a paid event. Self-submitted payments appear as PENDING until
 * the host approves them.
 */
function MyPaymentSection({
  event,
  currentUserId,
  onUpdated,
}: {
  event: EventDetailLike;
  currentUserId: string | null;
  onUpdated?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const fmt = (n: number) => formatFee(event.feeSymbol, n);
  const fullyPaid = event.remaining <= 0;
  const hasPending = event.pendingAmount > 0;
  const statusLabel = fullyPaid
    ? "PAID IN FULL"
    : hasPending
      ? "AWAITING APPROVAL"
      : "BALANCE DUE";
  const statusColor = fullyPaid ? "#10b981" : "#b45309";

  const record = async (amount: number, popUrl: string | null) => {
    if (!currentUserId) return;
    setBusy(true);
    try {
      await communityApi.recordEventPayment(
        event.id,
        currentUserId,
        amount,
        popUrl,
      );
      setOpen(false);
      onUpdated?.();
    } catch {
      Alert.alert("Error", "Failed to record your payment.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <View style={styles.card}>
      <View style={styles.sectionHead}>
        <Ionicons name="wallet-outline" size={15} color={colors.goldDark} />
        <Text style={styles.sectionHeadText}>My payment</Text>
        <View
          style={[
            styles.myPayStatus,
            fullyPaid ? styles.myPayStatusOn : styles.myPayStatusPending,
          ]}
        >
          <Text style={[styles.myPayStatusText, { color: statusColor }]}>
            {statusLabel}
          </Text>
        </View>
      </View>

      <View style={styles.myPayRow}>
        <Text style={styles.myPayLabel}>
          {event.myPartner ? "Fee (2 people)" : "Fee"}
        </Text>
        <Text style={styles.myPayValue}>{fmt(event.totalDue || event.feeAmount)}</Text>
      </View>
      <View style={styles.myPayRow}>
        <Text style={styles.myPayLabel}>Paid</Text>
        <Text style={[styles.myPayValue, { color: "#10b981" }]}>
          {fmt(event.amountPaid)}
        </Text>
      </View>
      {hasPending ? (
        <View style={styles.myPayRow}>
          <Text style={styles.myPayLabel}>Pending approval</Text>
          <Text style={[styles.myPayValue, { color: "#b45309" }]}>
            {fmt(event.pendingAmount)}
          </Text>
        </View>
      ) : null}
      <View style={[styles.myPayRow, styles.myPayRowLast]}>
        <Text style={styles.myPayLabel}>Remaining</Text>
        <Text
          style={[
            styles.myPayValue,
            { color: fullyPaid ? "#10b981" : "#b45309" },
          ]}
        >
          {fmt(event.remaining)}
        </Text>
      </View>

      {fullyPaid ? (
        <Text style={styles.myPayDone}>
          You are all settled up. See you at the event!
        </Text>
      ) : hasPending ? (
        <Text style={styles.myPayPendingNote}>
          Your payment of {fmt(event.pendingAmount)} is awaiting approval by the
          event host.
        </Text>
      ) : open ? (
        <PaymentFormInline
          feeSymbol={event.feeSymbol}
          remaining={event.remaining}
          busy={busy}
          submitLabel="Submit payment"
          onRecord={(amount, popUrl) => record(amount, popUrl)}
          onCancel={() => setOpen(false)}
        />
      ) : (
        <TouchableOpacity
          style={styles.myPayBtn}
          onPress={() => setOpen(true)}
          activeOpacity={0.85}
        >
          <Ionicons name="add-circle-outline" size={15} color={colors.forest} />
          <Text style={styles.myPayBtnText}>Make a payment</Text>
        </TouchableOpacity>
      )}
    </View>
  );
}

export default function EventDetailModal({
  event,
  currentUserId,
  onUpdated,
  onClose,
  onJoin,
  onEdit,
  onDelete,
  joinLoading,
}: {
  event: EventDetailLike;
  currentUserId?: string | null;
  onUpdated?: () => void;
  onClose: () => void;
  onJoin: () => void;
  onEdit: () => void;
  onDelete: () => void;
  joinLoading?: boolean;
}) {
  const insets = useSafeAreaInsets();
  const { height: screenHeight } = useWindowDimensions();

  // Smooth single-motion open/close (fade + slide together) instead of the
  // native slide, which on some platforms shows a bare overlay first.
  const [modalAnim] = useState(() => new Animated.Value(0));
  const closingRef = useRef(false);

  useEffect(() => {
    Animated.timing(modalAnim, {
      toValue: 1,
      duration: 240,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
  }, [modalAnim]);

  const animateOut = useCallback(
    (after?: () => void) => {
      if (closingRef.current) return;
      closingRef.current = true;
      Animated.timing(modalAnim, {
        toValue: 0,
        duration: 180,
        easing: Easing.in(Easing.cubic),
        useNativeDriver: true,
      }).start(() => (after ? after() : onClose()));
    },
    [modalAnim, onClose],
  );

  const badge = formatEventBadge(
    event.date,
    event.time,
    event.dateTo,
    event.timeTo,
  );
  const dateRange = eventDateRange(event.date, event.dateTo);
  const multiDay = !!dateRange.to && !!dateRange.days && dateRange.days > 1;
  const dateTimePart = (() => {
    const t = (event.time || "").trim();
    const tTo = (event.timeTo || "").trim();
    return tTo && tTo !== t ? `${t} - ${tTo}` : t;
  })();
  const dateMeta = multiDay
    ? [
        `${dateRange.days} ${dateRange.days === 1 ? "day" : "days"} · ${
          dateRange.nights
        } ${dateRange.nights === 1 ? "night" : "nights"}`,
        dateTimePart,
      ]
        .filter(Boolean)
        .join(" · ")
    : "";
  const fee = event.fee && event.fee !== "Free" ? event.fee : "Free";
  const shown = (event.rsvpUsers || []).slice(0, 4);

  const agenda = (event.agenda || []).filter(
    (a) => (a.title || "").trim() || (a.time || "").trim(),
  );

  const formatAgendaWindow = (a: EventAgendaItem) => {
    const date =
      a.dateFrom && a.dateTo
        ? `${a.dateFrom} → ${a.dateTo}`
        : a.dateFrom || a.dateTo || "";
    const time =
      a.timeFrom && a.timeTo
        ? `${a.timeFrom} – ${a.timeTo}`
        : a.timeFrom || a.timeTo || "";
    return [date, time].filter(Boolean).join(" · ");
  };

  const infoRows: { icon: any; text: string }[] = [
    { icon: "location-outline", text: event.location },
    ...(fee !== "Free" ? [{ icon: "cash-outline" as any, text: fee }] : []),
    { icon: "person-outline", text: `Hosted by ${event.author}` },
  ].filter((r) => r.text);

  return (
    <Modal
      visible
      animationType="none"
      statusBarTranslucent
      onRequestClose={() => animateOut()}
    >
      <Animated.View
        style={[
          styles.container,
          {
            opacity: modalAnim,
            transform: [
              {
                translateY: modalAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [24, 0],
                }),
              },
            ],
          },
        ]}
      >
        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          <ScrollView
            style={styles.scroll}
            contentContainerStyle={[
              styles.scrollContent,
              {
                paddingTop: insets.top,
                paddingBottom: insets.bottom + 24,
              },
            ]}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
          <LinearGradient
            colors={[colors.gold, colors.goldDark]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.goldBar}
          />

          {/* Hero */}
          <View style={[styles.hero, { height: screenHeight * 0.4 }]}>
            {event.imageUrl ? (
              <HeroImage
                uri={getOptimizedImageUrl(event.imageUrl, 1200)}
                style={styles.heroImg}
              />
            ) : (
              <LinearGradient
                colors={[colors.forestSoft, colors.forestDark]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.heroImg}
              >
                <Ionicons name="trail-sign-outline" size={44} color={colors.gold} />
              </LinearGradient>
            )}
          </View>

          <View style={styles.body}>
            <View style={styles.tagRow}>
              <View style={styles.tagDash} />
              <Text style={styles.tag}>{`${fee} · Community`}</Text>
            </View>
            <Text style={styles.title}>{event.title}</Text>

            {event.description ? (
              <Text style={styles.description}>{event.description}</Text>
            ) : null}

            {/* Quick facts */}
            {multiDay || infoRows.length > 0 ? (
              <View style={styles.infoCard}>
                <View style={styles.infoRow}>
                  <View style={styles.infoIcon}>
                    <Ionicons name="calendar-outline" size={15} color={colors.goldDark} />
                  </View>
                  {multiDay ? (
                    <View style={styles.infoDateCol}>
                      <View style={styles.infoDateLine}>
                        <Text style={styles.infoDateLabel}>FROM  </Text>
                        <Text style={styles.infoText}>{dateRange.from}</Text>
                      </View>
                      <View style={styles.infoDateLine}>
                        <Text style={styles.infoDateLabel}>TO    </Text>
                        <Text style={styles.infoText}>{dateRange.to}</Text>
                      </View>
                      {dateMeta ? (
                        <Text style={styles.infoDateMeta}>{dateMeta}</Text>
                      ) : null}
                    </View>
                  ) : (
                    <Text style={styles.infoText}>{badge}</Text>
                  )}
                </View>
                {infoRows.map((row, i) => (
                  <View key={i} style={[styles.infoRow, styles.infoRowBorder]}>
                    <View style={styles.infoIcon}>
                      <Ionicons name={row.icon} size={15} color={colors.goldDark} />
                    </View>
                    <Text style={styles.infoText}>{row.text}</Text>
                  </View>
                ))}
              </View>
            ) : null}

            {/* Itinerary & activities */}
            {agenda.length > 0 ? (
              <View style={styles.card}>
                <View style={styles.sectionHead}>
                  <Ionicons name="list-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.sectionHeadText}>Itinerary &amp; Activities</Text>
                  {agenda.length > 0 ? (
                    <View style={styles.agendaCountBadge}>
                      <Text style={styles.agendaCountText}>{agenda.length}</Text>
                    </View>
                  ) : null}
                </View>
                {agenda.map((a, i) => {
                  const window = formatAgendaWindow(a);
                  const chip = a.category ? agendaChipColors(a.category) : null;
                  const showMeta = !!(a.location || a.host);
                  return (
                    <View key={i} style={styles.agendaItem}>
                      <View style={styles.agendaTimeline}>
                        <View style={styles.agendaDot} />
                        {i < agenda.length - 1 && <View style={styles.agendaLine} />}
                      </View>
                      <View style={styles.agendaBody}>
                        <View style={styles.agendaTopRow}>
                          {a.time ? (
                            <Text style={styles.agendaTime}>{a.time}</Text>
                          ) : null}
                          <Text style={styles.agendaTitle}>{a.title}</Text>
                          {chip && (
                            <View
                              style={[
                                styles.agendaChip,
                                { backgroundColor: chip.bg },
                              ]}
                            >
                              <Text
                                style={[
                                  styles.agendaChipText,
                                  { color: chip.text },
                                ]}
                              >
                                {a.category}
                              </Text>
                            </View>
                          )}
                        </View>
                        {window ? (
                          <Text style={styles.agendaWindow}>
                            <Ionicons name="time-outline" size={11} color={colors.goldDark} />{" "}
                            {window}
                          </Text>
                        ) : null}
                        {a.description ? (
                          <Text style={styles.agendaDesc}>{a.description}</Text>
                        ) : null}
                        {showMeta ? (
                          <View style={styles.agendaMeta}>
                            {a.location ? (
                              <View style={styles.agendaMetaRow}>
                                <Ionicons
                                  name="location-outline"
                                  size={12}
                                  color={colors.muted}
                                />
                                <Text style={styles.agendaMetaText}>
                                  {a.location}
                                </Text>
                              </View>
                            ) : null}
                            {a.host ? (
                              <View style={styles.agendaMetaRow}>
                                <Ionicons
                                  name="person-outline"
                                  size={12}
                                  color={colors.muted}
                                />
                                <Text style={styles.agendaMetaText}>{a.host}</Text>
                              </View>
                            ) : null}
                          </View>
                        ) : null}
                      </View>
                    </View>
                  );
                })}
              </View>
            ) : null}

            {event.notes ? (
              <View style={styles.notesCard}>
                <View style={styles.sectionHead}>
                  <Ionicons name="information-circle-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.sectionHeadText}>Good to know</Text>
                </View>
                <Text style={styles.notesText}>{event.notes}</Text>
              </View>
            ) : null}

            {/* Attendees */}
            {event.attending > 0 ? (
              <View style={styles.card}>
                <View style={styles.goingRow}>
                  <View style={styles.avatars}>
                    {shown.map((u, i) => {
                      const margin = i === 0 ? 0 : -8;
                      if (u.image) {
                        return (
                          <View
                            key={u.id}
                            style={[styles.avatarWrap, { marginLeft: margin }]}
                          >
                            <HeroImage
                              uri={getOptimizedImageUrl(u.image, 160)}
                              style={styles.avatarImg}
                            />
                          </View>
                        );
                      }
                      return (
                        <LinearGradient
                          key={u.id}
                          colors={AVATAR_GRADIENTS[i % AVATAR_GRADIENTS.length]}
                          start={{ x: 0, y: 0 }}
                          end={{ x: 1, y: 1 }}
                          style={[styles.avatar, { marginLeft: margin }]}
                        >
                          <Text style={styles.avatarText}>
                            {(u.name || "?")[0].toUpperCase()}
                          </Text>
                        </LinearGradient>
                      );
                    })}
                  </View>
                  <Text style={styles.goingText}>
                    <Text style={styles.goingCount}>{event.attending}</Text>{" "}
                    {event.attending === 1 ? "person" : "people"} going
                  </Text>
                </View>

                {/* Payment management (owners) → dedicated screen */}
                {event.isOwner && (event.rsvpUsers || []).length > 0 ? (
                  <TouchableOpacity
                    style={styles.payManageRow}
                    onPress={() =>
                      router.push({
                        pathname: "/event-payments",
                        params: {
                          eventId: event.id,
                          title: event.title,
                          feeSymbol: event.feeSymbol,
                        },
                      })
                    }
                    activeOpacity={0.8}
                  >
                    <View style={styles.payManageIcon}>
                      <Ionicons name="card-outline" size={15} color={colors.forest} />
                    </View>
                    <View style={styles.payManageTextWrap}>
                      <Text style={styles.payManageText}>Manage payments</Text>
                      <Text style={styles.payManageSub}>
                        Record payments, review POPs and approve submissions
                      </Text>
                    </View>
                    <Ionicons name="chevron-forward" size={16} color={colors.muted} />
                  </TouchableOpacity>
                ) : null}
              </View>
            ) : null}

            {/* My payment (attendees on paid events) */}
            {!event.isOwner && event.hasRsvpd && event.feeAmount > 0 ? (
              <MyPaymentSection
                event={event}
                currentUserId={currentUserId ?? null}
                onUpdated={onUpdated}
              />
            ) : null}

            {/* Owner actions */}
            {event.isOwner ? (
              <View style={styles.ownerRow}>
                <TouchableOpacity
                  style={[styles.ownerBtn, styles.editBtn]}
                  onPress={() => animateOut(onEdit)}
                  activeOpacity={0.85}
                >
                  <Ionicons name="pencil-outline" size={15} color={colors.forest} />
                  <Text style={styles.editBtnText}>Edit event</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[styles.ownerBtn, styles.deleteBtn]}
                  onPress={() => animateOut(onDelete)}
                  activeOpacity={0.85}
                >
                  <Ionicons name="trash-outline" size={15} color="#dc2626" />
                  <Text style={styles.deleteBtnText}>Delete</Text>
                </TouchableOpacity>
              </View>
            ) : null}

            {/* Join */}
            <TouchableOpacity
              style={[styles.joinBtn, event.hasRsvpd && styles.joinBtnOn]}
              onPress={() => animateOut(onJoin)}
              disabled={joinLoading}
              activeOpacity={0.85}
            >
              {joinLoading ? (
                <ActivityIndicator
                  size="small"
                  color={event.hasRsvpd ? colors.goldDark : colors.forestDark}
                />
              ) : (
                <>
                  <Ionicons
                    name={event.hasRsvpd ? "checkmark-circle" : "checkmark-circle-outline"}
                    size={17}
                    color={event.hasRsvpd ? colors.goldDark : colors.forestDark}
                  />
                  <Text style={[styles.joinText, event.hasRsvpd && styles.joinTextOn]}>
                    {event.hasRsvpd ? "Joined — you're on the list" : "Join this event"}
                  </Text>
                </>
              )}
            </TouchableOpacity>
          </View>
        </ScrollView>
        </KeyboardAvoidingView>
      </Animated.View>
    </Modal>
  );
}

