/**
 * The guided daily read for a study guide: Verse → Read → Reflect → Respond.
 *
 * Respond finishes the day (prays + "Mark as read") and offers "Share", which
 * opens the native share sheet with the day's verse, reflection and a link to
 * the public web reader.
 */

const STEP_IDS = ["verse", "read", "reflect", "respond"] as const;
const STEP_LABELS = { verse: "Verse", read: "Read", reflect: "Reflect", respond: "Respond" };
const PUBLIC_WEB_URL = "https://relateworld.org";

const isInteractive = (b: PublicationBlock): b is InteractiveBlock =>
  b.type === "checklist" ||
  b.type === "quiz" ||
  b.type === "reflection" ||
  b.type === "pray";

/** First non-verse quote found in a day's reading content, if any. */
const findQuote = (
  blocks: PublicationBlock[],
): { text: string; by?: string } | undefined => {
  for (const b of blocks) {
    if (b.type === "quote") return { text: b.text, by: b.by };
    if (b.type === "reading") {
      const s = b.structure;
      const media: ReadingMedia[][] = [
        s.intro.beforeHook ?? [],
        s.intro.afterHook ?? [],
        s.intro.afterThesis ?? [],
        ...s.body.flatMap((p) => [
          p.beforeTopic ?? [],
          p.afterTopic ?? [],
          p.afterSupport ?? [],
          p.afterClosing ?? [],
        ]),
        s.conclusion.beforeRestate ?? [],
        s.conclusion.afterRestate ?? [],
        s.conclusion.afterWhyItMatters ?? [],
        s.conclusion.afterClosing ?? [],
      ];
      for (const group of media) {
        const q = group.find((m): m is Extract<ReadingMedia, { type: "quote" }> => m.type === "quote");
        if (q) return { text: q.text, by: q.by };
      }
    }
  }
  return undefined;
};

export default function DayReadScreen() {
  const { slug, week: weekParam, day: dayParam } = useLocalSearchParams<{
    slug?: string;
    week?: string;
    day?: string;
  }>();
  const [publication, setPublication] = useState<Publication | undefined>();
  const [loading, setLoading] = useState(true);
  const [responses, setResponses] = useState<DayResponses>({});
  const [done, setDone] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const scrollRef = useRef<ScrollView>(null);
  const [sectionY, setSectionY] = useState<number[]>([]);

  const date = useRef<string | undefined>(undefined);

  const { club, loading: clubsLoading, error: clubsError } = useClub(publication?.clubSlug);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const p = await fetchPublication(slug);
        const weekIndex = Number(weekParam);
        const dayIndex = Number(dayParam);
        const d = p?.weeks?.[weekIndex]?.days?.[dayIndex];
        if (p && d) {
          const [server, readDays] = await Promise.all([
            fetchReadingResponses(p.id),
            fetchReadingDays(),
          ]);
          if (!alive) return;
          date.current = d.date;
          const base = { ...server[d.date], ...getDayResponses(p.id, d.date) };
          setPublication(p);
          setResponses(base);
          setDone(readDays.includes(d.date));
          await loadStreakData();
        } else {
          if (alive) setPublication(undefined);
        }
      } catch {
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, [slug, weekParam, dayParam]);

  const handleChange = useCallback(
    (blockId: string, value: unknown) => {
      const pubId = publication?.id;
      const dayDate = date.current;
      if (!pubId || !dayDate) return;
      setResponses((prev) => ({ ...prev, [blockId]: value }));
      updateDayResponses(pubId, dayDate, { [blockId]: value });
    },
    [publication],
  );

  const handleFlush = useCallback(() => {
    const pubId = publication?.id;
    if (!pubId || !date.current) return;
    void flushDay(pubId, date.current);
  }, [publication]);

  const markDone = async () => {
    if (!date.current) return;
    setDone(true);
    try {
      await loadStreakData();
      await markMagazineRead(date.current);
    } catch {}
    void flushDay(publication?.id || "", date.current);
    setTimeout(() => router.back(), 450);
  };

  const share = () => {
    const pubId = publication?.id;
    const dayDate = date.current;
    if (!pubId || !dayDate) return;
    void flushDay(pubId, dayDate);
    const w = Number(weekParam);
    const v = Number(dayParam);
    const dd = publication.weeks?.[w]?.days?.[v];
    if (!dd) return;

    const parts: string[] = [];

    parts.push(dd.title);

    if (dd.verse?.text) {
      parts.push(`“${dd.verse.text}”${dd.verse.by ? ` — ${dd.verse.by}` : ""}`);
    }

    const q = findQuote(dd.blocks);
    if (q) parts.push(`“${q.text}”${q.by ? ` — ${q.by}` : ""}`);

    const reflect = dd.blocks.find((b) => b.type === "checklist" || b.type === "reflection");
    if (reflect) {
      if (reflect.type === "reflection") {
        parts.push(`Think it over:\n${reflect.prompt}`);
      } else {
        parts.push(`Think it over:\n${reflect.items.map((p) => `• ${p}`).join("\n")}`);
      }
    }

    const pray = dd.blocks.find((b) => b.type === "pray");
    if (pray?.items?.length) {
      parts.push(`Pray:\n${pray.items.map((p) => `• ${p}`).join("\n")}`);
    }

    const clubAge = (club?.ageRange || "").replace(/\s*years?\b/g, "").trim();
    if (club) parts.push(`Relate ${club.name} Club ${clubAge}`.trim());

    const season = publication.season;
    if (season) {
      const startYear = season.start.slice(0, 4);
      const endYear = season.end.slice(0, 4);
      const yearSpan = endYear && endYear !== startYear ? `${startYear}/${endYear}` : startYear;
      parts.push(`${season.name} ${yearSpan} Season Day ${dd.day ?? v + 1}`);
    }

    const webWeek = publication.weeks?.[w]?.index ?? w + 1;
    parts.push(`${PUBLIC_WEB_URL}/library/${pubId}?week=${webWeek}&day=${dayDate}`);
    void Share.share({ message: parts.join("\n\n").trim() });
  };

  if (loading || clubsLoading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={{ padding: 20, gap: 14 }}>
            <SkeletonPulse style={{ width: 120, height: 12 }} />
            <SkeletonPulse style={{ width: "70%", height: 24 }} />
            <SkeletonPulse style={{ width: "100%", height: 120, marginTop: 8 }} />
            <SkeletonPulse style={{ width: "90%", height: 16, marginTop: 8 }} />
            <SkeletonPulse style={{ width: "95%", height: 16 }} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const pubId = publication?.id;
  const weekIndex = Number(weekParam);
  const dayIndex = Number(dayParam);
  const day = publication?.weeks?.[weekIndex]?.days?.[dayIndex];

  if (!publication || !day) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.notFound}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={s.notFoundText}>This day isn&apos;t available yet.</Text>
            <TouchableOpacity style={s.backBtn} onPress={() => router.back()}>
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={s.backBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (clubsError) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={s.safe} edges={["top"]}>
          <View style={s.notFound}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={s.notFoundText}>{clubsError}</Text>
            <TouchableOpacity style={s.backBtn} onPress={() => router.back()}>
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Ionicons name="chevron-back" size={18} color={colors.white} />
              <Text style={s.backBtnText}>Go back</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const accent = club?.colorDark || colors.forest;
  const titleColor = club?.color || colors.darkGreen;
  const readBlocks = day.blocks.filter((b) => !isInteractive(b));
  const reflectBlocks = day.blocks.filter(
    (b) => b.type === "checklist" || b.type === "quiz" || b.type === "reflection",
  ) as InteractiveBlock[];
  const prayBlocks = day.blocks.filter((b) => b.type === "pray") as InteractiveBlock[];

  const onSectionLayout = (index: number) => (e: any) => {
    const y = e?.nativeEvent?.layout?.y;
    if (typeof y !== "number") return;
    setSectionY((prev) => {
      if (prev[index] === y) return prev;
      const next = [...prev];
      next[index] = y;
      return next;
    });
  };

  const onScroll = (e: any) => {
    const y = e.nativeEvent.contentOffset.y + 32;
    let step = 0;
    for (let i = 0; i < sectionY.length; i++) {
      if (sectionY[i] !== undefined && y >= sectionY[i]) {
        step = i;
      }
    }
    if (step !== currentStep) setCurrentStep(step);
  };

  const goToStep = (index: number) => {
    const target = sectionY[index];
    if (target === undefined) return;
    scrollRef.current?.scrollTo({ y: Math.max(0, target - 16), animated: true });
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={s.safe} edges={["top", "bottom"]}>
        <StatusBar style="dark" />

        <View style={s.topBar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={s.topBarBack}
            hitSlop={8}
            accessibilityLabel="Go back"
          >
            <Ionicons name="chevron-back" size={21} color={colors.ink} />
          </TouchableOpacity>
          <View style={s.topBarBody}>
            <Text style={s.topBarEyebrow}>
              {shortWeekday(day.weekday)} · {formatShort(day.date)}
            </Text>
            <Text style={s.topBarTitle} numberOfLines={1}>
              {day.title}
            </Text>
          </View>
          {done ? (
            <View style={s.donePill}>
              <Ionicons name="checkmark-circle" size={15} color={colors.success} />
              <Text style={s.donePillText}>Done</Text>
            </View>
          ) : (
            <View style={s.donePillPlaceholder} />
          )}
        </View>

        <View style={s.stepper}>
          {STEP_IDS.map((id, i) => (
            <TouchableOpacity
              key={id}
              style={s.step}
              onPress={() => goToStep(i)}
              activeOpacity={0.7}
            >
              <Text style={[s.stepText, i <= currentStep && { color: accent, fontWeight: "700" }]}>
                {STEP_LABELS[id]}
              </Text>
            </TouchableOpacity>
          ))}
        </View>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          <ScrollView
            ref={scrollRef}
            contentContainerStyle={s.scrollContent}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
            onScroll={onScroll}
            scrollEventThrottle={32}
          >
          {/* Verse */}
          <View style={s.section} onLayout={onSectionLayout(0)}>
            <View style={s.sectionHead}>
              <Text style={s.sectionEyebrow}>VERSE</Text>
              <Text style={[s.sectionTitle, { color: titleColor }]}>Today&apos;s verse</Text>
            </View>
            <View style={[s.verseCard, { borderColor: accent }]}>
              <Text style={s.verseText}>“{day.verse?.text}”</Text>
              {day.verse?.by ? <Text style={s.verseBy}>— {day.verse.by}</Text> : null}
            </View>
          </View>

          {/* Read */}
          <View style={s.section} onLayout={onSectionLayout(1)}>
            <View style={s.sectionHead}>
              <Text style={s.sectionEyebrow}>READ</Text>
              <Text style={[s.sectionTitle, { color: titleColor }]}>The reading</Text>
            </View>
            {readBlocks.map(renderReadBlock)}
          </View>

          {/* Reflect */}
          {reflectBlocks.length > 0 && pubId ? (
            <View style={s.section} onLayout={onSectionLayout(2)}>
              <View style={s.sectionHead}>
                <Text style={s.sectionEyebrow}>REFLECT</Text>
                <Text style={[s.sectionTitle, { color: titleColor }]}>Think it over</Text>
              </View>
              <InteractiveBlocks
                blocks={reflectBlocks}
                saved={responses}
                onChange={handleChange}
                onFlush={handleFlush}
              />
            </View>
          ) : null}

          {/* Respond */}
          <View style={s.section} onLayout={onSectionLayout(3)}>
            <View style={s.sectionHead}>
              <Text style={s.sectionEyebrow}>RESPOND</Text>
              <Text style={[s.sectionTitle, { color: titleColor }]}>Respond &amp; share</Text>
            </View>
            {prayBlocks.length > 0 && pubId ? (
              <InteractiveBlocks
                blocks={prayBlocks}
                saved={responses}
                onChange={handleChange}
                onFlush={handleFlush}
              />
            ) : null}

            <TouchableOpacity style={s.shareBtn} activeOpacity={0.85} onPress={share}>
                <Ionicons name="share-social-outline" size={17} color={colors.forestSoft} />
                <Text style={s.shareBtnText}>Share</Text>
              </TouchableOpacity>

            <TouchableOpacity
              style={[s.doneBtn, done && s.doneBtnDone]}
              activeOpacity={0.9}
              onPress={markDone}
            >
              {done ? (
                <>
                  <Ionicons name="checkmark-circle" size={18} color={colors.white} />
                  <Text style={s.doneBtnText}>Read today — done</Text>
                </>
              ) : (
                <>
                  <Ionicons name="bookmark" size={18} color={colors.white} />
                  <Text style={s.doneBtnText}>Mark as read · Done</Text>
                </>
              )}
            </TouchableOpacity>
          </View>
        </ScrollView>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

const SHORT_WEEKDAYS: Record<string, string> = {
  Sunday: "Sun",
  Monday: "Mon",
  Tuesday: "Tue",
  Wednesday: "Wed",
  Thursday: "Thu",
  Friday: "Fri",
  Saturday: "Sat",
};

function shortWeekday(name: string) {
  return SHORT_WEEKDAYS[name] || name;
}

function formatShort(date: string) {
  try {
    const d = new Date(`${date}T00:00:00`);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, {
      day: "numeric",
      month: "short",
    });
  } catch {
    return "";
  }
}

function MediaBlock({ media }: { media: ReadingMedia }) {
  if (media.type === "image") {
    return (
      <View style={s.readImageWrap}>
        <Image source={{ uri: getOptimizedImageUrl(media.uri, 720) }} style={s.readImage} contentFit="cover" accessibilityLabel={media.caption || "Reading image"} />
        {media.caption ? <Text style={s.readImageCaption}>{media.caption}</Text> : null}
      </View>
    );
  }
  return (
    <View style={s.readQuote}>
      <Text style={s.readQuoteText}>“{media.text}”</Text>
      {media.by || media.source ? (
        <Text style={s.readQuoteBy}>
          {media.by ? `— ${media.by}` : ""}
          {media.source ? ` · ${media.source}` : ""}
        </Text>
      ) : null}
    </View>
  );
}

function renderReadBlock(b: PublicationBlock, i: number) {
  switch (b.type) {
    case "heading":
      return (
        <Text key={i} style={s.readHeading}>
          {b.text}
        </Text>
      );
    case "quote":
      return (
        <View key={i} style={s.readQuote}>
          <Text style={s.readQuoteText}>“{b.text}”</Text>
          {b.by || b.source ? (
            <Text style={s.readQuoteBy}>
              {b.by ? `— ${b.by}` : ""}
              {b.source ? ` · ${b.source}` : ""}
            </Text>
          ) : null}
        </View>
      );
    case "list":
      return (
        <View key={i} style={s.readList}>
          {b.items.map((item, j) => (
            <View key={j} style={s.readListRow}>
              <View style={s.readListDot} />
              <Text style={s.readListText}>{item}</Text>
            </View>
          ))}
        </View>
      );
    case "reading": {
      const intro = b.structure.intro;
      const body = Array.isArray(b.structure.body) ? b.structure.body : [];
      const conclusion = b.structure.conclusion;
      const media = (m?: ReadingMedia[]) =>
        (m || []).map((x, j) => <MediaBlock key={j} media={x} />);
      return (
        <View key={i}>
          {media(intro?.beforeHook)}
          {intro.hook ? <Text style={s.readParagraph}>{intro.hook}</Text> : null}
          {media(intro?.afterHook)}
          {intro.thesis ? <Text style={s.readParagraph}>{intro.thesis}</Text> : null}
          {media(intro?.afterThesis)}
          {body.map((item, j) => (
            <View key={j}>
              {media(item?.beforeTopic)}
              {item.topic ? <Text style={s.readParagraph}>{item.topic}</Text> : null}
              {media(item?.afterTopic)}
              {item.support?.length ? (
                <Text style={[s.readParagraph, s.readSupport]}>{item.support.join(" ")}</Text>
              ) : null}
              {media(item?.afterSupport)}
              {item.closing ? <Text style={s.readParagraph}>{item.closing}</Text> : null}
              {media(item?.afterClosing)}
            </View>
          ))}
          {media(conclusion?.beforeRestate)}
          {conclusion.restate ? <Text style={s.readParagraph}>{conclusion.restate}</Text> : null}
          {media(conclusion?.afterRestate)}
          {conclusion.whyItMatters ? <Text style={s.readParagraph}>{conclusion.whyItMatters}</Text> : null}
          {media(conclusion?.afterWhyItMatters)}
          {conclusion.closing ? (
            <Text style={[s.readParagraph, s.readClosing]}>{conclusion.closing}</Text>
          ) : null}
          {media(conclusion?.afterClosing)}
        </View>
      );
    }
    default:
      return "text" in b ? (
        <Text key={i} style={s.readParagraph}>
          {b.text}
        </Text>
      ) : null;
  }
}

