import { FlatList, Modal, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useBibleTheme, type BibleTheme } from "@/lib/bible-theme";

export const BIBLE_VERSIONS = [
  { id: "ASV", label: "ASV", name: "American Standard Version" },
  { id: "WEB", label: "WEB", name: "World English Bible" },
  { id: "NET", label: "NET", name: "NET Bible" },
  { id: "KJV", label: "KJV", name: "King James Version" },
] as const;

export type BibleVersionId = (typeof BIBLE_VERSIONS)[number]["id"];

type Props = {
  visible: boolean;
  version: BibleVersionId;
  onSelect: (version: BibleVersionId) => void;
  onClose: () => void;
};

export default function VersionSheet({ visible, version, onSelect, onClose }: Props) {
  const theme = useBibleTheme();
  const s = createStyles(theme);

  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <TouchableOpacity style={s.overlay} activeOpacity={1} onPress={onClose}>
        <TouchableOpacity activeOpacity={1} style={s.sheet} onPress={() => {}}>
          <View style={s.grabber} />
          <View style={s.titleRow}>
            <Text style={s.title}>Translation</Text>
            <TouchableOpacity
              onPress={onClose}
              style={s.closeBtn}
              accessibilityRole="button"
              accessibilityLabel="Close"
            >
              <Ionicons name="close" size={20} color={theme.textMuted} />
            </TouchableOpacity>
          </View>
          <FlatList
            data={BIBLE_VERSIONS}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => {
              const active = item.id === version;
              return (
                <TouchableOpacity
                  style={[s.item, active && s.itemActive]}
                  onPress={() => {
                    onSelect(item.id as BibleVersionId);
                    onClose();
                  }}
                  accessibilityRole="button"
                  accessibilityLabel={`Use ${item.name}`}
                >
                  <View style={s.itemBody}>
                    <Text style={[s.itemLabel, active && s.itemLabelActive]}>
                      {item.label}
                    </Text>
                    <Text style={s.itemName}>{item.name}</Text>
                  </View>
                  {active ? (
                    <Ionicons name="checkmark-circle" size={22} color={theme.accent} />
                  ) : (
                    <View style={s.itemSpacer} />
                  )}
                </TouchableOpacity>
              );
            }}
            contentContainerStyle={s.list}
          />
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

function createStyles(theme: BibleTheme) {
  return StyleSheet.create({
    overlay: {
      flex: 1,
      backgroundColor: "rgba(0,0,0,0.5)",
      justifyContent: "flex-end",
    },
    sheet: {
      maxHeight: "62%",
      backgroundColor: theme.cardBg,
      borderTopLeftRadius: 24,
      borderTopRightRadius: 24,
      paddingTop: 10,
      paddingBottom: 30,
    },
    grabber: {
      alignSelf: "center",
      width: 40,
      height: 4,
      borderRadius: 2,
      backgroundColor: theme.borderStrong,
      marginBottom: 8,
    },
    titleRow: {
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between",
      paddingHorizontal: 20,
      marginBottom: 6,
    },
    title: {
      fontWeight: "700",
      fontSize: 22,
      color: theme.text,
    },
    closeBtn: {
      padding: 6,
    },
    list: {
      paddingBottom: 10,
    },
    item: {
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "space-between",
      paddingHorizontal: 20,
      paddingVertical: 14,
      borderBottomWidth: StyleSheet.hairlineWidth,
      borderBottomColor: theme.border,
    },
    itemActive: {
      backgroundColor: theme.accentSoft,
    },
    itemBody: {
      flex: 1,
      marginRight: 12,
    },
    itemLabel: {
      fontWeight: "700",
      fontSize: 17,
      color: theme.text,
    },
    itemLabelActive: {
      color: theme.accent,
    },
    itemName: {
      fontSize: 13,
      color: theme.textMuted,
      marginTop: 2,
    },
    itemSpacer: {
      width: 22,
      height: 22,
    },
  });
}
