import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  FlatList,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  Share,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
  type ViewToken,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import * as Clipboard from "expo-clipboard";
import { useSQLiteContext } from "expo-sqlite";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { fonts } from "@/constants/fonts";
import { getVerses, type VerseRow } from "@/lib/bible-queries";
import { useBibleTheme, type BibleTheme } from "@/lib/bible-theme";
import {
  READER_FONTS,
  type ReaderFontKey,
  type ReaderLayoutKey,
  type ReaderThemeKey,
} from "@/lib/reader-settings";
import DisplaySheet from "@/components/bible/DisplaySheet";

type Props = {
  version: string;
  versionLabel: string;
  bookNumber: number;
  bookName: string;
  chapter: number;
  totalChapters: number;
  fontSize: number;
  fontFamily: string;
  themePref: ReaderThemeKey;
  layout: ReaderLayoutKey;
  onLayoutChange: (layout: ReaderLayoutKey) => void;
  onFontSizeChange: (size: number) => void;
  onFontFamilyChange: (family: ReaderFontKey) => void;
  onFontWeightChange: (family: string) => void;
  onThemeChange: (theme: ReaderThemeKey) => void;
  onChapterChange: (chapter: number) => void;
  onOpenPicker: () => void;
  onOpenVersion: () => void;
  onSearch: () => void;
  highlightedVerses?: Map<number, string> | Set<number>;
  /** Verse to scroll to and select when the passage opens (VOTD deep link). */
  targetVerse?: number | null;
  onHighlight: (verse: number, color: string) => void;
  onRemoveHighlight: (verse: number) => void;
  bookmarkedVerses?: Map<number, { id: number; note: string }>;
  onToggleBookmark: (verse: number) => void;
  onSaveNote: (verse: number, note: string) => void;
  onOpenBookmarks: () => void;
};

export const HIGHLIGHT_COLORS = [
  { id: "#FFD700", label: "Gold" },
  { id: "#FF6B6B", label: "Red" },
  { id: "#4ECDC4", label: "Teal" },
  { id: "#A78BFA", label: "Purple" },
  { id: "#34D399", label: "Green" },
  { id: "#FB923C", label: "Orange" },
];

function hexToRgba(hex: string, alpha: number): string {
  let h = hex.replace("#", "");
  if (h.length === 3) {
    h = h
      .split("")
      .map((c) => c + c)
      .join("");
  }
  const num = parseInt(h, 16);
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r},${g},${b},${alpha})`;
}

function highlightFor(
  highlighted: Map<number, string> | Set<number>,
  verse: number,
  theme: BibleTheme,
): string | undefined {
  if (highlighted instanceof Map) {
    const color = highlighted.get(verse);
    if (color) return hexToRgba(color, theme.isDark ? 0.45 : 0.4);
  }
  if (highlighted.has(verse)) return theme.highlightBg;
  return undefined;
}

function referenceOf(bookName: string, verse: VerseRow, versionLabel: string) {
  return `${bookName} ${verse.verse} (${versionLabel})`;
}

export default function VerseReader({
  version,
  versionLabel,
  bookNumber,
  bookName,
  chapter,
  totalChapters,
  fontSize,
  fontFamily,
  themePref,
  layout,
  onLayoutChange,
  onFontSizeChange,
  onFontFamilyChange,
  onFontWeightChange,
  onThemeChange,
  onChapterChange,
  onOpenPicker,
  onOpenVersion,
  onSearch,
  highlightedVerses = new Map(),
  targetVerse = null,
  onHighlight,
  onRemoveHighlight,
  bookmarkedVerses = new Map(),
  onToggleBookmark,
  onSaveNote,
  onOpenBookmarks,
}: Props) {
  const db = useSQLiteContext();
  const theme = useBibleTheme();
  const insets = useSafeAreaInsets();
  const passageKey = `${bookNumber}:${chapter}`;
  const [selectedState, setSelectedState] = useState<{
    key: string;
    verse: number;
  } | null>(null);
  const [showDisplay, setShowDisplay] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [noteVerse, setNoteVerse] = useState<number | null>(null);
  const [noteText, setNoteText] = useState("");

  // Selection is scoped to the passage — moving chapter drops it naturally.
  const selected =
    selectedState && selectedState.key === passageKey ? selectedState.verse : null;
  const selectVerse = (verse: number | null) =>
    setSelectedState(
      verse == null ? null : { key: passageKey, verse },
    );
  const toggleVerse = (verse: number) =>
    setSelectedState((prev) =>
      prev && prev.key === passageKey && prev.verse === verse
        ? null
        : { key: passageKey, verse },
    );

  const verses = useMemo(
    () => getVerses(db, version, bookNumber, chapter),
    [db, version, bookNumber, chapter],
  );

  const activeFont =
    READER_FONTS.find((f) => f.weights.some((w) => w.family === fontFamily)) ??
    READER_FONTS[0];

  const currentColor =
    selected != null && highlightedVerses instanceof Map
      ? highlightedVerses.get(selected)
      : undefined;

  const currentBookmark =
    selected != null ? bookmarkedVerses.get(selected) : undefined;

  const verseBg = (verse: number) => {
    // A saved highlight always wins over the transient selection tint, so the
    // colour stays visible while the verse is selected (and after recoloring).
    const highlighted = highlightFor(highlightedVerses, verse, theme);
    if (highlighted) return highlighted;
    if (selected === verse) return theme.accentSoft;
    return undefined;
  };

  // Paragraph grouping: verses.bible.db has no verse markers, so group greedily
  // until a block is long enough and ends a sentence (cap keeps psalms sane).
  const paragraphs = useMemo(() => {
    const groups: VerseRow[][] = [];
    let current: VerseRow[] = [];
    for (const v of verses) {
      current.push(v);
      const text = current.map((x) => x.text).join(" ");
      const longEnough = text.length >= 280;
      const endsSentence = /[.!?:"”']$/.test(text.trim());
      if (longEnough && endsSentence && current.length < 8) {
        groups.push(current);
        current = [];
      }
    }
    if (current.length) groups.push(current);
    return groups;
  }, [verses]);

  // Focus mode: one verse per full-width page; the pager tracks the focused
  // verse so the counter stays right after swipes and passage changes.
  const [focusIndex, setFocusIndex] = useState(0);
  const [pageWidth, setPageWidth] = useState(0);
  const focusListRef = useRef<FlatList<VerseRow>>(null);
  const listRef = useRef<FlatList<any>>(null);
  const [viewabilityConfig] = useState({ itemVisiblePercentThreshold: 60 });

  const handleViewableItemsChanged = useCallback(
    ({ viewableItems }: { viewableItems: ViewToken[] }) => {
      const first = viewableItems[0];
      if (first?.index != null) setFocusIndex(first.index);
    },
    [],
  );

  const [appliedPassageKey, setAppliedPassageKey] = useState(passageKey);
  if (appliedPassageKey !== passageKey) {
    // Render-phase adjustment: moving chapter remounts the pager (key) and
    // clamps the index so stale positions never point past the new passage.
    setAppliedPassageKey(passageKey);
    setFocusIndex(0);
  }

  const focusTo = (index: number) => {
    if (index < 0 || index >= verses.length) return;
    focusListRef.current?.scrollToIndex({ index, animated: true });
    setFocusIndex(index);
  };

  const visibleFocusIndex =
    focusIndex >= 0 && focusIndex < verses.length ? focusIndex : 0;
  const focusFontSize = Math.min(fontSize + 6, 34);

  // Deep links (Verse of the Day) ask for a specific verse: scroll to it and
  // select it so the reader lands on the exact line, not just the chapter.
  const appliedTargetRef = useRef<string | null>(null);
  useEffect(() => {
    if (targetVerse == null) {
      appliedTargetRef.current = null;
      return;
    }
    const targetKey = `${passageKey}:${targetVerse}`;
    if (appliedTargetRef.current === targetKey) return;
    const index = verses.findIndex((v) => v.verse === targetVerse);
    if (index < 0) return;
    appliedTargetRef.current = targetKey;
    const timer = setTimeout(() => {
      selectVerse(targetVerse);
      if (layout === "focus") {
        focusListRef.current?.scrollToIndex({ index, animated: true });
        setFocusIndex(index);
        return;
      }
      const scrollIndex =
        layout === "paragraph"
          ? paragraphs.findIndex((g) => g.some((v) => v.verse === targetVerse))
          : index;
      if (scrollIndex < 0) return;
      listRef.current?.scrollToIndex({
        index: scrollIndex,
        animated: true,
        viewPosition: 0.3,
      });
    }, 150);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [passageKey, targetVerse, verses, paragraphs, layout]);

  const handleScrollToIndexFailed = useCallback(
    (info: { index: number; averageItemLength: number }) => {
      listRef.current?.scrollToOffset({
        offset: info.averageItemLength * info.index,
        animated: false,
      });
      setTimeout(() => {
        listRef.current?.scrollToIndex({
          index: info.index,
          animated: true,
          viewPosition: 0.3,
        });
      }, 100);
    },
    [],
  );

  useEffect(() => {
    return () => {
      if (toastTimer.current) clearTimeout(toastTimer.current);
    };
  }, []);

  const flashToast = (message: string) => {
    setToast(message);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 1800);
  };

  const verseRef = (verse: number) => verses.find((v) => v.verse === verse);

  const handleCopy = async (verse: number) => {
    const v = verseRef(verse);
    if (!v) return;
    await Clipboard.setStringAsync(
      `"${v.text}"\n— ${referenceOf(bookName, v, versionLabel)}`,
    );
    flashToast("Copied to clipboard");
  };

  const handleShare = async (verse: number) => {
    const v = verseRef(verse);
    if (!v) return;
    try {
      await Share.share({
        message: `"${v.text}"\n— ${referenceOf(bookName, v, versionLabel)}`,
      });
    } catch {
      // user dismissed the share sheet
    }
  };

  const goPrev = () => chapter > 1 && onChapterChange(chapter - 1);
  const goNext = () => chapter < totalChapters && onChapterChange(chapter + 1);

  const s = createStyles(theme);

  const chapterHeader = (
    <View style={s.chapterHead}>
      <Text style={s.chapterTitle}>{bookName}</Text>
      <Text style={s.chapterMeta}>
        Chapter {chapter} · {versionLabel}
      </Text>
      <View style={s.chapterRule} />
    </View>
  );

  // Signature of the actual highlight contents (not just the count) so
  // recoloring an existing verse re-renders the rows.
  const highlightSignature = useMemo(() => {
    if (highlightedVerses instanceof Map) {
      return Array.from(highlightedVerses.entries())
        .map(([v, c]) => `${v}:${c}`)
        .join(",");
    }
    return Array.from(highlightedVerses).join(",");
  }, [highlightedVerses]);

  const listExtraData = `${selected}-${theme.isDark}-${highlightSignature}-${fontSize}-${fontFamily}-${layout}`;

  return (
    <View style={s.container}>
      <View style={s.header}>
        <TouchableOpacity
          onPress={onOpenPicker}
          style={s.headerPill}
          accessibilityRole="button"
          accessibilityLabel="Choose book and chapter"
        >
          <Text
            style={s.headerPillText}
            numberOfLines={1}
            adjustsFontSizeToFit
            minimumFontScale={0.75}
          >
            {bookName} {chapter}
          </Text>
          <Ionicons name="chevron-down" size={14} color={theme.accent} />
        </TouchableOpacity>
        <View style={s.headerRight}>
          <TouchableOpacity
            onPress={onOpenBookmarks}
            style={s.headerIcon}
            accessibilityRole="button"
            accessibilityLabel="Bookmarks and notes"
          >
            <Ionicons name="bookmarks-outline" size={19} color={theme.text} />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={onSearch}
            style={s.headerIcon}
            accessibilityRole="button"
            accessibilityLabel="Search scripture"
          >
            <Ionicons name="search" size={19} color={theme.text} />
          </TouchableOpacity>
          <TouchableOpacity
            onPress={onOpenVersion}
            style={s.headerIcon}
            accessibilityRole="button"
            accessibilityLabel="Change translation"
          >
            <Text style={s.headerVersion}>{versionLabel}</Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => setShowDisplay(true)}
            style={s.headerIcon}
            accessibilityRole="button"
            accessibilityLabel="Display settings"
          >
            <Text style={s.headerAa}>Aa</Text>
          </TouchableOpacity>
        </View>
      </View>

      <View style={s.progressTrack}>
        <View style={[s.progressFill, { flex: Math.max(chapter, 0) }]} />
        <View style={{ flex: Math.max(totalChapters - chapter, 0) }} />
      </View>

      {layout === "focus" ? (
        <FlatList
          ref={focusListRef}
          data={verses}
          keyExtractor={(item) => String(item.verse)}
          extraData={listExtraData}
          key={passageKey}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          onLayout={(e) => setPageWidth(e.nativeEvent.layout.width)}
          onViewableItemsChanged={handleViewableItemsChanged}
          viewabilityConfig={viewabilityConfig}
          getItemLayout={(_, index) => ({
            length: pageWidth,
            offset: pageWidth * index,
            index,
          })}
          renderItem={({ item }) => {
            const bg = verseBg(item.verse);
            return (
              <View style={[s.focusPage, { width: pageWidth || undefined }]}>
                <TouchableOpacity
                  activeOpacity={0.8}
                  onPress={() => toggleVerse(item.verse)}
                  onLongPress={() => selectVerse(item.verse)}
                  style={[s.focusVerse, bg ? { backgroundColor: bg } : null]}
                >
                  <Text style={s.focusNum}>{item.verse}</Text>
                  <Text
                    style={[
                      s.focusText,
                      {
                        fontSize: focusFontSize,
                        fontFamily,
                        lineHeight: Math.round(focusFontSize * 1.55),
                      },
                    ]}
                  >
                    {item.text}
                  </Text>
                </TouchableOpacity>
              </View>
            );
          }}
        />
      ) : layout === "paragraph" ? (
        <FlatList<VerseRow[]>
          ref={listRef}
          data={paragraphs}
          keyExtractor={(items) => String(items[0]?.verse ?? 0)}
          extraData={listExtraData}
          onScrollToIndexFailed={handleScrollToIndexFailed}
          contentContainerStyle={s.content}
          ListHeaderComponent={chapterHeader}
          renderItem={({ item: group }) => {
            const groupText = group.map((v) => v.text).join(" ");
            const groupBg = group.some((v) => selected === v.verse)
              ? theme.accentSoft
              : undefined;
            const firstVerse = group[0]?.verse;
            return (
              <TouchableOpacity
                activeOpacity={0.65}
                onPress={() => firstVerse != null && toggleVerse(firstVerse)}
                onLongPress={() =>
                  firstVerse != null && selectVerse(firstVerse)
                }
                style={[
                  s.paraBlock,
                  groupBg ? { backgroundColor: groupBg } : null,
                ]}
              >
                <Text
                  style={[
                    s.paraText,
                    {
                      fontSize,
                      fontFamily,
                      lineHeight: Math.round(fontSize * 1.7),
                    },
                  ]}
                >
                  <Text style={[s.paraNum, { fontSize: fontSize - 6 }]}>
                    {firstVerse}{" "}
                  </Text>
                  {groupText}
                </Text>
              </TouchableOpacity>
            );
          }}
        />
      ) : layout === "poetry" ? (
        <FlatList<VerseRow>
          ref={listRef}
          data={verses}
          keyExtractor={(item) => String(item.verse)}
          extraData={listExtraData}
          onScrollToIndexFailed={handleScrollToIndexFailed}
          contentContainerStyle={s.content}
          ListHeaderComponent={chapterHeader}
          renderItem={({ item }) => {
            const bg = verseBg(item.verse);
            // Short lines or lines ending in punctuation read as poetic
            // half-lines — indent the continuation like a printed psalm.
            const indented = item.text.length < 90 || /[:,;]$/.test(item.text);
            return (
              <TouchableOpacity
                activeOpacity={0.65}
                onPress={() => toggleVerse(item.verse)}
                onLongPress={() => selectVerse(item.verse)}
                style={[s.poetryRow, bg ? { backgroundColor: bg } : null]}
              >
                <Text
                  style={[
                    s.poetryText,
                    indented && s.poetryIndent,
                    {
                      fontSize,
                      fontFamily,
                      lineHeight: Math.round(fontSize * 1.8),
                    },
                  ]}
                >
                  <Text style={[s.poetryNum, { fontSize: fontSize - 6 }]}>
                    {item.verse}{" "}
                  </Text>
                  {item.text}
                </Text>
              </TouchableOpacity>
            );
          }}
        />
      ) : (
        <FlatList<VerseRow>
          ref={listRef}
          data={verses}
          keyExtractor={(item) => String(item.verse)}
          extraData={listExtraData}
          onScrollToIndexFailed={handleScrollToIndexFailed}
          contentContainerStyle={s.content}
          ListHeaderComponent={chapterHeader}
          renderItem={({ item }) => {
            const bg = verseBg(item.verse);
            return (
              <TouchableOpacity
                activeOpacity={0.65}
                onPress={() => toggleVerse(item.verse)}
                onLongPress={() => selectVerse(item.verse)}
                style={[s.verseRow, bg ? { backgroundColor: bg } : null]}
              >
                <Text
                  style={[
                    s.verseText,
                    {
                      fontSize,
                      fontFamily,
                      lineHeight: Math.round(fontSize * 1.65),
                    },
                  ]}
                >
                  <Text style={[s.verseNum, { fontSize: fontSize - 6 }]}>
                    {item.verse}
                  </Text>
                  {item.text}
                </Text>
              </TouchableOpacity>
            );
          }}
        />
      )}

      {layout === "focus" && verses.length > 1 ? (
        <View style={s.focusNav}>
          <TouchableOpacity
            onPress={() => focusTo(visibleFocusIndex - 1)}
            disabled={visibleFocusIndex <= 0}
            style={[s.focusNavBtn, visibleFocusIndex <= 0 && s.navBtnDisabled]}
            accessibilityRole="button"
            accessibilityLabel="Previous verse"
          >
            <Ionicons name="chevron-back" size={18} color={theme.accent} />
          </TouchableOpacity>
          <Text
            style={s.focusCounter}
            numberOfLines={1}
            adjustsFontSizeToFit
            minimumFontScale={0.75}
          >
            {visibleFocusIndex + 1} / {verses.length}
          </Text>
          <TouchableOpacity
            onPress={() => focusTo(visibleFocusIndex + 1)}
            disabled={visibleFocusIndex >= verses.length - 1}
            style={[
              s.focusNavBtn,
              visibleFocusIndex >= verses.length - 1 && s.navBtnDisabled,
            ]}
            accessibilityRole="button"
            accessibilityLabel="Next verse"
          >
            <Ionicons name="chevron-forward" size={18} color={theme.accent} />
          </TouchableOpacity>
        </View>
      ) : null}

      {toast ? (
        <View style={s.toast} pointerEvents="none">
          <Text style={s.toastText}>{toast}</Text>
        </View>
      ) : null}

      {selected != null ? (
        <View style={s.actionBar}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={s.actionScroll}
          >
            {HIGHLIGHT_COLORS.map((c) => (
              <TouchableOpacity
                key={c.id}
                style={[
                  s.swatch,
                  { backgroundColor: c.id },
                  currentColor === c.id && s.swatchActive,
                ]}
                onPress={() => onHighlight(selected, c.id)}
                accessibilityRole="button"
                accessibilityLabel={`Highlight verse in ${c.label}`}
              />
            ))}
            <View style={s.actionDivider} />
            <TouchableOpacity
              style={s.actionBtn}
              onPress={() => handleCopy(selected)}
              accessibilityRole="button"
              accessibilityLabel="Copy verse"
            >
              <Ionicons name="copy-outline" size={18} color={theme.text} />
              <Text style={s.actionBtnText}>Copy</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={s.actionBtn}
              onPress={() => handleShare(selected)}
              accessibilityRole="button"
              accessibilityLabel="Share verse"
            >
              <Ionicons name="share-outline" size={18} color={theme.text} />
              <Text style={s.actionBtnText}>Share</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={s.actionBtn}
              onPress={() => onToggleBookmark(selected)}
              accessibilityRole="button"
              accessibilityLabel={
                currentBookmark ? "Remove bookmark" : "Bookmark verse"
              }
            >
              <Ionicons
                name={currentBookmark ? "bookmark" : "bookmark-outline"}
                size={18}
                color={currentBookmark ? theme.accent : theme.text}
              />
              <Text
                style={[
                  s.actionBtnText,
                  currentBookmark ? { color: theme.accent } : null,
                ]}
              >
                {currentBookmark ? "Saved" : "Save"}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={s.actionBtn}
              onPress={() => {
                setNoteText(currentBookmark?.note ?? "");
                setNoteVerse(selected);
              }}
              accessibilityRole="button"
              accessibilityLabel="Add or edit note"
            >
              <Ionicons name="create-outline" size={18} color={theme.text} />
              <Text style={s.actionBtnText}>Note</Text>
            </TouchableOpacity>
            {currentColor ? (
              <TouchableOpacity
                style={s.actionBtn}
                onPress={() => {
                  onRemoveHighlight(selected);
                  selectVerse(null);
                }}
                accessibilityRole="button"
                accessibilityLabel="Remove highlight"
              >
                <Ionicons
                  name="trash-outline"
                  size={18}
                  color={theme.isDark ? "#FF8A8A" : "#D64545"}
                />
                <Text style={[s.actionBtnText, { color: theme.isDark ? "#FF8A8A" : "#D64545" }]}>
                  Clear
                </Text>
              </TouchableOpacity>
            ) : null}
            <TouchableOpacity
              style={s.actionBtn}
              onPress={() => selectVerse(null)}
              accessibilityRole="button"
              accessibilityLabel="Dismiss verse actions"
            >
              <Ionicons name="close" size={18} color={theme.textMuted} />
            </TouchableOpacity>
          </ScrollView>
        </View>
      ) : null}

      <View style={s.navBar}>
        <TouchableOpacity
          onPress={goPrev}
          disabled={chapter <= 1}
          style={[s.navBtn, chapter <= 1 && s.navBtnDisabled]}
          accessibilityRole="button"
          accessibilityLabel="Previous chapter"
        >
          <Ionicons name="chevron-back" size={20} color={theme.accent} />
        </TouchableOpacity>
        <TouchableOpacity
          onPress={onOpenPicker}
          style={s.navCenter}
          accessibilityRole="button"
          accessibilityLabel="Choose book and chapter"
        >
          <Ionicons name="book-outline" size={16} color={theme.accent} />
          <Text
            style={s.navCenterText}
            numberOfLines={1}
            adjustsFontSizeToFit
            minimumFontScale={0.75}
          >
            {chapter} / {totalChapters}
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={goNext}
          disabled={chapter >= totalChapters}
          style={[s.navBtn, chapter >= totalChapters && s.navBtnDisabled]}
          accessibilityRole="button"
          accessibilityLabel="Next chapter"
        >
          <Ionicons name="chevron-forward" size={20} color={theme.accent} />
        </TouchableOpacity>
      </View>

      <DisplaySheet
        visible={showDisplay}
        onClose={() => setShowDisplay(false)}
        fontSize={fontSize}
        onFontSizeChange={onFontSizeChange}
        fontKey={activeFont.key}
        onFontFamilyChange={onFontFamilyChange}
        fontWeight={fontFamily}
        onFontWeightChange={onFontWeightChange}
        themePref={themePref}
        onThemeChange={onThemeChange}
        layout={layout}
        onLayoutChange={onLayoutChange}
      />

      <Modal
        visible={noteVerse != null}
        animationType="slide"
        statusBarTranslucent
        onRequestClose={() => setNoteVerse(null)}
      >
        <View style={[s.noteScreen, { paddingTop: insets.top }]}>
          <View style={s.noteHeader}>
            <TouchableOpacity
              onPress={() => setNoteVerse(null)}
              style={s.noteCloseBtn}
              accessibilityRole="button"
              accessibilityLabel="Close note"
            >
              <Ionicons name="close" size={22} color={theme.text} />
            </TouchableOpacity>
            <View style={s.noteHeaderBody}>
              <Text style={s.noteHeaderTitle}>Note</Text>
              <Text style={s.noteHeaderSub} numberOfLines={1}>
                {bookName} {chapter}:{noteVerse}
              </Text>
            </View>
            <TouchableOpacity
              style={[s.noteSaveBtn, { backgroundColor: theme.text }]}
              onPress={() => {
                if (noteVerse != null) onSaveNote(noteVerse, noteText.trim());
                setNoteVerse(null);
                flashToast("Note saved");
              }}
              accessibilityRole="button"
              accessibilityLabel="Save note"
            >
              <Ionicons name="checkmark" size={18} color={theme.bg} />
              <Text style={[s.noteSaveText, { color: theme.bg }]}>Save</Text>
            </TouchableOpacity>
          </View>

          <KeyboardAvoidingView
            style={s.noteFlex}
            behavior={Platform.OS === "ios" ? "padding" : "height"}
          >
            <ScrollView
              style={s.noteFlex}
              contentContainerStyle={s.noteBody}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <TextInput
                style={s.noteInput}
                value={noteText}
                onChangeText={setNoteText}
                placeholder="Write your note about this verse…"
                placeholderTextColor={theme.textMuted}
                multiline
                autoFocus
                maxLength={1000}
                textAlignVertical="top"
              />
              <Text style={s.noteHint}>
                Saved with this verse — find it again in Bookmarks.
              </Text>
            </ScrollView>
          </KeyboardAvoidingView>
        </View>
      </Modal>
    </View>
  );
}

