import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useEffect, useState } from "react";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";
import { communityApi } from "@/services/community";

export const PRAYER_CATEGORIES = [
  "Healing",
  "Family",
  "Guidance",
  "Protection",
  "Provision & Finances",
  "Comfort & Grief",
  "Relationships & Marriage",
  "Children & Youth",
  "Career & Work",
  "Travel & Journey",
  "Salvation",
  "Spiritual Growth",
  "Thanksgiving",
  "Other",
] as const;

export type PrayerRequestLike = {
  id: string;
  title: string;
  description: string;
  author: string;
  category?: string;
  anonymous?: boolean;
  visibility?: "community" | "team";
  email?: string;
};

export default function PrayerRequestModal({
  editing,
  onClose,
  onSubmit,
}: {
  editing: PrayerRequestLike | null;
  onClose: () => void;
  onSubmit: () => void;
}) {
  const isEditing = !!editing;
  const [name, setName] = useState(editing?.author && !editing.anonymous ? editing.author : "");
  const [anonymous, setAnonymous] = useState(editing?.anonymous ?? false);
  const [category, setCategory] = useState(
    editing ? editing.category || "Other" : "Healing",
  );
  const [showCategoryPicker, setShowCategoryPicker] = useState(false);
  const [request, setRequest] = useState(editing?.description || "");
  const [visibility, setVisibility] = useState<"community" | "team">(
    editing?.visibility || "community",
  );
  const [email, setEmail] = useState(editing?.email || "");
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);
  const [sessionName, setSessionName] = useState("");
  const insets = useSafeAreaInsets();

  useEffect(() => {
    getSession().then((s) => {
      const n = s?.user?.name || "";
      setSessionName(n);
      if (!isEditing && !anonymous && n && !name) setName(n);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const clearError = (key: string) =>
    setErrors((prev) => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });

  const handleSubmit = async () => {
    const errs: Record<string, string> = {};
    if (!anonymous && !name.trim()) errs.name = "Please enter your name.";
    if (!request.trim()) errs.request = "Please share your prayer request.";
    if (email.trim() && !/^\S+@\S+\.\S+$/.test(email.trim()))
      errs.email = "Please enter a valid email.";
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;

    setSubmitting(true);
    try {
      const author = anonymous ? "Anonymous" : name.trim() || sessionName || "Anonymous";
      const payload: any = {
        text: request.trim(),
        title: category,
        description: request.trim(),
        author,
        category,
        anonymous,
        visibility,
        email: email.trim(),
      };
      if (isEditing) {
        payload._id = editing!.id;
        await communityApi.updateRequest(payload);
      } else {
        await communityApi.createRequest(payload);
      }
      setSuccess(true);
      onSubmit();
    } catch (err: any) {
      Alert.alert("Error", err?.message || "Failed to send. Please try again.");
    }
    setSubmitting(false);
  };

  const firstName = (!anonymous && name.trim().split(" ")[0]) || "friend";

  return (
    <Modal
      visible
      animationType="slide"
      presentationStyle="fullScreen"
      statusBarTranslucent
      onRequestClose={() => !submitting && onClose()}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.overlay}
      >
        <View style={styles.overlay}>
          <LinearGradient
            colors={["#f59e0b", "#fbbf24"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.flameBar}
          />

          {success ? (
            <ScrollView
              contentContainerStyle={styles.successWrap}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <View style={styles.successIcon}>
                <Ionicons name="flame" size={30} color="#f59e0b" />
              </View>
              <Text style={styles.successTitle}>Your request is received</Text>
              <Text style={styles.successText}>
                Thank you, <Text style={styles.successName}>{firstName}</Text>. Your{" "}
                <Text style={styles.successName}>{category.toLowerCase()}</Text> request has been
                shared with{" "}
                <Text style={styles.successName}>
                  {visibility === "team" ? "our prayer team" : "the community"}
                </Text>
                , and our prayer team will be standing with you.
              </Text>
              <TouchableOpacity style={styles.doneBtn} onPress={onClose} activeOpacity={0.85}>
                <Text style={styles.doneBtnText}>Done</Text>
              </TouchableOpacity>
            </ScrollView>
          ) : (
            <>
              <View style={[styles.header, { paddingTop: insets.top + 18 }]}>
                <View style={styles.headIcon}>
                  <Ionicons name="flame" size={22} color="#f59e0b" />
                </View>
                <View style={styles.headerTextWrap}>
                  <Text style={styles.title}>
                    {isEditing ? "Edit Prayer Request" : "Ask for a Prayer"}
                  </Text>
                  <Text style={styles.sub}>
                    Share your request — our community will stand with you in prayer.
                  </Text>
                </View>
                <TouchableOpacity style={styles.closeBtn} onPress={onClose} disabled={submitting}>
                  <Ionicons name="close" size={20} color={colors.muted} />
                </TouchableOpacity>
              </View>

              <ScrollView
                style={styles.scroll}
                contentContainerStyle={styles.form}
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode="none"
                showsVerticalScrollIndicator={false}
              >
                {/* Full name */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Full name {anonymous ? <Text style={styles.opt}>(optional — hidden)</Text> : <Text style={styles.req}>*</Text>}
                  </Text>
                  <TextInput
                    style={[styles.input, errors.name && styles.inputError]}
                    placeholder={anonymous ? "Optional — hidden from community" : "Your name"}
                    placeholderTextColor="#a3aebc"
                    value={name}
                    editable={!anonymous}
                    onChangeText={(t) => {
                      setName(t);
                      clearError("name");
                    }}
                  />
                  {errors.name ? (
                    <View style={styles.errorRow}>
                      <Text style={styles.errorMark}>!</Text>
                      <Text style={styles.fieldError}>{errors.name}</Text>
                    </View>
                  ) : null}
                </View>

                {/* Anonymous toggle */}
                <View style={styles.toggleRow}>
                  <Switch
                    value={anonymous}
                    onValueChange={(v) => {
                      setAnonymous(v);
                      clearError("name");
                    }}
                    trackColor={{ false: "rgba(29,42,77,0.2)", true: colors.gold }}
                    thumbColor="#ffffff"
                  />
                  <Text style={styles.toggleText}>Post anonymously</Text>
                </View>

                {/* Category */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Category</Text>
                  <TouchableOpacity
                    style={styles.dropdownTrigger}
                    onPress={() => setShowCategoryPicker(true)}
                    activeOpacity={0.8}
                  >
                    <Text
                      style={
                        category
                          ? styles.dropdownText
                          : styles.dropdownPlaceholder
                      }
                    >
                      {category || "Select a category"}
                    </Text>
                    <Ionicons
                      name="chevron-down"
                      size={18}
                      color={colors.muted}
                    />
                  </TouchableOpacity>
                </View>

                {/* Request text */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Your prayer request <Text style={styles.req}>*</Text>
                  </Text>
                  <TextInput
                    style={[styles.input, styles.textArea, errors.request && styles.inputError]}
                    placeholder="Share what's on your heart…"
                    placeholderTextColor="#a3aebc"
                    value={request}
                    multiline
                    numberOfLines={4}
                    textAlignVertical="top"
                    onChangeText={(t) => {
                      setRequest(t);
                      clearError("request");
                    }}
                  />
                  {errors.request ? (
                    <View style={styles.errorRow}>
                      <Text style={styles.errorMark}>!</Text>
                      <Text style={styles.fieldError}>{errors.request}</Text>
                    </View>
                  ) : null}
                </View>

                {/* Visibility */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Who can see this?</Text>
                  <View style={styles.segment}>
                    {(
                      [
                        { key: "community", label: "Community" },
                        { key: "team", label: "Prayer team only" },
                      ] as const
                    ).map((seg) => {
                      const active = visibility === seg.key;
                      return (
                        <TouchableOpacity
                          key={seg.key}
                          style={[styles.seg, active && styles.segActive]}
                          onPress={() => setVisibility(seg.key)}
                          activeOpacity={0.85}
                        >
                          <Text style={[styles.segText, active && styles.segTextActive]}>
                            {seg.label}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                </View>

                {/* Email */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Email <Text style={styles.opt}>(optional · for follow-up)</Text>
                  </Text>
                  <TextInput
                    style={[styles.input, errors.email && styles.inputError]}
                    placeholder="you@example.com"
                    placeholderTextColor="#a3aebc"
                    value={email}
                    autoCapitalize="none"
                    keyboardType="email-address"
                    onChangeText={(t) => {
                      setEmail(t);
                      clearError("email");
                    }}
                  />
                  {errors.email ? (
                    <View style={styles.errorRow}>
                      <Text style={styles.errorMark}>!</Text>
                      <Text style={styles.fieldError}>{errors.email}</Text>
                    </View>
                  ) : null}
                </View>

                {/* Submit */}
                <Text style={styles.verseNote}>
                  {"\u201CCast all your anxiety on him because he cares for you.\u201D"}
                  <Text style={styles.verseRef}> {"1 PETER 5:7"}</Text>
                </Text>
              </ScrollView>

              <View
                style={[styles.submitBar, { paddingBottom: Math.max(insets.bottom, 16) + 4 }]}
              >
                <TouchableOpacity
                  style={styles.submit}
                  onPress={handleSubmit}
                  disabled={submitting}
                  activeOpacity={0.85}
                >
                  {submitting ? (
                    <ActivityIndicator size="small" color={colors.forestDark} />
                  ) : (
                    <>
                      <Ionicons name="flame" size={16} color={colors.forestDark} />
                      <Text style={styles.submitText}>
                        {isEditing ? "Save Changes" : "Send Prayer Request"}
                      </Text>
                    </>
                  )}
                </TouchableOpacity>
              </View>

              <Modal
                visible={showCategoryPicker}
                transparent
                animationType="fade"
                onRequestClose={() => setShowCategoryPicker(false)}
              >
                <TouchableOpacity
                  style={styles.pickerOverlay}
                  activeOpacity={1}
                  onPress={() => setShowCategoryPicker(false)}
                >
                  <View style={styles.pickerSheet}>
                    <View style={styles.pickerSheetHead}>
                      <Text style={styles.pickerSheetTitle}>Choose a category</Text>
                      <TouchableOpacity
                        style={styles.pickerCloseBtn}
                        onPress={() => setShowCategoryPicker(false)}
                        hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                      >
                        <Ionicons name="close" size={18} color={colors.muted} />
                      </TouchableOpacity>
                    </View>
                    <ScrollView
                      style={styles.pickerList}
                      showsVerticalScrollIndicator={false}
                      keyboardShouldPersistTaps="handled"
                    >
                      {PRAYER_CATEGORIES.map((c) => {
                        const active = c === category;
                        return (
                          <TouchableOpacity
                            key={c}
                            style={[styles.pickerOption, active && styles.pickerOptionActive]}
                            onPress={() => {
                              setCategory(c);
                              setShowCategoryPicker(false);
                            }}
                            activeOpacity={0.7}
                          >
                            <Text
                              style={[
                                styles.pickerOptionText,
                                active && styles.pickerOptionTextActive,
                              ]}
                            >
                              {c}
                            </Text>
                            {active ? (
                              <Ionicons name="checkmark-circle" size={18} color="#f59e0b" />
                            ) : null}
                          </TouchableOpacity>
                        );
                      })}
                    </ScrollView>
                  </View>
                </TouchableOpacity>
              </Modal>
            </>
          )}
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

