  bg: string;
  cardBg: string;
  text: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentSoft: string;
  inputBg: string;
  highlightBg: string;
  navBg: string;
  navDisabled: string;
