import { Ionicons } from "@expo/vector-icons";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  BackHandler,
  KeyboardAvoidingView,
  Modal,
  Platform,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { router, useFocusEffect } from "expo-router";
import { colors } from "@/constants/colors";
import EmptyState from "@/components/EmptyState";
import GrowthChart from "@/components/GrowthChart";
import { API_BASE } from "@/services/config";
import { getSession, getRequestHeaders } from "@/services/auth";

type GrowthMonth = {
  label: string;
  users: number;
  families: number;
  downloads: number;
};

type ClubGrowth = {
  slug: string;
  name: string;
  color: string;
  members: number[];
};

type Stats = {
  members: {
    total: number;
    admins: number;
    newLast30Days: number;
    families: number;
  };
  growth: { months: GrowthMonth[]; clubs?: ClubGrowth[] };
};

type DashboardUser = {
  id: string;
  name: string;
  email: string;
  role: string;
  createdAt: string | null;
};

type StreakDetail = {
  user: { id: string; name: string; email: string; image: string | null };
  prayerStreak: number;
  prayerDayCount: number;
  prayerRecentDays: string[];
  readingStreak: number;
  readingDayCount: number;
  readingRecentDays: string[];
};

type RestoreSection = "prayer" | "reading";

type Access = "checking" | "allowed" | "denied";

async function apiGet<T>(path: string, signal?: AbortSignal): Promise<T> {
  const headers = await getRequestHeaders();
  const res = await fetch(`${API_BASE}${path}`, { headers, signal });
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json() as Promise<T>;
}

async function apiPost<T>(path: string, body: unknown): Promise<T> {
  const headers = await getRequestHeaders({ "Content-Type": "application/json" });
  const res = await fetch(`${API_BASE}${path}`, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const json = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new Error(json?.error || `Request failed: ${res.status}`);
  }
  return res.json() as Promise<T>;
}

function formatCount(value: number | undefined): string {
  if (value === undefined) return "—";
  if (value >= 1000) return `${Math.round(value / 100) / 10}k`;
  return String(value);
}

function formatShortDate(iso?: string | null): string {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  } catch {
    return "—";
  }
}

function ChartLegend({ items }: { items: { label: string; color: string; value: number | undefined }[] }) {
  return (
    <View style={styles.legendRow}>
      {items.map((item) => (
        <View key={item.label} style={styles.legendItem}>
          <View style={[styles.legendDot, { backgroundColor: item.color }]} />
          <Text style={styles.legendLabel}>{item.label}</Text>
          <Text style={styles.legendValue}>{formatCount(item.value)}</Text>
        </View>
      ))}
    </View>
  );
}

function RecentDays({ days }: { days: string[] }) {
  if (days.length === 0) return <Text style={styles.detailMuted}>None recorded</Text>;
  return (
    <View style={styles.dayRow}>
      {days.slice(0, 8).map((day) => (
        <View key={day} style={styles.dayChip}>
          <Text style={styles.dayChipText}>{formatShortDate(day)}</Text>
        </View>
      ))}
      {days.length > 8 && <Text style={styles.detailMuted}>+{days.length - 8} more</Text>}
    </View>
  );
}

export default function DashboardScreen() {
  useEffect(() => {
    const onBackPress = () => {
      router.back();
      return true;
    };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, []);

  const [access, setAccess] = useState<Access>("checking");
  const [stats, setStats] = useState<Stats | null>(null);
  const [statsError, setStatsError] = useState(false);
  const [statsLoading, setStatsLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [reloadToken, setReloadToken] = useState(0);
  const [chartWidth, setChartWidth] = useState(0);
  const [clubFilter, setClubFilter] = useState("all");

  const insets = useSafeAreaInsets();
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<DashboardUser[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState(false);

  const [selected, setSelected] = useState<DashboardUser | null>(null);
  const [detail, setDetail] = useState<StreakDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailError, setDetailError] = useState("");
  const [restoreSection, setRestoreSection] = useState<RestoreSection | null>(null);
  const [targetValue, setTargetValue] = useState("");
  const [restoreBusy, setRestoreBusy] = useState<RestoreSection | null>(null);
  const [restoreMsg, setRestoreMsg] = useState("");

  const loadStats = useCallback(async () => {
    setStatsLoading(true);
    setStatsError(false);
    try {
      const session = await getSession();
      if (session?.user?.role !== "admin") {
        setAccess("denied");
        return;
      }
      setAccess("allowed");
      const res = await apiGet<{ data: Stats }>("/api/admin/stats");
      setStats(res.data);
    } catch {
      setStatsError(true);
    } finally {
      setStatsLoading(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadStats();
    }, [loadStats]),
  );

  useEffect(() => {
    if (access !== "allowed") return;
    const q = query.trim();
    if (q.length < 2) return;

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      setSearching(true);
      setSearchError(false);
      try {
        const res = await apiGet<{ data: DashboardUser[] }>(
          `/api/admin/users?search=${encodeURIComponent(q)}`,
          controller.signal,
        );
        setUsers((res.data || []).slice(0, 50));
      } catch {
        if (!controller.signal.aborted) setSearchError(true);
      } finally {
        if (!controller.signal.aborted) setSearching(false);
      }
    }, 350);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, access, reloadToken]);

  const onRefresh = async () => {
    setRefreshing(true);
    await loadStats();
    setReloadToken((n) => n + 1);
    setRefreshing(false);
  };

  const closeMember = useCallback(() => {
    setSelected(null);
    setDetail(null);
    setDetailError("");
    setRestoreSection(null);
    setTargetValue("");
    setRestoreMsg("");
  }, []);

  const openMember = useCallback(async (user: DashboardUser) => {
    setSelected(user);
    setDetail(null);
    setDetailError("");
    setRestoreMsg("");
    setRestoreSection(null);
    setDetailLoading(true);
    try {
      const res = await apiGet<{ data: StreakDetail }>(
        `/api/admin/streaks?userId=${encodeURIComponent(user.id)}`,
      );
      setDetail(res.data);
    } catch {
      setDetailError("Couldn't load member details.");
    } finally {
      setDetailLoading(false);
    }
  }, []);

  const startRestore = (section: RestoreSection) => {
    setDetailError("");
    setRestoreMsg("");
    setRestoreSection(section);
    setTargetValue(
      String(section === "prayer" ? detail?.prayerStreak ?? 0 : detail?.readingStreak ?? 0),
    );
  };

  const confirmRestore = useCallback(async () => {
    if (!selected || !restoreSection) return;
    const target = Number(targetValue);
    if (!Number.isInteger(target) || target < 0 || target > 3650) {
      setDetailError("Enter a whole number between 0 and 3650.");
      return;
    }
    const section = restoreSection;
    setRestoreBusy(section);
    setDetailError("");
    setRestoreMsg("");
    try {
      await apiPost("/api/admin/streaks", {
        userId: selected.id,
        [section === "prayer" ? "prayerStreak" : "readingStreak"]: target,
      });
      setRestoreMsg(
        `${section === "prayer" ? "Prayer" : "Reading"} streak set to ${target} day${target === 1 ? "" : "s"}.`,
      );
      setRestoreSection(null);
      const res = await apiGet<{ data: StreakDetail }>(
        `/api/admin/streaks?userId=${encodeURIComponent(selected.id)}`,
      );
      setDetail(res.data);
    } catch (err) {
      setDetailError(err instanceof Error ? err.message : "Restore failed.");
    } finally {
      setRestoreBusy(null);
    }
  }, [selected, restoreSection, targetValue]);

  const checking = access === "checking" || (access === "allowed" && !stats && statsLoading && !statsError);
  const q = query.trim();
  const months = stats?.growth.months ?? [];
  const labels = months.map((month) => month.label);
  const lastOf = (values: number[] | undefined) =>
    values && values.length > 0 ? values[values.length - 1] : undefined;
  const growthClubs = stats?.growth.clubs ?? [];
  // Default to a club that has members so the first chart isn't a flat zero.
  const activeClub =
    growthClubs.find((club) => club.slug === clubFilter) ??
    growthClubs.find((club) => (lastOf(club.members) ?? 0) > 0) ??
    growthClubs[0] ??
    null;
  const memberSeries = activeClub?.members ?? months.map(() => 0);
  const measureChart = (event: { nativeEvent: { layout: { width: number } } }) =>
    setChartWidth(Math.round(event.nativeEvent.layout.width));

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.backBtn}>
            <Ionicons name="chevron-back" size={20} color={colors.darkGreen} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Dashboard</Text>
          <View style={{ width: 36 }} />
        </View>

        {checking ? (
          <View style={styles.loadingWrap}>
            <ActivityIndicator size="large" color={colors.forest} />
          </View>
        ) : access === "denied" ? (
          <EmptyState
            icon="lock-closed-outline"
            color={colors.gold}
            eyebrow="Restricted"
            title="Admins only"
            subtitle="This dashboard is available to administrators."
            actionLabel="Go back"
            onAction={() => router.back()}
          />
        ) : (
          <KeyboardAvoidingView
            style={{ flex: 1 }}
            behavior={Platform.OS === "ios" ? "padding" : "height"}
          >
          <ScrollView
            contentContainerStyle={styles.scroll}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
            keyboardDismissMode="none"
            automaticallyAdjustKeyboardInsets
            refreshControl={
              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.forest} />
            }
          >
            {statsError && !stats ? (
              <EmptyState
                compact
                icon="cloud-offline-outline"
                color={colors.warning}
                eyebrow="Offline"
                title="Couldn't load stats"
                subtitle="Pull down to try again."
              />
            ) : (
              <>
                <View style={styles.section}>
                  <View style={styles.sectionHead}>
                    <Text style={styles.sectionTitle}>App growth</Text>
                    <Text style={styles.sectionHint}>Last 12 months</Text>
                  </View>
                  <View style={styles.chartPanel}>
                    <View style={styles.chartHead}>
                      <View>
                        <Text style={styles.chartTitle}>Downloads</Text>
                        <Text style={styles.chartSubtitle}>Cumulative APK downloads</Text>
                      </View>
                      <Text style={styles.chartTotal}>
                        {formatCount(months[months.length - 1]?.downloads)}
                      </Text>
                    </View>
                    {months.length > 0 && (
                      <View style={styles.chartBody} onLayout={measureChart}>
                        <GrowthChart
                          labels={labels}
                          series={[
                            {
                              name: "Downloads",
                              color: colors.goldDark,
                              values: months.map((month) => month.downloads),
                            },
                          ]}
                          width={chartWidth}
                        />
                      </View>
                    )}
                    <ChartLegend
                      items={[
                        {
                          label: "Downloads",
                          color: colors.goldDark,
                          value: months[months.length - 1]?.downloads,
                        },
                      ]}
                    />
                  </View>
                </View>

                <View style={styles.section}>
                  <View style={styles.sectionHead}>
                    <Text style={styles.sectionTitle}>Organisation growth</Text>
                    <Text style={styles.sectionHint}>Last 12 months</Text>
                  </View>
                  <View style={styles.chartPanel}>
                    <View style={styles.chartHead}>
                      <View>
                        <Text style={styles.chartTitle}>Members</Text>
                        <Text style={styles.chartSubtitle}>Cumulative totals</Text>
                      </View>
                    </View>
                    {months.length > 0 && (
                      <View style={styles.chartBody} onLayout={measureChart}>
                        <GrowthChart
                          labels={labels}
                          series={[
                            {
                              name: "Members",
                              color: colors.forest,
                              values: months.map((month) => month.users),
                            },
                          ]}
                          width={chartWidth}
                        />
                      </View>
                    )}
                    <ChartLegend
                      items={[
                        {
                          label: "Members",
                          color: colors.forest,
                          value: months[months.length - 1]?.users,
                        },
                      ]}
                    />
                  </View>
                </View>

                <View style={styles.section}>
                  <View style={styles.sectionHead}>
                    <Text style={styles.sectionTitle}>Club growth</Text>
                    <Text style={styles.sectionHint}>Last 12 months</Text>
                  </View>
                  {growthClubs.length > 0 && (
                    <ScrollView
                      horizontal
                      showsHorizontalScrollIndicator={false}
                      contentContainerStyle={styles.clubChips}
                    >
                      {growthClubs.map((club) => {
                        const active = club.slug === activeClub?.slug;
                        return (
                          <TouchableOpacity
                            key={club.slug}
                            onPress={() => setClubFilter(club.slug)}
                            style={[styles.clubChip, active && styles.clubChipActive]}
                            activeOpacity={0.8}
                          >
                            {club.color ? (
                              <View
                                style={[styles.clubChipDot, { backgroundColor: club.color }]}
                              />
                            ) : null}
                            <Text
                              style={[styles.clubChipText, active && styles.clubChipTextActive]}
                            >
                              {club.name}
                            </Text>
                            <Text
                              style={[styles.clubChipCount, active && styles.clubChipCountActive]}
                            >
                              {formatCount(lastOf(club.members))}
                            </Text>
                          </TouchableOpacity>
                        );
                      })}
                    </ScrollView>
                  )}
                  {activeClub ? (
                    <View style={styles.chartPanel}>
                      <View style={styles.chartHead}>
                        <View>
                          <Text style={styles.chartTitle}>{activeClub.name} members</Text>
                          <Text style={styles.chartSubtitle}>
                            Cumulative {activeClub.name} members
                          </Text>
                        </View>
                        <Text style={styles.chartTotal}>{formatCount(lastOf(memberSeries))}</Text>
                      </View>
                      {months.length > 0 && (
                        <View style={styles.chartBody} onLayout={measureChart}>
                          <GrowthChart
                            labels={labels}
                            series={[
                              {
                                name: activeClub.name,
                                color: activeClub.color || colors.gold,
                                values: memberSeries,
                              },
                            ]}
                            width={chartWidth}
                          />
                        </View>
                      )}
                      <ChartLegend
                        items={[
                          {
                            label: activeClub.name,
                            color: activeClub.color || colors.gold,
                            value: lastOf(memberSeries),
                          },
                        ]}
                      />
                    </View>
                  ) : (
                    <Text style={styles.sectionHint}>No clubs in the catalogue yet.</Text>
                  )}
                </View>
              </>
            )}

            <View style={styles.section}>
              <View style={styles.sectionHead}>
                <Text style={styles.sectionTitle}>Find a member</Text>
                <Text style={styles.sectionHint}>
                  {q.length >= 2 ? `${users.length} found` : "Search"}
                </Text>
              </View>

              <View style={styles.searchWrap}>
                <Ionicons name="search" size={16} color={colors.gray[400]} />
                <TextInput
                  style={styles.searchInput}
                  placeholder="Search by name or email"
                  placeholderTextColor={colors.gray[400]}
                  value={query}
                  onChangeText={setQuery}
                  autoCapitalize="none"
                  autoCorrect={false}
                />
                {query.length > 0 && (
                  <TouchableOpacity
                    onPress={() => setQuery("")}
                    hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                  >
                    <Ionicons name="close-circle" size={16} color={colors.gray[400]} />
                  </TouchableOpacity>
                )}
              </View>

              {q.length < 2 ? (
                <Text style={styles.searchNote}>Enter at least 2 characters to search.</Text>
              ) : searching ? (
                <View style={styles.searchLoading}>
                  <ActivityIndicator size="small" color={colors.forest} />
                </View>
              ) : searchError ? (
                <EmptyState
                  compact
                  icon="cloud-offline-outline"
                  color={colors.warning}
                  eyebrow="Search"
                  title="Couldn't search"
                  subtitle="Pull down to refresh and try again."
                />
              ) : users.length === 0 ? (
                <EmptyState
                  compact
                  icon="people-outline"
                  color={colors.info}
                  eyebrow="Members"
                  title="No members found"
                  subtitle="Try a different name or email."
                />
              ) : (
                users.map((user) => {
                  const isAdminUser = user.role === "admin";
                  return (
                    <TouchableOpacity
                      key={user.id}
                      style={styles.userCard}
                      onPress={() => void openMember(user)}
                      activeOpacity={0.75}
                    >
                      <View style={styles.userAvatar}>
                        <Text style={styles.userAvatarText}>
                          {(user.name || "?").charAt(0).toUpperCase()}
                        </Text>
                      </View>
                      <View style={styles.userBody}>
                        <View style={styles.userNameRow}>
                          <Text style={styles.userName} numberOfLines={1}>
                            {user.name}
                          </Text>
                          <View style={[styles.roleBadge, isAdminUser && styles.roleBadgeAdmin]}>
                            <Text style={[styles.roleBadgeText, isAdminUser && styles.roleBadgeTextAdmin]}>
                              {isAdminUser ? "ADMIN" : "USER"}
                            </Text>
                          </View>
                        </View>
                        <Text style={styles.userEmail} numberOfLines={1}>
                          {user.email}
                        </Text>
                        <Text style={styles.userDate}>
                          Joined {formatShortDate(user.createdAt)}
                        </Text>
                      </View>
                      <Ionicons name="chevron-forward" size={16} color={colors.gray[400]} />
                    </TouchableOpacity>
                  );
                })
              )}
            </View>

            <View style={{ height: 30 }} />
          </ScrollView>
          </KeyboardAvoidingView>
        )}

        <Modal
          visible={!!selected}
          animationType="slide"
          presentationStyle="fullScreen"
          onRequestClose={closeMember}
        >
          <View style={styles.sheetOverlay}>
            <KeyboardAvoidingView
              behavior={Platform.OS === "ios" ? "padding" : "height"}
              style={styles.sheetAvoid}
            >
              <View
                style={[
                  styles.sheet,
                  {
                    paddingTop: insets.top + 12,
                    paddingBottom: insets.bottom + 20,
                  },
                ]}
              >
                {selected && (
                  <>
                    <View style={styles.sheetHeader}>
                      <View style={styles.sheetTitleWrap}>
                        <Text style={styles.sheetTitle}>{selected.name}</Text>
                        <Text style={styles.sheetSubtitle}>Member details</Text>
                      </View>
                      <TouchableOpacity style={styles.sheetClose} onPress={closeMember} hitSlop={8}>
                        <Ionicons name="close" size={22} color={colors.darkGreen} />
                      </TouchableOpacity>
                    </View>

                    <ScrollView
                      style={styles.sheetScroll}
                      showsVerticalScrollIndicator={false}
                      keyboardShouldPersistTaps="handled"
                    >
                      <View style={styles.detailCard}>
                        <Text style={styles.detailLabel}>Account</Text>
                        <Text style={styles.detailValue}>{selected.email || "No email"}</Text>
                        <View style={styles.detailMetaRow}>
                          <View
                            style={[
                              styles.detailRoleBadge,
                              selected.role === "admin" && styles.detailRoleBadgeAdmin,
                            ]}
                          >
                            <Text
                              style={[
                                styles.detailRoleBadgeText,
                                selected.role === "admin" && styles.detailRoleBadgeTextAdmin,
                              ]}
                            >
                              {selected.role === "admin" ? "ADMIN" : "USER"}
                            </Text>
                          </View>
                          <Text style={styles.detailMuted}>
                            Joined {formatShortDate(selected.createdAt)}
                          </Text>
                        </View>
                      </View>

                      {detailLoading ? (
                        <View style={styles.detailLoading}>
                          <ActivityIndicator size="small" color={colors.forest} />
                        </View>
                      ) : detailError ? (
                        <Text style={styles.detailError}>{detailError}</Text>
                      ) : detail ? (
                        <>
                          <View style={styles.detailCard}>
                            <View style={styles.statHead}>
                              <Ionicons name="flame" size={16} color={colors.goldDark} />
                              <Text style={styles.detailLabel}>Prayer streak</Text>
                            </View>
                            <View style={styles.statRow}>
                              <Text style={styles.statNumber}>{detail.prayerStreak}</Text>
                              <Text style={styles.statUnit}>days</Text>
                              <Text style={styles.statTotal}>
                                {detail.prayerDayCount} days recorded
                              </Text>
                            </View>
                            <RecentDays days={detail.prayerRecentDays} />
                          </View>

                          <View style={styles.detailCard}>
                            <View style={styles.statHead}>
                              <Ionicons name="book-outline" size={16} color={colors.forest} />
                              <Text style={styles.detailLabel}>Reading streak</Text>
                            </View>
                            <View style={styles.statRow}>
                              <Text style={styles.statNumber}>{detail.readingStreak}</Text>
                              <Text style={styles.statUnit}>days</Text>
                              <Text style={styles.statTotal}>
                                {detail.readingDayCount} days recorded
                              </Text>
                            </View>
                            <RecentDays days={detail.readingRecentDays} />
                          </View>

                          <View style={styles.restorePanel}>
                            <Text style={styles.detailLabel}>Restore streak</Text>
                            <Text style={styles.detailMuted}>
                              Enter a new length; use 0 to reset. Restores are logged.
                            </Text>
                            <View style={styles.restoreActions}>
                              <TouchableOpacity
                                style={styles.restoreBtn}
                                onPress={() => startRestore("prayer")}
                                disabled={!!restoreBusy}
                              >
                                <Text style={styles.restoreBtnText}>
                                  Prayer ({detail.prayerStreak})
                                </Text>
                              </TouchableOpacity>
                              <TouchableOpacity
                                style={styles.restoreBtn}
                                onPress={() => startRestore("reading")}
                                disabled={!!restoreBusy}
                              >
                                <Text style={styles.restoreBtnText}>
                                  Reading ({detail.readingStreak})
                                </Text>
                              </TouchableOpacity>
                            </View>

                            {restoreSection && (
                              <View style={styles.restoreForm}>
                                <Text style={styles.restoreFormLabel}>
                                  New {restoreSection} streak (0–3650)
                                </Text>
                                <View style={styles.restoreFormRow}>
                                  <TextInput
                                    style={styles.restoreInput}
                                    keyboardType="number-pad"
                                    value={targetValue}
                                    onChangeText={setTargetValue}
                                    autoFocus
                                    selectTextOnFocus
                                  />
                                  <TouchableOpacity
                                    style={styles.restoreSave}
                                    onPress={() => void confirmRestore()}
                                    disabled={!!restoreBusy}
                                  >
                                    {restoreBusy === restoreSection ? (
                                      <ActivityIndicator size="small" color={colors.white} />
                                    ) : (
                                      <Text style={styles.restoreSaveText}>Save</Text>
                                    )}
                                  </TouchableOpacity>
                                  <TouchableOpacity
                                    style={styles.restoreCancel}
                                    onPress={() => setRestoreSection(null)}
                                    disabled={!!restoreBusy}
                                  >
                                    <Text style={styles.restoreCancelText}>Cancel</Text>
                                  </TouchableOpacity>
                                </View>
                              </View>
                            )}

                            {restoreMsg && <Text style={styles.restoreMsg}>{restoreMsg}</Text>}
                          </View>
                        </>
                      ) : null}
                    </ScrollView>
                  </>
                )}
              </View>
            </KeyboardAvoidingView>
          </View>
        </Modal>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

