import { createVideoPlayer, type VideoPlayer } from "expo-video";
import { AVAILABLE_SOUNDS, getSoundFile } from "@/constants/sounds";
import { getPrayerSounds } from "./prayer-sounds";
import type { PrayerName } from "./notifications";

// Static requires so Metro bundles every sound file into the app.
const SOUND_FILES: Record<string, any> = {
  dawn: require("../../assets/sounds/dawn.wav"),
  sunrise: require("../../assets/sounds/sunrise.wav"),
  noon: require("../../assets/sounds/noon.wav"),
  afternoon: require("../../assets/sounds/afternoon.wav"),
  sunset: require("../../assets/sounds/sunset.wav"),
  evening: require("../../assets/sounds/evening.wav"),
};

let player: VideoPlayer | null = null;
let currentFile: string | null = null;

function getPlayer(): VideoPlayer | null {
  if (player) return player;
  try {
    const p = createVideoPlayer(SOUND_FILES.dawn);
    p.loop = false;
    p.volume = 1;
    p.muted = false;
    p.audioMixingMode = "auto";
    p.addListener("playToEnd", () => {
      try {
        p.pause();
      } catch {}
    });
    player = p;
    currentFile = "dawn";
    return p;
  } catch {
    return null;
  }
}

function playFile(file: string) {
  try {
    const source = SOUND_FILES[file] || SOUND_FILES.dawn;
    const p = getPlayer();
    if (!p) return;
    // The player is reused, so swap its source whenever a different sound is
    // requested (e.g. each prayer time has its own chosen sound).
    if (currentFile !== file) {
      p.replace(source);
      currentFile = file;
    }
    p.currentTime = 0;
    p.play();
  } catch {}
}

/**
 * Plays the user's selected sound for a prayer time, in-app. Used when a
 * prayer-time notification arrives while the app is in the foreground so the
 * app's own (custom) sound is always heard instead of the device default.
 */
export async function playPrayerSound(name: PrayerName) {
  try {
    const sounds = await getPrayerSounds();
    const soundId = sounds[name] || name;
    const known = AVAILABLE_SOUNDS.some((s) => s.id === soundId);
    playFile(getSoundFile(known ? soundId : "dawn"));
  } catch {
    playFile("dawn");
  }
}
