import { PRAYER_CATEGORIES } from "@/components/PrayerRequestModal";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { IS_WEB } from "@/services/config";
import {
  getTodayKey,
  loadPrayerFocus,
  removePrayerFocus,
  savePrayerFocus,
  updatePrayerFocus,
  type PrayerKey,
  type PrayerRequestEntry,
} from "@/utils/streaks";
import { Ionicons } from "@expo/vector-icons";
import { router, useLocalSearchParams } from "expo-router";
import { useEffect, useState } from "react";
import {
  Alert,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useSQLiteContext } from "expo-sqlite";

function longDate(iso: string) {
  const [year, month, day] = iso.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

function showMessage(title: string, message: string) {
  if (IS_WEB && typeof window !== "undefined") {
    window.alert(message || title);
    return;
  }
  Alert.alert(title, message);
}

function confirmRemove(onConfirm: () => void | Promise<void>) {
  if (IS_WEB && typeof window !== "undefined") {
    if (window.confirm("Remove this prayer focus?")) void onConfirm();
    return;
  }
  Alert.alert("Remove focus", "Remove this prayer focus?", [
    { text: "Cancel", style: "cancel" },
    {
      text: "Remove",
      style: "destructive",
      onPress: () => void onConfirm(),
    },
  ]);
}

/**
 * Prayer focus — what the user wants to pray about in one prayer session
 * (e.g. today's noon prayer). Saved focuses show on that session's card on
 * Home; when none is saved the card keeps showing the day's verse.
 */
export default function PrayerRequestScreen() {
  const db = useSQLiteContext();
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams<{
    title: string;
    time: string;
    icon: string;
    prayerKey: PrayerKey;
    dateKey: string;
  }>();

  const title = params.title || "Prayer";
  const time = params.time || "";
  const icon = params.icon || "leaf-outline";
  const prayerKey = (params.prayerKey || "dawn") as PrayerKey;
  const dateKey = params.dateKey || getTodayKey();
  const storageKey = `${dateKey}_${prayerKey}`;

  // Reads happen only after mount, never during render — a slow or locked
  // local DB just leaves the list empty instead of interrupting the screen.
  const [entries, setEntries] = useState<PrayerRequestEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [text, setText] = useState("");
  const [name, setName] = useState("");
  const [category, setCategory] = useState("");

  useEffect(() => {
    let alive = true;
    (async () => {
      const all = await loadPrayerFocus(db);
      if (!alive) return;
      setEntries(all[storageKey] || []);
      setLoading(false);
    })();
    return () => {
      alive = false;
    };
  }, [db, storageKey]);

  const resetForm = () => {
    setEditingId(null);
    setText("");
    setName("");
    setCategory("");
  };

  const handleSave = async () => {
    const value = text.trim();
    if (!value || saving) return;
    setSaving(true);
    try {
      const result =
        editingId !== null
          ? await updatePrayerFocus(db, editingId, value, name.trim(), category, storageKey)
          : await savePrayerFocus(db, storageKey, value, name.trim(), category);
      if (!result.ok) {
        // The detail line is temporary: it tells us which SQLite error a
        // device hit if the storage repair above still could not write.
        const detail = result.reason ? `\n\nDetails: ${result.reason.slice(0, 160)}` : "";
        showMessage(
          "Could not save",
          `Your prayer focus was not saved. Please try again.${detail}`,
        );
        return;
      }
      setEntries(result.all[storageKey] || []);
      resetForm();
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (entry: PrayerRequestEntry) => {
    if (!entry.id) return;
    setEditingId(entry.id);
    setText(entry.text);
    setName(entry.name || "");
    setCategory(entry.topic || "");
  };

  const handleRemove = (entry: PrayerRequestEntry) => {
    const id = entry.id;
    if (!id) return;
    confirmRemove(async () => {
      const result = await removePrayerFocus(db, id);
      if (!result.ok) {
        showMessage("Could not remove", "Please try again.");
        return;
      }
      setEntries(result.all[storageKey] || []);
      if (editingId === id) resetForm();
    });
  };

  const canSave = text.trim().length > 0 && !saving;

  return (
    <View style={[s.safe, { paddingTop: insets.top }]}>
      <View style={s.header}>
        <TouchableOpacity
          style={s.backBtn}
          onPress={() => router.back()}
          accessibilityLabel="Back"
        >
          <Ionicons name="chevron-back" size={22} color={colors.forest} />
        </TouchableOpacity>
        <View style={s.headIcon}>
          <Ionicons name={icon as any} size={20} color={colors.white} />
        </View>
        <View style={{ flex: 1 }}>
          <Text style={s.headerTitle}>{title}</Text>
          <Text style={s.headerSub}>
            {longDate(dateKey)}
            {time ? ` · ${time}` : ""}
          </Text>
        </View>
      </View>

      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={{ flex: 1 }}
      >
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={[s.body, { paddingBottom: insets.bottom + 32 }]}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={s.card}>
            <Text style={s.cardTitle}>
              {editingId !== null ? "Edit prayer focus" : "What would you like to pray for?"}
            </Text>
            <Text style={s.cardSub}>
              This shows on the {title.toLowerCase()} card on Home.
            </Text>

            <TextInput
              style={s.textArea}
              placeholder="e.g. Peace for my family this week…"
              placeholderTextColor={colors.gray[400]}
              value={text}
              onChangeText={setText}
              multiline
              textAlignVertical="top"
            />

            <Text style={s.fieldLabel}>Who is this for?</Text>
            <TextInput
              style={s.input}
              placeholder="Name of the person (optional)"
              placeholderTextColor={colors.gray[400]}
              value={name}
              onChangeText={setName}
            />

            <Text style={s.fieldLabel}>Category</Text>
            <View style={s.chipWrap}>
              {PRAYER_CATEGORIES.map((c) => {
                const active = category === c;
                return (
                  <TouchableOpacity
                    key={c}
                    style={[s.chip, active && s.chipActive]}
                    onPress={() => setCategory(active ? "" : c)}
                    activeOpacity={0.8}
                  >
                    <Text style={[s.chipText, active && s.chipTextActive]}>{c}</Text>
                  </TouchableOpacity>
                );
              })}
            </View>

            <View style={s.actions}>
              {editingId !== null ? (
                <TouchableOpacity style={s.cancelBtn} onPress={resetForm} activeOpacity={0.8}>
                  <Text style={s.cancelText}>Cancel</Text>
                </TouchableOpacity>
              ) : null}
              <TouchableOpacity
                style={[s.saveBtn, !canSave && s.saveBtnDisabled]}
                onPress={handleSave}
                disabled={!canSave}
                activeOpacity={0.85}
              >
                <Ionicons name="checkmark" size={16} color={canSave ? colors.white : colors.gray[500]} />
                <Text style={[s.saveText, !canSave && s.saveTextDisabled]}>
                  {saving ? "Saving…" : editingId !== null ? "Save changes" : "Save focus"}
                </Text>
              </TouchableOpacity>
            </View>
          </View>

          <View style={s.listSection}>
            <Text style={s.listTitle}>Saved for this prayer</Text>
            {loading ? null : entries.length === 0 ? (
              <Text style={s.emptyText}>
                Nothing yet — without a focus the card keeps showing the day&apos;s verse.
              </Text>
            ) : (
              entries.map((entry, index) => (
                <View key={entry.id ?? index} style={s.entry}>
                  <View style={s.entryAccent} />
                  <View style={s.entryBody}>
                    <Text style={s.entryText}>{entry.text}</Text>
                    {entry.topic || entry.name ? (
                      <View style={s.entryMeta}>
                        {entry.topic ? (
                          <View style={s.entryChip}>
                            <Text style={s.entryChipText}>{entry.topic}</Text>
                          </View>
                        ) : null}
                        {entry.name ? (
                          <Text style={s.entryName}>— {entry.name}</Text>
                        ) : null}
                      </View>
                    ) : null}
                  </View>
                  <TouchableOpacity
                    style={s.entryAction}
                    onPress={() => handleEdit(entry)}
                    accessibilityLabel="Edit prayer focus"
                  >
                    <Ionicons name="create-outline" size={17} color="#0fa3c4" />
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={s.entryAction}
                    onPress={() => handleRemove(entry)}
                    accessibilityLabel="Remove prayer focus"
                  >
                    <Ionicons name="trash-outline" size={16} color={colors.gray[400]} />
                  </TouchableOpacity>
                </View>
              ))
            )}
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

