function formatDateTime(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("en-ZA", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function formatDayDate(value: string): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return "";
  const [year, month, day] = value.split("-").map(Number);
  return new Date(year, (month || 1) - 1, day || 1).toLocaleDateString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
}

function timeRange(startTime: string, endTime: string): string {
  if (startTime && endTime) return `${startTime} – ${endTime}`;
  return startTime || endTime;
}

export default function TrainingDetailScreen() {
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams<{ id?: string | string[] }>();
  const id = Array.isArray(params.id) ? params.id[0] : params.id || "";
  const [training, setTraining] = useState<Training | null>(null);
  const [currentUserId, setCurrentUserId] = useState("");
  const [canManage, setCanManage] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [deleting, setDeleting] = useState(false);
  const [busyAttendance, setBusyAttendance] = useState(false);
  const [savingReason, setSavingReason] = useState(false);
  const [reasonDraft, setReasonDraft] = useState("");

  const load = useCallback(async () => {
    if (!id) {
      setError("This training could not be found.");
      setLoading(false);
      return;
    }
    try {
      setError("");
      const res = await trainingsApi.get(id);
      const userId = res.currentUserId || "";
      setTraining(res.data);
      setCurrentUserId(userId);
      setReasonDraft(
        res.data.attendance?.find((entry) => entry.userId === userId)?.reason || "",
      );
      setCanManage(
        res.canManage ?? (!res.data.createdBy || res.data.createdBy === userId),
      );
    } catch (e: any) {
      setError(e?.message || "Failed to load the training.");
    } finally {
      setLoading(false);
    }
  }, [id]);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const respond = async (status: TrainingAttendanceStatus) => {
    if (!training || busyAttendance) return;
    setBusyAttendance(true);
    try {
      const res = await trainingsApi.markAttendance(
        training._id,
        status,
        status === "NOT_ATTENDING" ? reasonDraft.trim() : "",
      );
      setTraining(res.data);
      setReasonDraft(
        res.data.attendance?.find((entry) => entry.userId === currentUserId)
          ?.reason || "",
      );
    } catch (e: any) {
      Alert.alert("Could not save your attendance", e?.message || "Please try again.");
    } finally {
      setBusyAttendance(false);
    }
  };

  const saveReason = async () => {
    if (!training || savingReason) return;
    setSavingReason(true);
    try {
      const res = await trainingsApi.markAttendance(
        training._id,
        "NOT_ATTENDING",
        reasonDraft.trim(),
      );
      setTraining(res.data);
    } catch (e: any) {
      Alert.alert("Could not save your reason", e?.message || "Please try again.");
    } finally {
      setSavingReason(false);
    }
  };

  const remove = async () => {
    if (!training) return;
    setDeleting(true);
    try {
      await trainingsApi.remove(training._id);
      router.back();
    } catch (e: any) {
      Alert.alert("Could not delete", e?.message || "Please try again.");
    } finally {
      setDeleting(false);
    }
  };

  const confirmDelete = () => {
    if (!training) return;
    Alert.alert(
      "Delete this training?",
      `${training.title} will be removed from the calendar and every admin will be told. This cannot be undone.`,
      [
        { text: "Keep it", style: "cancel" },
        { text: "Delete", style: "destructive", onPress: () => void remove() },
      ],
    );
  };

  const joinOnline = async () => {
    if (!training?.meetingLink) return;
    try {
      await Linking.openURL(training.meetingLink);
    } catch {
      Alert.alert(
        "Could not open the meeting",
        "Copy the link and open it in your browser.",
      );
    }
  };

  const myAttendance =
    training?.attendance?.find((entry) => entry.userId === currentUserId)?.status ?? null;  const days = training?.days ?? [];
  const lastDayDate = days.reduce(
    (latest, day) => (day.date > latest ? day.date : latest),
    "",
  );
  const attendance = training?.attendance ?? [];
  const counts = training?.counts ?? { attending: 0, notAttending: 0, total: 0 };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <BoardHeader title="Training" />
        {loading ? (
          <View style={s.center}>
            <ActivityIndicator color={colors.goldDark} size="large" />
          </View>
        ) : error || !training ? (
          <View style={{ paddingHorizontal: 16 }}>
            <View style={s.emptyBox}>
              <Ionicons name="warning-outline" size={24} color={colors.error} />
              <Text style={s.emptyTitle}>Couldn’t load the training</Text>
              <Text style={s.emptyBody}>
                {error || "This training is no longer on the calendar."}
              </Text>
              <TouchableOpacity onPress={() => void load()} activeOpacity={0.85}>
                <Text style={[s.docLinkText, { marginTop: 6 }]}>Retry</Text>
              </TouchableOpacity>
            </View>
          </View>
        ) : (
          <ScrollView
            contentContainerStyle={[
              styles.content,
              { paddingBottom: 40 + insets.bottom },
            ]}
            showsVerticalScrollIndicator={false}
          >
            {training.imageUrl ? (
              <Image
                source={{
                  uri:
                    getOptimizedImageUrl(training.imageUrl, 1000) ||
                    training.imageUrl,
                }}
                style={styles.hero}
                contentFit="cover"
                transition={150}
              />
            ) : null}

            <View style={styles.head}>
              <Text style={styles.title}>{training.title}</Text>
              <View style={styles.metaRow}>
                <Ionicons name="calendar-clear-outline" size={16} color={colors.goldDark} />
                <Text style={styles.metaText}>
                  {formatDateTime(training.scheduledDate)}
                </Text>
              </View>
              {training.location ? (
                <View style={styles.metaRow}>
                  <Ionicons name="location-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.metaText}>{training.location}</Text>
                </View>
              ) : null}
              {days.length > 1 ? (
                <View style={styles.metaRow}>
                  <Ionicons name="layers-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.metaText}>
                    {days.length} days
                    {formatDayDate(lastDayDate)
                      ? ` · ends ${formatDayDate(lastDayDate)}`
                      : ""}
                  </Text>
                </View>
              ) : null}
            </View>

            {training.meetingLink ? (
              <TouchableOpacity
                style={styles.joinBtn}
                onPress={() => void joinOnline()}
                activeOpacity={0.9}
                accessibilityLabel="Join the online meeting"
              >
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                <Ionicons name="videocam-outline" size={18} color={colors.white} />
                <View style={{ flex: 1 }}>
                  <Text style={styles.joinText}>Join online</Text>
                  <Text style={styles.joinSub} numberOfLines={1}>
                    {training.meetingLink}
                  </Text>
                </View>
                <Ionicons name="open-outline" size={16} color={colors.white} />
              </TouchableOpacity>
            ) : null}

            {days.length ? (
              <View style={styles.body}>
                <Text style={styles.sectionTitle}>Day-by-day plan</Text>
                {days.map((day, index) => {
                  const range = timeRange(day.startTime, day.endTime);
                  const dateLabel = formatDayDate(day.date);
                  return (
                    <View
                      key={index}
                      style={[styles.dayRow, index > 0 && styles.dayRowBorder]}
                    >
                      <View style={styles.dayBadge}>
                        <Text style={styles.dayBadgeText}>{index + 1}</Text>
                      </View>
                      <View style={{ flex: 1, gap: 5 }}>
                        <Text style={styles.dayTitle}>
                          Day {index + 1}
                          {dateLabel ? ` · ${dateLabel}` : ""}
                        </Text>
                        {range ? (
                          <View style={styles.timePill}>
                            <Ionicons name="time-outline" size={13} color={colors.goldDark} />
                            <Text style={styles.timePillText}>{range}</Text>
                          </View>
                        ) : null}
                        {day.topic ? (
                          <Text style={styles.dayTopic}>{day.topic}</Text>
                        ) : null}
                        {day.details ? (
                          <Text style={styles.description}>{day.details}</Text>
                        ) : null}
                        {day.notes ? (
                          <Text style={styles.dayNotes}>{day.notes}</Text>
                        ) : null}
                        {day.timeline?.length ? (
                          <View style={styles.timeline}>
                            {day.timeline.map((item, blockIndex) => (
                              <View key={blockIndex} style={styles.timelineRow}>
                                <Text style={styles.timelineTime}>
                                  {timeRange(item.startTime, item.endTime) || "—"}
                                </Text>
                                <View style={{ flex: 1 }}>
                                  {item.title ? (
                                    <Text style={styles.timelineTitle}>
                                      {item.title}
                                    </Text>
                                  ) : null}
                                  {item.details ? (
                                    <Text style={styles.timelineDetails}>
                                      {item.details}
                                    </Text>
                                  ) : null}
                                </View>
                              </View>
                            ))}
                          </View>
                        ) : null}
                      </View>
                    </View>
                  );
                })}
              </View>
            ) : null}

            <View style={styles.body}>
              {training.description ? (
                <Text style={styles.description}>{training.description}</Text>
              ) : (
                <Text style={styles.descriptionMuted}>
                  Details for this training have not been added yet.
                </Text>
              )}
              <Text style={styles.footnote}>
                Scheduled by {training.createdByName} for officers and positions.
              </Text>
            </View>

            <View style={styles.body}>
              <Text style={styles.sectionTitle}>Your attendance</Text>
              <Text style={styles.attendanceHint}>
                Let the board know whether you will join this training.
              </Text>
              <View style={styles.attendButtons}>
                {(["ATTENDING", "NOT_ATTENDING"] as const).map((status) => {
                  const on = myAttendance === status;
                  const attending = status === "ATTENDING";
                  return (
                    <TouchableOpacity
                      key={status}
                      style={[
                        styles.attendBtn,
                        on && (attending ? styles.attendOn : styles.attendOff),
                      ]}
                      onPress={() => void respond(status)}
                      disabled={busyAttendance || !currentUserId}
                      activeOpacity={0.85}
                    >
                      {busyAttendance ? (
                        <ActivityIndicator size="small" color={colors.goldDark} />
                      ) : (
                        <>
                          <Ionicons
                            name={attending ? "checkmark-circle-outline" : "close-circle-outline"}
                            size={16}
                            color={on ? (attending ? "#047857" : "#be123c") : colors.muted}
                          />
                          <Text
                            style={[
                              styles.attendBtnText,
                              on && (attending ? styles.attendOnText : styles.attendOffText),
                            ]}
                          >
                            {attending ? "Attending" : "Not attending"}
                          </Text>
                        </>
                      )}
                    </TouchableOpacity>
                  );
                })}
              </View>

              {myAttendance === "NOT_ATTENDING" ? (
                <View style={styles.reasonBox}>
                  <Text style={styles.reasonLabel}>Reason for not attending</Text>
                  <Text style={styles.reasonHint}>
                    The facilitator sees this, so they know why you can’t make it.
                  </Text>
                  <AutoGrowInput
                    placeholder="e.g. Work travel, family commitment or ill health"
                    placeholderTextColor={colors.muted}
                    value={reasonDraft}
                    onChangeText={setReasonDraft}
                    maxLength={500}
                    minHeight={64}
                  />
                  <TouchableOpacity
                    style={[styles.reasonSave, savingReason && s.busy]}
                    onPress={() => void saveReason()}
                    disabled={savingReason}
                    activeOpacity={0.85}
                  >
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                    {savingReason ? (
                      <ActivityIndicator size="small" color={colors.white} />
                    ) : (
                      <Text style={styles.reasonSaveText}>Save reason</Text>
                    )}
                  </TouchableOpacity>
                </View>
              ) : null}

              <Text style={styles.tally}>
                {counts.attending} attending · {counts.notAttending} not attending
              </Text>

              {attendance.length ? (
                <View style={styles.attendList}>
                  {attendance.map((entry) => {
                    const attending = entry.status === "ATTENDING";
                    return (
                      <View key={entry.userId} style={styles.attendRow}>
                        <View style={styles.avatar}>
                          <Text style={styles.avatarText}>
                            {entry.name.charAt(0).toUpperCase()}
                          </Text>
                        </View>
                        <View style={{ flex: 1 }}>
                          <Text style={styles.attendName} numberOfLines={1}>
                            {entry.name}
                            {entry.userId === currentUserId ? (
                              <Text style={styles.youTag}> · You</Text>
                            ) : null}
                          </Text>
                          {!attending && entry.reason ? (
                            <Text style={styles.attendReason} numberOfLines={3}>
                              {entry.reason}
                            </Text>
                          ) : null}
                        </View>
                        <View
                          style={[
                            styles.attendPill,
                            { backgroundColor: attending ? "#d1fae5" : "#ffe4e6" },
                          ]}
                        >
                          <Text
                            style={[
                              styles.attendPillText,
                              { color: attending ? "#047857" : "#be123c" },
                            ]}
                          >
                            {attending ? "Attending" : "Not attending"}
                          </Text>
                        </View>
                      </View>
                    );
                  })}
                </View>
              ) : null}
            </View>

            {canManage ? (
              <View style={styles.body}>
                <View style={styles.manageHead}>
                  <Ionicons
                    name="shield-checkmark-outline"
                    size={16}
                    color={colors.goldDark}
                  />
                  <Text style={styles.sectionTitle}>Manage training</Text>
                </View>
                <Text style={styles.manageHint}>
                  Only the admin who scheduled this training can change or remove it.
                </Text>
                <View style={styles.actions}>
                  <TouchableOpacity
                    style={[s.secondaryBtn, { flex: 1 }]}
                    onPress={() =>
                      router.push({
                        pathname: "/admin/trainings/new",
                        params: { id: training._id },
                      } as any)
                    }
                    activeOpacity={0.85}
                  >
                    <Ionicons
                      name="create-outline"
                      size={17}
                      color={colors.goldDark}
                    />
                    <Text style={s.secondaryText}>Edit training</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.deleteBtn, deleting && s.busy]}
                    onPress={confirmDelete}
                    disabled={deleting}
                    activeOpacity={0.85}
                  >
                    {deleting ? (
                      <ActivityIndicator size="small" color="#be123c" />
                    ) : (
                      <>
                        <Ionicons name="trash-outline" size={17} color="#be123c" />
                        <Text style={styles.deleteText}>Delete</Text>
                      </>
                    )}
                  </TouchableOpacity>
                </View>
              </View>
            ) : null}
          </ScrollView>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

