import { router } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Linking,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { Skill, SkillLevel } from "@/constants/skills";
import { getSession, type Session } from "@/services/auth";
import { skillsProgressApi } from "@/services/skills-progress";
import type { SkillProgress } from "@/services/skills-catalog";

const EMPTY_SAVINGS = { total: 0, deposits: [] as { amount: number; at?: string }[] };

/** Blank criteria grid shaped to this skill's level requirements. */
function blankCriteria(level: SkillLevel): boolean[][] {
  return level.requirements.map((req) => req.criteria.map(() => false));
}

/** A saved grid reshaped to this level's requirement/criteria layout. */
function hydrateCriteria(
  level: SkillLevel,
  saved?: boolean[][] | null,
): boolean[][] {
  const blank = blankCriteria(level);
  if (!saved) return blank;
  return blank.map((row, i) => row.map((_, j) => saved[i]?.[j] === true));
}

/**
 * A participant's live measurable status for one skill level: every requirement
 * is broken into concrete pass criteria, each ticked as it is proven.
 */
export default function SkillProgressCard({
  skill,
  level,
  clubSlug,
  whatsappGroupLink,
}: {
  skill: Skill;
  level: SkillLevel;
  clubSlug: string;
  whatsappGroupLink?: string;
}) {
  const [session, setSession] = useState<Session | null | undefined>(undefined);
  const [criteria, setCriteria] = useState<boolean[][]>(() =>
    blankCriteria(level),
  );
  const [progress, setProgress] = useState<SkillProgress | null>(null);
  const [savings, setSavings] = useState(EMPTY_SAVINGS);
  const [amount, setAmount] = useState("");
  const [adding, setAdding] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [enrolling, setEnrolling] = useState(false);
  const [error, setError] = useState("");

  const user = session?.user ?? null;

  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((s) => {
        if (!cancelled) setSession(s);
      })
      .catch(() => {
        if (!cancelled) setSession(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    // Hydrate from the member's saved row; a signed-out or fresh account
    // gets `{data: null}` back — blank grid + the enroll screen.
    skillsProgressApi
      .get(skill.id, level.id)
      .then((row) => {
        if (cancelled) return;
        setProgress(row);
        setCriteria(hydrateCriteria(level, row?.criteria));
        setLoaded(true);
      })
      .catch(() => {
        if (cancelled) return;
        setProgress(null);
        setCriteria(blankCriteria(level));
        setLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, [user, skill, level]);

  async function enroll() {
    setEnrolling(true);
    setError("");
    try {
      const row = await skillsProgressApi.enroll(skill.id, level.id);
      setProgress(row);
      setCriteria(hydrateCriteria(level, row.criteria));
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setEnrolling(false);
    }
  }

  async function addDeposit() {
    const value = Number(amount);
    if (!Number.isFinite(value) || value <= 0) {
      setError("Enter the amount — above R0.");
      return;
    }
    setAdding(true);
    setError("");
    try {
      await new Promise((resolve) => setTimeout(resolve, 300));
      setSavings((prev) => ({
        total: prev.total + value,
        deposits: [...prev.deposits, { amount: value, at: new Date().toISOString() }],
      }));
      setAmount("");
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setAdding(false);
    }
  }

  const criterionTotal = level.requirements.reduce(
    (sum, req) => sum + req.criteria.length,
    0,
  );
  const criterionDone = criteria.reduce(
    (sum, row) => sum + row.filter(Boolean).length,
    0,
  );
  const total = level.requirements.length;
  const done = criteria.filter((row) => row.length > 0 && row.every(Boolean)).length;
  const allDone = total > 0 && done === total;
  const pct = criterionTotal
    ? Math.round((criterionDone / criterionTotal) * 100)
    : 0;

  if (session === undefined || (user && !loaded)) {
    return (
      <View style={s.card}>
        <View style={s.loadingRow}>
          <ActivityIndicator size="small" color={colors.goldDark} />
          <Text style={s.loadingText}>Loading your progress…</Text>
        </View>
      </View>
    );
  }

  if (!user) {
    return (
      <View style={s.card}>
        <Text style={s.kicker}>Level {level.levelNumber}</Text>
        <Text style={s.title}>{level.name}</Text>

        <View style={s.reqList}>
          {level.requirements.map((req, i) => (
            <View key={req.text} style={s.readReq}>
              <View style={s.readReqHead}>
                <View style={s.readIndex}>
                  <Text style={s.readIndexText}>{i + 1}</Text>
                </View>
                <Text style={s.readReqText}>{req.text}</Text>
              </View>
              <View style={s.readCriteria}>
                {req.criteria.map((criterion) => (
                  <Text key={criterion} style={s.readCriterion}>
                    {criterion}
                  </Text>
                ))}
              </View>
            </View>
          ))}
        </View>

        <View style={s.signInCard}>
          <View style={s.signInIcon}>
            <Ionicons name="log-in-outline" size={18} color={colors.goldDark} />
          </View>
          <Text style={s.signInTitle}>Track your progress</Text>
          <Text style={s.signInText}>
            Sign in to enroll and follow your progress — your instructor marks
            each criterion complete as you prove it.
          </Text>
          <TouchableOpacity
            activeOpacity={0.9}
            style={s.signInBtn}
            onPress={() =>
              router.push({
                pathname: "/login",
                params: { next: `/skills/${clubSlug}/${skill.id}` },
              })
            }
            accessibilityRole="button"
            accessibilityLabel="Sign in to start tracking this skill"
          >
            <Ionicons name="log-in-outline" size={15} color={colors.white} />
            <Text style={s.signInBtnText}>Sign in to start</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  // Enrolled = the row carries `enrolledAt` (POST may write it with no ticks yet).
  if (!progress?.enrolledAt) {
    return (
      <View style={s.card}>
        <Text style={s.kicker}>Get started</Text>
        <Text style={s.title}>{level.name}</Text>

        <View style={s.enrollIntro}>
          <View style={s.enrollIcon}>
            <Ionicons name="ribbon-outline" size={18} color={colors.goldDark} />
          </View>
          <View style={{ flex: 1 }}>
            <Text style={s.enrollTitle}>Enroll to start</Text>
            <Text style={s.enrollText}>
              Enroll for this skill level. Your instructor ticks each criterion
              as you prove it — progress shows here automatically.
            </Text>
          </View>
        </View>

        <TouchableOpacity
          activeOpacity={0.9}
          style={[s.enrollBtn, enrolling && { opacity: 0.6 }]}
          onPress={enroll}
          disabled={enrolling}
          accessibilityRole="button"
          accessibilityLabel={`Enroll in ${level.name}`}
        >
          {enrolling ? (
            <ActivityIndicator size="small" color={colors.white} />
          ) : (
            <>
              <Ionicons name="ribbon-outline" size={15} color={colors.white} />
              <Text style={s.enrollBtnText}>Enroll in {level.name}</Text>
            </>
          )}
        </TouchableOpacity>

        {error ? (
          <View style={s.errorBox}>
            <Text style={s.errorText}>{error}</Text>
          </View>
        ) : null}

        <View style={[s.reqList, s.enrollReqs]}>
          <Text style={s.enrollReqsKicker}>What you&rsquo;ll prove</Text>
          {level.requirements.map((req, i) => (
            <View key={req.text} style={s.readReq}>
              <View style={s.readReqHead}>
                <View style={s.readIndex}>
                  <Text style={s.readIndexText}>{i + 1}</Text>
                </View>
                <Text style={s.readReqText}>{req.text}</Text>
              </View>
              <View style={s.readCriteria}>
                {req.criteria.map((criterion) => (
                  <Text key={criterion} style={s.readCriterion}>
                    {criterion}
                  </Text>
                ))}
              </View>
            </View>
          ))}
        </View>
      </View>
    );
  }

  const statusLabel = allDone
    ? "Complete"
    : criterionDone > 0
      ? "In progress"
      : "Not started";

  return (
    <View style={s.card}>
      <View style={s.headRow}>
        <View style={{ flex: 1 }}>
          <Text style={s.kicker}>Level {level.levelNumber}</Text>
          <Text style={s.title}>{level.name}</Text>
        </View>
        <View
          style={[
            s.statusPill,
            {
              backgroundColor: allDone
                ? "rgba(16,185,129,0.14)"
                : criterionDone > 0
                  ? "rgba(19,197,221,0.14)"
                  : colors.bgSoft,
            },
          ]}
        >
          <Text
            style={[
              s.statusPillText,
              {
                color: allDone
                  ? colors.emeraldDark
                  : criterionDone > 0
                    ? colors.goldDark
                    : colors.muted,
              },
            ]}
          >
            {statusLabel}
          </Text>
        </View>
      </View>

      <View style={s.progressBlock}>
        <View style={s.barTrack}>
          <View
            style={[
              s.barFill,
              {
                width: `${pct}%`,
                backgroundColor: allDone ? colors.emerald : colors.gold,
              },
            ]}
          />
        </View>
        <Text style={s.progressText}>
          <Text style={s.strong}>
            {criterionDone} of {criterionTotal} criteria proven ({pct}%)
          </Text>
          {"  · "}
          {done} of {total} requirements complete
        </Text>
      </View>

      <View style={s.reqList}>
        {level.requirements.map((req, i) => {
          const row = criteria[i] ?? req.criteria.map(() => false);
          const rowDone = row.filter(Boolean).length;
          const reqProven = rowDone === req.criteria.length;
          return (
            <View
              key={req.text}
              style={[s.reqCard, reqProven && s.reqCardDone]}
            >
              <View style={s.reqHead}>
                <Text style={s.reqLabel}>Requirement {i + 1}</Text>
                <Text
                  style={[
                    s.reqCount,
                    { color: reqProven ? colors.emeraldDark : colors.goldDark },
                  ]}
                >
                  {reqProven
                    ? "Proven"
                    : `${rowDone} of ${req.criteria.length} criteria`}
                </Text>
              </View>
              <Text style={s.reqText}>{req.text}</Text>

              <View style={s.criterionList}>
                {req.criteria.map((criterion, j) => {
                  const checked = row[j] === true;
                  return (
                    <View
                      key={criterion}
                      style={s.criterionRow}
                      accessibilityRole="text"
                      accessibilityLabel={`Criterion for requirement ${i + 1}: ${criterion}${checked ? " — proven" : " — not yet marked"}`}
                    >
                      <Ionicons
                        name={checked ? "checkmark-circle" : "ellipse-outline"}
                        size={17}
                        color={checked ? colors.emerald : colors.gray[300]}
                      />
                      <Text
                        style={[
                          s.criterionText,
                          checked && s.criterionTextDone,
                        ]}
                      >
                        {criterion}
                      </Text>
                    </View>
                  );
                })}
              </View>

              {reqProven && (
                <View style={s.provenRow}>
                  <Ionicons
                    name="checkmark-circle"
                    size={14}
                    color={colors.emeraldDark}
                  />
                  <Text style={s.provenText}>Requirement proven</Text>
                </View>
              )}
            </View>
          );
        })}
      </View>

      {error ? (
        <View style={s.errorBox}>
          <Text style={s.errorText}>{error}</Text>
        </View>
      ) : null}

      <View style={s.leaderNote}>
        {allDone ? (
          <Text style={s.leaderNoteText}>
            <Text style={{ color: colors.emeraldDark, fontWeight: "700" }}>
              ✓{" "}
            </Text>
            Every criterion is proven. Your instructor confirms the sign-off
            and awards{" "}
            <Text style={s.strong}>{skill.name}</Text>.
          </Text>
        ) : (
          <Text style={s.leaderNoteText}>
            Your instructor marks each criterion as you prove it — a
            requirement counts once all of its criteria are signed off.
            Progress updates here automatically.
          </Text>
        )}
        {whatsappGroupLink ? (
          <TouchableOpacity
            activeOpacity={0.7}
            onPress={() => Linking.openURL(whatsappGroupLink).catch(() => {})}
            style={s.waLink}
            accessibilityRole="link"
            accessibilityLabel="Ask your leader on WhatsApp"
          >
            <Ionicons
              name="logo-whatsapp"
              size={13}
              color={colors.goldDark}
            />
            <Text style={s.waLinkText}>Ask your leader on WhatsApp →</Text>
          </TouchableOpacity>
        ) : null}
      </View>

    </View>
  );
}

