import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import * as ImagePicker from "expo-image-picker";
import { useEffect, useState } from "react";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { router } from "expo-router";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";
import {
  sponsorApi,
  EMPTY_BANKING,
  formatBankingDetails,
  type BankingDetails,
  type SponsorshipSummary,
} from "@/services/sponsorships";

const fmtMoney = (n: number) => `R ${n.toLocaleString("en-US")}`;

/** Pick a proof-of-payment image and upload it to storage. */
async function pickSponsorPop(): Promise<string | null> {
  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ImagePicker.MediaTypeOptions.Images,
    allowsEditing: true,
    quality: 0.7,
    base64: true,
  });
  if (result.canceled || !result.assets?.length) return null;
  const asset = result.assets[0];
  const { uploadSponsorPop } = await import("@/services/cloudinary");
  return uploadSponsorPop({
    uri: asset.uri,
    base64: asset.base64 ?? null,
    mimeType: asset.mimeType,
  });
}

export default function SponsorModal({ onClose }: { onClose: () => void }) {
  const insets = useSafeAreaInsets();

  const [signedIn, setSignedIn] = useState<boolean | null>(null);
  const [sponsorId, setSponsorId] = useState<string | null>(null);
  const [summary, setSummary] = useState<SponsorshipSummary | null>(null);
  const [banking, setBanking] = useState<BankingDetails>(EMPTY_BANKING);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [amount, setAmount] = useState("");
  const [popUrl, setPopUrl] = useState<string | null>(null);
  const [uploadingPop, setUploadingPop] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState<{ sponsorId: string; firstName: string } | null>(null);

  useEffect(() => {
    getSession().then((s) => {
      const n = s?.user?.name || "";
      const e = s?.user?.email || "";
      if (n && !name) setName(n);
      if (e && !email) setEmail(e);
      setSignedIn(!!s?.user);
    });
    (async () => {
      try {
        const res = await sponsorApi.ensureId();
        setSponsorId(res.sponsorId);
      } catch {}
      try {
        setSummary(await sponsorApi.summary());
      } catch {}
      try {
        const res = await sponsorApi.banking();
        setBanking({ ...EMPTY_BANKING, ...res.data.banking });
      } catch {}
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const clearError = (key: string) =>
    setErrors((prev) => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });

  const handleAttachPop = async () => {
    setUploadingPop(true);
    try {
      const url = await pickSponsorPop();
      if (url) setPopUrl(url);
    } catch (err: any) {
      Alert.alert("Upload failed", err?.message || "Please try again.");
    }
    setUploadingPop(false);
  };

  const handleSubmit = async () => {
    const errs: Record<string, string> = {};
    if (!name.trim()) errs.name = "Please enter your name.";
    if (email.trim() && !/^\S+@\S+\.\S+$/.test(email.trim()))
      errs.email = "Please enter a valid email.";
    const amt = parseFloat(amount.replace(/[^\d.]/g, ""));
    if (!Number.isFinite(amt) || amt <= 0)
      errs.amount = "Enter an amount greater than zero.";
    if (!email.trim() && !phone.trim())
      errs.contact = "Add an email or phone number so we can reach you.";
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;

    setSubmitting(true);
    try {
      const res = await sponsorApi.submit({
        name: name.trim(),
        email: email.trim() || undefined,
        phone: phone.trim() || undefined,
        amount: amt,
        popUrl,
      });
      const firstName = name.trim().split(" ")[0] || "friend";
      setSuccess({ sponsorId: res.data.sponsorId, firstName });
    } catch (err: any) {
      Alert.alert("Error", err?.message || "Failed to submit. Please try again.");
    }
    setSubmitting(false);
  };

  return (
    <Modal
      visible
      animationType="slide"
      presentationStyle="fullScreen"
      statusBarTranslucent
      onRequestClose={() => !submitting && onClose()}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.overlay}
      >
        <View style={styles.overlay}>
          <LinearGradient
            colors={[colors.gold, colors.goldLight]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.flameBar}
          />

          {success ? (
            <ScrollView
              contentContainerStyle={styles.successWrap}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <View style={styles.successIcon}>
                <Ionicons name="heart" size={30} color={colors.goldDark} />
              </View>
              <Text style={styles.successTitle}>Thank you, {success.firstName}!</Text>
              <Text style={styles.successText}>
                Your sponsorship pledge has been received. This is your{" "}
                <Text style={styles.successName}>Relate sponsorship ID</Text>:
              </Text>
              <View style={styles.idBox}>
                <Text style={styles.idText}>{success.sponsorId}</Text>
              </View>
              <LinearGradient
                colors={["#151f3a", "#1d2a4d"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.bankingCard}
              >
                <View style={styles.bankingHead}>
                  <Ionicons name="card-outline" size={16} color={colors.goldDark} />
                  <Text style={styles.bankingLabel}>Paying by bank transfer?</Text>
                </View>
                {formatBankingDetails(banking) ? (
                  <View style={styles.bankingRows}>
                    {[
                      ["Bank", banking.bankName],
                      ["Account holder", banking.accountHolder],
                      ["Account number", banking.accountNumber],
                      ["Branch code", banking.branchCode],
                      ["Account type", banking.accountType],
                      ["Reference", banking.reference],
                    ]
                      .filter(([, v]) => v && v.trim())
                      .map(([k, v]) => (
                        <View key={k} style={styles.bankingRow}>
                          <Text style={styles.bankingFieldLabel}>{k}</Text>
                          <Text style={styles.bankingValue}>{v}</Text>
                        </View>
                      ))}
                    {banking.instructions ? (
                      <Text style={styles.bankingInstructions}>{banking.instructions}</Text>
                    ) : null}
                  </View>
                ) : (
                  <Text style={styles.bankingEmpty}>Banking details to be added.</Text>
                )}
              </LinearGradient>
              <TouchableOpacity style={styles.doneBtnWrap} onPress={onClose} activeOpacity={0.85}>
                <LinearGradient
                  colors={["#151f3a", "#1d2a4d"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.doneBtn}
                >
                  <Text style={styles.doneBtnText}>Done</Text>
                </LinearGradient>
              </TouchableOpacity>
            </ScrollView>
          ) : signedIn === false ? (
            <>
              <View style={[styles.header, { paddingTop: insets.top + 18 }]}>
                <View style={styles.headIcon}>
                  <Ionicons name="heart" size={22} color={colors.goldDark} />
                </View>
                <View style={styles.headerTextWrap}>
                  <Text style={styles.title}>Sponsor a Relate</Text>
                  <Text style={styles.sub}>
                    Partner with us in sustainable change.
                  </Text>
                </View>
                <TouchableOpacity style={styles.closeBtn} onPress={onClose}>
                  <Ionicons name="close" size={20} color={colors.muted} />
                </TouchableOpacity>
              </View>
              <View style={styles.gateWrap}>
                <View style={styles.gateIcon}>
                  <Ionicons name="person-circle-outline" size={34} color={colors.goldDark} />
                </View>
                <Text style={styles.gateTitle}>Sign in to sponsor</Text>
                <Text style={styles.gateText}>
                  Your pledge is linked to your account so you can track it and
                  keep your sponsor ID on your dashboard.
                </Text>
                <TouchableOpacity
                  style={styles.gateBtnWrap}
                  activeOpacity={0.85}
                  onPress={() => {
                    onClose();
                    router.push({ pathname: "/login", params: { next: "/" } });
                  }}
                >
                  <LinearGradient
                    colors={["#151f3a", "#1d2a4d"]}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={styles.gateBtn}
                  >
                    <Text style={styles.gateBtnText}>Sign in</Text>
                    <Ionicons name="arrow-forward" size={16} color={colors.white} />
                  </LinearGradient>
                </TouchableOpacity>
                <TouchableOpacity
                  style={styles.gateNotNow}
                  onPress={onClose}
                  activeOpacity={0.8}
                >
                  <Text style={styles.gateNotNowText}>Not now</Text>
                </TouchableOpacity>
              </View>
            </>
          ) : signedIn === null ? (
            <View style={styles.gateWrap}>
              <ActivityIndicator color={colors.goldDark} />
            </View>
          ) : (
            <>
              <View style={[styles.header, { paddingTop: insets.top + 18 }]}>
                <View style={styles.headIcon}>
                  <Ionicons name="heart" size={22} color={colors.goldDark} />
                </View>
                <View style={styles.headerTextWrap}>
                  <Text style={styles.title}>Sponsor a Relate</Text>
                  <Text style={styles.sub}>
                    Partner with us in sustainable change.
                  </Text>
                </View>
                <TouchableOpacity style={styles.closeBtn} onPress={onClose} disabled={submitting}>
                  <Ionicons name="close" size={20} color={colors.muted} />
                </TouchableOpacity>
              </View>

              <ScrollView
                style={styles.scroll}
                contentContainerStyle={styles.form}
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode="none"
                showsVerticalScrollIndicator={false}
              >
                {/* Our work — mini financial report */}
                <View style={styles.workCard}>
                  <View style={styles.workHead}>
                    <Ionicons name="leaf" size={15} color={colors.goldDark} />
                    <Text style={styles.workEyebrow}>OUR WORK</Text>
                  </View>
                  {summary ? (
                    <View style={styles.workStats}>
                      <View style={styles.workStat}>
                        <Text style={styles.workValue}>{fmtMoney(summary.fundsRaised)}</Text>
                        <Text style={styles.workLabel}>funds raised</Text>
                      </View>
                      <View style={styles.workDivider} />
                      <View style={styles.workStat}>
                        <Text style={styles.workValue}>{summary.families}</Text>
                        <Text style={styles.workLabel}>families helped</Text>
                      </View>
                      <View style={styles.workDivider} />
                      <View style={styles.workStat}>
                        <Text style={styles.workValue}>{summary.est}</Text>
                        <Text style={styles.workLabel}>est. since</Text>
                      </View>
                    </View>
                  ) : (
                    <ActivityIndicator color={colors.goldDark} style={{ marginVertical: 14 }} />
                  )}
                </View>

                {/* Banking details */}
                <LinearGradient
                  colors={["#151f3a", "#1d2a4d"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.bankingCard}
                >
                  <View style={styles.bankingHead}>
                    <Ionicons name="card-outline" size={16} color={colors.goldDark} />
                    <Text style={styles.bankingLabel}>Banking details</Text>
                  </View>
                  {formatBankingDetails(banking) ? (
                    <View style={styles.bankingRows}>
                      {[
                        ["Bank", banking.bankName],
                        ["Account holder", banking.accountHolder],
                        ["Account number", banking.accountNumber],
                        ["Branch code", banking.branchCode],
                        ["Account type", banking.accountType],
                        ["Reference", banking.reference],
                      ]
                        .filter(([, v]) => v && v.trim())
                        .map(([k, v]) => (
                          <View key={k} style={styles.bankingRow}>
                            <Text style={styles.bankingFieldLabel}>{k}</Text>
                            <Text style={styles.bankingValue}>{v}</Text>
                          </View>
                        ))}
                      {banking.instructions ? (
                        <Text style={styles.bankingInstructions}>{banking.instructions}</Text>
                      ) : null}
                    </View>
                  ) : (
                    <Text style={styles.bankingEmpty}>Banking details to be added.</Text>
                  )}
                </LinearGradient>

                {/* Full name */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Full name <Text style={styles.req}>*</Text>
                  </Text>
                  <TextInput
                    style={[styles.input, errors.name && styles.inputError]}
                    placeholder="Your name"
                    placeholderTextColor={colors.muted}
                    value={name}
                    onChangeText={(t) => {
                      setName(t);
                      clearError("name");
                    }}
                    editable={!submitting}
                  />
                  {!!errors.name && <Text style={styles.errorText}>{errors.name}</Text>}
                </View>

                {/* Contact */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Email</Text>
                  <TextInput
                    style={[styles.input, errors.email && styles.inputError]}
                    placeholder="you@example.com"
                    placeholderTextColor={colors.muted}
                    value={email}
                    onChangeText={(t) => {
                      setEmail(t);
                      clearError("email");
                      clearError("contact");
                    }}
                    autoCapitalize="none"
                    keyboardType="email-address"
                    editable={!submitting}
                  />
                  {!!errors.email && <Text style={styles.errorText}>{errors.email}</Text>}
                </View>

                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Phone (WhatsApp)</Text>
                  <TextInput
                    style={[styles.input, errors.contact && errors.phone ? styles.inputError : null]}
                    placeholder="+27 00 000 0000"
                    placeholderTextColor={colors.muted}
                    value={phone}
                    onChangeText={(t) => {
                      setPhone(t);
                      clearError("contact");
                    }}
                    keyboardType="phone-pad"
                    editable={!submitting}
                  />
                  {!!errors.contact && <Text style={styles.errorText}>{errors.contact}</Text>}
                </View>

                {/* Amount */}
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Amount (ZAR) <Text style={styles.req}>*</Text>
                  </Text>
                  <TextInput
                    style={[styles.input, errors.amount && styles.inputError]}
                    placeholder="e.g. 500"
                    placeholderTextColor={colors.muted}
                    value={amount}
                    onChangeText={(t) => {
                      setAmount(t);
                      clearError("amount");
                    }}
                    keyboardType="numeric"
                    editable={!submitting}
                  />
                  {!!errors.amount && <Text style={styles.errorText}>{errors.amount}</Text>}
                </View>

                {/* POP (optional) */}
                <TouchableOpacity
                  style={styles.popBtn}
                  onPress={handleAttachPop}
                  disabled={submitting || uploadingPop}
                  activeOpacity={0.8}
                >
                  <View style={styles.popIcon}>
                    <Ionicons
                      name={popUrl ? "checkmark" : "cloud-upload-outline"}
                      size={18}
                      color={colors.goldDark}
                    />
                  </View>
                  <View style={styles.popBody}>
                    <Text style={styles.popTitle}>
                      {uploadingPop ? "Uploading…" : popUrl ? "POP attached" : "Proof of payment (optional)"}
                    </Text>
                    <Text style={styles.popSub}>
                      {uploadingPop
                        ? "Please wait…"
                        : popUrl
                          ? "Tap to replace"
                          : "Snap or pick your payment confirmation"}
                    </Text>
                  </View>
                </TouchableOpacity>

                {/* Submit */}
                <TouchableOpacity
                  style={[styles.submitBtnWrap, submitting && styles.submitBtnDisabled]}
                  onPress={handleSubmit}
                  disabled={submitting}
                  activeOpacity={0.85}
                >
                  <LinearGradient
                    colors={["#151f3a", "#1d2a4d"]}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={styles.submitBtn}
                  >
                    {submitting ? (
                      <ActivityIndicator color={colors.white} />
                    ) : (
                      <Text style={styles.submitText}>Submit pledge</Text>
                    )}
                  </LinearGradient>
                </TouchableOpacity>
                {sponsorId ? (
                  <View style={styles.sponsorIdCard}>
                    <Ionicons name="finger-print-outline" size={16} color={colors.goldDark} />
                    <View style={styles.sponsorIdBody}>
                      <Text style={styles.sponsorIdLabel}>Your Relate sponsor ID</Text>
                      <Text style={styles.sponsorIdValue}>{sponsorId}</Text>
                    </View>
                  </View>
                ) : (
                  <Text style={styles.idHint}>
                    Your sponsor ID is created with your first pledge and stays
                    with you on every pledge after.
                  </Text>
                )}
              </ScrollView>
            </>
          )}
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

