import { Ionicons } from "@expo/vector-icons";
import { useState } from "react";
import {
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { colors } from "@/constants/colors";
import type { InteractiveBlock } from "@/data/publications/types";
import type { DayResponses } from "@/services/reading-responses";

/**
 * Interactive blocks for seasonal study-guide daily reads, styled to match
 * the admin preview's flat gray card design.
 *
 * Each block is a self-contained widget with local UI state seeded from
 * `saved` (server + in-memory drafts). A change is pushed upward with the raw
 * server value for that block id:
 *   checklist / pray -> number[] of checked indices
 *   quiz          -> number of the selected option (immediate feedback)
 *   reflection    -> string
 */

type Props = {
  blocks: InteractiveBlock[];
  saved: DayResponses;
  onChange: (blockId: string, value: unknown) => void;
  onFlush?: () => void;
};

export function InteractiveBlocks({ blocks, saved, onChange, onFlush }: Props) {
  return (
    <View style={s.wrap}>
      {blocks.map((block) => {
        switch (block.type) {
          case "checklist":
            return (
              <ChecklistBlock key={block.id} block={block} saved={saved} onChange={onChange} />
            );
          case "quiz":
            return <QuizBlock key={block.id} block={block} saved={saved} onChange={onChange} />;
          case "reflection":
            return (
              <ReflectionBlock
                key={block.id}
                block={block}
                saved={saved}
                onChange={onChange}
                onFlush={onFlush}
              />
            );
          case "pray":
            return (
              <PrayBlock key={block.id} block={block} saved={saved} onChange={onChange} onFlush={onFlush} />
            );
          default:
            return null;
        }
      })}
    </View>
  );
}

function Card({ children }: { children: React.ReactNode }) {
  return <View style={s.card}>{children}</View>;
}

function ChecklistBlock({
  block,
  saved,
  onChange,
}: {
  block: Extract<InteractiveBlock, { type: "checklist" }>;
  saved: DayResponses;
  onChange: Props["onChange"];
}) {
  const [checked, setChecked] = useState<number[]>(
    Array.isArray(saved[block.id]) ? (saved[block.id] as number[]) : [],
  );

  const toggle = (index: number) => {
    const next = checked.includes(index)
      ? checked.filter((i) => i !== index)
      : [...checked, index];
    setChecked(next);
    onChange(block.id, next);
  };

  return (
    <Card>
      <Text style={s.cardTitle}>{block.title || "Try it today"}</Text>
      {block.items.map((item, index) => {
        const on = checked.includes(index);
        return (
          <TouchableOpacity
            key={index}
            onPress={() => toggle(index)}
            style={s.row}
            activeOpacity={0.7}
          >
            <View style={[s.checkBox, on && s.checkBoxOn]}>
              {on ? (
                <Ionicons name="checkmark" size={10} color={colors.white} />
              ) : null}
            </View>
            <Text style={[s.rowText, on && s.rowTextOn]}>{item}</Text>
          </TouchableOpacity>
        );
      })}
    </Card>
  );
}

function QuizBlock({
  block,
  saved,
  onChange,
}: {
  block: Extract<InteractiveBlock, { type: "quiz" }>;
  saved: DayResponses;
  onChange: Props["onChange"];
}) {
  const [selected, setSelected] = useState<number | null>(
    typeof saved[block.id] === "number" ? (saved[block.id] as number) : null,
  );
  const answered = selected !== null;

  const pick = (index: number) => {
    setSelected(index);
    onChange(block.id, index);
  };

  return (
    <Card>
      <Text style={s.cardTitle}>{block.question}</Text>
      {block.options.map((option, index) => {
        const isSelected = selected === index;
        const isCorrect = answered && index === block.correctIndex;
        const isWrongPick = answered && isSelected && index !== block.correctIndex;
        return (
          <TouchableOpacity
            key={index}
            onPress={() => pick(index)}
            style={[
              s.row,
              isCorrect && s.rowCorrect,
              isWrongPick && s.rowWrong,
            ]}
            activeOpacity={0.7}
          >
            <View style={[s.radioDot, isSelected && s.radioDotOn]} />
            <Text style={s.rowText}>{option}</Text>
            {isCorrect ? (
              <Ionicons name="checkmark-circle" size={16} color={colors.success} />
            ) : isWrongPick ? (
              <Ionicons name="close-circle" size={16} color={colors.error} />
            ) : null}
          </TouchableOpacity>
        );
      })}
      {answered && block.explain ? (
        <Text style={[s.explain, selected === block.correctIndex && s.explainGood]}>
          {selected === block.correctIndex ? "Correct — " : ""}
          {block.explain}
        </Text>
      ) : null}
    </Card>
  );
}

function ReflectionBlock({
  block,
  saved,
  onChange,
  onFlush,
}: {
  block: Extract<InteractiveBlock, { type: "reflection" }>;
  saved: DayResponses;
  onChange: Props["onChange"];
  onFlush?: Props["onFlush"];
}) {
  const [text, setText] = useState(
    typeof saved[block.id] === "string" ? (saved[block.id] as string) : "",
  );

  return (
    <Card>
      <Text style={s.prompt}>{block.prompt}</Text>
      <TextInput
        style={s.reflectInput}
        multiline
        value={text}
        onChangeText={(value) => {
          setText(value);
          onChange(block.id, value);
        }}
        onBlur={onFlush}
        placeholder={block.placeholder || "Write your thoughts here…"}
        placeholderTextColor={colors.gray[400]}
        maxLength={2000}
      />
    </Card>
  );
}

function PrayBlock({
  block,
  saved,
  onChange,
  onFlush,
}: {
  block: Extract<InteractiveBlock, { type: "pray" }>;
  saved: DayResponses;
  onChange: Props["onChange"];
  onFlush?: Props["onFlush"];
}) {
  const [prayed, setPrayed] = useState<number[]>(
    Array.isArray(saved[block.id]) ? (saved[block.id] as number[]) : [],
  );

  const toggle = (index: number) => {
    const next = prayed.includes(index)
      ? prayed.filter((i) => i !== index)
      : [...prayed, index];
    setPrayed(next);
    onChange(block.id, next);
    onFlush?.();
  };

  return (
    <Card>
      <View style={s.prayHeader}>
        <Ionicons name="heart" size={14} color={colors.muted} />
        <Text style={s.cardTitle}>{block.title || "Pray it today"}</Text>
      </View>
      {block.items.map((item, index) => {
        const on = prayed.includes(index);
        return (
          <TouchableOpacity
            key={index}
            onPress={() => toggle(index)}
            style={s.row}
            activeOpacity={0.7}
          >
            <View style={[s.bulletDot, on && s.bulletDotOn]} />
            <Text style={[s.rowText, on && s.rowTextOn]}>{item}</Text>
          </TouchableOpacity>
        );
      })}
    </Card>
  );
}

