import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import { StatusBar } from "expo-status-bar";
import { useRouter } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { getSession } from "@/services/auth";
import { useCart } from "@/services/cart";
import { ordersApi } from "@/services/orders";
import { formatPrice } from "@/services/store";
import { getOptimizedImageUrl } from "@/services/cloudinary";
import { GradientBox } from "@/constants/gradients";

/**
 * Checkout — delivery contact + order review. Submitting POSTs the cart to
 * /api/orders (the backend re-prices everything against the catalogue), then
 * swaps this screen for the receipt so a back gesture can't resubmit it.
 */
export default function CheckoutScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const { lines, subtotal, clear } = useCart();

  const [checkingAuth, setCheckingAuth] = useState(true);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [note, setNote] = useState("");
  const [errors, setErrors] = useState<{ name?: string; phone?: string; email?: string }>({});
  const [submitting, setSubmitting] = useState(false);

  // Signed-in buyers skip the form's identity fields.
  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((session) => {
        if (cancelled) return;
        if (!session?.user) {
          router.replace({ pathname: "/login", params: { next: "/checkout" } });
          return;
        }
        setName((n) => n || session.user.name || "");
        setEmail((e) => e || session.user.email || "");
        setCheckingAuth(false);
      })
      .catch(() => {
        if (!cancelled) {
          router.replace({ pathname: "/login", params: { next: "/checkout" } });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [router]);

  const validate = () => {
    const next: typeof errors = {};
    if (!name.trim()) next.name = "Your name is required";
    if (!phone.trim()) next.phone = "A contact number is required";
    else if (phone.trim().replace(/\D/g, "").length < 7)
      next.phone = "That number looks too short";
    if (email.trim() && !/^\S+@\S+\.\S+$/.test(email.trim()))
      next.email = "Check the email address";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const submit = async () => {
    if (lines.length === 0 || submitting) return;
    if (!validate()) return;

    setSubmitting(true);
    try {
      const res = await ordersApi.place(lines, {
        name: name.trim(),
        phone: phone.trim(),
        email: email.trim() || undefined,
        note: note.trim() || undefined,
      });
      const order = res.data.order;
      clear();
      router.replace({ pathname: "/order/[id]" as any, params: { id: order._id } });
    } catch (err: any) {
      const message = String(err?.message || "Couldn't place your order");
      if (message.toLowerCase().includes("sign in")) {
        router.replace({ pathname: "/login", params: { next: "/checkout" } });
        return;
      }
      Alert.alert("Order not placed", message, [{ text: "OK" }]);
    } finally {
      setSubmitting(false);
    }
  };

  if (checkingAuth) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={styles.loading}>
            <ActivityIndicator color={colors.forest} size="large" />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />

        <View style={styles.bar}>
          <TouchableOpacity
            style={styles.iconBtn}
            onPress={() => router.back()}
            accessibilityRole="button"
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={22} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={styles.barTitle}>Checkout</Text>
            <Text style={styles.barSub}>Where should we send it?</Text>
          </View>
          <View style={styles.iconBtn} />
        </View>

        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          keyboardVerticalOffset={24}
        >
          <ScrollView
            showsVerticalScrollIndicator={false}
            contentContainerStyle={styles.scroll}
            keyboardShouldPersistTaps="handled"
          >
            {/* Items being ordered */}
            <View style={styles.card}>
              <Text style={styles.cardTitle}>
                Your order · {lines.length} line{lines.length === 1 ? "" : "s"}
              </Text>
              {lines.map((l) => (
                <View key={`${l.itemId}:${l.size ?? ""}`} style={styles.itemRow}>
                  <Image source={{ uri: getOptimizedImageUrl(l.image, 720) }} style={styles.itemImg} contentFit="cover" />
                  <View style={{ flex: 1 }}>
                    <Text style={styles.itemName} numberOfLines={1}>
                      {l.name}
                    </Text>
                    <Text style={styles.itemMeta}>
                      {l.size ? `Size ${l.size} · ` : ""}
                      {l.qty} × {formatPrice(l.price)}
                    </Text>
                  </View>
                  <Text style={styles.itemTotal}>
                    {formatPrice(l.price * l.qty)}
                  </Text>
                </View>
              ))}
              <View style={styles.divider} />
              <View style={styles.totalRow}>
                <Text style={styles.totalLabel}>Total due</Text>
                <Text style={styles.totalValue}>{formatPrice(subtotal)}</Text>
              </View>
            </View>

            {/* Contact */}
            <View style={styles.card}>
              <Text style={styles.cardTitle}>Contact details</Text>

              <Text style={styles.label}>Full name</Text>
              <TextInput
                style={[styles.input, errors.name && styles.inputError]}
                value={name}
                onChangeText={(v) => {
                  setName(v);
                  if (errors.name) setErrors((e) => ({ ...e, name: undefined }));
                }}
                placeholder="Your name"
                placeholderTextColor={colors.muted}
                autoCapitalize="words"
                returnKeyType="next"
              />
              {!!errors.name && <Text style={styles.error}>{errors.name}</Text>}

              <Text style={styles.label}>Contact number</Text>
              <TextInput
                style={[styles.input, errors.phone && styles.inputError]}
                value={phone}
                onChangeText={(v) => {
                  setPhone(v);
                  if (errors.phone) setErrors((e) => ({ ...e, phone: undefined }));
                }}
                placeholder="072 123 4567"
                placeholderTextColor={colors.muted}
                keyboardType="phone-pad"
              />
              {!!errors.phone && <Text style={styles.error}>{errors.phone}</Text>}

              <Text style={styles.label}>Email (optional)</Text>
              <TextInput
                style={[styles.input, errors.email && styles.inputError]}
                value={email}
                onChangeText={(v) => {
                  setEmail(v);
                  if (errors.email) setErrors((e) => ({ ...e, email: undefined }));
                }}
                placeholder="you@example.com"
                placeholderTextColor={colors.muted}
                keyboardType="email-address"
                autoCapitalize="none"
                autoCorrect={false}
              />
              {!!errors.email && <Text style={styles.error}>{errors.email}</Text>}

              <Text style={styles.label}>Notes for us (optional)</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={note}
                onChangeText={setNote}
                placeholder="Colour preference, delivery window, a gift message…"
                placeholderTextColor={colors.muted}
                multiline
                textAlignVertical="top"
                maxLength={500}
              />
            </View>

            {/* Payment instructions */}
            <View style={styles.card}>
              <View style={styles.payHead}>
                <Ionicons name="wallet-outline" size={18} color={colors.forest} />
                <Text style={styles.cardTitle}>Payment by EFT</Text>
              </View>
              <Text style={styles.payText}>
                Place the order, then transfer the total to our bank account.
                Your receipt carries the order number as the payment reference
                plus our banking details — send us the proof of payment and an
                admin marks it paid.
              </Text>
            </View>
          </ScrollView>

          <View style={[styles.footer, { paddingBottom: Math.max(12, insets.bottom) }]}>
            <TouchableOpacity
              style={[styles.payBtn, submitting && styles.payBtnOff]}
              onPress={submit}
              disabled={submitting || lines.length === 0}
              activeOpacity={0.9}
              accessibilityRole="button"
              accessibilityLabel="Place order"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              {submitting ? (
                <ActivityIndicator color={colors.white} />
              ) : (
                <>
                  <Text style={styles.payText2}>Place order</Text>
                  <Text style={styles.payTotal}>{formatPrice(subtotal)}</Text>
                </>
              )}
            </TouchableOpacity>
          </View>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  loading: { flex: 1, alignItems: "center", justifyContent: "center" },
  bar: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  iconBtn: {
    width: 42,
    height: 42,
    borderRadius: 21,
    backgroundColor: colors.white,
    alignItems: "center",
    justifyContent: "center",
  },
  barTitle: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 20,
    letterSpacing: -0.4,
    color: colors.ink,
  },
  barSub: { fontFamily: fonts.sans, fontSize: 12, color: colors.muted, marginTop: 1 },
  scroll: { padding: 16, paddingBottom: 140 },
  card: {
    backgroundColor: colors.white,
    borderRadius: 20,
    padding: 16,
    marginBottom: 14,
  },
  cardTitle: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 10,
    letterSpacing: 1.6,
    textTransform: "uppercase",
    color: colors.ink,
    marginBottom: 12,
  },
  itemRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
    marginBottom: 10,
  },
  itemImg: {
    width: 44,
    height: 44,
    borderRadius: 10,
    backgroundColor: colors.cream,
  },
  itemName: {
    fontFamily: fonts.sansSemiBold,
    fontWeight: "600",
    fontSize: 13,
    color: colors.ink,
  },
  itemMeta: { fontFamily: fonts.sans, fontSize: 11.5, color: colors.muted, marginTop: 2 },
  itemTotal: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 13,
    color: colors.ink,
  },
  divider: {
    height: 1,
    backgroundColor: "rgba(11,25,44,0.08)",
    marginVertical: 6,
  },
  totalRow: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    marginTop: 4,
  },
  totalLabel: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 14,
    color: colors.ink,
  },
  totalValue: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 20,
    color: colors.ink,
  },
  label: {
    fontFamily: fonts.sansSemiBold,
    fontWeight: "600",
    fontSize: 12,
    color: colors.ink,
    marginBottom: 6,
    marginTop: 4,
  },
  input: {
    minHeight: 48,
    borderRadius: 14,
    backgroundColor: colors.bgSoft,
    paddingHorizontal: 14,
    paddingVertical: 12,
    fontFamily: fonts.sans,
    fontSize: 15,
    color: colors.ink,
    borderWidth: 1,
    borderColor: "transparent",
  },
  textarea: { minHeight: 92, paddingTop: 12 },
  inputError: { borderColor: colors.error },
  error: {
    fontFamily: fonts.sans,
    fontSize: 12,
    color: colors.error,
    marginTop: 5,
  },
  payHead: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    marginBottom: 4,
  },
  payText: {
    fontFamily: fonts.sans,
    fontSize: 12.5,
    lineHeight: 18,
    color: colors.muted,
  },
  footer: {
    position: "absolute",
    left: 0,
    right: 0,
    bottom: 0,
    paddingHorizontal: 16,
    paddingTop: 12,
    paddingBottom: 26,
    backgroundColor: colors.bg,
    borderTopWidth: 1,
    borderTopColor: "rgba(11,25,44,0.08)",
  },
  payBtn: {
    overflow: "hidden",
    minHeight: 54,
    borderRadius: 27,
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 12,
  },
  payBtnOff: { opacity: 0.6 },
  payText2: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 15,
    color: colors.white,
  },
  payTotal: {
    fontFamily: fonts.sansBold,
    fontWeight: "700",
    fontSize: 15,
    color: colors.goldLight,
  },
});
