import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { Ionicons } from "@expo/vector-icons";
import { Image as ExpoImage } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { memo } from "react";
import {
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  useWindowDimensions,
} from "react-native";
import { getOptimizedImageUrl } from "@/services/cloudinary";

export type HeroSlide = {
  key: string;
  image: string;
  /** Brand gradient beneath the photo (club colors), as on the club hero. */
  gradient: [string, string, string];
  /** White pill above the title (age band / status), like the member chip. */
  chip?: string;
  title: string;
  tagline?: string;
  description?: string;
  meta: { label: string; value: string }[];
  cta: { label: string; onPress: () => void };
  /** Outline button under the primary one (the club hero's ghost action). */
  ghostCta?: { label: string; onPress: () => void };
};

/**
 * Landing carousel slide built like a club detail hero — white pill,
 * oversized title, tagline, primary action and meta bar.
 */
function LandingHeroSlide({ slide }: { slide: HeroSlide }) {
  const { height: winH } = useWindowDimensions();
  return (
    <View
      style={[s.hero, { height: Math.max(Math.round(winH * 0.54), 500) }]}
    >
      {/* Brand gradient base — visible under the photo while it loads */}
      <LinearGradient
        colors={slide.gradient}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFill}
      />
      <ExpoImage
        source={{ uri: getOptimizedImageUrl(slide.image, 1200) }}
        style={StyleSheet.absoluteFill}
        contentFit="cover"
        transition={250}
        accessibilityLabel={slide.title}
      />
      <View style={s.body}>
        {slide.chip ? (
          <View style={s.chip}>
            <Text style={s.chipText}>{slide.chip}</Text>
          </View>
        ) : null}
        <Text style={s.title} numberOfLines={2}>
          {slide.title}
        </Text>
        {slide.tagline ? (
          <Text style={s.tagline} numberOfLines={2}>
            {slide.tagline}
          </Text>
        ) : null}

        <View style={s.actions}>
          <TouchableOpacity
            style={s.join}
            activeOpacity={0.9}
            onPress={slide.cta.onPress}
            accessibilityRole="button"
            accessibilityLabel={slide.cta.label}
          >
            <Text style={s.joinText}>{slide.cta.label}</Text>
            <Ionicons name="arrow-forward" size={16} color={colors.forestDark} />
          </TouchableOpacity>
        </View>

        <View style={s.divider} />

        <View style={s.metaBar}>
          {slide.meta.map((m) => (
            <View key={m.label} style={s.metaItem}>
              <Text style={s.metaLabel}>{m.label}</Text>
              <Text style={s.metaValue}>{m.value}</Text>
            </View>
          ))}
        </View>
      </View>
    </View>
  );
}

