import { Ionicons } from "@expo/vector-icons";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { colors } from "@/constants/colors";
import { GradientBox } from "@/constants/gradients";

export default function EmptyState({
  icon = "leaf-outline",
  color = colors.gold,
  eyebrow,
  title,
  subtitle,
  actionLabel,
  onAction,
  compact = false,
}: {
  icon?: any;
  color?: string;
  eyebrow?: string;
  title: string;
  subtitle?: string;
  actionLabel?: string;
  onAction?: () => void;
  compact?: boolean;
}) {
  return (
    <View style={[styles.wrap, compact && styles.wrapCompact]}>
      <View style={[styles.badgeWrap, compact && styles.badgeWrapCompact]}>
        <LinearGradient
          colors={[`${color}22`, `${color}0d`]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[styles.badge, compact && styles.badgeCompact]}
        >
          <View style={[styles.badgeRing, compact && styles.badgeRingCompact, { borderColor: `${color}40` }]}>
            <Ionicons
              name={icon}
              size={compact ? 20 : 30}
              color={color}
            />
          </View>
        </LinearGradient>
      </View>

      {!!eyebrow && (
        <View style={[styles.eyebrowPill, { backgroundColor: `${color}14` }]}>
          <Text style={[styles.eyebrowText, { color }]}>{eyebrow}</Text>
        </View>
      )}

      <Text style={[styles.title, compact && styles.titleCompact]}>{title}</Text>
      {!!subtitle && <Text style={styles.subtitle}>{subtitle}</Text>}

      {!!actionLabel && !!onAction && (
        <TouchableOpacity
          style={styles.actionBtn}
          onPress={onAction}
          activeOpacity={0.85}
        >
          <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
          <Text style={styles.actionText}>{actionLabel}</Text>
        </TouchableOpacity>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    alignItems: "center",
    paddingVertical: 52,
    paddingHorizontal: 32,
  },
  wrapCompact: {
    paddingVertical: 32,
  },
  badgeWrap: {
    marginBottom: 20,
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.08,
    shadowRadius: 12,
    elevation: 2,
  },
  badgeWrapCompact: {
    marginBottom: 14,
  },
  badge: {
    width: 92,
    height: 92,
    borderRadius: 30,
    alignItems: "center",
    justifyContent: "center",
  },
  badgeCompact: {
    width: 64,
    height: 64,
    borderRadius: 20,
  },
  badgeRing: {
    width: 62,
    height: 62,
    borderRadius: 22,
    borderWidth: 1.5,
    backgroundColor: "rgba(255,255,255,0.85)",
    alignItems: "center",
    justifyContent: "center",
  },
  badgeRingCompact: {
    width: 44,
    height: 44,
    borderRadius: 15,
    borderWidth: 1,
  },
  eyebrowPill: {
    paddingHorizontal: 12,
    paddingVertical: 5,
    borderRadius: 999,
    marginBottom: 12,
  },
  eyebrowText: {
    fontSize: 10,
    textTransform: "uppercase",
    letterSpacing: 1.8,
    fontWeight: "700",
    fontFamily: "Poppins_700Bold",
  },
  title: {
    fontSize: 20,
    fontWeight: "700",
    fontFamily: "Poppins_700Bold",
    color: colors.forestDark,
    textAlign: "center",
  },
  titleCompact: {
    fontSize: 14,
  },
  subtitle: {
    fontSize: 11,
    fontWeight: "400",
    fontFamily: "Poppins_400Regular",
    color: colors.muted,
    textAlign: "center",
    lineHeight: 15,
    marginTop: 7,
    maxWidth: 300,
  },
  actionBtn: {
    overflow: "hidden",
    marginTop: 20,
    paddingHorizontal: 24,
    paddingVertical: 12,
    borderRadius: 999,
    shadowColor: colors.forest,
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.2,
    shadowRadius: 8,
    elevation: 3,
  },
  actionText: {
    fontSize: 13,
    fontWeight: "700",
    fontFamily: "Poppins_700Bold",
    color: colors.white,
  },
});
