import { router } from "expo-router";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  InteractionManager,
  KeyboardAvoidingView,
  Platform,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import BoardHeader from "@/components/board/BoardHeader";
import MeetingSchedulerForm from "@/components/board/MeetingSchedulerForm";
import { boardStyles as s } from "@/components/board/styles";
import {
  boardApi,
  type BoardMeeting,
  type BoardMeetingCard,
} from "@/services/board-governance";

function shortDate(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  const day = date.toLocaleDateString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
  const time = date.toLocaleTimeString("en-ZA", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
  return `${day} · ${time}`;
}

function dateBadge(value: string | null): { day: string; month: string } | null {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return {
    day: date.toLocaleDateString("en-ZA", { day: "numeric" }),
    month: date.toLocaleDateString("en-ZA", { month: "short" }),
  };
}

export default function BoardScheduleScreen() {
  const insets = useSafeAreaInsets();
  const scrollRef = useRef<ScrollView>(null);
  const [meetings, setMeetings] = useState<BoardMeetingCard[]>([]);
  const [past, setPast] = useState<BoardMeetingCard[]>([]);
  const [editing, setEditing] = useState<BoardMeeting | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [openingId, setOpeningId] = useState("");
  const [deleting, setDeleting] = useState("");

  const load = useCallback(async () => {
    try {
      const [upcoming, history] = await Promise.all([
        boardApi.listMeetingCards("upcoming"),
        boardApi.listMeetingCards("past"),
      ]);
      setMeetings(upcoming.data || []);
      setPast((history.data || []).slice(0, 5));
    } catch (e: any) {
      Alert.alert("Could not load meetings", e?.message || "Please try again.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      void load();
    });
    return () => task.cancel();
  }, [load]);

  const onRefresh = () => {
    setRefreshing(true);
    void load();
  };

  const open = (meeting: BoardMeetingCard) => {
    router.push(`/admin/board-governance/meetings/${meeting._id}` as any);
  };

  const startEdit = async (meeting: BoardMeetingCard) => {
    if (openingId) return;
    setOpeningId(meeting._id);
    try {
      const res = await boardApi.getMeeting(meeting._id);
      setEditing(res.data);
      scrollRef.current?.scrollTo({ y: 0, animated: true });
    } catch (e: any) {
      Alert.alert("Could not open the meeting", e?.message || "Please try again.");
    } finally {
      setOpeningId("");
    }
  };

  const remove = async (meeting: BoardMeetingCard) => {
    setDeleting(meeting._id);
    try {
      await boardApi.deleteMeeting(meeting._id);
      setMeetings((current) => current.filter((item) => item._id !== meeting._id));
      setPast((current) => current.filter((item) => item._id !== meeting._id));
      setEditing((current) => (current?._id === meeting._id ? null : current));
    } catch (e: any) {
      Alert.alert("Could not delete", e?.message || "Please try again.");
    } finally {
      setDeleting("");
    }
  };

  const confirmDelete = (meeting: BoardMeetingCard) => {
    Alert.alert(
      "Delete this meeting?",
      `${meeting.title} will be removed from the schedule and the board will be told. This cannot be undone.`,
      [
        { text: "Keep it", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: () => void remove(meeting),
        },
      ],
    );
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <BoardHeader title="Meeting schedule" />
        <KeyboardAvoidingView
          style={styles.flex}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
        >
          <ScrollView
            ref={scrollRef}
            contentContainerStyle={[
              styles.content,
              { paddingBottom: 36 + insets.bottom },
            ]}
            showsVerticalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
            keyboardDismissMode="none"
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={onRefresh}
                tintColor={colors.goldDark}
                colors={[colors.goldDark]}
              />
            }
          >
            <MeetingSchedulerForm
              key={editing?._id ?? "new"}
              meeting={editing}
              onCancelEdit={() => setEditing(null)}
              onSaved={(meeting) => {
                const card: BoardMeetingCard = {
                  _id: meeting._id,
                  title: meeting.title,
                  scheduledDate: meeting.scheduledDate,
                  location: meeting.location,
                  meetingLink: meeting.meetingLink,
                  status: meeting.status,
                };
                setMeetings((current) =>
                  current.some((item) => item._id === card._id)
                    ? current.map((item) => (item._id === card._id ? card : item))
                    : [card, ...current],
                );
                setEditing(null);
              }}
            />

            <View style={styles.sectionHead}>
              <Text style={styles.sectionTitle}>Upcoming sittings</Text>
              <Text style={styles.sectionMeta}>{meetings.length}</Text>
            </View>

            {loading ? (
              <View style={s.center}>
                <ActivityIndicator color={colors.goldDark} size="large" />
              </View>
            ) : meetings.length === 0 ? (
              <View style={s.emptyBox}>
                <Ionicons name="calendar-outline" size={22} color={colors.muted} />
                <Text style={s.emptyTitle}>Nothing on the calendar</Text>
                <Text style={s.emptyBody}>
                  Schedule the next sitting above and everyone on the board is notified.
                </Text>
              </View>
            ) : (
              meetings.map((meeting) => {
                const badge = dateBadge(meeting.scheduledDate);
                return (
                  <View key={meeting._id} style={styles.row}>
                    <TouchableOpacity
                      style={styles.rowMain}
                      onPress={() => open(meeting)}
                      activeOpacity={0.85}
                      accessibilityLabel={`View details for ${meeting.title}`}
                    >
                      <View style={styles.dateBadge}>
                        <Text style={styles.dateDay}>{badge?.day ?? "—"}</Text>
                        <Text style={styles.dateMonth}>{badge?.month ?? "TBC"}</Text>
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={styles.rowTitle} numberOfLines={2}>
                          {meeting.title}
                        </Text>
                        <Text style={styles.rowMeta} numberOfLines={2}>
                          {shortDate(meeting.scheduledDate)}
                          {meeting.location ? ` · ${meeting.location}` : ""}
                        </Text>
                      </View>
                    </TouchableOpacity>
                    <TouchableOpacity
                      onPress={() => void startEdit(meeting)}
                      disabled={!!openingId}
                      activeOpacity={0.8}
                      style={styles.iconBtn}
                      accessibilityLabel={`Edit ${meeting.title}`}
                    >
                      {openingId === meeting._id ? (
                        <ActivityIndicator size="small" color={colors.goldDark} />
                      ) : (
                        <Ionicons name="create-outline" size={16} color={colors.goldDark} />
                      )}
                    </TouchableOpacity>
                    <TouchableOpacity
                      onPress={() => confirmDelete(meeting)}
                      disabled={deleting === meeting._id}
                      activeOpacity={0.8}
                      style={styles.deleteBtn}
                      accessibilityLabel={`Delete ${meeting.title}`}
                    >
                      {deleting === meeting._id ? (
                        <ActivityIndicator size="small" color="#be123c" />
                      ) : (
                        <Ionicons name="trash-outline" size={15} color="#be123c" />
                      )}
                    </TouchableOpacity>
                  </View>
                );
              })
            )}

            {past.length > 0 ? (
              <>
                <View style={styles.sectionHead}>
                  <Text style={styles.sectionTitle}>Past sittings</Text>
                  <TouchableOpacity
                    onPress={() => router.push("/admin/board-governance/upload-minutes" as any)}
                  >
                    <Text style={s.addLink}>Log minutes</Text>
                  </TouchableOpacity>
                </View>
                <View style={styles.pastList}>
                  {past.map((meeting) => (
                    <View key={meeting._id} style={styles.pastRow}>
                      <TouchableOpacity
                        style={styles.pastMain}
                        onPress={() => open(meeting)}
                        activeOpacity={0.85}
                        accessibilityLabel={`View details for ${meeting.title}`}
                      >
                        <Text style={styles.pastTitle} numberOfLines={2}>
                          {meeting.title}
                        </Text>
                        <Text style={styles.pastMeta}>{shortDate(meeting.scheduledDate)}</Text>
                      </TouchableOpacity>
                      <View
                        style={[
                          styles.countPill,
                          {
                            backgroundColor:
                              meeting.status === "CANCELLED" ? "#ffe4e6" : colors.bg,
                          },
                        ]}
                      >
                        <Text
                          style={[
                            styles.countText,
                            {
                              color:
                                meeting.status === "CANCELLED" ? "#be123c" : colors.muted,
                            },
                          ]}
                        >
                          {meeting.status === "COMPLETED"
                            ? "Minuted"
                            : meeting.status === "CANCELLED"
                              ? "Cancelled"
                              : "Awaiting minutes"}
                        </Text>
                      </View>
                      <TouchableOpacity
                        onPress={() => confirmDelete(meeting)}
                        disabled={deleting === meeting._id}
                        activeOpacity={0.8}
                        style={styles.deleteBtn}
                        accessibilityLabel={`Delete ${meeting.title}`}
                      >
                        {deleting === meeting._id ? (
                          <ActivityIndicator size="small" color="#be123c" />
                        ) : (
                          <Ionicons name="trash-outline" size={15} color="#be123c" />
                        )}
                      </TouchableOpacity>
                    </View>
                  ))}
                </View>
              </>
            ) : null}
          </ScrollView>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

