// Sender names get their own colour so a busy 40–50 member thread is easy to
// follow. The palette spreads across the hue wheel and every colour is dark
// enough to read on the light thread background; the assignment hashes the
// sender id, so a member keeps the same colour on every device and session
// (plain randomness would reshuffle them on each render).
const SENDER_NAME_COLORS = [
  "#b3352c", // red
  "#c2410c", // burnt orange
  "#a16207", // ochre
  "#4d7c0f", // olive
  "#15803d", // green
  "#0f766e", // teal
  "#0e7490", // cyan
  "#1d4ed8", // blue
  "#4338ca", // indigo
  "#6d28d9", // violet
  "#a21caf", // fuchsia
  "#be185d", // pink
  "#9f1239", // rose
  "#854d0e", // bronze
  "#166534", // forest
  "#0c4a6e", // ocean
  "#312e81", // navy
  "#581c87", // deep purple
  "#701a35", // burgundy
  "#3f6212", // moss
  "#134e4a", // deep teal
  "#7c2d12", // rust
  "#1e3a8a", // royal blue
  "#4a044e", // plum
];

function senderNameColor(seed: string): string {
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 33 + seed.charCodeAt(i)) >>> 0;
  }
  return SENDER_NAME_COLORS[hash % SENDER_NAME_COLORS.length];
}

const QUICK_REACTIONS = ["❤️", "🙏", "😂", "👍", "🔥", "😮"];

// The composer offers member suggestions while the last word starts with @.
const MENTION_TAIL = /(?:^|\s)@([\p{L}\p{N}_-]*)$/u;
// Mentions must start the text or follow whitespace, so emails stay plain.
const MENTION_TOKEN = /((?:^|\s)@[\p{L}\p{N}_-]+)/u;

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// A message made of only emoji (and spaces) renders bubble-less so the glyphs
// show at full size. Capped at three so a wall of emoji keeps normal wrapping.
const EMOJI_ONLY_PATTERN =
  /^[\p{Extended_Pictographic}\p{Emoji_Modifier}\p{Emoji_Modifier_Base}\p{Regional_Indicator}\u200d\ufe0f\u20e3\s]+$/u;
const EMOJI_GLYPH = /[\p{Extended_Pictographic}\p{Regional_Indicator}]/u;

function isEmojiOnlyMessage(text?: string): boolean {
  const value = text?.trim();
  if (!value || !EMOJI_ONLY_PATTERN.test(value)) return false;
  const glyphs = [...value].filter((ch) => EMOJI_GLYPH.test(ch)).length;
  return glyphs > 0 && glyphs <= 3;
}

/** Message text with @mentions picked out in their own colour. */
function MentionText({
  text,
  mine,
  palette,
  style,
}: {
  text: string;
  mine: boolean;
  palette: ChatPalette;
  style?: StyleProp<TextStyle>;
}) {
  const parts = text.split(MENTION_TOKEN);
  return (
    <Text style={style}>
      {parts.map((part, index) =>
        index % 2 === 1 ? (
          <Text
            key={index}
            style={[
              mine ? s.mentionMine : s.mentionOther,
              { color: mine ? palette.mineText : palette.accentDeep },
            ]}
          >
            {part}
          </Text>
        ) : (
          part
        )
      )}
    </Text>
  );
}

/** The quoted original shown inside a reply bubble. */
function ReplyQuote({
  reply,
  mine,
  palette,
}: {
  reply: NonNullable<ChatMessage["replyTo"]>;
  mine: boolean;
  palette: ChatPalette;
}) {
  return (
    <View
      style={[
        s.replyQuote,
        mine
          ? {
              borderLeftColor: palette.mineText,
              backgroundColor: palette.accentSoft,
            }
          : {
              borderLeftColor: palette.accentDeep,
              backgroundColor: palette.accentFaint,
            },
      ]}
    >
      <Text
        style={[
          s.replyQuoteName,
          { color: mine ? palette.mineText : palette.accentDeep },
        ]}
        numberOfLines={1}
      >
        {reply.sender || "Member"}
      </Text>
      <Text
        style={[
          s.replyQuoteText,
          { color: mine ? palette.mineText : palette.textMuted },
        ]}
        numberOfLines={2}
      >
        {reply.text || "Photo"}
      </Text>
    </View>
  );
}

/**
 * Horizontal swipe on a bubble to reply to it. Vertical drags are left to the
 * thread scroll, and the bubble springs back whether or not the swipe crossed
 * the trigger distance.
 */
function SwipeToReply({
  message,
  onReply,
  palette,
  children,
}: {
  message: ChatMessage;
  onReply: (message: ChatMessage) => void;
  palette: ChatPalette;
  children: ReactNode;
}) {
  const [translateX] = useState(() => new Animated.Value(0));
  const springBack = useCallback(() => {
    Animated.spring(translateX, {
      toValue: 0,
      useNativeDriver: true,
      bounciness: 4,
      speed: 18,
    }).start();
  }, [translateX]);
  const panResponder = useMemo(
    () =>
      PanResponder.create({
        // Claim only clearly horizontal drags so the thread keeps its scroll.
        onMoveShouldSetPanResponder: (_event, gesture) =>
          Math.abs(gesture.dx) > 12 &&
          Math.abs(gesture.dx) > Math.abs(gesture.dy) * 1.4,
        onPanResponderMove: (_event, gesture) => {
          translateX.setValue(Math.max(-88, Math.min(88, gesture.dx)));
        },
        onPanResponderRelease: (_event, gesture) => {
          if (Math.abs(gesture.dx) > 52) onReply(message);
          springBack();
        },
        onPanResponderTerminate: springBack,
      }),
    [message, onReply, springBack, translateX],
  );

  const leftHint = translateX.interpolate({
    inputRange: [0, 52],
    outputRange: [0, 1],
    extrapolate: "clamp",
  });
  const rightHint = translateX.interpolate({
    inputRange: [-52, 0],
    outputRange: [1, 0],
    extrapolate: "clamp",
  });

  return (
    <View style={s.swipeWrap}>
      <Animated.View
        pointerEvents="none"
        style={[s.swipeHint, s.swipeHintLeft, { opacity: leftHint }]}
      >
        <Ionicons name="arrow-undo" size={15} color={palette.inlineIcon} />
      </Animated.View>
      <Animated.View
        pointerEvents="none"
        style={[s.swipeHint, s.swipeHintRight, { opacity: rightHint }]}
      >
        <Ionicons name="arrow-undo" size={15} color={palette.inlineIcon} />
      </Animated.View>
      <Animated.View
        style={{ transform: [{ translateX }] }}
        {...panResponder.panHandlers}
      >
        {children}
      </Animated.View>
    </View>
  );
}

/**
 * Club Chat — one conversation per club, opened from the Home community
 * section. Membership decides what the screen offers: signed-out users are
 * sent to sign in, non-members are pointed at the join flow, members get the
 * club's chat room plus its member roster.
 */
export default function ClubChatScreen() {
  const insets = useSafeAreaInsets();
  const [gate, setGate] = useState<Gate>("loading");
  const [membership, setMembership] = useState<ClubMembership | null>(null);
  const [roster, setRoster] = useState<ClubMembers | null>(null);
  const [infoOpen, setInfoOpen] = useState(false);
  const [muted, setMuted] = useState(false);
  const [onlineUids, setOnlineUids] = useState<string[]>([]);
  const [lastSeen, setLastSeen] = useState<Record<string, string>>({});
  const [, setPresenceTick] = useState(0);
  const [appearance, setAppearance] =
    useState<ChatAppearance>(DEFAULT_CHAT_APPEARANCE);

  const slug = membership ? effectiveClubSlug(membership) : "";
  // The catalogue fetch is shared across the app session, so this is free.
  const { club } = useClub(slug);

  const check = useCallback(async () => {
    const session = await getSession().catch(() => null);
    if (!session?.user) {
      setGate("signedOut");
      return;
    }
    try {
      const res = await clubJoinApi.me();
      const m = res.data;
      if (!m || m.status === "graduated") {
        setMembership(null);
        setGate("noClub");
        return;
      }
      setMembership(m);
      setGate("ready");
    } catch (err) {
      if (err instanceof ApiError && err.status === 401) {
        void signOut();
        setMembership(null);
        setGate("signedOut");
        return;
      }
      setGate("error");
    }
  }, []);

  // Re-checked on every focus so returning from the join flow opens the chat.
  useFocusEffect(
    useCallback(() => {
      void check();
    }, [check]),
  );

  useEffect(() => {
    if (gate !== "ready" || !slug) return;
    let alive = true;
    (async () => {
      const res = await clubChatApi.members(slug).catch(() => null);
      if (!alive || !res) return;
      setRoster(res);
    })();
    return () => {
      alive = false;
    };
  }, [gate, slug]);

  useEffect(() => {
    if (!slug) return;
    let alive = true;
    clubChatSettingsApi
      .muted()
      .then((res) => {
        if (!alive) return;
        setMuted(
          res.muted.some(
            (m) => m === slug || (slug.startsWith("sprout-") && m === "sprout"),
          ),
        );
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [slug]);

  const refreshLastSeen = useCallback(() => {
    if (!roster) return;
    void fetchLastSeen(
      roster.members.map((m) => m.id),
      true,
    ).then(setLastSeen);
  }, [roster]);

  useEffect(() => {
    refreshLastSeen();
  }, [refreshLastSeen]);

  useEffect(() => {
    if (gate !== "ready") return;
    const timer = setInterval(() => setPresenceTick((tick) => tick + 1), 60_000);
    return () => clearInterval(timer);
  }, [gate]);

  const clubName = club?.name || membership?.clubName || "Club Chat";
  const clubColor = club?.colorDark || colors.gold;

  useEffect(() => {
    let alive = true;
    void getChatAppearance().then((saved) => {
      if (alive) setAppearance(saved);
    });
    return () => {
      alive = false;
    };
  }, []);

  const palette = useMemo(
    () => resolveChatPalette(appearance.theme, clubColor),
    [appearance.theme, clubColor],
  );

  const changeTheme = useCallback((theme: ChatThemeKey) => {
    setAppearance((prev) => ({ ...prev, theme }));
    void setChatTheme(theme).catch(() => {});
  }, []);

  const changeBackground = useCallback((background: ChatBackgroundKey) => {
    setAppearance((prev) => ({ ...prev, background }));
    void setChatBackground(background).catch(() => {});
  }, []);

  const openInfo = () => setInfoOpen(true);
  const closeInfo = () => setInfoOpen(false);

  const memberLabel = roster
    ? `${roster.count} ${roster.count === 1 ? "member" : "members"}`
    : "Club chat";
  const onlineLabel = onlineUids.length ? ` · ${onlineUids.length} Online` : "";
  const headerSub =
    gate === "ready" ? `${memberLabel}${onlineLabel}` : "Members only";

  return (
    <View
      style={[
        s.safe,
        { paddingTop: insets.top, backgroundColor: palette.background },
      ]}
    >
      <StatusBar style={palette.statusBar} />
      <View
        style={[
          s.header,
          {
            backgroundColor: palette.headerBg,
            borderBottomWidth: StyleSheet.hairlineWidth,
            borderBottomColor: palette.border,
          },
        ]}
      >
        <TouchableOpacity
          style={[s.backBtn, { backgroundColor: palette.accentSoft }]}
          onPress={() => router.back()}
          accessibilityLabel="Back"
        >
          <Ionicons name="chevron-back" size={22} color={palette.headerText} />
        </TouchableOpacity>
        <TouchableOpacity
          style={s.headMain}
          onPress={gate === "ready" ? openInfo : undefined}
          disabled={gate !== "ready"}
          activeOpacity={0.7}
          accessibilityLabel={gate === "ready" ? "Show club info and members" : undefined}
        >
          <View
            style={[
              s.headIcon,
              {
                backgroundColor:
                  gate === "ready" ? palette.headerIconBg : palette.accent,
              },
            ]}
          >
            <Ionicons
              name={(gate === "ready" && club?.icon ? club.icon : "chatbubbles") as any}
              size={19}
              color={palette.headerIconText}
            />
          </View>
          <View style={{ flex: 1 }}>
            <Text
              style={[s.headerTitle, { color: palette.headerText }]}
              numberOfLines={1}
            >
              {gate === "ready" ? clubName : "Club Chat"}
            </Text>
            <Text style={[s.headerSub, { color: palette.headerMuted }]}>
              {headerSub}
            </Text>
          </View>
          {gate === "ready" ? (
            <Ionicons
              name="information-circle-outline"
              size={19}
              color={palette.headerMuted}
            />
          ) : null}
        </TouchableOpacity>
      </View>

      <View style={{ flex: 1 }}>
        {gate === "loading" ? (
          <View style={s.center}>
            <ActivityIndicator color={colors.goldDark} />
          </View>
        ) : gate === "ready" && membership ? (
          <ChatRoom
            key={slug}
            clubName={clubName}
            slug={slug}
            members={roster?.members ?? []}
            onPresence={(uids) => setOnlineUids(uids)}
            onLastSeenRefresh={refreshLastSeen}
            accent={clubColor}
            palette={palette}
            background={appearance.background}
            bottomInset={insets.bottom}
          />
        ) : (
          <ScrollView
            contentContainerStyle={[
              s.centerBody,
              { paddingBottom: insets.bottom + 24 },
            ]}
            showsVerticalScrollIndicator={false}
          >
            {gate === "signedOut" ? (
              <GatePane
                icon="person-circle-outline"
                title="Sign in to chat"
                body="Club chat connects you with the members of your club. Sign in to join the conversation."
                action="Sign in"
                onPress={() =>
                  router.push({
                    pathname: "/login",
                    params: { next: "/club-chat" },
                  } as any)
                }
              />
            ) : gate === "noClub" ? (
              <GatePane
                icon="people-outline"
                title="You're not in a club yet"
                body="Club chat is for members. Choose the club you belong to and register to start chatting with your group."
                action="Join a club"
                onPress={() => router.push("/join")}
              />
            ) : (
              <GatePane
                icon="cloud-offline-outline"
                title="Couldn't load your club"
                body="Something went wrong while checking your membership. Check your connection and try again."
                action="Try again"
                onPress={() => {
                  setGate("loading");
                  void check();
                }}
              />
            )}
          </ScrollView>
        )}

        <ChatInfo
          visible={infoOpen}
          onClose={closeInfo}
          club={club ?? null}
          clubName={clubName}
          clubColor={clubColor}
          roster={roster}
          slug={slug}
          muted={muted}
          onMutedChange={setMuted}
          onlineUids={onlineUids}
          lastSeen={lastSeen}
          appearance={appearance}
          palette={palette}
          onThemeChange={changeTheme}
          onBackgroundChange={changeBackground}
        />
      </View>
    </View>
  );
}

function ChatInfo({
  visible,
  onClose,
  club,
  clubName,
  clubColor,
  roster,
  slug,
  muted,
  onMutedChange,
  onlineUids,
  lastSeen,
  appearance,
  palette,
  onThemeChange,
  onBackgroundChange,
}: {
  visible: boolean;
  onClose: () => void;
  club: Club | null;
  clubName: string;
  clubColor: string;
  roster: ClubMembers | null;
  slug: string;
  muted: boolean;
  onMutedChange: (muted: boolean) => void;
  onlineUids: string[];
  lastSeen: Record<string, string>;
  appearance: ChatAppearance;
  palette: ChatPalette;
  onThemeChange: (theme: ChatThemeKey) => void;
  onBackgroundChange: (background: ChatBackgroundKey) => void;
}) {
  const insets = useSafeAreaInsets();
  const [memberQuery, setMemberQuery] = useState("");
  const [muteBusy, setMuteBusy] = useState(false);

  const toggleMute = async (next: boolean) => {
    onMutedChange(next);
    setMuteBusy(true);
    try {
      await clubChatSettingsApi.setMuted(slug, next);
    } catch {
      onMutedChange(!next);
      Alert.alert("Couldn't save", "The setting wasn't saved. Try again in a moment.");
    } finally {
      setMuteBusy(false);
    }
  };

  const members = useMemo(() => roster?.members ?? [], [roster]);
  const filtered = useMemo(() => {
    const q = memberQuery.trim().toLowerCase();
    if (!q) return members;
    return members.filter((m) => m.firstName.toLowerCase().includes(q));
  }, [members, memberQuery]);
  const selectedThemeLabel =
    appearance.theme === "club"
      ? clubName
      : (CHAT_THEME_OPTIONS.find((option) => option.key === appearance.theme)
          ?.label ?? "Theme");
  const selectedBackgroundLabel =
    CHAT_BACKGROUND_OPTIONS.find(
      (option) => option.key === appearance.background,
    )?.label ?? "Plain";

  return (
    <Modal
      visible={visible}
      animationType="slide"
      statusBarTranslucent
      onRequestClose={onClose}
    >
      <View
        style={[
          s.infoSafe,
          { paddingTop: insets.top, backgroundColor: palette.background },
        ]}
      >
        <View style={s.infoHeader}>
          <TouchableOpacity
            style={[s.infoHeaderBtn, { backgroundColor: palette.surface }]}
            onPress={onClose}
            accessibilityLabel="Close chat info"
          >
            <Ionicons name="close" size={22} color={palette.text} />
          </TouchableOpacity>
          <Text style={[s.infoHeaderTitle, { color: palette.text }]}>
            Chat info
          </Text>
          <View style={{ width: 36 }} />
        </View>

        <ScrollView
          contentContainerStyle={{ paddingBottom: insets.bottom + 28 }}
          showsVerticalScrollIndicator={false}
          keyboardShouldPersistTaps="handled"
        >
          <View style={s.infoHero}>
            <View style={[s.infoAvatar, { backgroundColor: clubColor }]}>
              <Ionicons
                name={(club?.icon || "chatbubbles") as any}
                size={30}
                color={colors.white}
              />
            </View>
            <Text style={[s.infoName, { color: palette.text }]}>{clubName}</Text>
            <Text style={[s.infoCount, { color: palette.textMuted }]}>
              {roster
                ? `${roster.count} ${roster.count === 1 ? "member" : "members"}`
                : "Club chat"}
            </Text>
            {club?.tagline ? (
              <Text style={[s.infoTagline, { color: palette.textMuted }]}>
                {club.tagline}
              </Text>
            ) : null}
          </View>

          <View style={[s.infoSection, { backgroundColor: palette.surface }]}>
            <Text style={[s.infoLabel, { color: palette.textMuted }]}>About</Text>
            <Text style={[s.infoAbout, { color: palette.text }]}>
              {club?.description ||
                `The private chat for ${clubName} members — share updates, photos and plans with your club.`}
            </Text>
          </View>

          <View style={[s.infoSection, { backgroundColor: palette.surface }]}>
            <Text style={[s.infoLabel, { color: palette.textMuted }]}>
              Appearance
            </Text>
            <View style={s.appearanceRail}>
              <View style={s.appearanceRailHead}>
                <Text style={[s.appearanceLabel, { color: palette.textMuted }]}>
                  Theme
                </Text>
                <Text style={[s.appearanceValue, { color: palette.accentDeep }]}>
                  {selectedThemeLabel}
                </Text>
              </View>
              <ScrollView
                horizontal
                bounces={false}
                nestedScrollEnabled
                showsHorizontalScrollIndicator={false}
                style={s.themePillScroll}
                contentContainerStyle={s.themePillRow}
              >
                {CHAT_THEME_OPTIONS.map((option) => {
                  const active = appearance.theme === option.key;
                  const swatch = option.key === "club" ? clubColor : option.swatch;
                  return (
                    <TouchableOpacity
                      key={option.key}
                      style={[
                        s.themePill,
                        {
                          backgroundColor: active
                            ? palette.accentFaint
                            : palette.surfaceAlt,
                          borderColor: active ? palette.accentDeep : palette.border,
                        },
                      ]}
                      onPress={() => onThemeChange(option.key)}
                      accessibilityRole="button"
                      accessibilityState={{ selected: active }}
                      accessibilityLabel={`Use ${option.label} chat theme`}
                    >
                      <View
                        style={[
                          s.themePillSwatch,
                          { backgroundColor: swatch, borderColor: palette.border },
                        ]}
                      />
                      <Text
                        numberOfLines={1}
                        style={[
                          s.themePillLabel,
                          {
                            color: active ? palette.accentDeep : palette.textMuted,
                          },
                        ]}
                      >
                        {option.label}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </ScrollView>
            </View>

            <View style={s.appearanceRail}>
              <View style={s.appearanceRailHead}>
                <Text style={[s.appearanceLabel, { color: palette.textMuted }]}>
                  Background
                </Text>
                <Text style={[s.appearanceValue, { color: palette.accentDeep }]}>
                  {selectedBackgroundLabel}
                </Text>
              </View>
              <View style={s.backgroundChipRow}>
                {CHAT_BACKGROUND_OPTIONS.map((option) => {
                  const active = appearance.background === option.key;
                  return (
                    <TouchableOpacity
                      key={option.key}
                      style={[
                        s.backgroundChip,
                        {
                          backgroundColor: palette.background,
                          borderColor: active ? palette.accentDeep : palette.border,
                          borderWidth: active ? 2 : StyleSheet.hairlineWidth,
                        },
                      ]}
                      onPress={() => onBackgroundChange(option.key)}
                      hitSlop={5}
                      accessibilityRole="button"
                      accessibilityState={{ selected: active }}
                      accessibilityLabel={`Use ${option.label} chat background`}
                    >
                      <BackgroundPreview
                        background={option.key}
                        palette={palette}
                      />
                    </TouchableOpacity>
                  );
                })}
              </View>
            </View>
          </View>

          <View style={[s.infoSection, { backgroundColor: palette.surface }]}>
            <Text style={[s.infoLabel, { color: palette.textMuted }]}>Settings</Text>
            <View style={s.infoRow}>
              <Ionicons
                name="notifications-off-outline"
                size={20}
                color={palette.inlineIcon}
              />
              <View style={{ flex: 1 }}>
                <Text style={[s.infoRowTitle, { color: palette.text }]}>
                  Mute notifications
                </Text>
                <Text style={[s.infoRowSub, { color: palette.textMuted }]}>
                  Stop push alerts for new messages in this club.
                </Text>
              </View>
              <Switch
                value={muted}
                onValueChange={toggleMute}
                disabled={muteBusy}
                trackColor={{ false: palette.border, true: palette.accentSoft }}
                thumbColor={muted ? palette.accent : palette.surface}
              />
            </View>
          </View>

          <View style={[s.infoSection, { backgroundColor: palette.surface }]}>
            <Text style={[s.infoLabel, { color: palette.textMuted }]}>
              Members{roster ? ` · ${roster.count}` : ""}
            </Text>
            <View style={[s.infoSearch, { backgroundColor: palette.surfaceAlt }]}>
              <Ionicons name="search" size={16} color={palette.placeholder} />
              <TextInput
                style={[s.infoSearchInput, { color: palette.text }]}
                placeholder="Search members"
                placeholderTextColor={palette.placeholder}
                value={memberQuery}
                onChangeText={setMemberQuery}
                autoCapitalize="none"
              />
            </View>
            {filtered.map((m, i) => {
              const online = onlineUids.includes(m.id);
              const seen = `Last seen ${
                lastSeen[m.id] ? formatLastSeen(lastSeen[m.id]) : "recently"
              }`;
              return (
                <View key={`${m.id || m.firstName}-${i}`} style={s.memberRow}>
                  {m.image ? (
                    <Image source={{ uri: m.image }} style={s.avatar} contentFit="cover" />
                  ) : (
                    <View style={[s.avatar, { backgroundColor: `${clubColor}22` }]}>
                      <Text style={[s.avatarText, { color: clubColor }]}>
                        {initials(m.firstName)}
                      </Text>
                    </View>
                  )}
                  <View style={{ flex: 1 }}>
                    <View style={s.memberNameRow}>
                      <Text style={[s.memberName, { color: palette.text }]}>
                        {m.firstName}
                      </Text>
                      {online ? (
                        <View
                          style={[s.onlineDot, { backgroundColor: colors.success }]}
                          accessibilityLabel="Online"
                        />
                      ) : null}
                    </View>
                    <Text style={[s.memberStatus, { color: palette.textMuted }]}>
                      {online ? "Online" : seen}
                    </Text>
                  </View>
                </View>
              );
            })}
            {filtered.length === 0 ? (
              <Text style={[s.moreMembers, { color: palette.textMuted }]}>
                {members.length === 0
                  ? "Loading members…"
                  : "No members match that search."}
              </Text>
            ) : null}
            {roster && roster.count > members.length ? (
              <Text style={[s.moreMembers, { color: palette.textMuted }]}>
                +{roster.count - members.length} more
              </Text>
            ) : null}
          </View>
        </ScrollView>
      </View>
    </Modal>
  );
}

function MessageActionsModal({
  message,
  mine,
  myReaction,
  canReact,
  canEditMessage,
  palette,
  onClose,
  onCopy,
  onEdit,
  onDelete,
  onReact,
}: {
  message: ChatMessage;
  mine: boolean;
  myReaction: string | null;
  canReact: boolean;
  canEditMessage: boolean;
  palette: ChatPalette;
  onClose: () => void;
  onCopy: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onReact: (emoji: string) => void;
}) {
  const [confirming, setConfirming] = useState(false);
  const [anim] = useState(() => new Animated.Value(0));
  const closingRef = useRef(false);

  useEffect(() => {
    Animated.spring(anim, {
      toValue: 1,
      useNativeDriver: true,
      damping: 18,
      stiffness: 240,
      mass: 0.9,
    }).start();
  }, [anim]);

  const dismiss = useCallback(() => {
    if (closingRef.current) return;
    closingRef.current = true;
    Animated.timing(anim, {
      toValue: 0,
      duration: 140,
      useNativeDriver: true,
    }).start(({ finished }) => {
      if (finished) onClose();
    });
  }, [anim, onClose]);

  const scale = anim.interpolate({ inputRange: [0, 1], outputRange: [0.92, 1] });
  const translateY = anim.interpolate({ inputRange: [0, 1], outputRange: [14, 0] });
  const preview = message.text?.trim() || (message.image ? "Photo" : "");
  const canEdit = canEditMessage && Boolean(message.text?.trim());

  return (
    <Modal
      visible
      transparent
      animationType="none"
      statusBarTranslucent
      onRequestClose={dismiss}
    >
      <View style={s.actionOverlay}>
        <Animated.View
          style={[
            s.actionBackdrop,
            { opacity: anim, backgroundColor: palette.backdrop },
          ]}
        />
        <Pressable
          style={StyleSheet.absoluteFill}
          onPress={dismiss}
          accessibilityLabel="Close message actions"
        />
        <Animated.View
          style={[
            s.actionCard,
            {
              opacity: anim,
              transform: [{ scale }, { translateY }],
              backgroundColor: palette.cardBg,
            },
          ]}
        >
          {confirming ? (
            <>
              <View
                style={[
                  s.actionIconBadge,
                  s.actionIconDanger,
                  { backgroundColor: palette.surfaceAlt },
                ]}
              >
                <Ionicons name="trash-outline" size={20} color={colors.error} />
              </View>
              <Text style={[s.actionTitle, { color: palette.text }]}>
                Delete message?
              </Text>
              <Text style={[s.actionBody, { color: palette.textMuted }]}>
                This removes it for everyone in the club.
              </Text>
              <View style={s.actionConfirmRow}>
                <TouchableOpacity
                  style={[
                    s.actionBtn,
                    s.actionBtnGhost,
                    { backgroundColor: palette.surfaceAlt },
                  ]}
                  onPress={() => setConfirming(false)}
                  activeOpacity={0.8}
                >
                  <Text style={[s.actionBtnGhostText, { color: palette.text }]}>
                    Cancel
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[s.actionBtn, s.actionBtnDanger]}
                  onPress={() => {
                    onDelete();
                    dismiss();
                  }}
                  activeOpacity={0.85}
                >
                  <Text style={s.actionBtnDangerText}>Delete</Text>
                </TouchableOpacity>
              </View>
            </>
          ) : (
            <>
              <View
                style={[s.actionIconBadge, { backgroundColor: palette.surfaceAlt }]}
              >
                <Ionicons
                  name="ellipsis-horizontal"
                  size={20}
                  color={palette.accentDeep}
                />
              </View>
              <Text style={[s.actionPreview, { color: palette.textMuted }]} numberOfLines={2}>
                {preview}
              </Text>
              {canReact ? (
                <>
                  <Text style={[s.reactLabel, { color: palette.textMuted }]}>
                    React
                  </Text>
                  <View style={s.reactRow}>
                    {QUICK_REACTIONS.map((emoji) => (
                      <TouchableOpacity
                        key={emoji}
                        style={[
                          s.reactBtn,
                          { backgroundColor: palette.reactionBg },
                          myReaction === emoji && {
                            backgroundColor: palette.reactionActiveBg,
                          },
                        ]}
                        onPress={() => {
                          onReact(emoji);
                          dismiss();
                        }}
                        activeOpacity={0.7}
                        accessibilityLabel={`React with ${emoji}`}
                      >
                        <Text style={s.reactEmoji}>{emoji}</Text>
                      </TouchableOpacity>
                    ))}
                  </View>
                </>
              ) : null}
              <View style={[s.actionList, { backgroundColor: palette.surfaceAlt }]}>
                {canEdit ? (
                  <>
                    <TouchableOpacity
                      style={s.actionRow}
                      onPress={() => {
                        onCopy();
                        dismiss();
                      }}
                      activeOpacity={0.7}
                    >
                      <Ionicons
                        name="copy-outline"
                        size={19}
                        color={palette.accentDeep}
                      />
                      <Text style={[s.actionRowText, { color: palette.text }]}>
                        Copy text
                      </Text>
                    </TouchableOpacity>
                    <View style={[s.actionDivider, { backgroundColor: palette.border }]} />
                  </>
                ) : null}
                {mine && canEdit ? (
                  <>
                    <TouchableOpacity
                      style={s.actionRow}
                      onPress={() => {
                        onEdit();
                        dismiss();
                      }}
                      activeOpacity={0.7}
                    >
                      <Ionicons
                        name="pencil-outline"
                        size={19}
                        color={palette.accentDeep}
                      />
                      <Text style={[s.actionRowText, { color: palette.text }]}>
                        Edit
                      </Text>
                    </TouchableOpacity>
                    <View style={[s.actionDivider, { backgroundColor: palette.border }]} />
                  </>
                ) : null}
                {mine ? (
                  <>
                    <TouchableOpacity
                      style={s.actionRow}
                      onPress={() => setConfirming(true)}
                      activeOpacity={0.7}
                    >
                      <Ionicons name="trash-outline" size={19} color={colors.error} />
                      <Text style={[s.actionRowText, { color: colors.error }]}>
                        Delete
                      </Text>
                    </TouchableOpacity>
                    <View style={[s.actionDivider, { backgroundColor: palette.border }]} />
                  </>
                ) : null}
                <TouchableOpacity style={s.actionRow} onPress={dismiss} activeOpacity={0.7}>
                  <Ionicons
                    name="close-outline"
                    size={19}
                    color={palette.textMuted}
                  />
                  <Text style={[s.actionRowText, { color: palette.textMuted }]}>
                    Cancel
                  </Text>
                </TouchableOpacity>
              </View>
            </>
          )}
        </Animated.View>
      </View>
    </Modal>
  );
}

function GatePane({
  icon,
  title,
  body,
  action,
  onPress,
}: {
  icon: string;
  title: string;
  body: string;
  action: string;
  onPress: () => void;
}) {
  return (
    <View style={s.card}>
      <View style={s.cardIcon}>
        <Ionicons name={icon as any} size={26} color={colors.goldDark} />
      </View>
      <Text style={s.cardTitle}>{title}</Text>
      <Text style={s.cardBody}>{body}</Text>
      <TouchableOpacity style={s.cardBtn} onPress={onPress} activeOpacity={0.85}>
        <Text style={s.cardBtnText}>{action}</Text>
        <Ionicons name="arrow-forward" size={16} color={colors.white} />
      </TouchableOpacity>
    </View>
  );
}

function ChatRoom({
  clubName,
  slug,
  members,
  onPresence,
  onLastSeenRefresh,
  accent,
  palette,
  background,
  bottomInset,
}: {
  clubName: string;
  slug: string;
  members: ClubMember[];
  onPresence: (uids: string[]) => void;
  onLastSeenRefresh: () => void;
  accent: string;
  palette: ChatPalette;
  background: ChatBackgroundKey;
  bottomInset: number;
}) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  // Rows this device just stored. Realtime normally echoes them back; this
  // overlay keeps them visible when the Realtime publication is unavailable.
  const [sentMessages, setSentMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [editing, setEditing] = useState<{ id: string; text: string } | null>(null);
  const draftBeforeEdit = useRef("");
  const [pendingImage, setPendingImage] = useState<UploadImageSource | null>(null);
  const [sending, setSending] = useState(false);
  const [myUid, setMyUid] = useState<string | null>(null);
  const [chatError, setChatError] = useState<string | null>(null);
  const [viewerUrl, setViewerUrl] = useState<string | null>(null);
  const [actionMsg, setActionMsg] = useState<ChatMessage | null>(null);
  const [savingImage, setSavingImage] = useState(false);
  const [reactions, setReactions] = useState<ChatRealtimeReaction[]>([]);
  const [features, setFeatures] = useState({
    replies: false,
    edits: false,
    reactions: false,
  });
  const [mentionQuery, setMentionQuery] = useState<string | null>(null);
  const [replyingTo, setReplyingTo] = useState<ChatMessage | null>(null);
  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const scrollRef = useRef<ScrollView>(null);
  const composerRef = useRef<View>(null);
  const inputRef = useRef<TextInput>(null);
  const lastReconnectAt = useRef(0);
  const lastSeenRefreshRef = useRef(onLastSeenRefresh);
  const subscriptionRef = useRef<ClubChatSubscription | null>(null);
  const scrollMetricsRef = useRef({ y: 0, contentHeight: 0 });
  const pendingScrollRef = useRef<{ y: number; contentHeight: number } | null>(
    null,
  );
  const atBottomRef = useRef(true);
  const autoScrollRef = useRef(true);
  const loadingOlderRef = useRef(false);

  useEffect(() => {
    lastSeenRefreshRef.current = onLastSeenRefresh;
  }, [onLastSeenRefresh]);

  // Lift the composer by however much the keyboard actually overlaps it. The
  // composer's bottom edge stays fixed while only its inner padding grows, so
  // re-measuring is safe and settles whatever Android does with the window
  // (resize or edge-to-edge overlay).
  useEffect(() => {
    const showEvent = Platform.OS === "ios" ? "keyboardWillShow" : "keyboardDidShow";
    const hideEvent = Platform.OS === "ios" ? "keyboardWillHide" : "keyboardDidHide";
    let timers: ReturnType<typeof setTimeout>[] = [];
    const measure = (keyboardTop: number) => {
      composerRef.current?.measureInWindow((_x, y, _width, height) => {
        const overlap = Math.round(y + height - keyboardTop);
        setKeyboardHeight(Math.max(0, overlap));
      });
    };
    const show = Keyboard.addListener(showEvent, (e) => {
      const keyboardTop = e.endCoordinates.screenY;
      timers.forEach(clearTimeout);
      timers = [
        setTimeout(() => measure(keyboardTop), 120),
        setTimeout(() => measure(keyboardTop), 420),
      ];
      setTimeout(() => {
        if (atBottomRef.current) {
          scrollRef.current?.scrollToEnd({ animated: true });
        }
      }, 80);
    });
    const hide = Keyboard.addListener(hideEvent, () => {
      timers.forEach(clearTimeout);
      timers = [];
      setKeyboardHeight(0);
    });
    return () => {
      timers.forEach(clearTimeout);
      show.remove();
      hide.remove();
    };
  }, []);

  // Unsent text is kept per club so leaving the screen (or the app) doesn't
  // lose what the user was typing.
  const draftKey = `club-chat:draft:${slug}`;
  const [draftRestored, setDraftRestored] = useState(false);

  useEffect(() => {
    let alive = true;
    AsyncStorage.getItem(draftKey)
      .then((stored) => {
        if (alive && stored) setDraft((current) => current || stored);
      })
      .catch(() => {})
      .finally(() => {
        if (alive) setDraftRestored(true);
      });
    return () => {
      alive = false;
    };
  }, [draftKey]);

  useEffect(() => {
    if (!draftRestored || editing) return;
    const timer = setTimeout(() => {
      if (draft) AsyncStorage.setItem(draftKey, draft).catch(() => {});
      else AsyncStorage.removeItem(draftKey).catch(() => {});
    }, 300);
    return () => clearTimeout(timer);
  }, [draft, draftKey, draftRestored, editing]);

  // Chat rows carry the sender's user id, so avatars and names resolve from
  // the roster already loaded for the members sheet.
  const memberById = useMemo(() => {
    const map = new Map<string, ClubMember>();
    for (const member of members) {
      if (member.id) map.set(member.id, member);
    }
    return map;
  }, [members]);

  // First names are the tag handle (that's what the roster shows), so
  // suggestions are unique first names that still match what's typed.
  const mentionMatches = useMemo(() => {
    if (mentionQuery === null) return [];
    const query = mentionQuery.toLowerCase();
    const seen = new Set<string>();
    const matches: ClubMember[] = [];
    for (const member of members) {
      const name = member.firstName.trim();
      const key = name.toLowerCase();
      if (!name || !key.startsWith(query) || seen.has(key)) continue;
      seen.add(key);
      matches.push(member);
      if (matches.length >= 8) break;
    }
    return matches;
  }, [members, mentionQuery]);

  const changeDraft = (value: string) => {
    setDraft(value);
    const tail = MENTION_TAIL.exec(value);
    setMentionQuery(tail ? tail[1] : null);
  };

  const insertMention = (member: ClubMember) => {
    setDraft((current) =>
      current.replace(
        MENTION_TAIL,
        (_match: string, lead: string) => `${lead}@${member.firstName.trim()} `,
      ),
    );
    setMentionQuery(null);
    inputRef.current?.focus();
  };

  // Reactions are grouped per message: emoji → how many members picked it.
  const reactionSummary = useMemo(() => {
    const byMessage = new Map<string, Map<string, number>>();
    for (const reaction of reactions) {
      let byEmoji = byMessage.get(reaction.messageId);
      if (!byEmoji) {
        byEmoji = new Map();
        byMessage.set(reaction.messageId, byEmoji);
      }
      byEmoji.set(reaction.emoji, (byEmoji.get(reaction.emoji) ?? 0) + 1);
    }
    return byMessage;
  }, [reactions]);

  const myReactionFor = (messageId: string): string | null =>
    myUid
      ? reactions.find((r) => r.messageId === messageId && r.userId === myUid)?.emoji ?? null
      : null;

  const react = async (message: ChatMessage, emoji: string) => {
    if (!features.reactions || !myUid || !isChatRealtimeConfigured) return;
    const messageId = String(message.id);
    // Local preview rows (Supabase not set up) have no server id to attach to.
    if (!UUID_PATTERN.test(messageId)) return;
    const previous = myReactionFor(messageId);
    const withoutMine = (list: ChatRealtimeReaction[]) =>
      list.filter((r) => !(r.messageId === messageId && r.userId === myUid));
    // Optimistic: the chip updates instantly, then the Realtime echo confirms.
    setReactions((list) =>
      previous === emoji
        ? withoutMine(list)
        : [...withoutMine(list), { messageId, userId: myUid, emoji }],
    );
    try {
      await setClubChatReaction(slug, myUid, messageId, emoji, previous);
    } catch (err) {
      console.warn("[club-chat] reaction failed", err);
      setReactions((list) => {
        const rest = withoutMine(list);
        return previous ? [...rest, { messageId, userId: myUid, emoji: previous }] : rest;
      });
      Alert.alert(
        "Couldn't react",
        "Your reaction wasn't saved. Check your connection and try again.",
      );
    }
  };

  // The Supabase channel lives exactly as long as this screen is focused and
  // the app is in the foreground: backgrounding the phone releases the
  // connection instead of leaving a dead socket holding one of the free
  // tier's concurrent slots. Coming back re-subscribes and re-fetches the
  // history, so messages sent while away show up immediately.
  const [appActive, setAppActive] = useState(
    () => AppState.currentState === "active",
  );
  const [reconnectTick, setReconnectTick] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  // History arrives asynchronously; until the first snapshot the thread is
  // unknown, not empty — showing "No messages yet" then filling in reads as
  // a glitch, so the list shows a spinner instead.
  const [historyLoaded, setHistoryLoaded] = useState(false);

  // Pull-to-refresh (or tapping the error chip) drops the current channel and
  // opens a fresh one, which reloads the latest history — the escape hatch
  // when the phone slept through a message burst.
  const refreshConnection = useCallback(() => {
    const now = Date.now();
    if (now - lastReconnectAt.current < 5000) return;
    lastReconnectAt.current = now;
    setChatError(null);
    setRefreshing(true);
    setReconnectTick((t) => t + 1);
    setTimeout(() => setRefreshing(false), 1200);
  }, []);

  useEffect(() => {
    const sub = AppState.addEventListener("change", (state) => {
      setAppActive(state === "active");
    });
    return () => sub.remove();
  }, []);

  useFocusEffect(
    useCallback(() => {
      setFeatures({ replies: false, edits: false, reactions: false });
      if (!isChatRealtimeConfigured || !slug || !appActive) return;
      setHasMore(true);
      setLoadingOlder(false);
      loadingOlderRef.current = false;
      pendingScrollRef.current = null;
      atBottomRef.current = true;
      autoScrollRef.current = true;
      // Never leave the spinner running forever on a bad network: after a
      // few seconds fall back to the thread plus a tap-to-refresh chip.
      let slow: ReturnType<typeof setTimeout> | null = setTimeout(() => {
        slow = null;
        setHistoryLoaded(true);
        setRefreshing(false);
        setChatError("Still connecting. Tap here to refresh.");
      }, 4000);
      const stopSlow = () => {
        if (slow) {
          clearTimeout(slow);
          slow = null;
        }
      };
      const markLastSeen = () => {
        void touchLastSeen().then((ok) => {
          if (ok) lastSeenRefreshRef.current();
        });
      };
      markLastSeen();
      const heartbeat = setInterval(markLastSeen, 300_000);
      const subscription = subscribeClubChat(slug, {
        onMessages: (list, uid, meta) => {
          stopSlow();
          setMessages(list);
          setSentMessages((extra) => {
            if (!extra.length) return extra;
            const loaded = new Set(list.map((m) => String(m.id)));
            return extra.filter((m) => !loaded.has(String(m.id)));
          });
          if (meta) setHasMore(meta.hasMore);
          if (atBottomRef.current) autoScrollRef.current = true;
          setMyUid(uid);
          setChatError(null);
          setRefreshing(false);
          setHistoryLoaded(true);
        },
        onReactions: (list) => setReactions(list),
        onPresence: (uids) => onPresence(uids),
        onFeatures: (next) => setFeatures(next),
        onDeleted: (id) =>
          setSentMessages((list) =>
            list.filter((m) => String(m.id) !== id),
          ),
        onError: () => {
          stopSlow();
          setRefreshing(false);
          setHistoryLoaded(true);
          setChatError(
            "Couldn't reach the club chat. Tap here to reconnect.",
          );
        },
      });
      subscriptionRef.current = subscription;
      return () => {
        stopSlow();
        clearInterval(heartbeat);
        subscriptionRef.current = null;
        subscription.unsubscribe();
      };
      // reconnectTick is a deliberate dependency: bumping it drops the old
      // channel and subscribes again with fresh history.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [slug, appActive, reconnectTick]),
  );

  const pickImage = async () => {
    try {
      const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!permission.granted) {
        Alert.alert(
          "Permission needed",
          "Allow photo access to attach an image to your message.",
        );
        return;
      }
      const res = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        quality: 0.8,
        base64: true,
      });
      if (res.canceled) return;
      const asset = res.assets[0];
      if (!asset?.uri) return;
      if (asset.fileSize && asset.fileSize > 10 * 1024 * 1024) {
        Alert.alert("Image too large", "Choose an image smaller than 10 MB.");
        return;
      }
      // Pass the whole asset so the uploader can use its base64 data URI and
      // real MIME type instead of a local file URI other devices can't read.
      setPendingImage({
        uri: asset.uri,
        base64: asset.base64,
        mimeType: asset.mimeType ?? undefined,
      });
    } catch (err) {
      console.warn("[club-chat] pick image failed", err);
      Alert.alert("Could not open photos", "Choose an image and try again.");
    }
  };

  const canSend = (draft.trim().length > 0 || !!pendingImage) && !sending;

  const thread = useMemo(() => {
    if (!sentMessages.length) return messages;
    const loaded = new Set(messages.map((m) => m.id));
    const extra = sentMessages.filter((m) => !loaded.has(m.id));
    if (!extra.length) return messages;
    return [...messages, ...extra].sort((a, b) => a.at - b.at);
  }, [messages, sentMessages]);

  const saveViewerImage = async () => {
    if (!viewerUrl || savingImage) return;
    if (Platform.OS === "web") {
      await Linking.openURL(viewerUrl).catch(() => {});
      return;
    }
    setSavingImage(true);
    try {
      // Loaded on demand so the chat screen also works in bundles built before
      // these modules were added. SDK 57 exposes the class-based MediaLibrary
      // API and the File API — the legacy helpers throw at runtime.
      const media = await import("expo-media-library");
      const fs = await import("expo-file-system");
      // Write-only: saving needs no read access to the photo library.
      const permission = await media.requestPermissionsAsync(true);
      if (!permission.granted) {
        Alert.alert(
          "Permission needed",
          "Allow photo access so the image can be saved to your gallery.",
        );
        return;
      }
      const file = new fs.File(fs.Paths.cache, `club-chat-${Date.now()}.jpg`);
      const downloaded = await fs.File.downloadFileAsync(viewerUrl, file);
      try {
        await media.Asset.create(downloaded.uri);
      } catch {
        const legacy = await import("expo-media-library/legacy");
        await legacy.saveToLibraryAsync(downloaded.uri);
      }
      try {
        downloaded.delete();
      } catch {}
      Alert.alert("Saved", "The image is in your photo gallery.");
    } catch (err) {
      console.warn("[club-chat] save image failed", err);
      const detail = err instanceof Error ? err.message.trim() : "";
      Alert.alert(
        "Could not save",
        detail
          ? `The image wasn't saved to your gallery.\n\n${detail.slice(0, 160)}`
          : "The image wasn't saved to your gallery. Try again in a moment.",
      );
    } finally {
      setSavingImage(false);
    }
  };

  const startEdit = (m: ChatMessage) => {
    if (!m.text || !features.edits) return;
    draftBeforeEdit.current = draft;
    setReplyingTo(null);
    setPendingImage(null);
    setEditing({ id: String(m.id), text: m.text });
    setDraft(m.text);
    inputRef.current?.focus();
  };

  const cancelEdit = () => {
    setEditing(null);
    setDraft(draftBeforeEdit.current);
    draftBeforeEdit.current = "";
    setMentionQuery(null);
  };

  const replaceMessage = (id: string, patch: Partial<ChatMessage>) => {
    const apply = (list: ChatMessage[]) =>
      list.map((m) => (String(m.id) === id ? { ...m, ...patch } : m));
    setMessages(apply);
    setSentMessages(apply);
  };

  const deleteMessage = async (m: ChatMessage) => {
    try {
      if (isChatRealtimeConfigured) await deleteClubChatMessage(String(m.id));
      const apply = (list: ChatMessage[]) => list.filter((x) => x.id !== m.id);
      setMessages(apply);
      setSentMessages(apply);
      setReactions((list) => list.filter((r) => r.messageId !== String(m.id)));
      if (editing?.id === String(m.id)) {
        setEditing(null);
        setDraft(draftBeforeEdit.current);
        draftBeforeEdit.current = "";
      }
    } catch (err) {
      console.warn("[club-chat] delete failed", err);
      const detail = err instanceof Error ? err.message.trim() : "";
      Alert.alert(
        "Could not delete",
        detail
          ? `The message wasn't deleted.\n\n${detail.slice(0, 160)}`
          : "The message wasn't deleted. Try again in a moment.",
      );
    }
  };

  // Long-press works on every message: everyone can react or copy, while
  // edit/delete stay limited to the sender inside the sheet.
  const messageActions = (m: ChatMessage) => {
    setActionMsg(m);
  };

  // Stable across re-renders so each bubble's swipe responder isn't rebuilt on
  // every keystroke in the composer.
  const startReply = useCallback(
    (message: ChatMessage) => {
      if (editing || !features.replies) return;
      setReplyingTo(message);
      inputRef.current?.focus();
    },
    [editing, features.replies],
  );

  const send = async () => {
    if (!canSend) return;
    const text = draft.trim();
    const replySnapshot = features.replies && replyingTo
      ? {
          id: String(replyingTo.id),
          sender: replyingTo.senderName || "Member",
          text: messagePreview(replyingTo),
        }
      : null;

    // Editing an existing message keeps the draft machinery out of the way.
    if (editing) {
      if (!text || !features.edits) return;
      setSending(true);
      try {
        if (isChatRealtimeConfigured) {
          const stored = await updateClubChatMessage(editing.id, text);
          replaceMessage(editing.id, { text: stored.text, edited: true });
        } else {
          replaceMessage(editing.id, { text, edited: true });
        }
        setEditing(null);
        setDraft("");
        setMentionQuery(null);
        draftBeforeEdit.current = "";
        AsyncStorage.removeItem(draftKey).catch(() => {});
      } catch (err) {
        console.warn("[club-chat] edit failed", err);
        const detail = err instanceof Error ? err.message.trim() : "";
        Alert.alert(
          "Could not save changes",
          detail
            ? `Your edit wasn't saved.\n\n${detail.slice(0, 160)}`
            : "Your edit wasn't saved. Try again in a moment.",
        );
      } finally {
        setSending(false);
      }
      return;
    }

    if (!isChatRealtimeConfigured) {
      // Supabase not configured — keep the local preview working.
      atBottomRef.current = true;
      autoScrollRef.current = true;
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now(),
          text: text || undefined,
          image: pendingImage?.uri,
          at: Date.now(),
          replyTo: replySnapshot ?? undefined,
        },
      ]);
      setDraft("");
      setMentionQuery(null);
      setPendingImage(null);
      setReplyingTo(null);
      return;
    }
    setSending(true);
    try {
      // Images go to Cloudinary first; the chat row stores only the URL.
      const image = pendingImage ? await uploadChatImage(pendingImage) : undefined;
      const session = await getSession().catch(() => null);
      const stored = await sendClubChatMessage(slug, {
        text: text || undefined,
        image,
        senderName: session?.user?.name || "Member",
        replyTo: replySnapshot,
      });
      setSentMessages((prev) => [
        ...prev,
        {
          id: stored.id,
          text: stored.text,
          image: stored.image,
          at: stored.at,
          senderId: stored.senderId,
          senderName: stored.senderName,
          replyTo: stored.replyTo,
        },
      ]);
      atBottomRef.current = true;
      autoScrollRef.current = true;
      setDraft("");
      setMentionQuery(null);
      setPendingImage(null);
      setReplyingTo(null);
      AsyncStorage.removeItem(draftKey).catch(() => {});
    } catch (err) {
      console.warn("[club-chat] send failed", err);
      const detail = err instanceof Error ? err.message.trim() : "";
      Alert.alert(
        "Could not send",
        detail
          ? `Your message wasn't sent. Check your connection and try again.\n\n${detail.slice(0, 160)}`
          : "Your message wasn't sent. Check your connection and try again.",
      );
    } finally {
      setSending(false);
    }
  };

  const loadOlder = useCallback(async () => {
    if (loadingOlderRef.current || !hasMore || !subscriptionRef.current) return;
    loadingOlderRef.current = true;
    setLoadingOlder(true);
    pendingScrollRef.current = { ...scrollMetricsRef.current };
    try {
      const result = await subscriptionRef.current.loadOlder();
      setHasMore(result.hasMore);
      if (!result.loaded) pendingScrollRef.current = null;
    } catch {
      pendingScrollRef.current = null;
    } finally {
      loadingOlderRef.current = false;
      setLoadingOlder(false);
    }
  }, [hasMore]);

  const onScroll = useCallback(
    (event: NativeSyntheticEvent<NativeScrollEvent>) => {
      const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent;
      scrollMetricsRef.current = {
        y: contentOffset.y,
        contentHeight: contentSize.height,
      };
      atBottomRef.current =
        contentOffset.y + layoutMeasurement.height >= contentSize.height - 80;
      if (contentOffset.y <= 80) void loadOlder();
    },
    [loadOlder],
  );

  const onContentSizeChange = useCallback((_width: number, height: number) => {
    const pending = pendingScrollRef.current;
    if (pending) {
      const delta = height - pending.contentHeight;
      scrollRef.current?.scrollTo({
        y: Math.max(0, pending.y + delta),
        animated: false,
      });
      pendingScrollRef.current = null;
      return;
    }
    if (autoScrollRef.current && atBottomRef.current) {
      scrollRef.current?.scrollToEnd({ animated: false });
      autoScrollRef.current = false;
    }
  }, []);

  return (
    <View style={{ flex: 1 }}>
      <ChatBackdrop palette={palette} background={background} />
      <ScrollView
        ref={scrollRef}
        style={{ flex: 1 }}
        contentContainerStyle={[
          s.thread,
          thread.length === 0 && s.threadEmpty,
        ]}
        onContentSizeChange={onContentSizeChange}
        onScroll={onScroll}
        scrollEventThrottle={16}
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode={Platform.OS === "ios" ? "interactive" : "on-drag"}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={refreshConnection}
            tintColor={palette.inlineIcon}
            colors={[palette.accent]}
          />
        }
      >
        {!historyLoaded && isChatRealtimeConfigured ? (
          <View style={s.threadLoading}>
            <ActivityIndicator size="small" color={palette.inlineIcon} />
            <Text style={[s.threadLoadingText, { color: palette.textMuted }]}>
              Loading messages…
            </Text>
          </View>
        ) : thread.length === 0 ? (
          <View style={s.empty}>
            <View style={[s.emptyIcon, { backgroundColor: palette.accentSoft }]}>
              <Ionicons
                name="chatbubbles-outline"
                size={26}
                color={palette.accentDeep}
              />
            </View>
            <Text style={[s.emptyTitle, { color: palette.text }]}>
              No messages yet
            </Text>
            <Text style={[s.emptySub, { color: palette.textMuted }]}>
              Be the first to say hello to {clubName}.
            </Text>
          </View>
        ) : (
          <>
            {hasMore && thread.length > 0 ? (
              <View style={s.olderLoading}>
                {loadingOlder ? (
                  <ActivityIndicator size="small" color={palette.inlineIcon} />
                ) : null}
                <Text style={[s.olderLoadingText, { color: palette.textMuted }]}>
                  {loadingOlder
                    ? "Loading older messages…"
                    : "Scroll up for older messages"}
                </Text>
              </View>
            ) : null}
            {thread.map((m, index) => {
            const mine = !!myUid && m.senderId === myUid;
            const member = m.senderId ? memberById.get(m.senderId) : undefined;
            const name = m.senderName || member?.firstName || "Member";
            const avatar = member?.image ?? null;
            const nameColor = senderNameColor(m.senderId || name);
            const prev = index > 0 ? thread[index - 1] : null;
            const grouped = !!prev && !!m.senderId && prev.senderId === m.senderId;
            const timeText = `${timeLabel(m.at)}${m.edited ? " · edited" : ""}`;
            const emojiOnly =
              !m.image && !m.replyTo && isEmojiOnlyMessage(m.text);
            const messageReactions = reactionSummary.get(String(m.id));
            const myReaction = myUid ? myReactionFor(String(m.id)) : null;
            const content = m.image ? (
              // Photos render bare — no coloured bubble or frame around them.
              // A caption, when present, sits as plain text under the image;
              // with no caption the time floats on the photo.
              <View style={s.mediaWrap}>
                {m.replyTo ? (
                  <ReplyQuote reply={m.replyTo} mine={false} palette={palette} />
                ) : null}
                <TouchableOpacity
                  activeOpacity={0.92}
                  onPress={() => setViewerUrl(m.image ?? null)}
                  onLongPress={() => messageActions(m)}
                  delayLongPress={280}
                  accessibilityLabel="Open image"
                >
                  <Image
                    source={{ uri: getOptimizedImageUrl(m.image, 480) }}
                    style={s.bubbleImage}
                    contentFit="cover"
                  />
                </TouchableOpacity>
                {m.text ? (
                  <View style={[s.mediaCaption, mine && s.mediaCaptionMine]}>
                    <MentionText
                      text={m.text}
                      mine={false}
                      palette={palette}
                      style={[
                        s.bubbleText,
                        s.bubbleTextOther,
                        { color: palette.text },
                      ]}
                    />
                    <Text
                      style={[
                        s.bubbleTime,
                        s.bubbleTimeOther,
                        { color: palette.textMuted },
                      ]}
                    >
                      {timeText}
                    </Text>
                  </View>
                ) : (
                  <View style={s.mediaTimeChip} pointerEvents="none">
                    <Text style={s.mediaTimeChipText}>{timeText}</Text>
                  </View>
                )}
              </View>
            ) : emojiOnly ? (
              // Emoji-only messages skip the coloured bubble so the glyphs
              // read at full size with just the time underneath.
              <>
                <Text style={s.emojiText}>{m.text}</Text>
                <Text
                  style={[
                    s.emojiTime,
                    mine && s.emojiTimeMine,
                    { color: mine ? palette.mineText : palette.textMuted },
                  ]}
                >
                  {timeText}
                </Text>
              </>
            ) : (
              <>
                {m.replyTo ? (
                  <ReplyQuote reply={m.replyTo} mine={mine} palette={palette} />
                ) : null}
                {m.text ? (
                  <MentionText
                    text={m.text}
                    mine={mine}
                    palette={palette}
                    style={[
                      s.bubbleText,
                      !mine && s.bubbleTextOther,
                      { color: mine ? palette.mineText : palette.text },
                    ]}
                  />
                ) : null}
                <Text
                  style={[
                    s.bubbleTime,
                    !mine && s.bubbleTimeOther,
                    { color: mine ? palette.mineText : palette.textMuted },
                  ]}
                >
                  {timeText}
                </Text>
              </>
            );
            return (
              <View
                key={m.id}
                style={[
                  s.bubbleRow,
                  mine ? s.bubbleRowMine : s.bubbleRowOther,
                  grouped && s.bubbleRowGrouped,
                ]}
              >
                {!mine ? (
                  grouped ? (
                    <View style={s.msgAvatarSpacer} />
                  ) : avatar ? (
                    <Image
                      source={{ uri: avatar }}
                      style={s.msgAvatar}
                      contentFit="cover"
                    />
                  ) : (
                    <View
                      style={[
                        s.msgAvatar,
                        s.msgAvatarFallback,
                        { backgroundColor: `${accent}22` },
                      ]}
                    >
                      <Text style={[s.msgAvatarText, { color: accent }]}>
                        {initials(name)}
                      </Text>
                    </View>
                  )
                ) : null}
                <View
                  style={[s.msgCol, mine ? s.msgColMine : s.msgColOther]}
                >
                  {!mine && !grouped ? (
                    <Text style={[s.msgSender, { color: nameColor }]}>{name}</Text>
                  ) : null}
                  <SwipeToReply
                    message={m}
                    onReply={startReply}
                    palette={palette}
                  >
                    <Pressable
                      onLongPress={() => messageActions(m)}
                      delayLongPress={280}
                    >
                      {emojiOnly || m.image ? (
                        content
                      ) : mine ? (
                        <LinearGradient
                          colors={[palette.mineFrom, palette.mineTo]}
                          start={{ x: 0, y: 0 }}
                          end={{ x: 1, y: 1 }}
                          style={[s.bubble, s.bubbleMine]}
                        >
                          {content}
                        </LinearGradient>
                      ) : (
                        <View
                          style={[
                            s.bubble,
                            s.bubbleOther,
                            { backgroundColor: palette.surface },
                          ]}
                        >
                          {content}
                        </View>
                      )}
                    </Pressable>
                  </SwipeToReply>
                  {features.reactions && messageReactions ? (
                    <View style={s.reactionRow}>
                      {[...messageReactions.entries()].map(([emoji, count]) => {
                        const active = myReaction === emoji;
                        return (
                          <TouchableOpacity
                            key={emoji}
                            style={[
                              s.reactionChip,
                              {
                                backgroundColor: palette.reactionBg,
                                borderColor: palette.border,
                              },
                              active && {
                                backgroundColor: palette.reactionActiveBg,
                                borderColor: palette.accent,
                              },
                            ]}
                            onPress={() => void react(m, emoji)}
                            activeOpacity={0.7}
                            accessibilityLabel={`React with ${emoji}`}
                          >
                            <Text style={s.reactionEmojiText}>{emoji}</Text>
                            {count > 1 ? (
                              <Text
                                style={[
                                  s.reactionCount,
                                  { color: palette.textMuted },
                                  active && {
                                    color: palette.reactionActiveText,
                                  },
                                ]}
                              >
                                {count}
                              </Text>
                            ) : null}
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                  ) : null}
                </View>
              </View>
            );
            })}
          </>
        )}
        {chatError ? (
          <TouchableOpacity
            style={[s.threadRetry, { backgroundColor: palette.surface }]}
            onPress={refreshConnection}
            activeOpacity={0.75}
            accessibilityLabel="Reconnect to the club chat"
          >
            <Ionicons name="refresh" size={13} color={palette.inlineIcon} />
            <Text style={[s.threadRetryText, { color: palette.text }]}>
              {chatError}
            </Text>
          </TouchableOpacity>
        ) : null}
        {!isChatRealtimeConfigured ? (
          <Text style={[s.threadError, { color: palette.textMuted }]}>
            Chat isn&apos;t connected to the server — messages stay on this device.
          </Text>
        ) : null}
      </ScrollView>

      <View
        ref={composerRef}
        style={[
          s.composer,
          {
            paddingBottom:
              keyboardHeight > 0 ? keyboardHeight + 8 : bottomInset + 10,
            backgroundColor: palette.composerBg,
            borderTopColor: palette.border,
          },
        ]}
      >
        {pendingImage ? (
          <View style={s.previewWrap}>
            <Image source={{ uri: pendingImage.uri }} style={s.preview} contentFit="cover" />
            <TouchableOpacity
              style={s.previewRemove}
              onPress={() => setPendingImage(null)}
              accessibilityLabel="Remove image"
            >
              <Ionicons name="close" size={12} color={colors.white} />
            </TouchableOpacity>
          </View>
        ) : null}
        {replyingTo ? (
          <View style={s.replyBanner}>
            <Ionicons name="arrow-undo" size={13} color={palette.accentDeep} />
            <View style={{ flex: 1 }}>
              <Text
                style={[s.replyBannerName, { color: palette.accentDeep }]}
                numberOfLines={1}
              >
                {replyingTo.senderName || "Member"}
              </Text>
              <Text
                style={[s.replyBannerText, { color: palette.textMuted }]}
                numberOfLines={1}
              >
                {messagePreview(replyingTo)}
              </Text>
            </View>
            <TouchableOpacity
              onPress={() => setReplyingTo(null)}
              hitSlop={8}
              accessibilityLabel="Cancel reply"
            >
              <Ionicons name="close" size={16} color={palette.textMuted} />
            </TouchableOpacity>
          </View>
        ) : null}
        {editing ? (
          <View style={s.editBanner}>
            <Ionicons name="pencil" size={12} color={palette.accentDeep} />
            <Text
              style={[s.editBannerText, { color: palette.accentDeep }]}
              numberOfLines={1}
            >
              Editing message
            </Text>
            <TouchableOpacity
              onPress={cancelEdit}
              hitSlop={8}
              accessibilityLabel="Cancel edit"
            >
              <Ionicons name="close" size={16} color={palette.textMuted} />
            </TouchableOpacity>
          </View>
        ) : null}
        {mentionMatches.length ? (
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            keyboardShouldPersistTaps="handled"
            contentContainerStyle={s.mentionBar}
          >
            {mentionMatches.map((member, index) => (
                <TouchableOpacity
                  key={`${member.id || member.firstName}-${index}`}
                  style={[
                    s.mentionChip,
                    {
                      backgroundColor: palette.accentSoft,
                      borderColor: palette.accentSoft,
                    },
                  ]}
                  onPress={() => insertMention(member)}
                  activeOpacity={0.8}
                  accessibilityLabel={`Tag ${member.firstName}`}
                >
                  <Text
                    style={[s.mentionChipText, { color: palette.accentDeep }]}
                    numberOfLines={1}
                  >
                    @{member.firstName}
                  </Text>
                </TouchableOpacity>
            ))}
          </ScrollView>
        ) : null}
        <View style={s.composerRow}>
          <TouchableOpacity
            style={[s.attachBtn, { backgroundColor: palette.surfaceAlt }]}
            onPress={pickImage}
            disabled={sending || !!editing}
            accessibilityLabel="Attach an image"
          >
            {sending ? (
              <ActivityIndicator size="small" color={palette.inlineIcon} />
            ) : (
              <Ionicons
                name="image-outline"
                size={21}
                color={palette.inlineIcon}
              />
            )}
          </TouchableOpacity>
          <TextInput
            ref={inputRef}
            style={[
              s.input,
              { backgroundColor: palette.fieldBg, color: palette.fieldText },
            ]}
            placeholder={
              editing ? "Edit message…" : "Write a message… (@ to tag)"
            }
            placeholderTextColor={palette.placeholder}
            value={draft}
            onChangeText={changeDraft}
            multiline
            maxLength={1000}
          />
          <TouchableOpacity
            style={[
              s.sendBtn,
              { backgroundColor: palette.sendBg },
              !canSend && { backgroundColor: palette.sendDisabledBg },
            ]}
            onPress={send}
            disabled={!canSend}
            activeOpacity={0.85}
            accessibilityLabel="Send message"
          >
            <Ionicons
              name="send"
              size={18}
              color={canSend ? palette.sendText : palette.sendDisabledText}
            />
          </TouchableOpacity>
        </View>
      </View>

      {actionMsg ? (
        <MessageActionsModal
          message={actionMsg}
          mine={!!myUid && actionMsg.senderId === myUid}
          myReaction={myReactionFor(String(actionMsg.id))}
          canReact={features.reactions && !!myUid}
          canEditMessage={features.edits}
          palette={palette}
          onClose={() => setActionMsg(null)}
          onCopy={() => void Clipboard.setStringAsync(actionMsg.text ?? "").catch(() => {})}
          onEdit={() => startEdit(actionMsg)}
          onDelete={() => void deleteMessage(actionMsg)}
          onReact={(emoji) => void react(actionMsg, emoji)}
        />
      ) : null}

      <Modal
        visible={!!viewerUrl}
        transparent
        animationType="fade"
        statusBarTranslucent
        onRequestClose={() => setViewerUrl(null)}
      >
        <View style={s.viewer}>
          <Pressable
            style={StyleSheet.absoluteFill}
            onPress={() => setViewerUrl(null)}
            accessibilityLabel="Close image"
          >
            {viewerUrl ? (
              <Image
                source={{ uri: getOptimizedImageUrl(viewerUrl, 1200) }}
                style={s.viewerImage}
                contentFit="contain"
              />
            ) : null}
          </Pressable>
          <View
            style={[s.viewerBar, { paddingBottom: bottomInset + 24 }]}
            pointerEvents="box-none"
          >
            <TouchableOpacity
              style={s.viewerBtn}
              onPress={() => setViewerUrl(null)}
              accessibilityLabel="Close image"
            >
              <Ionicons name="close" size={22} color={colors.white} />
            </TouchableOpacity>
            <TouchableOpacity
              style={s.viewerBtn}
              onPress={saveViewerImage}
              disabled={savingImage}
              accessibilityLabel="Save image to gallery"
            >
              {savingImage ? (
                <ActivityIndicator size="small" color={colors.white} />
              ) : (
                <Ionicons name="download-outline" size={22} color={colors.white} />
              )}
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </View>
  );
}

