const drawerListeners = new Set<(open: boolean) => void>();

/** Whether the study library drawer is open (hides the floating tab bar). */
export function setDrawerOpen(open: boolean) {
  drawerListeners.forEach((l) => l(open));
}

export function subscribeDrawerOpen(listener: (open: boolean) => void) {
  drawerListeners.add(listener);
  return () => {
    drawerListeners.delete(listener);
  };
}

// Unlike the drawer flag above, this one stores state and replays it to late
// subscribers — the tab bar can mount after the loader has already hidden it.
// Starts hidden: a cold start begins on the welcome, so the bar must never
// paint for a frame before the landing loader mounts.
let tabBarHidden = true;
const tabBarListeners = new Set<(hidden: boolean) => void>();

/** Whether a full-screen moment (e.g. the home landing loader) hides the floating tab bar. */
export function setTabBarHidden(hidden: boolean) {
  tabBarHidden = hidden;
  tabBarListeners.forEach((l) => l(hidden));
}

export function subscribeTabBarHidden(listener: (hidden: boolean) => void) {
  tabBarListeners.add(listener);
  listener(tabBarHidden);
  return () => {
    tabBarListeners.delete(listener);
  };
}
