export type ClubPillar = "Shift" | "Sanctuary" | "Connect";

export const PILLARS: ClubPillar[] = ["Shift", "Sanctuary", "Connect"];

export type ClubProgram = {
  name: string;
  blurb: string;
  /** Which pillar this program sits under (Sprout programs stay ungrouped). */
  pillar?: ClubPillar;
  /** What a typical activity session looks like (shown on the program detail screen). */
  detail?: string;
  /** Extra fields collected when requesting help for this program. */
  helpFields?: {
    key: string;
    label: string;
    placeholder?: string;
    multiline?: boolean;
  }[];
  /** Thumbnail shown on the program card (e.g. a photo children can relate to). */
  image?: string;
};

export type Club = {
  slug: string;
  name: string;
  group: string;
  ageRange: string;
  tagline: string;
  description: string;
  color: string;
  colorDark: string;
  icon: string;
  programs: ClubProgram[];
  /** When set, this club is an age class that belongs under a parent club (e.g. Sprout's Kids/Tweens/Teens). */
  parentSlug?: string;
  /** Hero photo for this club's detail page (overrides the color gradient when set). */
  heroImage?: string;
  /** WhatsApp group invite link for this club's community. */
  whatsappGroupLink: string;
  /** Mission and vision from the foundation blueprint (clubs above Sprout). */
  mission?: string;
  vision?: string;
  /** Club-specific name for each pillar (e.g. Surge's Shift pillar = "Runway"). */
  pillarLabels?: Record<ClubPillar, string>;
  /** Fields collected by the club's unique registration form (before joining the WhatsApp group). */
  registrationFields: {
    key: string;
    label: string;
    placeholder?: string;
    multiline?: boolean;
  }[];
};

