/** Group a club's programs by pillar. Clubs whose programs carry no pillar
 *  (Sprout) come back as a single unnamed group. */
export function programsByPillar(
  club: Club,
): { pillar: ClubPillar | null; label: string | null; programs: ClubProgram[] }[] {
  const grouped: {
    pillar: ClubPillar | null;
    label: string | null;
    programs: ClubProgram[];
  }[] = PILLARS.map((pillar) => ({
    pillar,
    label: club.pillarLabels?.[pillar] ?? null,
    programs: club.programs.filter((p) => p.pillar === pillar),
  })).filter((g) => g.programs.length > 0);

  const ungrouped = club.programs.filter((p) => !p.pillar);
  if (ungrouped.length > 0)
    grouped.push({ pillar: null, label: null, programs: ungrouped });
  return grouped;
}

export function getClub(slug: string | undefined): Club | undefined {
  return CLUBS.find((c) => c.slug === slug);
}

/**
 * Clubs with their own content (magazines/bulletins). Purely an umbrella name,
 * "sprout" carries no content of its own — its material belongs to its classes.
 */
export const CONTENT_CLUBS: Club[] = CLUBS.filter((c) => c.slug !== "sprout");

/** Age-class clubs that belong under a parent club (e.g. Sprout's Kids/Tweens/Teens). */
export function getClubClasses(slug: string | undefined): Club[] {
  return CLUBS.filter((c) => c.parentSlug === slug);
}
