type IconName = React.ComponentProps<typeof Ionicons>["name"];

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];
const MIN_YEAR = 2020;
const MAX_YEAR = 2100;

/**
 * Each source keeps its own hue so a merged day reads at a glance. Badge text
 * uses a darkened ink of the same hue — the full-chroma dot colour is far too
 * light to read on its own tint.
 */
const SOURCE_META: Record<
  CalendarFeedSource,
  { label: string; one: string; dot: string; tint: string; ink: string; icon: IconName }
> = {
  program: {
    label: "Programme",
    one: "programme date",
    dot: colors.forest,
    tint: "rgba(11,25,44,0.08)",
    ink: colors.forest,
    icon: "calendar-outline",
  },
  event: {
    label: "Events",
    one: "event",
    dot: colors.gold,
    tint: "rgba(19,197,221,0.16)",
    ink: "#0b6b7d",
    icon: "sparkles-outline",
  },
  board: {
    label: "Meetings",
    one: "board meeting",
    dot: colors.emerald,
    tint: "rgba(16,185,129,0.16)",
    ink: colors.emeraldDark,
    icon: "people-outline",
  },
  training: {
    label: "Trainings",
    one: "training",
    dot: colors.amber,
    tint: "rgba(245,158,11,0.18)",
    ink: "#8a4b06",
    icon: "school-outline",
  },
};

const SOURCE_ORDER: CalendarFeedSource[] = ["program", "event", "board", "training"];

function toISO(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function fromISO(iso: string): Date {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, m - 1, d);
}

function shiftISO(iso: string, days: number): string {
  const d = fromISO(iso);
  d.setDate(d.getDate() + days);
  return toISO(d);
}

function longDate(iso: string): string {
  return fromISO(iso).toLocaleDateString("en-US", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
}

function shortDate(iso: string): string {
  return fromISO(iso).toLocaleDateString("en-US", { day: "numeric", month: "short" });
}

/**
 * Every day an item covers, so a camp or a multi-day training shows on all of
 * its dates rather than only the day it starts.
 */
function indexByDay(items: CalendarFeedItem[]): Map<string, CalendarFeedItem[]> {
  const index = new Map<string, CalendarFeedItem[]>();
  for (const item of items) {
    const last = item.endDate && item.endDate > item.date ? item.endDate : item.date;
    let day = item.date;
    // A year holds at most 366 days, so this always terminates on valid data.
    for (let guard = 0; guard < 400 && day <= last; guard++) {
      const rows = index.get(day);
      if (rows) rows.push(item);
      else index.set(day, [item]);
      day = shiftISO(day, 1);
    }
  }
  return index;
}

function monthPrefix(year: number, month: number): string {
  return `${year}-${String(month + 1).padStart(2, "0")}-`;
}

/** Rows touching a month, including a span that began in the month before. */
function monthRows(
  index: Map<string, CalendarFeedItem[]>,
  year: number,
  month: number,
): CalendarFeedItem[] {
  const prefix = monthPrefix(year, month);
  const seen = new Map<string, CalendarFeedItem>();
  for (const [iso, rows] of index) {
    if (!iso.startsWith(prefix)) continue;
    for (const row of rows) if (!seen.has(row.id)) seen.set(row.id, row);
  }
  return [...seen.values()].sort((a, b) => a.date.localeCompare(b.date));
}

/** The first day of a month that has anything on it, so stepping months never lands on a blank. */
function firstBusyDay(
  index: Map<string, CalendarFeedItem[]>,
  year: number,
  month: number,
): string | null {
  const prefix = monthPrefix(year, month);
  let first: string | null = null;
  for (const iso of index.keys()) {
    if (iso.startsWith(prefix) && (first === null || iso < first)) first = iso;
  }
  return first;
}

function hexRgb(hex: string): [number, number, number] | null {
  const raw = hex.replace("#", "");
  if (raw.length !== 6) return null;
  const n = Number.parseInt(raw, 16);
  if (!Number.isFinite(n)) return null;
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/**
 * Club hues are brand colours, not UI colours: most sit under 3:1 on white.
 * Darken the same hue until it clears the ratio the element needs — 0.15 for
 * text on its own tint, 0.30 for a 4px dot on the grid.
 */
function shade(rgb: [number, number, number], maxLuminance: number): string {
  let [r, g, b] = rgb;
  const luminance = () => {
    const channel = (v: number) => {
      const c = v / 255;
      return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
  };
  while (luminance() > maxLuminance && r + g + b > 0) {
    r = Math.floor(r * 0.85);
    g = Math.floor(g * 0.85);
    b = Math.floor(b * 0.85);
  }
  return `rgb(${r},${g},${b})`;
}

/** Events wear their club's colour, so a merged day shows who is running what. */
function clubTone(color: string, colorDark: string) {
  const rgb = hexRgb(color);
  const dark = hexRgb(colorDark) ?? rgb;
  if (!rgb || !dark) return null;
  return {
    dot: shade(rgb, 0.3),
    tint: `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0.14)`,
    ink: shade(dark, 0.15),
  };
}

/** A programme row back into the shape the entry form and the save API use. */
function toEntry(item: CalendarFeedItem): ProgramCalendarEntry {
  return {
    id: item.refId,
    date: item.date,
    ...(item.endDate ? { endDate: item.endDate } : {}),
    title: item.title,
    ...(item.description ? { description: item.description } : {}),
    ...(item.time ? { time: item.time } : {}),
    ...(item.location ? { location: item.location } : {}),
    ...(item.term ? { term: item.term } : {}),
    ...(item.setting ? { setting: item.setting } : {}),
  };
}

/**
 * Everything Relate runs, on one calendar: the published year plan, community
 * and club events, and — for admins — board meetings and trainings.
 *
 * Members read. Only an admin the server recognises sees any authoring control,
 * and the calendar only authors programme dates; every other row is edited in
 * the screen that owns it.
 */
export default function CalendarScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { find, allClubs } = useClubs();

  const [scopeChip, setScopeChip] = useState(ALL_CLUBS);
  const [year, setYear] = useState(new Date().getFullYear());
  const [feed, setFeed] = useState<CalendarFeed | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sourceFilter, setSourceFilter] = useState<CalendarFeedSource | "all">("all");
  const [view, setView] = useState<"month" | "year">("month");
  const [month, setMonth] = useState(new Date().getMonth());
  const [selected, setSelected] = useState(toISO(new Date()));
  const [expanded, setExpanded] = useState<string | null>(null);
  const [showEditor, setShowEditor] = useState(false);
  const [editing, setEditing] = useState<ProgramCalendarEntry | null>(null);
  const [editorScope, setEditorScope] = useState(ORGANIZATION_SCOPE);
  const [busy, setBusy] = useState(false);
  const [reload, setReload] = useState(0);

  const keepReader = useRef(false);
  // Set when stepping over New Year: the month the user asked for, to be
  // resolved against the new year's dates once they arrive.
  const pendingMonth = useRef<number | null>(null);

  const wireScope =
    scopeChip === ALL_CLUBS ? ALL_SCOPES : scopeChip || ORGANIZATION_SCOPE;
  // The server decides who is an admin, so authoring controls can never appear
  // for a member by way of a stale client-side session.
  const isAdmin = feed?.isAdmin === true;
  const club = find(wireScope);
  const accent = club?.color ?? colors.forest;
  const accentDark = club?.colorDark ?? colors.forestSoft;
  const scopeName =
    scopeChip === ALL_CLUBS ? "Relate" : feed?.scopeName || club?.name || "Relate";

  const clubTones = useMemo(() => {
    const tones = new Map<string, { dot: string; tint: string; ink: string }>();
    for (const c of allClubs) {
      const tone = clubTone(c.color, c.colorDark);
      if (tone) tones.set(c.slug, tone);
    }
    return tones;
  }, [allClubs]);

  /** An organisation-wide event has no club, so it keeps the Relate accent. */
  const toneOf = (item: CalendarFeedItem) => {
    const base = SOURCE_META[item.source];
    const own = item.source === "event" ? clubTones.get(item.scope) : undefined;
    return { meta: own ? { ...base, ...own } : base, own };
  };

  /** Place the reader on today, or on the year's first date when it's a future year. */
  const placeReader = useCallback((rows: CalendarFeedItem[], forYear: number) => {
    const today = new Date();
    if (today.getFullYear() === forYear) {
      setMonth(today.getMonth());
      setSelected(toISO(today));
      return;
    }
    const first = rows[0];
    if (first) {
      setMonth(fromISO(first.date).getMonth());
      setSelected(first.date);
      return;
    }
    setMonth(0);
    setSelected(`${forYear}-01-01`);
  }, []);

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await fetchCalendarFeed(year, wireScope);
        if (!active) return;
        setFeed(res);
        setExpanded(null);
        const asked = pendingMonth.current;
        pendingMonth.current = null;
        if (asked !== null) {
          const index = indexByDay(res.items);
          setMonth(asked);
          setSelected(
            firstBusyDay(index, res.year, asked) ?? `${monthPrefix(res.year, asked)}01`,
          );
        } else if (!keepReader.current) {
          placeReader(res.items, res.year);
        }
      } catch (e: any) {
        if (!active) return;
        setFeed(null);
        setError(e?.message || "Couldn't load the calendar. Check your connection.");
      } finally {
        if (active) {
          keepReader.current = false;
          setLoading(false);
        }
      }
    })();
    return () => {
      active = false;
    };
  }, [year, wireScope, reload, placeReader]);

  const items = useMemo(() => feed?.items ?? [], [feed]);
  const visible = useMemo(
    () => (sourceFilter === "all" ? items : items.filter((i) => i.source === sourceFilter)),
    [items, sourceFilter],
  );
  const counts = useMemo(() => {
    const tally: Partial<Record<CalendarFeedSource, number>> = {};
    for (const item of items) tally[item.source] = (tally[item.source] ?? 0) + 1;
    return tally;
  }, [items]);
  const presentSources = SOURCE_ORDER.filter((source) => (counts[source] ?? 0) > 0);

  const byDay = useMemo(() => indexByDay(visible), [visible]);
  const dayItems = byDay.get(selected) ?? [];
  const monthItems = useMemo(() => monthRows(byDay, year, month), [byDay, year, month]);

  const monthGroups = useMemo(() => {
    const groups: { month: number; rows: CalendarFeedItem[] }[] = [];
    for (const item of visible) {
      const m = fromISO(item.date).getMonth();
      const last = groups[groups.length - 1];
      if (last && last.month === m) last.rows.push(item);
      else groups.push({ month: m, rows: [item] });
    }
    return groups;
  }, [visible]);

  const changeScope = (slug: string) => {
    if (slug === scopeChip) return;
    setScopeChip(slug);
    setSourceFilter("all");
    setFeed(null);
  };

  const changeYear = (next: number) => {
    if (next < MIN_YEAR || next > MAX_YEAR || next === year) return;
    setYear(next);
  };

  const shiftMonth = (delta: number) => {
    const next = month + delta;
    if (next < 0) {
      if (year <= MIN_YEAR) return;
      // Stepping over New Year loads another year; the reader stays on the
      // month the user asked for instead of jumping to that year's first date.
      keepReader.current = true;
      pendingMonth.current = 11;
      setMonth(11);
      changeYear(year - 1);
      setSelected(`${year - 1}-12-01`);
      return;
    }
    if (next > 11) {
      if (year >= MAX_YEAR) return;
      keepReader.current = true;
      pendingMonth.current = 0;
      setMonth(0);
      changeYear(year + 1);
      setSelected(`${year + 1}-01-01`);
      return;
    }
    setMonth(next);
    // Land on the month's first scheduled day: the 1st is usually blank, and a
    // blank day list reads as "this month has nothing" when it plainly does.
    setSelected(firstBusyDay(byDay, year, next) ?? `${monthPrefix(year, next)}01`);
  };

  const jumpToday = () => {
    const today = new Date();
    keepReader.current = true;
    if (today.getFullYear() !== year) changeYear(today.getFullYear());
    setMonth(today.getMonth());
    setSelected(toISO(today));
  };

  const refresh = () => {
    keepReader.current = true;
    setReload((r) => r + 1);
  };

  const openCreate = () => {
    setEditing(null);
    setEditorScope(scopeChip === ALL_CLUBS ? ORGANIZATION_SCOPE : wireScope);
    setShowEditor(true);
  };

  const openEdit = (item: CalendarFeedItem) => {
    setEditing(toEntry(item));
    setEditorScope(item.scope);
    setShowEditor(true);
  };

  /**
   * The feed is a projection of the year, so a write reads the stored year
   * first — upserting the rows on screen would drop anything it filtered out.
   */
  const saveEntry = async (entry: ProgramCalendarEntry) => {
    // A date belongs to the year it falls in, not the year being browsed.
    const targetYear = Number(entry.date.slice(0, 4));
    const current = await fetchScopedCalendar(editorScope, targetYear);
    const exists = current.entries.some((e) => e.id === entry.id);
    const rows = exists
      ? current.entries.map((e) => (e.id === entry.id ? entry : e))
      : [...current.entries, entry];
    await saveCalendarEntries(editorScope, targetYear, rows);
    keepReader.current = true;
    if (targetYear !== year) setYear(targetYear);
    setReload((r) => r + 1);
    setMonth(fromISO(entry.date).getMonth());
    setSelected(entry.date);
  };

  const confirmDelete = (item: CalendarFeedItem) => {
    Alert.alert("Remove date", `Remove "${item.title}" from the ${year} programme?`, [
      { text: "Cancel", style: "cancel" },
      {
        text: "Remove",
        style: "destructive",
        onPress: async () => {
          setBusy(true);
          try {
            const current = await fetchScopedCalendar(item.scope, year);
            await saveCalendarEntries(
              item.scope,
              year,
              current.entries.filter((e) => e.id !== item.refId),
            );
            refresh();
          } catch (e: any) {
            Alert.alert("Couldn't remove", e?.message || "Please try again.");
          } finally {
            setBusy(false);
          }
        },
      },
    ]);
  };

  const programmeCount = counts.program ?? 0;

  const confirmClearYear = () => {
    Alert.alert(
      "Clear the programme",
      `Delete all ${programmeCount} programme dates in the ${year} ${scopeName} calendar? Events, meetings and trainings are not affected. This can't be undone.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete dates",
          style: "destructive",
          onPress: async () => {
            setBusy(true);
            try {
              await deleteCalendarYear(wireScope, year);
              refresh();
            } catch (e: any) {
              Alert.alert("Couldn't delete", e?.message || "Please try again.");
            } finally {
              setBusy(false);
            }
          },
        },
      ],
    );
  };

  const exportable = useMemo(() => visible.filter(isExportable), [visible]);
  const keptInApp = visible.length - exportable.length;

  const exportIcs = (item?: CalendarFeedItem) => {
    const count = item ? 1 : exportable.length;
    if (count === 0) {
      Alert.alert(
        "Nothing to export",
        keptInApp > 0
          ? "Board meetings and trainings stay in the app, so there's nothing here for a calendar file."
          : `Nothing is published for ${year} yet.`,
      );
      return;
    }
    const url = calendarFeedIcsUrl(year, wireScope, item?.id);
    Alert.alert(
      item ? "Add this date" : `Add ${year} to your calendar`,
      `This opens a calendar file (.ics) with ${count} ${count === 1 ? "date" : "dates"}. Choose your calendar app to import ${count === 1 ? "it" : "them"}.` +
        (!item && keptInApp > 0
          ? " Board meetings and trainings stay in the app and aren't in the file."
          : ""),
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Open",
          onPress: async () => {
            try {
              await Linking.openURL(url);
            } catch {
              Alert.alert("Couldn't open the file", "Check that your phone has a browser or calendar app available.");
            }
          },
        },
      ],
    );
  };

  /** Admins edit each row where it lives; the calendar only owns programme dates. */
  const openAtSource = (item: CalendarFeedItem) => {
    if (item.source === "event") {
      router.push("/events");
      return;
    }
    if (item.source === "board") {
      router.push(`/admin/board-governance/meetings/${item.refId}` as any);
      return;
    }
    if (item.source === "training") {
      router.push(`/admin/trainings/${item.refId}` as any);
    }
  };

  const sourceActionLabel = (source: CalendarFeedSource) =>
    source === "event" ? "Edit in Events" : source === "board" ? "Open meeting" : "Open training";

  const renderItem = (item: CalendarFeedItem, showDate: boolean) => {
    const { meta, own } = toneOf(item);
    const when = fromISO(item.date);
    const open = expanded === item.id;
    const spans = !!item.endDate && item.endDate > item.date;
    const line = [item.time, item.location].filter(Boolean).join(" · ");
    const tags = [item.term, item.setting].filter(Boolean) as string[];
    return (
      <View key={item.id} style={[s.item, open && { borderColor: meta.dot }]}>
        <TouchableOpacity
          style={s.itemMain}
          onPress={() => setExpanded(open ? null : item.id)}
          activeOpacity={0.7}
          accessibilityState={{ expanded: open }}
          accessibilityLabel={`${item.kind}: ${item.title}, ${longDate(item.date)}`}
        >
          <View style={[s.dateChip, { backgroundColor: meta.tint }]}>
            <Text style={[s.dateWeekday, { color: meta.ink }]}>
              {showDate
                ? MONTHS[when.getMonth()].slice(0, 3)
                : when.toLocaleDateString("en-US", { weekday: "short" })}
            </Text>
            <Text style={[s.dateDay, { color: meta.ink }]}>{when.getDate()}</Text>
          </View>
          <View style={s.itemBody}>
            <View style={s.badgeRow}>
              <View style={[s.badge, { backgroundColor: meta.tint }]}>
                <Ionicons name={meta.icon} size={10} color={meta.ink} />
                <Text style={[s.badgeText, { color: meta.ink }]} numberOfLines={1}>
                  {item.kind}
                </Text>
              </View>
              {scopeChip === ALL_CLUBS ? (
                <Text style={[s.scopeTag, own && { color: own.ink }]} numberOfLines={1}>
                  {item.scopeName}
                </Text>
              ) : null}
            </View>
            <Text style={s.itemTitle} numberOfLines={open ? undefined : 2}>
              {item.title}
            </Text>
            {spans ? (
              <Text style={s.itemSpan}>
                {shortDate(item.date)} – {shortDate(item.endDate!)}
              </Text>
            ) : null}
            {line ? <Text style={s.itemMeta} numberOfLines={open ? undefined : 1}>{line}</Text> : null}
          </View>
          <Ionicons
            name={open ? "chevron-up" : "chevron-down"}
            size={16}
            color={colors.muted}
            style={s.chevron}
          />
        </TouchableOpacity>

        {open ? (
          <View style={s.itemDetail}>
            {item.description ? (
              <Text style={s.itemBlurb}>{item.description}</Text>
            ) : (
              <Text style={s.itemBlurbMuted}>No further details published.</Text>
            )}
            {tags.length ? (
              <View style={s.tagRow}>
                {tags.map((tag) => (
                  <View key={tag} style={s.tag}>
                    <Text style={s.tagText}>{tag}</Text>
                  </View>
                ))}
              </View>
            ) : null}
            <View style={s.actionRow}>
              {isExportable(item) ? (
                <TouchableOpacity
                  style={s.actionBtn}
                  onPress={() => exportIcs(item)}
                  activeOpacity={0.8}
                  accessibilityLabel={`Add ${item.title} to my calendar`}
                >
                  <Ionicons name="download-outline" size={15} color={colors.forestDark} />
                  <Text style={s.actionText}>Add to my calendar</Text>
                </TouchableOpacity>
              ) : (
                <View style={s.privateNote}>
                  <Ionicons name="lock-closed-outline" size={13} color={colors.muted} />
                  <Text style={s.privateNoteText}>Admin only — stays in the app</Text>
                </View>
              )}
              {isAdmin ? (
                item.source === "program" ? (
                  <View style={s.adminActions}>
                    <TouchableOpacity
                      style={s.iconBtn}
                      onPress={() => openEdit(item)}
                      disabled={busy}
                      accessibilityLabel={`Edit ${item.title}`}
                    >
                      <Ionicons name="create-outline" size={17} color={colors.forest} />
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={s.iconBtn}
                      onPress={() => confirmDelete(item)}
                      disabled={busy}
                      accessibilityLabel={`Remove ${item.title}`}
                    >
                      <Ionicons name="trash-outline" size={17} color={colors.error} />
                    </TouchableOpacity>
                  </View>
                ) : (
                  <TouchableOpacity
                    style={s.actionBtn}
                    onPress={() => openAtSource(item)}
                    activeOpacity={0.8}
                    accessibilityLabel={`${sourceActionLabel(item.source)}: ${item.title}`}
                  >
                    <Ionicons name="create-outline" size={15} color={colors.forestDark} />
                    <Text style={s.actionText}>{sourceActionLabel(item.source)}</Text>
                  </TouchableOpacity>
                )
              ) : null}
            </View>
          </View>
        ) : null}
      </View>
    );
  };

  const offset = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const todayISO = toISO(new Date());
  const cells: (number | null)[] = [];
  for (let i = 0; i < 42; i++) {
    const day = i - offset + 1;
    cells.push(day >= 1 && day <= daysInMonth ? day : null);
  }
  const monthCount = monthItems.length;
  const otherYears = (feed?.programmeYears ?? []).filter((y) => y !== year);

  return (
    <View style={[s.safe, { paddingTop: insets.top }]}>
      <View style={s.header}>
        <TouchableOpacity style={s.backBtn} onPress={() => router.back()} accessibilityLabel="Back">
          <Ionicons name="chevron-back" size={22} color={colors.forest} />
        </TouchableOpacity>
        <View style={{ flex: 1 }}>
          <Text style={s.headerTitle}>Calendar</Text>
          <Text style={s.headerSub}>Programmes, events, meetings &amp; trainings</Text>
        </View>
        <TouchableOpacity onPress={() => exportIcs()} activeOpacity={0.85} accessibilityLabel="Export this year to my calendar">
          <LinearGradient
            colors={colors.gradients.accent as [string, string]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.exportBtn}
          >
            <Ionicons name="download-outline" size={16} color={colors.forest} />
            <Text style={s.exportBtnText}>Export</Text>
          </LinearGradient>
        </TouchableOpacity>
      </View>

      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={[s.body, { paddingBottom: insets.bottom + 32 }]}
        showsVerticalScrollIndicator={false}
      >
        <ClubSelect
          value={scopeChip}
          onChange={changeScope}
          label="Whose calendar?"
          allowAll
          allowOrganization
        />

        <View style={s.controlRow}>
          <View style={s.yearStepper}>
            <TouchableOpacity
              style={[s.stepBtn, year <= MIN_YEAR && s.stepBtnDisabled]}
              onPress={() => changeYear(year - 1)}
              disabled={year <= MIN_YEAR}
              accessibilityLabel="Previous year"
            >
              <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <Text style={s.yearText}>{year}</Text>
            <TouchableOpacity
              style={[s.stepBtn, year >= MAX_YEAR && s.stepBtnDisabled]}
              onPress={() => changeYear(year + 1)}
              disabled={year >= MAX_YEAR}
              accessibilityLabel="Next year"
            >
              <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
            </TouchableOpacity>
          </View>
          <View style={s.viewToggle}>
            {(["month", "year"] as const).map((option) => (
              <TouchableOpacity
                key={option}
                style={[s.viewBtn, view === option && s.viewBtnActive]}
                onPress={() => setView(option)}
                accessibilityState={{ selected: view === option }}
              >
                <Text style={[s.viewBtnText, view === option && s.viewBtnTextActive]}>
                  {option === "month" ? "Month" : "Whole year"}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {!loading && !error && presentSources.length > 1 ? (
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.filterRow}>
            <TouchableOpacity
              style={[s.filterChip, sourceFilter === "all" && s.filterChipActive]}
              onPress={() => setSourceFilter("all")}
              activeOpacity={0.8}
              accessibilityState={{ selected: sourceFilter === "all" }}
            >
              <Text style={[s.filterText, sourceFilter === "all" && s.filterTextActive]}>
                All {items.length}
              </Text>
            </TouchableOpacity>
            {presentSources.map((source) => {
              const meta = SOURCE_META[source];
              const active = sourceFilter === source;
              return (
                <TouchableOpacity
                  key={source}
                  style={[s.filterChip, active && { backgroundColor: meta.tint, borderColor: meta.dot }]}
                  onPress={() => setSourceFilter(active ? "all" : source)}
                  activeOpacity={0.8}
                  accessibilityState={{ selected: active }}
                >
                  <View style={[s.filterDot, { backgroundColor: meta.dot }]} />
                  <Text style={[s.filterText, active && { color: meta.ink }]}>
                    {meta.label} {counts[source]}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        ) : null}

        {loading ? (
          <View style={s.card}>
            <SkeletonPulse style={{ height: 20, width: "45%", borderRadius: 6, alignSelf: "center", marginBottom: 14 }} />
            <View style={s.weekRow}>
              {WEEKDAYS.map((w) => (
                <Text key={w} style={s.weekLabel}>{w}</Text>
              ))}
            </View>
            <View style={s.grid}>
              {Array.from({ length: 42 }).map((_, i) => (
                <View key={i} style={s.cell}>
                  <SkeletonPulse style={{ height: 34, borderRadius: 17 }} />
                </View>
              ))}
            </View>
          </View>
        ) : error ? (
          <View style={s.notice}>
            <Ionicons name="cloud-offline-outline" size={32} color={colors.muted} />
            <Text style={s.noticeText}>{error}</Text>
            <TouchableOpacity
              style={s.noticeBtn}
              onPress={() => setReload((r) => r + 1)}
              activeOpacity={0.85}
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={s.noticeBtnText}>Try again</Text>
            </TouchableOpacity>
          </View>
        ) : (
          <>
            {view === "month" ? (
              <View style={s.card}>
                <View style={s.monthHead}>
                  <TouchableOpacity style={s.stepBtn} onPress={() => shiftMonth(-1)} accessibilityLabel="Previous month">
                    <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
                  </TouchableOpacity>
                  <View style={{ flex: 1, alignItems: "center" }}>
                    <Text style={s.monthTitle}>{MONTHS[month]} {year}</Text>
                    <Text style={s.monthCount}>
                      {monthCount === 0 ? "Nothing planned" : `${monthCount} scheduled`}
                    </Text>
                  </View>
                  <TouchableOpacity style={s.todayBtn} onPress={jumpToday} accessibilityLabel="Jump to today">
                    <Text style={s.todayText}>Today</Text>
                  </TouchableOpacity>
                  <TouchableOpacity style={s.stepBtn} onPress={() => shiftMonth(1)} accessibilityLabel="Next month">
                    <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
                  </TouchableOpacity>
                </View>

                <View style={s.weekRow}>
                  {WEEKDAYS.map((w) => (
                    <Text key={w} style={s.weekLabel}>{w}</Text>
                  ))}
                </View>

                <View style={s.grid}>
                  {cells.map((day, i) => {
                    if (day === null) return <View key={i} style={s.cell} />;
                    const iso = toISO(new Date(year, month, day));
                    const rows = byDay.get(iso) ?? [];
                    // One dot per colour, so two clubs on the same day read as
                    // two dots while a club's own programme and event share one.
                    const dots = [...new Set(rows.map((row) => toneOf(row).meta.dot))].slice(0, 4);
                    const isSelected = iso === selected;
                    const isToday = iso === todayISO;
                    return (
                      <View key={i} style={s.cell}>
                        <TouchableOpacity
                          style={[
                            s.day,
                            isToday && !isSelected && { borderWidth: 1.5, borderColor: accent },
                            isSelected && { backgroundColor: accent },
                          ]}
                          onPress={() => setSelected(iso)}
                          activeOpacity={0.7}
                          accessibilityLabel={`${longDate(iso)}${rows.length ? `, ${rows.length} scheduled` : ", nothing planned"}`}
                          accessibilityState={{ selected: isSelected }}
                        >
                          <Text style={[s.dayText, isSelected && s.dayTextActive]}>{day}</Text>
                          {dots.length ? (
                            <View style={s.dotRow}>
                              {dots.map((dot) => (
                                <View
                                  key={dot}
                                  style={[
                                    s.dot,
                                    { backgroundColor: isSelected ? colors.white : dot },
                                  ]}
                                />
                              ))}
                            </View>
                          ) : null}
                        </TouchableOpacity>
                      </View>
                    );
                  })}
                </View>
              </View>
            ) : null}

            {view === "month" && items.length === 0 && otherYears.length ? (
              <View style={s.yearHint}>
                <Text style={s.yearHintText}>
                  Nothing is published for {year}. These years have dates:
                </Text>
                <View style={s.yearJumpRow}>
                  {otherYears.map((y) => (
                    <TouchableOpacity key={y} style={s.yearJump} onPress={() => changeYear(y)} activeOpacity={0.8}>
                      <Ionicons name="calendar-outline" size={14} color={colors.forestDark} />
                      <Text style={s.yearJumpText}>{y}</Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </View>
            ) : null}

            {view === "month" ? (
              <View style={s.daySection}>
                <View style={s.dayHead}>
                  <View style={{ flex: 1 }}>
                    <Text style={s.dayTitle}>{longDate(selected)}</Text>
                    <Text style={s.daySub}>
                      {dayItems.length === 0
                        ? "Nothing planned"
                        : `${dayItems.length} scheduled`}
                    </Text>
                  </View>
                  {isAdmin ? (
                    <TouchableOpacity style={s.addBtn} onPress={openCreate} activeOpacity={0.85} disabled={busy}>
                      <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      <Ionicons name="add" size={16} color={colors.white} />
                      <Text style={s.addBtnText}>Add</Text>
                    </TouchableOpacity>
                  ) : null}
                </View>
                {dayItems.length > 0
                  ? dayItems.map((item) => renderItem(item, false))
                  : null}
                {dayItems.length === 0 && monthItems.length > 0 ? (
                  <>
                    <Text style={s.groupMonth}>Elsewhere in {MONTHS[month]}</Text>
                    {monthItems.map((item) => renderItem(item, true))}
                  </>
                ) : null}
                {dayItems.length === 0 && monthItems.length === 0 ? (
                  <View style={s.dayEmpty}>
                    <Ionicons name="calendar-clear-outline" size={22} color={colors.muted} />
                    <Text style={s.dayEmptyText}>
                      {isAdmin
                        ? "Tap Add to plan a programme date here."
                        : `Nothing in ${MONTHS[month]}. Try another month, or Whole year.`}
                    </Text>
                  </View>
                ) : null}
              </View>
            ) : visible.length === 0 ? (
              <View style={s.notice}>
                <Ionicons name="calendar-outline" size={36} color={colors.muted} />
                <Text style={s.noticeTitle}>
                  {items.length > 0
                    ? `No ${SOURCE_META[sourceFilter as CalendarFeedSource]?.label.toLowerCase()} in ${year}`
                    : `Nothing on for ${year}`}
                </Text>
                <Text style={s.noticeText}>
                  {items.length > 0
                    ? "Switch the filter back to All to see the rest of the year."
                    : isAdmin
                      ? `Nothing is published for ${year} yet. Switch to Month to pick a date and add the first one.`
                      : `Nothing has been published for ${year} yet.`}
                </Text>
                {items.length > 0 ? (
                  <TouchableOpacity style={s.noticeBtn} onPress={() => setSourceFilter("all")} activeOpacity={0.85}>
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                    <Text style={s.noticeBtnText}>Show everything</Text>
                  </TouchableOpacity>
                ) : otherYears.length ? (
                  <View style={s.yearJumpRow}>
                    {otherYears.map((y) => (
                      <TouchableOpacity key={y} style={s.yearJump} onPress={() => changeYear(y)} activeOpacity={0.8}>
                        <Ionicons name="calendar-outline" size={14} color={colors.forestDark} />
                        <Text style={s.yearJumpText}>{y}</Text>
                      </TouchableOpacity>
                    ))}
                  </View>
                ) : null}
                {items.length === 0 && isAdmin ? (
                  <TouchableOpacity
                    style={s.noticeBtn}
                    onPress={() => {
                      setView("month");
                      openCreate();
                    }}
                    activeOpacity={0.85}
                  >
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                    <Ionicons name="add" size={16} color={colors.white} />
                    <Text style={s.noticeBtnText}>Add the first date</Text>
                  </TouchableOpacity>
                ) : null}
              </View>
            ) : (
              <>
                {monthGroups.map((group) => (
                  <View key={group.month}>
                    <Text style={s.groupMonth}>{MONTHS[group.month]} {year}</Text>
                    {group.rows.map((item) => renderItem(item, true))}
                  </View>
                ))}
                {isAdmin && scopeChip !== ALL_CLUBS && programmeCount > 0 ? (
                  <TouchableOpacity style={s.clearBtn} onPress={confirmClearYear} disabled={busy} activeOpacity={0.8}>
                    {busy ? (
                      <ActivityIndicator size="small" color={colors.error} />
                    ) : (
                      <Ionicons name="trash-outline" size={15} color={colors.error} />
                    )}
                    <Text style={s.clearBtnText}>Delete the {year} programme dates</Text>
                  </TouchableOpacity>
                ) : null}
              </>
            )}

            {exportable.length > 0 ? (
              <TouchableOpacity style={s.exportRow} onPress={() => exportIcs()} activeOpacity={0.8}>
                <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
                <Text style={s.exportRowText}>
                  Add {exportable.length} {exportable.length === 1 ? "date" : "dates"} to my phone&apos;s calendar
                </Text>
                <Ionicons name="chevron-forward" size={15} color={colors.muted} />
              </TouchableOpacity>
            ) : null}

            <Text style={s.footNote}>
              {isAdmin
                ? "Programme dates are edited here. Events, board meetings and trainings are edited in their own screens."
                : "Relate's admins publish these dates. Tap any row for its details."}
            </Text>
          </>
        )}
      </ScrollView>

      {isAdmin ? (
        <CalendarEntryModal
          visible={showEditor}
          scopeName={
            editorScope === ORGANIZATION_SCOPE
              ? "Relate"
              : find(editorScope)?.name || editorScope
          }
          accent={accent}
          accentDark={accentDark}
          entry={editing}
          defaultDate={selected}
          scopePicker={
            scopeChip === ALL_CLUBS && !editing
              ? { value: editorScope, onChange: setEditorScope }
              : undefined
          }
          onClose={() => setShowEditor(false)}
          onSave={saveEntry}
        />
      ) : null}
    </View>
  );
}

