import { useSQLiteContext, type SQLiteDatabase } from "expo-sqlite";
import { API_BASE } from "@/services/config";
import { getRequestHeaders, getSessionToken } from "@/services/auth";

export type SyncAction = "insert" | "update" | "delete";

export async function enqueue(
  db: SQLiteDatabase,
  tableName: string,
  recordId: string,
  action: SyncAction,
  payload: Record<string, unknown>,
) {
  await db.runAsync(
    `INSERT INTO sync_queue (table_name, record_id, action, payload_json, created_at, synced)
     VALUES (?, ?, ?, ?, datetime('now'), 0)`,
    [tableName, recordId, action, JSON.stringify(payload)],
  );
}

/**
 * Enqueue a full-state replace for a table. Tracks a single pending entry per
 * (table, recordId) so batches of offline changes never pile up stale rows —
 * each new state simply replaces the previous pending one, and the last flush
 * reflects the latest full picture.
 */
export async function enqueueReplace(
  db: SQLiteDatabase,
  tableName: string,
  recordId: string,
  action: SyncAction,
  payload: Record<string, unknown>,
) {
  await db.runAsync(
    `DELETE FROM sync_queue WHERE table_name = ? AND record_id = ? AND synced = 0`,
    [tableName, recordId],
  );
  await enqueue(db, tableName, recordId, action, payload);
}

export async function flushSyncQueue(db: SQLiteDatabase) {
  const pending = await db.getAllSync<{
    id: number;
    table_name: string;
    record_id: string;
    action: string;
    payload_json: string;
  }>(`SELECT * FROM sync_queue WHERE synced = 0 ORDER BY created_at ASC LIMIT 50`);

  if (pending.length === 0) return;

  const token = await getSessionToken();
  if (!token) return;
  const headers = await getRequestHeaders({ "Content-Type": "application/json" });

  for (const item of pending) {
    try {
      const payload = JSON.parse(item.payload_json);
      const endpoint = getEndpoint(item.table_name);
      if (!endpoint) continue;

      const method = item.action === "delete" ? "DELETE" : item.action === "update" ? "PUT" : "POST";

      const res = await fetch(`${API_BASE}${endpoint}`, {
        method,
        headers,
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        await db.runAsync(`UPDATE sync_queue SET synced = 1 WHERE id = ?`, [item.id]);
      }
    } catch {
      // Will retry on next flush
    }
  }
}

function getEndpoint(tableName: string): string | null {
  switch (tableName) {
    case "highlights":
      return "/api/bible-highlights";
    case "bookmarks":
      return "/api/bookmarks";
    case "reading_progress":
      return "/api/reading-progress";
    case "prayer_preferences":
      return "/api/prayer-preferences";
    default:
      return null;
  }
}

export function useSyncQueue() {
  const db = useSQLiteContext();
  return {
    enqueue: (table: string, id: string, action: SyncAction, payload: Record<string, unknown>) =>
      enqueue(db, table, id, action, payload),
    flush: () => flushSyncQueue(db),
  };
}
