const USFM_TO_FRIENDLY: Record<string, string> = Object.entries(
  FRIENDLY_TO_USFM,
).reduce<Record<string, string>>((acc, [friendly, usfm]) => {
  acc[usfm] = friendly;
  return acc;
}, {});

const USFM_SET = new Set(Object.values(FRIENDLY_TO_USFM));

export function bookToUsfm(name: string): string {
  const trimmed = name?.trim() || "";
  if (USFM_SET.has(trimmed)) return trimmed;
  const cleaned = trimmed.replace(/\.$/, "").trim();
  return FRIENDLY_TO_USFM[cleaned] ?? "JHN";
}

export function usfmToFriendly(code: string): string {
  const upper = (code || "").toUpperCase();
  return USFM_TO_FRIENDLY[upper] ?? "John";
}

export function parsePassageId(passageId: string): {
  book: string;
  chapter: number;
  verse?: number;
} | null {
  const match = passageId?.match(/^(\d?[A-Z]+)\.(\d+)(?:\.(\d+))?/);
  if (!match) return null;
  return {
    book: usfmToFriendly(match[1]),
    chapter: parseInt(match[2], 10),
    ...(match[3] ? { verse: parseInt(match[3], 10) } : {}),
  };
}
