import { cachedFetch, SHORT_TTL, type CachedFetchOptions } from "./cache";

export type ParticipantUser = {
  id: string;
  name: string;
  email: string;
  image: string | null;
  // Admin/owner view — filled in by the participants endpoints.
  connectedAt?: string | null;
  appliedAt?: string | null;
  registeredAt?: string | null;
  registrationEmail?: string;
  fullName?: string;
  phone?: string;
  dob?: string;
  emergencyContact?: string;
  notes?: string;
  bringingPartner?: boolean;
  partner?: {
    fullName: string;
    phone: string;
    dob?: string;
    email?: string;
  } | null;
  // Payment tracking (admin/owner view — participants endpoints).
  feeAmount?: number;
  feeSymbol?: string;
  totalDue?: number;
  amountPaid?: number;
  pendingAmount?: number;
  remaining?: number;
  paid?: boolean;
  popUrl?: string | null;
  paidAt?: string | null;
  payments?: PaymentEntry[];
};

export type PaymentEntry = {
  _id?: string | null;
  amount: number;
  popUrl?: string | null;
  note?: string | null;
  paidAt?: string | null;
  recordedBy?: string | null;
  status?: "pending" | "approved";
};

export type Skill = {
  _id: string;
  title: string;
  category: string;
  description: string;
  author: string;
  userId: string | null;
  offering: boolean;
  connected: boolean;
  connectionCount: number;
  connectedUsers: ParticipantUser[];
  isOwner: boolean;
  createdAt: string;
};

export type EventAgendaItem = {
  time: string;
  title: string;
  description?: string;
  /** Optional window for activities that span a specific period. */
  dateFrom?: string;
  dateTo?: string;
  timeFrom?: string;
  timeTo?: string;
  /** Venue / room where this activity takes place. */
  location?: string;
  /** Activity type — e.g. Worship, Workshop, Meals, Free time. */
  category?: string;
  /** Speaker / facilitator / leader running the activity. */
  host?: string;
};

export type EventDetail = {
  label: string;
  value: string;
};

export type Event = {
  _id: string;
  title: string;
  date: string;
  time: string;
  /** Optional end of a multi-day event (e.g. a weekend retreat). */
  dateTo?: string;
  timeTo?: string;
  /** Program schedule — the event's itinerary and activities. */
  agenda?: EventAgendaItem[];
  /** Free-form notes (what to bring, packing list, etc.). */
  notes?: string;
  location: string;
  description: string;
  fee: string;
  imageUrl: string | null;
  author: string;
  userId: string | null;
  attending: number;
  hasRsvpd: boolean;
  isBookmarked: boolean;
  rsvpUsers: ParticipantUser[];
  isOwner: boolean;
  createdAt: string;
  /** Whether the signed-in user's registration for this event is paid. */
  hasPaid?: boolean;
  /** Numeric fee + currency symbol for payment math (0 = free). */
  feeAmount?: number;
  feeSymbol?: string;
  /** Amount due for the signed-in user (doubled when bringing a partner). */
  totalDue?: number;
  /** Signed-in user's running total paid toward the fee. */
  amountPaid?: number;
  /** Signed-in user's self-submitted payments awaiting owner approval. */
  pendingAmount?: number;
  /** Signed-in user's remaining balance. */
  remaining?: number;
  /** Whether the signed-in user's registration includes a partner. */
  myPartner?: boolean;
  /** Club this event belongs to (created inside a club page). */
  clubSlug?: string;
  /** Short chip label, e.g. "HIKING". */
  category?: string;
  /** Eyebrow above the title, e.g. "WEEKEND HIKE". */
  eyebrow?: string;
  /** Accent part of the serif title, e.g. "Ridge Hike". */
  titleAccent?: string;
  /** Chips, e.g. ["TRAIL", "SUNRISE", "PHOTO"]. */
  tags?: string[];
  /** Guide / leader running the event (shown as GUIDE · LEAD · HOST). */
  host?: string;
  /** Max number of seats (drives "SPOTS LEFT" on the card). */
  capacity?: number;
  /** Extra key/value rows for the details grid (DISTANCE, LEVEL, …). */
  details?: EventDetail[];
};

export type EventRegistrationDetails = {
  fullName: string;
  email: string;
  phone: string;
  dob?: string;
  emergencyContact: string;
  notes?: string;
  bringingPartner: boolean;
  partner?: {
    fullName: string;
    phone: string;
    dob?: string;
    email?: string;
  } | null;
};

export type GroupSession = {
  sessionId: string;
  roomName: string;
  roomUrl: string;
  type: "audio" | "video";
  /** Short OTP-style code members can use to join the live call. */
  accessCode: string;
  startedBy: string;
  startedByName: string;
  startedAt: string;
  /** How long the session lasts (45 minutes for group calls). */
  durationMs?: number;
  /** Present in responses from start/join so the caller can enter the call. */
  token?: string;
  isOwner?: boolean;
};

export type PrayerGroup = {
  _id: string;
  name: string;
  description: string;
  category: string;
  imageUrl: string | null;
  facilitator: string;
  location: string;
  audience: string;
  notes: string;
  contactInfo: string;
  inviteCode: string;
  meetingTime: string;
  schedule: string;
  maxMembers: number;
  members: number;
  commentCount?: number;
  live: boolean;
  activeSession: GroupSession | null;
  hasJoined: boolean;
  joinedUsers: ParticipantUser[];
  isOwner: boolean;
  /** Club this group belongs to (created inside a club page). */
  clubSlug?: string;
  channelFocus?: string;
  channelName?: string;
  channelUrl?: string;
  createdAt: string;
};

export type PrayerRequest = {
  _id: string;
  text: string;
  title: string;
  description: string;
  author: string;
  userId: string | null;
  category?: string;
  anonymous?: boolean;
  visibility?: "community" | "team";
  email?: string;
  prayedByMe: boolean;
  prayCount: number;
  /** Present in list responses; omitted from create/update responses. */
  commentCount?: number;
  prayedUsers: ParticipantUser[];
  isOwner: boolean;
  createdAt: string;
};

export type Comment = {
  _id: string;
  /** Set on prayer-request comments (requests API). */
  requestId?: string;
  /** Set on prayer-group comments (groups API). */
  groupId?: string;
  text: string;
  author: string;
  image: string | null;
  mine?: boolean;
  createdAt: string;
};

export type Job = {
  _id: string;
  title: string;
  company: string;
  location: string;
  type: string;
  description: string;
  category: string;
  salary: string;
  contactEmail: string;
  author: string;
  userId: string | null;
  applied: boolean;
  applicationCount: number;
  applicants: ParticipantUser[];
  isOwner: boolean;
  createdAt: string;
};

export type ClubRegistration = {
  _id: string;
  name?: string;
  clubSlug: string;
  answers: Record<string, string>;
  status: "pending" | "approved" | "rejected";
  createdAt: string;
};

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, [
    "/api/community",
    "/api/activity",
    "/api/bookmarks",
    // Club registrations live under /api/clubs — keep their reads fresh after
    // a POST so a just-submitted registration is visible immediately.
    "/api/clubs/",
  ]);
}

/** The fields a Discover or club event card renders (?view=card). */
export type EventCard = Pick<
  Event,
  | "_id"
  | "title"
  | "date"
  | "time"
  | "dateTo"
  | "timeTo"
  | "location"
  | "imageUrl"
  | "clubSlug"
  | "createdAt"
>;

/**
 * One row of an activity list (?view=summary). Which fields are present depends
 * on the section, so everything but the id and ownership flag is optional.
 */
export type ActivitySummary = {
  _id: string;
  isOwner: boolean;
  title?: string;
  name?: string;
  text?: string;
  description?: string;
  author?: string;
  createdAt?: string;
  date?: string;
  time?: string;
  location?: string;
  company?: string;
  meetingTime?: string;
  schedule?: string;
  attending?: number;
  members?: number;
  connectionCount?: number;
  applicationCount?: number;
  prayCount?: number;
  hasRsvpd?: boolean;
  hasJoined?: boolean;
  connected?: boolean;
  prayedByMe?: boolean;
  applied?: boolean;
  isBookmarked?: boolean;
};

export const communityApi = {
  /**
   * Card-only events (?view=card) — the fields a Discover/club card renders,
   * with no rosters, agenda or payment state. Fetch the full event by id when
   * a detail or edit modal opens.
   */
  getEventCards: (clubSlug?: string) =>
    apiFetch<{ data: EventCard[] }>(
      `/api/community/events?view=card${clubSlug ? `&club=${encodeURIComponent(clubSlug)}` : ""}`,
      { cacheTtl: 0 },
    ),
  /** One event with every field the detail, registration and edit modals read. */
  getEvent: (id: string) =>
    apiFetch<{ data: Event }>(`/api/community/events/${id}`, { cacheTtl: 0 }),

  /** Groups for one club only (?club=<slug>). */
  getClubGroups: (clubSlug: string) =>
    apiFetch<{ data: PrayerGroup[] }>(`/api/community/groups?club=${encodeURIComponent(clubSlug)}`, {
      cacheTtl: 0,
    }),

  /**
   * Activity-list rows (?view=summary) — title, meta line, a participant count
   * and the viewer's own flags. No rosters, so the server skips participant,
   * comment and registration joins. Rosters are read from the dedicated
   * participants endpoints when a detail screen opens.
   */
  getEventSummaries: () =>
    apiFetch<{ data: ActivitySummary[] }>("/api/community/events?view=summary", { cacheTtl: 0 }),
  getSkillSummaries: () =>
    apiFetch<{ data: ActivitySummary[] }>("/api/community/skills?view=summary", { cacheTtl: 0 }),
  getGroupSummaries: () =>
    apiFetch<{ data: ActivitySummary[] }>("/api/community/groups?view=summary", { cacheTtl: 0 }),
  getRequestSummaries: () =>
    apiFetch<{ data: ActivitySummary[] }>("/api/community/requests?view=summary", { cacheTtl: 0 }),
  getJobSummaries: () =>
    apiFetch<{ data: ActivitySummary[] }>("/api/community/jobs?view=summary", { cacheTtl: 0 }),

  getSkills: () => apiFetch<{ data: Skill[] }>("/api/community/skills"),
  createSkill: (skill: Partial<Skill>) =>
    apiFetch<{ data: Skill }>("/api/community/skills", { method: "POST", body: JSON.stringify(skill) }),
  updateSkill: (skill: Partial<Skill> & { _id: string }) =>
    apiFetch<{ data: Skill }>("/api/community/skills", { method: "PUT", body: JSON.stringify(skill) }),
  deleteSkill: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/skills", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  connectSkill: (id: string) =>
    apiFetch<{ data: { connected: boolean } }>(`/api/community/skills/${id}/connect`, { method: "POST" }),

  getEvents: () => apiFetch<{ data: Event[] }>("/api/community/events"),
  createEvent: (event: Partial<Event>) =>
    apiFetch<{ data: Event }>("/api/community/events", { method: "POST", body: JSON.stringify(event) }),
  updateEvent: (event: Partial<Event> & { _id: string }) =>
    apiFetch<{ data: Event }>("/api/community/events", { method: "PUT", body: JSON.stringify(event) }),
  deleteEvent: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/events", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  rsvpEvent: (id: string, details?: EventRegistrationDetails) =>
    apiFetch<{ data: Event }>(`/api/community/events/${id}/rsvp`, {
      method: "POST",
      ...(details ? { body: JSON.stringify(details) } : {}),
    }),

  getGroups: () => apiFetch<{ data: PrayerGroup[] }>("/api/community/groups"),
  createGroup: (group: Partial<PrayerGroup>) =>
    apiFetch<{ data: PrayerGroup }>("/api/community/groups", { method: "POST", body: JSON.stringify(group) }),
  updateGroup: (group: Partial<PrayerGroup> & { _id: string }) =>
    apiFetch<{ data: PrayerGroup }>("/api/community/groups", { method: "PUT", body: JSON.stringify(group) }),
  deleteGroup: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/groups", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  joinGroup: (id: string) =>
    apiFetch<{ data: PrayerGroup }>(`/api/community/groups/${id}/join`, { method: "POST" }),
  joinGroupByCode: (code: string) =>
    apiFetch<{ data: { id: string; name: string; hasJoined: boolean } }>("/api/community/groups/join-by-code", {
      method: "POST",
      body: JSON.stringify({ code }),
    }),

  startGroupSession: (id: string, type: "audio" | "video") =>
    apiFetch<{ data: GroupSession }>(`/api/community/groups/${id}/session`, {
      method: "POST",
      body: JSON.stringify({ action: "start", type }),
    }),
  joinGroupSession: (id: string, accessCode?: string) =>
    apiFetch<{ data: GroupSession }>(`/api/community/groups/${id}/session`, {
      method: "POST",
      body: JSON.stringify({ action: "join", accessCode }),
    }),
  endGroupSession: (id: string) =>
    apiFetch<{ success: boolean }>(`/api/community/groups/${id}/session`, { method: "DELETE" }),

  getRequests: () => apiFetch<{ data: PrayerRequest[] }>("/api/community/requests"),
  createRequest: (req: Partial<PrayerRequest>) =>
    apiFetch<{ data: PrayerRequest }>("/api/community/requests", { method: "POST", body: JSON.stringify(req) }),
  updateRequest: (req: Partial<PrayerRequest> & { _id: string }) =>
    apiFetch<{ data: PrayerRequest }>("/api/community/requests", { method: "PUT", body: JSON.stringify(req) }),
  deleteRequest: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/requests", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  prayForRequest: (id: string) =>
    apiFetch<{ data: PrayerRequest }>(`/api/community/requests/${id}/pray`, { method: "POST" }),
  getRequestComments: (id: string) =>
    apiFetch<{ data: Comment[] }>(`/api/community/requests/${id}/comments`, {
      cacheTtl: SHORT_TTL,
    }),
  addRequestComment: (id: string, text: string) =>
    apiFetch<{ data: Comment }>(`/api/community/requests/${id}/comments`, {
      method: "POST",
      body: JSON.stringify({ text }),
    }),
  deleteRequestComment: (id: string, commentId: string) =>
    apiFetch<{ success: boolean }>(`/api/community/requests/${id}/comments`, {
      method: "DELETE",
      body: JSON.stringify({ commentId }),
    }),
  getGroupComments: (id: string) =>
    apiFetch<{ data: Comment[] }>(`/api/community/groups/${id}/comments`, {
      cacheTtl: SHORT_TTL,
    }),
  addGroupComment: (id: string, text: string) =>
    apiFetch<{ data: Comment }>(`/api/community/groups/${id}/comments`, {
      method: "POST",
      body: JSON.stringify({ text }),
    }),
  deleteGroupComment: (id: string, commentId: string) =>
    apiFetch<{ success: boolean }>(`/api/community/groups/${id}/comments`, {
      method: "DELETE",
      body: JSON.stringify({ commentId }),
    }),

  getJobs: () => apiFetch<{ data: Job[] }>("/api/community/jobs"),
  createJob: (job: Partial<Job>) =>
    apiFetch<{ data: Job }>("/api/community/jobs", { method: "POST", body: JSON.stringify(job) }),
  updateJob: (job: Partial<Job> & { _id: string }) =>
    apiFetch<{ data: Job }>("/api/community/jobs", { method: "PUT", body: JSON.stringify(job) }),
  deleteJob: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/jobs", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  applyForJob: (id: string) =>
    apiFetch<{ data: { applied: boolean } }>(`/api/community/jobs/${id}/apply`, { method: "POST" }),

  getEventParticipants: (id: string) =>
    apiFetch<{ data: ParticipantUser[] }>(`/api/community/events/${id}/participants`, {
      cacheTtl: SHORT_TTL,
    }),

  /** Record a payment toward the event fee (self, owner, or admin). */
  recordEventPayment: (id: string, userId: string, amount: number, popUrl?: string | null) =>
    apiFetch<{ data: any }>(`/api/community/events/${id}/payments`, {
      method: "POST",
      body: JSON.stringify({
        userId,
        amount,
        popUrl: popUrl || undefined,
      }),
    }),
  /** Convenience: settle the attendee's full remaining balance in one entry. */
  settleEventPayment: (id: string, userId: string) =>
    apiFetch<{ data: any }>(`/api/community/events/${id}/payments`, {
      method: "POST",
      body: JSON.stringify({ userId, paid: true }),
    }),
  /** Owner/admin: approve (true) or reject (false) a pending payment entry. */
  approveEventPayment: (
    id: string,
    userId: string,
    paymentId: string,
    approve: boolean,
  ) =>
    apiFetch<{ data: any }>(`/api/community/events/${id}/payments`, {
      method: "PUT",
      body: JSON.stringify({ userId, paymentId, approve }),
    }),

  getSkillParticipants: (id: string) =>
    apiFetch<{ data: ParticipantUser[] }>(`/api/community/skills/${id}/participants`, {
      cacheTtl: SHORT_TTL,
    }),
  getGroupParticipants: (id: string) =>
    apiFetch<{ data: ParticipantUser[] }>(`/api/community/groups/${id}/participants`, {
      cacheTtl: SHORT_TTL,
    }),
  getJobParticipants: (id: string) =>
    apiFetch<{ data: ParticipantUser[] }>(`/api/community/jobs/${id}/participants`, {
      cacheTtl: SHORT_TTL,
    }),

  getActivity: (limit?: number) =>
    apiFetch<{ data: ActivityItem[] }>(`/api/activity${limit ? `?limit=${limit}` : ""}`),

  toggleBookmark: (section: string, itemId: string) =>
    apiFetch<{ data: { bookmarked: boolean } }>("/api/bookmarks", {
      method: "POST",
      body: JSON.stringify({ section, itemId }),
    }),

  getBookmarks: () =>
    apiFetch<{ data: any[] }>("/api/bookmarks"),

  /** Submit the unique per-club registration form (before joining WhatsApp). */
  registerForClub: (clubSlug: string, answers: Record<string, string>) =>
    apiFetch<{ data: ClubRegistration }>(`/api/clubs/${encodeURIComponent(clubSlug)}/register`, {
      method: "POST",
      body: JSON.stringify({ answers }),
    }),

  /** The signed-in user's own registration for a club (null when none). */
  getMyClubRegistration: (clubSlug: string) =>
    apiFetch<{ data: ClubRegistration | null }>(
      `/api/clubs/${encodeURIComponent(clubSlug)}/register`,
      { cacheTtl: 0 },
    ),

  /** Admin roster of everyone registered for a club. */
  listClubRegistrations: (clubSlug: string) =>
    apiFetch<{ data: ClubRegistration[] }>(
      `/api/clubs/${encodeURIComponent(clubSlug)}/participants`,
      { cacheTtl: 0 },
    ),

  getDevotionals: () =>
    apiFetch<{ data: Devotional[] }>("/api/community/devotionals"),
  createDevotional: (data: { title: string; content: string; scripture?: string; theme?: string }) =>
    apiFetch<{ data: Devotional }>("/api/community/devotionals", { method: "POST", body: JSON.stringify(data) }),
  deleteDevotional: (id: string) =>
    apiFetch<{ success: boolean }>("/api/community/devotionals", { method: "DELETE", body: JSON.stringify({ _id: id }) }),
  likeDevotional: (id: string) =>
    apiFetch<{ data: { liked: boolean } }>(`/api/community/devotionals/${id}/like`, { method: "POST" }),
};

export type Devotional = {
  _id: string;
  title: string;
  author: string;
  authorId: string;
  content: string;
  scripture: string;
  theme: string;
  likeCount: number;
  likedByMe: boolean;
  isOwner: boolean;
  createdAt: string;
};

export type ActivityItem = {
  _id: string;
  type: "rsvp" | "pray" | "connect" | "join" | "apply";
  section: string;
  itemId: string;
  itemTitle: string;
  actorName: string;
  actorEmail: string;
  createdAt: string;
};

export const ACTIVITY_LABELS: Record<string, string> = {
  rsvp: "RSVP'd to",
  pray: "Prayed for",
  connect: "Connected to",
  join: "Joined",
  apply: "Applied to",
};
