import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import * as ImagePicker from "expo-image-picker";
import { useLocalSearchParams, useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";
import { useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { Image } from "expo-image";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useSportsCatalog } from "@/services/sports-catalog";
import { getSession, type Session } from "@/services/auth";
import { clubJoinApi } from "@/services/club-join";
import { getClub } from "@/constants/clubs";
import {
  fetchPositionCounts,
  registerPlayer,
  type PlayerPhoto,
  type PositionCounts,
  type SportsRegistrationResult,
} from "@/services/sports";
import { clearPersistentFormDraft, usePersistentFormState } from "@/hooks/usePersistentFormState";
import { GradientBox } from "@/constants/gradients";

const RELIGIONS = [
  "Christian",
  "Apostolic",
  "Pentecostal",
  "Catholic",
  "Baptist",
  "Methodist",
  "Evangelical",
  "Other",
];

const GENDERS = [
  { value: "", label: "Prefer not to say" },
  { value: "male", label: "Male" },
  { value: "female", label: "Female" },
];

const MAX_PHOTO_BYTES = 4 * 1024 * 1024;
const PHOTO_TYPES = ["image/jpeg", "image/pjpeg", "image/png", "image/webp", "image/avif"];

type Done = SportsRegistrationResult;

export default function PlayerRegisterScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ teamId?: string; position?: string }>();
  const insets = useSafeAreaInsets();

  const { data: catalog, loading, error: catalogError } = useSportsCatalog();
  const team =
    typeof params.teamId === "string" && catalog
      ? catalog.getTeam(params.teamId)
      : undefined;
  const positions = useMemo(
    () => (team && catalog ? catalog.positionsForSport(team.sport) : []),
    [team, catalog],
  );

  const [sessionState, setSessionState] = useState<"loading" | "in" | "out">(
    "loading",
  );
  const [counts, setCounts] = useState<PositionCounts>({});
  const [membershipState, setMembershipState] = useState<
    "loading" | "member" | "none" | "error"
  >("loading");
  const [membershipAttempt, setMembershipAttempt] = useState(0);
  const draftKey = `form-draft:sports-register:${typeof params.teamId === "string" ? params.teamId : "unknown"}`;
  const [name, setName] = usePersistentFormState(`${draftKey}:name`, "");
  const [age, setAge] = usePersistentFormState(`${draftKey}:age`, "");
  const [gender, setGender] = usePersistentFormState(`${draftKey}:gender`, "");
  const [phone, setPhone] = usePersistentFormState(`${draftKey}:phone`, "");
  const [heightCm, setHeightCm] = usePersistentFormState(`${draftKey}:heightCm`, "");
  const [religion, setReligion] = usePersistentFormState(`${draftKey}:religion`, "");
  const [position, setPosition] = usePersistentFormState(`${draftKey}:position`, "");
  const [foot, setFoot] = usePersistentFormState<"" | "left" | "right">(`${draftKey}:foot`, "");
  const [hand, setHand] = usePersistentFormState<"" | "left" | "right">(`${draftKey}:hand`, "");
  const [photo, setPhoto] = useState<PlayerPhoto | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [done, setDone] = useState<Done | null>(null);

  // A ?position= deep link only applies once the catalogue's slots (which
  // arrive asynchronously) confirm that position exists — derived here so no
  // setState-in-effect is needed.
  const activePosition = useMemo(() => {
    if (position) return position;
    const wanted = params.position;
    return wanted && positions.some((p) => p.name === wanted) ? wanted : "";
  }, [position, params.position, positions]);

  // Sign-in gate (web wraps the form in RequireAuth) + live places per slot.
  useEffect(() => {
    let cancelled = false;
    getSession()
      .then((s: Session | null) => {
        if (cancelled) return;
        setSessionState(s ? "in" : "out");
        if (!name && s?.user?.name) setName(s.user.name);
      })
      .catch(() => {
        if (!cancelled) setSessionState("out");
      });
    if (team) {
      fetchPositionCounts(team.id)
        .then((c) => {
          if (!cancelled) setCounts(c);
        })
        .catch(() => {});
    }
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [team?.id]);

  // Team seats are member-only: a signed-in visitor without a club membership
  // is sent to join a club first, and the membership doubles as the prefill.
  useEffect(() => {
    if (sessionState !== "in") return;
    let cancelled = false;
    clubJoinApi
      .me()
      .then((json) => {
        const m = json?.data;
        if (cancelled) return;
        // Mirrors the API's rule: no reference or a graduated membership means
        // no team seat.
        const active = Boolean(m?.reference) && m?.status !== "graduated";
        setMembershipState(active ? "member" : "none");
        if (!active || !m) return;
        setName((v) => v || m.name || "");
        setAge((v) => v || (m.age != null ? String(m.age) : ""));
        setGender((v) =>
          v || (m.gender === "male" || m.gender === "female" ? m.gender : ""),
        );
        setPhone((v) => v || m.phone || "");
      })
      .catch(() => {
        if (!cancelled) setMembershipState("error");
      });
    return () => {
      cancelled = true;
    };
  }, [sessionState, membershipAttempt, setName, setAge, setGender, setPhone]);

  const placeLabel = (positionName: string): string => {
    const taken = counts[positionName]?.taken ?? 0;
    const capacity = counts[positionName]?.capacity ?? catalog?.maxPerPosition ?? 0;
    const left = Math.max(0, capacity - taken);
    if (left === 0) return "Full — joins the waiting list";
    return `${left} of ${capacity} places left`;
  };

  const pickPhoto = async () => {
    setError(null);
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      quality: 0.7,
    });
    if (result.canceled || !result.assets?.length) return;
    const asset = result.assets[0];
    const type = asset.mimeType || "image/jpeg";
    if (asset.mimeType && !PHOTO_TYPES.includes(asset.mimeType)) {
      setError("Use a JPEG, PNG or WebP photo.");
      return;
    }
    if (typeof asset.fileSize === "number" && asset.fileSize > MAX_PHOTO_BYTES) {
      setError("That photo is over 4 MB — pick a smaller one.");
      return;
    }
    setPhoto({
      uri: asset.uri,
      name: asset.fileName || `player-${Date.now()}.jpg`,
      type,
    });
  };

  const submit = async () => {
    if (!team) return;
    setError(null);

    const ageNum = Number.parseInt(age, 10);
    const heightNum = Number.parseInt(heightCm, 10);
    if (name.trim().length < 2) return setError("Enter the player's full name.");
    if (!Number.isFinite(ageNum) || ageNum < 4 || ageNum > 99)
      return setError("Enter a valid age.");
    if (!photo) return setError("Add a profile photo.");
    if (!Number.isFinite(heightNum) || heightNum < 80 || heightNum > 230)
      return setError("Enter a height between 80 cm and 230 cm.");
    if (!religion.trim()) return setError("Enter the player's religion.");
    if (!activePosition) return setError("Choose the position you play.");
    if (!foot) return setError("Choose the stronger foot (right or left).");
    if (!hand) return setError("Choose the stronger hand (right or left).");
    if (phone.trim() && phone.replace(/\D/g, "").length < 9)
      return setError("Enter a valid phone number, or leave it empty.");

    setSending(true);
    try {
      const result = await registerPlayer({
        clubSlug: team.clubSlug,
        clubName: getClub(team.clubSlug)?.name,
        teamId: team.id,
        teamName: team.name,
        name: name.trim(),
        age: ageNum,
        gender: gender || undefined,
        phone: phone.trim() || undefined,
        heightCm: heightNum,
        religion: religion.trim(),
        position: activePosition,
        foot: foot as "left" | "right",
        hand: hand as "left" | "right",
        photo,
      });
      await clearPersistentFormDraft(draftKey);
      setDone(result);
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setSending(false);
    }
  };

  if (loading) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={r.missing}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (catalogError || !catalog) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={r.missing}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={r.missingTitle}>Registration unavailable</Text>
            <Text style={r.missingText}>{catalogError ?? ""}</Text>
            <TouchableOpacity
              style={r.missingBtn}
              onPress={() => router.replace("/sports")}
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.missingBtnText}>All teams</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (!team) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={r.missing}>
            <Ionicons name="alert-circle-outline" size={40} color={colors.muted} />
            <Text style={r.missingTitle}>Team not found</Text>
            <TouchableOpacity
              style={r.missingBtn}
              onPress={() => router.replace("/sports")}
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.missingBtnText}>All teams</Text>
            </TouchableOpacity>
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  const accent = "#13c5dd";
  const teamNext = `/sports/${team.id}/register`;
  const squadSize =
    catalog.squadSize[team.sport] ?? catalog.slotsForSport(team.sport).length;

  if (sessionState === "out") {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <ScrollView
            contentContainerStyle={[r.gateWrap, { paddingBottom: 40 + insets.bottom }]}
          >
            <View style={r.gateIcon}>
              <Ionicons name="lock-closed-outline" size={30} color={accent} />
            </View>
            <Text style={r.gateTitle}>Register for {team.name}</Text>
            <Text style={r.gateBlurb}>
              Sign in to claim a position on the squad — we keep your
              registration with your account.
            </Text>
            <TouchableOpacity
              style={r.gateBtn}
              activeOpacity={0.88}
              onPress={() =>
                router.push({ pathname: "/login", params: { next: teamNext } })
              }
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.gateBtnText}>Sign in</Text>
              <Ionicons name="arrow-forward" size={16} color={colors.white} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => router.back()}
              accessibilityRole="button"
            >
              <Text style={r.gateBack}>Back to {team.name}</Text>
            </TouchableOpacity>
          </ScrollView>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (membershipState === "loading") {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <View style={r.missing}>
            <ActivityIndicator size="large" color={colors.goldDark} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (membershipState === "error") {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <ScrollView
            contentContainerStyle={[r.gateWrap, { paddingBottom: 40 + insets.bottom }]}
          >
            <View style={r.gateIcon}>
              <Ionicons name="cloud-offline-outline" size={30} color={accent} />
            </View>
            <Text style={r.gateTitle}>We couldn’t check your membership</Text>
            <Text style={r.gateBlurb}>
              Check your connection and try again — team registration needs a
              club membership on your account.
            </Text>
            <TouchableOpacity
              style={r.gateBtn}
              activeOpacity={0.88}
              onPress={() => setMembershipAttempt((n) => n + 1)}
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.gateBtnText}>Try again</Text>
              <Ionicons name="refresh" size={16} color={colors.white} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => router.replace(`/sports/${team.id}`)}
              accessibilityRole="button"
            >
              <Text style={r.gateBack}>Back to {team.name}</Text>
            </TouchableOpacity>
          </ScrollView>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (membershipState === "none") {
    const club = getClub(team.clubSlug);
    const clubName = club?.name ?? "a Relate club";
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <ScrollView
            contentContainerStyle={[r.gateWrap, { paddingBottom: 40 + insets.bottom }]}
          >
            <View style={[r.gateIcon, { backgroundColor: "#fbbf241f" }]}>
              <Ionicons name="id-card-outline" size={30} color="#b45309" />
            </View>
            <Text style={r.gateTitle}>Join a club first</Text>
            <Text style={r.gateBlurb}>
              Team registration is for Relate club members. Joining {clubName}{" "}
              gives you a Membership ID and your age-based club home — then come
              back and claim your place on {team.name}.
            </Text>
            <View style={r.doneInfo}>
              <Text style={r.doneInfoText}>
                1 · Join {clubName} — a few minutes gives you your Membership ID.
              </Text>
              <Text style={[r.doneInfoText, { marginTop: 8 }]}>
                2 · Register for {team.name} — pick a position and add your photo.
              </Text>
            </View>
            <TouchableOpacity
              style={r.gateBtn}
              activeOpacity={0.88}
              onPress={() =>
                router.push({ pathname: "/join", params: { slug: team.clubSlug } })
              }
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.gateBtnText}>Join {clubName}</Text>
              <Ionicons name="arrow-forward" size={16} color={colors.white} />
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => router.replace(`/sports/${team.id}`)}
              accessibilityRole="button"
            >
              <Text style={r.gateBack}>Back to {team.name}</Text>
            </TouchableOpacity>
          </ScrollView>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  if (done) {
    const onSheet = done.status === "active";
    return (
      <SafeAreaProvider>
        <SafeAreaView style={r.safe} edges={["top"]}>
          <StatusBar style="dark" />
          <ScrollView
            contentContainerStyle={[r.doneWrap, { paddingBottom: 40 + insets.bottom }]}
          >
            <View style={[r.doneIcon, { backgroundColor: `${accent}1f` }]}>
              <Ionicons name="checkmark" size={34} color="#0e7490" />
            </View>
            <Text style={r.doneEyebrow}>RELATE · {team.name.toUpperCase()}</Text>
            <Text style={r.doneTitle}>
              {onSheet ? "You’re on the team sheet" : "You’re in the queue"}
            </Text>
            <Text style={r.doneText}>
              {onSheet ? (
                <>
                  Registered as{" "}
                  <Text style={r.doneStrong}>
                    {done.position} ({done.positionCode})
                  </Text>{" "}
                  for {team.name} — #{done.order} in that position.
                </>
              ) : (
                <>
                  <Text style={r.doneStrong}>{done.position}</Text> is full, so
                  you&rsquo;re #{done.order} on the waiting list for{" "}
                  {team.name}. We&rsquo;ll move you onto the sheet as soon as a
                  place opens.
                </>
              )}
            </Text>
            <View style={r.doneInfo}>
              <Text style={r.doneInfoText}>
                Your photo and details are saved. Coaches see the first
                registrants per position as the starting side — check the squad
                page to see where you land.
              </Text>
            </View>
            <TouchableOpacity
              style={r.donePrimary}
              activeOpacity={0.88}
              onPress={() => router.replace(`/sports/${team.id}`)}
              accessibilityRole="button"
            >
              <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
              <Text style={r.donePrimaryText}>View the squad</Text>
              <Ionicons name="arrow-forward" size={16} color={colors.white} />
            </TouchableOpacity>
            <TouchableOpacity
              style={r.doneSecondary}
              activeOpacity={0.85}
              onPress={() => router.replace("/sports")}
              accessibilityRole="button"
            >
              <Text style={r.doneSecondaryText}>All teams</Text>
            </TouchableOpacity>
          </ScrollView>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={r.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
        >
          <ScrollView
            contentContainerStyle={{ paddingBottom: 40 + insets.bottom }}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            <LinearGradient
              colors={["#1d2a4d", "#0f1a33"]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={r.head}
            >
              <TouchableOpacity
                style={r.back}
                onPress={() => router.back()}
                activeOpacity={0.85}
                accessibilityLabel="Back to team"
              >
                <Ionicons name="chevron-back" size={19} color={colors.white} />
              </TouchableOpacity>
              <Text style={r.headEyebrow}>
                RELATE · {team.sport.toUpperCase()} REGISTRATION
              </Text>
              <Text style={r.headTitle}>Register for {team.name}</Text>
              <Text style={r.headSub}>
                Pick your position, add a photo and the essentials — the first{" "}
                {squadSize} players per position make the team sheet, and every
                position holds up to {catalog.maxPerPosition} players (starter
                plus cover).
              </Text>
            </LinearGradient>

            {/* 1 · Profile photo */}
            <View style={r.body}>
              <View style={r.card}>
                <Text style={r.cardBadge}>1 · PROFILE PHOTO</Text>
                <View style={r.photoRow}>
                  <TouchableOpacity
                    style={r.photoBtn}
                    activeOpacity={0.85}
                    onPress={pickPhoto}
                    accessibilityRole="button"
                    accessibilityLabel="Choose a profile photo"
                  >
                    {photo ? (
                      <Image source={{ uri: photo.uri }} style={r.photoImg} />
                    ) : (
                      <View style={r.photoEmpty}>
                        <Ionicons name="camera-outline" size={22} color={colors.muted} />
                        <Text style={r.photoEmptyText}>ADD PHOTO</Text>
                      </View>
                    )}
                  </TouchableOpacity>
                  <View style={r.photoBody}>
                    <Text style={r.label}>Profile photo</Text>
                    <Text style={r.help}>
                      A clear head-and-shoulders shot. JPEG, PNG or WebP, up to
                      4 MB — it is stored in Supabase and shown on your squad
                      page.
                    </Text>
                    <TouchableOpacity
                      onPress={pickPhoto}
                      activeOpacity={0.7}
                      accessibilityRole="button"
                    >
                      <Text style={r.photoLink}>
                        {photo ? "Choose a different photo" : "Choose a photo"}
                      </Text>
                    </TouchableOpacity>
                  </View>
                </View>
              </View>

              {/* 2 · Player details */}
              <View style={r.card}>
                <Text style={r.cardBadge}>2 · PLAYER DETAILS</Text>

                <View style={r.field}>
                  <Text style={r.label}>Full name</Text>
                  <TextInput
                    style={r.input}
                    value={name}
                    onChangeText={setName}
                    placeholder="e.g. Thabo Mokoena"
                    placeholderTextColor={colors.muted}
                    autoCapitalize="words"
                  />
                </View>

                <View style={r.fieldRow}>
                  <View style={[r.field, r.fieldHalf]}>
                    <Text style={r.label}>Age</Text>
                    <TextInput
                      style={r.input}
                      value={age}
                      onChangeText={setAge}
                      placeholder="e.g. 14"
                      placeholderTextColor={colors.muted}
                      keyboardType="number-pad"
                    />
                  </View>
                  <View style={[r.field, r.fieldHalf]}>
                    <Text style={r.label}>Height (cm)</Text>
                    <TextInput
                      style={r.input}
                      value={heightCm}
                      onChangeText={setHeightCm}
                      placeholder="e.g. 162"
                      placeholderTextColor={colors.muted}
                      keyboardType="number-pad"
                    />
                  </View>
                </View>

                <View style={r.field}>
                  <Text style={r.label}>Gender</Text>
                  <View style={r.segment}>
                    {GENDERS.map((g) => {
                      const active = gender === g.value;
                      return (
                        <TouchableOpacity
                          key={g.label}
                          style={[r.segmentItem, active && r.segmentItemActive]}
                          onPress={() => setGender(g.value)}
                          activeOpacity={0.8}
                          accessibilityRole="button"
                          accessibilityState={{ selected: active }}
                        >
                          <Text
                            style={[
                              r.segmentText,
                              active && r.segmentTextActive,
                            ]}
                          >
                            {g.label}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                </View>

                <View style={r.field}>
                  <Text style={r.label}>Religion</Text>
                  <TextInput
                    style={r.input}
                    value={religion}
                    onChangeText={setReligion}
                    placeholder="e.g. Christian"
                    placeholderTextColor={colors.muted}
                    autoCapitalize="words"
                  />
                  <View style={r.chips}>
                    {RELIGIONS.map((rel) => {
                      const active = religion === rel;
                      return (
                        <TouchableOpacity
                          key={rel}
                          style={[r.chip, active && r.chipActive]}
                          onPress={() => setReligion(rel)}
                          activeOpacity={0.8}
                          accessibilityRole="button"
                          accessibilityState={{ selected: active }}
                        >
                          <Text style={[r.chipText, active && r.chipTextActive]}>
                            {rel}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                </View>

                <View style={r.field}>
                  <Text style={r.label}>Phone (optional)</Text>
                  <TextInput
                    style={r.input}
                    value={phone}
                    onChangeText={setPhone}
                    placeholder="e.g. +27 82 000 0000"
                    placeholderTextColor={colors.muted}
                    keyboardType="phone-pad"
                  />
                </View>
              </View>

              {/* 3 · Position */}
              <View style={r.card}>
                <Text style={r.cardBadge}>3 · POSITION</Text>

                <View style={r.field}>
                  <Text style={r.label}>Position you play</Text>
                  <View style={r.chips}>
                    {positions.map((p) => {
                      const active = activePosition === p.name;
                      return (
                        <TouchableOpacity
                          key={p.name}
                          style={[r.chip, active && r.chipActive]}
                          onPress={() => setPosition(p.name)}
                          activeOpacity={0.8}
                          accessibilityRole="button"
                          accessibilityState={{ selected: active }}
                        >
                          <Text style={[r.chipText, active && r.chipTextActive]}>
                            {p.name} ({p.code})
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>
                  {activePosition ? (
                    <Text style={r.hint}>
                      {placeLabel(activePosition)}. First come, first picked — the
                      earliest {squadSize} per squad are shown as the team.
                    </Text>
                  ) : null}
                </View>

                <View style={r.fieldRow}>
                  <View style={[r.field, r.fieldHalf]}>
                    <Text style={r.label}>Stronger foot</Text>
                    <View style={r.choiceRow}>
                      {(["right", "left"] as const).map((side) => {
                        const active = foot === side;
                        return (
                          <TouchableOpacity
                            key={side}
                            style={[r.choice, active && r.choiceActive]}
                            onPress={() => setFoot(side)}
                            activeOpacity={0.8}
                            accessibilityRole="button"
                            accessibilityState={{ selected: active }}
                          >
                            <Text
                              style={[r.choiceText, active && r.choiceTextActive]}
                            >
                              {side === "right" ? "Right" : "Left"}
                            </Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                    <Text style={r.choiceNote}>
                      {foot === "right"
                        ? "Right-footed"
                        : foot === "left"
                          ? "Left-footed"
                          : "Not chosen yet"}
                    </Text>
                  </View>
                  <View style={[r.field, r.fieldHalf]}>
                    <Text style={r.label}>Stronger hand</Text>
                    <View style={r.choiceRow}>
                      {(["right", "left"] as const).map((side) => {
                        const active = hand === side;
                        return (
                          <TouchableOpacity
                            key={side}
                            style={[r.choice, active && r.choiceActive]}
                            onPress={() => setHand(side)}
                            activeOpacity={0.8}
                            accessibilityRole="button"
                            accessibilityState={{ selected: active }}
                          >
                            <Text
                              style={[r.choiceText, active && r.choiceTextActive]}
                            >
                              {side === "right" ? "Right" : "Left"}
                            </Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                    <Text style={r.choiceNote}>
                      {hand === "right"
                        ? "Right-handed"
                        : hand === "left"
                          ? "Left-handed"
                          : "Not chosen yet"}
                    </Text>
                  </View>
                </View>
              </View>

              {error ? (
                <View style={r.errorRow} accessibilityRole="alert">
                  <Ionicons name="alert-circle" size={15} color={colors.error} />
                  <Text style={r.errorText}>{error}</Text>
                </View>
              ) : null}

              <TouchableOpacity
                style={r.submitBtn}
                activeOpacity={0.88}
                onPress={submit}
                disabled={sending}
                accessibilityRole="button"
              >
                <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                {sending ? (
                  <ActivityIndicator size="small" color={colors.white} />
                ) : (
                  <>
                    <Text style={r.submitText}>Register for {team.name}</Text>
                    <Ionicons name="arrow-forward" size={16} color={colors.white} />
                  </>
                )}
              </TouchableOpacity>
            </View>
          </ScrollView>
        </KeyboardAvoidingView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

