import { cachedFetch, type CachedFetchOptions } from "./cache";
import { fetchMobileBadges } from "./mobile-badges";

export type AppNotification = {
  _id: string;
  userId: string;
  type: string;
  title: string;
  body: string;
  data?: {
    requestId?: string;
    section?: string;
    tab?: string;
    filter?: string;
    itemId?: string;
    reportId?: string;
    appraisalId?: string;
    trainingId?: string;
    period?: string;
    route?: string;
    action?: string;
    submissionId?: string;
    status?: string;
  };
  read: boolean;
  createdAt: string;
};

async function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/notifications", "/api/mobile/badges"]);
}

export const notifApi = {
  /** Current user's unread notifications, newest first (read history is not fetched). */
  list: () =>
    apiFetch<{ data: AppNotification[]; unread: number }>("/api/notifications", {
      cacheTtl: 0,
    }),

  /** One page of the full inbox (newest first), for the All section. */
  listAll: (options: { before?: string; limit?: number } = {}) => {
    const params = new URLSearchParams({
      scope: "all",
      limit: String(options.limit ?? 20),
    });
    if (options.before) params.set("before", options.before);
    return apiFetch<{ data: AppNotification[]; hasMore: boolean }>(
      `/api/notifications?${params.toString()}`,
      { cacheTtl: 0 },
    );
  },

  /** Lightweight unread count for the bell badge (avoids fetching the full list). */
  unreadCount: async () => {
    const res = await fetchMobileBadges();
    return { unread: res.data.unread };
  },

  /** Mark every notification of the current user as read. */
  markAllRead: () =>
    apiFetch<{ success: boolean }>("/api/notifications", { method: "POST" }),

  /** Mark ONE notification as read — returns the remaining unread count. */
  markRead: (id: string) =>
    apiFetch<{ success: boolean; unread: number }>(
      `/api/notifications/${id}`,
      { method: "POST", cacheTtl: 0 },
    ),
};
