import { Ionicons } from "@expo/vector-icons";
import { FlatList, Modal, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import type { DailyParticipant, DailyParticipantsObject } from "@daily-co/react-native-daily-js";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

function initials(name: string) {
  return (name || "?")
    .split(" ")
    .map((w) => w[0])
    .filter(Boolean)
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

function NetworkDot({ state }: { state?: "good" | "warning" | "bad" | "unknown" }) {
  const color =
    state === "good"
      ? colors.success
      : state === "warning"
        ? colors.warning
        : state === "bad"
          ? colors.error
          : "rgba(255,255,255,0.25)";
  return <View style={[s.netDot, { backgroundColor: color }]} />;
}

export default function CallPeopleSheet({
  visible,
  onClose,
  participants,
  speaking,
  amOwner,
  onMuteAudio,
  onEject,
}: {
  visible: boolean;
  onClose: () => void;
  participants: DailyParticipantsObject | null;
  speaking: Set<string>;
  amOwner: boolean;
  onMuteAudio: (sessionId: string) => void;
  onEject: (sessionId: string) => void;
}) {
  const insets = useSafeAreaInsets();

  const list: DailyParticipant[] = participants
    ? Object.values(participants).sort((a, b) =>
        a.local ? -1 : b.local ? 1 : (a.user_name || "").localeCompare(b.user_name || ""),
      )
    : [];

  const micOn = (p: DailyParticipant) => p?.tracks?.audio?.state === "playable";

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <View style={s.overlay}>
        <TouchableOpacity style={s.backdrop} activeOpacity={1} onPress={onClose} />
        <View style={[s.sheet, { paddingBottom: insets.bottom + 12 }]}>
          <View style={s.grabber} />
          <View style={s.header}>
            <View style={s.headerTitleWrap}>
              <Text style={s.title}>Participants</Text>
              <View style={s.countPill}>
                <Text style={s.countText}>{list.length}</Text>
              </View>
            </View>
            <TouchableOpacity style={s.closeBtn} onPress={onClose} hitSlop={8}>
              <Ionicons name="close" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>

          <FlatList
            data={list}
            keyExtractor={(p) => p.session_id}
            style={s.list}
            showsVerticalScrollIndicator={false}
            renderItem={({ item }) => {
              const audio = micOn(item);
              const isSpeaking = speaking.has(item.session_id) && audio;
              return (
                <View style={s.row}>
                  <View
                    style={[
                      s.avatar,
                      isSpeaking && s.avatarSpeaking,
                    ]}
                  >
                    <Text style={s.avatarText}>
                      {initials(item.user_name || (item.local ? "You" : "Guest"))}
                    </Text>
                  </View>

                  <View style={s.rowInfo}>
                    <View style={s.nameRow}>
                      <Text style={s.name} numberOfLines={1}>
                        {item.local ? "You" : item.user_name || "Guest"}
                      </Text>
                      {item.owner && (
                        <View style={s.modPill}>
                          <Ionicons name="shield-checkmark" size={10} color={colors.goldLight} />
                          <Text style={s.modText}>Moderator</Text>
                        </View>
                      )}
                    </View>
                    <View style={s.stateRow}>
                      {isSpeaking ? (
                        <Text style={s.speakingText}>Speaking</Text>
                      ) : !audio ? (
                        <Text style={s.stateOff}>Muted</Text>
                      ) : null}
                      <NetworkDot state={item.networkQualityState} />
                    </View>
                  </View>

                  <View style={s.trackIcons}>
                    <Ionicons
                      name={audio ? "mic" : "mic-off"}
                      size={15}
                      color={audio ? "rgba(255,255,255,0.7)" : colors.error}
                    />
                  </View>

                  {amOwner && !item.local && (
                    <View style={s.actions}>
                      {audio && (
                        <TouchableOpacity
                          style={s.actBtn}
                          onPress={() => onMuteAudio(item.session_id)}
                          activeOpacity={0.7}
                        >
                          <Ionicons name="mic-off-outline" size={15} color={colors.white} />
                        </TouchableOpacity>
                      )}
                      <TouchableOpacity
                        style={[s.actBtn, s.actBtnDanger]}
                        onPress={() => onEject(item.session_id)}
                        activeOpacity={0.7}
                      >
                        <Ionicons name="remove-circle-outline" size={15} color={colors.white} />
                      </TouchableOpacity>
                    </View>
                  )}
                </View>
              );
            }}
          />
        </View>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  overlay: { flex: 1, justifyContent: "flex-end" },
  backdrop: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "rgba(4,9,20,0.55)",
  },
  sheet: {
    backgroundColor: colors.forest,
    borderTopLeftRadius: 22,
    borderTopRightRadius: 22,
    paddingHorizontal: 18,
    paddingTop: 10,
    maxHeight: "78%",
  },
  grabber: {
    alignSelf: "center",
    width: 36,
    height: 4,
    borderRadius: 2,
    backgroundColor: "rgba(255,255,255,0.25)",
    marginBottom: 10,
  },
  header: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    marginBottom: 6,
  },
  headerTitleWrap: { flexDirection: "row", alignItems: "center", gap: 8 },
  title: { color: colors.white, fontFamily: fonts.sansBold, fontWeight: "700", fontSize: 20 },
  countPill: {
    backgroundColor: "rgba(19,197,221,0.2)",
    borderRadius: 999,
    paddingHorizontal: 9,
    paddingVertical: 2,
  },
  countText: { color: colors.goldLight, fontFamily: fonts.sansBold, fontWeight: "700", fontSize: 11.5 },
  closeBtn: {
    width: 30,
    height: 30,
    borderRadius: 15,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(255,255,255,0.12)",
  },
  list: { marginTop: 4 },
  row: {
    flexDirection: "row",
    alignItems: "center",
    paddingVertical: 9,
    gap: 10,
    borderBottomWidth: 1,
    borderBottomColor: "rgba(255,255,255,0.08)",
  },
  avatar: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: colors.forestSoft,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 2,
    borderColor: "transparent",
  },
  avatarSpeaking: {
    borderColor: colors.success,
  },
  avatarText: { color: colors.white, fontFamily: fonts.sansBold, fontWeight: "700", fontSize: 13 },
  rowInfo: { flex: 1, minWidth: 0 },
  nameRow: { flexDirection: "row", alignItems: "center", gap: 6 },
  name: { color: colors.white, fontFamily: fonts.sansSemiBold, fontWeight: "600", fontSize: 14, flexShrink: 1 },
  modPill: {
    flexDirection: "row",
    alignItems: "center",
    gap: 3,
    backgroundColor: "rgba(19,197,221,0.16)",
    borderRadius: 999,
    paddingHorizontal: 7,
    paddingVertical: 2,
  },
  modText: { color: colors.goldLight, fontFamily: fonts.sans, fontWeight: "400", fontSize: 9.5 },
  stateRow: { flexDirection: "row", alignItems: "center", gap: 6, marginTop: 2 },
  speakingText: { color: colors.success, fontFamily: fonts.sans, fontWeight: "400", fontSize: 11 },
  stateOff: { color: "rgba(255,255,255,0.4)", fontFamily: fonts.sans, fontWeight: "400", fontSize: 11 },
  netDot: { width: 7, height: 7, borderRadius: 3.5 },
  trackIcons: { flexDirection: "row", alignItems: "center", gap: 8 },
  actions: { flexDirection: "row", alignItems: "center", gap: 6 },
  actBtn: {
    width: 28,
    height: 28,
    borderRadius: 14,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(255,255,255,0.12)",
  },
  actBtnDanger: { backgroundColor: "rgba(239,68,68,0.55)" },
});
