import { useCallback, useEffect, useState } from "react";
import { File } from "expo-file-system";
import { getRequestHeaders } from "./auth";
import { API_BASE } from "./config";
import type { RelateSport } from "@/services/sports-catalog";

/** Live places per position for one squad: `{ taken, capacity }`. */
export type PositionCounts = Record<string, { taken: number; capacity: number }>;

/** A row of GET /api/sports/registrations (public fields only). */
export type RegisteredPlayer = {
  id: string;
  teamId: string;
  clubSlug: string;
  sport: RelateSport;
  position: string;
  positionCode: string;
  name: string;
  photoUrl: string;
  heightCm: number;
  foot: "left" | "right";
  hand: "left" | "right";
  status: "active" | "waitlist";
  /** 1-based position in the queue for that position. */
  order: number;
  createdAt: string;
};

export type RosterPayload = {
  registrations: RegisteredPlayer[];
  counts: PositionCounts;
};

export type SportsRegistrationResult = {
  id: string;
  position: string;
  positionCode: string;
  status: "active" | "waitlist";
  order: number;
  photoUrl: string;
  teamId: string;
};

export type PlayerPhoto = {
  uri: string;
  name: string;
  type: string;
};

/** The signed-in member's own team row — what the join-a-team gate reads. */
export type MyRegistration = {
  id: string;
  teamId: string;
  teamName: string;
  clubSlug: string;
  clubName: string;
  sport: RelateSport;
  position: string;
  positionCode: string;
  name: string;
  photoUrl: string;
  status: "active" | "waitlist";
  /** 1-based place in the queue for that position. */
  order: number;
  createdAt: string;
};

export type PlayerRegistrationInput = {
  clubSlug: string;
  /** Display names for the squad message — sent when known. */
  clubName?: string;
  teamName?: string;
  teamId: string;
  name: string;
  age: number;
  gender?: string;
  phone?: string;
  heightCm: number;
  religion: string;
  position: string;
  foot: "left" | "right";
  hand: "left" | "right";
  photo: PlayerPhoto;
};

async function authHeaders(): Promise<Record<string, string>> {
  return getRequestHeaders();
}

/**
 * A team's registrations plus per-position counts. Any failure falls back to
 * an empty roster — the "nobody has registered yet" state the team page renders.
 */
export async function fetchRoster(teamId: string): Promise<RosterPayload> {
  const empty: RosterPayload = { registrations: [], counts: {} };
  if (!teamId) return empty;
  try {
    const res = await fetch(
      `${API_BASE}/api/sports/registrations?teamId=${encodeURIComponent(teamId)}`,
      { headers: await authHeaders() },
    );
    if (!res.ok) return empty;
    const data = await res.json().catch(() => null);
    return {
      registrations:
        data && Array.isArray(data.registrations) ? data.registrations : [],
      counts: data && typeof data.counts === "object" && data.counts ? data.counts : {},
    };
  } catch {
    return empty;
  }
}

/**
 * Places left per position for a team, so the registration form never offers
 * a full slot blind. Mirrors the web form's GET /api/sports/registrations.
 */
export async function fetchPositionCounts(teamId: string): Promise<PositionCounts> {
  return (await fetchRoster(teamId)).counts;
}

/**
 * The signed-in member's own registration (one team per member), or null when
 * they haven't registered / aren't signed in — the join-a-team screen's
 * "you're already on a team" branch.
 */
export async function myRegistration(): Promise<MyRegistration | null> {
  const res = await fetch(`${API_BASE}/api/sports/registrations/mine`, {
    headers: await authHeaders(),
  });
  if (res.status === 401) return null;
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    throw new Error(data?.error || "Could not load your team.");
  }
  return (data?.data ?? null) as MyRegistration | null;
}

/**
 * Submit one player registration (multipart — the backend uploads the photo
 * to Cloudinary). Resolves with `active` when the position still had a place, or
 * `waitlist` when the position was already full.
 */
export async function registerPlayer(
  input: PlayerRegistrationInput,
): Promise<SportsRegistrationResult> {
  const body = new FormData();
  body.append("clubSlug", input.clubSlug);
  if (input.clubName) body.append("clubName", input.clubName);
  body.append("teamId", input.teamId);
  if (input.teamName) body.append("teamName", input.teamName);
  body.append("name", input.name);
  body.append("age", String(input.age));
  if (input.gender) body.append("gender", input.gender);
  if (input.phone) body.append("phone", input.phone);
  body.append("heightCm", String(input.heightCm));
  body.append("religion", input.religion);
  body.append("position", input.position);
  body.append("foot", input.foot);
  body.append("hand", input.hand);
  body.append(
    "photo",
    new File(input.photo.uri),
    input.photo.name || "player-photo.jpg",
  );

  const res = await fetch(`${API_BASE}/api/sports/registrations`, {
    method: "POST",
    headers: await authHeaders(),
    body,
  });
  const data = await res.json().catch(() => ({}) as any);
  if (!res.ok) {
    throw new Error(data?.error || "Registration failed. Try again.");
  }
  return data as SportsRegistrationResult;
}

/**
 * My team registration for screens with "Join / Register" CTAs: fetched once
 * on mount, then `check()` gates every register button — resolving to the
 * existing registration (show the status sheet) or null (open the form).
 *
 * Fail-open: a network error resolves to null so a hiccup never blocks the
 * form — the API's one-team 409 still catches duplicates at submit.
 */
export function useMyRegistration(): {
  /** undefined = still fetching, null = none, otherwise my registration. */
  mine: MyRegistration | null | undefined;
  check: () => Promise<MyRegistration | null>;
} {
  const [mine, setMine] = useState<MyRegistration | null | undefined>(undefined);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const m = await myRegistration();
        if (active) setMine(m);
      } catch {
        if (active) setMine(null);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const check = useCallback(async (): Promise<MyRegistration | null> => {
    if (mine !== undefined) return mine;
    try {
      const m = await myRegistration();
      setMine(m);
      return m;
    } catch {
      setMine(null);
      return null;
    }
  }, [mine]);

  return { mine, check };
}
