import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useEffect, useRef, useState } from "react";
import {
  Animated,
  BackHandler,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { setDrawerOpen } from "@/services/unread";

export type CommunityTabKey = "groups" | "skills" | "social" | "spiritual";
export type CommunitySubKey =
  | "groups"
  | "requests"
  | "all"
  | "offering"
  | "seeking"
  | "jobs";

type MenuItem = {
  key: string;
  label: string;
  tagline: string;
  icon: any;
  /** Switches the active Community section. */
  tab: CommunityTabKey;
  /** Optional sub-section within the Skills section. */
  sub?: CommunitySubKey;
};

const SECTIONS: { title: string; items: MenuItem[] }[] = [
  {
    title: "Groups",
    items: [
      {
        key: "groups",
        label: "Groups",
        tagline: "Create or join a group on any topic",
        icon: "people-outline",
        tab: "groups",
      },
    ],
  },
  {
    title: "Spiritual",
    items: [
      {
        key: "requests",
        label: "Prayer Requests",
        tagline: "Share what's on your heart",
        icon: "heart-outline",
        tab: "spiritual",
      },
    ],
  },
  {
    title: "Social",
    items: [
      {
        key: "social",
        label: "Events & Socials",
        tagline: "Connect with others ",
        icon: "calendar-outline",
        tab: "social",
      },
    ],
  },
  {
    title: "Skills",
    items: [
      {
        key: "skills-all",
        label: "All",
        tagline: "Browse everything",
        icon: "apps-outline",
        tab: "skills",
        sub: "all",
      },
      {
        key: "skills-offering",
        label: "Offer",
        tagline: "Offer your skills",
        icon: "hand-right-outline",
        tab: "skills",
        sub: "offering",
      },
      {
        key: "skills-seeking",
        label: "Seek",
        tagline: "Find someone to help",
        icon: "search-outline",
        tab: "skills",
        sub: "seeking",
      },
      {
        key: "skills-jobs",
        label: "Jobs",
        tagline: "Opportunities to serve",
        icon: "briefcase-outline",
        tab: "skills",
        sub: "jobs",
      },
    ],
  },
];

export default function CommunityMenuDrawer({
  open,
  onClose,
  activeTab,
  activeSub,
  onSelectTab,
}: {
  open: boolean;
  onClose: () => void;
  activeTab: CommunityTabKey;
  activeSub?: CommunitySubKey | null;
  onSelectTab: (tab: CommunityTabKey, sub?: CommunitySubKey) => void;
}) {
  const { width } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const panelWidth = Math.min(width * 0.84, 380);
  // Stored in state (never replaced) so animations work while satisfying the
  // react-hooks/refs rule that forbids reading refs during render.
  const [progress] = useState(() => new Animated.Value(0));
  const mountedOnce = useRef(false);

  // Keep the floating tab bar hidden while the drawer is open.
  useEffect(() => {
    setDrawerOpen(open);
    return () => setDrawerOpen(false);
  }, [open]);

  // Slide in on open and slide out on close. The panel stays mounted so the
  // exit animation can play; pointerEvents is disabled while closed. The
  // first run is skipped since the value already starts at the closed state.
  useEffect(() => {
    if (!mountedOnce.current) {
      mountedOnce.current = true;
      return;
    }
    Animated.timing(progress, {
      toValue: open ? 1 : 0,
      duration: open ? 240 : 200,
      useNativeDriver: true,
    }).start();
  }, [open, progress]);

  // Android hardware back closes the menu first.
  useEffect(() => {
    if (!open) return;
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      onClose();
      return true;
    });
    return () => sub.remove();
  }, [open, onClose]);

  const translateX = progress.interpolate({
    inputRange: [0, 1],
    outputRange: [-panelWidth, 0],
  });

  const handleSelect = (item: MenuItem) => {
    onClose();
    onSelectTab(item.tab, item.sub);
  };

  return (
    <View
      style={styles.root}
      pointerEvents={open ? "auto" : "none"}
      importantForAccessibility={open ? "auto" : "no-hide-descendants"}
      accessibilityElementsHidden={!open}
    >
      <Animated.View style={[styles.backdrop, { opacity: progress }]}>
        <Pressable
          style={styles.backdropPress}
          onPress={onClose}
          accessibilityLabel="Close menu"
        />
      </Animated.View>

      <Animated.View
        style={[
          styles.panel,
          { width: panelWidth, transform: [{ translateX }] },
        ]}
      >
        <LinearGradient
          colors={[colors.goldDark, colors.goldLight]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[styles.panelHead, { paddingTop: insets.top + 16 }]}
        >
          <TouchableOpacity
            style={styles.closeBtn}
            onPress={onClose}
            activeOpacity={0.8}
            accessibilityLabel="Close menu"
          >
            <Ionicons name="close" size={20} color={colors.white} />
          </TouchableOpacity>

          <View style={styles.brandRow}>
            <View style={styles.brandIcon}>
              <Ionicons name="leaf" size={18} color={colors.gold} />
            </View>
            <Text style={styles.brandName}>Relate</Text>
          </View>
          <Text style={styles.headEyebrow}>EXPLORE</Text>
          <Text style={styles.headTitle}>Choose a section</Text>
        </LinearGradient>

        <ScrollView
          showsVerticalScrollIndicator={false}
          contentContainerStyle={{
            paddingBottom: insets.bottom + 24,
          }}
        >
          {SECTIONS.map((section) => (
            <View key={section.title} style={styles.section}>
              <Text style={styles.sectionLabel}>
                {section.title.toUpperCase()}
              </Text>
              <View style={styles.sectionCard}>
                {section.items.map((item, i) => {
                  const active =
                    item.tab === activeTab &&
                    (item.sub ?? null) === (activeSub ?? null);
                  return (
                    <TouchableOpacity
                      key={item.key}
                      style={[
                        styles.row,
                        i < section.items.length - 1 && styles.rowBorder,
                        active && styles.rowActive,
                      ]}
                      onPress={() => handleSelect(item)}
                      activeOpacity={0.8}
                    >
                      {active ? (
                        <LinearGradient
                          colors={[colors.forestSoft, colors.forestDark]}
                          start={{ x: 0, y: 0 }}
                          end={{ x: 1, y: 1 }}
                          style={styles.rowIcon}
                        >
                          <Ionicons
                            name={item.icon}
                            size={18}
                            color={colors.white}
                          />
                        </LinearGradient>
                      ) : (
                        <View style={styles.rowIcon}>
                          <Ionicons
                            name={item.icon}
                            size={18}
                            color={colors.forest}
                          />
                        </View>
                      )}
                      <View style={styles.rowBody}>
                        <Text style={styles.rowLabel}>{item.label}</Text>
                        <Text style={styles.rowTagline} numberOfLines={1}>
                          {item.tagline}
                        </Text>
                      </View>
                      {active ? (
                        <View style={styles.activeChip}>
                          <Ionicons
                            name="checkmark"
                            size={12}
                            color={colors.forestDark}
                          />
                        </View>
                      ) : (
                        <Ionicons
                          name="chevron-forward"
                          size={16}
                          color={colors.muted}
                        />
                      )}
                    </TouchableOpacity>
                  );
                })}
              </View>
            </View>
          ))}
        </ScrollView>
      </Animated.View>
    </View>
  );
}

