import { API_BASE } from "@/services/config";
import { getRequestHeaders } from "@/services/auth";

/**
 * Interactive-block responses for study-guide daily reads.
 *
 * Responses are kept as drafts in memory and flushed to
 * PUT /api/reading-responses on a short debounce — never per keystroke — and
 * immediately on blur / unmount / "Mark as read". The server owns the values
 * per block: checklist/pray -> number[] of checked indices, quiz -> number of
 * the selected option, reflection -> string.
 */

export type DayResponses = Record<string, unknown>;

const FLUSH_DEBOUNCE_MS = 800;

async function apiRequest(path: string, options: RequestInit = {}) {
  const headers = await getRequestHeaders({
    "Content-Type": "application/json",
    ...((options.headers as Record<string, string>) || {}),
  });
  return fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });
}

type Draft = {
  responses: DayResponses;
  timer: ReturnType<typeof setTimeout> | null;
};

const drafts = new Map<string, Draft>();

const keyOf = (publicationId: string, date: string) => `${publicationId}::${date}`;

/** Loads the user's responses for a publication into a { date: responses } map. */
export async function fetchReadingResponses(
  publicationId: string,
): Promise<Record<string, DayResponses>> {
  const out: Record<string, DayResponses> = {};
  try {
    const res = await apiRequest(
      `/api/reading-responses?publicationId=${encodeURIComponent(publicationId)}`,
    );
    if (!res.ok) return out;
    const { data } = await res.json();
    if (Array.isArray(data)) {
      for (const day of data) {
        if (day?.date && day?.responses) out[day.date] = day.responses;
      }
    }
  } catch {}
  return out;
}

/** Returns any in-memory draft, falling back to a freshly loaded map. */
export function getDayResponses(publicationId: string, date: string): DayResponses {
  const key = keyOf(publicationId, date);
  return drafts.get(key)?.responses || {};
}

/** Whether this day currently has an unsaved draft pending flush. */
export function hasDraft(publicationId: string, date: string): boolean {
  const key = keyOf(publicationId, date);
  const draft = drafts.get(key);
  return !!draft && draft.timer !== null;
}

/**
 * Merges a block-level patch into the day's draft and schedules a flush.
 * Callers pass only the changed block id -> raw value.
 */
export function updateDayResponses(
  publicationId: string,
  date: string,
  patch: DayResponses,
) {
  const key = keyOf(publicationId, date);
  const existing = drafts.get(key);
  const responses = { ...(existing?.responses || {}), ...patch };
  if (existing?.timer) clearTimeout(existing.timer);

  const timer = setTimeout(() => {
    void flushDay(publicationId, date);
  }, FLUSH_DEBOUNCE_MS);

  drafts.set(key, { responses, timer });
}

/** Flushes a day's draft to the server immediately. */
export async function flushDay(publicationId: string, date: string): Promise<void> {
  const key = keyOf(publicationId, date);
  const draft = drafts.get(key);
  if (!draft) return;
  if (draft.timer) {
    clearTimeout(draft.timer);
    drafts.set(key, { responses: draft.responses, timer: null });
  }
  try {
    await apiRequest("/api/reading-responses", {
      method: "PUT",
      body: JSON.stringify({ publicationId, date, responses: draft.responses }),
    });
  } catch {
    // Keep the draft so a later flush retries; the user's answers aren't lost.
  }
}

/** Removes any pending timer for a day (e.g. component unmount). */
export function cancelDayTimer(publicationId: string, date: string) {
  const key = keyOf(publicationId, date);
  const draft = drafts.get(key);
  if (draft?.timer) {
    clearTimeout(draft.timer);
    drafts.set(key, { responses: draft.responses, timer: null });
  }
}