/* ── Date/time sorting for events and groups ───────────────────────────── */

/** Start time (ms) of an event from its date + time, or null when unparseable. */
function eventStartMs(e: { date: string; time: string }): number | null {
  if (!e.date) return null;
  const day = new Date(`${String(e.date).slice(0, 10)}T00:00:00`);
  if (isNaN(day.getTime())) return null;
  const m = /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i.exec(String(e.time).trim());
  let h = 12;
  let min = 0;
  if (m) {
    h = parseInt(m[1], 10);
    min = m[2] ? parseInt(m[2], 10) : 0;
    const ampm = m[3] ? m[3].toLowerCase() : null;
    if (ampm) {
      if (ampm === "pm" && h < 12) h += 12;
      if (ampm === "am" && h === 12) h = 0;
    } else if (h >= 24) {
      h = h % 24;
    }
  }
  day.setHours(h, min, 0, 0);
  return day.getTime();
}

const GROUP_DAYS = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
];

/** Next occurrence (ms) of a group's recurring meeting, or null when unparseable. */
function groupNextMeetingMs(
  g: { meetingTime: string },
  now: number,
): number | null {
  const text = String(g.meetingTime || "")
    .toLowerCase()
    .trim();
  if (!text) return null;
  const dayIdx = GROUP_DAYS.findIndex((d) => text.includes(d));
  const tm = /(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/.exec(text);
  if (!tm) return null;
  let h = parseInt(tm[1], 10);
  const min = tm[2] ? parseInt(tm[2], 10) : 0;
  const ampm = tm[3] ? tm[3].toLowerCase() : null;
  if (ampm) {
    if (ampm === "pm" && h < 12) h += 12;
    if (ampm === "am" && h === 12) h = 0;
  } else if (h >= 24) {
    h = h % 24;
  }
  const next = new Date(now);
  next.setHours(h, min, 0, 0);
  if (dayIdx === -1) {
    if (next.getTime() <= now) next.setDate(next.getDate() + 1);
    return next.getTime();
  }
  const delta = (dayIdx - next.getDay() + 7) % 7;
  next.setDate(next.getDate() + delta);
  if (next.getTime() <= now) next.setDate(next.getDate() + 7);
  return next.getTime();
}

/** Upcoming first (soonest at the top); past events trail newest-first. */
function sortEvents<T extends { date: string; time: string }>(list: T[]): T[] {
  const now = Date.now();
  return list
    .map((e) => ({ e, at: eventStartMs(e) }))
    .sort((a, b) => {
      const aAt = a.at ?? Number.MAX_SAFE_INTEGER;
      const bAt = b.at ?? Number.MAX_SAFE_INTEGER;
      const aPast = aAt !== Number.MAX_SAFE_INTEGER && aAt < now;
      const bPast = bAt !== Number.MAX_SAFE_INTEGER && bAt < now;
      if (aPast !== bPast) return aPast ? 1 : -1;
      if (aPast) return bAt - aAt;
      return aAt - bAt;
    })
    .map((x) => x.e);
}

/** Live first, then by next meeting time; groups without a time trail newest-first. */
function sortGroups<
  T extends { meetingTime: string; isLive: boolean; createdAt?: string },
>(list: T[]): T[] {
  const now = Date.now();
  const at = (g: T) => (g.isLive ? now : groupNextMeetingMs(g, now));
  return [...list].sort((a, b) => {
    const aAt = at(a) ?? Number.MAX_SAFE_INTEGER;
    const bAt = at(b) ?? Number.MAX_SAFE_INTEGER;
    if (aAt !== bAt) return aAt - bAt;
    const aNew = a.createdAt ? new Date(a.createdAt).getTime() || 0 : 0;
    const bNew = b.createdAt ? new Date(b.createdAt).getTime() || 0 : 0;
    return bNew - aNew;
  });
}

