function CommunityLanding() {
  const router = useRouter();
  const { width: deviceWidth } = useWindowDimensions();
  const [events, setEvents] = useState<Event[]>([]);
  // Skeletons cover the nearby-events rails until the fetch settles so the
  // sections below don't jump when the data lands.
  const [eventsLoading, setEventsLoading] = useState(true);
  const [session, setSession] =
    useState<Awaited<ReturnType<typeof getSession>>>(null);
  const [detailEvent, setDetailEvent] = useState<CommunityEvent | null>(null);
  const [regEvent, setRegEvent] = useState<CommunityEvent | null>(null);
  const scrollRef = useRef<ScrollView>(null);
  const sectionY = useRef<Record<string, number>>({});

  useEffect(() => {
    let active = true;
    communityApi
      .getEvents()
      .then((res) => {
        if (!active) return;
        setEvents(
          sortEvents(
            ((res.data || []) as any[])
              .filter((e: any) => !!e.clubSlug) // Events live inside clubs now.
              .slice(0, 16),
          ),
        );
      })
      .catch(() => {
        if (active) setEvents([]);
      })
      .finally(() => {
        if (active) setEventsLoading(false);
      });
    getSession()
      .then((s) => {
        if (!active) return;
        setSession(s);
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, []);

  const spotlightClubs = SPOTLIGHT_CLUBS;
  const eventCardWidth = deviceWidth - 40;

  // Events are grouped per club so each club owns its own discover rail.
  const eventsByClub = useMemo(() => {
    const map = new Map<string, Event[]>();
    for (const e of events) {
      if (!e.clubSlug) continue;
      const list = map.get(e.clubSlug);
      if (list) list.push(e);
      else map.set(e.clubSlug, [e]);
    }
    return Array.from(map.entries());
  }, [events]);

  const scrollTo = useCallback((key: "events" | "clubs") => {
    const y = sectionY.current[key];
    if (y != null)
      scrollRef.current?.scrollTo({ y: Math.max(0, y - 8), animated: true });
  }, []);

  const openSport = (sport: RelateSport) =>
    router.push({ pathname: "/sports" as any, params: { sport } });

  // Each slide is a club detail hero inside the carousel: the intro, one
  // slide per club (same copy the club page shows) and an events slide.
  const clubSlide = useCallback((club: Club): HeroSlide => ({
    key: club.slug,
    image: club.heroImage ?? "",
    gradient: [colors.forestDark, club.colorDark, club.color],
    chip: club.ageRange,
    title: club.name,
    tagline: club.tagline,
    description: club.description,
    meta: [
      { label: "Group", value: club.group },
      { label: "Age", value: club.ageRange },
      ...(club.programs.length > 0
        ? [{ label: "Programs", value: String(club.programs.length) }]
        : club.slug === "sprout"
          ? [
              {
                label: "Age groups",
                value: String(getClubClasses("sprout").length),
              },
            ]
          : []),
    ],
    cta: {
      label: `Open ${club.name}`,
      onPress: () =>
        router.push({ pathname: "/clubs/[slug]", params: { slug: club.slug } }),
    },
    ghostCta: { label: "Upcoming events", onPress: () => scrollTo("events") },
  }), [router, scrollTo]);

  const heroSlides = useMemo<HeroSlide[]>(() => [
    {
      key: "community",
      image:
        "https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=1600&q=80",
      gradient: [colors.forestDark, colors.forestDark, colors.gold],
      chip: `${spotlightClubs.length} free clubs`,
      title: "Life-giving clubs",
      tagline: "Children, teens and adults — all free to join",
      description:
        "Children, teens and adults — Sprout to Prime. Every club is free to join and built for your season of life.",
      meta: [
        { label: "Clubs", value: String(spotlightClubs.length) },
        { label: "Ages", value: "6 – 33+" },
        { label: "Cost", value: "Free" },
      ],
      cta: { label: "Explore clubs", onPress: () => scrollTo("clubs") },
      ghostCta: { label: "Upcoming events", onPress: () => scrollTo("events") },
    },
    ...spotlightClubs.map(clubSlide),
    {
      key: "events",
      image:
        "https://images.unsplash.com/photo-1511895426328-dc8714191300?w=1600&q=80",
      gradient: [colors.forestDark, colors.forestDark, colors.gold],
      chip: "Near you",
      title: "Come as you are",
      tagline: "Gatherings, games and get-togethers",
      description:
        "Every club hosts its own meet-ups, match days and socials — see what's on and RSVP in a tap.",
      meta: [
        { label: "Events", value: String(events.length) },
        { label: "Clubs", value: String(eventsByClub.length) },
      ],
      cta: { label: "Upcoming events", onPress: () => scrollTo("events") },
      ghostCta: { label: "Explore clubs", onPress: () => scrollTo("clubs") },
    },
  ], [clubSlide, events.length, eventsByClub.length, scrollTo, spotlightClubs]);

  const requireAuth = () => {
    Alert.alert(
      "Sign in required",
      "Sign in to join events and save favorites.",
      [
        { text: "Cancel", style: "cancel" },
        { text: "Sign in", onPress: () => router.push("/login") },
      ],
    );
  };

  const handleRsvp = async (
    eventId: string,
    details?: EventRegistrationDetails,
  ): Promise<boolean> => {
    try {
      const res = await communityApi.rsvpEvent(eventId, details);
      if (res?.data) {
        setEvents((evs) =>
          evs.map((e) =>
            e._id === eventId
              ? {
                  ...e,
                  attending: res.data.attending,
                  hasRsvpd: res.data.hasRsvpd,
                }
              : e,
          ),
        );
        return true;
      }
      return false;
    } catch (err: any) {
      Alert.alert("Error", err?.message || "Failed to RSVP. Please try again.");
      return false;
    }
  };

  return (
    <>
      <ScrollView
        ref={scrollRef}
        showsVerticalScrollIndicator={false}
        removeClippedSubviews={Platform.OS === "android"}
        scrollEventThrottle={16}
        contentContainerStyle={styles.landingScroll}
      >
        <View style={styles.landingHeader}>
          <Text style={styles.headerEyebrow}>CONNECT &amp; GROW</Text>
          <Text style={styles.landingTitle}>Find your club</Text>
          <Text style={styles.headerSubtitle}>
            Clubs, events and sports — one place to belong
          </Text>
        </View>

        {/* ── Hero: photo carousel introducing the clubs ── */}
        <AutoCarousel
          intervalMs={5500}
          sidePadding={20}
        >
          {/* Refs are only read inside the press handlers these slides carry. */}
          {/* eslint-disable-next-line react-hooks/refs */}
          {heroSlides.map((slide) => (
            <LandingHeroSlide key={slide.key} slide={slide} />
          ))}
        </AutoCarousel>

        {/* ── Clubs grid (first — the hero is about clubs too) ── */}
        <View
          onLayout={(e) => {
            sectionY.current.clubs = e.nativeEvent.layout.y;
          }}
        >
          <View style={[landing.sectionHead, landing.sectionGap]}>
            <View style={landing.sectionHeadText}>
              <Text style={landing.sectionEyebrow}>Clubs</Text>
              <Text style={landing.sectionTitle}>Pick a club to explore</Text>
              <Text style={landing.sectionSub}>
                Free to join — open a club to see its programs.
              </Text>
            </View>
          </View>
          <View style={styles.clubsGrid}>
            {spotlightClubs.map((club) => (
              <DiscoverCard
                key={club.slug}
                type="group"
                title={club.name}
                chipLabel={club.ageRange.toUpperCase()}
                tileIcon={club.icon}
                image={club.heroImage}
                gradient={[club.color, club.colorDark]}
                meta={[
                  {
                    icon: "albums-outline",
                    text: `${club.programs.length} ${
                      club.programs.length === 1 ? "program" : "programs"
                    }`,
                  },
                  { icon: "people-outline", text: club.group },
                ]}
                onPress={() =>
                  router.push({
                    pathname: "/clubs/[slug]",
                    params: { slug: club.slug },
                  })
                }
                accessibilityLabel={`Open ${club.name}. ${club.tagline}`}
              />
            ))}
          </View>
        </View>

        {/* ── Events — each club gets its own discover rail ── */}
        {eventsLoading || eventsByClub.length > 0 ? (
          <View
            onLayout={(e) => {
              sectionY.current.events = e.nativeEvent.layout.y;
            }}
          >
            <View style={[landing.sectionHead, landing.sectionGap]}>
              <View style={landing.sectionHeadText}>
                <Text style={landing.sectionEyebrow}>
                  Match days &amp; gatherings
                </Text>
                <Text style={landing.sectionTitle}>
                  What&rsquo;s happening near you
                </Text>
                <Text style={landing.sectionSub}>
                  Games, gatherings and get-togethers across every Relate club.
                </Text>
              </View>
              <TouchableOpacity
                onPress={() =>
                  router.push({
                    pathname: "/(tabs)/community",
                    params: { tab: "social" },
                  })
                }
                style={landing.viewAll}
                hitSlop={{ top: 10, bottom: 10, left: 6, right: 6 }}
                activeOpacity={0.7}
                accessibilityRole="link"
              >
                <Text style={landing.viewAllText}>All events</Text>
                <Ionicons
                  name="chevron-forward"
                  size={14}
                  color={colors.goldDark}
                />
              </TouchableOpacity>
            </View>

            {eventsLoading ? (
              <NearbyEventsSkeleton cardWidth={eventCardWidth} />
            ) : (
              eventsByClub.map(([slug, clubEvents]) => {
                const club = getClub(slug);
                if (!club) return null;
                return (
                  <View key={slug} style={landing.clubRail}>
                    <View style={landing.clubRailHead}>
                      <View
                        style={[
                          landing.clubRailDot,
                          { backgroundColor: club.color },
                        ]}
                      />
                      <View style={landing.clubRailText}>
                        <Text
                          style={[
                            landing.clubRailEyebrow,
                            { color: club.colorDark },
                          ]}
                        >
                          {club.group.toUpperCase()} ·{" "}
                          {club.ageRange.toUpperCase()}
                        </Text>
                        <Text style={landing.clubRailTitle} numberOfLines={1}>
                          {club.name} — {clubEvents.length}{" "}
                          {clubEvents.length === 1 ? "event" : "events"}
                        </Text>
                      </View>
                      <TouchableOpacity
                        onPress={() =>
                          router.push({
                            pathname: "/clubs/[slug]",
                            params: { slug },
                          })
                        }
                        style={[
                          landing.clubRailOpen,
                          { backgroundColor: `${club.color}1A` },
                        ]}
                        hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                        accessibilityRole="button"
                        accessibilityLabel={`Open ${club.name}`}
                      >
                        <Ionicons
                          name="arrow-forward"
                          size={15}
                          color={club.colorDark}
                        />
                      </TouchableOpacity>
                    </View>
                    <ScrollView
                      horizontal
                      showsHorizontalScrollIndicator={false}
                      contentContainerStyle={landing.eventRail}
                    >
                      {clubEvents.map((e) => (
                        <ClubEventCard
                          key={e._id}
                          event={e}
                          width={eventCardWidth}
                          onPress={() => setDetailEvent(toCommunityEvent(e))}
                        />
                      ))}
                    </ScrollView>
                  </View>
                );
              })
            )}
          </View>
        ) : null}

        {/* ── Sports league — compact banner ── */}
        <TouchableOpacity
          style={[landing.sectionGap, landing.sportsBanner]}
          activeOpacity={0.92}
          onPress={() => router.push("/sports" as any)}
          accessibilityRole="button"
          accessibilityLabel="Sports leagues — play for a Relate team"
        >
          <ExpoImage
            source={{ uri: getOptimizedImageUrl(SPORT_THEME.Football.image, 1200) }}
            style={StyleSheet.absoluteFill}
            contentFit="cover"
            transition={250}
            accessibilityLabel="Sports leagues"
          />
          <LinearGradient
            colors={["rgba(9,23,15,0.86)", "rgba(9,23,15,0.32)"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={StyleSheet.absoluteFill}
          />
          <View style={landing.sportsBannerBody}>
            <View>
              <Text style={landing.sportsBannerEyebrow}>Sports leagues</Text>
              <Text style={landing.sportsBannerTitle}>
                Play for a Relate team
              </Text>
            </View>
            <View style={landing.sportsBannerCta}>
              <Text style={landing.sportsBannerCtaText}>All teams</Text>
              <Ionicons
                name="arrow-forward"
                size={15}
                color={colors.forestDark}
              />
            </View>
          </View>
        </TouchableOpacity>
        <View style={[landing.sectionHead, { marginTop: 24 }]}>
          <View style={landing.sectionHeadText}>
            <Text style={landing.sectionEyebrow}>Sports league</Text>
            <Text style={landing.sectionTitle}>Pick your sport</Text>
            <Text style={landing.sectionSub}>
              Football, netball and volleyball — training midweek, match days on
              the weekend.
            </Text>
          </View>
          <TouchableOpacity
            onPress={() => router.push("/sports" as any)}
            style={landing.viewAll}
            hitSlop={{ top: 10, bottom: 10, left: 6, right: 6 }}
            activeOpacity={0.7}
            accessibilityRole="link"
          >
            <Text style={landing.viewAllText}>All teams</Text>
            <Ionicons
              name="chevron-forward"
              size={14}
              color={colors.goldDark}
            />
          </TouchableOpacity>
        </View>
        <View style={landing.sportList}>
          {SPORTS.map((sport) => {
            const theme = SPORT_THEME[sport];
            const teams = teamsForSport(sport);
            return (
              <TouchableOpacity
                key={sport}
                style={landing.sportRow}
                activeOpacity={0.88}
                onPress={() => openSport(sport)}
                accessibilityLabel={`${sport} — view teams`}
              >
                <LinearGradient
                  colors={theme.colors}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={landing.sportRowIcon}
                >
                  <MaterialCommunityIcons
                    name={theme.icon as any}
                    size={24}
                    color={colors.white}
                  />
                </LinearGradient>
                <View style={landing.sportRowBody}>
                  <Text style={landing.sportRowTitle}>{sport}</Text>
                  <Text style={landing.sportRowSub} numberOfLines={1}>
                    {theme.line}
                  </Text>
                </View>
                <View
                  style={[
                    landing.sportRowChip,
                    { backgroundColor: `${theme.accent}1A` },
                  ]}
                >
                  <Text
                    style={[landing.sportRowChipText, { color: theme.accent }]}
                  >
                    {teams.length} teams
                  </Text>
                </View>
                <Ionicons
                  name="chevron-forward"
                  size={18}
                  color={theme.accent}
                />
              </TouchableOpacity>
            );
          })}
        </View>

        <Text style={styles.landingHint}>
          Every club is free to join — meet, play and grow together
        </Text>
      </ScrollView>

      {/* Event detail (full screen with RSVP + payments) — reused component */}
      {detailEvent ? (
        <EventDetailModal
          event={detailEvent}
          currentUserId={session?.user?.id || null}
          onClose={() => setDetailEvent(null)}
          joinLoading={false}
          onJoin={() => {
            if (!session?.user) return requireAuth();
            if (detailEvent.hasRsvpd) {
              handleRsvp(detailEvent.id);
            } else {
              setDetailEvent(null);
              setRegEvent(detailEvent);
            }
          }}
          onEdit={() => {
            const slug = detailEvent.clubSlug;
            setDetailEvent(null);
            if (slug) {
              router.push({ pathname: "/clubs/[slug]", params: { slug } });
            }
          }}
          onDelete={() => {
            const ev = detailEvent;
            Alert.alert("Delete event", `Delete "${ev.title}"?`, [
              { text: "Cancel", style: "cancel" },
              {
                text: "Delete",
                style: "destructive",
                onPress: async () => {
                  try {
                    await communityApi.deleteEvent(ev.id);
                    setEvents((evs) => evs.filter((e) => e._id !== ev.id));
                  } catch {
                    Alert.alert("Error", "Failed to delete the event.");
                  }
                  setDetailEvent(null);
                },
              },
            ]);
          }}
        />
      ) : null}

      {/* RSVP registration modal — reused component */}
      {regEvent ? (
        <EventRegistrationModal
          key={regEvent.id}
          event={regEvent}
          onClose={() => setRegEvent(null)}
          onSubmit={(details) => handleRsvp(regEvent.id, details)}
        />
      ) : null}
    </>
  );
}

