export default function CommunityScreen() {
  const params = useLocalSearchParams<{
    tab?: string;
    event?: string;
    section?: string;
    filter?: string;
  }>();
  const router = useRouter();
  const openEventId =
    typeof params.event === "string" && params.event ? params.event : undefined;
  // Groups is its own tab; spiritual holds prayer requests. Legacy deep links
  // used ?section=groups / ?section=requests — map those to the right tab.
  const initialTab =
    params.tab && TABS.some((x) => x.key === params.tab)
      ? (params.tab as TabKey)
      : params.section === "groups"
        ? "groups"
        : params.section === "requests"
          ? "spiritual"
          : "spiritual";
  const [tab, setTab] = useState<TabKey>(initialTab);
  const [menuOpen, setMenuOpen] = useState(false);
  const [lastTabParam, setLastTabParam] = useState<string | undefined>(
    params.tab || (params.section as string | undefined),
  );

  // Club-cards landing: shown by default until a section is chosen or an
  // active ?tab/?section/?event deep link routes straight into a section.
  const [onLanding, setOnLanding] = useState<boolean>(
    () => !params.tab && !params.section && !params.event,
  );
  const deepLinkedNow = !!(params.tab || params.section || params.event);
  const showLanding = onLanding && !deepLinkedNow;

  // Keep the active tab in sync with a ?tab= deep link (e.g. from the
  // home-screen banners) using render-time state adjustment, per React docs.
  const targetTab =
    params.tab && TABS.some((x) => x.key === params.tab)
      ? (params.tab as TabKey)
      : params.section === "groups"
        ? "groups"
        : params.section === "requests"
          ? "spiritual"
          : null;
  if (targetTab && lastTabParam !== (params.tab || params.section)) {
    setLastTabParam(params.tab || params.section);
    setTab(targetTab);
  }
  // A deep link with ?event=<id> (from the "What's new" rail) opens the
  // event's detail card directly on the Social tab.
  if (openEventId && tab !== "social") {
    setTab("social");
  }
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [createType, setCreateType] = useState<
    "skill" | "event" | "group" | "request" | "job" | null
  >(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [currentUserRole, setCurrentUserRole] = useState<string | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [editingItem, setEditingItem] = useState<EditingItem | null>(null);

  const [prayerReqVisible, setPrayerReqVisible] = useState(false);
  const [prayerReqEditing, setPrayerReqEditing] =
    useState<PrayerRequest | null>(null);
  const [showJoinByCode, setShowJoinByCode] = useState(false);
  const [filter, setFilter] = useState<"all" | "offering" | "seeking" | "jobs">(
    "all",
  );
  // Deep links can also pick the skills filter (?filter=jobs) once the
  // skills tab is active.
  if (tab === "skills" && params.filter === "jobs" && filter !== "jobs") {
    setFilter("jobs");
  }

  // Deep-link section/filter params are one-shot: once they've been applied
  // (their tab is active), clear them so they don't re-force the section or
  // filter on every later visit to the Community tab — mirroring how the
  // ?event= deep link is cleared after it opens an event.
  useEffect(() => {
    if (params.section !== undefined) {
      const mapped =
        params.section === "groups"
          ? "groups"
          : params.section === "requests"
            ? "spiritual"
            : null;
      if (mapped && tab === mapped) {
        router.setParams({ section: undefined });
      }
    }
    if (params.filter !== undefined && tab === "skills") {
      router.setParams({ filter: undefined });
    }
  }, [params.section, params.filter, tab, router]);
  const [skills, setSkills] = useState<SkillListing[]>([]);
  const [jobs, setJobs] = useState<JobListing[]>([]);
  const [events, setEvents] = useState<SocialEvent[]>([]);
  const [groups, setGroups] = useState<PrayerGroup[]>([]);
  const [requests, setRequests] = useState<PrayerRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});

  useEffect(() => {
    (async () => {
      const s = await getSession();
      setCurrentUserId(s?.user?.id || null);
      setCurrentUserRole(s?.user?.role || null);
      setSessionLoading(false);
    })();
  }, []);

  const requireAuth = () => {
    Alert.alert(
      "Sign in required",
      "Sign in to join events and save favorites.",
      [
        { text: "Cancel", style: "cancel" },
        { text: "Sign in", onPress: () => router.push("/login") },
      ],
    );
  };

  const fetchSkills = async () => {
    try {
      const res = await communityApi.getSkills();
      if (res?.data)
        setSkills(
          res.data.map((s: any) => ({
            id: s._id || s.id,
            title: s.title,
            category: s.category,
            description: s.description,
            offering: s.offering,
            author: s.author,
            date: s.createdAt || s.date || "",
            time: s.time || "",
            connected: s.connected || false,
            connectionCount: s.connectionCount || 0,
            connectedUsers: s.connectedUsers || [],
            isOwner: s.isOwner || false,
          })),
        );
    } catch (e: any) {
      console.error("Failed to load skills:", e);
    }
  };

  const fetchJobs = async () => {
    try {
      const res = await communityApi.getJobs();
      if (res?.data)
        setJobs(
          res.data.map((j: any) => ({
            id: j._id || j.id,
            title: j.title,
            company: j.company,
            location: j.location,
            type: j.type,
            description: j.description,
            category: j.category,
            salary: j.salary,
            contactEmail: j.contactEmail,
            author: j.author,
            applied: j.applied || false,
            applicationCount: j.applicationCount || 0,
            applicants: j.applicants || [],
            isOwner: j.isOwner || false,
            date: j.createdAt || "",
          })),
        );
    } catch (e: any) {
      console.error("Failed to load jobs:", e);
    }
  };

  const fetchEvents = async () => {
    try {
      const res = await communityApi.getEvents();
      if (res?.data)
        setEvents(
          sortEvents(
            res.data
              .filter((e: any) => !!e.clubSlug) // Events live inside clubs now; unscoped legacy events are retired.
              .map((e: any) => ({
                id: e._id || e.id,
                title: e.title,
                date: e.date,
                time: e.time,
                dateTo: e.dateTo || undefined,
                timeTo: e.timeTo || undefined,
                agenda: Array.isArray(e.agenda) ? e.agenda : [],
                notes: e.notes || "",
                location: e.location,
                description: e.description,
                fee: e.fee || "Free",
                imageUrl: e.imageUrl || null,
                author: e.author || "",
                userId: e.userId || null,
                attending: e.attending || 0,
                hasRsvpd: e.hasRsvpd || false,
                isBookmarked: e.isBookmarked || false,
                rsvpUsers: e.rsvpUsers || [],
                isOwner: e.isOwner || false,
                hasPaid: e.hasPaid || false,
                feeAmount: e.feeAmount || 0,
                feeSymbol: e.feeSymbol || "",
                totalDue: e.totalDue ?? e.feeAmount ?? 0,
                amountPaid: e.amountPaid || 0,
                pendingAmount: e.pendingAmount || 0,
                remaining: e.remaining ?? e.totalDue ?? e.feeAmount ?? 0,
                myPartner: e.myPartner || false,
                category: e.category || undefined,
                eyebrow: e.eyebrow || undefined,
                titleAccent: e.titleAccent || undefined,
                tags: Array.isArray(e.tags) ? e.tags : [],
                host: e.host || undefined,
                capacity:
                  typeof e.capacity === "number" ? e.capacity : undefined,
                details: Array.isArray(e.details) ? e.details : [],
                clubSlug: (e as any).clubSlug || undefined,
              })),
          ),
        );
    } catch (e: any) {
      console.error("Failed to load events:", e);
    }
  };

  const fetchGroups = async () => {
    try {
      const res = await communityApi.getGroups();
      if (res?.data)
        setGroups(
          sortGroups(
            res.data
              .filter((g: any) => !!g.clubSlug) // Groups live inside clubs now; unscoped legacy groups are retired.
              .map((g: any) => ({
                id: g._id || g.id,
                name: g.name,
                description: g.description,
                category: g.category || "prayer",
                imageUrl: g.imageUrl || null,
                facilitator: g.facilitator || "",
                location: g.location || "",
                audience: g.audience || "",
                notes: g.notes || "",
                contactInfo: g.contactInfo || "",
                inviteCode: g.inviteCode || "",
                meetingTime: g.meetingTime || "",
                schedule: g.schedule || "",
                maxMembers: g.maxMembers || 0,
                members: g.members || 0,
                commentCount: g.commentCount || 0,
                isLive: g.live || false,
                activeSession: g.activeSession || null,
                hasJoined: g.hasJoined || false,
                joinedUsers: g.joinedUsers || [],
                isOwner: g.isOwner || false,
                clubSlug: g.clubSlug || undefined,
                createdAt: g.createdAt || "",
              })),
          ),
        );
    } catch (e: any) {
      console.error("Failed to load groups:", e);
    }
  };

  const fetchRequests = async () => {
    try {
      const res = await communityApi.getRequests();
      if (res?.data)
        setRequests(
          res.data.map((r: any) => ({
            id: r._id || r.id,
            title: r.title || r.text,
            description: r.description || r.text,
            author: r.author,
            date: r.createdAt || r.date || "",
            category: r.category || "",
            anonymous: !!r.anonymous,
            visibility: r.visibility || "community",
            email: r.email || "",
            prayCount: r.prayCount || 0,
            commentCount: r.commentCount || 0,
            prayedByMe: r.prayedByMe || false,
            prayedUsers: r.prayedUsers || [],
            isOwner: r.isOwner || false,
          })),
        );
    } catch (e: any) {
      console.error("Failed to load requests:", e);
    }
  };

  const refreshData = useCallback(
    async (isRefresh = false) => {
      if (isRefresh) {
        setRefreshing(true);
        // Bypass the 30s fetch cache so pull-to-refresh is a true refresh.
        const token = await getSessionToken();
        invalidateCache("/api/community", token);
      } else {
        setLoading(true);
      }

      if (tab === "skills") {
        await Promise.all([fetchSkills(), fetchJobs()]);
      } else if (tab === "social") {
        await fetchEvents();
      } else if (tab === "groups") {
        await fetchGroups();
      } else if (tab === "spiritual") {
        await fetchRequests();
      }

      setLoading(false);
      setRefreshing(false);
    },
    [tab],
  );

  // Track when each tab was last loaded to avoid redundant refetches
  // when quickly switching between tabs.
  const lastLoadedRef = useRef<Record<string, number>>({});
  const RELOAD_GAP_MS = 10_000; // 10 seconds

  useFocusEffect(
    useCallback(() => {
      if (showLanding) return; // Landing only lists clubs — no section data needed.
      (async () => {
        const now = Date.now();
        const last = lastLoadedRef.current[tab] || 0;
        if (now - last < RELOAD_GAP_MS) return; // Skip if loaded recently
        lastLoadedRef.current[tab] = now;

        setLoading(true);
        if (tab === "skills") {
          await Promise.all([fetchSkills(), fetchJobs()]);
        } else if (tab === "social") {
          await fetchEvents();
        } else if (tab === "groups") {
          await fetchGroups();
        } else if (tab === "spiritual") {
          await fetchRequests();
        }
        setLoading(false);
      })();
    }, [tab, showLanding]),
  );

  const handleConnectSkill = async (skillId: string) => {
    const prev = skills;
    setSkills((s) =>
      s.map((sk) =>
        sk.id === skillId ? { ...sk, connected: !sk.connected } : sk,
      ),
    );
    try {
      const res = await communityApi.connectSkill(skillId);
      setSkills((s) =>
        s.map((sk) =>
          sk.id === skillId
            ? { ...sk, connected: res?.data?.connected ?? !sk.connected }
            : sk,
        ),
      );
    } catch {
      setSkills(prev);
      Alert.alert("Error", "Failed to connect. Please try again.");
    }
  };

  const handleApply = async (jobId: string) => {
    const prev = jobs;
    setJobs((j) =>
      j.map((job) =>
        job.id === jobId ? { ...job, applied: !job.applied } : job,
      ),
    );
    try {
      const res = await communityApi.applyForJob(jobId);
      setJobs((j) =>
        j.map((job) =>
          job.id === jobId
            ? { ...job, applied: res?.data?.applied ?? !job.applied }
            : job,
        ),
      );
    } catch {
      setJobs(prev);
      Alert.alert("Error", "Failed to apply. Please try again.");
    }
  };

  const handleRsvp = async (
    eventId: string,
    details?: EventRegistrationDetails,
  ): Promise<boolean> => {
    const prev = events;
    const optimisticDelta = details ? (details.bringingPartner ? 2 : 1) : 1;
    setEvents((ev) =>
      ev.map((e) =>
        e.id === eventId
          ? {
              ...e,
              hasRsvpd: !e.hasRsvpd,
              attending: e.hasRsvpd
                ? Math.max(0, e.attending - 1)
                : e.attending + optimisticDelta,
            }
          : e,
      ),
    );
    setLoadingItems((prev) => ({ ...prev, [`rsvp_${eventId}`]: true }));
    try {
      const res = await communityApi.rsvpEvent(eventId, details);
      if (res?.data) {
        setEvents((ev) =>
          ev.map((e) =>
            e.id === eventId
              ? {
                  ...e,
                  attending: res.data.attending,
                  hasRsvpd: res.data.hasRsvpd,
                }
              : e,
          ),
        );
        return true;
      }
      setEvents(prev);
      return false;
    } catch {
      setEvents(prev);
      Alert.alert("Error", "Failed to RSVP. Please try again.");
      return false;
    } finally {
      setLoadingItems((prev) => ({ ...prev, [`rsvp_${eventId}`]: false }));
    }
  };

  const handleToggleSave = async (eventId: string) => {
    const prev = events;
    setEvents((ev) =>
      ev.map((e) =>
        e.id === eventId ? { ...e, isBookmarked: !e.isBookmarked } : e,
      ),
    );
    try {
      const res = await communityApi.toggleBookmark("events", eventId);
      setEvents((ev) =>
        ev.map((e) =>
          e.id === eventId
            ? { ...e, isBookmarked: res?.data?.bookmarked ?? e.isBookmarked }
            : e,
        ),
      );
    } catch {
      setEvents(prev);
      Alert.alert("Error", "Failed to save. Please try again.");
    }
  };

  const handleJoinGroup = async (groupId: string) => {
    const prev = groups;
    setGroups((g) =>
      g.map((gr) =>
        gr.id === groupId
          ? {
              ...gr,
              hasJoined: !gr.hasJoined,
              members: gr.hasJoined ? gr.members - 1 : gr.members + 1,
            }
          : gr,
      ),
    );
    try {
      const res = await communityApi.joinGroup(groupId);
      if (res?.data) {
        setGroups((g) =>
          g.map((gr) =>
            gr.id === groupId
              ? {
                  ...gr,
                  members: res.data.members,
                  hasJoined: res.data.hasJoined,
                }
              : gr,
          ),
        );
      }
    } catch {
      setGroups(prev);
      Alert.alert("Error", "Failed to join group. Please try again.");
    }
  };

  const openCall = (session: GroupSession, groupName: string) => {
    if (IS_WEB) return;
    if (!session?.roomUrl) {
      Alert.alert("Session unavailable", "This session has no room yet.");
      return;
    }
    router.push({
      pathname: "/call" as any,
      params: {
        roomUrl: session.roomUrl,
        token: session.token || "",
        userName: session.startedByName || "Group member",
        type: session.type,
        groupName,
        isOwner: session.isOwner ? "1" : "0",
        accessCode: session.accessCode || "",
        groupId: session.sessionId?.split("-")[0] || "",
        startedAt: session.startedAt
          ? String(new Date(session.startedAt).getTime())
          : String(Date.now()),
        durationMs: session.durationMs
          ? String(session.durationMs)
          : String(45 * 60 * 1000),
      },
    });
  };

  const handleStartSession = async (groupId: string) => {
    const group = groups.find((g) => g.id === groupId);
    const prev = groups;
    setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: true }));
    try {
      const res = await communityApi.startGroupSession(groupId, "audio");
      if (res?.data) {
        setGroups((g) =>
          g.map((gr) =>
            gr.id === groupId
              ? { ...gr, isLive: true, activeSession: res.data }
              : gr,
          ),
        );
        openCall(res.data, group?.name || "");
      }
    } catch (err: any) {
      setGroups(prev);
      Alert.alert(
        "Could not start session",
        err?.message || "Please try again.",
      );
    } finally {
      setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: false }));
    }
  };

  const handleJoinSession = async (groupId: string, accessCode?: string) => {
    const group = groups.find((g) => g.id === groupId);
    setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: true }));
    try {
      const res = await communityApi.joinGroupSession(groupId, accessCode);
      if (res?.data) {
        setGroups((g) =>
          g.map((gr) =>
            gr.id === groupId
              ? { ...gr, isLive: true, activeSession: res.data }
              : gr,
          ),
        );
        openCall(res.data, group?.name || "");
      }
    } catch (err: any) {
      Alert.alert(
        "Could not join",
        err?.message || "The session may have ended.",
      );
    } finally {
      setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: false }));
    }
  };

  const handleEndSession = async (groupId: string) => {
    const prev = groups;
    setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: true }));
    try {
      const res = await communityApi.endGroupSession(groupId);
      if (res?.success) {
        setGroups((g) =>
          g.map((gr) =>
            gr.id === groupId
              ? { ...gr, isLive: false, activeSession: null }
              : gr,
          ),
        );
      }
    } catch {
      setGroups(prev);
      Alert.alert("Error", "Failed to end the session. Please try again.");
    } finally {
      setLoadingItems((l) => ({ ...l, [`session_${groupId}`]: false }));
    }
  };

  const handleJoinByCode = () => {
    setShowJoinByCode(true);
  };

  const handlePray = async (requestId: string) => {
    const prev = requests;
    setRequests((r) =>
      r.map((rq) =>
        rq.id === requestId
          ? {
              ...rq,
              prayedByMe: !rq.prayedByMe,
              prayCount: rq.prayedByMe ? rq.prayCount - 1 : rq.prayCount + 1,
            }
          : rq,
      ),
    );
    try {
      const res = await communityApi.prayForRequest(requestId);
      if (res?.data) {
        setRequests((r) =>
          r.map((rq) =>
            rq.id === requestId
              ? {
                  ...rq,
                  prayCount: res.data.prayCount,
                  prayedByMe: res.data.prayedByMe,
                }
              : rq,
          ),
        );
      }
    } catch {
      setRequests(prev);
      Alert.alert("Error", "Failed to record prayer. Please try again.");
    }
  };

  const handleEditItem = (
    type: "skill" | "event" | "group" | "request" | "job",
    data: any,
  ) => {
    if (type === "request") {
      setPrayerReqEditing(data as PrayerRequest);
      setPrayerReqVisible(true);
      return;
    }
    setEditingItem({ type, data });
    setCreateType(type);
    setShowCreateModal(true);
  };

  const handleDeleteItem = (
    type: "skill" | "event" | "group" | "request" | "job",
    id: string,
    title: string,
  ) => {
    const labels: Record<string, string> = {
      skill: "Skill",
      event: "Event",
      group: "Group",
      request: "Prayer Request",
      job: "Job",
    };
    Alert.alert(`Delete ${labels[type]}`, `Delete "${title}"?`, [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          setLoadingItems((prev) => ({ ...prev, [`delete_${id}`]: true }));
          try {
            if (type === "skill") {
              await communityApi.deleteSkill(id);
              setSkills((prev) => prev.filter((s) => s.id !== id));
            } else if (type === "event") {
              await communityApi.deleteEvent(id);
              setEvents((prev) => prev.filter((e) => e.id !== id));
            } else if (type === "group") {
              await communityApi.deleteGroup(id);
              setGroups((prev) => prev.filter((g) => g.id !== id));
            } else if (type === "request") {
              await communityApi.deleteRequest(id);
              setRequests((prev) => prev.filter((r) => r.id !== id));
            } else if (type === "job") {
              await communityApi.deleteJob(id);
              setJobs((prev) => prev.filter((j) => j.id !== id));
            }
          } catch {
            Alert.alert(
              "Error",
              `Failed to delete ${labels[type].toLowerCase()}.`,
            );
          } finally {
            setLoadingItems((prev) => ({ ...prev, [`delete_${id}`]: false }));
          }
        },
      },
    ]);
  };

  const handleSubmitFromModal = () => {
    refreshData(true);
    setEditingItem(null);
  };

  const sectionPillTitle =
    tab === "skills"
      ? filter === "jobs"
        ? "Jobs"
        : filter === "offering"
          ? "Offer Skills"
          : filter === "seeking"
            ? "Seek Skills"
            : "All Skills"
      : TAB_META[tab].title;

  const sectionSubtitle =
    tab === "skills"
      ? filter === "jobs"
        ? "Opportunities to serve"
        : filter === "offering"
          ? "Offer your gifts to others"
          : filter === "seeking"
            ? "Find people offering help"
            : "Browse every skill shared"
      : TAB_META[tab].sub;

  const handleHeaderAdd = () => {
    if (tab === "skills") {
      setEditingItem(null);
      setCreateType(filter === "jobs" ? "job" : "skill");
      setShowCreateModal(true);
    } else if (tab === "social") {
      if (currentUserRole !== "admin") return;
      setEditingItem(null);
      setCreateType("event");
      setShowCreateModal(true);
    } else if (tab === "groups") {
      if (currentUserRole !== "admin") {
        Alert.alert(
          "Admins only",
          "Only admins can create groups now. Ask a Relate admin to set one up.",
        );
        return;
      }
      setEditingItem(null);
      setCreateType("group");
      setShowCreateModal(true);
    } else if (tab === "spiritual") {
      setPrayerReqEditing(null);
      setPrayerReqVisible(true);
    }
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <StatusBar style="dark" />
        <LinearGradient
          colors={[colors.bg, colors.white]}
          start={{ x: 0, y: 0 }}
          end={{ x: 0, y: 1 }}
          style={styles.bgGradient}
        >
          {showLanding ? (
            <CommunityLanding />
          ) : (
            <>
              {/* Header: hamburger menu replaces the old Skills / Social / Spiritual tabs */}
              <View style={styles.headerContainer}>
                <TouchableOpacity
                  style={styles.backToClubs}
                  onPress={() => {
                    router.replace("/(tabs)/community");
                    setOnLanding(true);
                  }}
                  activeOpacity={0.8}
                  accessibilityLabel="Back to clubs"
                >
                  <Ionicons
                    name="chevron-back"
                    size={16}
                    color={colors.goldDark}
                  />
                  <Text style={styles.backToClubsText}>All clubs</Text>
                </TouchableOpacity>
                <View style={styles.headerTopRow}>
                  <View>
                    <Text style={styles.headerEyebrow}>CONNECT &amp; GROW</Text>
                  </View>
                  {tab !== "social" || currentUserRole === "admin" ? (
                    <TouchableOpacity
                      style={styles.headerAddBtn}
                      onPress={handleHeaderAdd}
                      activeOpacity={0.8}
                      accessibilityLabel="Add"
                    >
                      <GradientBox
                        gradient="darkGreen"
                        style={styles.headerAddGradient}
                      >
                        <Ionicons name="add" size={24} color={colors.white} />
                      </GradientBox>
                    </TouchableOpacity>
                  ) : null}
                </View>

                <TouchableOpacity
                  style={styles.sectionSwitch}
                  onPress={() => setMenuOpen(true)}
                  activeOpacity={0.8}
                  accessibilityLabel="Change section"
                >
                  <Text style={styles.sectionSwitchText}>
                    {sectionPillTitle}
                  </Text>
                  <Ionicons
                    name="chevron-down"
                    size={15}
                    color={colors.goldDark}
                  />
                </TouchableOpacity>

                <Text style={styles.headerSubtitle}>{sectionSubtitle}</Text>
              </View>

              {loading ? (
                <>
                  {tab === "skills" && (
                    <SkeletonList count={3} CardSkeleton={SkillCardSkeleton} />
                  )}
                  {tab === "social" && (
                    <SkeletonList count={3} CardSkeleton={EventCardSkeleton} />
                  )}
                  {(tab === "groups" || tab === "spiritual") && (
                    <SkeletonList count={3} CardSkeleton={GroupCardSkeleton} />
                  )}
                </>
              ) : (
                <>
                  {tab === "skills" && (
                    <SkillsTab
                      skills={skills}
                      jobs={jobs}
                      filter={filter}
                      onOpenCreate={(type) => {
                        setEditingItem(null);
                        setCreateType(type);
                        setShowCreateModal(true);
                      }}
                      onConnect={handleConnectSkill}
                      onApply={handleApply}
                      onEditItem={handleEditItem}
                      onDeleteItem={handleDeleteItem}
                      refreshing={refreshing}
                      onRefresh={() => refreshData(true)}
                      loadingItems={loadingItems}
                    />
                  )}
                  {tab === "social" && (
                    <SocialTab
                      events={events}
                      openEventId={openEventId}
                      onClearOpenEvent={() =>
                        router.setParams({ event: undefined })
                      }
                      canCreateEvents={currentUserRole === "admin"}
                      onOpenCreate={() => {
                        setEditingItem(null);
                        setCreateType("event");
                        setShowCreateModal(true);
                      }}
                      onRsvp={handleRsvp}
                      onToggleSave={handleToggleSave}
                      onEditItem={handleEditItem}
                      onDeleteItem={handleDeleteItem}
                      refreshing={refreshing}
                      onRefresh={() => refreshData(true)}
                      loadingItems={loadingItems}
                      isAuthed={!!currentUserId}
                      currentUserId={currentUserId}
                      sessionLoading={sessionLoading}
                      onRequireAuth={requireAuth}
                    />
                  )}
                  {(tab === "groups" || tab === "spiritual") && (
                    <SpiritualTab
                      groups={tab === "groups" ? groups : []}
                      requests={tab === "spiritual" ? requests : []}
                      section={tab === "groups" ? "groups" : "requests"}
                      onOpenCreate={(type) => {
                        if (type === "request") {
                          setPrayerReqEditing(null);
                          setPrayerReqVisible(true);
                          return;
                        }
                        setEditingItem(null);
                        setCreateType(type);
                        setShowCreateModal(true);
                      }}
                      onJoinGroup={handleJoinGroup}
                      onStartSession={handleStartSession}
                      onJoinSession={handleJoinSession}
                      onEndSession={handleEndSession}
                      onOpenSession={openCall}
                      onJoinByCode={handleJoinByCode}
                      onPray={handlePray}
                      onEditItem={handleEditItem}
                      onDeleteItem={handleDeleteItem}
                      refreshing={refreshing}
                      onRefresh={() => refreshData(true)}
                      loadingItems={loadingItems}
                      onCommentAdded={(requestId) =>
                        setRequests((prev) =>
                          prev.map((r) =>
                            r.id === requestId
                              ? {
                                  ...r,
                                  commentCount: (r.commentCount || 0) + 1,
                                }
                              : r,
                          ),
                        )
                      }
                      onCommentRemoved={(requestId) =>
                        setRequests((prev) =>
                          prev.map((r) =>
                            r.id === requestId
                              ? {
                                  ...r,
                                  commentCount: Math.max(
                                    0,
                                    (r.commentCount || 0) - 1,
                                  ),
                                }
                              : r,
                          ),
                        )
                      }
                      onGroupCommentAdded={(groupId) =>
                        setGroups((prev) =>
                          prev.map((g) =>
                            g.id === groupId
                              ? {
                                  ...g,
                                  commentCount: (g.commentCount || 0) + 1,
                                }
                              : g,
                          ),
                        )
                      }
                      onGroupCommentRemoved={(groupId) =>
                        setGroups((prev) =>
                          prev.map((g) =>
                            g.id === groupId
                              ? {
                                  ...g,
                                  commentCount: Math.max(
                                    0,
                                    (g.commentCount || 0) - 1,
                                  ),
                                }
                              : g,
                          ),
                        )
                      }
                    />
                  )}
                </>
              )}
            </>
          )}

          <CreateModal
            visible={showCreateModal}
            type={createType}
            editingItem={editingItem}
            onClose={() => {
              setShowCreateModal(false);
              setCreateType(null);
              setEditingItem(null);
            }}
            onSubmit={handleSubmitFromModal}
          />

          <JoinByCodeModal
            visible={showJoinByCode}
            onClose={() => setShowJoinByCode(false)}
            onJoin={async (code) => {
              try {
                await communityApi.joinGroupByCode(code.trim());
                setShowJoinByCode(false);
                refreshData(true);
                return null;
              } catch (err: any) {
                return err?.message || "Check the code and try again.";
              }
            }}
          />

          {prayerReqVisible && (
            <PrayerRequestModal
              editing={prayerReqEditing}
              onClose={() => {
                setPrayerReqVisible(false);
                setPrayerReqEditing(null);
              }}
              onSubmit={() => {
                setPrayerReqEditing(null);
                refreshData(true);
              }}
            />
          )}
        </LinearGradient>
      </SafeAreaView>
      <CommunityMenuDrawer
        open={menuOpen}
        onClose={() => setMenuOpen(false)}
        activeTab={tab}
        activeSub={tab === "skills" ? filter : null}
        onSelectTab={(t, sub) => {
          setMenuOpen(false);
          setOnLanding(false);
          const tabChanged = t !== tab;
          // Only show a loading state when actually switching tabs. Switching
          // a skills filter within the current tab reuses the skills+jobs data
          // that was already fetched together, so setting loading=true here
          // would leave the skeleton stuck — nothing else clears it because
          // the tab itself didn't change.
          if (tabChanged) setLoading(true);
          setTab(t);
          if (
            t === "skills" &&
            (sub === "all" ||
              sub === "offering" ||
              sub === "seeking" ||
              sub === "jobs")
          ) {
            setFilter(sub);
          }
        }}
      />
    </SafeAreaProvider>
  );
}

