/* ─────────────── SKILLS TAB ─────────────── */
function SkillsTab({
  skills,
  jobs,
  filter,
  onOpenCreate,
  onConnect,
  onApply,
  onEditItem,
  onDeleteItem,
  refreshing,
  onRefresh,
  loadingItems,
}: {
  skills: SkillListing[];
  jobs: JobListing[];
  filter: "all" | "offering" | "seeking" | "jobs";
  onOpenCreate: (type: "skill" | "job") => void;
  onConnect: (id: string) => void;
  onApply: (id: string) => void;
  onEditItem: (
    type: "skill" | "event" | "group" | "request" | "job",
    data: any,
  ) => void;
  onDeleteItem: (
    type: "skill" | "event" | "group" | "request" | "job",
    id: string,
    title: string,
  ) => void;
  refreshing: boolean;
  onRefresh: () => void;
  loadingItems: Record<string, boolean>;
}) {
  const [search, setSearch] = useState("");

  const filtered = skills.filter((s) => {
    if (filter === "offering" && !s.offering) return false;
    if (filter === "seeking" && s.offering) return false;
    if (filter === "jobs") return false;
    if (search) {
      const q = search.toLowerCase();
      return (
        s.title.toLowerCase().includes(q) ||
        s.category.toLowerCase().includes(q) ||
        s.author.toLowerCase().includes(q)
      );
    }
    return true;
  });

  const filteredJobs = jobs.filter((j) => {
    if (filter !== "jobs") return false;
    if (search) {
      const q = search.toLowerCase();
      return (
        j.title.toLowerCase().includes(q) ||
        j.company.toLowerCase().includes(q) ||
        j.category.toLowerCase().includes(q)
      );
    }
    return true;
  });

  const isJobsActive = filter === "jobs";

  // Empty-state copy follows the active dropdown filter / search so the
  // message always matches what the user is looking at.
  const skillsEmpty = search
    ? {
        icon: "search-outline",
        eyebrow: "Skills",
        title: `No results for "${search}"`,
        subtitle: "Try a different search or filter",
      }
    : filter === "offering"
      ? {
          icon: "hand-right-outline",
          eyebrow: "Offer Skills",
          title: "No skills offered yet",
          subtitle: "Be the first to offer your skills to the community",
        }
      : filter === "seeking"
        ? {
            icon: "hand-right-outline",
            eyebrow: "Seek Skills",
            title: "Nothing being sought yet",
            subtitle: "Share what you'd like to learn or find help with",
          }
        : {
            icon: "hand-right-outline",
            eyebrow: "Skills",
            title: "No skills shared yet",
            subtitle: "Be the first to share a skill with the community",
          };
  const jobsEmpty = search
    ? {
        icon: "search-outline",
        eyebrow: "Jobs",
        title: `No results for "${search}"`,
        subtitle: "Try a different search",
      }
    : {
        icon: "briefcase-outline",
        eyebrow: "Jobs",
        title: "No jobs listed yet",
        subtitle: "Be the first to post a job opportunity!",
      };

  return (
    <>
      <View style={styles.searchContainer}>
        <View style={styles.searchIconWrap}>
          <Ionicons name="search-outline" size={18} color={colors.muted} />
        </View>
        <TextInput
          style={styles.searchInput}
          placeholder={isJobsActive ? "Search jobs..." : "Search skills..."}
          placeholderTextColor={colors.muted}
          value={search}
          onChangeText={setSearch}
        />
        {search ? (
          <TouchableOpacity
            onPress={() => setSearch("")}
            style={styles.searchClearBtn}
          >
            <Ionicons name="close-circle" size={18} color={colors.muted} />
          </TouchableOpacity>
        ) : null}
      </View>

      {isJobsActive ? (
        <FlashList
          data={filteredJobs}
          keyExtractor={(item) => item.id}
          contentContainerStyle={styles.list}
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              tintColor={colors.forest}
            />
          }
          renderItem={({ item }) => (
            <JobCard
              item={item}
              onApply={onApply}
              loading={loadingItems[`apply_${item.id}`]}
              onEdit={() => onEditItem("job", item)}
              onDelete={() => onDeleteItem("job", item.id, item.title)}
              deleteLoading={loadingItems[`delete_${item.id}`]}
            />
          )}
          ListEmptyComponent={<EmptyState color={colors.gold} {...jobsEmpty} />}
        />
      ) : (
        <FlashList
          data={filtered}
          keyExtractor={(item) => item.id}
          contentContainerStyle={styles.list}
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              tintColor={colors.forest}
            />
          }
          renderItem={({ item }) => (
            <SkillCard
              item={item}
              onConnect={onConnect}
              loading={loadingItems[`connect_${item.id}`]}
              onEdit={() => onEditItem("skill", item)}
              onDelete={() => onDeleteItem("skill", item.id, item.title)}
              deleteLoading={loadingItems[`delete_${item.id}`]}
            />
          )}
          ListEmptyComponent={
            <EmptyState color={colors.gold} {...skillsEmpty} />
          }
        />
      )}
    </>
  );
}

