function SaveBurst({ onDone }: { onDone?: () => void }) {
  const [parts] = useState(() =>
    Array.from({ length: 8 }, (_, i) => {
      const angle = (i / 8) * Math.PI * 2 + (Math.random() * 0.4 - 0.2);
      const dist = 30 + Math.random() * 22;
      return {
        angle,
        dist,
        char: "♥✦★+●"[Math.floor(Math.random() * 5)],
        anim: new Animated.Value(0),
      };
    }),
  );

  useEffect(() => {
    const anims = parts.map((p) =>
      Animated.timing(p.anim, {
        toValue: 1,
        duration: 600 + Math.random() * 250,
        useNativeDriver: true,
      }),
    );
    Animated.parallel(anims).start(({ finished }) => {
      if (finished) onDone?.();
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <View pointerEvents="none" style={StyleSheet.absoluteFill}>
      {parts.map((p, i) => (
        <Animated.Text
          key={i}
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            color: colors.gold,
            fontSize: 14,
            opacity: p.anim.interpolate({
              inputRange: [0, 0.2, 1],
              outputRange: [0, 1, 0],
            }),
            transform: [
              {
                translateX: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, Math.cos(p.angle) * p.dist],
                }),
              },
              {
                translateY: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, Math.sin(p.angle) * p.dist - 12],
                }),
              },
              {
                scale: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0.4, 1.2],
                }),
              },
            ],
          }}
        >
          {p.char}
        </Animated.Text>
      ))}
    </View>
  );
}

