        setDescription(e.description);
        setLocation(e.location);
        setFee(e.fee !== "Free" ? e.fee : "");
        setImageUrl(e.imageUrl);
        setDateObj(parseDateInput(e.date));
        setTimeObj(parseTimeToDate(e.time));
        setDateToObj(parseDateInput(e.dateTo));
        setTimeToObj(parseTimeToDate(e.timeTo));
        setAgenda(Array.isArray(e.agenda) ? e.agenda : []);
        setNotes(e.notes || "");
        setCategory(e.category || "");
        setEyebrow(e.eyebrow || "");
