import { cachedFetch, type CachedFetchOptions } from "./cache";

export const ASSET_CATEGORIES = [
  "Computer",
  "Mobile phone",
  "Tablet",
  "Printer",
  "Audio & visual",
  "Furniture",
  "Vehicle",
  "Tools",
  "Other",
] as const;

export type AssetCategory = (typeof ASSET_CATEGORIES)[number];

export type Asset = {
  _id: string;
  name: string;
  category: string;
  description: string;
  year: number | null;
  model: string;
  serialNumber: string;
  createdByName: string | null;
  createdAt: string | null;
  updatedAt: string | null;
};

export type AssetInput = {
  name: string;
  category: string;
  description: string;
  year: number | null;
  model: string;
  serialNumber: string;
};

function apiFetch<T>(path: string, options: CachedFetchOptions = {}): Promise<T> {
  return cachedFetch<T>(path, options, ["/api/assets"]);
}

export const assetsApi = {
  list: () => apiFetch<{ data: Asset[] }>("/api/assets", { cacheTtl: 0 }),

  create: (input: AssetInput) =>
    apiFetch<{ data: Asset }>("/api/assets", {
      method: "POST",
      body: JSON.stringify(input),
    }),

  update: (id: string, input: AssetInput) =>
    apiFetch<{ data: Asset }>("/api/assets", {
      method: "PUT",
      body: JSON.stringify({ ...input, id }),
    }),

  remove: (id: string) =>
    apiFetch<{ success: boolean }>("/api/assets", {
      method: "DELETE",
      body: JSON.stringify({ id }),
    }),
};