import { type SQLiteDatabase } from "expo-sqlite";
import { appStorage } from "./app-storage";
import { getLocalDb } from "./prayer-preferences";
import {
  getNotificationsEnabled,
  scheduleAllPrayerNotifications,
  scheduleVerseReminderNotifications,
  type PrayerNotificationInfo,
} from "./notifications";
import { rescheduleReadingReminder } from "./reading-reminder";
import { syncNotificationPreferences } from "./notification-settings";

/**
 * Multi-day prayer notification scheduling.
 *
 * Schedules SCHEDULE_DAYS days of prayer notifications at once so prayers
 * fire even when the user never opens the app, and rebuilds the window only
 * when something significant changes — a big location move, a timezone
 * change, a preference change, or a window about to expire. Ordinary app
 * opens, focus events and day rollovers are deliberately NOT reasons to
 * reschedule (the window already covers them).
 */

/** How many days of prayer notifications are scheduled ahead. */
const SCHEDULE_DAYS = 8;
/** A move bigger than this counts as a significant location change. */
const SIGNIFICANT_MOVE_KM = 5;
/** Rebuild when the window no longer covers at least one full day. */
const WINDOW_EXPIRY_MS = 24 * 60 * 60 * 1000;
const META_KEY = "prayer_schedule_meta_v1";
const LOCATION_KEY = "last_location_v1";
const SESSION_KEY = "prayer_app_session_data";
const DEFAULT_LAT = -25.7;
const DEFAULT_LNG = 28.2;

type ScheduledPrayer = { name: string; title: string; date: Date };

type StoredCustom = {
  id: string;
  name: string;
  time: string;
  enabled?: boolean;
};

type PrayerPrefs = {
  disabled: string[];
  customs: StoredCustom[];
  advanceMinutes: number;
};

export type PrayerScheduleMeta = {
  lat: number;
  lng: number;
  /** `Date.getTimezoneOffset()` at schedule time — catches travel across zones. */
  tzOffset: number;
  prefsSig: string;
  /** End of the last scheduled day (epoch ms). */
  windowEnd: number;
  count: number;
  scheduledAt: number;
};

type RescheduleReason =
  | "first-install"
  | "location"
  | "timezone"
  | "preferences"
  | "window-expiring"
  | "forced";

export type MaybeRescheduleResult = {
  action: "skipped" | "scheduled" | "disabled";
  reason?: RescheduleReason | "error";
  count?: number;
};

export type SunTimes = { sunrise: Date; noon: Date; sunset: Date };

// ── Preferences ─────────────────────────────────────────────────────────

// prayer_preferences exists in two historical shapes: legacy key/value rows
// (user_id, key, value) and the single-row layout created by migrateDb on
// fresh installs. Read whichever the installed schema actually has.
function readPrayerPrefs(db: SQLiteDatabase): PrayerPrefs {
  const prefs: PrayerPrefs = { disabled: [], customs: [], advanceMinutes: 10 };

  let keyValuePairSchema = false;
  try {
    db.getAllSync(
      `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'disabled'`,
    );
    keyValuePairSchema = true;
  } catch {}

  if (keyValuePairSchema) {
    try {
      const rows = db.getAllSync<{ value: string }>(
        `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'disabled'`,
      );
      if (rows[0]) prefs.disabled = JSON.parse(rows[0].value);
    } catch {}
    try {
      const rows = db.getAllSync<{ value: string }>(
        `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'custom'`,
      );
      if (rows[0]) prefs.customs = JSON.parse(rows[0].value);
    } catch {}
    try {
      const rows = db.getAllSync<{ value: string }>(
        `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'advance_minutes'`,
      );
      if (rows[0]) {
        const n = parseInt(rows[0].value, 10);
        if ([0, 5, 10, 15].includes(n)) prefs.advanceMinutes = n;
      }
    } catch {}
  } else {
    try {
      const row = db.getFirstSync<{
        disabled_prayers: string;
        custom_prayers: string;
        advance_minutes: number;
      }>(
        `SELECT disabled_prayers, custom_prayers, advance_minutes FROM prayer_preferences WHERE id = 1`,
      );
      if (row) {
        try {
          prefs.disabled = JSON.parse(row.disabled_prayers || "[]");
        } catch {}
        try {
          prefs.customs = JSON.parse(row.custom_prayers || "[]");
        } catch {}
        if ([0, 5, 10, 15].includes(row.advance_minutes)) {
          prefs.advanceMinutes = row.advance_minutes;
        }
      }
    } catch {}
  }

  return prefs;
}

/** Stable fingerprint of everything that changes the notification window. */
function prefsSignature(prefs: PrayerPrefs): string {
  return JSON.stringify({
    v: 1,
    d: [...prefs.disabled].sort(),
    c: prefs.customs
      .map((c) => `${c.id}|${c.time}|${c.enabled === false ? 0 : 1}`)
      .sort(),
    a: prefs.advanceMinutes,
  });
}

// ── Sun times ───────────────────────────────────────────────────────────

function localDayKey(d: Date): string {
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

function round3(n: number): number {
  return Math.round(n * 1000) / 1000;
}

function fallbackSun(base: Date): SunTimes {
  const sunrise = new Date(base);
  sunrise.setHours(6, 15, 0, 0);
  const noon = new Date(base);
  noon.setHours(12, 0, 0, 0);
  const sunset = new Date(base);
  sunset.setHours(18, 30, 0, 0);
  return { sunrise, noon, sunset };
}

/**
 * Sunrise/sunset/solar-noon for one day — cached in SQLite per location and
 * date, so opening the app again (even on the welcome screen) paints from
 * the previous fetch instead of hitting the API. `forceRefresh` skips the
 * stored row for a deliberate pull-to-refresh.
 */
export async function getSunTimes(
  db: SQLiteDatabase,
  lat: number,
  lng: number,
  base: Date,
  forceRefresh = false,
): Promise<SunTimes> {
  const key = localDayKey(base);
  const latR = round3(lat);
  const lngR = round3(lng);

  if (!forceRefresh) {
    try {
      const row = db.getFirstSync<{
        sunrise: string;
        sunset: string;
        solar_noon: string;
      }>(
        `SELECT sunrise, sunset, solar_noon FROM sunrise_cache WHERE date = ? AND lat = ? AND lng = ?`,
        [key, latR, lngR],
      );
      if (row) {
        return {
          sunrise: new Date(row.sunrise),
          noon: new Date(row.solar_noon),
          sunset: new Date(row.sunset),
        };
      }
    } catch {}
  }

  try {
    const res = await fetch(
      `https://api.sunrise-sunset.org/json?lat=${latR}&lng=${lngR}&date=${key}&formatted=0`,
    );
    const data = await res.json();
    const r = data?.results;
    if (
      data?.status === "OK" &&
      r?.sunrise &&
      r?.solar_noon &&
      r?.sunset &&
      typeof r.sunrise === "string"
    ) {
      try {
        db.runSync(
          `DELETE FROM sunrise_cache WHERE date = ? AND lat = ? AND lng = ?`,
          [key, latR, lngR],
        );
        db.runSync(
          `INSERT INTO sunrise_cache (lat, lng, sunrise, sunset, solar_noon, date) VALUES (?, ?, ?, ?, ?, ?)`,
          [latR, lngR, r.sunrise, r.sunset, r.solar_noon, key],
        );
        db.runSync(`DELETE FROM sunrise_cache WHERE date < date('now', '-14 days')`);
      } catch {}
      return {
        sunrise: new Date(r.sunrise),
        noon: new Date(r.solar_noon),
        sunset: new Date(r.sunset),
      };
    }
  } catch {}

  return fallbackSun(base);
}

// ── Window builder ──────────────────────────────────────────────────────

function prayersForDay(sun: SunTimes, base: Date): ScheduledPrayer[] {
  const mins = (d: Date) => d.getHours() * 60 + d.getMinutes();
  const sunriseM = mins(sun.sunrise);
  const noonM = mins(sun.noon);
  const sunsetM = mins(sun.sunset);

  const raw = [
    { name: "dawn", title: "Dawn", m: sunriseM - 90 },
    { name: "sunrise", title: "Sunrise", m: sunriseM },
    { name: "noon", title: "Noon", m: noonM },
    { name: "afternoon", title: "Afternoon", m: Math.floor((noonM + sunsetM) / 2) },
    { name: "sunset", title: "Sunset", m: sunsetM },
    { name: "evening", title: "Evening", m: sunsetM + 90 },
  ];

  return raw.map((p) => {
    const d = new Date(base);
    d.setHours(Math.floor(p.m / 60), p.m % 60, 0, 0);
    return { name: p.name, title: p.title, date: d };
  });
}

function customsForDay(prefs: PrayerPrefs, base: Date): ScheduledPrayer[] {
  const out: ScheduledPrayer[] = [];
  for (const c of prefs.customs) {
    if (!c || typeof c.id !== "string" || c.enabled === false) continue;
    if (typeof c.time !== "string") continue;
    const [h, m] = c.time.split(":").map(Number);
    if (Number.isNaN(h) || Number.isNaN(m)) continue;
    const d = new Date(base);
    d.setHours(h, m, 0, 0);
    out.push({ name: `custom-${c.id}`, title: c.name || "Prayer", date: d });
  }
  return out;
}

/** Built-in + custom prayers for the next SCHEDULE_DAYS days, soonest first. */
async function buildPrayerWindow(
  lat: number,
  lng: number,
  now: Date,
  prefs: PrayerPrefs,
): Promise<ScheduledPrayer[]> {
  const db = getLocalDb();
  const list: ScheduledPrayer[] = [];
  for (let d = 0; d < SCHEDULE_DAYS; d++) {
    const base = new Date(now);
    base.setHours(0, 0, 0, 0);
    base.setDate(base.getDate() + d);
    const sun = await getSunTimes(db, lat, lng, base);
    for (const p of prayersForDay(sun, base)) {
      if (prefs.disabled.includes(p.name)) continue;
      list.push(p);
    }
    list.push(...customsForDay(prefs, base));
  }

  const nowMs = now.getTime();
  return list
    .filter((p) => p.date.getTime() > nowMs)
    .sort((a, b) => a.date.getTime() - b.date.getTime());
}

// ── Change detection ────────────────────────────────────────────────────

async function resolveLocation(
  lat?: number,
  lng?: number,
): Promise<{ lat: number; lng: number }> {
  if (typeof lat === "number" && typeof lng === "number") return { lat, lng };
  try {
    const raw = await appStorage.getItemAsync(LOCATION_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (typeof parsed?.lat === "number" && typeof parsed?.lng === "number") {
        return { lat: parsed.lat, lng: parsed.lng };
      }
    }
  } catch {}
  return { lat: DEFAULT_LAT, lng: DEFAULT_LNG };
}

async function readMeta(): Promise<PrayerScheduleMeta | null> {
  try {
    const raw = await appStorage.getItemAsync(META_KEY);
    if (raw) return JSON.parse(raw);
  } catch {}
  return null;
}

async function writeMeta(meta: PrayerScheduleMeta): Promise<void> {
  try {
    await appStorage.setItemAsync(META_KEY, JSON.stringify(meta));
  } catch {}
}

async function readUserName(): Promise<string> {
  try {
    const raw = await appStorage.getItemAsync(SESSION_KEY);
    if (raw) {
      const name = (JSON.parse(raw)?.user?.name || "").split(" ")[0];
      return name || "";
    }
  } catch {}
  return "";
}

function distanceKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const toRad = (v: number) => (v * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.min(1, Math.sqrt(a)));
}

function changeReason(
  meta: PrayerScheduleMeta,
  loc: { lat: number; lng: number },
  sig: string,
  now: Date,
): RescheduleReason | null {
  if (meta.tzOffset !== now.getTimezoneOffset()) return "timezone";
  if (distanceKm(meta.lat, meta.lng, loc.lat, loc.lng) > SIGNIFICANT_MOVE_KM) {
    return "location";
  }
  if (meta.prefsSig !== sig) return "preferences";
  if (meta.windowEnd - now.getTime() < WINDOW_EXPIRY_MS) return "window-expiring";
  return null;
}

// ── Entry point ─────────────────────────────────────────────────────────

async function runMaybeReschedule(opts: {
  force?: boolean;
  lat?: number;
  lng?: number;
}): Promise<MaybeRescheduleResult> {
  try {
    const enabled = await getNotificationsEnabled();
    if (!enabled) return { action: "disabled" };

    const now = new Date();
    const loc = await resolveLocation(opts.lat, opts.lng);

    const prefs = readPrayerPrefs(getLocalDb());
    const sig = prefsSignature(prefs);

    const meta = await readMeta();
    const reason: RescheduleReason | null = opts.force
      ? "forced"
      : meta
        ? changeReason(meta, loc, sig, now)
        : "first-install";
    if (!reason) return { action: "skipped" };

    await syncNotificationPreferences({
      enabled,
      lat: loc.lat,
      lng: loc.lng,
      tzOffset: now.getTimezoneOffset(),
    });

    const list = await buildPrayerWindow(loc.lat, loc.lng, now, prefs);
    const ids = await scheduleAllPrayerNotifications(
      list as PrayerNotificationInfo[],
      prefs.advanceMinutes,
      await readUserName(),
    );
    // scheduleAll cancels every scheduled notification — restore the daily
    // reading reminder and verse-of-the-day reminders it wiped.
    await rescheduleReadingReminder();
    await scheduleVerseReminderNotifications();

    const windowEnd = new Date(now);
    windowEnd.setHours(0, 0, 0, 0);
    windowEnd.setDate(windowEnd.getDate() + (SCHEDULE_DAYS - 1));
    windowEnd.setHours(23, 59, 59, 999);
    await writeMeta({
      lat: loc.lat,
      lng: loc.lng,
      tzOffset: now.getTimezoneOffset(),
      prefsSig: sig,
      windowEnd: windowEnd.getTime(),
      count: ids.length,
      scheduledAt: now.getTime(),
    });

    return { action: "scheduled", reason, count: ids.length };
  } catch (err) {
    console.warn("prayer schedule: reschedule failed", err);
    return { action: "skipped", reason: "error" };
  }
}

// Home fires this from mount, focus and AppState resume — serialize so two
// overlapping runs can't cancel each other's notifications.
let queue: Promise<unknown> = Promise.resolve();

/**
 * Rebuilds the SCHEDULE_DAYS-day prayer notification window when needed and
 * skips when the existing window is still valid. Never throws.
 */
export function maybeReschedulePrayerNotifications(
  opts: { force?: boolean; lat?: number; lng?: number } = {},
): Promise<MaybeRescheduleResult> {
  const run = queue.then(() => runMaybeReschedule(opts));
  queue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}
