type PrayerEntry = {
  id: number;
  title: string;
  icon: string;
  date: Date;
  time: string;
  past: boolean;
  prayerKey: PrayerKey | string;
  isCustom?: boolean;
  message?: string;
};

function mins(date: Date) {
  return date.getHours() * 60 + date.getMinutes();
}

function dateFromMins(m: number, now: Date) {
  const d = new Date(now);
  d.setHours(Math.floor(m / 60), m % 60, 0, 0);
  return d;
}

function buildPrayerTimes(
  sunrise: Date,
  noon: Date,
  sunset: Date,
  now: Date,
): PrayerEntry[] {
  const sunriseM = mins(sunrise);
  const noonM = mins(noon);
  const sunsetM = mins(sunset);

  const dawnM = sunriseM - 90;
  const afternoonM = Math.floor((noonM + sunsetM) / 2);
  const eveningM = sunsetM + 90;

  const raw: {
    id: number;
    title: string;
    icon: string;
    m: number;
    prayerKey: PrayerKey;
  }[] = [
    { id: 1, title: "Dawn", icon: "moon-outline", m: dawnM, prayerKey: "dawn" },
    {
      id: 2,
      title: "Sunrise",
      icon: "sunny-outline",
      m: sunriseM,
      prayerKey: "sunrise",
    },
    { id: 3, title: "Noon", icon: "sunny", m: noonM, prayerKey: "noon" },
    {
      id: 4,
      title: "Afternoon",
      icon: "partly-sunny-outline",
      m: afternoonM,
      prayerKey: "afternoon",
    },
    {
      id: 5,
      title: "Sunset",
      icon: "cloudy-night-outline",
      m: sunsetM,
      prayerKey: "sunset",
    },
    {
      id: 6,
      title: "Evening",
      icon: "moon",
      m: eveningM,
      prayerKey: "evening",
    },
  ];

  return raw.map((p) => {
    const d = dateFromMins(p.m, now);
    return {
      ...p,
      date: d,
      time: d.toLocaleTimeString("en-GB", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      past: d < now,
    };
  });
}

function getNextPrayer(times: PrayerEntry[]) {
  if (times.length === 0) return null;
  const now = new Date();
  const upcoming = times.find((p) => p.date > now);
  if (upcoming) return upcoming;
  const tomorrow = new Date(times[0].date);
  tomorrow.setDate(tomorrow.getDate() + 1);
  return { ...times[0], date: tomorrow, past: false as const };
}

function calcRemaining(target: Date) {
  const diff = target.getTime() - Date.now();
  if (diff <= 0) return { hours: 0, minutes: 0, seconds: 0 };
  return {
    hours: Math.floor(diff / 3600000),
    minutes: Math.floor((diff % 3600000) / 60000),
    seconds: Math.floor((diff % 60000) / 1000),
  };
}

