/* ── Location cache ─────────────────────────────────────────────
   Remembers the last known coordinates so the home screen can paint
   prayer times instantly on launch, then refine with fresh GPS. */
const LOCATION_CACHE_KEY = "last_location_v1";

async function getCachedLocation(): Promise<{
  lat: number;
  lng: number;
} | null> {
  try {
    const raw = await appStorage.getItemAsync(LOCATION_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (typeof parsed?.lat === "number" && typeof parsed?.lng === "number") {
      return { lat: parsed.lat, lng: parsed.lng };
    }
  } catch {}
  return null;
}

async function saveCachedLocation(coords: { lat: number; lng: number }) {
  try {
    await appStorage.setItemAsync(LOCATION_CACHE_KEY, JSON.stringify(coords));
  } catch {}
}

