const CLUB_CAROUSEL_MS = 3000;

// The landing is a welcome screen, not a navigation destination: once the
// user has entered the app in this session, remounting Home (tab switches,
// back from a detail screen) must never show it again.
let landingSeen = false;

// Set before an OAuth sheet opens. The OS can recreate the app while the
// browser is up, wiping module state — this flag survives that so the return
// from sign-in lands on Home, not the welcome again.
const OAUTH_PENDING_KEY = "home_oauth_pending_v1";

function DeferredHomeSection({ children }: { children: ReactNode }) {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => setReady(true));
    return () => task.cancel();
  }, []);

  return ready ? children : null;
}

/**
 * Horizontal, auto-advancing carousel of Relate Sports League team cards
 * (sport gradient, team name, tagline). Advances one card every 3s, snaps
 * per card and pauses while the user is dragging.
 */
function SportsCarousel() {
  const { width } = useWindowDimensions();
  const cardWidth = width - 32;
  const scrollRef = useRef<ScrollView>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const draggingRef = useRef(false);
  const [index, setIndex] = useState(0);
  const indexRef = useRef(0);

  const teams = SPORTS_TEAMS;
  const step = cardWidth + 12;

  useEffect(() => {
    indexRef.current = index;
  }, [index]);

  const clearTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  const startTimer = () => {
    clearTimer();
    timerRef.current = setInterval(() => {
      if (draggingRef.current) return;
      const next = (indexRef.current + 1) % teams.length;
      scrollRef.current?.scrollTo({ x: next * step, animated: true });
    }, CLUB_CAROUSEL_MS);
  };

  useEffect(() => {
    startTimer();
    return clearTimer;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cardWidth]);

  const onMomentumScrollEnd = (e: NativeSyntheticEvent<NativeScrollEvent>) => {
    const next = Math.round(e.nativeEvent.contentOffset.x / step);
    setIndex(Math.max(0, Math.min(teams.length - 1, next)));
    startTimer();
  };

  return (
    <View style={s.exploreSection}>
      <View style={s.exploreHead}>
        <Text style={s.exploreEyebrow}>Sports</Text>
        <Text style={s.exploreTitle}>Relate Sports League</Text>
        <Text style={s.exploreSub}>
          Football, netball and volleyball squads for every age group
        </Text>
      </View>

      <ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        snapToInterval={step}
        decelerationRate="fast"
        onMomentumScrollEnd={onMomentumScrollEnd}
        onScrollBeginDrag={() => {
          draggingRef.current = true;
          clearTimer();
        }}
        onScrollEndDrag={() => {
          draggingRef.current = false;
        }}
        contentContainerStyle={s.carouselRail}
      >
        {teams.map((team) => {
          const club = getClub(team.clubSlug);
          return (
            <DiscoverCard
              key={team.id}
              type="team"
              title={team.name}
              chipLabel={team.sport.toUpperCase()}
              tileIcon={club?.icon}
              image={teamCrest(team) ?? undefined}
              gradient={
                club
                  ? [club.color, club.colorDark]
                  : SPORT_THEME[team.sport].colors
              }
              meta={[
                { icon: "shield-outline", text: club?.name ?? "Relate" },
                { icon: "people-outline", text: club?.ageRange ?? "All ages" },
              ]}
              width={cardWidth}
              onPress={() =>
                router.push({
                  pathname: "/sports/[teamId]",
                  params: { teamId: team.id },
                })
              }
              accessibilityLabel={`Open ${team.name}. ${team.tagline}`}
            />
          );
        })}
      </ScrollView>

      <View style={s.carouselDots}>
        {teams.map((team, i) => (
          <View
            key={team.id}
            style={[s.carouselDot, i === index && s.carouselDotActive]}
          />
        ))}
      </View>
    </View>
  );
}

export default function HomeScreen() {
  const db = useSQLiteContext();
  const [prayerTimes, setPrayerTimes] = useState<PrayerEntry[]>([]);
  const [next, setNext] = useState<PrayerEntry | null>(null);
  const [remaining, setRemaining] = useState({
    hours: 0,
    minutes: 0,
    seconds: 0,
  });
  const [refreshing, setRefreshing] = useState(false);
  // null while we check whether the app was recreated mid-OAuth; the welcome
  // must not flash for a user who is already signing in.
  const [landingDismissed, setLandingDismissed] = useState<boolean | null>(
    landingSeen ? true : null,
  );
  const [authReady, setAuthReady] = useState(false);
  const [location, setLocation] = useState<{ lat: number; lng: number } | null>(
    null,
  );
  const [streak, setStreak] = useState(0);
  const [magazineStreak, setMagazineStreak] = useState(0);
  const [verse, setVerse] = useState<{
    reference: string;
    text: string;
  } | null>(null);
  // Settings → General "Verse of the Day" toggle; re-read on focus so turning
  // it off in Settings hides the Home card immediately.
  const [votdEnabled, setVotdEnabled] = useState(true);
  // Last opened Bible passage — powers the Home "Continue reading" entry.
  const [lastRead, setLastRead] = useState<{ book: string; chapter: number } | null>(null);
  const [, setPrayersLeft] = useState(3);
  const [completed, setCompleted] = useState<Record<string, boolean>>({});
  // Latest prayer focus the user saved for each session on the selected day.
  // When present it replaces the verse on that session's card.
  const [prayerFocus, setPrayerFocus] = useState<Record<string, PrayerRequestEntry>>({});
  const [allStreakData, setAllStreakData] = useState<StreakData>({});
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [selectedDateKey, setSelectedDateKey] = useState(getTodayKey());
  const [, setDisabledPrayers] = useState<PrayerKey[]>([]);
  const [, setCustomPrayers] = useState<CustomPrayer[]>([]);
  const [user, setUser] = useState<User | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [notifUnread, setNotifUnread] = useState(() => getNotifUnread());
  // The user's chosen club — recolors the avatar ring + streak icons, refreshed on focus.
  const [homeClub, setHomeClub] = useState<Club | undefined>(undefined);
  // Club identity is shown through color only (avatar ring + streak icons);
  // falls back to the brand gold when no club is chosen yet.
  const clubColor = homeClub?.colorDark || colors.gold;
  // Generation counter bumped on every manual tap, mirrored into a ref so
  // loadStreaks can discard stale in-flight results without adding it to its
  // dependency list (which would re-trigger the focus effect on each tap).
  const [streakWriteSeq, setStreakWriteSeq] = useState(0);
  const streakWriteSeqRef = useRef(0);
  useEffect(() => {
    streakWriteSeqRef.current = streakWriteSeq;
  }, [streakWriteSeq]);
  const [discoverTick, setDiscoverTick] = useState(0);
  const [prayerModalOpen, setPrayerModalOpen] = useState(false);

  // Keep the hero bell badge in sync with the unread notification count.
  useEffect(() => subscribeNotifUnread(setNotifUnread), []);

  // Resolve the welcome state once per mount. Signed-in users go straight to
  // Home — the welcome is for guests only. Otherwise a pending OAuth flag
  // means the app was recreated while the browser was up; that attempt is
  // simply discarded when no session came back.
  useEffect(() => {
    if (landingDismissed !== null) return;
    let active = true;
    (async () => {
      try {
        const session = await getSession();
        if (session) {
          await appStorage.deleteItemAsync(OAUTH_PENDING_KEY).catch(() => {});
          landingSeen = true;
          if (active) setLandingDismissed(true);
          return;
        }
        await appStorage.deleteItemAsync(OAUTH_PENDING_KEY).catch(() => {});
      } catch {}
      if (active) setLandingDismissed(false);
    })();
    return () => {
      active = false;
    };
  }, [landingDismissed]);

  // Keep the floating tab bar hidden until Home is actually entered, so a
  // cold start never flashes it over the welcome or its placeholder frame.
  useEffect(() => {
    setTabBarHidden(landingDismissed !== true);
  }, [landingDismissed]);

  // The welcome screen is dead time: warm the "Up Coming" rail there so Home
  // paints it from the SQLite snapshot instead of waiting on the network.
  useEffect(() => {
    if (landingDismissed !== false) return;
    prefetchDiscover(db);
  }, [landingDismissed, db]);

  // VOTD fetchers (plain API, no SDK).
  const fetchPassageText = fetchVotdPassageText;

  // VOTD: today's verse is cached in SQLite keyed by date, so the card renders
  // instantly and works offline — the YouVersion API is only hit when the day
  // changes (or the user's reader version preference changed).
  useEffect(() => {
    let active = true;
    (async () => {
      let versionId = 3034;
      try {
        versionId = await getVotdVersionId();
      } catch {}
      if (!active) return;
      const dayKey = getTodayKey();
      const cached = loadVotd(db, dayKey);
      if (
        cached &&
        cached.versionId === versionId &&
        cached.passageId &&
        cached.text
      ) {
        if (active) setVerse(cached);
        return;
      }
      const data = await fetchPassageText(versionId, getDayOfYear());
      if (active && data) {
        setVerse(data);
        saveVotd(db, {
          dayKey,
          dayOfYear: getDayOfYear(),
          versionId,
          passageId: data.passageId,
          reference: data.reference,
          text: data.text,
        });
      }
    })();
    return () => {
      active = false;
    };
  }, [fetchPassageText, db]);

  const openVotdPassage = useCallback(async () => {
    if (IS_WEB) return;
    try {
      const passageId = await fetchVotdPassageId(getDayOfYear());
      const parsed = parsePassageId(passageId || "");
      if (!parsed) return;
      const verseParam = parsed.verse ? `&verse=${parsed.verse}` : "";
      router.push(
        `/(tabs)/bible?book=${encodeURIComponent(parsed.book)}&chapter=${parsed.chapter}${verseParam}` as any,
      );
    } catch {}
  }, []);

  // The "reading track" badge: open today's guided reading for the club the
  // user has chosen. Backed by GET /api/reading-today, which returns the
  // exact-day day, else the next upcoming day, else the first day of the guide.
  const openTodayReading = useCallback(async () => {
    try {
      const clubSlug = await getSelectedClubSlug();
      const tag = clubSlug === "relate" ? "RELATE" : clubSlug.toUpperCase();
      const target = await fetchTodayReading(tag, getTodayKey());
      if (target) {
        router.push({
          pathname: "/library/[slug]/day",
          params: {
            slug: target.slug,
            week: String(target.week),
            day: String(target.day),
          },
        } as any);
        return;
      }
      router.push("/(tabs)/library" as any);
    } catch {
      router.push("/(tabs)/library" as any);
    }
  }, []);

  const loadStreaks = useCallback(async () => {
    // Take a "generation" snapshot: if the user taps a prayer while this load
    // is still resolving (e.g. a slow fetch started on focus), the result is
    // already stale and must not clobber the tap's optimistic state.
    const seq = streakWriteSeqRef.current;
    const data = await loadStreakData();
    if (seq !== streakWriteSeqRef.current) return;
    setAllStreakData(data);
    const day = data[selectedDateKey] || {};
    const comp: Record<string, boolean> = {};
    Object.entries(day).forEach(([k, v]) => {
      if (typeof v === "boolean") comp[k] = v;
    });
    setCompleted(comp);
    setStreak(calcStreak(data));
    setMagazineStreak(calcMagazineStreak(data));
    setPrayersLeft(calcPrayersLeftToday(data));
  }, [selectedDateKey]);

  // Prayer focuses are local (SQLite) and per session, so they are re-read
  // whenever the visible day changes or the screen regains focus.
  const refreshPrayerFocus = useCallback(
    async (dateKey: string) => {
      const all = await loadPrayerFocus(db);
      const prefix = `${dateKey}_`;
      const map: Record<string, PrayerRequestEntry> = {};
      for (const key of Object.keys(all)) {
        if (!key.startsWith(prefix)) continue;
        const list = all[key];
        if (list.length) map[key.slice(prefix.length)] = list[list.length - 1];
      }
      setPrayerFocus(map);
    },
    [db],
  );

  const fetchTimes = useCallback(
    async (lat: number, lng: number, forceRefresh = false) => {
      const now = new Date();
      // SQLite-cached per day + location (shared with the notification
      // scheduler), so a normal app open reuses the last fetch instead of
      // hitting the API again.
      const sun = await getSunTimes(db, lat, lng, now, forceRefresh);
      const times = buildPrayerTimes(sun.sunrise, sun.noon, sun.sunset, now);

      // Filter out disabled prayers and add custom prayers. A local-DB hiccup
      // must never blank the cards, so a failed read falls back to "none".
      let prefs: PrayerKey[] = [];
      let customs: CustomPrayer[] = [];
      try {
        prefs = await getDisabledPrayers();
        customs = await getCustomPrayers();
      } catch {}
      setDisabledPrayers(prefs);
      setCustomPrayers(customs);
      const filtered = times.filter(
        (t) => !prefs.includes(t.prayerKey as PrayerKey),
      );
      const customEntries: PrayerEntry[] = [];
      customs.forEach((c, i) => {
        if (c.enabled === false) return;
        const [h, m] = c.time.split(":").map(Number);
        if (Number.isNaN(h) || Number.isNaN(m)) return;
        const d = new Date(now);
        d.setHours(h, m, 0, 0);
        customEntries.push({
          id: 100 + i,
          title: c.name,
          icon: c.icon || "heart-outline",
          date: d,
          time: c.time,
          past: d < now,
          prayerKey: `custom-${c.id}`,
          isCustom: true,
          message: c.message || "",
        });
      });
      const all = [...filtered, ...customEntries].sort(
        (a, b) => a.date.getTime() - b.date.getTime(),
      );
      setPrayerTimes(all);
      const n = getNextPrayer(all);
      setNext(n);
      if (n) setRemaining(calcRemaining(n.date));
      setPrayerData(
        all.map((t) => ({
          name: t.prayerKey as PrayerKey,
          title: t.title,
          date: t.date,
        })),
      );

      // The scheduler owns the multi-day notification window: it rebuilds it
      // only when something significant changed (big location move, timezone,
      // preferences, window about to expire) and skips otherwise. Today's
      // prayers are already scheduled days ahead, so opening the app is never
      // required to receive them.
      try {
        maybeReschedulePrayerNotifications({ lat, lng });
      } catch {}
    },
    [db],
  );

  // Coordinates only arrive after a GPS round-trip, and Home can stay mounted
  // across a sign-out/sign-in. Always fetch with the best known location so
  // the prayer cards are never left empty.
  const fetchWithFallback = useCallback(async () => {
    if (location) {
      fetchTimes(location.lat, location.lng);
      return;
    }
    const cached = await getCachedLocation();
    fetchTimes(cached?.lat ?? -25.7, cached?.lng ?? 28.2);
  }, [location, fetchTimes]);

  const refreshHome = useCallback(async () => {
    setRefreshing(true);
    try {
      // Streaks live in SQLite and sync with the backend; a pull-to-refresh
      // forces a re-pull. The "What's new" rail compares its stored snapshot
      // against the server's content version on remount (discoverTick).
      resetStreakFetchThrottle();
      const lat = location?.lat ?? -25.7;
      const lng = location?.lng ?? 28.2;
      await Promise.all([loadStreaks(), fetchTimes(lat, lng, true)]);
      setDiscoverTick((t) => t + 1);
    } finally {
      setRefreshing(false);
    }
  }, [location, loadStreaks, fetchTimes]);

  useEffect(() => {
    initializeNotifications();
    registerBackgroundReschedule();
    rescheduleReadingReminder();
    scheduleVerseReminderNotifications();
    getDisabledPrayers().then(setDisabledPrayers);
    getCustomPrayers().then(setCustomPrayers);

    (async () => {
      // Fast path: paint with the last known location while fresh GPS
      // coordinates arrive in the background. If nothing is cached yet the
      // fallback still paints immediately — waiting on a GPS fix here left the
      // prayer cards empty on slower fixes (e.g. right after a re-login).
      const cached = await getCachedLocation();
      if (cached) setLocation(cached);
      fetchTimes(cached?.lat ?? -25.7, cached?.lng ?? 28.2);

      try {
        const { status } = await Location.requestForegroundPermissionsAsync();
        if (status !== "granted") {
          return;
        }

        // Prefer the last known GPS fix (fast); fall back to a fresh fix.
        let coords: { lat: number; lng: number };
        const lastKnown = await Location.getLastKnownPositionAsync();
        if (lastKnown?.coords) {
          coords = {
            lat: lastKnown.coords.latitude,
            lng: lastKnown.coords.longitude,
          };
        } else {
          const loc = await Location.getCurrentPositionAsync({});
          coords = { lat: loc.coords.latitude, lng: loc.coords.longitude };
        }

        setLocation(coords);
        saveCachedLocation(coords);
        fetchTimes(coords.lat, coords.lng);
      } catch {}
    })();
  }, [fetchTimes]);

  useFocusEffect(
    useCallback(() => {
      // The welcome belongs to the first entry only. If this Home instance was
      // parked behind the stack (sign-in pushed over it, or a duplicate tabs
      // entry), it must not replay the landing when it resurfaces.
      if (landingSeen) setLandingDismissed(true);
      loadStreaks();
      void refreshPrayerFocus(selectedDateKey);
      getSession().then((session) => {
        const u = session?.user || null;
        setUser(u);
        userNameRef.current = (u?.name || "").split(" ")[0];
        setAuthReady(true);
      });
      // The club badge under the avatar follows the "my club" preference and
      // re-reads on focus so changes in Settings show up immediately.
      getSelectedClubSlug().then((slug) => {
        setHomeClub(slug === "relate" ? undefined : getClub(slug));
      });
      getDisabledPrayers().then(setDisabledPrayers);
      getCustomPrayers().then(setCustomPrayers);
      getVotdEnabled().then(setVotdEnabled);
      getReaderSettings(db)
        .then((st) =>
          setLastRead(
            st.lastBook
              ? { book: st.lastBook, chapter: st.lastChapter ?? 1 }
              : null,
          ),
        )
        .catch(() => {});
      fetchWithFallback();
    }, [loadStreaks, refreshPrayerFocus, selectedDateKey, fetchWithFallback, db]),
  );

  // Streaks are per-account: signing out or switching accounts must never
  // leave the previous user's numbers on screen. The first identity resolve
  // on mount is not a switch — the focus effect already loads streaks then.
  const timesUserIdRef = useRef<string | null>(null);
  const identitySettledRef = useRef(false);
  useEffect(() => {
    const nextId = user?.id ?? null;
    if (nextId === timesUserIdRef.current) return;
    timesUserIdRef.current = nextId;
    if (!identitySettledRef.current) {
      identitySettledRef.current = true;
      return;
    }
    if (nextId) {
      // Clears the streak when signed out; fetches the new account's when
      // signed in (loadStreakData drops caches from another session).
      void loadStreaks();
      const task = InteractionManager.runAfterInteractions(() => {
        void fetchWithFallback();
      });
      return () => task.cancel();
    }
    void loadStreaks();
  }, [user, loadStreaks, fetchWithFallback]);

  // No hourly interval needed: the background task (every 15 min) handles
  // overnight rescheduling, and AppState "active" + useFocusEffect handle
  // within-day updates. This avoids 24 unnecessary fetchTimes calls/day.
  useEffect(() => {
    if (!location) return;
    const sub = AppState.addEventListener("change", (state) => {
      if (state === "active") {
        fetchTimes(location.lat, location.lng);
      }
    });
    return () => sub.remove();
  }, [location, fetchTimes]);

  const nextRef = useRef(next);
  const prayerTimesRef = useRef(prayerTimes);
  const prayerScrollRef = useRef<ScrollView>(null);
  const hasScrolledRef = useRef(false);
  const userNameRef = useRef("");

  useEffect(() => {
    nextRef.current = next;
  }, [next]);

  useEffect(() => {
    prayerTimesRef.current = prayerTimes;
  }, [prayerTimes]);

  // Auto-scroll to the upcoming prayer card (once on mount only)
  useEffect(() => {
    if (hasScrolledRef.current) return;
    if (!next || prayerTimes.length === 0) return;
    const filtered = prayerTimes.filter(
      (p) => p.isCustom || p.prayerKey in prayerConfig,
    );
    const idx = filtered.findIndex((p) => p.prayerKey === next.prayerKey);
    if (idx > 0) {
      hasScrolledRef.current = true;
      setTimeout(() => {
        prayerScrollRef.current?.scrollTo({
          x: idx * (CARD_WIDTH + 12),
          animated: true,
        });
      }, 300);
    }
  }, [prayerTimes, next]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null;
    const syncTimer = (state: string) => {
      if (interval) {
        clearInterval(interval);
        interval = null;
      }
      if (state !== "active") return;
      interval = setInterval(() => {
        // Roll the card onto the following prayer as soon as the current one
        // passes, without waiting for a focus/AppState refresh.
        const upcoming = getNextPrayer(prayerTimesRef.current);
        const current = nextRef.current;
        if (upcoming && upcoming.date.getTime() !== current?.date.getTime()) {
          nextRef.current = upcoming;
          setNext(upcoming);
        }
        const target = upcoming ?? current;
        if (target) setRemaining(calcRemaining(target.date));
      }, 1000);
    };
    syncTimer(AppState.currentState);
    const subscription = AppState.addEventListener("change", syncTimer);
    return () => {
      subscription.remove();
      if (interval) clearInterval(interval);
    };
  }, []);

  const handleToggle = async (prayerKey: PrayerKey | string) => {
    setStreakWriteSeq((s) => s + 1);
    const prev = allStreakData;
    const day = prev[selectedDateKey] || {};
    const wasDone = !!day[prayerKey];
    const comp: Record<string, boolean> = { ...completed };
    comp[prayerKey] = !wasDone;
    setCompleted(comp);
    const prevDay = prev[selectedDateKey] || {};
    const updatedDay = { ...prevDay, [prayerKey]: !wasDone };
    const optimisticData = { ...prev, [selectedDateKey]: updatedDay };
    setAllStreakData(optimisticData);
    setStreak(calcStreak(optimisticData));
    setPrayersLeft(calcPrayersLeftToday(optimisticData));
    try {
      const data = await togglePrayer(selectedDateKey, prayerKey, prev);
      setAllStreakData(data);
      setStreak(calcStreak(data));
      setMagazineStreak(calcMagazineStreak(data));
      setPrayersLeft(calcPrayersLeftToday(data));
    } catch {
      setCompleted(completed);
      setAllStreakData(prev);
      setStreak(calcStreak(prev));
      setPrayersLeft(calcPrayersLeftToday(prev));
    }
  };

  const formatShortDate = (date: Date) => {
    return date.toLocaleDateString("en-ZA", {
      weekday: "short",
      day: "numeric",
      month: "short",
    });
  };

  const changeDay = (offset: number) => {
    const newDate = new Date(selectedDate);
    newDate.setDate(newDate.getDate() + offset);
    setSelectedDate(newDate);
    const key = `${newDate.getFullYear()}-${String(newDate.getMonth() + 1).padStart(2, "0")}-${String(newDate.getDate()).padStart(2, "0")}`;
    setSelectedDateKey(key);
    void refreshPrayerFocus(key);
    const day = allStreakData[key] || {};
    const comp: Record<string, boolean> = {};
    Object.entries(day).forEach(([k, v]) => {
      if (typeof v === "boolean") comp[k] = v;
    });
    setCompleted(comp);
  };

  const goToToday = () => {
    setSelectedDate(new Date());
    const key = getTodayKey();
    setSelectedDateKey(key);
    void refreshPrayerFocus(key);
    const day = allStreakData[key] || {};
    const comp: Record<string, boolean> = {};
    Object.entries(day).forEach(([k, v]) => {
      if (typeof v === "boolean") comp[k] = v;
    });
    setCompleted(comp);
  };

  const dismissLanding = () => {
    landingSeen = true;
    setLandingDismissed(true);
  };
  const openSignIn = () => {
    // Choosing auth is entering the app: after the login screen replaces
    // the route, Home remounts and must not show the welcome again.
    landingSeen = true;
    router.push({
      pathname: "/login" as any,
      params: { next: "/(tabs)" },
    });
  };
  const startOAuth = () => {
    landingSeen = true;
    appStorage.setItemAsync(OAUTH_PENDING_KEY, "1").catch(() => {});
  };

  if (landingDismissed === null) {
    return <View style={{ flex: 1, backgroundColor: colors.forestDark }} />;
  }

  if (!landingDismissed) {
    return (
      <HomeLandingLoader
        signedIn={user != null}
        authReady={authReady}
        onGetStarted={dismissLanding}
        onSignIn={openSignIn}
        onAuthStart={startOAuth}
        onAuthSuccess={dismissLanding}
        onContinueAsGuest={dismissLanding}
        prayerTitle={next?.title}
        remaining={remaining}
      />
    );
  }

  return (
    <SafeAreaView style={s.safe} edges={["top"]}>
      <StatusBar style="dark" />
      <LinearGradient
        colors={[colors.bg, colors.white]}
        start={{ x: 0, y: 0 }}
        end={{ x: 0, y: 1 }}
        style={{ flex: 1 }}
      >
        <ScrollView
          contentContainerStyle={s.scroll}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={refreshHome}
              tintColor={colors.gold}
              colors={[colors.gold]}
            />
          }
        >
          {/* ── Hero ── */}
          <View style={s.hero}>
            <View style={s.heroTop}>
              <View style={s.logoWrap}>
                <Image
                  source={{ uri: APP_LOGO_URL }}
                  placeholder={require("../../../assets/images/relateworld_logo.png")}
                  style={s.appLogo}
                  contentFit="contain"
                />
              </View>
              <View style={s.heroActions}>
                <TouchableOpacity
                  onPress={() => router.push("/prayer-history" as any)}
                  style={s.streakBadge}
                  activeOpacity={0.8}
                  accessibilityLabel="Open prayer history"
                >
                  <MaterialCommunityIcons
                    name="hands-pray"
                    size={15}
                    color={clubColor}
                  />
                  <Text style={s.streakText}>{streak}</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  onPress={openTodayReading}
                  style={s.streakBadge}
                  activeOpacity={0.8}
                  accessibilityLabel="Open today's reading"
                >
                  <Ionicons name="book-outline" size={15} color={clubColor} />
                  <Text style={s.streakText}>{magazineStreak}</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  onPress={() => setMenuOpen(true)}
                  style={[s.bellBtn, { borderColor: clubColor }]}
                  activeOpacity={0.8}
                  accessibilityLabel="Open notifications menu"
                >
                  <Ionicons
                    name="notifications-outline"
                    size={20}
                    color={colors.darkGreen}
                  />
                  {notifUnread > 0 && (
                    <View style={s.bellDot}>
                      <Text style={s.bellDotText}>
                        {notifUnread > 9 ? "9+" : notifUnread}
                      </Text>
                    </View>
                  )}
                </TouchableOpacity>
                <TouchableOpacity
                  onPress={async () => {
                    const session = await getSession();
                    router.push(session ? "/profile-modal" : "/login");
                  }}
                  style={[s.glassBtn, { borderColor: clubColor }]}
                >
                  {user?.image ? (
                    <Image
                      source={{ uri: getOptimizedImageUrl(user.image, 160) }}
                      style={s.heroAvatar}
                      contentFit="cover"
                    />
                  ) : (
                    <Ionicons
                      name="person-circle"
                      size={24}
                      color={colors.darkGreen}
                    />
                  )}
                </TouchableOpacity>
              </View>
            </View>

            {/* Marketing pitch */}
            <View style={s.pitchBlock}>
              <Text style={s.pitchEyebrow}>SKILLS · SOCIAL · SPIRITUAL</Text>
              <Text style={s.pitchTitleLine1}>Grow</Text>
              <Text style={s.pitchTitleLine2}>in every area of life</Text>
              <Text style={s.pitchSub}>
                Share your gifts. Connect with your community. Deepen your
                faith. Relate brings it all together.
              </Text>
            </View>
          </View>

          {/* ── Verse Card ── */}
          {votdEnabled && (
            <TouchableOpacity
              style={s.verseWrap}
              activeOpacity={0.9}
              onPress={IS_WEB ? undefined : openVotdPassage}
            >
              <View style={s.verseCardShadow}>
                <View style={s.verseCard}>
                  <Image
                    source={votdBackgroundForDay()}
                    placeholder={votdPlaceholderForDay()}
                    style={s.verseBg}
                    contentFit="cover"
                    transition={500}
                  />
                  <LinearGradient
                    colors={[
                      "rgba(8,16,32,0.16)",
                      "rgba(8,16,32,0.44)",
                      "rgba(8,16,32,0.34)",
                    ]}
                    locations={[0, 0.55, 1]}
                    style={s.verseOverlay}
                    pointerEvents="none"
                  />
                  <View style={s.verseContent}>
                    <View style={s.verseHead}>
                      <View style={s.verseIcon}>
                        <Ionicons name="book" size={20} color={colors.gold} />
                      </View>
                      <Text style={s.verseEyebrow}>Verse Of The Day</Text>
                    </View>
                    <Text style={s.verseText}>
                      &quot;{verse?.text || "Loading…"}&quot;
                    </Text>
                    {verse ? (
                      <Text style={s.verseRef}>{verse.reference}</Text>
                    ) : null}
                  </View>
                </View>
              </View>
            </TouchableOpacity>
          )}

          {/* ── Continue Reading ── */}
          {!IS_WEB && lastRead ? (
            <TouchableOpacity
              style={s.continueWrap}
              activeOpacity={0.85}
              onPress={() =>
                router.push(
                  `/(tabs)/bible?book=${encodeURIComponent(lastRead.book)}&chapter=${lastRead.chapter}` as any,
                )
              }
              accessibilityRole="button"
              accessibilityLabel={`Continue reading ${lastRead.book} ${lastRead.chapter}`}
            >
              <View style={s.continueCard}>
                <View style={s.continueIcon}>
                  <Ionicons name="book-outline" size={20} color={colors.gold} />
                </View>
                <View style={s.continueBody}>
                  <Text style={s.continueEyebrow}>Continue reading</Text>
                  <Text style={s.continueRef} numberOfLines={1}>
                    {lastRead.book} {lastRead.chapter}
                  </Text>
                </View>
                <Ionicons name="chevron-forward" size={20} color={colors.muted} />
              </View>
            </TouchableOpacity>
          ) : null}

          {/* ── Next Prayer Card ── */}
          {next && (
            <View style={s.nextWrap}>
              <LinearGradient
                colors={["#13c5dd", "#1d2a4d"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={s.nextCard}
              >
                <View style={s.nextLeft}>
                  <Text style={s.nextEyebrow}>NEXT PRAYER</Text>
                  <Text style={s.nextName}>{next.title}</Text>
                  <View style={s.nextCountdown}>
                    <Ionicons
                      name="time-outline"
                      size={14}
                      color="rgba(255,255,255,0.85)"
                    />
                    <Text style={s.nextCountdownText}>
                      {remaining.hours}h {remaining.minutes}m remaining
                    </Text>
                  </View>
                </View>
                <View style={s.progressRing}>
                  <LinearGradient
                    colors={[colors.forestSoft, colors.forestDark]}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={s.progressRingBg}
                  >
                    <Text style={s.progressTime}>{next.time}</Text>
                    <Text style={s.progressLabel}>Next</Text>
                  </LinearGradient>
                </View>
              </LinearGradient>
            </View>
          )}

          {/* ── Prayer Times Section ── */}
          {prayerTimes.length > 0 && (
            <View style={s.section}>
              <View style={s.sectionHead}>
                <View>
                  <Text style={s.sectionTitle}>Today&apos;s prayer times</Text>
                  <Text style={s.sectionSub}>
                    A suggested daily devotional rhythm
                  </Text>
                </View>
                <TouchableOpacity onPress={goToToday} style={s.todayBtn}>
                  <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  <Text style={s.todayBtnText}>Today</Text>
                </TouchableOpacity>
              </View>

              {/* Date Nav */}
              <View style={s.dateNav}>
                <TouchableOpacity
                  onPress={() => changeDay(-1)}
                  style={s.dateNavBtn}
                >
                  <Ionicons name="chevron-back" size={20} color={colors.forest} />
                </TouchableOpacity>
                <Text style={s.dateNavText}>{formatShortDate(selectedDate)}</Text>
                <TouchableOpacity
                  onPress={() => changeDay(1)}
                  style={s.dateNavBtn}
                >
                  <Ionicons
                    name="chevron-forward"
                    size={20}
                    color={colors.forest}
                  />
                </TouchableOpacity>
              </View>

              {/* ── Daily Verse Cards ── */}
              <ScrollView
                ref={prayerScrollRef}
                horizontal
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={s.prayerCardScroll}
                snapToInterval={CARD_WIDTH + 12}
                decelerationRate="fast"
              >
                {prayerTimes
                  .filter((p) => p.isCustom || p.prayerKey in prayerConfig)
                  .map((pt) => {
                    const key = pt.prayerKey;
                    const custom = !!pt.isCustom;
                    // Custom prayers have no curated verse pool; showing one
                    // would crash todayVerse, so they carry their own message.
                    const point = custom ? null : todayVerse(key as PrayerKey);
                    const icon = custom
                      ? pt.icon || "heart-outline"
                      : prayerConfig[key as PrayerKey].icon;
                    const label = custom
                      ? pt.title
                      : prayerConfig[key as PrayerKey].label;
                    const caption = custom
                      ? pt.message || "Custom prayer"
                      : prayerConfig[key as PrayerKey].caption;
                    const done = completed[key];
                    const timeStr = pt.time || "";
                    const focus = prayerFocus[key];

                    return (
                      <TouchableOpacity
                        key={key}
                        onPress={() => handleToggle(key)}
                        activeOpacity={0.85}
                      >
                        <LinearGradient
                          colors={["#13c5dd", "#1d2a4d"]}
                          start={{ x: 0, y: 0 }}
                          end={{ x: 1, y: 1 }}
                          style={s.prayerCard}
                        >
                          <View style={s.prayerCardHeader}>
                            <View style={s.prayerCardIcon}>
                              <Ionicons
                                name={icon as any}
                                size={24}
                                color={colors.white}
                              />
                            </View>
                            <View style={{ flex: 1 }}>
                              <Text style={s.prayerCardName}>{label}</Text>
                              <Text style={s.prayerCardCaption}>{caption}</Text>
                            </View>
                            {timeStr ? (
                              <Text style={s.prayerCardTime}>{timeStr}</Text>
                            ) : null}
                          </View>
                          {focus ? (
                            <>
                              <Text style={s.prayerCardVerse} numberOfLines={4}>
                                &ldquo;{focus.text}&rdquo;
                              </Text>
                              <Text style={s.prayerCardRef}>
                                &mdash;{" "}
                                {[focus.name, focus.topic].filter(Boolean).join(" · ") ||
                                  "Your prayer focus"}
                              </Text>
                            </>
                          ) : point ? (
                            <>
                              <Text style={s.prayerCardVerse}>
                                &ldquo;{point.verse}&rdquo;
                              </Text>
                              <Text style={s.prayerCardRef}>
                                &mdash; {point.ref}
                              </Text>
                            </>
                          ) : null}
                          {done ? (
                            <View style={s.prayerCardCheck}>
                              <Ionicons
                                name="checkmark"
                                size={16}
                                color={colors.forestDark}
                              />
                            </View>
                          ) : (
                            <View style={s.prayerCardDot} />
                          )}
                        </LinearGradient>
                      </TouchableOpacity>
                    );
                  })}
              </ScrollView>
            </View>
          )}

          {/* ── Discover rail ── */}
          <DiscoverRail refreshSignal={discoverTick} />

          {/* ── Community ── */}
          <View style={s.communitySection}>
            <View style={s.exploreHead}>
              <Text style={s.exploreEyebrow}>Community</Text>
              <Text style={s.exploreTitle}>Stay connected</Text>
              <Text style={s.exploreSub}>
                Chat with your club and follow us online
              </Text>
            </View>

            <View style={s.cardStack}>
              {/* Club Chat card */}
              <ClubChatCard />

              {/* Facebook card */}
              <LinearGradient
                colors={[colors.info, "#2563eb"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={s.helpCard}
              >
                <View style={s.helpIconRow}>
                  <View style={s.helpIcon}>
                    <Ionicons
                      name="logo-facebook"
                      size={22}
                      color={colors.white}
                    />
                  </View>
                  <Text style={s.helpTitle}>Facebook</Text>
                </View>
                <Text style={s.helpText}>
                  Follow our page for prayer updates, event highlights, and
                  community news.
                </Text>
                <TouchableOpacity
                  style={[s.cardBtn, s.cardBtnBlue]}
                  onPress={() =>
                    Linking.openURL(
                      "https://www.facebook.com/profile.php?id=100091465431429",
                    )
                  }
                  activeOpacity={0.85}
                >
                  <Text style={s.cardBtnBlueText}>Follow</Text>
                  <Ionicons name="arrow-forward" size={16} color="#1877F2" />
                </TouchableOpacity>
              </LinearGradient>

              {/* Instagram card */}
              <View style={[s.helpCard, s.helpCardPlain]}>
                <View style={s.helpIconRow}>
                  <View style={[s.helpIcon, s.helpIconPlain]}>
                    <Ionicons name="logo-instagram" size={22} color="#C13584" />
                  </View>
                  <Text style={[s.helpTitle, s.helpTitlePlain]}>Instagram</Text>
                </View>
                <Text style={[s.helpText, s.helpTextPlain]}>
                  Follow for prayer updates, event highlights, and community
                  news.
                </Text>
                <TouchableOpacity
                  style={[s.cardBtn, s.cardBtnPink]}
                  onPress={() => Linking.openURL(INSTAGRAM_URL)}
                  activeOpacity={0.85}
                >
                  <Text style={s.cardBtnPinkText}>Follow</Text>
                  <Ionicons name="arrow-forward" size={16} color="#C13584" />
                </TouchableOpacity>
              </View>
            </View>
          </View>

          {/* ── Grow in Faith ── */}
          <View style={s.exploreSection}>
            <View style={s.exploreHead}>
              <Text style={s.exploreEyebrow}>Explore</Text>
              <Text style={s.exploreTitle}>Grow in faith</Text>
              <Text style={s.exploreSub}>Go deeper in the Word</Text>
            </View>

            <View style={s.bannerList}>
              <FeatureBanner
                eyebrow="Requests"
                title="Help & Requests"
                sub="Ask the community for help"
                icon="chatbubbles-outline"
                gradient={["#C73618", "#004a59"]}
                onPress={() => router.push("/ask-help")}
              />
              <FeatureBanner
                eyebrow="Prayer"
                title="Prayer Requests"
                sub="Let the community pray for you"
                icon="heart-circle-outline"
                gradient={["#0F4C5C", "#86112e"]}
                onPress={async () => {
                  const session = await getSession();
                  if (!session?.user) {
                    router.push({
                      pathname: "/login",
                      params: { next: "/(tabs)" },
                    });
                    return;
                  }
                  setPrayerModalOpen(true);
                }}
              />
            </View>
          </View>

          <DeferredHomeSection>
            {/* ── Skills & growth ── */}
            <SkillsRail />

            {/* ── Sports teams ── */}
            <SportsCarousel />

            {/* ── Skill Resources ── */}
            <SkillResources />
          </DeferredHomeSection>
        </ScrollView>
      </LinearGradient>

      {prayerModalOpen && (
        <PrayerRequestModal
          editing={null}
          onClose={() => setPrayerModalOpen(false)}
          onSubmit={() => {}}
        />
      )}

      <NotificationsMenuModal
        visible={menuOpen}
        onClose={() => setMenuOpen(false)}
      />
    </SafeAreaView>
  );
}

