import { memo } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { Skill } from "@/constants/skills";
import { getOptimizedImageUrl } from "@/services/cloudinary";

/** The club half of the context a card needs — fits bundled and API catalogs. */
export type SkillCardClub = {
  clubSlug: string;
  clubName: string;
  clubColor: string;
  clubColorDark: string;
};

/**
 * A skill card exactly as the web club page draws it: photo header over a
 * club gradient (initial-letter fallback), then level dot + level name,
 * the skill title with a trailing arrow, and a two-line description.
 */
function SkillCard({
  skill,
  club,
  onPress,
  width,
  accessibilityLabel,
}: {
  skill: Skill;
  club: SkillCardClub;
  onPress: () => void;
  width?: number;
  accessibilityLabel?: string;
}) {
  const level = skill.levels[0];
  const firstRequirement = (
    skill.requirements?.length ? skill.requirements : level?.requirements
  )?.[0]?.text;
  const levelLabel = skill.type
    ? `${skill.type} · ${level?.name ?? "Skill"}`
    : level?.name ?? "Skill";
  const gradient = [
    level?.colorDark ?? club.clubColorDark,
    club.clubColor,
  ] as const;
  const mediaH = Math.max(
    104,
    Math.min(164, Math.round((width ?? 300) * 0.5)),
  );

  return (
    <TouchableOpacity
      activeOpacity={0.85}
      onPress={onPress}
      style={[s.card, width ? { width } : null]}
      accessibilityRole="button"
      accessibilityLabel={
        accessibilityLabel ?? `${skill.name} — open the skill details`
      }
    >
      <View style={[s.media, { height: mediaH }]}>
        <LinearGradient
          colors={gradient}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFill}
        >
          {!skill.image && (
            <View style={s.initialWrap}>
              <Text style={s.initial}>{skill.name[0]}</Text>
            </View>
          )}
        </LinearGradient>
        {skill.image ? (
          <Image
            source={{ uri: getOptimizedImageUrl(skill.image, 720) }}
            style={StyleSheet.absoluteFill}
            contentFit="cover"
            transition={200}
            accessibilityIgnoresInvertColors
          />
        ) : null}
      </View>

      <View style={s.details}>
        <View style={s.levelRow}>
          <View
            style={[s.levelDot, { backgroundColor: level?.color ?? club.clubColor }]}
          />
          <Text
            style={[s.levelName, skill.type === "Compulsory" && s.levelNameBold]}
            numberOfLines={1}
          >
            {levelLabel}
          </Text>
        </View>

        <View style={s.titleRow}>
          <Text style={s.title} numberOfLines={1}>
            {skill.name}
          </Text>
          <Text style={s.arrow}>→</Text>
        </View>

        {skill.description ? (
          <Text style={s.desc} numberOfLines={2}>
            {skill.description}
          </Text>
        ) : null}
        {firstRequirement ? (
          <Text style={s.req} numberOfLines={1}>
            {firstRequirement}
          </Text>
        ) : null}
      </View>
    </TouchableOpacity>
  );
}

const s = StyleSheet.create({
  card: {
    backgroundColor: colors.white,
    borderRadius: 16,
    padding: 12,
  },
  media: {
    borderRadius: 12,
    overflow: "hidden",
  },
  initialWrap: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  initial: {
    fontSize: 44,
    fontWeight: "900",
    color: "rgba(255,255,255,0.25)",
    fontFamily: fonts.sansBold,
  },
  details: {
    paddingHorizontal: 4,
    paddingTop: 12,
    paddingBottom: 2,
  },
  levelRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 7,
    marginBottom: 6,
  },
  levelDot: {
    width: 10,
    height: 10,
    borderRadius: 5,
  },
  levelName: {
    fontSize: 11,
    color: colors.muted,
    fontFamily: fonts.sans,
  },
  levelNameBold: {
    color: colors.darkGreen,
    fontWeight: "700",
    fontFamily: fonts.sansBold,
  },
  titleRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
  },
  title: {
    flex: 1,
    fontSize: 15,
    fontWeight: "700",
    color: colors.darkGreen,
    fontFamily: fonts.sansBold,
    lineHeight: 20,
  },
  arrow: {
    fontSize: 14,
    fontWeight: "700",
    color: colors.gold,
    opacity: 0.55,
  },
  desc: {
    marginTop: 5,
    fontSize: 12,
    color: colors.muted,
    fontFamily: fonts.sans,
    lineHeight: 17,
  },
  req: {
    marginTop: 4,
    fontSize: 11,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
    lineHeight: 15,
  },
});

export default memo(SkillCard);
