import { appStorage } from "./app-storage";

// The club the user has chosen to follow. Drives the home "today's reading"
// shortcut and the Library tab's default filter. Stored locally on-device;
// defaults to the umbrella "relate" club until the user picks one.
const SELECTED_CLUB_KEY = "selected_club";
export const DEFAULT_CLUB = "relate";

export function getSelectedClubSlug(): Promise<string> {
  return appStorage.getItemAsync(SELECTED_CLUB_KEY)
    .then((slug) => slug || DEFAULT_CLUB)
    .catch(() => DEFAULT_CLUB);
}

export async function setSelectedClubSlug(slug: string): Promise<void> {
  await appStorage.setItemAsync(SELECTED_CLUB_KEY, slug);
}