import { Ionicons } from "@expo/vector-icons";
import { router } from "expo-router";
import {
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  ScrollView,
  useWindowDimensions,
} from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { useClubsSkills } from "@/services/skills-catalog";
import SkillCard from "@/components/skills/SkillCard";

const CARD_GAP = 12;

/** Home rail carries Sprout only — every other club's skills stay on its page. */
const RAIL_CLUBS = ["sprout"];

/**
 * Skills rail — Sprout skills (Kids, Tweens and Teens) from the backend catalog.
 */
export default function SkillsRail() {
  const { width } = useWindowDimensions();
  const cardWidth = width - 32;

  const { catalogs } = useClubsSkills(RAIL_CLUBS);
  const allSkills = catalogs.flatMap((catalog) =>
    catalog.skills.map((skill) => ({ skill, catalog })),
  );

  // Both the API and the bundled fallback need a moment — no empty rail flash.
  if (allSkills.length === 0) return null;

  const header = (
    <View style={s.head}>
      <View style={s.headLeft}>
        <Text style={s.eyebrow}>SPROUT CLUB</Text>
        <Text style={s.title}>Skills &amp; growth</Text>
        <Text style={s.sub}>
          Earn real skills as you grow — from first aid to code, saving and
          storytelling, ages 6–16.
        </Text>
      </View>
      <TouchableOpacity
        onPress={() => router.push("/skills/sprout" as any)}
        style={s.viewAllBtn}
        activeOpacity={0.7}
        accessibilityRole="button"
        accessibilityLabel="See all skills"
      >
        <Text style={s.viewAllText}>View all</Text>
        <Ionicons name="chevron-forward" size={14} color={colors.gold} />
      </TouchableOpacity>
    </View>
  );

  return (
    <View style={s.section}>
      {header}
      <View style={s.railWrap}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          snapToInterval={cardWidth + CARD_GAP}
          decelerationRate="fast"
          contentContainerStyle={s.rail}
        >
          {allSkills.map(({ skill, catalog }) => (
            <SkillCard
              key={`${catalog.clubSlug}:${skill.id}`}
              skill={skill}
              club={catalog}
              width={cardWidth}
              onPress={() =>
                router.push(`/skills/${catalog.clubSlug}/${skill.id}`)
              }
            />
          ))}
        </ScrollView>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  section: { paddingTop: 8, paddingBottom: 4 },
  head: {
    flexDirection: "row",
    alignItems: "flex-start",
    justifyContent: "space-between",
    paddingHorizontal: 18,
    marginBottom: 14,
  },
  headLeft: { flex: 1, marginRight: 12 },
  eyebrow: {
    fontSize: 10,
    textTransform: "uppercase",
    letterSpacing: 1.8,
    fontWeight: "700",
    color: colors.gold,
    fontFamily: fonts.sansBold,
  },
  title: {
    fontSize: 16,
    fontWeight: "700",
    color: colors.darkGreen,
    fontFamily: fonts.sansBold,
    marginTop: 4,
  },
  sub: {
    fontSize: 11,
    fontWeight: "400",
    color: colors.muted,
    fontFamily: fonts.sans,
    marginTop: 4,
    lineHeight: 15,
  },
  viewAllBtn: {
    flexDirection: "row",
    alignItems: "center",
    gap: 2,
    paddingTop: 22,
  },
  viewAllText: {
    fontSize: 13,
    fontWeight: "700",
    color: colors.gold,
    fontFamily: fonts.sansBold,
  },
  railWrap: { position: "relative" },
  rail: {
    paddingHorizontal: 16,
    gap: CARD_GAP,
    paddingRight: 60,
  },
});
