import { Ionicons } from "@expo/vector-icons";
import * as ImagePicker from "expo-image-picker";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useState } from "react";
import { LinearGradient } from "expo-linear-gradient";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { type Club, useClubs } from "@/services/clubs";
import ClubSelect from "@/components/ClubSelect";
import { communityApi } from "@/services/community";
import { getSession } from "@/services/auth";

const GROUP_CATEGORIES = [
  { value: "prayer", label: "Prayer" },
  { value: "bible", label: "Bible study" },
  { value: "support", label: "Support" },
  { value: "activity", label: "Activity" },
  { value: "study", label: "Study" },
  { value: "youtube", label: "YouTube channel" },
];

const YOUTUBE_FOCUS_OPTIONS = [
  "Education",
  "Sport",
  "Lifestyle",
  "Culture",
  "Comedy",
  "Gaming",
  "News",
  "Music",
  "Entrepreneurship",
];

const QUICK_TIMES = [
  "Every Sunday 5:00 PM",
  "Every Tuesday 6:00 PM",
  "Every Wednesday 6:30 PM",
  "Every Saturday 9:00 AM",
];

/**
 * Create a group inside a club. The backend only accepts group creation from
 * admins (requireGroupCreator); the UI mirrors that so members see a clear
 * explanation instead of a raw 403.
 */
export default function ClubGroupFormModal({
  visible,
  club,
  onClose,
  onSaved,
}: {
  visible: boolean;
  club: Club;
  onClose: () => void;
  onSaved: () => void;
}) {
  const insets = useSafeAreaInsets();
  const [clubSlug, setClubSlug] = useState<string>(club.slug);
  const { find } = useClubs();
  const selectedClub = find(clubSlug) ?? club;
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("prayer");
  const [meetingTime, setMeetingTime] = useState("");
  const [schedule, setSchedule] = useState("");
  const [location, setLocation] = useState("");
  const [maxMembers, setMaxMembers] = useState("");
  const [channelFocus, setChannelFocus] = useState("");
  const [channelName, setChannelName] = useState("");
  const [channelUrl, setChannelUrl] = useState("");
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const resetForm = () => {
    setClubSlug(club.slug);
    setName("");
    setDescription("");
    setCategory("prayer");
    setMeetingTime("");
    setSchedule("");
    setLocation("");
    setMaxMembers("");
    setChannelFocus("");
    setChannelName("");
    setChannelUrl("");
    setImageUrl(null);
  };

  const pickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      quality: 0.8,
      base64: true,
    });
    if (!result.canceled && result.assets?.length > 0) {
      const asset = result.assets[0];
      setImageLoading(true);
      try {
        const { uploadGroupImage } = await import("@/services/cloudinary");
        const url = await uploadGroupImage(asset);
        setImageUrl(url);
      } catch (err) {
        Alert.alert(
          "Upload Failed",
          err instanceof Error ? err.message : "Could not upload the group image.",
        );
      }
      setImageLoading(false);
    }
  };

  const submit = async () => {
    if (!name.trim()) {
      Alert.alert("Required", "Please enter a group name.");
      return;
    }
    if (category === "youtube") {
      const size = maxMembers ? parseInt(maxMembers, 10) : 0;
      if (!channelFocus.trim() || !channelName.trim()) {
        Alert.alert(
          "Channel details required",
          "Enter a channel name and choose the focus of the channel.",
        );
        return;
      }
      if (size < 4 || size > 5) {
        Alert.alert(
          "Invalid team size",
          "Video channel teams must have between 4 and 5 members.",
        );
        return;
      }
    }
    setSubmitting(true);
    try {
      const session = await getSession();
      const payload: any = {
        name: name.trim(),
        description: description.trim(),
        category,
        meetingTime: meetingTime.trim(),
        schedule: schedule.trim(),
        location: location.trim(),
        maxMembers: maxMembers ? parseInt(maxMembers, 10) : 0,
        imageUrl,
        clubSlug,
        author: session?.user?.name || "Anonymous",
        channelFocus: category === "youtube" ? channelFocus.trim() : "",
        channelName: category === "youtube" ? channelName.trim() : "",
        channelUrl: category === "youtube" ? channelUrl.trim() : "",
      };
      await communityApi.createGroup(payload);
      onSaved();
      onClose();
    } catch (err: any) {
      Alert.alert(
        "Could not create group",
        err?.message || "Only admins can create groups. Ask a Relate admin to set one up.",
      );
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal visible={visible} animationType="slide" statusBarTranslucent onShow={resetForm} onRequestClose={onClose}>
      <View style={[s.safe, { paddingTop: insets.top }]}>
        <LinearGradient
          colors={[selectedClub.color, selectedClub.colorDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.head}
        >
          <View style={s.headRow}>
            <View style={s.headIcon}>
              <Ionicons name="people-outline" size={20} color={colors.white} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.headEyebrow}>{selectedClub.name.toUpperCase()} CLUB</Text>
              <Text style={s.headTitle}>Create a group</Text>
            </View>
            <TouchableOpacity onPress={onClose} style={s.closeBtn} accessibilityLabel="Close">
              <Ionicons name="close" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>
          <Text style={s.headSub}>
            This group is tagged to the {selectedClub.name} club — it shows only
            in that club and in the home discover rail.
            Admins only.
          </Text>
        </LinearGradient>

        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={{ flex: 1 }}
        >
          <ScrollView
            contentContainerStyle={s.form}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            <ClubSelect value={clubSlug} onChange={setClubSlug} label="Which club is this group for?" />

            <Text style={s.label}>
              Group name <Text style={s.req}>*</Text>
            </Text>
            <TextInput style={s.input} value={name} onChangeText={setName} placeholder="e.g. Thursday Prayer Circle" placeholderTextColor={colors.muted} />

            <Text style={s.label}>Description</Text>
            <TextInput
              style={[s.input, s.inputMultiline]}
              value={description}
              onChangeText={setDescription}
              placeholder="What is this group about?"
              placeholderTextColor={colors.muted}
              multiline
              textAlignVertical="top"
            />

            <Text style={s.label}>Category</Text>
            <View style={s.pillRow}>
              {GROUP_CATEGORIES.map((c) => (
                <TouchableOpacity
                  key={c.value}
                  style={[s.pill, category === c.value && s.pillActive]}
                  onPress={() => setCategory(c.value)}
                >
                  <Text style={[s.pillText, category === c.value && s.pillTextActive]}>
                    {c.label}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>

            <Text style={s.label}>Meeting time</Text>
            <TextInput style={s.input} value={meetingTime} onChangeText={setMeetingTime} placeholder="e.g. Every Sunday 5:00 PM" placeholderTextColor={colors.muted} />
            <View style={s.pillRow}>
              {QUICK_TIMES.map((t) => (
                <TouchableOpacity key={t} style={s.pill} onPress={() => setMeetingTime(t)}>
                  <Text style={s.pillText}>{t.replace("Every ", "")}</Text>
                </TouchableOpacity>
              ))}
            </View>

            <Text style={s.label}>Schedule note</Text>
            <TextInput style={s.input} value={schedule} onChangeText={setSchedule} placeholder="e.g. Weekly during term" placeholderTextColor={colors.muted} />

            <Text style={s.label}>Location</Text>
            <TextInput style={s.input} value={location} onChangeText={setLocation} placeholder="e.g. Community hall, or Online" placeholderTextColor={colors.muted} />

            <Text style={s.label}>Max members</Text>
            <TextInput
              style={s.input}
              value={maxMembers}
              onChangeText={(t) => setMaxMembers(t.replace(/[^0-9]/g, ""))}
              placeholder="0 = no limit"
              placeholderTextColor={colors.muted}
              keyboardType="numeric"
              maxLength={4}
            />
            {category === "youtube" ? (
              <>
                <Text style={s.label}>YouTube channel name *</Text>
                <TextInput
                  style={s.input}
                  value={channelName}
                  onChangeText={setChannelName}
                  placeholder="e.g. Surge Creators"
                  placeholderTextColor={colors.muted}
                />

                <Text style={s.label}>Channel focus *</Text>
                <View style={s.pillRow}>
                  {YOUTUBE_FOCUS_OPTIONS.map((focus) => (
                    <TouchableOpacity
                      key={focus}
                      style={[s.pill, channelFocus === focus && s.pillActive]}
                      onPress={() => setChannelFocus(focus)}
                    >
                      <Text
                        style={[
                          s.pillText,
                          channelFocus === focus && s.pillTextActive,
                        ]}
                      >
                        {focus}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>

                <Text style={s.label}>YouTube channel link</Text>
                <TextInput
                  style={s.input}
                  value={channelUrl}
                  onChangeText={setChannelUrl}
                  placeholder="https://youtube.com/@your-channel"
                  placeholderTextColor={colors.muted}
                  autoCapitalize="none"
                  keyboardType="url"
                />
              </>
            ) : null}

            <Text style={s.label}>Group image</Text>
            {imageUrl ? (
              <View style={s.imagePreviewWrap}>
                <TouchableOpacity style={s.imagePreview} onPress={pickImage} activeOpacity={0.85}>
                  <Text style={s.imagePreviewBtnText}>Tap to change image</Text>
                </TouchableOpacity>
                <TouchableOpacity style={s.imageRemove} onPress={() => setImageUrl(null)} accessibilityLabel="Remove image">
                  <Ionicons name="trash-outline" size={16} color={colors.error} />
                </TouchableOpacity>
              </View>
            ) : (
              <TouchableOpacity style={s.imageAdd} onPress={imageLoading ? undefined : pickImage} activeOpacity={0.8} disabled={imageLoading}>
                {imageLoading ? (
                  <ActivityIndicator size="small" color={colors.goldDark} />
                ) : (
                  <>
                    <Ionicons name="image-outline" size={22} color={colors.goldDark} />
                    <Text style={s.imageAddText}>Add an image (stored in Supabase)</Text>
                  </>
                )}
              </TouchableOpacity>
            )}

            <TouchableOpacity
              style={[s.submitBtn, { backgroundColor: selectedClub.colorDark }]}
              activeOpacity={0.9}
              onPress={submit}
              disabled={submitting}
            >
              {submitting ? (
                <ActivityIndicator size="small" color={colors.white} />
              ) : (
                <>
                  <Ionicons name="checkmark-circle-outline" size={18} color={colors.white} />
                  <Text style={s.submitText}>Create group</Text>
                </>
              )}
            </TouchableOpacity>
          </ScrollView>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: colors.bg,
  },
  head: {
    paddingHorizontal: 20,
    paddingTop: 14,
    paddingBottom: 22,
  },
  headRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
  },
  headIcon: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: "rgba(255,255,255,0.22)",
    alignItems: "center",
    justifyContent: "center",
  },
  headEyebrow: {
    fontFamily: fonts.sansBold, fontWeight: "700",
    fontSize: 10,
    textTransform: "uppercase",
    letterSpacing: 1.8,
    color: "rgba(255,255,255,0.85)",
  },
  headTitle: {
    fontFamily: fonts.serif,
    fontSize: 20,
    color: colors.white,
    marginTop: 2,
  },
  closeBtn: {
    width: 34,
    height: 34,
    borderRadius: 17,
    backgroundColor: "rgba(255,255,255,0.2)",
    alignItems: "center",
    justifyContent: "center",
  },
  headSub: {
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 11,
    lineHeight: 15,
    color: "rgba(255,255,255,0.92)",
    marginTop: 10,
  },
  form: {
    padding: 20,
    paddingBottom: 48,
  },
  label: {
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    fontSize: 13,
    color: colors.ink,
    marginTop: 14,
    marginBottom: 6,
  },
  req: {
    color: colors.error,
  },
  input: {
    backgroundColor: colors.white,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: "#d9e8f1",
    paddingHorizontal: 14,
    paddingVertical: 11,
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 14,
    color: colors.ink,
  },
  inputMultiline: {
    minHeight: 84,
    paddingTop: 12,
  },
  pillRow: {
    flexDirection: "row",
    flexWrap: "wrap",
    gap: 8,
    marginTop: 4,
  },
  pill: {
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 999,
    backgroundColor: colors.white,
    borderWidth: 1,
    borderColor: "#d9e8f1",
  },
  pillActive: {
    backgroundColor: colors.gold,
    borderColor: colors.gold,
  },
  pillText: {
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    fontSize: 12.5,
    color: colors.forestSoft,
  },
  pillTextActive: {
    color: colors.forestDark,
  },
  imageAdd: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    borderRadius: 12,
    borderWidth: 1.5,
    borderStyle: "dashed",
    borderColor: "#b9d6e4",
    paddingVertical: 22,
    backgroundColor: "rgba(19,197,221,0.04)",
  },
  imageAddText: {
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 13,
    color: colors.muted,
  },
  imagePreviewWrap: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
  },
  imagePreview: {
    flex: 1,
    backgroundColor: colors.white,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: "#d9e8f1",
    paddingVertical: 14,
    alignItems: "center",
  },
  imagePreviewBtnText: {
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    fontSize: 13,
    color: colors.forest,
  },
  imageRemove: {
    width: 40,
    height: 40,
    borderRadius: 12,
    alignItems: "center",
    justifyContent: "center",
  },
  submitBtn: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    borderRadius: 26,
    paddingVertical: 14,
    marginTop: 22,
  },
  submitText: {
    fontFamily: fonts.sansBold, fontWeight: "700",
    fontSize: 15,
    color: colors.white,
  },
});
