const MONTH_SHORT = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

function formatDate(value: string | null) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return date.toLocaleString();
}

function formatDay(value: string | null) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return date.toISOString().slice(0, 10);
}

function toDateInput(value: string | null) {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toISOString().slice(0, 10);
}

function isDateInput(value: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const date = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
}

function toLocalDateKey(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function prettyDateKey(value: string) {
  if (!isDateInput(value)) return "Choose date";
  const date = new Date(`${value}T12:00:00`);
  return `${date.getDate()} ${MONTH_SHORT[date.getMonth()]} ${date.getFullYear()}`;
}

function shortDate(value: string | null) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return `${date.getDate()} ${MONTH_SHORT[date.getMonth()]}`;
}

function CheckRow({
  label,
  checked,
  reason,
  reasonOpen,
  onToggle,
  onToggleReason,
  onReasonChange,
}: {
  label: string;
  checked: boolean;
  reason: string;
  reasonOpen: boolean;
  onToggle: () => void;
  onToggleReason: () => void;
  onReasonChange: (value: string) => void;
}) {
  return (
    <View style={styles.checkItem}>
      <TouchableOpacity
        onPress={onToggle}
        accessibilityRole="checkbox"
        accessibilityState={{ checked }}
        style={styles.checkRow}
      >
        <Ionicons
          name={checked ? "checkbox" : "checkbox-outline"}
          size={22}
          color={checked ? colors.info : colors.gray[400]}
        />
        <Text style={[styles.checkLabel, checked && styles.checkLabelDone]}>{label}</Text>
      </TouchableOpacity>
      {!checked ? (
        <View style={styles.reasonBlock}>
          <TouchableOpacity
            onPress={onToggleReason}
            accessibilityRole="button"
            style={styles.reasonToggle}
          >
            <Ionicons
              name={reasonOpen ? "chevron-up-outline" : "add-circle-outline"}
              size={16}
              color={colors.info}
            />
            <Text style={styles.reasonToggleText}>
              {reasonOpen ? "Hide reason" : reason ? "Edit reason" : "Why not?"}
            </Text>
          </TouchableOpacity>
          {reasonOpen ? (
            <TextInput
              value={reason}
              onChangeText={onReasonChange}
              placeholder="Tell the approver why you could not complete this"
              placeholderTextColor={colors.gray[400]}
              style={styles.reasonInput}
              multiline
              numberOfLines={3}
              textAlignVertical="top"
              autoCapitalize="sentences"
              maxLength={500}
            />
          ) : reason ? (
            <Text style={styles.reasonPreview}>{reason}</Text>
          ) : null}
        </View>
      ) : null}
    </View>
  );
}

