function DateField({
  label,
  value,
  minimumDate,
  maximumDate,
  disabled,
  onChange,
}: {
  label: string;
  value: string;
  minimumDate?: Date;
  maximumDate?: Date;
  disabled?: boolean;
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const selected = isDateInput(value) ? new Date(`${value}T12:00:00`) : null;
  return (
    <View style={styles.dateFieldWrap}>
      <Text style={styles.dateLabel}>{label}</Text>
      <TouchableOpacity
        accessibilityRole="button"
        accessibilityLabel={`${label}: ${prettyDateKey(value)}`}
        disabled={disabled}
        activeOpacity={0.7}
        style={[styles.dateField, disabled && styles.buttonDisabled]}
        onPress={() => setOpen(true)}
      >
        <Ionicons name="calendar-outline" size={16} color={colors.info} />
        <Text
          style={[styles.dateFieldText, !selected && styles.dateFieldPlaceholder]}
          numberOfLines={1}
        >
          {prettyDateKey(value)}
        </Text>
      </TouchableOpacity>
      <Modal
        visible={open}
        transparent
        animationType="fade"
        onRequestClose={() => setOpen(false)}
      >
        <View style={styles.modalBackdrop}>
          <View style={styles.modalCard}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>{label}</Text>
              <TouchableOpacity
                accessibilityRole="button"
                accessibilityLabel="Close date picker"
                onPress={() => setOpen(false)}
                style={styles.modalClose}
              >
                <Ionicons name="close" size={18} color={colors.gray[600]} />
              </TouchableOpacity>
            </View>
            <InlineCalendar
              value={selected}
              minimumDate={minimumDate}
              maximumDate={maximumDate}
              onSelect={(date) => {
                onChange(toLocalDateKey(date));
                setOpen(false);
              }}
            />
          </View>
        </View>
      </Modal>
    </View>
  );
}

function StatusBanner({ submission }: { submission: OnboardingSubmission | null }) {
  const status = submission?.status || "none";
  const meta = STATUS_META[status];
  const colorKey =
    status === "none"
      ? "notSubmitted"
      : status === "assigned"
        ? "pending"
        : status === "retake"
          ? "rejected"
          : status;
  return (
    <View style={[styles.statusBanner, { backgroundColor: colors.statusBg[colorKey] }]}>
      <Ionicons
        name={
          status === "approved"
            ? "checkmark-circle"
            : status === "rejected" || status === "retake"
              ? "alert-circle"
              : status === "pending" || status === "assigned"
                ? "time-outline"
                : "clipboard-outline"
        }
        size={22}
        color={colors.status[colorKey]}
      />
      <View style={{ flex: 1 }}>
        <Text style={[styles.statusTitle, { color: colors.status[colorKey] }]}>
          {meta.label}
        </Text>
        <Text style={styles.statusNote}>{meta.note}</Text>
        {submission?.submittedAt ? (
          <Text style={styles.statusNote}>Submitted {formatDate(submission.submittedAt)}</Text>
        ) : null}
        {status === "rejected" && submission?.reviewNote ? (
          <Text style={[styles.statusNote, { color: colors.status.rejected }]}>
            Reviewer: {submission.reviewNote}
          </Text>
        ) : null}
      </View>
    </View>
  );
}

function WindowBanner({ submission }: { submission: OnboardingSubmission | null }) {
  if (!submission?.startDate && !submission?.dueDate) return null;
  const now = new Date();
  const start = submission.startDate ? new Date(submission.startDate) : null;
  const due = submission.dueDate ? new Date(submission.dueDate) : null;
  const overdue =
    due && now.getTime() > due.getTime() && submission.status !== "approved";
  const upcoming = start && now.getTime() < start.getTime();
  return (
    <View style={styles.windowBanner}>
      <View style={styles.windowRow}>
        <Ionicons name="calendar-outline" size={18} color={colors.info} />
        <Text style={styles.windowTitle}>Your onboarding window</Text>
      </View>
      <Text style={styles.windowText}>
        {formatDay(submission.startDate)} to {formatDay(submission.dueDate)}
      </Text>
      {overdue ? (
        <Text style={[styles.windowText, styles.windowWarn]}>Past due date — please submit.</Text>
      ) : null}
      {upcoming && !overdue ? (
        <Text style={styles.windowText}>Starts {formatDay(submission.startDate)}</Text>
      ) : null}
      <Text style={styles.windowText}>Attempt {submission.attempt || 1}</Text>
    </View>
  );
}

function AnswerBreakdown({ answers }: { answers: OnboardingAnswers }) {
  return (
    <View style={styles.answerWrap}>
      {SECTIONS.map((section) => {
        const done = section.questions.filter((q) => answers[q.key]).length;
        return (
          <View key={section.title} style={styles.answerSection}>
            <View style={styles.answerSectionHeader}>
              <Text style={styles.answerSectionTitle}>{section.title}</Text>
              <Text style={styles.answerSectionCount}>
                {done}/{section.questions.length}
              </Text>
            </View>
            {section.questions.map((q) => {
              const yes = Boolean(answers[q.key]);
              const reason = (answers.reasons?.[q.key] || "").trim();
              return (
                <View key={q.key} style={styles.answerRow}>
                  <Ionicons
                    name={yes ? "checkmark-circle" : reason ? "alert-circle" : "ellipse-outline"}
                    size={16}
                    color={yes ? colors.success : reason ? colors.status.pending : colors.gray[300]}
                  />
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.answerLabel, !yes && styles.answerLabelTodo]}>
                      {q.label}
                      {q.optional ? " (optional)" : ""}
                    </Text>
                    {!yes && reason ? (
                      <Text style={styles.answerReason}>{reason}</Text>
                    ) : null}
                  </View>
                </View>
              );
            })}
          </View>
        );
      })}
    </View>
  );
}

function ReviewCard({
  item,
  note,
  busy,
  onNoteChange,
  onReview,
}: {
  item: OnboardingSubmission;
  note: string;
  busy: boolean;
  onNoteChange: (value: string) => void;
  onReview: (action: "approve" | "reject" | "retake") => void;
}) {
  const [answersOpen, setAnswersOpen] = useState(true);
  const checked = Object.entries(item.answers || {}).filter(
    ([key, value]) => key !== "note" && key !== "reasons" && value === true,
  ).length;
  const requiredDone = REQUIRED_KEYS.filter((key) => item.answers?.[key]).length;
  const reasonEntries = Object.entries(item.answers?.reasons || {}).filter(
    ([, value]) => typeof value === "string" && value.trim().length > 0,
  );
  return (
    <View style={styles.reviewCard}>
      <View style={styles.reviewHeaderRow}>
        <View style={{ flex: 1 }}>
          <Text style={styles.reviewName}>{item.userName || "Admin"}</Text>
          <Text style={styles.reviewEmail}>{item.userEmail}</Text>
        </View>
        {item.attempt > 0 ? (
          <View style={styles.attemptPill}>
            <Text style={styles.attemptText}>Attempt {item.attempt}</Text>
          </View>
        ) : null}
      </View>
      <Text style={styles.reviewMeta}>
        Submitted {formatDate(item.submittedAt)} · {requiredDone}/{REQUIRED_KEYS.length} required
        done · {checked} ticks
      </Text>

      <TouchableOpacity
        accessibilityRole="button"
        accessibilityState={{ expanded: answersOpen }}
        onPress={() => setAnswersOpen((open) => !open)}
        style={styles.answersToggle}
        activeOpacity={0.7}
      >
        <Ionicons
          name={answersOpen ? "chevron-up" : "chevron-down"}
          size={15}
          color={colors.info}
        />
        <Text style={styles.answersToggleText}>
          {answersOpen ? "Hide answers" : "View answers"}
        </Text>
      </TouchableOpacity>

      {answersOpen ? <AnswerBreakdown answers={item.answers} /> : null}

      {item.answers?.note ? (
        <View style={styles.reviewNoteBox}>
          <Text style={styles.reviewNoteLabel}>Note from submitter</Text>
          <Text style={styles.reviewNoteText}>{item.answers.note}</Text>
        </View>
      ) : null}
      {reasonEntries.length && !answersOpen ? (
        <View style={styles.reviewNoteBox}>
          <Text style={styles.reviewNoteLabel}>Reasons</Text>
          {reasonEntries.map(([key, value]) => (
            <Text key={key} style={styles.reviewNoteText}>
              {QUESTION_LABELS[key] || key}: {value}
            </Text>
          ))}
        </View>
      ) : null}
      <TextInput
        value={note}
        onChangeText={onNoteChange}
        placeholder="Note for the submitter (optional)"
        placeholderTextColor={colors.gray[400]}
        style={styles.reviewInput}
        multiline
        numberOfLines={3}
        textAlignVertical="top"
        editable={!busy}
      />
      <View style={styles.reviewActions}>
        <View style={{ flex: 1 }}>
          <PrimaryButton
            label="Approve"
            icon="checkmark-circle"
            size="sm"
            loading={busy}
            disabled={busy}
            onPress={() => onReview("approve")}
          />
        </View>
        <TouchableOpacity
          accessibilityRole="button"
          disabled={busy}
          style={[styles.rejectButton, busy && styles.buttonDisabled]}
          onPress={() => onReview("reject")}
        >
          <Ionicons name="close-circle-outline" size={16} color={colors.status.rejected} />
          <Text style={styles.rejectText}>Request changes</Text>
        </TouchableOpacity>
      </View>
      <TouchableOpacity
        accessibilityRole="button"
        disabled={busy}
        style={[styles.retakeButton, busy && styles.buttonDisabled]}
        onPress={() => onReview("retake")}
      >
        <Ionicons name="refresh-outline" size={16} color={colors.info} />
        <Text style={styles.retakeText}>Require full retake</Text>
      </TouchableOpacity>
    </View>
  );
}

type ApproverTab = "me" | "assign" | "approvals";

export default function OnboardingInductionScreen() {
  const [user, setUser] = useState<User | null>(null);
  const [submission, setSubmission] = useState<OnboardingSubmission | null>(null);
  const [canApprove, setCanApprove] = useState(false);
  const [queue, setQueue] = useState<OnboardingSubmission[]>([]);
  const [reviewNotes, setReviewNotes] = useState<Record<string, string>>({});
  const [reviewingId, setReviewingId] = useState<string | null>(null);
  const [adminRows, setAdminRows] = useState<AdminOnboardingRow[]>([]);
  const [assignDrafts, setAssignDrafts] = useState<
    Record<string, { startDate: string; dueDate: string }>
  >({});
  const [assigningId, setAssigningId] = useState<string | null>(null);
  const [expandedAssignId, setExpandedAssignId] = useState<string | null>(null);
  const [assignQuery, setAssignQuery] = useState("");
  const [tab, setTab] = useState<ApproverTab | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const draftKey = user?.id
    ? `onboarding-induction:draft:${user.id}`
    : "onboarding-induction:draft:pending";
  const [answers, setAnswers, clearDraft] = usePersistentFormState<OnboardingAnswers>(
    draftKey,
    emptyOnboardingAnswers(),
  );
  const [openReasonKeys, setOpenReasonKeys] = useState<Record<string, boolean>>({});

  useEffect(() => {
    let alive = true;
    getSession()
      .then((session) => {
        if (!alive) return;
        const sessionUser = session?.user || null;
        setUser(sessionUser);
        if (!sessionUser?.id) setLoading(false);
      })
      .catch(() => {
        if (!alive) return;
        setUser(null);
        setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, []);

  const load = useCallback(async () => {
    try {
      const result = await onboardingApi.get();
      setCanApprove(result.canApprove);
      setSubmission(result.data);
      if (result.data) {
        setAnswers({ ...emptyOnboardingAnswers(), ...result.data.answers });
      }
      if (result.canApprove) {
        const [pending, admins] = await Promise.all([
          onboardingApi.queue(),
          onboardingApi.admins(),
        ]);
        setQueue(pending.data);
        setAdminRows(admins.data);
        return { pending: pending.data.length };
      }
    } catch (error: any) {
      Alert.alert("Could not load", error?.message || "Please try again.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [setAnswers]);

  useEffect(() => {
    if (!user?.id) return;
    const timer = setTimeout(() => {
      void load();
    }, 0);
    return () => clearTimeout(timer);
  }, [load, user?.id]);

  const toggle = (key: BooleanAnswerKey) => {
    const willCheck = !answers[key];
    setAnswers((prev) => {
      const reasons = { ...(prev.reasons || {}) };
      if (willCheck) delete reasons[key];
      return { ...prev, [key]: willCheck, reasons };
    });
    if (willCheck) {
      setOpenReasonKeys((prev) => ({ ...prev, [key]: false }));
    }
  };

  const toggleReason = (key: BooleanAnswerKey) => {
    setOpenReasonKeys((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const changeReason = (key: BooleanAnswerKey, value: string) => {
    setAnswers((prev) => ({
      ...prev,
      reasons: { ...(prev.reasons || {}), [key]: value },
    }));
  };

  const handleSubmit = async () => {
    if (submission?.status === "pending" || submission?.status === "approved") return;
    setSubmitting(true);
    try {
      const result = await onboardingApi.submit(answers);
      setSubmission(result.data);
      if (result.data?.answers) {
        setAnswers({ ...emptyOnboardingAnswers(), ...result.data.answers });
      }
      Alert.alert(
        "Submitted",
        "Your onboarding and induction has been sent for approval.",
      );
      try {
        await clearDraft();
      } catch {}
      if (canApprove) void load().catch(() => {});
    } catch (error: any) {
      Alert.alert("Could not submit", error?.message || "Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  const mergeRow = (data: OnboardingSubmission) => {
    setAdminRows((prev) =>
      prev.map((row) =>
        row.userId === data.userId
          ? {
              ...row,
              startDate: data.startDate,
              dueDate: data.dueDate,
              status: data.status,
              attempt: data.attempt,
              submittedAt: data.submittedAt,
              submissionId: data.id,
            }
          : row,
      ),
    );
  };

  const handleAssign = async (row: AdminOnboardingRow) => {
    const draft = assignDrafts[row.userId] || {
      startDate: toDateInput(row.startDate),
      dueDate: toDateInput(row.dueDate),
    };
    if (!isDateInput(draft.startDate) || !isDateInput(draft.dueDate)) {
      Alert.alert("Choose both dates", "Pick a start date and a due date.");
      return;
    }
    if (draft.startDate > draft.dueDate) {
      Alert.alert("Invalid dates", "Start date must be on or before the due date.");
      return;
    }
    setAssigningId(row.userId);
    try {
      const result = await onboardingApi.assign(
        row.userId,
        draft.startDate,
        draft.dueDate,
      );
      mergeRow(result.data);
      if (row.userId === user?.id) setSubmission(result.data);
      Alert.alert("Dates saved", "The admin has been notified.");
    } catch (error: any) {
      Alert.alert("Could not save dates", error?.message || "Please try again.");
    } finally {
      setAssigningId(null);
    }
  };

  const handleRetake = async (row: AdminOnboardingRow) => {
    if (!row.submissionId) return;
    setReviewingId(row.submissionId);
    try {
      const result = await onboardingApi.review(
        row.submissionId,
        "retake",
        reviewNotes[row.userId] || "",
      );
      mergeRow(result.data);
      setQueue((prev) => prev.filter((entry) => entry.id !== row.submissionId));
      if (row.userId === user?.id) setSubmission(result.data);
      Alert.alert("Retake required", "The admin has been notified.");
    } catch (error: any) {
      Alert.alert("Could not request retake", error?.message || "Please try again.");
    } finally {
      setReviewingId(null);
    }
  };

  const handleReview = async (
    item: OnboardingSubmission,
    action: "approve" | "reject" | "retake",
  ) => {
    setReviewingId(item.id);
    try {
      const result = await onboardingApi.review(
        item.id,
        action,
        reviewNotes[item.id] || "",
      );
      setQueue((prev) => prev.filter((entry) => entry.id !== item.id));
      mergeRow(result.data);
      if (item.userId === user?.id) setSubmission(result.data);
      Alert.alert(
        action === "approve"
          ? "Approved"
          : action === "retake"
            ? "Retake required"
            : "Sent back",
        action === "approve"
          ? "The admin has been notified."
          : action === "retake"
            ? "The admin must review and submit again."
            : "The admin has been asked to review and resubmit.",
      );
    } catch (error: any) {
      Alert.alert("Could not review", error?.message || "Please try again.");
    } finally {
      setReviewingId(null);
    }
  };

  const addressedRequired = REQUIRED_KEYS.filter(
    (key) => answers[key] || Boolean(answers.reasons?.[key]?.trim()),
  ).length;
  const progress = Math.round((addressedRequired / REQUIRED_KEYS.length) * 100);
  const canSubmit = addressedRequired === REQUIRED_KEYS.length;
  // Once submitted it sits with the approver; locking the CTA stops a second
  // submission while it is under review or already approved.
  const submitLocked =
    submission?.status === "pending" || submission?.status === "approved";

  const visibleRows = useMemo(() => {
    const query = assignQuery.trim().toLowerCase();
    return adminRows
      .filter(
        (row) =>
          !query ||
          (row.userName || "").toLowerCase().includes(query) ||
          (row.userEmail || "").toLowerCase().includes(query),
      )
      .sort((a, b) => {
        const orderDiff =
          (ROW_ORDER[a.status || "none"] ?? 0) - (ROW_ORDER[b.status || "none"] ?? 0);
        if (orderDiff !== 0) return orderDiff;
        return (a.userName || a.userEmail).localeCompare(b.userName || b.userEmail);
      });
  }, [adminRows, assignQuery]);

  const showTabs = canApprove;
  const activeTab: ApproverTab = showTabs
    ? tab ?? (queue.length ? "approvals" : "me")
    : "me";

  return (
    <SafeAreaView style={styles.safeArea}>
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.flex}
      >
        <BoardHeader title="Onboarding & Induction" />
        {!user?.id && !loading ? (
          <View style={styles.centered}>
            <Ionicons name="person-circle-outline" size={40} color={colors.muted} />
            <Text style={styles.signInText}>Please sign in to view onboarding.</Text>
          </View>
        ) : loading ? (
          <View style={styles.centered}>
            <ActivityIndicator size="large" color={colors.info} />
          </View>
        ) : (
          <ScrollView
            keyboardShouldPersistTaps="handled"
            keyboardDismissMode="none"
            automaticallyAdjustKeyboardInsets
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={() => {
                  setRefreshing(true);
                  void load();
                }}
              />
            }
            contentContainerStyle={styles.content}
          >
            {showTabs ? (
              <View style={styles.segments}>
                {(
                  [
                    { key: "me", label: "My induction" },
                    { key: "assign", label: "Assign" },
                    { key: "approvals", label: "Approvals" },
                  ] as { key: ApproverTab; label: string }[]
                ).map((item) => {
                  const active = activeTab === item.key;
                  const badge =
                    item.key === "approvals" && queue.length > 0 ? queue.length : null;
                  return (
                    <TouchableOpacity
                      key={item.key}
                      accessibilityRole="tab"
                      accessibilityState={{ selected: active }}
                      onPress={() => setTab(item.key)}
                      activeOpacity={0.7}
                      style={[styles.segmentBtn, active && styles.segmentBtnOn]}
                    >
                      <Text style={[styles.segmentText, active && styles.segmentTextOn]}>
                        {item.label}
                      </Text>
                      {badge ? (
                        <View style={styles.segmentBadge}>
                          <Text style={styles.segmentBadgeText}>{badge}</Text>
                        </View>
                      ) : null}
                    </TouchableOpacity>
                  );
                })}
              </View>
            ) : null}

            {activeTab === "me" ? (
              <>
                <Text style={styles.intro}>
                  Tick each statement you have completed, or add a reason where you could not.
                  Your answers save as you go.
                </Text>

                <StatusBanner submission={submission} />
                <WindowBanner submission={submission} />

                <View style={styles.progressCard}>
                  <View style={styles.progressHeader}>
                    <Text style={styles.progressTitle}>Getting started checklist</Text>
                    <Text style={styles.progressValue}>{progress}%</Text>
                  </View>
                  <View style={styles.progressTrack}>
                    <View style={[styles.progressFill, { width: `${progress}%` }]} />
                  </View>
                  <Text style={styles.progressHint}>
                    {addressedRequired} of {REQUIRED_KEYS.length} required items addressed
                  </Text>
                </View>

                {SECTIONS.map((section) => (
                  <ChecklistSection
                    key={section.title}
                    section={section}
                    answers={answers}
                    openReasonKeys={openReasonKeys}
                    onToggle={toggle}
                    onToggleReason={toggleReason}
                    onReasonChange={changeReason}
                  />
                ))}

                <View style={styles.sectionCard}>
                  <Text style={styles.sectionTitle}>Anything else?</Text>
                  <Text style={styles.sectionHint}>Optional note for the approver</Text>
                  <TextInput
                    value={answers.note}
                    onChangeText={(text) => setAnswers((prev) => ({ ...prev, note: text }))}
                    placeholder="For example: I need help finding the minutes."
                    placeholderTextColor={colors.gray[400]}
                    style={styles.noteInput}
                    multiline
                    numberOfLines={4}
                    textAlignVertical="top"
                    autoCapitalize="sentences"
                  />
                  <Text style={styles.autosave}>Draft saved automatically on this device</Text>
                </View>

                <PrimaryButton
                  label={
                    submission?.status === "rejected" || submission?.status === "retake"
                      ? "Resubmit for approval"
                      : "Submit for approval"
                  }
                  icon="send-outline"
                  loading={submitting}
                  disabled={!canSubmit || submitting || submitLocked}
                  onPress={() => void handleSubmit()}
                />
                {submitLocked ? (
                  <Text style={styles.submitHint}>
                    {submission?.status === "approved"
                      ? "Your onboarding and induction has been approved."
                      : "Submitted and waiting for the approver — you can submit again once it is reviewed."}
                  </Text>
                ) : !canSubmit ? (
                  <Text style={styles.submitHint}>
                    Tick each required item or add a reason above to submit.
                  </Text>
                ) : null}
              </>
            ) : null}

            {activeTab === "assign" ? (
              <View>
                <Text style={styles.reviewSubheading}>
                  Set the onboarding window for each admin, then track where everyone is.
                </Text>
                <View style={styles.searchBox}>
                  <Ionicons name="search-outline" size={16} color={colors.muted} />
                  <TextInput
                    value={assignQuery}
                    onChangeText={setAssignQuery}
                    placeholder="Search admins by name or email"
                    placeholderTextColor={colors.gray[400]}
                    style={styles.searchInput}
                    autoCapitalize="none"
                    autoCorrect={false}
                  />
                  {assignQuery ? (
                    <TouchableOpacity
                      accessibilityRole="button"
                      accessibilityLabel="Clear search"
                      onPress={() => setAssignQuery("")}
                    >
                      <Ionicons name="close-circle" size={16} color={colors.gray[400]} />
                    </TouchableOpacity>
                  ) : null}
                </View>

                {visibleRows.length === 0 ? (
                  <View style={styles.emptyQueue}>
                    <Ionicons name="people-outline" size={22} color={colors.muted} />
                    <Text style={styles.emptyQueueText}>
                      {adminRows.length === 0 ? "No admin users found" : "No admins match your search"}
                    </Text>
                  </View>
                ) : (
                  visibleRows.map((row) => {
                    const open = expandedAssignId === row.userId;
                    const draft = assignDrafts[row.userId] || {
                      startDate: toDateInput(row.startDate),
                      dueDate: toDateInput(row.dueDate),
                    };
                    const meta = ROW_STATUS[row.status || "none"];
                    const hasWindow = Boolean(row.startDate && row.dueDate);
                    const startDate = isDateInput(draft.startDate)
                      ? new Date(`${draft.startDate}T12:00:00`)
                      : undefined;
                    const dueDate = isDateInput(draft.dueDate)
                      ? new Date(`${draft.dueDate}T12:00:00`)
                      : undefined;
                    return (
                      <View key={row.userId} style={styles.assignCard}>
                        <TouchableOpacity
                          accessibilityRole="button"
                          accessibilityState={{ expanded: open }}
                          activeOpacity={0.7}
                          onPress={() =>
                            setExpandedAssignId(open ? null : row.userId)
                          }
                          style={styles.assignRow}
                        >
                          <View style={{ flex: 1 }}>
                            <Text style={styles.reviewName}>
                              {row.userName || row.userEmail}
                            </Text>
                            <Text style={styles.reviewEmail}>{row.userEmail}</Text>
                            <Text style={styles.assignWindow}>
                              {hasWindow
                                ? `${shortDate(row.startDate)} → ${shortDate(row.dueDate)}`
                                : "No window set"}
                            </Text>
                          </View>
                          <View style={{ alignItems: "flex-end", gap: 6 }}>
                            <View style={[styles.rowPill, { backgroundColor: meta.bg }]}>
                              <Text style={[styles.rowPillText, { color: meta.color }]}>
                                {meta.label}
                              </Text>
                            </View>
                            <Ionicons
                              name={open ? "chevron-up" : "chevron-down"}
                              size={16}
                              color={colors.muted}
                            />
                          </View>
                        </TouchableOpacity>

                        {open ? (
                          <View style={styles.assignBody}>
                            <View style={styles.dateRow}>
                              <DateField
                                label="Start date"
                                value={draft.startDate}
                                maximumDate={dueDate}
                                disabled={assigningId === row.userId}
                                onChange={(value) =>
                                  setAssignDrafts((prev) => ({
                                    ...prev,
                                    [row.userId]: { ...draft, startDate: value },
                                  }))
                                }
                              />
                              <DateField
                                label="Due date"
                                value={draft.dueDate}
                                minimumDate={startDate}
                                disabled={assigningId === row.userId}
                                onChange={(value) =>
                                  setAssignDrafts((prev) => ({
                                    ...prev,
                                    [row.userId]: { ...draft, dueDate: value },
                                  }))
                                }
                              />
                            </View>
                            <View style={styles.assignActions}>
                              <View style={{ flex: 1 }}>
                                <PrimaryButton
                                  label="Save dates"
                                  icon="save-outline"
                                  size="sm"
                                  loading={assigningId === row.userId}
                                  disabled={assigningId === row.userId}
                                  onPress={() => void handleAssign(row)}
                                />
                              </View>
                              {row.submissionId ? (
                                <TouchableOpacity
                                  accessibilityRole="button"
                                  disabled={reviewingId === row.submissionId}
                                  style={[
                                    styles.retakeButton,
                                    styles.retakeInline,
                                    reviewingId === row.submissionId && styles.buttonDisabled,
                                  ]}
                                  onPress={() => void handleRetake(row)}
                                >
                                  <Ionicons name="refresh-outline" size={15} color={colors.info} />
                                  <Text style={styles.retakeText}>Retake</Text>
                                </TouchableOpacity>
                              ) : null}
                            </View>
                          </View>
                        ) : null}
                      </View>
                    );
                  })
                )}
              </View>
            ) : null}

            {activeTab === "approvals" ? (
              <View>
                <Text style={styles.reviewSubheading}>
                  Only the designated approver can review these submissions.
                </Text>
                {queue.length === 0 ? (
                  <View style={styles.emptyQueue}>
                    <Ionicons name="checkmark-done-outline" size={22} color={colors.success} />
                    <Text style={styles.emptyQueueText}>No pending submissions</Text>
                  </View>
                ) : (
                  queue.map((item) => (
                    <ReviewCard
                      key={item.id}
                      item={item}
                      note={reviewNotes[item.id] || ""}
                      busy={reviewingId === item.id}
                      onNoteChange={(value) =>
                        setReviewNotes((prev) => ({ ...prev, [item.id]: value }))
                      }
                      onReview={(action) => void handleReview(item, action)}
                    />
                  ))
                )}
              </View>
            ) : null}

            <View style={{ height: 28 }} />
          </ScrollView>
        )}
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

