import { Circle, G, Line, Rect, Svg, Text as SvgText } from "react-native-svg";
import { colors } from "@/constants/colors";
import type { IncomeMixRow, PerformanceMonth } from "@/services/performance";

export const CHART_INCOME = colors.gold;
export const CHART_EXPENSE = colors.forestDark;
export const MIX_COLORS = ["#13c5dd", "#0B192C", "#0ea5e9", "#f59e0b", "#10b981"];

const GRID = "#EDF1F5";

function compact(value: number): string {
  if (value >= 1_000_000) return `${Math.round(value / 100_000) / 10}m`;
  if (value >= 1_000) return `${Math.round(value / 100) / 10}k`;
  return String(Math.round(value));
}

/** Rounds the axis top to a readable step so bar heights stay meaningful. */
function axis(max: number): { top: number; step: number } {
  const raw = max / 4;
  const step =
    [100, 250, 500, 1_000, 2_500, 5_000, 10_000, 25_000, 50_000].find(
      (s) => s >= raw,
    ) ?? Math.max(100, Math.ceil(raw));
  return { top: Math.max(step, Math.ceil(max / step) * step), step };
}

type BarsProps = {
  months: PerformanceMonth[];
  width: number;
  height?: number;
  selectedMonth?: number | null;
  onSelectMonth?: (month: number) => void;
};

/** Grouped income/expenditure bars, one group per reported month. */
export function IncomeExpenseBars({
  months,
  width,
  height = 200,
  selectedMonth = null,
  onSelectMonth,
}: BarsProps) {
  if (months.length === 0 || width <= 0) return null;

  const PAD = { top: 10, right: 4, bottom: 24, left: 40 };
  const innerW = width - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const max = Math.max(...months.map((m) => Math.max(m.income, m.expenses)), 0);
  const { top, step } = axis(max);
  const groupW = innerW / months.length;
  const barW = Math.min(12, Math.max(5, groupW * 0.26));
  const barGap = Math.min(3, barW * 0.3);

  const ticks: number[] = [];
  for (let value = 0; value <= top; value += step) ticks.push(value);

  const yFor = (value: number) => PAD.top + innerH * (1 - value / top);
  const showLabels = months.length <= 8;
  const hasSelection = selectedMonth !== null;

  return (
    <Svg
      width={width}
      height={height}
      accessibilityLabel={`Income and expenditure for ${months.length} reported months`}
    >
      {ticks.map((tick) => (
        <G key={`grid-${tick}`}>
          <Line
            x1={PAD.left}
            x2={width - PAD.right}
            y1={yFor(tick)}
            y2={yFor(tick)}
            stroke={GRID}
            strokeWidth={1}
          />
          <SvgText
            x={PAD.left - 6}
            y={yFor(tick) + 3}
            fontSize={9}
            fill={colors.muted}
            textAnchor="end"
          >
            {tick === 0 ? "0" : `R${compact(tick)}`}
          </SvgText>
        </G>
      ))}

      {months.map((month, index) => {
        const groupX = PAD.left + index * groupW;
        const centerX = groupX + groupW / 2;
        const totalW = barW * 2 + barGap;
        const incomeX = centerX - totalW / 2;
        const expenseX = incomeX + barW + barGap;
        const incomeY = yFor(month.income);
        const expenseY = yFor(month.expenses);
        const selected = selectedMonth === month.month;
        const dimmed = hasSelection && !selected;

        return (
          <G
            key={`${month.period}-${month.month}`}
            onPress={() => onSelectMonth?.(month.month)}
          >
            {selected ? (
              <Rect
                x={groupX + 1}
                y={PAD.top}
                width={Math.max(1, groupW - 2)}
                height={innerH}
                fill={`${CHART_INCOME}14`}
                rx={4}
              />
            ) : null}
            <Rect
              x={incomeX}
              y={incomeY}
              width={barW}
              height={Math.max(1.5, PAD.top + innerH - incomeY)}
              rx={2.5}
              fill={CHART_INCOME}
              opacity={dimmed ? 0.35 : 1}
            />
            <Rect
              x={expenseX}
              y={expenseY}
              width={barW}
              height={Math.max(1.5, PAD.top + innerH - expenseY)}
              rx={2.5}
              fill={CHART_EXPENSE}
              opacity={dimmed ? 0.35 : 1}
            />
            {(showLabels || index % 2 === 0 || index === months.length - 1) && (
              <SvgText
                x={centerX}
                y={height - 7}
                fontSize={9}
                fill={selected ? colors.forestDark : colors.muted}
                fontFamily={selected ? "Poppins_700Bold" : undefined}
                textAnchor="middle"
              >
                {month.label}
              </SvgText>
            )}
            {/* Invisible full-column hit area so tapping anywhere selects it. */}
            <Rect
              x={groupX}
              y={PAD.top}
              width={groupW}
              height={innerH}
              fill="rgba(0,0,0,0.001)"
            />
          </G>
        );
      })}
    </Svg>
  );
}

type PieProps = {
  rows: IncomeMixRow[];
  size?: number;
};

/** Donut of the year's income mix with the total in the middle. */
export function IncomeMixPie({ rows, size = 152 }: PieProps) {
  const total = rows.reduce((sum, row) => sum + row.value, 0);
  if (total <= 0) return null;

  const stroke = 24;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const prefix = (end: number) =>
    rows
      .slice(0, end)
      .reduce((sum, row) => sum + (row.value / total) * circumference, 0);

  return (
    <Svg
      width={size}
      height={size}
      accessibilityLabel={`Income mix across ${rows.length} sources`}
    >
      <Circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke={GRID}
        strokeWidth={stroke}
      />
      {rows.map((row, index) => {
        const length = (row.value / total) * circumference;
        const dash = Math.max(length - 1.5, 0.5);
        return (
          <Circle
            key={row.key}
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={MIX_COLORS[index % MIX_COLORS.length]}
            strokeWidth={stroke}
            strokeDasharray={`${dash} ${circumference - dash}`}
            strokeDashoffset={-prefix(index)}
            rotation={-90}
            origin={`${size / 2}, ${size / 2}`}
          />
        );
      })}
      <SvgText
        x={size / 2}
        y={size / 2 - 2}
        fontSize={16}
        fontWeight="700"
        fill={colors.forestDark}
        textAnchor="middle"
      >
        {`R${compact(total)}`}
      </SvgText>
      <SvgText
        x={size / 2}
        y={size / 2 + 14}
        fontSize={9}
        fill={colors.muted}
        textAnchor="middle"
      >
        INCOME
      </SvgText>
    </Svg>
  );
}
