import { useEffect, useState } from "react";
import { cachedFetch } from "@/services/cache";

/**
 * Storefront catalogue — the app's access layer for GET /api/store.
 *
 * The admin-managed backend owns every product (price, stock, gallery,
 * sizes); screens read through the hooks below rather than a bundled copy,
 * so what the store tab shows is always what the admin published.
 */

export const STORE_CATEGORIES = [
  "Apparel",
  "Accessories",
  "Home & Study",
] as const;

export type StoreCategory = (typeof STORE_CATEGORIES)[number];

export type StoreProduct = {
  _id?: string;
  id: string;
  name: string;
  blurb: string;
  category: StoreCategory;
  /** List price in ZAR. */
  price: number;
  /** Sale price when the admin has put the item on offer. */
  offerPrice: number | null;
  /** Cover photo used by the grid and the detail hero. */
  image: string;
  /** Extra gallery shots — the thumbnails under the main image. */
  images: string[];
  /** Available sizes for apparel; empty for everything else. */
  sizes: string[];
  /** "About this product" bullets. */
  details: string[];
  inStock: boolean;
  rating: number | null;
  active: boolean;
};

type ApiRow = {
  _id?: string;
  id?: string;
  name?: string;
  blurb?: string;
  category?: string;
  price?: number;
  offerPrice?: number | null;
  image?: string;
  images?: string[];
  sizes?: string[];
  details?: string[];
  inStock?: boolean;
  rating?: number | null;
  active?: boolean;
};

const SITE_URL = "https://relateworld.org";

/**
 * Admins may store site-relative paths (`/images/store/tee.png`) so the
 * website can share them — the app has no origin, so those resolve against
 * the public site instead of showing a blank tile.
 */
export function resolveImageUrl(src?: string | null): string {
  const raw = (src || "").trim();
  if (!raw) return "";
  if (/^(https?:|file:|data:)/i.test(raw)) return raw;
  return `${SITE_URL}${raw.startsWith("/") ? raw : `/${raw}`}`;
}

function toProduct(row: ApiRow): StoreProduct | null {
  if (!row.id || !row.name) return null;
  if (typeof row.price !== "number" || !Number.isFinite(row.price)) return null;
  const category = (STORE_CATEGORIES as readonly string[]).includes(
    row.category || "",
  )
    ? (row.category as StoreCategory)
    : "Accessories";

  return {
    _id: row._id,
    id: row.id,
    name: row.name,
    blurb: row.blurb || "",
    category,
    price: row.price,
    offerPrice:
      typeof row.offerPrice === "number" && row.offerPrice >= 0
        ? row.offerPrice
        : null,
    image: resolveImageUrl(row.image),
    images: (row.images || []).map(resolveImageUrl).filter(Boolean),
    sizes: row.sizes || [],
    details: row.details || [],
    inStock: row.inStock !== false,
    rating: typeof row.rating === "number" ? row.rating : null,
    active: row.active === true || row.active == null,
  };
}

export async function fetchStoreProducts(forceRefresh = false): Promise<StoreProduct[]> {
  const json = await cachedFetch<unknown>("/api/store", {
    cacheTtl: 60_000,
    forceRefresh,
  });
  const rows = (json as { data?: unknown } | null)?.data;
  if (!Array.isArray(rows)) return [];
  const products = rows
    .map((row) => toProduct(row as ApiRow))
    .filter((p): p is StoreProduct => p !== null);
  return products.filter((product) => product.active);
}

/** Single product for the detail screen; throws when the id is unknown. */
export async function fetchStoreProduct(id: string): Promise<StoreProduct | null> {
  const products = await fetchStoreProducts();
  return products.find((p) => p.id === id) ?? null;
}

export type CreateStoreProductInput = {
  name: string;
  blurb: string;
  category: StoreCategory;
  price: number;
  offerPrice: number | null;
  image: string;
  images: string[];
  sizes: string[];
  details: string[];
  inStock: boolean;
  active: boolean;
};

export async function createStoreProduct(
  input: CreateStoreProductInput,
): Promise<StoreProduct> {
  const json = await cachedFetch<unknown>("/api/admin/store", {
    method: "POST",
    body: JSON.stringify(input),
  });
  const product = toProduct(json as ApiRow);
  if (!product) throw new Error("The product was created but could not be read.");
  return product;
}

export async function fetchAdminStoreProducts(): Promise<StoreProduct[]> {
  const json = await cachedFetch<unknown>("/api/admin/store", { cacheTtl: 0 });
  const rows = (json as { data?: unknown } | null)?.data;
  if (!Array.isArray(rows)) return [];
  return rows
    .map((row) => toProduct(row as ApiRow))
    .filter((product): product is StoreProduct => product !== null);
}

export async function updateStoreProduct(
  mongoId: string,
  input: CreateStoreProductInput,
): Promise<StoreProduct> {
  const json = await cachedFetch<unknown>(`/api/admin/store/${mongoId}`, {
    method: "PATCH",
    body: JSON.stringify(input),
  });
  const product = toProduct(json as ApiRow);
  if (!product) throw new Error("The product was updated but could not be read.");
  return product;
}

export async function deleteStoreProduct(mongoId: string): Promise<void> {
  await cachedFetch(`/api/admin/store/${mongoId}`, { method: "DELETE" });
}

/** The price the buyer actually pays (offer price when one is set). */
export function effectivePrice(product: StoreProduct): number {
  return product.offerPrice ?? product.price;
}

export function formatPrice(value: number): string {
  return `R ${Math.round(value)}`;
}

const STORE_ERROR =
  "The store couldn't be loaded — check your connection and try again.";

/** Product grid data; empty until the request resolves. */
export function useStoreProducts(): {
  products: StoreProduct[];
  loading: boolean;
  error: string | null;
  refreshing: boolean;
  refresh: () => Promise<void>;
} {
  const [products, setProducts] = useState<StoreProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetchStoreProducts()
      .then((data) => {
        if (!cancelled) setProducts(data);
      })
      .catch(() => {
        if (!cancelled) {
          setProducts([]);
          setError(STORE_ERROR);
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const refresh = async () => {
    setRefreshing(true);
    setError(null);
    try {
      const data = await fetchStoreProducts(true);
      setProducts(data);
    } catch {
      setError(STORE_ERROR);
    } finally {
      setRefreshing(false);
    }
  };

  return { products, loading, error, refreshing, refresh };
}

/** One product by id (used by the product detail screen). */
export function useStoreProduct(id?: string): {
  product: StoreProduct | null;
  loading: boolean;
  error: string | null;
} {
  const [product, setProduct] = useState<StoreProduct | null>(null);
  const [loading, setLoading] = useState(!!id);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    fetchStoreProduct(id)
      .then((p) => {
        if (cancelled) return;
        setProduct(p);
        setError(p ? null : "That product is no longer available.");
      })
      .catch(() => {
        if (cancelled) return;
        setProduct(null);
        setError(STORE_ERROR);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  return { product, loading, error };
}
