import { Ionicons } from "@expo/vector-icons";
import { useState } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
const MONTH_SHORT = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

type Mode = "day" | "month" | "year";

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

const sameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

type Props = {
  value?: Date | null;
  onSelect: (d: Date) => void;
  minimumDate?: Date;
  maximumDate?: Date;
};

export default function InlineCalendar({
  value,
  onSelect,
  minimumDate,
  maximumDate,
}: Props) {
  const today = new Date();
  const min = minimumDate ? startOfDay(minimumDate) : null;
  const max = maximumDate ? startOfDay(maximumDate) : null;
  const minYear = min ? min.getFullYear() : null;
  const maxYear = max ? max.getFullYear() : null;

  const initial = value && !isNaN(value.getTime()) ? new Date(value) : new Date();
  const [viewYear, setViewYear] = useState(initial.getFullYear());
  const [viewMonth, setViewMonth] = useState(initial.getMonth());
  const [mode, setMode] = useState<Mode>("day");

  // Day-mode month navigation (clamped by min/max).
  const canPrevMonth =
    !min || new Date(viewYear, viewMonth - 1, 1) >= new Date(min.getFullYear(), min.getMonth(), 1);
  const canNextMonth =
    !max || new Date(viewYear, viewMonth + 1, 1) <= new Date(max.getFullYear(), max.getMonth(), 1);

  const goPrevMonth = () => {
    if (!canPrevMonth) return;
    if (viewMonth === 0) {
      setViewYear((y) => y - 1);
      setViewMonth(11);
    } else setViewMonth((m) => m - 1);
  };

  const goNextMonth = () => {
    if (!canNextMonth) return;
    if (viewMonth === 11) {
      setViewYear((y) => y + 1);
      setViewMonth(0);
    } else setViewMonth((m) => m + 1);
  };

  // Year-mode navigation (paged by decade so no scrolling is needed).
  const decadeStart = viewYear - (viewYear % 10);
  const years: number[] = [];
  for (let i = -1; i <= 10; i++) years.push(decadeStart + i);
  const canPrevDecade = minYear === null || decadeStart - 10 >= minYear;
  const canNextDecade = maxYear === null || decadeStart + 10 <= maxYear;

  const yearMinReached = minYear !== null && viewYear <= minYear;
  const yearMaxReached = maxYear !== null && viewYear >= maxYear;

  const yearDisabled = (y: number) =>
    (minYear !== null && y < minYear) || (maxYear !== null && y > maxYear);

  const monthDisabled = (i: number) => {
    if (min && viewYear === min.getFullYear() && i < min.getMonth()) return true;
    if (max && viewYear === max.getFullYear() && i > max.getMonth()) return true;
    return false;
  };

  const jumpToday = () => {
    setViewYear(today.getFullYear());
    setViewMonth(today.getMonth());
  };

  const offset = new Date(viewYear, viewMonth, 1).getDay();
  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();

  const cells: (number | null)[] = [];
  for (let i = 0; i < 42; i++) {
    const day = i - offset + 1;
    cells.push(day >= 1 && day <= daysInMonth ? day : null);
  }

  const handleDay = (day: number) => {
    const hasValue = value && !isNaN(value.getTime());
    const h = hasValue ? value.getHours() : 12;
    const m = hasValue ? value.getMinutes() : 0;
    onSelect(new Date(viewYear, viewMonth, day, h, m, 0, 0));
  };

  const headerBtnProps = (active: boolean, label: string, onPress: () => void) => ({
    style: [styles.headerBtn, !active && styles.headerBtnDisabled],
    onPress,
    disabled: !active,
    accessibilityLabel: label,
  });

  return (
    <View style={styles.container}>
      {mode === "year" ? (
        <>
          <View style={styles.header}>
            <TouchableOpacity
              {...headerBtnProps(canPrevDecade, "Previous decade", () => setViewYear((y) => y - 10))}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <View style={styles.headerTitleWrap}>
              <Text style={styles.headerTitle}>Select year</Text>
            </View>
            <TouchableOpacity
              {...headerBtnProps(canNextDecade, "Next decade", () => setViewYear((y) => y + 10))}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.headerBtn}
              onPress={() => setMode("month")}
              activeOpacity={0.7}
              accessibilityLabel="Close year selector"
            >
              <Ionicons name="close" size={16} color={colors.forestDark} />
            </TouchableOpacity>
          </View>
          <View style={styles.monthGrid}>
            {years.map((y) => {
              const disabled = yearDisabled(y);
              const selected = y === viewYear;
              return (
                <View key={y} style={styles.monthCell}>
                  <TouchableOpacity
                    style={[
                      styles.monthBtn,
                      selected && styles.monthBtnSelected,
                      disabled && styles.monthBtnDisabled,
                    ]}
                    onPress={() => {
                      setViewYear(y);
                      setMode("month");
                    }}
                    disabled={disabled}
                    activeOpacity={0.7}
                  >
                    <Text
                      style={[
                        styles.monthBtnText,
                        selected && styles.monthBtnTextSelected,
                        disabled && styles.monthBtnTextDisabled,
                      ]}
                    >
                      {y}
                    </Text>
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        </>
      ) : mode === "month" ? (
        <>
          <View style={styles.header}>
            <TouchableOpacity
              {...headerBtnProps(!yearMinReached, "Previous year", () => setViewYear((y) => y - 1))}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.headerTitleWrap}
              onPress={() => setMode("year")}
              activeOpacity={0.7}
              accessibilityLabel="Choose year"
            >
              <Text style={styles.headerTitle}>{viewYear}</Text>
            </TouchableOpacity>
            <TouchableOpacity
              {...headerBtnProps(!yearMaxReached, "Next year", () => setViewYear((y) => y + 1))}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
            </TouchableOpacity>
          </View>
          <View style={styles.monthGrid}>
            {MONTH_SHORT.map((m, i) => {
              const disabled = monthDisabled(i);
              const selected =
                value &&
                !isNaN(value.getTime()) &&
                viewYear === value.getFullYear() &&
                i === viewMonth;
              return (
                <View key={m} style={styles.monthCell}>
                  <TouchableOpacity
                    style={[
                      styles.monthBtn,
                      selected && styles.monthBtnSelected,
                      disabled && styles.monthBtnDisabled,
                    ]}
                    onPress={() => {
                      setViewMonth(i);
                      setMode("day");
                    }}
                    disabled={disabled}
                    activeOpacity={0.7}
                  >
                    <Text
                      style={[
                        styles.monthBtnText,
                        selected && styles.monthBtnTextSelected,
                        disabled && styles.monthBtnTextDisabled,
                      ]}
                    >
                      {m}
                    </Text>
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        </>
      ) : (
        <>
          <View style={styles.header}>
            <TouchableOpacity
              {...headerBtnProps(canPrevMonth, "Previous month", goPrevMonth)}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-back" size={16} color={colors.forestDark} />
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.headerTitleWrap}
              onPress={() => setMode("month")}
              activeOpacity={0.7}
              accessibilityLabel="Choose month and year"
            >
              <Text style={styles.headerTitle}>
                {MONTHS[viewMonth]} {viewYear}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.todayBtn}
              onPress={jumpToday}
              activeOpacity={0.7}
              accessibilityLabel="Jump to today"
            >
              <Text style={styles.todayText}>Today</Text>
            </TouchableOpacity>
            <TouchableOpacity
              {...headerBtnProps(canNextMonth, "Next month", goNextMonth)}
              activeOpacity={0.7}
            >
              <Ionicons name="chevron-forward" size={16} color={colors.forestDark} />
            </TouchableOpacity>
          </View>

          <View style={styles.weekRow}>
            {WEEKDAYS.map((w) => (
              <Text key={w} style={styles.weekLabel}>
                {w}
              </Text>
            ))}
          </View>

          <View style={styles.grid}>
            {cells.map((day, i) => {
              if (day === null) return <View key={i} style={styles.cell} />;
              const date = new Date(viewYear, viewMonth, day);
              const disabled = !!((min && date < min) || (max && date > max));
              const selected = value && !isNaN(value.getTime()) && sameDay(date, value);
              const isToday = sameDay(date, today);
              return (
                <View key={i} style={styles.cell}>
                  <TouchableOpacity
                    style={[
                      styles.day,
                      selected && styles.daySelected,
                      isToday && !selected && styles.dayToday,
                      disabled && styles.dayDisabled,
                    ]}
                    onPress={() => handleDay(day)}
                    disabled={disabled}
                    activeOpacity={0.7}
                  >
                    <Text
                      style={[
                        styles.dayText,
                        selected && styles.dayTextSelected,
                        disabled && styles.dayTextDisabled,
                      ]}
                    >
                      {day}
                    </Text>
                  </TouchableOpacity>
                </View>
              );
            })}
          </View>
        </>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: 4,
  },
  header: {
    flexDirection: "row",
    alignItems: "center",
    marginBottom: 6,
    gap: 4,
  },
  headerBtn: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: colors.cream,
    alignItems: "center",
    justifyContent: "center",
  },
  headerBtnDisabled: {
    opacity: 0.35,
  },
  headerTitleWrap: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  headerTitle: {
    fontSize: 20,
    fontFamily: fonts.sansBold, fontWeight: "700",
    color: colors.forestDark,
    letterSpacing: 0.2,
  },
  todayBtn: {
    paddingHorizontal: 8,
    paddingVertical: 6,
  },
  todayText: {
    fontSize: 12,
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    color: colors.goldDark,
  },
  weekRow: {
    flexDirection: "row",
    marginBottom: 4,
  },
  weekLabel: {
    flex: 1,
    textAlign: "center",
    fontSize: 10.5,
    fontFamily: fonts.sansBold, fontWeight: "700",
    color: colors.muted,
    textTransform: "uppercase",
    letterSpacing: 0.5,
  },
  grid: {
    flexDirection: "row",
    flexWrap: "wrap",
  },
  cell: {
    width: "14.2857%",
    padding: 2,
  },
  day: {
    height: 34,
    borderRadius: 17,
    alignItems: "center",
    justifyContent: "center",
  },
  daySelected: {
    backgroundColor: colors.gold,
  },
  dayToday: {
    borderWidth: 1.5,
    borderColor: colors.goldDark,
  },
  dayDisabled: {
    opacity: 0.35,
  },
  dayText: {
    fontSize: 13,
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    color: colors.forestDark,
  },
  dayTextSelected: {
    color: colors.white,
    fontFamily: fonts.sansBold, fontWeight: "700",
  },
  dayTextDisabled: {
    color: colors.muted,
  },
  monthGrid: {
    flexDirection: "row",
    flexWrap: "wrap",
  },
  monthCell: {
    width: "33.333%",
    padding: 3,
  },
  monthBtn: {
    paddingVertical: 10,
    borderRadius: 9,
    backgroundColor: colors.cream,
    alignItems: "center",
    justifyContent: "center",
  },
  monthBtnSelected: {
    backgroundColor: colors.gold,
  },
  monthBtnDisabled: {
    opacity: 0.35,
  },
  monthBtnText: {
    fontSize: 13,
    fontFamily: fonts.sansSemiBold, fontWeight: "600",
    color: colors.forestDark,
  },
  monthBtnTextSelected: {
    color: colors.white,
    fontFamily: fonts.sansBold, fontWeight: "700",
  },
  monthBtnTextDisabled: {
    color: colors.muted,
  },
});
