import {
  createClient,
  type RealtimeChannel,
  type SupabaseClient,
} from "@supabase/supabase-js";
import { getSession } from "./auth";
import { clubChatNotifyApi } from "./club-chat";
import { SUPABASE_ANON_KEY, SUPABASE_URL } from "./config";
import { getDeviceId } from "./device-id";

/**
 * Club chat — Supabase is the only store for chat messages.
 *
 * Rows live in the `club_chat_messages` table; live delivery is Supabase
 * Realtime (Postgres INSERT changes on that table). A channel is opened when
 * the chat screen gains focus and removed the moment it blurs, so each device
 * holds at most one realtime connection (the free tier caps concurrent
 * connections). Images never enter Supabase — they go to Cloudinary and only
 * the URL is stored on the row.
 *
 * Requires SUPABASE_URL + publishable/anon key and the table/RLS/publication
 * setup from `mobile_app/supabase/club-chat.sql` run in the Supabase SQL editor.
 */

export type ChatRealtimeReply = {
  id?: string;
  sender?: string;
  text?: string;
};

export type ChatRealtimeMessage = {
  id: string;
  text?: string;
  image?: string;
  senderId: string;
  senderName: string;
  at: number;
  createdAt?: string;
  edited?: boolean;
  replyTo?: ChatRealtimeReply;
};

/** One member's emoji reaction on one message (max one per member). */
export type ChatRealtimeReaction = {
  messageId: string;
  userId: string;
  emoji: string;
};

export type ChatFeatures = {
  replies: boolean;
  edits: boolean;
  reactions: boolean;
};

export type ChatPageMeta = {
  hasMore: boolean;
};

export type LoadOlderResult = {
  loaded: number;
  hasMore: boolean;
};

export type ClubChatSubscription = {
  unsubscribe: () => void;
  loadOlder: () => Promise<LoadOlderResult>;
};

export const isChatRealtimeConfigured = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);

const TABLE = "club_chat_messages";
const REACTION_TABLE = "club_chat_reactions";
const PAGE_SIZE = 15;
const REACTION_LIMIT = 1000;

let client: SupabaseClient | null = null;

export function supabase(): SupabaseClient {
  if (!client) {
    client = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: { persistSession: false, autoRefreshToken: false },
      realtime: { disconnectOnEmptyChannelsAfterMs: 0 },
    });
  }
  return client;
}

type ChatRow = {
  id: number | string;
  club_slug: string;
  sender_id: string | null;
  sender_name: string | null;
  body: string | null;
  image_url: string | null;
  created_at: string;
  edited_at?: string | null;
  reply_to_id?: string | null;
  reply_to_sender?: string | null;
  reply_to_preview?: string | null;
};

type ReactionRow = {
  message_id?: string | null;
  user_id?: string | null;
  emoji?: string | null;
};

function toMessage(row: ChatRow): ChatRealtimeMessage {
  const at = Date.parse(row.created_at);
  const replySender = row.reply_to_sender || "";
  const replyText = row.reply_to_preview || "";
  const replyId = row.reply_to_id || "";
  return {
    id: String(row.id),
    text: row.body || undefined,
    image: row.image_url || undefined,
    senderId: row.sender_id || "",
    senderName: row.sender_name || "Member",
    at: Number.isFinite(at) ? at : Date.now(),
    createdAt: row.created_at,
    edited: Boolean(row.edited_at),
    replyTo:
      replyId || replySender || replyText
        ? {
            id: replyId || undefined,
            sender: replySender || undefined,
            text: replyText || undefined,
          }
        : undefined,
  };
}

function toReaction(row: ReactionRow): ChatRealtimeReaction | null {
  const messageId = String(row.message_id ?? "");
  const userId = String(row.user_id ?? "");
  const emoji = String(row.emoji ?? "");
  if (!messageId || !userId || !emoji) return null;
  return { messageId, userId, emoji };
}

function friendlyDbError(message: string): Error {
  if (
    /does not exist|relation|could not find the .* column|schema cache/i.test(
      message,
    )
  ) {
    return new Error(
      "Club chat isn't set up in Supabase yet — run mobile_app/supabase/club-chat.sql in the SQL editor.",
    );
  }
  return new Error(message);
}

async function hasColumn(db: SupabaseClient, column: string): Promise<boolean> {
  const { error } = await db.from(TABLE).select(column).limit(1);
  return !error;
}

const presenceDeviceId = `${Date.now().toString(36)}-${Math.random()
  .toString(36)
  .slice(2, 10)}`;

/**
 * Load the latest 15 messages, then stream new ones and page older history on
 * demand. Returns unsubscribe/load-older helpers for the Realtime channel.
 *
 * Reactions ride the same channel. If the reactions table is missing (the
 * SQL file hasn't been re-run yet) the chat still works — only the reaction
 * chips are disabled.
 */
export function subscribeClubChat(
  slug: string,
  handlers: {
    onMessages: (
      messages: ChatRealtimeMessage[],
      myUid: string,
      meta?: ChatPageMeta,
    ) => void;
    onReactions?: (reactions: ChatRealtimeReaction[]) => void;
    onPresence?: (uids: string[]) => void;
    onFeatures?: (features: ChatFeatures) => void;
    onDeleted?: (id: string) => void;
    onError?: (err: Error) => void;
  },
): ClubChatSubscription {
  const empty: ClubChatSubscription = {
    unsubscribe: () => {},
    loadOlder: async () => ({ loaded: 0, hasMore: false }),
  };
  if (!isChatRealtimeConfigured || !slug) return empty;

  const db = supabase();
  let active = true;
  let messages: ChatRealtimeMessage[] = [];
  let reactions: ChatRealtimeReaction[] = [];
  let myUid = "";
  let hasMore = true;
  let loadingOlder = false;

  let channel: RealtimeChannel | null = null;

  const publish = () => {
    if (active) handlers.onMessages([...messages], myUid, { hasMore });
  };
  const publishReactions = () => {
    if (active) handlers.onReactions?.([...reactions]);
  };

  (async () => {
    const session = await getSession().catch(() => null);
    if (!active) return;
    myUid = session?.user.id || "";

    channel = db.channel(`club-chat:${slug}`, {
      config: {
        presence: {
          key: myUid ? `${myUid}:${presenceDeviceId}` : presenceDeviceId,
        },
      },
    });
    const activeChannel = channel;
    activeChannel.on("presence", { event: "sync" }, () => {
      if (!active) return;
      const state = activeChannel.presenceState();
      const uids = new Set<string>();
      for (const metas of Object.values(state)) {
        for (const meta of metas as { uid?: unknown }[]) {
          const uid = String(meta?.uid ?? "");
          if (uid) uids.add(uid);
        }
      }
      handlers.onPresence?.([...uids]);
    });

    const { data, error } = await db
      .from(TABLE)
      .select("*")
      .eq("club_slug", slug)
      .order("created_at", { ascending: false })
      .order("id", { ascending: false })
      .limit(PAGE_SIZE);
    if (!active) return;
    if (error) {
      handlers.onError?.(friendlyDbError(error.message));
      return;
    }
    const rows = (data as ChatRow[] | null) ?? [];
    hasMore = rows.length === PAGE_SIZE;
    messages = rows.map(toMessage).reverse();
    publish();

    const [replies, edits] = await Promise.all([
      hasColumn(db, "reply_to_id"),
      hasColumn(db, "edited_at"),
    ]);
    if (!active) return;

    const reactionsRes = await db
      .from(REACTION_TABLE)
      .select("message_id, user_id, emoji")
      .eq("club_slug", slug)
      .order("created_at", { ascending: false })
      .limit(REACTION_LIMIT);
    if (!active) return;
    if (!reactionsRes.error) {
      reactions = ((reactionsRes.data as ReactionRow[] | null) ?? [])
        .map(toReaction)
        .filter((r): r is ChatRealtimeReaction => r !== null);
      publishReactions();
      handlers.onFeatures?.({ replies, edits, reactions: true });
      const upsertReaction = (row: ReactionRow) => {
        const next = toReaction(row);
        if (!next) return;
        reactions = reactions.some(
          (r) => r.messageId === next.messageId && r.userId === next.userId,
        )
          ? reactions.map((r) =>
              r.messageId === next.messageId && r.userId === next.userId ? next : r,
            )
          : [...reactions, next];
        publishReactions();
      };

      activeChannel
        .on(
          "postgres_changes",
          {
            event: "INSERT",
            schema: "public",
            table: REACTION_TABLE,
            filter: `club_slug=eq.${slug}`,
          },
          (payload) => upsertReaction(payload.new as ReactionRow),
        )
        .on(
          "postgres_changes",
          {
            event: "UPDATE",
            schema: "public",
            table: REACTION_TABLE,
            filter: `club_slug=eq.${slug}`,
          },
          (payload) => upsertReaction(payload.new as ReactionRow),
        )
        .on(
          "postgres_changes",
          {
            event: "DELETE",
            schema: "public",
            table: REACTION_TABLE,
            filter: `club_slug=eq.${slug}`,
          },
          (payload) => {
            const old = payload.old as ReactionRow;
            const messageId = String(old?.message_id ?? "");
            const userId = String(old?.user_id ?? "");
            if (!messageId || !userId) return;
            reactions = reactions.filter(
              (r) => !(r.messageId === messageId && r.userId === userId),
            );
            publishReactions();
          },
        );
    } else {
      // Missing table (SQL not re-run yet) or a transient failure: the chat
      // keeps working, it just shows no reaction chips.
      reactions = [];
      publishReactions();
      handlers.onFeatures?.({ replies, edits, reactions: false });
    }

    activeChannel
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: TABLE,
          filter: `club_slug=eq.${slug}`,
        },
        (payload) => {
          const message = toMessage(payload.new as ChatRow);
          if (messages.some((m) => m.id === message.id)) return;
          messages = [...messages, message];
          publish();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: TABLE,
          filter: `club_slug=eq.${slug}`,
        },
        (payload) => {
          const updated = toMessage(payload.new as ChatRow);
          if (!messages.some((m) => m.id === updated.id)) return;
          messages = messages.map((m) => (m.id === updated.id ? updated : m));
          publish();
        },
      )
      .on(
        "postgres_changes",
        {
          event: "DELETE",
          schema: "public",
          table: TABLE,
          filter: `club_slug=eq.${slug}`,
        },
        (payload) => {
          const old = payload.old as { id?: unknown };
          const id = old?.id != null ? String(old.id) : "";
          if (!id) return;
          handlers.onDeleted?.(id);
          messages = messages.filter((m) => m.id !== id);
          reactions = reactions.filter((r) => r.messageId !== id);
          publish();
          publishReactions();
        },
      )
      .subscribe(async (status) => {
        if (!active) return;
        if (status === "SUBSCRIBED") {
          if (myUid) {
            await activeChannel.track({ uid: myUid }).catch(() => {});
          }
          return;
        }
        if (
          status === "CHANNEL_ERROR" ||
          status === "TIMED_OUT" ||
          status === "CLOSED"
        ) {
          handlers.onError?.(new Error("Realtime channel unavailable."));
        }
      });
  })().catch((err: unknown) => {
    handlers.onError?.(err instanceof Error ? err : new Error(String(err)));
  });

  const loadOlder = async (): Promise<LoadOlderResult> => {
    if (!active || loadingOlder || !hasMore || messages.length === 0) {
      return { loaded: 0, hasMore };
    }
    loadingOlder = true;
    try {
      const oldest = messages[0];
      const rawAt = oldest.createdAt || new Date(oldest.at).toISOString();
      const cursorAt = rawAt.replace(/\+00:00$/, "Z");
      const cursorId = String(oldest.id);
      const { data, error } = await db
        .from(TABLE)
        .select("*")
        .eq("club_slug", slug)
        .or(
          `created_at.lt.${cursorAt},and(created_at.eq.${cursorAt},id.lt.${cursorId})`,
        )
        .order("created_at", { ascending: false })
        .order("id", { ascending: false })
        .limit(PAGE_SIZE);
      if (!active) return { loaded: 0, hasMore };
      if (error) {
        handlers.onError?.(friendlyDbError(error.message));
        return { loaded: 0, hasMore };
      }
      const rows = (data as ChatRow[] | null) ?? [];
      const seen = new Set(messages.map((m) => m.id));
      const older = rows
        .map(toMessage)
        .reverse()
        .filter((m) => !seen.has(m.id));
      if (older.length) messages = [...older, ...messages];
      hasMore = rows.length === PAGE_SIZE && older.length > 0;
      publish();
      return { loaded: older.length, hasMore };
    } finally {
      loadingOlder = false;
    }
  };

  return {
    unsubscribe: () => {
      active = false;
      handlers.onPresence?.([]);
      const current = channel;
      channel = null;
      if (current) {
        void current.untrack().catch(() => {});
        void db.removeChannel(current);
      }
    },
    loadOlder,
  };
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Insert a message (text and/or an already-uploaded image URL) and return the
 * stored row, so the sender can show it without waiting for the Realtime echo.
 */
export async function sendClubChatMessage(
  slug: string,
  input: {
    text?: string;
    image?: string;
    senderName: string;
    replyTo?: ChatRealtimeReply | null;
  },
): Promise<ChatRealtimeMessage> {
  const session = await getSession().catch(() => null);
  const replyId = input.replyTo?.id ?? "";
  const hasServerReply = !!input.replyTo && UUID_RE.test(replyId);
  const { data, error } = await supabase()
    .from(TABLE)
    .insert({
      club_slug: slug,
      sender_id: session?.user.id || "member",
      sender_name: input.senderName,
      body: input.text ?? "",
      image_url: input.image ?? null,
      ...(hasServerReply
        ? {
            reply_to_id: replyId,
            reply_to_sender: input.replyTo?.sender ?? null,
            reply_to_preview: input.replyTo?.text ?? null,
          }
        : {}),
    })
    .select("*")
    .single();
  if (error) throw friendlyDbError(error.message);
  const message = toMessage(data as ChatRow);
  // Push the club's other members right away instead of relying on the
  // Supabase dashboard webhook; the backend dedupes by message id, so
  // whichever path fires first sends the notification.
  const deviceId = await getDeviceId();
  void clubChatNotifyApi
    .send({
      id: message.id,
      club_slug: slug,
      sender_id: session?.user.id || "member",
      sender_name: input.senderName,
      body: input.text ?? "",
      image_url: input.image ?? null,
      device_id: deviceId,
    })
    .catch(() => {});
  return message;
}

/** Edit the text of one of the signed-in member's own messages. */
export async function updateClubChatMessage(
  id: string,
  text: string,
): Promise<ChatRealtimeMessage> {
  const session = await getSession().catch(() => null);
  let query = supabase()
    .from(TABLE)
    .update({ body: text, edited_at: new Date().toISOString() })
    .eq("id", id);
  if (session?.user.id) query = query.eq("sender_id", session.user.id);
  const { data, error } = await query.select("*").single();
  if (error) throw friendlyDbError(error.message);
  return toMessage(data as ChatRow);
}

/** Delete one of the signed-in member's own messages. */
export async function deleteClubChatMessage(id: string): Promise<void> {
  const session = await getSession().catch(() => null);
  let query = supabase().from(TABLE).delete().eq("id", id);
  if (session?.user.id) query = query.eq("sender_id", session.user.id);
  const { error } = await query;
  if (error) throw friendlyDbError(error.message);
}

/**
 * Set this member's reaction on a message. One emoji per member per message,
 * so the operation is: same emoji → remove; different emoji → replace; none →
 * insert. `currentEmoji` is what the caller already believes the member picked.
 */
export async function setClubChatReaction(
  slug: string,
  userId: string,
  messageId: string,
  emoji: string,
  currentEmoji: string | null,
): Promise<void> {
  const db = supabase();
  if (currentEmoji === emoji) {
    const { error } = await db
      .from(REACTION_TABLE)
      .delete()
      .eq("message_id", messageId)
      .eq("user_id", userId);
    if (error) throw friendlyDbError(error.message);
    return;
  }
  if (currentEmoji) {
    const { data, error } = await db
      .from(REACTION_TABLE)
      .update({ emoji })
      .eq("message_id", messageId)
      .eq("user_id", userId)
      .select("id");
    if (error) throw friendlyDbError(error.message);
    if (data?.length) return;
  }
  const { error } = await db.from(REACTION_TABLE).insert({
    message_id: messageId,
    club_slug: slug,
    user_id: userId,
    emoji,
  });
  if (error) throw friendlyDbError(error.message);
}
