import AsyncStorage from "@react-native-async-storage/async-storage";
import { useEffect, useRef, useState, type Dispatch, type SetStateAction } from "react";

export async function clearPersistentFormDraft(prefix: string) {
  const keys = await AsyncStorage.getAllKeys();
  await AsyncStorage.multiRemove(keys.filter((key) => key.startsWith(prefix)));
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

/**
 * A draft can outlive the shape it was saved with — an app update that adds a
 * field leaves every older draft missing it. Layering the stored draft over
 * the current initial value keeps the newer fields present instead of handing
 * components an object from a previous schema.
 */
function mergeDraft<T>(initial: T, stored: unknown): T {
  if (isPlainObject(initial) && isPlainObject(stored)) {
    return { ...initial, ...stored } as T;
  }
  return stored as T;
}

export function usePersistentFormState<T>(
  key: string,
  initialValue: T,
): [T, Dispatch<SetStateAction<T>>, () => Promise<void>] {
  const [value, setValue] = useState(initialValue);
  const [loadedKey, setLoadedKey] = useState<string | null>(null);
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const initialRef = useRef(initialValue);

  useEffect(() => {
    let active = true;
    AsyncStorage.getItem(key)
      .then((stored) => {
        if (!active || stored == null) return;
        try {
          setValue(mergeDraft(initialRef.current, JSON.parse(stored)));
        } catch {
          void AsyncStorage.removeItem(key);
        }
      })
      .finally(() => {
        if (active) setLoadedKey(key);
      });

    return () => {
      active = false;
    };
  }, [key]);

  useEffect(() => {
    if (loadedKey !== key) return;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      void AsyncStorage.setItem(key, JSON.stringify(value)).catch((error) => {
        console.error(`Could not save form draft "${key}"`, error);
      });
    }, 250);

    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
    };
  }, [key, loadedKey, value]);

  const clearDraft = async () => {
    if (saveTimer.current) clearTimeout(saveTimer.current);
    await AsyncStorage.removeItem(key);
  };

  return [value, setValue, clearDraft];
}
