import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useEffect, useState, type ReactNode } from "react";
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Linking,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";

const BUG_WA_NUMBER = "27782677436";

function Field({
  label,
  required,
  children,
}: {
  label: string;
  required?: boolean;
  children: ReactNode;
}) {
  return (
    <View style={styles.field}>
      <Text style={styles.fieldLabel}>
        {label} {required ? <Text style={styles.req}>*</Text> : null}
      </Text>
      {children}
    </View>
  );
}

export default function BugReportModal({
  visible,
  onClose,
}: {
  visible: boolean;
  onClose: () => void;
}) {
  const insets = useSafeAreaInsets();
  const [summary, setSummary] = useState("");
  const [description, setDescription] = useState("");
  const [steps, setSteps] = useState("");
  const [contact, setContact] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!visible) return;
    getSession().then((s) => {
      if (!contact && s?.user?.email) setContact(s.user.email);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible]);

  const handleClose = () => {
    if (submitting) return;
    setSummary("");
    setDescription("");
    setSteps("");
    setContact("");
    onClose();
  };

  const handleSubmit = async () => {
    if (!summary.trim()) {
      Alert.alert("Required", "Please give the bug a short summary.");
      return;
    }
    if (!description.trim()) {
      Alert.alert("Required", "Please describe what went wrong.");
      return;
    }
    setSubmitting(true);
    const lines = [
      "BUG REPORT",
      "",
      `Summary: ${summary.trim()}`,
      "",
      `What went wrong:`,
      description.trim(),
    ];
    if (steps.trim()) {
      lines.push("", "Steps to reproduce:", steps.trim());
    }
    lines.push("", `App version: ${Platform.OS}`, `Device: ${Platform.OS}`);
    if (contact.trim()) lines.push("", `Contact: ${contact.trim()}`);
    lines.push("", `Sent: ${new Date().toLocaleString()}`);
    const text = encodeURIComponent(lines.join("\n"));
    const url = `https://wa.me/${BUG_WA_NUMBER}?text=${text}`;
    try {
      await Linking.openURL(url);
    } catch {
      Alert.alert(
        "Couldn't open WhatsApp",
        "Please make sure WhatsApp is installed, then try again.",
      );
    }
    setSubmitting(false);
    handleClose();
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      presentationStyle="fullScreen"
      statusBarTranslucent
      onRequestClose={handleClose}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.overlay}
      >
        <View style={styles.overlay}>
          <LinearGradient
            colors={["#f59e0b", "#fbbf24"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.accentBar}
          />
          <View style={[styles.header, { paddingTop: insets.top + 18 }]}>
            <View style={styles.headIcon}>
              <Ionicons name="bug-outline" size={22} color="#f59e0b" />
            </View>
            <View style={styles.headerTextWrap}>
              <Text style={styles.title}>Help with a bug</Text>
              <Text style={styles.sub}>
                Tell us what went wrong — we&apos;ll get it fixed.
              </Text>
            </View>
            <TouchableOpacity
              style={styles.closeBtn}
              onPress={handleClose}
              disabled={submitting}
            >
              <Ionicons name="close" size={20} color={colors.muted} />
            </TouchableOpacity>
          </View>

          <ScrollView
            style={styles.scroll}
            contentContainerStyle={styles.form}
            keyboardShouldPersistTaps="handled"
            keyboardDismissMode="none"
            showsVerticalScrollIndicator={false}
          >
            <Field label="Short summary" required>
              <TextInput
                style={styles.input}
                placeholder="e.g. App crashes when editing an event time"
                placeholderTextColor="#a3aebc"
                value={summary}
                onChangeText={setSummary}
                maxLength={80}
              />
            </Field>

            <Field label="What went wrong?" required>
              <TextInput
                style={[styles.input, styles.textArea]}
                placeholder="Describe the problem in as much detail as you can…"
                placeholderTextColor="#a3aebc"
                value={description}
                onChangeText={setDescription}
                multiline
                numberOfLines={4}
                textAlignVertical="top"
              />
            </Field>

            <Field label="Steps to reproduce (optional)">
              <TextInput
                style={[styles.input, styles.textArea]}
                placeholder="1. Open the app\n2. Tap Events\n3. Edit the time…"
                placeholderTextColor="#a3aebc"
                value={steps}
                onChangeText={setSteps}
                multiline
                numberOfLines={3}
                textAlignVertical="top"
              />
            </Field>

            <Field label="Email (optional · for follow-up)">
              <TextInput
                style={styles.input}
                placeholder="you@example.com"
                placeholderTextColor="#a3aebc"
                value={contact}
                onChangeText={setContact}
                autoCapitalize="none"
                keyboardType="email-address"
              />
            </Field>

            <TouchableOpacity
              style={styles.submit}
              onPress={handleSubmit}
              disabled={submitting}
              activeOpacity={0.85}
            >
              {submitting ? (
                <ActivityIndicator size="small" color={colors.forestDark} />
              ) : (
                <>
                  <Ionicons name="logo-whatsapp" size={16} color={colors.forestDark} />
                  <Text style={styles.submitText}>Send via WhatsApp</Text>
                </>
              )}
            </TouchableOpacity>

            <Text style={styles.note}>
              Your report opens in WhatsApp, ready to send to our support line.
            </Text>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: colors.bg,
  },
  accentBar: { height: 4 },
  header: {
    flexDirection: "row",
    alignItems: "flex-start",
    gap: 12,
    paddingHorizontal: 22,
    paddingTop: 18,
    paddingBottom: 16,
    backgroundColor: colors.white,
    borderBottomWidth: 1,
    borderBottomColor: "rgba(29,42,77,0.06)",
  },
  headIcon: {
    width: 48,
    height: 48,
    borderRadius: 24,
    backgroundColor: "rgba(251,191,36,0.14)",
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 1,
    borderColor: "rgba(245,158,11,0.25)",
  },
  headerTextWrap: { flex: 1 },
  title: {
    fontFamily: "Poppins_600SemiBold",
    fontSize: 20,
    lineHeight: 26,
    color: colors.forestDark,
  },
  sub: {
    fontSize: 11,
    fontWeight: "400",
    lineHeight: 15,
    color: colors.muted,
    marginTop: 3,
    fontFamily: "Poppins_400Regular",
  },
  closeBtn: {
    width: 32,
    height: 32,
    borderRadius: 16,
    borderWidth: 1,
    borderColor: "rgba(29,42,77,0.12)",
    backgroundColor: colors.bgSoft,
    alignItems: "center",
    justifyContent: "center",
  },
  scroll: { flex: 1 },
  form: { paddingHorizontal: 22, paddingTop: 18, paddingBottom: 32 },
  field: { marginBottom: 16 },
  fieldLabel: {
    fontSize: 13,
    fontWeight: "600",
    color: colors.forestDark,
    marginBottom: 8,
    fontFamily: "Poppins_600SemiBold",
  },
  req: { color: colors.goldDark, fontFamily: "Poppins_600SemiBold" },
  input: {
    paddingHorizontal: 14,
    paddingVertical: 12,
    borderRadius: 12,
    fontSize: 15,
    color: colors.forestDark,
    backgroundColor: colors.white,
    borderWidth: 1.5,
    borderColor: "rgba(29,42,77,0.12)",
    fontFamily: "Poppins_400Regular",
  },
  textArea: { minHeight: 96, lineHeight: 20, paddingTop: 12 },
  submit: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    backgroundColor: colors.gold,
    paddingVertical: 15,
    borderRadius: 14,
    marginTop: 4,
    shadowColor: colors.gold,
    shadowOffset: { width: 0, height: 10 },
    shadowOpacity: 0.4,
    shadowRadius: 14,
    elevation: 4,
  },
  submitText: {
    fontSize: 14,
    fontWeight: "700",
    color: colors.forestDark,
    fontFamily: "Poppins_700Bold",
  },
  note: {
    textAlign: "center",
    marginTop: 14,
    fontSize: 12,
    lineHeight: 17,
    color: colors.muted,
    fontFamily: "Poppins_400Regular",
  },
});
