import { Ionicons } from "@expo/vector-icons";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { Image } from "expo-image";
import {
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import EmptyState from "@/components/EmptyState";
import { type Comment } from "@/services/community";
import { getOptimizedImageUrl } from "@/services/cloudinary";

function timeAgo(iso?: string) {
  if (!iso) return "";
  try {
    const diff = Date.now() - new Date(iso).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "Just now";
    if (mins < 60) return `${mins}m`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h`;
    const days = Math.floor(hours / 24);
    if (days < 7) return `${days}d`;
    return new Date(iso).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
    });
  } catch {
    return "";
  }
}

/**
 * Twitter-style replies on a prayer request or prayer group: shows the
 * encouragement thread and lets the user add a comment, which lands
 * optimistically in the list. Keyboard-safe (full-screen presentation with
 * the composer pinned above the keyboard).
 */
export default function CommentsModal({
  itemId,
  title,
  getComments,
  addComment,
  deleteComment,
  onClose,
  onCommentAdded,
  onCommentRemoved,
}: {
  itemId: string;
  title: string;
  getComments: (id: string) => Promise<{ data: Comment[] }>;
  addComment: (id: string, text: string) => Promise<{ data: Comment }>;
  deleteComment: (id: string, commentId: string) => Promise<{ success: boolean }>;
  onClose: () => void;
  onCommentAdded?: (itemId: string) => void;
  onCommentRemoved?: (itemId: string) => void;
}) {
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [loadError, setLoadError] = useState(false);
  const insets = useSafeAreaInsets();

  const load = useCallback(
    async (isRetry = false) => {
      if (isRetry) setLoading(true);
      try {
        setLoadError(false);
        const res = await getComments(itemId);
        setComments(res?.data || []);
      } catch {
        setLoadError(true);
      } finally {
        setLoading(false);
      }
    },
    [getComments, itemId],
  );

  useEffect(() => {
    // Initial fetch (and only that) — retries go through the Retry button.
    (async () => {
      await load();
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const send = async () => {
    const body = text.trim();
    if (!body || sending) return;
    setSending(true);
    const optimistic: Comment = {
      _id: `temp_${Date.now()}`,
      text: body,
      author: "You",
      image: null,
      mine: true,
      createdAt: new Date().toISOString(),
    };
    setComments((prev) => [...prev, optimistic]);
    setText("");
    try {
      const res = await addComment(itemId, body);
      setComments((prev) =>
        prev.map((c) => (c._id === optimistic._id ? { ...c, ...res?.data } : c)),
      );
      onCommentAdded?.(itemId);
    } catch {
      // Roll back on failure.
      setComments((prev) => prev.filter((c) => c._id !== optimistic._id));
      setText(body);
    } finally {
      setSending(false);
    }
  };

  const removeComment = async (comment: Comment) => {
    if (deletingId) return;
    setDeletingId(comment._id);
    try {
      await deleteComment(itemId, comment._id);
      setComments((prev) => prev.filter((c) => c._id !== comment._id));
      onCommentRemoved?.(itemId);
    } catch {
      // Keep the comment — deletion failed.
    } finally {
      setDeletingId(null);
    }
  };

  const renderComment = ({ item }: { item: Comment }) => (
    <View style={styles.comment}>
      {item.image ? (
        <Image source={{ uri: getOptimizedImageUrl(item.image, 160) }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarText}>
            {(item.author || "?")[0].toUpperCase()}
          </Text>
        </View>
      )}
      <View style={styles.commentBody}>
        <View style={styles.commentHead}>
          <Text style={styles.commentName} numberOfLines={1}>
            {item.author}
          </Text>
          <View style={styles.commentMeta}>
            <Text style={styles.commentTime}>{timeAgo(item.createdAt)}</Text>
            {item.mine && (
              <TouchableOpacity
                onPress={() => removeComment(item)}
                hitSlop={8}
                disabled={deletingId === item._id}
                accessibilityLabel="Delete your comment"
              >
                {deletingId === item._id ? (
                  <ActivityIndicator size="small" color={colors.gray[400]} />
                ) : (
                  <Ionicons name="trash-outline" size={14} color={colors.gray[400]} />
                )}
              </TouchableOpacity>
            )}
          </View>
        </View>
        <Text style={styles.commentText}>{item.text}</Text>
      </View>
    </View>
  );

  return (
    <Modal
      visible
      animationType="slide"
      presentationStyle="fullScreen"
      statusBarTranslucent
      onRequestClose={onClose}
    >
      <KeyboardAvoidingView
        style={styles.safe}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <SafeAreaView style={styles.safe} edges={["top"]}>
          {/* Header */}
          <View style={styles.header}>
            <TouchableOpacity onPress={onClose} style={styles.headerBtn}>
              <Ionicons name="close" size={22} color={colors.darkGreen} />
            </TouchableOpacity>
            <View style={{ flex: 1, alignItems: "center" }}>
              <Text style={styles.headerTitle}>Encouragements</Text>
              <Text style={styles.headerSub} numberOfLines={1}>
                on “{title}”
              </Text>
            </View>
            <View style={{ width: 36 }} />
          </View>

          {/* Thread */}
          {loading ? (
            <View style={styles.loadingBox}>
              <ActivityIndicator size="small" color={colors.gold} />
              <Text style={styles.loadingText}>Loading encouragements…</Text>
            </View>
          ) : loadError ? (
            <EmptyState
              icon="cloud-offline-outline"
              color={colors.error}
              eyebrow="Couldn't load"
              title="Encouragements unavailable"
              subtitle="Check your connection and try again."
              actionLabel="Retry"
              onAction={() => load(true)}
            />
          ) : (
            <FlatList
              data={comments}
              keyExtractor={(item) => item._id}
              style={styles.thread}
              contentContainerStyle={styles.list}
              keyboardShouldPersistTaps="handled"
              ListEmptyComponent={
                <EmptyState
                  icon="chatbubble-ellipses-outline"
                  color={colors.gold}
                  eyebrow="Be the first"
                  title="No encouragements yet"
                  subtitle="Leave a word of hope for this prayer request or group."
                />
              }
              renderItem={renderComment}
            />
          )}

          {/* Composer */}
          <View
            style={[
              styles.composer,
              { paddingBottom: Math.max(insets.bottom, 8) },
            ]}
          >
            <TextInput
              style={styles.input}
              placeholder="Share a word of encouragement…"
              placeholderTextColor={colors.muted}
              value={text}
              onChangeText={setText}
              multiline
              maxLength={500}
              blurOnSubmit={false}
            />
            <Pressable
              onPress={send}
              disabled={!text.trim() || sending}
              style={[
                styles.sendBtn,
                (!text.trim() || sending) && styles.sendBtnDisabled,
              ]}
            >
              {sending ? (
                <ActivityIndicator size="small" color={colors.white} />
              ) : (
                <Ionicons name="arrow-up" size={18} color={colors.white} />
              )}
            </Pressable>
          </View>
        </SafeAreaView>
      </KeyboardAvoidingView>
    </Modal>
  );
}

