import { Ionicons } from "@expo/vector-icons";
import { router, useFocusEffect } from "expo-router";
import { useCallback, useState } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { getClub } from "@/constants/clubs";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { getSession } from "@/services/auth";
import {
  clubJoinApi,
  effectiveClubSlug,
  type ClubMembership,
} from "@/services/club-join";
import { useClubs } from "@/services/clubs";

// Surge is the club the chat card wears until the user joins one of their own.
const SURGE = getClub("surge");

/**
 * Home → Community → Club Chat. White card in the Instagram/Facebook family.
 * Members get their club's colours on the border, icon, copy and CTA;
 * everyone else sees Surge's orange.
 */
export default function ClubChatCard() {
  const { find } = useClubs();
  const [membership, setMembership] = useState<ClubMembership | null>(null);

  // Re-checked on focus so the colours follow a club that was just joined.
  useFocusEffect(
    useCallback(() => {
      let alive = true;
      (async () => {
        const session = await getSession().catch(() => null);
        if (!alive) return;
        if (!session?.user) {
          setMembership(null);
          return;
        }
        const res = await clubJoinApi.me().catch(() => null);
        if (!alive) return;
        const m = res?.data;
        setMembership(m && m.status !== "graduated" ? m : null);
      })();
      return () => {
        alive = false;
      };
    }, []),
  );

  const slug = membership ? effectiveClubSlug(membership) : "";
  const club = slug ? find(slug) : undefined;
  const accentLight = club?.color ?? SURGE?.color ?? "#FF6B00";
  const accent = club?.colorDark ?? SURGE?.colorDark ?? "#C2410C";

  return (
    <View style={[s.card, { borderColor: `${accentLight}88` }]}>
      <View style={s.iconRow}>
        <View style={[s.iconChip, { backgroundColor: `${accentLight}18` }]}>
          <Ionicons name="chatbubbles" size={21} color={accent} />
        </View>
        <Text style={s.title}>Club Chat</Text>
      </View>
      <Text style={[s.text, { color: accent }]}>
        Talk with the members of your club without leaving the app.
      </Text>
      <TouchableOpacity
        style={[s.btn, { borderColor: accentLight }]}
        onPress={() => router.push("/club-chat" as any)}
        activeOpacity={0.85}
      >
        <Text style={[s.btnText, { color: accent }]}>Open chat</Text>
        <Ionicons name="arrow-forward" size={16} color={accent} />
      </TouchableOpacity>
    </View>
  );
}

const s = StyleSheet.create({
  card: {
    borderRadius: 24,
    padding: 22,
    borderWidth: 1,
    backgroundColor: colors.white,
    shadowColor: colors.forestDark,
    shadowOffset: { width: 0, height: 18 },
    shadowOpacity: 0.1,
    shadowRadius: 40,
    elevation: 3,
  },
  iconRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
  },
  iconChip: {
    width: 40,
    height: 40,
    borderRadius: 20,
    alignItems: "center",
    justifyContent: "center",
  },
  title: {
    fontSize: 14,
    lineHeight: 18,
    fontWeight: "700",
    color: colors.forestDark,
    fontFamily: fonts.sansBold,
  },
  text: {
    fontSize: 12,
    fontFamily: fonts.sans,
    lineHeight: 18,
    marginTop: 8,
  },
  btn: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    alignSelf: "flex-start",
    backgroundColor: colors.white,
    borderRadius: 999,
    paddingHorizontal: 20,
    paddingVertical: 11,
    marginTop: 18,
    borderWidth: 1.5,
  },
  btnText: {
    fontSize: 13.5,
    fontWeight: "700",
    fontFamily: fonts.sansBold,
  },
});
