import { openDatabaseSync, type SQLiteDatabase } from "expo-sqlite";
import { API_BASE, IS_WEB } from "./config";
import { getRequestHeaders } from "./auth";

export type PrayerKey = "dawn" | "sunrise" | "noon" | "afternoon" | "sunset" | "evening";

export type CustomPrayer = {
  id: string;
  name: string;
  message: string;
  time: string;
  icon: string;
  enabled: boolean;
};

const DEFAULT_ICONS = [
  "heart-outline",
  "book-outline",
  "star-outline",
  "flame-outline",
  "leaf-outline",
  "moon-outline",
];

const DEFAULT_ADVANCE_MINUTES = 10;
const WEB_PREFS_KEY = "prayer_prefs_web_v1";

// One long-lived connection: prayer preferences are read and written from
// several screens, and opening a fresh connection per call left the file
// locked often enough that toggles silently failed on some devices.
let cachedDb: SQLiteDatabase | null = null;

export function getLocalDb(): SQLiteDatabase {
  if (!cachedDb) {
    // Dedicated connection + busy_timeout so sync writes don't collide with
    // the provider's async handle (same-connection locks surfaced as "Couldn't save").
    cachedDb = openDatabaseSync("relate.db", { useNewConnection: true });
    cachedDb.execSync("PRAGMA busy_timeout = 3000;");
  }
  return cachedDb;
}

// prayer_preferences exists in two shapes: the legacy key/value rows
// (user_id, key, value) and the single-row layout created by migrateDb.
// The columns are inspected once with PRAGMA table_info — probing with a
// SELECT that throws is unreliable when the table itself is missing, and a
// missing table used to make every toggle fail silently.
type PrefSchema = "rows" | "single";
let cachedSchema: PrefSchema | null = null;

function detectSchema(db: SQLiteDatabase): PrefSchema {
  if (cachedSchema) return cachedSchema;
  let columns: string[] = [];
  try {
    columns = db
      .getAllSync<{ name: string }>(`PRAGMA table_info(prayer_preferences)`)
      .map((row) => row.name);
  } catch {
    columns = [];
  }
  if (columns.includes("disabled_prayers")) {
    cachedSchema = "single";
  } else if (columns.includes("key") && columns.includes("value")) {
    cachedSchema = "rows";
  } else {
    // Table missing or from an unrecognised build — create the current
    // single-row schema so preferences always have somewhere to persist.
    db.execSync(`
      CREATE TABLE IF NOT EXISTS prayer_preferences (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        disabled_prayers TEXT NOT NULL DEFAULT '[]',
        custom_prayers TEXT NOT NULL DEFAULT '[]',
        sounds TEXT NOT NULL DEFAULT '{}',
        advance_minutes INTEGER NOT NULL DEFAULT 10
      );
    `);
    cachedSchema = "single";
  }
  return cachedSchema;
}

function readPref(db: SQLiteDatabase, key: string, column: string): string | null {
  if (detectSchema(db) === "rows") {
    const row = db.getFirstSync<{ value: string }>(
      `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = ? ORDER BY rowid DESC LIMIT 1`,
      [key],
    );
    return row?.value ?? null;
  }
  const row = db.getFirstSync<Record<string, string | number>>(
    `SELECT ${column} AS value FROM prayer_preferences WHERE id = 1`,
  );
  return row ? String(row.value) : null;
}

function writePref(db: SQLiteDatabase, key: string, column: string, value: string): void {
  if (detectSchema(db) === "rows") {
    // The legacy table has no unique constraint, so INSERT OR REPLACE would
    // append a new row and reads would keep returning the oldest value.
    db.runSync(
      `DELETE FROM prayer_preferences WHERE user_id = 'local' AND key = ?`,
      [key],
    );
    db.runSync(
      `INSERT INTO prayer_preferences (user_id, key, value) VALUES ('local', ?, ?)`,
      [key, value],
    );
    return;
  }
  db.runSync(`INSERT OR IGNORE INTO prayer_preferences (id) VALUES (1)`);
  db.runSync(`UPDATE prayer_preferences SET ${column} = ? WHERE id = 1`, [value]);
}

function parseJson<T>(value: string | null, fallback: T): T {
  if (!value) return fallback;
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

export function getDisabledPrayersDb(db: SQLiteDatabase): PrayerKey[] {
  return parseJson<PrayerKey[]>(readPref(db, "disabled", "disabled_prayers"), []);
}

export function setDisabledPrayersDb(db: SQLiteDatabase, keys: PrayerKey[]): void {
  writePref(db, "disabled", "disabled_prayers", JSON.stringify(keys));
  syncToApi({ disabled: keys });
}

export function togglePrayerDisabledDb(db: SQLiteDatabase, key: PrayerKey): PrayerKey[] {
  const current = getDisabledPrayersDb(db);
  const next = current.includes(key) ? current.filter((k) => k !== key) : [...current, key];
  setDisabledPrayersDb(db, next);
  return next;
}

export function getCustomPrayersDb(db: SQLiteDatabase): CustomPrayer[] {
  return parseJson<CustomPrayer[]>(readPref(db, "custom", "custom_prayers"), []);
}

export function saveCustomPrayersDb(db: SQLiteDatabase, prayers: CustomPrayer[]): void {
  writePref(db, "custom", "custom_prayers", JSON.stringify(prayers));
  syncToApi({ custom: prayers });
}

export function addCustomPrayerDb(
  db: SQLiteDatabase,
  name: string,
  time: string,
  message: string = "",
): CustomPrayer[] {
  const all = getCustomPrayersDb(db);
  if (all.length >= 6) return all;
  const prayer: CustomPrayer = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name,
    message,
    time,
    icon: DEFAULT_ICONS[all.length % DEFAULT_ICONS.length],
    enabled: true,
  };
  const next = [...all, prayer];
  saveCustomPrayersDb(db, next);
  return next;
}

export function updateCustomPrayerDb(
  db: SQLiteDatabase,
  id: string,
  updates: Partial<Omit<CustomPrayer, "id">>,
): CustomPrayer[] {
  const all = getCustomPrayersDb(db);
  const next = all.map((p) => (p.id === id ? { ...p, ...updates } : p));
  saveCustomPrayersDb(db, next);
  return next;
}

export function deleteCustomPrayerDb(db: SQLiteDatabase, id: string): CustomPrayer[] {
  const all = getCustomPrayersDb(db);
  const next = all.filter((p) => p.id !== id);
  saveCustomPrayersDb(db, next);
  return next;
}

export function getDefaultIcon(index: number): string {
  return DEFAULT_ICONS[index % DEFAULT_ICONS.length];
}

function isAdvanceMinutes(value: unknown): value is number {
  return value === 0 || value === 5 || value === 10 || value === 15;
}

export function getAdvanceMinutesDb(db: SQLiteDatabase): number {
  const raw = readPref(db, "advance_minutes", "advance_minutes");
  if (raw == null) return DEFAULT_ADVANCE_MINUTES;
  const n = parseInt(raw, 10);
  return isAdvanceMinutes(n) ? n : DEFAULT_ADVANCE_MINUTES;
}

export function setAdvanceMinutesDb(db: SQLiteDatabase, minutes: number): void {
  writePref(db, "advance_minutes", "advance_minutes", String(minutes));
  syncToApi({ advanceMinutes: minutes });
}

type ApiPreferencesPatch = {
  disabled?: PrayerKey[];
  custom?: CustomPrayer[];
  sounds?: Record<string, string>;
  enabled?: boolean;
  advanceMinutes?: number;
  lat?: number;
  lng?: number;
  tzOffset?: number;
  readingEnabled?: boolean;
  readingTime?: string;
  votdEnabled?: boolean;
};

async function syncToApi(data: ApiPreferencesPatch) {
  try {
    const headers = await getRequestHeaders({ "Content-Type": "application/json" });
    if (!IS_WEB && !("Cookie" in headers) && !("cookie" in headers)) return;
    await fetch(`${API_BASE}/api/prayer-preferences`, {
      method: "PUT",
      headers,
      credentials: "include",
      body: JSON.stringify(data),
    });
  } catch {}
}

// ── Web (PWA) mirror ────────────────────────────────────────────────────
// Browsers have no SQLite here (the web shim is a no-op), so the toggles read
// back as defaults on every open. Persist them in localStorage and hydrate
// once per page load from the account's saved preferences, which the server
// already uses to build reminders.

type WebPrefs = { disabled: PrayerKey[]; advanceMinutes: number };

let webPrefs: WebPrefs | null = null;
let webPrefsPromise: Promise<WebPrefs> | null = null;

function readWebCache(): WebPrefs | null {
  if (webPrefs) return webPrefs;
  try {
    const raw = localStorage.getItem(WEB_PREFS_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const disabled = Array.isArray(parsed?.disabled)
      ? parsed.disabled.filter((key: unknown): key is PrayerKey => typeof key === "string")
      : [];
    const advanceMinutes = isAdvanceMinutes(parsed?.advanceMinutes)
      ? parsed.advanceMinutes
      : DEFAULT_ADVANCE_MINUTES;
    webPrefs = { disabled, advanceMinutes };
    return webPrefs;
  } catch {
    return null;
  }
}

function writeWebPrefs(next: WebPrefs): void {
  webPrefs = next;
  try {
    localStorage.setItem(WEB_PREFS_KEY, JSON.stringify(next));
  } catch {}
}

async function fetchWebPrefs(): Promise<WebPrefs> {
  const fallback = readWebCache() ?? {
    disabled: [],
    advanceMinutes: DEFAULT_ADVANCE_MINUTES,
  };
  try {
    const res = await fetch(`${API_BASE}/api/prayer-preferences`, {
      headers: await getRequestHeaders(),
      credentials: "include",
    });
    if (!res.ok) return fallback;
    const data = await res.json();
    const disabled = Array.isArray(data?.disabled)
      ? data.disabled.filter((key: unknown): key is PrayerKey => typeof key === "string")
      : [];
    const advanceMinutes = isAdvanceMinutes(data?.advanceMinutes)
      ? data.advanceMinutes
      : DEFAULT_ADVANCE_MINUTES;
    return { disabled, advanceMinutes };
  } catch {
    return fallback;
  }
}

function loadWebPrefs(): Promise<WebPrefs> {
  if (!webPrefsPromise) {
    webPrefsPromise = fetchWebPrefs().then((prefs) => {
      // A toggle saved while the fetch was in flight wins over the snapshot.
      if (!webPrefs) writeWebPrefs(prefs);
      return webPrefs as WebPrefs;
    });
  }
  return webPrefsPromise;
}

// Async API wrappers used by screens that don't hold a database context.
export async function getDisabledPrayers(): Promise<PrayerKey[]> {
  if (IS_WEB) return (await loadWebPrefs()).disabled;
  return getDisabledPrayersDb(getLocalDb());
}

export async function setDisabledPrayers(keys: PrayerKey[]): Promise<void> {
  if (IS_WEB) {
    const current = await loadWebPrefs();
    writeWebPrefs({ ...current, disabled: keys });
    await syncToApi({ disabled: keys });
    return;
  }
  setDisabledPrayersDb(getLocalDb(), keys);
}

export async function getAdvanceMinutes(): Promise<number> {
  if (IS_WEB) return (await loadWebPrefs()).advanceMinutes;
  return getAdvanceMinutesDb(getLocalDb());
}

export async function setAdvanceMinutes(minutes: number): Promise<void> {
  if (IS_WEB) {
    const current = await loadWebPrefs();
    writeWebPrefs({ ...current, advanceMinutes: minutes });
    await syncToApi({ advanceMinutes: minutes });
    return;
  }
  setAdvanceMinutesDb(getLocalDb(), minutes);
}

export async function getCustomPrayers(): Promise<CustomPrayer[]> {
  return getCustomPrayersDb(getLocalDb());
}

export async function saveCustomPrayers(prayers: CustomPrayer[]): Promise<void> {
  saveCustomPrayersDb(getLocalDb(), prayers);
}

export async function addCustomPrayer(
  name: string,
  time: string,
  message?: string,
): Promise<CustomPrayer[]> {
  return addCustomPrayerDb(getLocalDb(), name, time, message);
}

export async function updateCustomPrayer(
  id: string,
  updates: Partial<Omit<CustomPrayer, "id">>,
): Promise<CustomPrayer[]> {
  return updateCustomPrayerDb(getLocalDb(), id, updates);
}

export async function deleteCustomPrayer(id: string): Promise<CustomPrayer[]> {
  return deleteCustomPrayerDb(getLocalDb(), id);
}
