import { Ionicons } from "@expo/vector-icons";
import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  InteractionManager,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import SuccessModal from "@/components/SuccessModal";
import {
  DUE_LABELS,
  KIT_ITEMS,
  KIT_ITEM_KEYS,
  schoolKitApi,
  type DueState,
  type KitItemKey,
  type KitMovement,
  type LearnerKit,
} from "@/services/school-kit";

const SURGE = "#FF6B00";

const ITEM_COLORS: Record<KitItemKey, string> = {
  book: colors.gold,
  pencil: SURGE,
  pen: colors.goldDark,
};

const DUE_PILL: Record<DueState, { color: string; bg: string }> = {
  overdue: { color: "#be123c", bg: "#ffe4e6" },
  due: { color: "#b45309", bg: "#fef3c7" },
  ok: { color: "#047857", bg: "#d1fae5" },
  none: { color: colors.muted, bg: colors.gray[100] },
};

const fmtDate = (iso: string | null) => {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" });
};

export default function LearnerKitScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const insets = useSafeAreaInsets();
  const [learner, setLearner] = useState<LearnerKit | null>(null);
  const [history, setHistory] = useState<KitMovement[]>([]);
  const [loading, setLoading] = useState(true);
  const [qty, setQty] = useState<Record<KitItemKey, string>>({
    book: "",
    pencil: "",
    pen: "",
  });
  const [swap, setSwap] = useState(false);
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState<{ title: string; message?: string } | null>(null);
  const [season] = useState(new Date().getFullYear());

  const load = useCallback(async () => {
    if (!id) return;
    try {
      const res = await schoolKitApi.learner(String(id), season);
      setLearner(res.data.learner);
      setHistory(res.data.history);
    } catch {
      setLearner(null);
    } finally {
      setLoading(false);
    }
  }, [id, season]);

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      void load();
    });
    return () => task.cancel();
  }, [load]);

  const allocate = async () => {
    if (!learner) return;
    const items = KIT_ITEM_KEYS.map((key) => ({
      item: key,
      qty: Number(qty[key] || 0),
    })).filter((row) => Number.isInteger(row.qty) && row.qty > 0);

    if (items.length === 0) {
      Alert.alert("Nothing selected", "Enter a quantity for at least one item.");
      return;
    }

    setSaving(true);
    try {
      await schoolKitApi.allocate({
        memberIds: [learner.id],
        items,
        swapVerified: swap,
        note: note.trim() || undefined,
      });
      setQty({ book: "", pencil: "", pen: "" });
      setNote("");
      setSwap(false);
      await load();
      setSuccess({
        title: "Allocation recorded",
        message: `${learner.name}'s kit has been updated.`,
      });
    } catch (e: any) {
      Alert.alert("Could not allocate", e?.message || "Try again in a moment.");
    }
    setSaving(false);
  };

  const removeAllocation = (mv: KitMovement) => {
    Alert.alert(
      "Delete this allocation?",
      `${KIT_ITEMS[mv.item].short} × ${mv.qty} on ${fmtDate(mv.date)} goes back into stock.`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: async () => {
            try {
              await schoolKitApi.removeMovement(mv._id);
              await load();
              setSuccess({
                title: "Allocation deleted",
                message: `${KIT_ITEMS[mv.item].short} × ${mv.qty} returned to stock.`,
              });
            } catch (e: any) {
              Alert.alert("Could not delete", e?.message || "Try again in a moment.");
            }
          },
        },
      ],
    );
  };

  const toggleExamCheck = async (checked: boolean) => {
    if (!learner) return;
    setLearner({
      ...learner,
      examCheckedAt: checked ? new Date().toISOString() : null,
    });
    try {
      await schoolKitApi.setExamCheck(learner.id, checked, season);
    } catch {
      Alert.alert("Could not save", "The stationery check was not saved.");
      await load();
    }
  };

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === "ios" ? "padding" : undefined}
        >
          <View style={styles.header}>
            <TouchableOpacity onPress={() => router.back()} hitSlop={10}>
              <Ionicons name="chevron-back" size={22} color={colors.forest} />
            </TouchableOpacity>
            <Text style={styles.headerTitle}>Learner kit</Text>
          </View>

          {loading ? (
            <View style={styles.center}>
              <ActivityIndicator color={colors.goldDark} size="large" />
            </View>
          ) : !learner ? (
            <View style={styles.center}>
              <Ionicons name="person-outline" size={26} color={colors.muted} />
              <Text style={styles.emptyText}>Learner not found.</Text>
            </View>
          ) : (
            <ScrollView
              contentContainerStyle={{
                paddingHorizontal: 16,
                paddingBottom: 36 + insets.bottom,
                gap: 12,
              }}
              showsVerticalScrollIndicator={false}
            >
              <View style={styles.profileCard}>
                <View style={styles.avatar}>
                  <Text style={styles.avatarText}>
                    {learner.name.slice(0, 1).toUpperCase()}
                  </Text>
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={styles.name}>{learner.name}</Text>
                  <Text style={styles.meta}>
                    {learner.clubName || learner.clubSlug}
                    {learner.age ? ` · age ${learner.age}` : ""}
                  </Text>
                </View>
                <View
                  style={[
                    styles.pill,
                    { backgroundColor: DUE_PILL[learner.dueState].bg },
                  ]}
                >
                  <Text
                    style={[styles.pillText, { color: DUE_PILL[learner.dueState].color }]}
                  >
                    {DUE_LABELS[learner.dueState]}
                  </Text>
                </View>
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="book-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>What they have</Text>
                </View>
                {KIT_ITEM_KEYS.map((key) => {
                  const item = learner.items[key];
                  return (
                    <View key={key} style={styles.itemRow}>
                      <View
                        style={[styles.itemIcon, { backgroundColor: `${ITEM_COLORS[key]}1f` }]}
                      >
                        <Ionicons
                          name={
                            key === "book"
                              ? "book-outline"
                              : key === "pencil"
                                ? "pencil-outline"
                                : "create-outline"
                          }
                          size={15}
                          color={ITEM_COLORS[key]}
                        />
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={styles.itemName}>{KIT_ITEMS[key].short}</Text>
                        <Text style={styles.itemMeta}>
                          {item.lastIssued
                            ? `Last issued ${fmtDate(item.lastIssued)} · ${item.qty} given`
                            : "Not issued yet"}
                          {item.renewedWith ? " · renewal swapped" : ""}
                        </Text>
                        <Text style={styles.itemDue}>
                          {item.dueTo
                            ? `Renewal window ${fmtDate(item.dueFrom)} – ${fmtDate(item.dueTo)}`
                            : KIT_ITEMS[key].weeks}
                        </Text>
                      </View>
                      <View
                        style={[styles.pill, { backgroundColor: DUE_PILL[item.state].bg }]}
                      >
                        <Text style={[styles.pillText, { color: DUE_PILL[item.state].color }]}>
                          {item.state === "none" ? "—" : DUE_LABELS[item.state].split(" ").slice(-1)[0]}
                        </Text>
                      </View>
                    </View>
                  );
                })}
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="add-circle-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Issue items</Text>
                </View>
                <Text style={styles.hint}>
                  Quantities deduct from stock straight away. Toggle the swap switch when
                  collecting the worn item back.
                </Text>
                {KIT_ITEM_KEYS.map((key) => (
                  <View key={key} style={styles.qtyRow}>
                    <Text style={styles.qtyLabel}>{KIT_ITEMS[key].short}</Text>
                    <TextInput
                      style={styles.qtyInput}
                      keyboardType="number-pad"
                      placeholder="0"
                      placeholderTextColor={colors.muted}
                      value={qty[key]}
                      onChangeText={(t) => setQty((prev) => ({ ...prev, [key]: t }))}
                      editable={!saving}
                    />
                  </View>
                ))}

                <View style={styles.switchRow}>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.switchLabel}>Renewal — old item shown and swapped</Text>
                    <Text style={styles.switchHint}>Athletes bring the worn item back to swap.</Text>
                  </View>
                  <Switch
                    value={swap}
                    disabled={saving}
                    onValueChange={setSwap}
                    trackColor={{ false: colors.gray[200], true: `${colors.gold}80` }}
                    thumbColor={swap ? colors.goldDark : "#f4f4f5"}
                  />
                </View>

                <Text style={styles.fieldLabel}>Note (optional)</Text>
                <TextInput
                  style={styles.input}
                  placeholder="e.g. Term 4 allocation"
                  placeholderTextColor={colors.muted}
                  value={note}
                  onChangeText={setNote}
                  editable={!saving}
                />

                <TouchableOpacity
                  style={[styles.primaryBtn, saving && { opacity: 0.6 }]}
                  onPress={allocate}
                  disabled={saving}
                  activeOpacity={0.85}
                >
                  {saving ? (
                    <ActivityIndicator color={colors.white} size="small" />
                  ) : (
                    <Text style={styles.primaryBtnText}>Record allocation</Text>
                  )}
                </TouchableOpacity>
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="checkbox-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>November exam check</Text>
                </View>
                <View style={styles.switchRow}>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.switchLabel}>Stationery checked for exams</Text>
                    <Text style={styles.switchHint}>
                      {learner.examCheckedAt
                        ? `Checked ${fmtDate(learner.examCheckedAt)}`
                        : "Confirm books, pens and pencils are exam-ready."}
                    </Text>
                  </View>
                  <Switch
                    value={Boolean(learner.examCheckedAt)}
                    onValueChange={toggleExamCheck}
                    trackColor={{ false: colors.gray[200], true: `${colors.gold}80` }}
                    thumbColor={learner.examCheckedAt ? colors.goldDark : "#f4f4f5"}
                  />
                </View>
              </View>

              <View style={styles.card}>
                <View style={styles.cardHead}>
                  <Ionicons name="time-outline" size={15} color={colors.goldDark} />
                  <Text style={styles.cardTitle}>Allocation history</Text>
                  <Text style={styles.cardMeta}>{history.length}</Text>
                </View>
                {history.length === 0 ? (
                  <Text style={styles.emptyText}>No allocations recorded yet.</Text>
                ) : (
                  history.map((mv) => (
                    <View key={mv._id} style={styles.historyRow}>
                      <View
                        style={[styles.itemIcon, { backgroundColor: `${ITEM_COLORS[mv.item]}1f` }]}
                      >
                        <Ionicons name="arrow-up-outline" size={13} color={ITEM_COLORS[mv.item]} />
                      </View>
                      <View style={{ flex: 1 }}>
                        <Text style={styles.historyTitle}>
                          {KIT_ITEMS[mv.item].short} × {mv.qty}
                          {mv.swapVerified ? " · swapped" : ""}
                        </Text>
                        <Text style={styles.historyMeta}>
                          {fmtDate(mv.date)}
                          {mv.note ? ` · ${mv.note}` : ""}
                        </Text>
                      </View>
                      <TouchableOpacity
                        style={styles.rowAction}
                        onPress={() => removeAllocation(mv)}
                        hitSlop={6}
                        accessibilityLabel={`Delete ${KIT_ITEMS[mv.item].short} allocation`}
                      >
                        <Ionicons name="trash-outline" size={15} color={colors.muted} />
                      </TouchableOpacity>
                    </View>
                  ))
                )}
              </View>
            </ScrollView>
          )}
        </KeyboardAvoidingView>
        <SuccessModal
          visible={success !== null}
          title={success?.title ?? ""}
          message={success?.message}
          onClose={() => setSuccess(null)}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

