const fmtDate = (value?: string) => {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-ZA", { day: "numeric", month: "short" });
};

/** "YYYY-MM-DD" that parses to a real date. */
const isDateOnly = (value: string) =>
  /^\d{4}-\d{2}-\d{2}$/.test(value) && !isNaN(new Date(value).getTime());

const quickDueOptions = [
  { label: "1 week", days: 7 },
  { label: "2 weeks", days: 14 },
  { label: "1 month", days: 30 },
];

type Tab = "review" | "open" | "mine" | "all";

const USER_TABS: { key: Tab; label: string }[] = [
  { key: "open", label: "Open" },
  { key: "mine", label: "My work" },
  { key: "all", label: "All" },
];

const ADMIN_TABS: { key: Tab; label: string }[] = [
  { key: "review", label: "In review" },
  { key: "open", label: "Open" },
  { key: "mine", label: "My work" },
  { key: "all", label: "All" },
];

function ServiceCard({
  item,
  onPress,
}: {
  item: ClubService;
  onPress: () => void;
}) {
  const type = SERVICE_TYPE_META[item.type];
  const status = SERVICE_STATUS_META[item.status];
  // Snapshot "now" once per card so the overdue check stays render-pure.
  const [now] = useState(() => Date.now());
  return (
    <TouchableOpacity
      style={styles.card}
      activeOpacity={0.85}
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={item.title}
    >
      <View style={styles.cardTop}>
        <View style={[styles.typeChip, { backgroundColor: `${type.color}16` }]}>
          <Ionicons name={type.icon} size={13} color={type.color} />
          <Text style={[styles.typeChipText, { color: type.color }]}>
            {type.label}
          </Text>
        </View>
        <View style={[styles.pill, { backgroundColor: status.bg }]}>
          <Text style={[styles.pillText, { color: status.color }]}>
            {status.label}
          </Text>
        </View>
      </View>

      <Text style={styles.cardTitle} numberOfLines={2}>
        {item.title}
      </Text>
      <Text style={styles.cardDesc} numberOfLines={2}>
        {item.description}
      </Text>

      <View style={styles.cardFoot}>
        {item.clubSlug ? (
          <View style={styles.clubChip}>
            <Ionicons name="people" size={11} color={colors.forest} />
            <Text style={styles.clubChipText}>
              {CLUBS.find((c) => c.slug === item.clubSlug)?.name || item.clubSlug}
            </Text>
          </View>
        ) : null}
        {item.dueDate && item.status !== "approved" && item.status !== "closed" ? (
          <View
            style={[
              styles.dueChip,
              new Date(item.dueDate).getTime() < now && styles.dueChipOverdue,
            ]}
          >
            <Ionicons name="calendar-outline" size={11} color={colors.forest} />
            <Text style={styles.dueChipText}>Due {fmtDate(item.dueDate)}</Text>
          </View>
        ) : null}
        {item.acceptedByName && item.status !== "open" ? (
          <Text style={styles.cardMeta}>
            <Ionicons name="person" size={11} color={colors.muted} />{" "}
            {item.isClaimedByMe ? "You" : item.acceptedByName}
          </Text>
        ) : (
          <Text style={styles.cardMeta}>Posted {fmtDate(item.createdAt)}</Text>
        )}
        {item.status === "submitted" && item.submission?.githubLink ? (
          <Ionicons name="logo-github" size={14} color={colors.forest} />
        ) : null}
      </View>
    </TouchableOpacity>
  );
}

function PostServiceModal({
  visible,
  onClose,
  onCreated,
}: {
  visible: boolean;
  onClose: () => void;
  onCreated: () => void;
}) {
  const serviceDraftKey = "form-draft:admin:service";
  const [title, setTitle] = usePersistentFormState(`${serviceDraftKey}:title`, "");
  const [description, setDescription] = usePersistentFormState(`${serviceDraftKey}:description`, "");
  const [type, setType] = usePersistentFormState<ServiceType>(`${serviceDraftKey}:type`, "bug");
  const [clubSlug, setClubSlug] = usePersistentFormState<string | null>(`${serviceDraftKey}:clubSlug`, null);
  const [dueDate, setDueDate] = usePersistentFormState(`${serviceDraftKey}:dueDate`, "");
  const [rewardAmount, setRewardAmount] = usePersistentFormState(`${serviceDraftKey}:rewardAmount`, "");
  const [busy, setBusy] = useState(false);

  const reset = () => {
    setTitle("");
    setDescription("");
    setType("bug");
    setClubSlug(null);
    setDueDate("");
    setRewardAmount("");
  };

  const submit = async () => {
    if (!title.trim() || !description.trim()) {
      Alert.alert("Missing details", "Add a title and description.");
      return;
    }
    const due = dueDate.trim();
    const reward = Number(rewardAmount);
    if (!rewardAmount.trim() || !Number.isFinite(reward) || reward <= 0) {
      Alert.alert("Payment amount required", "Enter the amount paid after approval.");
      return;
    }
    if (due && !isDateOnly(due)) {
      Alert.alert("Invalid due date", "Use the format YYYY-MM-DD.");
      return;
    }
    setBusy(true);
    try {
      await servicesApi.create({
        title: title.trim(),
        description: description.trim(),
        type,
        clubSlug,
        dueDate: due || null,
        rewardAmount: reward,
      });
      await clearPersistentFormDraft(serviceDraftKey);
      reset();
      onClose();
      onCreated();
    } catch (e: any) {
      Alert.alert("Could not post", e?.message || "Please try again.");
    }
    setBusy(false);
  };

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <View style={styles.sheetBackdrop}>
        <KeyboardAvoidingView
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          style={styles.sheetWrap}
        >
          <View style={styles.sheet}>
            <View style={styles.sheetHead}>
              <Text style={styles.sheetTitle}>Post a service</Text>
              <TouchableOpacity onPress={onClose} style={styles.sheetClose}>
                <Ionicons name="close" size={18} color={colors.muted} />
              </TouchableOpacity>
            </View>

            <ScrollView
              style={styles.sheetBody}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <Text style={styles.fieldLabel}>Title</Text>
              <TextInput
                style={styles.input}
                value={title}
                onChangeText={setTitle}
                placeholder="e.g. Fix the event payment bug"
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>What needs doing?</Text>
              <TextInput
                style={[styles.input, styles.textarea]}
                value={description}
                onChangeText={setDescription}
                multiline
                placeholder="Describe the work, links to files or context, and what 'done' looks like."
                placeholderTextColor={colors.muted}
              />

              <Text style={styles.fieldLabel}>Type</Text>
              <View style={styles.chipRow}>
                {(Object.keys(SERVICE_TYPE_META) as ServiceType[]).map((key) => {
                  const meta = SERVICE_TYPE_META[key];
                  const active = type === key;
                  return (
                    <TouchableOpacity
                      key={key}
                      style={[
                        styles.typeOption,
                        active && {
                          borderColor: meta.color,
                          backgroundColor: `${meta.color}14`,
                        },
                      ]}
                      activeOpacity={0.8}
                      onPress={() => setType(key)}
                    >
                      <Ionicons
                        name={meta.icon}
                        size={14}
                        color={active ? meta.color : colors.muted}
                      />
                      <Text
                        style={[
                          styles.typeOptionText,
                          active && { color: meta.color },
                        ]}
                      >
                        {meta.label}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              <Text style={styles.fieldLabel}>Club (optional)</Text>
              <View style={styles.chipRow}>
                <TouchableOpacity
                  style={[styles.clubOption, !clubSlug && styles.clubOptionActive]}
                  activeOpacity={0.8}
                  onPress={() => setClubSlug(null)}
                >
                  {!clubSlug && (
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  )}
                  <Text style={[styles.clubOptionText, !clubSlug && styles.clubOptionTextActive]}>
                    All members
                  </Text>
                </TouchableOpacity>
                {CLUBS.filter((c) => c.slug !== "sprout").map((club) => {
                  const active = clubSlug === club.slug;
                  return (
                    <TouchableOpacity
                      key={club.slug}
                      style={[styles.clubOption, active && styles.clubOptionActive]}
                      activeOpacity={0.8}
                      onPress={() => setClubSlug(active ? null : club.slug)}
                    >
                      {active && (
                        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      )}
                      <Text
                        style={[styles.clubOptionText, active && styles.clubOptionTextActive]}
                      >
                        {club.name}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              <Text style={styles.fieldLabel}>Due date (optional)</Text>
              <View style={styles.chipRow}>
                {quickDueOptions.map((opt) => {
                  const d = new Date();
                  d.setDate(d.getDate() + opt.days);
                  const iso = d.toISOString().slice(0, 10);
                  const active = dueDate === iso;
                  return (
                    <TouchableOpacity
                      key={opt.label}
                      style={[styles.clubOption, active && styles.clubOptionActive]}
                      activeOpacity={0.8}
                      onPress={() => setDueDate(active ? "" : iso)}
                    >
                      {active && (
                        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                      )}
                      <Text
                        style={[styles.clubOptionText, active && styles.clubOptionTextActive]}
                      >
                        {opt.label}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              <TextInput
                style={styles.input}
                value={dueDate}
                onChangeText={setDueDate}
                placeholder="YYYY-MM-DD"
                placeholderTextColor={colors.muted}
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="numbers-and-punctuation"
              />

              <Text style={styles.fieldLabel}>Reward amount</Text>
              <TextInput
                style={styles.input}
                value={rewardAmount}
                onChangeText={setRewardAmount}
                placeholder="Amount paid in Smart Saver"
                placeholderTextColor={colors.muted}
                keyboardType="decimal-pad"
              />
            </ScrollView>

            <PrimaryButton
              label="Post service"
              icon="arrow-forward"
              onPress={submit}
              disabled={busy}
              loading={busy}
            />
          </View>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

export default function ServicesScreen() {
  const { tab: tabParam } = useLocalSearchParams<{ tab?: string }>();
  const [isAdmin, setIsAdmin] = useState(false);
  const [tab, setTab] = useState<Tab>(() => {
    const t = typeof tabParam === "string" ? tabParam : undefined;
    return t === "review" || t === "mine" || t === "all" ? t : "open";
  });
  const [items, setItems] = useState<ClubService[] | null>(null);
  const [error, setError] = useState("");
  const [refreshing, setRefreshing] = useState(false);
  const [postOpen, setPostOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await servicesApi.list();
      setItems(res.data);
      setError("");
    } catch (e: any) {
      setError(e?.message || "Could not reach the server.");
    }
  }, []);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      const admin = session?.user?.role === "admin";
      setIsAdmin(admin);
      if (!admin) setTab((current) => (current === "review" ? "open" : current));
      await load();
    })();
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

  const tabs = isAdmin ? ADMIN_TABS : USER_TABS;

  const visible = useMemo(() => {
    if (!items) return [];
    if (tab === "mine") return items.filter((s) => s.isClaimedByMe);
    if (tab === "open") return items.filter((s) => s.status === "open");
    if (tab === "review") return items.filter((s) => s.status === "submitted");
    return items;
  }, [items, tab]);

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <View style={styles.bar}>
          <TouchableOpacity
            onPress={() => router.back()}
            style={styles.iconBtn}
            accessibilityLabel="Back"
          >
            <Ionicons name="chevron-back" size={20} color={colors.forest} />
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={styles.pageEyebrow}>SERVICES</Text>
            <Text style={styles.pageTitle}>Skills at work</Text>
          </View>
          {isAdmin ? (
            <TouchableOpacity
              onPress={() => setPostOpen(true)}
              style={styles.addBtn}
              accessibilityLabel="Post a service"
            >
              <Ionicons name="add" size={22} color={colors.forest} />
            </TouchableOpacity>
          ) : null}
        </View>

        <View>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.tabsRow}
          >
            {tabs.map((t) => {
              const active = tab === t.key;
              return (
                <TouchableOpacity
                  key={t.key}
                  style={[styles.tab, active && styles.tabActive]}
                  activeOpacity={0.8}
                  onPress={() => setTab(t.key)}
                >
                  {active && (
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  )}
                  <Text style={[styles.tabText, active && styles.tabTextActive]}>
                    {t.label}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        </View>

        {items === null && !error ? (
          <View style={styles.skeletonWrap}>
            {[0, 1, 2, 3].map((i) => (
              <SkeletonPulse key={i} style={styles.skeletonCard} />
            ))}
          </View>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load services"
            subtitle={error}
            actionLabel="Retry"
            onAction={load}
          />
        ) : (
          <FlatList
            data={visible}
            keyExtractor={(item) => item._id}
            contentContainerStyle={styles.list}
            refreshControl={
              <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.forest} />
            }
            renderItem={({ item }) => (
              <ServiceCard
                item={item}
                onPress={() => router.push(`/services/${item._id}`)}
              />
            )}
            ListEmptyComponent={
              <EmptyState
                icon="briefcase-outline"
                eyebrow={
                  tab === "mine"
                    ? "Nothing claimed yet"
                    : tab === "review"
                      ? "Review queue clear"
                      : "No services here"
                }
                title={
                  tab === "mine"
                    ? "You haven't accepted a service"
                    : tab === "review"
                      ? "No work waiting"
                      : "No services right now"
                }
                subtitle={
                  tab === "mine"
                    ? "Accept an open service and your work shows up here."
                    : "New services posted by admins appear on the Open tab."
                }
                compact
              />
            }
          />
        )}

        <PostServiceModal
          visible={postOpen}
          onClose={() => setPostOpen(false)}
          onCreated={load}
        />
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

