import { Ionicons } from "@expo/vector-icons";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  BackHandler,
  Linking,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { useFocusEffect, useLocalSearchParams, router } from "expo-router";
import { colors } from "@/constants/colors";
import { communityApi, type ParticipantUser } from "@/services/community";
import { waLink, telLink } from "@/utils/phone";
import { GradientBox } from "@/constants/gradients";

const SECTION_META: Record<string, { label: string; icon: any; color: string; bg: string }> = {
  events: { label: "Event", icon: "calendar-outline", color: colors.gold, bg: colors.lightGreen },
  skills: { label: "Skill", icon: "hand-right-outline", color: colors.forest, bg: colors.lightGreen },
  groups: { label: "Group", icon: "people-outline", color: colors.forestSoft, bg: colors.cream },
  jobs: { label: "Job", icon: "briefcase-outline", color: colors.status.pending, bg: colors.statusBg.pending },
  requests: { label: "Prayer", icon: "heart-outline", color: colors.status.rejected, bg: colors.statusBg.rejected },
};

function formatShortDate(iso?: string): string {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  } catch {
    return "";
  }
}

function participantDateLabel(u: ParticipantUser): string {
  if (u.registeredAt) return `Registered ${formatShortDate(u.registeredAt)}`;
  if (u.connectedAt) return `Connected ${formatShortDate(u.connectedAt)}`;
  if (u.appliedAt) return `Applied ${formatShortDate(u.appliedAt)}`;
  return "";
}

export default function DetailsScreen() {
  const { section, id, title, meta, count } = useLocalSearchParams<{
    section: string;
    id: string;
    title?: string;
    meta?: string;
    count?: string;
  }>();

  const sec = SECTION_META[section || ""] || SECTION_META.events;
  const [users, setUsers] = useState<ParticipantUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      router.back();
      return true;
    });
    return () => sub.remove();
  }, []);

  const load = useCallback(async () => {
    try {
      let data: ParticipantUser[] = [];
      if (section === "events") {
        data = (await communityApi.getEventParticipants(id)).data || [];
      } else if (section === "skills") {
        data = (await communityApi.getSkillParticipants(id)).data || [];
      } else if (section === "groups") {
        data = (await communityApi.getGroupParticipants(id)).data || [];
      } else if (section === "jobs") {
        data = (await communityApi.getJobParticipants(id)).data || [];
      }
      setUsers(data);
    } catch {
      Alert.alert("Error", "Failed to load participants.");
    } finally {
      setLoading(false);
    }
  }, [section, id]);

  useFocusEffect(
    useCallback(() => {
      setLoading(true);
      load();
    }, [load]),
  );

  const onRefresh = async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  };

  const email = (u: ParticipantUser) => u.email || u.registrationEmail;

  const emailAll = () => {
    const list = users
      .map((u) => email(u))
      .filter((e): e is string => !!e)
      .filter((e, i, arr) => arr.indexOf(e) === i);
    if (list.length === 0) {
      Alert.alert("No emails", "None of the participants shared an email address.");
      return;
    }
    Linking.openURL(`mailto:?bcc=${encodeURIComponent(list.join(","))}&subject=${encodeURIComponent(title || sec.label)}`).catch(() =>
      Alert.alert("Error", "Could not open your email app."),
    );
  };

  const contactRow = (
    icon: any,
    label: string,
    value: string | undefined | null,
    onPress?: () => void,
  ) => {
    if (!value) return null;
    return (
      <TouchableOpacity
        style={styles.contactRow}
        onPress={onPress}
        disabled={!onPress}
        activeOpacity={0.7}
      >
        <Ionicons name={icon} size={13} color={colors.goldDark} />
        <Text style={styles.contactRowText} numberOfLines={1}>
          {label}: {value}
        </Text>
      </TouchableOpacity>
    );
  };

  const renderParticipant = (u: ParticipantUser) => {
    const mail = email(u);
    const wa = waLink(u.phone);
    return (
      <View key={u.id} style={styles.participantCard}>
        <View style={styles.participantTop}>
          <View style={styles.participantAvatar}>
            <Text style={styles.participantAvatarText}>
              {(u.fullName || u.name || "?").charAt(0).toUpperCase()}
            </Text>
          </View>
          <View style={styles.participantBody}>
            <Text style={styles.participantName}>
              {u.fullName || u.name}
              {u.bringingPartner ? " + guest" : ""}
            </Text>
            <Text style={styles.participantDate}>{participantDateLabel(u)}</Text>
          </View>
          <View style={styles.chipRow}>
            {wa && (
              <TouchableOpacity
                style={styles.contactChip}
                onPress={() => Linking.openURL(wa)}
                accessibilityLabel={`WhatsApp ${u.fullName || u.name}`}
              >
                <Ionicons name="logo-whatsapp" size={16} color="#25D366" />
              </TouchableOpacity>
            )}
            {mail && (
              <TouchableOpacity
                style={styles.contactChip}
                onPress={() => Linking.openURL(`mailto:${mail}`)}
                accessibilityLabel={`Email ${u.fullName || u.name}`}
              >
                <Ionicons name="mail-outline" size={16} color={colors.goldDark} />
              </TouchableOpacity>
            )}
            {u.phone && (
              <TouchableOpacity
                style={styles.contactChip}
                onPress={() => Linking.openURL(telLink(u.phone) || `tel:${u.phone}`)}
                accessibilityLabel={`Call ${u.fullName || u.name}`}
              >
                <Ionicons name="call-outline" size={16} color={colors.forest} />
              </TouchableOpacity>
            )}
          </View>
        </View>

        {contactRow("mail-outline", "Email", mail, mail ? () => Linking.openURL(`mailto:${mail}`) : undefined)}
        {contactRow("call-outline", "Phone", u.phone, u.phone ? () => Linking.openURL(telLink(u.phone) || `tel:${u.phone}`) : undefined)}
        {contactRow("medkit-outline", "Emergency", u.emergencyContact)}
        {!!u.partner?.fullName && (
          <View style={styles.contactRow}>
            <Ionicons name="people-outline" size={13} color={colors.goldDark} />
            <Text style={styles.contactRowText} numberOfLines={1}>
              Guest: {u.partner.fullName}
              {u.partner.phone ? ` · ${u.partner.phone}` : ""}
            </Text>
          </View>
        )}
        {!!u.notes && (
          <View style={styles.contactRow}>
            <Ionicons name="document-text-outline" size={13} color={colors.goldDark} />
            <Text style={styles.contactRowText}>{u.notes}</Text>
          </View>
        )}
      </View>
    );
  };

  return (
    <SafeAreaView style={styles.safe} edges={["top"]}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => router.back()} style={styles.backBtn}>
          <Ionicons name="chevron-back" size={20} color={colors.darkGreen} />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>{sec.label} Details</Text>
        <View style={styles.headerCount}>
          <Text style={styles.headerCountText}>{users.length}</Text>
        </View>
      </View>

      <ScrollView
        contentContainerStyle={styles.scroll}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={colors.forest} />
        }
      >
        <View style={styles.heroCard}>
          <View style={[styles.heroIconBox, { backgroundColor: sec.bg }]}>
            <Ionicons name={sec.icon} size={22} color={sec.color} />
          </View>
          <View style={styles.heroBody}>
            <Text style={styles.heroTitle}>{title || "Untitled"}</Text>
            {!!meta && <Text style={styles.heroMeta}>{meta}</Text>}
            <Text style={styles.heroSub}>
              {users.length} {users.length === 1 ? "participant" : "participants"}
              {count ? ` · ${count} total` : ""}
            </Text>
          </View>
        </View>

        <View style={styles.bulkRow}>
          <TouchableOpacity style={styles.bulkBtn} onPress={emailAll} activeOpacity={0.85}>
            <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
            <Ionicons name="mail-outline" size={15} color={colors.white} />
            <Text style={styles.bulkBtnText}>Email all</Text>
          </TouchableOpacity>
        </View>

        {loading ? (
          <View style={styles.loading}>
            <ActivityIndicator size="large" color={colors.forest} />
          </View>
        ) : users.length === 0 ? (
          <View style={styles.empty}>
            <Ionicons name="people-outline" size={40} color={colors.gray[400]} />
            <Text style={styles.emptyTitle}>No participants yet</Text>
            <Text style={styles.emptyText}>People who join will appear here.</Text>
          </View>
        ) : (
          users.map(renderParticipant)
        )}

        <View style={{ height: 40 }} />
      </ScrollView>
    </SafeAreaView>
  );
}

