import { Ionicons } from "@expo/vector-icons";
import { Image } from "expo-image";
import * as ImagePicker from "expo-image-picker";
import { router, useLocalSearchParams } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  InteractionManager,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { uploadStoreImage } from "@/services/cloudinary";
import {
  createStoreProduct,
  deleteStoreProduct,
  fetchAdminStoreProducts,
  STORE_CATEGORIES,
  updateStoreProduct,
  type StoreCategory,
  type StoreProduct,
} from "@/services/store";

const splitList = (value: string) =>
  value
    .split(/[\n,]+/)
    .map((item) => item.trim())
    .filter(Boolean);

export default function AdminStoreScreen() {
  const { id, mode } = useLocalSearchParams<{ id?: string; mode?: string }>();
  const [name, setName] = useState("");
  const [blurb, setBlurb] = useState("");
  const [category, setCategory] = useState<StoreCategory>("Apparel");
  const [price, setPrice] = useState("");
  const [offerPrice, setOfferPrice] = useState("");
  const [sizes, setSizes] = useState("");
  const [details, setDetails] = useState("");
  const [cover, setCover] = useState("");
  const [images, setImages] = useState<string[]>([]);
  const [inStock, setInStock] = useState(true);
  const [active, setActive] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<StoreProduct[]>([]);
  const isEditing = typeof id === "string" && id.length > 0;
  const isCreating = mode === "create";

  useEffect(() => {
    const task = InteractionManager.runAfterInteractions(() => {
      if (isEditing) {
        setLoading(true);
        fetchAdminStoreProducts()
          .then((items) => {
            const product = items.find((item) => item._id === id || item.id === id);
            if (!product) {
              Alert.alert("Product not found", "This merchandise item could not be loaded.");
              return;
            }
            setName(product.name);
            setBlurb(product.blurb);
            setCategory(product.category);
            setPrice(String(product.price));
            setOfferPrice(product.offerPrice == null ? "" : String(product.offerPrice));
            setSizes(product.sizes.join(", "));
            setDetails(product.details.join("\n"));
            setCover(product.image);
            setImages(product.images);
            setInStock(product.inStock);
            setActive(product.active);
          })
          .catch((error) => Alert.alert("Could not load product", error instanceof Error ? error.message : "Please try again."))
          .finally(() => setLoading(false));
      } else if (isCreating) {
        setLoading(false);
      } else {
        setLoading(true);
        fetchAdminStoreProducts()
          .then(setProducts)
          .catch((error) => Alert.alert("Could not load merchandise", error instanceof Error ? error.message : "Please try again."))
          .finally(() => setLoading(false));
      }
    });
    return () => task.cancel();
  }, [id, isEditing, isCreating]);

  const pickImage = async (gallery: boolean) => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ["images"],
      allowsEditing: !gallery,
      allowsMultipleSelection: gallery,
      quality: 0.8,
      base64: true,
    });
    if (result.canceled || !result.assets?.length) return;

    setUploading(true);
    try {
      const urls = await Promise.all(
        result.assets.map((asset) => uploadStoreImage(asset)),
      );
      if (gallery) {
        setImages((current) => [...current, ...urls]);
      } else {
        setCover(urls[0]);
      }
    } catch (error) {
      Alert.alert("Upload failed", error instanceof Error ? error.message : "Please try again.");
    } finally {
      setUploading(false);
    }
  };

  const save = async () => {
    const numericPrice = Number(price);
    const numericOffer = offerPrice.trim() ? Number(offerPrice) : null;
    if (!name.trim()) return Alert.alert("Missing name", "Enter the product name.");
    if (!Number.isFinite(numericPrice) || numericPrice < 0) {
      return Alert.alert("Invalid price", "Enter a valid regular price.");
    }
    if (numericOffer !== null && (!Number.isFinite(numericOffer) || numericOffer < 0)) {
      return Alert.alert("Invalid offer price", "Enter a valid offer price.");
    }
    if (numericOffer !== null && numericOffer > numericPrice) {
      return Alert.alert("Invalid offer price", "The offer price cannot exceed the regular price.");
    }
    if (!cover) return Alert.alert("Cover image required", "Add a cover image for the product.");

    setSaving(true);
    try {
      const input = {
        name: name.trim(),
        blurb: blurb.trim(),
        category,
        price: numericPrice,
        offerPrice: numericOffer,
        image: cover,
        images,
        sizes: splitList(sizes),
        details: splitList(details),
        inStock,
        active,
      };
      if (isEditing) {
        await updateStoreProduct(id, input);
      } else {
        await createStoreProduct(input);
      }
      Alert.alert(isEditing ? "Merchandise updated" : "Merchandise added", isEditing ? "Your changes have been saved." : "The product is now available in the store.", [
        { text: "OK", onPress: () => router.back() },
      ]);
    } catch (error) {
      Alert.alert("Could not add merchandise", error instanceof Error ? error.message : "Please try again.");
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = () => {
    Alert.alert("Delete merchandise?", "This product will be removed from the store.", [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          setSaving(true);
          try {
            if (typeof id !== "string") return;
            await deleteStoreProduct(id);
            Alert.alert("Deleted", "The product has been removed.", [
              { text: "OK", onPress: () => router.replace("/admin-store" as any) },
            ]);
          } catch (error) {
            Alert.alert("Could not delete merchandise", error instanceof Error ? error.message : "Please try again.");
          } finally {
            setSaving(false);
          }
        },
      },
    ]);
  };

  if (!isEditing && !isCreating) {
    return (
      <SafeAreaView style={styles.safe} edges={["top", "bottom"]}>
        <View style={styles.header}>
          <TouchableOpacity onPress={() => router.back()} style={styles.iconButton}>
            <Ionicons name="arrow-back" size={22} color={colors.ink} />
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Manage Merchandise</Text>
          <View style={styles.headerSpacer} />
        </View>
        <ScrollView contentContainerStyle={styles.listContent}>
          <TouchableOpacity style={styles.newButton} onPress={() => router.setParams({ mode: "create", id: undefined })}>
            <Ionicons name="add-circle-outline" size={22} color="#fff" />
            <Text style={styles.newButtonText}>Add new merchandise</Text>
          </TouchableOpacity>
          {loading ? <ActivityIndicator color={colors.gold} /> : null}
          {products.map((product) => (
            <TouchableOpacity
              key={product._id || product.id}
              style={styles.productRow}
              onPress={() => router.setParams({ id: product._id || product.id })}
            >
              <Image source={{ uri: product.image }} style={styles.productImage} contentFit="cover" />
              <View style={styles.productInfo}>
                <Text style={styles.productName} numberOfLines={1}>{product.name}</Text>
                <Text style={styles.productPrice}>R {Math.round(product.price)}</Text>
                <Text style={styles.editText}>Tap to edit</Text>
              </View>
              <Ionicons name="chevron-forward" size={20} color={colors.muted} />
            </TouchableOpacity>
          ))}
        </ScrollView>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe} edges={["top", "bottom"]}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => router.back()} style={styles.iconButton}>
          <Ionicons name="arrow-back" size={22} color={colors.ink} />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>{isEditing ? "Edit Merchandise" : "Add Merchandise"}</Text>
        <View style={styles.headerSpacer} />
      </View>

      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={{ flex: 1 }}
      >
        <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
        <Text style={styles.sectionTitle}>Product details</Text>
        <TextInput value={name} onChangeText={setName} placeholder="Product name" style={styles.input} />
        <TextInput value={blurb} onChangeText={setBlurb} placeholder="Description" multiline style={[styles.input, styles.textArea]} />

        <Text style={styles.label}>Category</Text>
        <View style={styles.chips}>
          {STORE_CATEGORIES.map((item) => (
            <TouchableOpacity
              key={item}
              style={[styles.chip, category === item && styles.chipActive]}
              onPress={() => setCategory(item)}
            >
              <Text style={[styles.chipText, category === item && styles.chipTextActive]}>{item}</Text>
            </TouchableOpacity>
          ))}
        </View>

        <View style={styles.row}>
          <TextInput value={price} onChangeText={setPrice} placeholder="Regular price" keyboardType="decimal-pad" style={[styles.input, styles.half]} />
          <TextInput value={offerPrice} onChangeText={setOfferPrice} placeholder="Offer price" keyboardType="decimal-pad" style={[styles.input, styles.half]} />
        </View>
        <TextInput value={sizes} onChangeText={setSizes} placeholder="Sizes: S, M, L, XL" style={styles.input} />
        <TextInput value={details} onChangeText={setDetails} placeholder={"Product details (one per line)"} multiline style={[styles.input, styles.textArea]} />

        <Text style={styles.sectionTitle}>Images</Text>
        <View style={styles.imageRow}>
          <TouchableOpacity style={styles.addImage} onPress={() => pickImage(false)} disabled={uploading}>
            {cover ? (
              <Image source={{ uri: cover }} style={styles.preview} contentFit="cover" />
            ) : (
              <>
                <Ionicons name="image-outline" size={28} color={colors.gold} />
                <Text style={styles.addImageText}>Cover image</Text>
              </>
            )}
          </TouchableOpacity>
          {cover ? (
            <TouchableOpacity style={styles.removeCover} onPress={() => setCover("")}>
              <Ionicons name="close-circle" size={22} color={colors.muted} />
            </TouchableOpacity>
          ) : null}
        </View>

        <TouchableOpacity style={styles.galleryButton} onPress={() => pickImage(true)} disabled={uploading}>
          <Ionicons name="images-outline" size={20} color={colors.gold} />
          <Text style={styles.galleryButtonText}>Add gallery images</Text>
        </TouchableOpacity>
        <View style={styles.gallery}>
          {images.map((uri, index) => (
            <View key={`${uri}-${index}`} style={styles.galleryItem}>
              <Image source={{ uri }} style={styles.galleryPreview} contentFit="cover" />
              <TouchableOpacity style={styles.galleryRemove} onPress={() => setImages((current) => current.filter((_, i) => i !== index))}>
                <Ionicons name="close-circle" size={20} color={colors.ink} />
              </TouchableOpacity>
            </View>
          ))}
        </View>

        <View style={styles.switchRow}>
          <Text style={styles.switchLabel}>In stock</Text>
          <Switch value={inStock} onValueChange={setInStock} />
        </View>
        <View style={styles.switchRow}>
          <Text style={styles.switchLabel}>Published</Text>
          <Switch value={active} onValueChange={setActive} />
        </View>

        {isEditing ? (
          <TouchableOpacity style={styles.deleteButton} onPress={confirmDelete} disabled={saving}>
            <Text style={styles.deleteText}>Delete Merchandise</Text>
          </TouchableOpacity>
        ) : null}
        <TouchableOpacity style={styles.saveButton} onPress={save} disabled={saving || uploading}>
          {saving || uploading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.saveText}>{isEditing ? "Save Changes" : "Add Merchandise"}</Text>
          )}
        </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: "#fff" },
  header: { height: 56, flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: 16, borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: "#eee" },
  iconButton: { width: 40, height: 40, alignItems: "center", justifyContent: "center" },
  headerTitle: { fontFamily: fonts.sansBold, fontSize: 18, color: colors.ink },
  headerSpacer: { width: 40 },
  listContent: { padding: 16, gap: 12 },
  newButton: { height: 50, borderRadius: 12, backgroundColor: colors.gold, flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8 },
  newButtonText: { fontFamily: fonts.sansBold, color: "#fff", fontSize: 15 },
  productRow: { minHeight: 92, borderWidth: 1, borderColor: "#eee", borderRadius: 14, padding: 10, flexDirection: "row", alignItems: "center", gap: 12 },
  productImage: { width: 72, height: 72, borderRadius: 10, backgroundColor: colors.bg },
  productInfo: { flex: 1 },
  productName: { fontFamily: fonts.sansBold, fontSize: 15, color: colors.ink },
  productPrice: { fontFamily: fonts.sansMedium, fontSize: 13, color: colors.goldDark, marginTop: 3 },
  editText: { fontFamily: fonts.sans, fontSize: 12, color: colors.muted, marginTop: 3 },
  content: { padding: 20, paddingBottom: 40 },
  sectionTitle: { fontFamily: fonts.sansBold, fontSize: 17, color: colors.ink, marginBottom: 12, marginTop: 6 },
  label: { fontFamily: fonts.sansMedium, fontSize: 13, color: colors.muted, marginBottom: 8 },
  input: { borderWidth: 1, borderColor: "#ddd", borderRadius: 12, paddingHorizontal: 14, paddingVertical: 12, fontFamily: fonts.sans, color: colors.ink, marginBottom: 12, backgroundColor: "#fff" },
  textArea: { minHeight: 88, textAlignVertical: "top" },
  row: { flexDirection: "row", gap: 10 },
  half: { flex: 1 },
  chips: { flexDirection: "row", flexWrap: "wrap", gap: 8, marginBottom: 14 },
  chip: { borderWidth: 1, borderColor: "#ddd", borderRadius: 999, paddingHorizontal: 12, paddingVertical: 8 },
  chipActive: { backgroundColor: colors.gold, borderColor: colors.gold },
  chipText: { fontFamily: fonts.sansMedium, color: colors.ink, fontSize: 13 },
  chipTextActive: { color: "#fff" },
  imageRow: { flexDirection: "row" },
  addImage: { width: 150, height: 150, borderRadius: 14, borderWidth: 1, borderColor: "#ddd", borderStyle: "dashed", alignItems: "center", justifyContent: "center", overflow: "hidden" },
  preview: { width: "100%", height: "100%" },
  addImageText: { fontFamily: fonts.sansMedium, color: colors.gold, marginTop: 8 },
  removeCover: { marginLeft: -28, marginTop: 4, alignSelf: "flex-start" },
  galleryButton: { height: 46, marginTop: 14, borderRadius: 12, borderWidth: 1, borderColor: colors.gold, flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8 },
  galleryButtonText: { fontFamily: fonts.sansMedium, color: colors.gold },
  gallery: { flexDirection: "row", flexWrap: "wrap", gap: 10, marginTop: 12 },
  galleryItem: { width: 92, height: 92 },
  galleryPreview: { width: 92, height: 92, borderRadius: 10 },
  galleryRemove: { position: "absolute", right: -4, top: -4 },
  switchRow: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingVertical: 10 },
  switchLabel: { fontFamily: fonts.sansMedium, color: colors.ink },
  deleteButton: { height: 48, borderRadius: 14, borderWidth: 1, borderColor: colors.error, alignItems: "center", justifyContent: "center", marginTop: 18 },
  deleteText: { fontFamily: fonts.sansBold, color: colors.error },
  saveButton: { height: 52, borderRadius: 14, backgroundColor: colors.gold, alignItems: "center", justifyContent: "center", marginTop: 18 },
  saveText: { fontFamily: fonts.sansBold, color: "#fff", fontSize: 16 },
});
