import { getRequestHeaders } from "./auth";
import { API_BASE, IS_WEB } from "./config";
import { getDeviceId } from "./device-id";

const VAPID_PUBLIC_KEY = process.env.EXPO_PUBLIC_VAPID_PUBLIC_KEY || "";
const SW_URL = "/app/sw.js";
const SW_SCOPE = "/app/";

function urlBase64ToUint8Array(value: string): Uint8Array<ArrayBuffer> {
  const padding = "=".repeat((4 - (value.length % 4)) % 4);
  const base64 = (value + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(base64);
  const bytes = new Uint8Array(new ArrayBuffer(raw.length));
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

export function isWebPushSupported(): boolean {
  return (
    IS_WEB &&
    typeof window !== "undefined" &&
    typeof navigator !== "undefined" &&
    "serviceWorker" in navigator &&
    "PushManager" in window &&
    typeof Notification !== "undefined" &&
    Boolean(VAPID_PUBLIC_KEY)
  );
}

export function getWebPushPermission(): NotificationPermission | "unsupported" {
  if (!isWebPushSupported()) return "unsupported";
  try {
    return Notification.permission;
  } catch {
    return "unsupported";
  }
}

export async function requestWebPushPermission(): Promise<NotificationPermission | "unsupported"> {
  if (!isWebPushSupported()) return "unsupported";
  try {
    return await Notification.requestPermission();
  } catch {
    return getWebPushPermission();
  }
}

async function getRegistration(): Promise<ServiceWorkerRegistration | null> {
  if (!isWebPushSupported()) return null;
  try {
    const existing = await navigator.serviceWorker.getRegistration(SW_SCOPE);
    if (existing) return existing;
    return await navigator.serviceWorker.register(SW_URL, { scope: SW_SCOPE });
  } catch {
    try {
      return await navigator.serviceWorker.ready;
    } catch {
      return null;
    }
  }
}

async function subscribe(
  registration: ServiceWorkerRegistration,
): Promise<PushSubscription | null> {
  try {
    return await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
    });
  } catch {
    return null;
  }
}

async function saveSubscription(subscription: PushSubscription): Promise<PushSubscriptionJSON | null> {
  const payload = subscription.toJSON();
  try {
    const res = await fetch(`${API_BASE}/api/push-subscriptions`, {
      method: "POST",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      credentials: "include",
      body: JSON.stringify({
        subscription: payload,
        deviceId: await getDeviceId(),
      }),
    });
    return res.ok ? payload : null;
  } catch {
    return null;
  }
}

export async function enableWebPush(): Promise<PushSubscriptionJSON | null> {
  if (!isWebPushSupported()) return null;
  const permission = await requestWebPushPermission();
  if (permission !== "granted") return null;
  const registration = await getRegistration();
  if (!registration) return null;
  let subscription: PushSubscription | null = null;
  try {
    subscription = await registration.pushManager.getSubscription();
  } catch {}
  if (!subscription) subscription = await subscribe(registration);
  if (!subscription) return null;
  return saveSubscription(subscription);
}

export async function disableWebPush(): Promise<boolean> {
  if (!isWebPushSupported()) return false;
  const registration = await getRegistration();
  if (!registration) return false;
  let subscription: PushSubscription | null = null;
  try {
    subscription = await registration.pushManager.getSubscription();
  } catch {}
  if (!subscription) return true;
  let payload: PushSubscriptionJSON;
  try {
    payload = subscription.toJSON();
    await subscription.unsubscribe();
  } catch {
    return false;
  }
  try {
    const res = await fetch(`${API_BASE}/api/push-subscriptions`, {
      method: "DELETE",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      credentials: "include",
      body: JSON.stringify({ endpoint: payload.endpoint }),
    });
    return res.ok;
  } catch {
    return false;
  }
}

export async function syncWebPush(): Promise<PushSubscriptionJSON | null> {
  if (!isWebPushSupported() || getWebPushPermission() !== "granted") return null;
  const registration = await getRegistration();
  if (!registration) return null;
  let subscription: PushSubscription | null = null;
  try {
    subscription = await registration.pushManager.getSubscription();
  } catch {}
  if (!subscription) subscription = await subscribe(registration);
  if (!subscription) return null;
  return saveSubscription(subscription);
}

export async function sendTestWebPush(): Promise<boolean> {
  if (!isWebPushSupported()) return false;
  try {
    const res = await fetch(`${API_BASE}/api/push-subscriptions/test`, {
      method: "POST",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      credentials: "include",
    });
    return res.ok;
  } catch {
    return false;
  }
}
