/**
 * Live skill progress — GET/POST `/api/skills/<skillId>?levelId=<levelId>`.
 *
 * One row per user + skill + level in the backend `skill_progress`
 * collection. GET returns `{data}` with `data: null` when signed out or
 * nothing saved yet; POST takes `{levelId, criteria}` (the ticked grid) or
 * `{enroll: true, levelId}` and returns the saved row.
 */

import { cachedFetch } from "@/services/cache";
import type { ModuleProgress, SkillProgress } from "@/services/skills-catalog";

type ProgressEnvelope = { data: SkillProgress | null };
type SaveEnvelope = { data: SkillProgress };
type ModulesEnvelope = { data: ModuleProgress[] };
type ModuleSaveEnvelope = { data: ModuleProgress };

function path(skillId: string, levelId: string): string {
  return `/api/skills/${encodeURIComponent(skillId)}?levelId=${encodeURIComponent(levelId)}`;
}

function modulesPath(skillId: string): string {
  return `/api/skills/${encodeURIComponent(skillId)}/modules`;
}

export const skillsProgressApi = {
  /** The signed-in member's saved row for this level — null when none. */
  get(skillId: string, levelId: string): Promise<SkillProgress | null> {
    return cachedFetch<ProgressEnvelope>(path(skillId, levelId), {
      cacheTtl: 0,
    }).then((res) => res.data);
  },

  /** Enroll in the level (row with no ticks yet) — returns the saved row. */
  enroll(skillId: string, levelId: string): Promise<SkillProgress> {
    return cachedFetch<SaveEnvelope>(
      `/api/skills/${encodeURIComponent(skillId)}`,
      {
        method: "POST",
        body: JSON.stringify({ enroll: true, levelId }),
      },
      [`/api/skills/${encodeURIComponent(skillId)}`],
    ).then((res) => res.data);
  },
};

export type ModuleSavePatch = {
  moduleId: string;
  completed?: boolean;
  deliverableSubmitted?: boolean;
  deliverableUrl?: string;
};

export const moduleProgressApi = {
  /** The member's saved rows for every module of a skill (empty when signed out). */
  list(skillId: string): Promise<ModuleProgress[]> {
    return cachedFetch<ModulesEnvelope>(modulesPath(skillId), {
      cacheTtl: 0,
    }).then((res) => res.data ?? []);
  },

  /** Upsert one module's completion / deliverable — returns the saved row. */
  save(skillId: string, patch: ModuleSavePatch): Promise<ModuleProgress> {
    return cachedFetch<ModuleSaveEnvelope>(modulesPath(skillId), {
      method: "POST",
      body: JSON.stringify(patch),
    }, [modulesPath(skillId)]).then((res) => res.data);
  },
};
