/** Returns the verse for a given prayer time on a given day. Deterministic by day of year. */
export function verseForDate(prayer: PrayerKey, date: Date): PrayerVerse {
  const startOfYear = new Date(date.getFullYear(), 0, 0);
  const dayOfYear = Math.floor(
    (date.getTime() - startOfYear.getTime()) / 86400000,
  );
  const pool = VERSE_POOLS[prayer];
  return pool[dayOfYear % pool.length];
}

/** Returns today's verse for a given prayer time. Deterministic by day of year. */
export function todayVerse(prayer: PrayerKey): PrayerVerse {
  return verseForDate(prayer, new Date());
}
