import { useEffect, useState, type ReactNode } from "react";
import { Animated, View, type StyleProp, type ViewStyle } from "react-native";
import { colors } from "@/constants/colors";
import { IS_WEB } from "@/services/config";
/** Soft pulsing placeholder block — same pattern used by Dashboard and Community. */
export function SkeletonPulse({ style }: { style?: StyleProp<ViewStyle> }) {
  const opacity = useState(new Animated.Value(IS_WEB ? 0.5 : 0.38))[0];

  useEffect(() => {
    if (IS_WEB) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, { toValue: 0.62, duration: 900, useNativeDriver: true }),
          Animated.timing(opacity, { toValue: 0.38, duration: 900, useNativeDriver: true }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [opacity]);

  return <Animated.View style={[{ backgroundColor: colors.skeleton, borderRadius: 6 }, style, { opacity }]} />;
}

/** Renders `count` copies of a card skeleton with a consistent gap. */
export function SkeletonList({
  count = 3,
  gap = 10,
  render,
}: {
  count?: number;
  gap?: number;
  render: () => ReactNode;
}) {
  return (
    <View style={{ paddingHorizontal: 16, gap }}>
      {Array.from({ length: count }).map((_, i) => (
        <View key={i}>{render()}</View>
      ))}
    </View>
  );
}
