import Constants from "expo-constants";
import * as Device from "expo-device";
import * as Notifications from "expo-notifications";
import { Platform } from "react-native";
import { API_BASE, IS_WEB } from "./config";
import { getRequestHeaders, getSessionToken } from "./auth";
import { setupNotificationChannels } from "./notifications";
import { syncWebPush } from "./web-push";
import { getDeviceId } from "./device-id";

async function registerRemote(token: string, platform: string) {
  const authToken = await getSessionToken();
  if (!authToken) return;
  try {
    const res = await fetch(`${API_BASE}/api/push-tokens`, {
      method: "POST",
      headers: await getRequestHeaders({ "Content-Type": "application/json" }),
      body: JSON.stringify({ token, platform, deviceId: await getDeviceId() }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      console.warn(`[push] register token failed ${res.status}: ${body.slice(0, 300)}`);
    }
  } catch (e) {
    console.warn("[push] register token failed", e);
  }
}

let attemptedThisSession = false;

/**
 * Fetches the Expo push token (device, permission and projectId permitting)
 * and stores it. On Android this requires FCM credentials (google-services.json
 * wired into the build via app.json `android.googleServicesFile`); without them
 * the token call rejects here, which is the usual reason pushes never arrive.
 */
export async function registerPushToken() {
  if (IS_WEB) {
    await syncWebPush();
    return;
  }
  if (attemptedThisSession) return;
  attemptedThisSession = true;
  try {
    if (!Device.isDevice) {
      console.warn("[push] skipped: emulators/simulators don't receive remote push");
      return;
    }
    if (Platform.OS === "android") {
      // Android 13+ won't even ask for notification permission until a channel
      // exists, and remote push needs one to deliver to. Create the "requests"
      // channel (HIGH importance) before fetching a token.
      await setupNotificationChannels();
    }
    const { status } = await Notifications.getPermissionsAsync();
    if (status !== "granted") {
      console.warn("[push] skipped: notification permission not granted");
      return;
    }
    const projectId = Constants.expoConfig?.extra?.eas?.projectId;
    if (!projectId) {
      console.warn("[push] skipped: no EAS projectId in app config");
      return;
    }
    const tokenData = await Notifications.getExpoPushTokenAsync({ projectId });
    if (tokenData?.data) {
      await registerRemote(tokenData.data, Platform.OS);
    }

    // Tokens can be rotated by FCM/APNs while the app is running. Re-register
    // automatically so stale tokens don't silently kill future pushes.
    Notifications.addPushTokenListener(({ data, type }) => {
      const platform = type === "fcm" ? "android" : type === "apns" ? "ios" : "unknown";
      registerRemote(data, platform);
    });
  } catch (e) {
    console.warn(
      "[push] failed to get Expo push token. If this is Android, check that " +
        "google-services.json is present and wired via app.json " +
        "`android.googleServicesFile`, and that you're testing in a dev/build, " +
        "not Expo Go.",
      e,
    );
  }
}
