import { Ionicons } from "@expo/vector-icons";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import type { AgendaItem } from "@/services/board-governance";
import AutoGrowInput from "./AutoGrowInput";

export function subLabel(index: number): string {
  return String.fromCharCode(97 + index);
}

/**
 * Agenda builder with numbered points and lettered sub-points (1, 1a, 1b),
 * so a decision can carry its own detail without becoming a separate item.
 */
export default function AgendaEditor({
  value,
  onChange,
}: {
  value: AgendaItem[];
  onChange: (next: AgendaItem[]) => void;
}) {
  const patch = (index: number, next: Partial<AgendaItem>) => {
    onChange(value.map((item, i) => (i === index ? { ...item, ...next } : item)));
  };

  const addPoint = () => onChange([...value, { text: "", subs: [] }]);

  const removePoint = (index: number) => {
    onChange(value.filter((_, i) => i !== index));
  };

  const addSub = (index: number) => {
    patch(index, { subs: [...value[index].subs, ""] });
  };

  const updateSub = (index: number, subIndex: number, text: string) => {
    patch(index, {
      subs: value[index].subs.map((sub, i) => (i === subIndex ? text : sub)),
    });
  };

  const removeSub = (index: number, subIndex: number) => {
    patch(index, { subs: value[index].subs.filter((_, i) => i !== subIndex) });
  };

  return (
    <View style={styles.wrap}>
      <View style={styles.head}>
        <Text style={styles.label}>Agenda</Text>
        <TouchableOpacity onPress={addPoint} activeOpacity={0.8}>
          <Text style={styles.addLink}>+ Add point</Text>
        </TouchableOpacity>
      </View>

      {value.length === 0 ? (
        <Text style={styles.empty}>
          No agenda points yet — add the first one, then attach sub-points where a
          decision needs detail.
        </Text>
      ) : null}

      {value.map((item, index) => (
        <View key={`agenda-${index}`} style={styles.item}>
          <View style={styles.itemTop}>
            <View style={styles.numberBadge}>
              <Text style={styles.numberText}>{index + 1}</Text>
            </View>
            <AutoGrowInput
              value={item.text}
              onChangeText={(text) => patch(index, { text })}
              placeholder="Budget review, safeguarding update…"
              placeholderTextColor={colors.muted}
              maxLength={240}
              style={styles.grow}
            />
            <TouchableOpacity
              onPress={() => removePoint(index)}
              style={styles.iconBtn}
              accessibilityLabel={`Delete agenda point ${index + 1}`}
            >
              <Ionicons name="trash-outline" size={15} color={colors.muted} />
            </TouchableOpacity>
          </View>

          {item.subs.length > 0 ? (
            <View style={styles.subList}>
              {item.subs.map((sub, subIndex) => (
                <View key={`agenda-${index}-sub-${subIndex}`} style={styles.subRow}>
                  <Text style={styles.subNumber}>
                    {index + 1}
                    {subLabel(subIndex)}
                  </Text>
                  <AutoGrowInput
                    value={sub}
                    onChangeText={(text) => updateSub(index, subIndex, text)}
                    placeholder="Sub-point detail"
                    placeholderTextColor={colors.muted}
                    maxLength={240}
                    minHeight={42}
                    style={[styles.grow, styles.subInput]}
                  />
                  <TouchableOpacity
                    onPress={() => removeSub(index, subIndex)}
                    style={styles.subIconBtn}
                    accessibilityLabel={`Delete sub-point ${index + 1}${subLabel(subIndex)}`}
                  >
                    <Ionicons name="close" size={14} color={colors.muted} />
                  </TouchableOpacity>
                </View>
              ))}
            </View>
          ) : null}

          <TouchableOpacity
            onPress={() => addSub(index)}
            style={styles.addSub}
            activeOpacity={0.8}
          >
            <Ionicons name="return-down-forward-outline" size={12} color={colors.goldDark} />
            <Text style={styles.addSubText}>Add sub-point</Text>
          </TouchableOpacity>
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { gap: 8, marginTop: 2 },
  head: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  },
  label: {
    fontSize: 11,
    lineHeight: 15,
    letterSpacing: 0.8,
    textTransform: "uppercase",
    color: colors.muted,
    fontFamily: fonts.sansSemiBold,
  },
  addLink: {
    fontSize: 12.5,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
  empty: {
    fontSize: 12.5,
    lineHeight: 18,
    color: colors.gray[400],
    fontFamily: fonts.sans,
  },
  item: {
    gap: 6,
    padding: 10,
    borderRadius: 12,
    backgroundColor: colors.bg,
    borderWidth: 0.5,
    borderColor: colors.border,
  },
  itemTop: { flexDirection: "row", alignItems: "flex-start", gap: 8 },
  numberBadge: {
    width: 24,
    height: 24,
    marginTop: 8,
    borderRadius: 12,
    backgroundColor: `${colors.gold}1f`,
    alignItems: "center",
    justifyContent: "center",
  },
  numberText: {
    fontSize: 11.5,
    color: colors.goldDark,
    fontFamily: fonts.sansBold,
  },
  grow: { flex: 1 },
  iconBtn: {
    width: 32,
    height: 32,
    marginTop: 4,
    borderRadius: 16,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.white,
  },
  subList: { gap: 5, paddingLeft: 32 },
  subRow: { flexDirection: "row", alignItems: "flex-start", gap: 6 },
  subNumber: {
    width: 30,
    marginTop: 10,
    fontSize: 11.5,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
  subInput: { backgroundColor: colors.white },
  subIconBtn: {
    width: 28,
    height: 28,
    marginTop: 4,
    borderRadius: 14,
    alignItems: "center",
    justifyContent: "center",
  },
  addSub: {
    flexDirection: "row",
    alignItems: "center",
    gap: 4,
    marginLeft: 32,
    paddingVertical: 2,
    alignSelf: "flex-start",
  },
  addSubText: {
    fontSize: 12,
    color: colors.goldDark,
    fontFamily: fonts.sansSemiBold,
  },
});
