function formatDate(iso?: string) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return "";
  }
}

/* ─────────────── CASE FILE CARD ─────────────── */

/** The brand cyan only reaches 2.98:1 on the white card, too light to read. */
const CASE_ACCENT = "#0b6b7d";

function caseRef(id?: string) {
  return (
    String(id || "")
      .slice(-6)
      .toUpperCase() || "000000"
  );
}

function formatCaseDate(iso?: string) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  } catch {
    return "";
  }
}

function formatCaseTime(iso?: string) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleTimeString("en-GB", {
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return "";
  }
}

/** Stepper position: Intake -> In Progress -> Resolved. */
function statusStepIndex(status?: HelpRequestStatus | string) {
  switch (status) {
    case "in_progress":
      return 1;
    case "resolved":
    case "archived":
      return 2;
    default:
      return 0;
  }
}

function isActiveStatus(status?: HelpRequestStatus | string) {
  return status === "open" || status === "in_progress";
}

/** Pulsing ring used for the status dot and the active stepper node. */
function PulseRing({
  color,
  size = 7,
  children,
  style,
}: {
  color: string;
  size?: number;
  children?: React.ReactNode;
  style?: any;
}) {
  const [v] = useState(() => new Animated.Value(0));
  useEffect(() => {
    const loop = Animated.loop(
      Animated.timing(v, { toValue: 1, duration: 2000, useNativeDriver: true }),
    );
    loop.start();
    return () => loop.stop();
  }, [v]);
  return (
    <View style={[{ width: size, height: size }, style]}>
      <Animated.View
        pointerEvents="none"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          borderRadius: size / 2,
          borderWidth: 2,
          borderColor: color,
          opacity: v.interpolate({ inputRange: [0, 1], outputRange: [0.7, 0] }),
          transform: [
            {
              scale: v.interpolate({
                inputRange: [0, 1],
                outputRange: [1, 2.1],
              }),
            },
          ],
        }}
      />
      {children}
    </View>
  );
}

function CaseAvatar({ name, size = 40 }: { name: string; size?: number }) {
  const initials =
    (name || "?")
      .trim()
      .split(/\s+/)
      .map((p) => p[0])
      .filter(Boolean)
      .slice(0, 2)
      .join("")
      .toUpperCase() || "?";
  return (
    <LinearGradient
      colors={[colors.forestSoft, colors.forestDark]}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={[
        styles.caseAvatar,
        { width: size, height: size, borderRadius: size / 2 },
      ]}
    >
      <Text style={[styles.caseAvatarText, { fontSize: size * 0.34 }]}>
        {initials}
      </Text>
    </LinearGradient>
  );
}

const CASE_STEPS = ["Intake", "In Progress", "Resolved"];

function CaseStepper({ activeIdx }: { activeIdx: number }) {
  return (
    <View style={styles.caseSteps} accessibilityLabel="Case progress">
      {CASE_STEPS.map((label, i) => {
        const done = i < activeIdx;
        const active = i === activeIdx;
        return (
          <Fragment key={label}>
            {i > 0 && (
              <View
                style={[styles.caseStepLine, done && styles.caseStepLineFill]}
              />
            )}
            <View style={styles.caseStep}>
              {active ? (
                <PulseRing color={colors.gold} size={24}>
                  <View
                    style={[styles.caseStepNode, styles.caseStepNodeActive]}
                  >
                    <Text style={styles.caseStepNodeActiveText}>{i + 1}</Text>
                  </View>
                </PulseRing>
              ) : done ? (
                <View style={[styles.caseStepNode, styles.caseStepNodeDone]}>
                  <Ionicons
                    name="checkmark"
                    size={13}
                    color={colors.forestDark}
                  />
                </View>
              ) : (
                <View style={[styles.caseStepNode, styles.caseStepNodeNext]}>
                  <Text style={styles.caseStepNodeNextText}>{i + 1}</Text>
                </View>
              )}
              <Text
                style={[
                  styles.caseStepLabel,
                  active && styles.caseStepLabelActive,
                ]}
              >
                {label}
              </Text>
            </View>
          </Fragment>
        );
      })}
    </View>
  );
}

function RequestCard({
  item,
  onPress,
}: {
  item: HelpRequest;
  onPress: () => void;
}) {
  const s = statusMeta(item.status);
  const activeIdx = statusStepIndex(item.status);
  const pulse = isActiveStatus(item.status);
  const [fade] = useState(() => new Animated.Value(0));
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      fade.setValue(1);
      return;
    }
    Animated.timing(fade, {
      toValue: 1,
      duration: 550,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
  }, [fade, reduceMotion]);

  return (
    <Animated.View
      style={{
        opacity: fade,
        transform: [
          {
            translateY: fade.interpolate({
              inputRange: [0, 1],
              outputRange: [18, 0],
            }),
          },
        ],
      }}
    >
      <TouchableOpacity
        onPress={onPress}
        activeOpacity={0.92}
        style={styles.caseCard}
        accessibilityRole="button"
        accessibilityLabel={`Case file for ${item.name || item.helpType}`}
      >
        <View style={[styles.caseEdge, { backgroundColor: s.text }]} />
        <View style={styles.caseInner}>
          {/* File header */}
          <View style={styles.caseFilehead}>
            <Text style={styles.caseRef} numberOfLines={1}>
              CASE{" "}
              <Text style={styles.caseRefAccent}>#{caseRef(item._id)}</Text>
              {item.helpType ? ` · ${item.helpType.toUpperCase()}` : ""}
            </Text>
            <View style={[styles.caseStatus, { backgroundColor: s.bg }]}>
              {pulse ? (
                <PulseRing color={s.text} size={7}>
                  <View
                    style={[styles.caseStatusDot, { backgroundColor: s.text }]}
                  />
                </PulseRing>
              ) : (
                <View
                  style={[styles.caseStatusDot, { backgroundColor: s.text }]}
                />
              )}
              <Text style={[styles.caseStatusText, { color: s.text }]}>
                {s.label}
              </Text>
            </View>
          </View>

          {/* Person */}
          <View style={styles.casePerson}>
            <CaseAvatar name={item.name || "?"} />
            <Text style={styles.caseName} numberOfLines={1}>
              {item.name || "Unknown"}
            </Text>
          </View>

          {/* Tags */}
          <View style={styles.casePills}>
            <View style={[styles.casePill, styles.casePillCategory]}>
              <Ionicons
                name="people-outline"
                size={11}
                color={colors.forestSoft}
              />
              <Text
                style={[styles.casePillText, { color: colors.forestSoft }]}
                numberOfLines={1}
              >
                {item.helpType || "Support"}
              </Text>
            </View>
            {item.urgency === "Urgent" ? (
              <View style={[styles.casePill, styles.casePillUrgent]}>
                <Ionicons
                  name="alert-circle-outline"
                  size={11}
                  color="#dc2626"
                />
                <Text style={[styles.casePillText, { color: "#dc2626" }]}>
                  Urgent
                </Text>
              </View>
            ) : item.urgency === "This week" ? (
              <View style={[styles.casePill, styles.casePillWeek]}>
                <Ionicons name="calendar-outline" size={11} color="#8a6d1a" />
                <Text style={[styles.casePillText, { color: "#8a6d1a" }]}>
                  This Week
                </Text>
              </View>
            ) : item.urgency === "Not urgent" ? (
              <View style={[styles.casePill, styles.casePillCalm]}>
                <Ionicons
                  name="checkmark-circle-outline"
                  size={11}
                  color="#166534"
                />
                <Text style={[styles.casePillText, { color: "#166534" }]}>
                  Not Urgent
                </Text>
              </View>
            ) : null}
          </View>

          {/* Message */}
          {item.description ? (
            <View style={styles.caseMessage}>
              <Text style={styles.caseMessageMark}>“</Text>
              <Text style={styles.caseMessageText}>{item.description}</Text>
            </View>
          ) : null}

          {/* Stepper */}
          <CaseStepper activeIdx={activeIdx} />

          <View style={styles.caseDivider} />

          {/* Footer */}
          <View style={styles.caseFooter}>
            <View style={styles.caseMeta}>
              <View style={styles.caseMetaItem}>
                <Ionicons
                  name="calendar-outline"
                  size={13}
                  color={CASE_ACCENT}
                />
                <Text style={styles.caseMetaText}>
                  {formatCaseDate(item.createdAt)}
                </Text>
              </View>
              <View style={styles.caseMetaItem}>
                <Ionicons
                  name="time-outline"
                  size={13}
                  color={CASE_ACCENT}
                />
                <Text style={styles.caseMetaText}>
                  {formatCaseTime(item.createdAt)}
                </Text>
              </View>
            </View>
            <View style={styles.caseAssignee}>
              <CaseAvatar name={item.assignedToName || "—"} size={24} />
              <View style={styles.caseAssigneeInfo}>
                <Text style={styles.caseAssigneeLabel}>Assigned to</Text>
                <Text style={styles.caseAssigneeName} numberOfLines={1}>
                  {item.assignedToName || "Unassigned"}
                </Text>
              </View>
            </View>
          </View>
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
}

export default function RequestsScreen() {
  const [role, setRole] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [checking, setChecking] = useState(true);
  const [requests, setRequests] = useState<HelpRequest[]>([]);
  const [loadingList, setLoadingList] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<HelpRequestStatus | "all" | "assigned">(
    "open",
  );
  const [menuOpen, setMenuOpen] = useState(false);
  const filters: {
    key: HelpRequestStatus | "all" | "assigned";
    label: string;
  }[] =
    role === "admin"
      ? [...FILTERS, { key: "assigned", label: "Mine" }]
      : FILTERS;
  const [selected, setSelected] = useState<HelpRequest | null>(null);
  const [sending, setSending] = useState(false);
  const [notifUnread, setNotifUnread] = useState(0);
  const [prayerRequests, setPrayerRequests] = useState<PrayerRequest[]>([]);
  const [loadingPrayer, setLoadingPrayer] = useState(false);
  const [prayerError, setPrayerError] = useState<string | null>(null);
  const [prayerOpen, setPrayerOpen] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [commentTarget, setCommentTarget] = useState<PrayerRequest | null>(
    null,
  );
  const listRef = useRef<FlatList>(null);
  const selectedIdRef = useRef<string | null>(null);
  const params = useLocalSearchParams<{ open?: string; segment?: string }>();
  const [segment, setSegment] = useState<"help" | "prayer">(
    params.segment === "prayer" ? "prayer" : "help",
  );
  const isFocused = useIsFocused();

  const isAdmin = role === "admin";

  useEffect(() => {
    (async () => {
      const session = await getSession();
      setRole(session?.user?.role || null);
      setCurrentUserId(session?.user?.id || null);
      setChecking(false);
    })();
  }, []);

  const fetchRequests = useCallback(async () => {
    if (!role) {
      setRequests([]);
      return;
    }
    setLoadingList(true);
    try {
      setError(null);
      const res =
        role === "admin"
          ? await helpApi.list(
              filter === "all" || filter === "assigned"
                ? undefined
                : (filter as HelpRequestStatus),
              filter === "assigned",
            )
          : await helpApi.mine();
      setRequests(res.data || []);
    } catch (e: any) {
      setError(e?.message || "Failed to load requests.");
      setRequests([]);
    } finally {
      setLoadingList(false);
    }
  }, [role, filter]);

  const fetchPrayerRequests = useCallback(async () => {
    setLoadingPrayer(true);
    try {
      setPrayerError(null);
      const res = await communityApi.getRequests();
      const all = res?.data || [];
      setPrayerRequests(
        isAdmin
          ? all
          : all.filter((r) => (r.visibility || "community") === "community"),
      );
    } catch (e: any) {
      setPrayerError(e?.message || "Failed to load prayer requests.");
      setPrayerRequests([]);
    } finally {
      setLoadingPrayer(false);
    }
  }, [isAdmin]);

  const refreshUnread = useCallback(async () => {
    if (!role) return;
    try {
      const res = await helpApi.unreadCounts();
      const n = role === "admin" ? res.data.adminUnread : res.data.userUnread;
      setRequestsUnread(n);
    } catch {}
  }, [role]);

  useFocusEffect(
    useCallback(() => {
      if (checking) return;
      fetchRequests();
      fetchPrayerRequests();
      refreshUnread();
      notifApi
        .unreadCount()
        .then((r) => setNotifUnread(r.unread))
        .catch(() => {});
      const selId = selectedIdRef.current;
      if (selId) {
        helpApi
          .get(selId)
          .then((res) => setSelected(res.data))
          .catch(() => {});
      }
    }, [checking, fetchRequests, fetchPrayerRequests, refreshUnread]),
  );

  // Live chat without polling: the server pushes when the other side replies
  // or the request changes, so refetch the open thread (or the list) on
  // receipt — but only while this tab is visible.
  useEffect(() => {
    if (IS_WEB) return;
    if (!isFocused) return;
    const sub = Notifications.addNotificationReceivedListener(
      (notification) => {
        if (checking || AppState.currentState !== "active") return;
        const data = notification.request.content.data as Record<
          string,
          unknown
        > | null;
        if (!data || data.prayer) return;
        const requestId =
          typeof data.requestId === "string" ? data.requestId : null;
        if (requestId && selectedIdRef.current === requestId) {
          // Bypass the short cache so the new message shows up immediately.
          helpApi
            .get(requestId, { cacheTtl: 0 })
            .then((res) => setSelected(res.data))
            .catch(() => {});
        } else if (!selectedIdRef.current) {
          // No thread open — refresh the list so new/updated requests appear.
          fetchRequests();
        }
        refreshUnread();
      },
    );
    return () => sub.remove();
  }, [isFocused, checking, fetchRequests, refreshUnread]);

  // Deep link from a notification: open the referenced request directly.
  useEffect(() => {
    const openId = params.open;
    if (!openId || checking) return;
    (async () => {
      try {
        const res = await helpApi.get(openId);
        selectedIdRef.current = openId;
        setSelected(res.data);
        helpApi
          .markRead(openId)
          .then(() => refreshUnread())
          .catch(() => {});
      } catch {
      } finally {
        router.setParams({ open: undefined });
      }
    })();
  }, [params.open, checking, refreshUnread]);

  // Refresh instantly when the app returns to the foreground.
  useEffect(() => {
    const sub = AppState.addEventListener("change", (state) => {
      if (state !== "active") return;
      fetchRequests();
      fetchPrayerRequests();
      refreshUnread();
      const selId = selectedIdRef.current;
      if (selId) {
        helpApi
          .get(selId)
          .then((res) => setSelected(res.data))
          .catch(() => {});
      }
    });
    return () => sub.remove();
  }, [fetchRequests, fetchPrayerRequests, refreshUnread]);

  // Bell badge follows the live in-app notification count.
  useEffect(() => subscribeNotifUnread(setNotifUnread), []);

  // Hide the floating tab bar while a request detail is open so it never covers the chat input.
  useEffect(() => {
    setRequestsDetailOpen(!!selected);
  }, [selected]);

  const closeDetail = () => {
    selectedIdRef.current = null;
    setSelected(null);
  };

  useEffect(() => {
    const onBackPress = () => {
      if (selected) {
        closeDetail();
        return true;
      }
      return false;
    };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, [selected]);

  const openDetail = (item: HelpRequest) => {
    selectedIdRef.current = item._id;
    setSelected(item);
    // List responses only carry the last chat message — fetch the full thread.
    helpApi
      .get(item._id)
      .then((res) => setSelected(res.data))
      .catch(() => {});
    helpApi
      .markRead(item._id)
      .then(() => refreshUnread())
      .catch(() => {});
  };

  const handleSend = async (text: string) => {
    if (!selected) return;
    setSending(true);
    try {
      const res = await helpApi.sendMessage(selected._id, text);
      setSelected(res.data.request);
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to send message.");
    }
    setSending(false);
  };

  const handleStatus = async (status: HelpRequestStatus) => {
    if (!selected) return;
    try {
      const res = await helpApi.updateStatus(selected._id, status);
      setSelected(res.data);
      refreshUnread();
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to update request.");
    }
  };

  const handleAssign = async (assign: boolean) => {
    if (!selected) return;
    try {
      const res = await helpApi.assign(selected._id, assign);
      setSelected(res.data);
      fetchRequests();
      refreshUnread();
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to update assignment.");
    }
  };

  const handleAssignToggle = () => {
    if (!selected) return;
    if (!selected.assignedTo) {
      handleAssign(true);
      return;
    }
    if (selected.assignedTo === currentUserId) {
      Alert.alert("Unassign request", "Remove this request from your queue?", [
        { text: "Cancel", style: "cancel" },
        {
          text: "Unassign",
          style: "destructive",
          onPress: () => handleAssign(false),
        },
      ]);
    } else {
      handleAssign(true); // take over from another admin
    }
  };

  const handleAdd = () => {
    if (!role) {
      router.push("/login");
      return;
    }
    setAddOpen(true);
  };

  const handlePray = async (item: PrayerRequest) => {
    if (!role) {
      router.push("/login");
      return;
    }
    try {
      const res = await communityApi.prayForRequest(item._id);
      if (res?.data) {
        setPrayerRequests((prev) =>
          prev.map((r) => (r._id === item._id ? res.data : r)),
        );
      }
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to update prayer.");
    }
  };

  const handleDeletePrayer = (item: PrayerRequest) => {
    Alert.alert("Delete request", "Delete this prayer request permanently?", [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          try {
            await communityApi.deleteRequest(item._id);
            setPrayerRequests((prev) =>
              prev.filter((r) => r._id !== item._id),
            );
          } catch (e: any) {
            Alert.alert("Error", e?.message || "Failed to delete request.");
          }
        },
      },
    ]);
  };

  const handleConvert = async () => {
    if (!selected) return;
    try {
      const res = await helpApi.convert(selected._id);
      const recordId = res.data.recordId;
      setSelected({ ...selected, recordId });
      Alert.alert(
        "Record Created",
        "A family record has been created from this request.",
        [
          { text: "Later" },
          {
            text: "View Record",
            onPress: () =>
              router.push({ pathname: "/record-form", params: { recordId } }),
          },
        ],
      );
    } catch (e: any) {
      Alert.alert("Error", e?.message || "Failed to create record.");
    }
  };

  const handleDelete = () => {
    if (!selected) return;
    Alert.alert("Delete Request", "Delete this help request permanently?", [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          try {
            await helpApi.remove(selected._id);
            closeDetail();
            fetchRequests();
            refreshUnread();
          } catch (e: any) {
            Alert.alert("Error", e?.message || "Failed to delete request.");
          }
        },
      },
    ]);
  };

  if (selected) {
    const c = HELP_TYPE_COLORS[selected.helpType] || HELP_TYPE_COLORS.Other;
    const status = selected.status || "open";
    const meta = statusMeta(status);
    const canEdit = status === "open";
    const messages = selected.messages || [];
    const heroTitle = isAdmin ? selected.name : selected.helpType;

    return (
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <LinearGradient
          colors={[colors.bg, colors.white]}
          start={{ x: 0, y: 0 }}
          end={{ x: 0, y: 1 }}
          style={{ flex: 1 }}
        >
          <View style={styles.header}>
            <TouchableOpacity onPress={closeDetail} style={styles.headerBtn}>
              <Ionicons name="chevron-back" size={22} color={colors.darkGreen} />
            </TouchableOpacity>
            <Text style={styles.headerTitle} numberOfLines={1}>
              Request Details
            </Text>
            <View style={styles.headerStatus}>
              {isAdmin ? (
                <TouchableOpacity
                  style={[
                    styles.assignBtn,
                    selected.assignedTo === currentUserId &&
                      styles.assignBtnActive,
                  ]}
                  onPress={handleAssignToggle}
                  activeOpacity={0.8}
                >
                  {selected.assignedTo === currentUserId && (
                    <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
                  )}
                  <Ionicons
                    name={
                      selected.assignedTo === currentUserId
                        ? "checkmark-circle"
                        : "person-add-outline"
                    }
                    size={15}
                    color={
                      selected.assignedTo === currentUserId
                        ? colors.white
                        : colors.darkGreen
                    }
                  />
                  <Text
                    style={[
                      styles.assignBtnText,
                      selected.assignedTo === currentUserId &&
                        styles.assignBtnTextActive,
                    ]}
                  >
                    {selected.assignedTo === currentUserId
                      ? "Assigned"
                      : "Assign"}
                  </Text>
                </TouchableOpacity>
              ) : (
                <View style={[styles.badge, { backgroundColor: meta.bg }]}>
                  <Text style={[styles.badgeText, { color: meta.text }]}>
                    {meta.label}
                  </Text>
                </View>
              )}
            </View>
          </View>

          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : "height"}
            style={{ flex: 1 }}
          >
            <FlatList
              ref={listRef}
              data={messages}
              keyExtractor={(m, i) => `${i}-${m.createdAt}`}
              contentContainerStyle={styles.chatList}
              keyboardShouldPersistTaps="handled"
              onContentSizeChange={() =>
                listRef.current?.scrollToEnd({ animated: true })
              }
              ListHeaderComponent={
                <>
                  <LinearGradient
                    colors={[colors.forestDark, colors.forestSoft]}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                    style={styles.detailHero}
                  >
                    <View style={styles.detailHeroIcon}>
                      <Ionicons name="heart" size={22} color={colors.gold} />
                    </View>
                    <Text style={styles.detailName}>{heroTitle}</Text>
                    <View style={styles.heroBadgeRow}>
                      <View style={[styles.badge, { backgroundColor: c.bg }]}>
                        <Text style={[styles.badgeText, { color: c.text }]}>
                          {selected.helpType}
                        </Text>
                      </View>
                      <View
                        style={[styles.badge, { backgroundColor: meta.bg }]}
                      >
                        <Text style={[styles.badgeText, { color: meta.text }]}>
                          {meta.label}
                        </Text>
                      </View>
                    </View>
                    {selected.assignedToName ? (
                      <View style={styles.assigneeChip}>
                        <Ionicons
                          name="person-circle-outline"
                          size={13}
                          color="rgba(255,255,255,0.85)"
                        />
                        <Text style={styles.assigneeChipText}>
                          Assigned to {selected.assignedToName}
                        </Text>
                      </View>
                    ) : null}
                    <Text style={styles.detailDate}>
                      {formatDate(selected.createdAt)}
                    </Text>
                  </LinearGradient>

                  {isAdmin ? (
                    <View style={styles.actionsCard}>
                      <View style={styles.actionsRow}>
                        {selected.recordId ? (
                          <ActionChip
                            icon="folder-open-outline"
                            label="View Record"
                            onPress={() =>
                              router.push({
                                pathname: "/record-form",
                                params: { recordId: selected.recordId },
                              })
                            }
                          />
                        ) : (
                          <ActionChip
                            icon="create-outline"
                            label="Create Record"
                            variant="primary"
                            onPress={handleConvert}
                          />
                        )}
                        {status === "open" && (
                          <ActionChip
                            icon="time-outline"
                            label="In Progress"
                            onPress={() => handleStatus("in_progress")}
                          />
                        )}
                        {status === "in_progress" && (
                          <ActionChip
                            icon="checkmark-done-outline"
                            label="Resolved"
                            onPress={() => handleStatus("resolved")}
                          />
                        )}
                        {(status === "resolved" || status === "archived") && (
                          <ActionChip
                            icon="refresh-outline"
                            label="Reopen"
                            onPress={() => handleStatus("open")}
                          />
                        )}
                        {status !== "archived" ? (
                          <ActionChip
                            icon="archive-outline"
                            label="Archive"
                            onPress={() => handleStatus("archived")}
                          />
                        ) : null}
                        <ActionChip
                          icon="trash-outline"
                          label="Delete"
                          variant="danger"
                          onPress={handleDelete}
                        />
                      </View>
                    </View>
                  ) : canEdit ? (
                    <View style={styles.actionsCard}>
                      <View style={styles.actionsRow}>
                        <ActionChip
                          icon="create-outline"
                          label="Edit Request"
                          variant="primary"
                          onPress={() =>
                            router.push({
                              pathname: "/ask-help",
                              params: { editId: selected._id },
                            })
                          }
                        />
                        <ActionChip
                          icon="trash-outline"
                          label="Delete"
                          variant="danger"
                          onPress={handleDelete}
                        />
                      </View>
                    </View>
                  ) : (
                    <View style={styles.closedNote}>
                      <Ionicons
                        name="information-circle-outline"
                        size={18}
                        color={colors.gray[500]}
                      />
                      <Text style={styles.closedNoteText}>
                        This request is {meta.label.toLowerCase()}. You can
                        still message the support team.
                      </Text>
                    </View>
                  )}

                  <Text style={styles.sectionTitle}>Details</Text>
                  <View style={styles.sectionCard}>
                    {isAdmin ? (
                      <InfoRow
                        icon="person-outline"
                        label="Name"
                        value={selected.name}
                      />
                    ) : null}
                    {selected.area ? (
                      <InfoRow
                        icon="location-outline"
                        label="City / Area"
                        value={selected.area}
                      />
                    ) : null}
                    {selected.phone ? (
                      <InfoRow
                        icon="call-outline"
                        label="Phone"
                        value={selected.phone}
                      />
                    ) : null}
                    {selected.email ? (
                      <InfoRow
                        icon="mail-outline"
                        label="Email"
                        value={selected.email}
                      />
                    ) : null}
                    {selected.contactMethod ? (
                      <InfoRow
                        icon="chatbubble-outline"
                        label="Preferred contact"
                        value={selected.contactMethod}
                      />
                    ) : null}
                    {selected.urgency ? (
                      <InfoRow
                        icon="time-outline"
                        label="Urgency"
                        value={selected.urgency}
                      />
                    ) : null}
                    {selected.whoFor ? (
                      <InfoRow
                        icon="people-outline"
                        label="Who needs help"
                        value={selected.whoFor}
                      />
                    ) : null}
                    {selected.ageGroup ? (
                      <InfoRow
                        icon="body-outline"
                        label="Age group"
                        value={selected.ageGroup}
                      />
                    ) : null}
                    <Text style={styles.detailText}>
                      {selected.description || "No description provided."}
                    </Text>
                  </View>

                  <Text style={styles.sectionTitle}>Conversation</Text>
                  {messages.length === 0 && (
                    <View style={styles.emptyChat}>
                      <Ionicons
                        name="chatbubbles-outline"
                        size={28}
                        color={colors.gray[400]}
                      />
                      <Text style={styles.emptyChatText}>
                        {isAdmin
                          ? "No messages yet. Start the conversation."
                          : "No messages yet. We'll respond here."}
                      </Text>
                    </View>
                  )}
                </>
              }
              renderItem={({ item }) => (
                <MessageBubble message={item} adminView={isAdmin} />
              )}
            />
            <ChatInput
              sending={sending}
              onSend={handleSend}
              placeholder={
                isAdmin ? `Reply to ${selected.name}...` : "Write a message..."
              }
            />
          </KeyboardAvoidingView>
        </LinearGradient>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.safe} edges={["top"]}>
      <LinearGradient
        colors={[colors.bg, colors.white]}
        start={{ x: 0, y: 0 }}
        end={{ x: 0, y: 1 }}
        style={{ flex: 1 }}
      >
        <View style={[styles.listHeader, menuOpen && styles.listHeaderOpen]}>
          <View style={styles.headerRow}>
            <View>
              <Text style={styles.pageEyebrow}>REQUESTS</Text>
              {segment === "prayer" ? (
                <View style={styles.prayerScopePill}>
                  <Ionicons
                    name={
                      isAdmin ? "shield-checkmark-outline" : "people-outline"
                    }
                    size={13}
                    color={colors.goldDark}
                  />
                  <Text style={styles.prayerScopePillText}>
                    {isAdmin ? "Community & prayer team" : "Community only"}
                  </Text>
                </View>
              ) : (
                <View style={styles.filterDropdown}>
                  <TouchableOpacity
                    style={styles.dropdownBtn}
                    onPress={() => setMenuOpen((o) => !o)}
                    activeOpacity={0.75}
                    accessibilityLabel="Filter requests"
                  >
                    <Text style={styles.dropdownBtnText}>
                      {filters.find((f) => f.key === filter)?.label ?? "All"}
                    </Text>
                    <Ionicons
                      name={menuOpen ? "chevron-up" : "chevron-down"}
                      size={15}
                      color={colors.goldDark}
                    />
                  </TouchableOpacity>
                  {menuOpen && (
                    <>
                      <TouchableOpacity
                        style={styles.dropdownBackdrop}
                        activeOpacity={1}
                        onPress={() => setMenuOpen(false)}
                      />
                      <View style={styles.dropdownMenu}>
                        {filters.map((f) => {
                          const active = filter === f.key;
                          return (
                            <TouchableOpacity
                              key={f.key}
                              style={styles.dropdownItem}
                              onPress={() => {
                                if (f.key !== filter) {
                                  setRequests([]);
                                  setLoadingList(true);
                                }
                                setFilter(f.key);
                                setMenuOpen(false);
                              }}
                              activeOpacity={0.7}
                            >
                              <Text
                                style={[
                                  styles.dropdownItemText,
                                  active && styles.dropdownItemTextActive,
                                ]}
                              >
                                {f.label}
                              </Text>
                              {active && (
                                <Ionicons
                                  name="checkmark"
                                  size={15}
                                  color={colors.gold}
                                />
                              )}
                            </TouchableOpacity>
                          );
                        })}
                      </View>
                    </>
                  )}
                </View>
              )}
            </View>
            <View style={styles.headerActions}>
              {role ? (
                <TouchableOpacity
                  onPress={() => router.push("/notifications-center")}
                  style={styles.bellBtn}
                  activeOpacity={0.7}
                >
                  <Ionicons
                    name="notifications-outline"
                    size={20}
                    color={colors.darkGreen}
                  />
                  {notifUnread > 0 && (
                    <View style={styles.bellDot}>
                      <Text style={styles.bellDotText}>
                        {notifUnread > 9 ? "9+" : notifUnread}
                      </Text>
                    </View>
                  )}
                </TouchableOpacity>
              ) : null}
              <TouchableOpacity
                onPress={handleAdd}
                style={styles.askBtn}
                activeOpacity={0.8}
                accessibilityLabel="Create a request"
                accessibilityHint="Choose between a help request or a prayer request"
              >
                <Ionicons name="add" size={22} color={colors.white} />
              </TouchableOpacity>
            </View>
          </View>
          {role ? (
            <View style={styles.segmentRow}>
              <View style={styles.segmentCtrl}>
                {(
                  [
                    {
                      key: "help",
                      label: "Help Requests",
                      icon: "chatbubbles-outline",
                    },
                    {
                      key: "prayer",
                      label: "Prayer Requests",
                      icon: "flame-outline",
                    },
                  ] as const
                ).map((seg) => {
                  const active = segment === seg.key;
                  return (
                    <TouchableOpacity
                      key={seg.key}
                      style={[styles.segmentBtn, active && styles.segmentBtnActive]}
                      onPress={() => {
                        setSegment(seg.key);
                        setMenuOpen(false);
                      }}
                      activeOpacity={0.85}
                      accessibilityRole="tab"
                      accessibilityState={{ selected: active }}
                    >
                      <Ionicons
                        name={seg.icon}
                        size={14}
                        color={active ? colors.forestDark : colors.muted}
                      />
                      <Text
                        style={[
                          styles.segmentBtnText,
                          active && styles.segmentBtnTextActive,
                        ]}
                      >
                        {seg.label}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
            </View>
          ) : null}
          <Text style={styles.pageSub}>
            {segment === "help"
              ? "Ask for help — it stays between you and our support team"
              : isAdmin
                ? "Prayer requests from the community and the prayer team"
                : "Requests shared by the community — stand with them in prayer"}
          </Text>
        </View>

        {checking ? (
          <SkeletonList
            count={5}
            render={
              segment === "prayer" ? PrayerCardSkeleton : RequestCardSkeleton
            }
          />
        ) : !role ? (
          <EmptyState
            icon="chatbubbles-outline"
            color={colors.gold}
            eyebrow="Requests"
            title="Log in to get started"
            subtitle="Track your help requests and pray with the community from here."
            actionLabel="Log In"
            onAction={() => router.push("/login")}
          />
        ) : segment === "prayer" ? (
          <>
            {loadingPrayer && prayerRequests.length === 0 ? (
              <SkeletonList count={6} render={PrayerCardSkeleton} />
            ) : prayerError ? (
              <EmptyState
                icon="warning-outline"
                color={colors.error}
                eyebrow="Something went wrong"
                title="Couldn't load prayer requests"
                subtitle={prayerError}
                actionLabel="Retry"
                onAction={fetchPrayerRequests}
              />
            ) : prayerRequests.length === 0 ? (
              <EmptyState
                icon="flame-outline"
                color={colors.gold}
                eyebrow="Prayer requests"
                title="No prayer requests yet"
                subtitle="Be the first to share what's on your heart with the community."
                actionLabel="Share a request"
                onAction={() => setPrayerOpen(true)}
              />
            ) : (
              <>
                <FlatList
                  data={prayerRequests}
                  keyExtractor={(item) => item._id}
                  contentContainerStyle={styles.list}
                  renderItem={({ item }) => (
                    <PrayerRequestCard
                      item={item}
                      isAdmin={isAdmin}
                      onPray={() => handlePray(item)}
                      onOpenComments={() => setCommentTarget(item)}
                      prayLoading={false}
                      onDelete={() => handleDeletePrayer(item)}
                      deleteLoading={false}
                    />
                  )}
                />
                <View style={styles.totalRow}>
                  <Text style={styles.totalText}>
                    Total: {prayerRequests.length}
                  </Text>
                </View>
              </>
            )}
          </>
        ) : error ? (
          <EmptyState
            icon="warning-outline"
            color={colors.error}
            eyebrow="Something went wrong"
            title="Couldn't load requests"
            subtitle={error}
            actionLabel="Retry"
            onAction={fetchRequests}
          />
        ) : (
          <>
            {loadingList && requests.length === 0 ? (
              <SkeletonList count={4} render={RequestCardSkeleton} />
            ) : requests.length === 0 ? (
              isAdmin ? (
                (() => {
                  const copy = EMPTY_COPY[filter] ?? EMPTY_COPY.all;
                  return (
                    <EmptyState
                      icon={copy.icon}
                      color={copy.color}
                      eyebrow={copy.eyebrow}
                      title={copy.title}
                      subtitle={copy.subtitle}
                    />
                  );
                })()
              ) : (
                <EmptyState
                  icon="heart-outline"
                  color={colors.gold}
                  eyebrow="Requests"
                  title="You haven't asked for help yet"
                  subtitle="When you send a request, you'll be able to follow it from here."
                  actionLabel="Ask for help"
                  onAction={() => router.push("/ask-help")}
                />
              )
            ) : (
              <>
                <FlatList
                  data={requests}
                  keyExtractor={(item) => item._id}
                  contentContainerStyle={styles.list}
                  renderItem={({ item }) => (
                    <RequestCard item={item} onPress={() => openDetail(item)} />
                  )}
                />
                <View style={styles.totalRow}>
                  <Text style={styles.totalText}>Total: {requests.length}</Text>
                </View>
              </>
            )}
          </>
        )}

        {prayerOpen ? (
          <PrayerRequestModal
            editing={null}
            onClose={() => setPrayerOpen(false)}
            onSubmit={() => {
              fetchPrayerRequests();
              setSegment("prayer");
            }}
          />
        ) : null}

        {addOpen ? (
          <Modal
            visible
            transparent
            animationType="slide"
            onRequestClose={() => setAddOpen(false)}
          >
            <TouchableOpacity
              style={styles.addOverlay}
              activeOpacity={1}
              onPress={() => setAddOpen(false)}
            >
              <View style={styles.addSheet}>
                <View style={styles.addHandle} />
                <Text style={styles.addTitle}>New request</Text>
                <Text style={styles.addSubtitle}>
                  What would you like to create?
                </Text>

                <TouchableOpacity
                  style={styles.addOption}
                  activeOpacity={0.7}
                  onPress={() => {
                    setAddOpen(false);
                    router.push("/ask-help");
                  }}
                  accessibilityRole="button"
                >
                  <View style={[styles.addOptionIcon, styles.addHelpIcon]}>
                    <Ionicons
                      name="chatbubbles-outline"
                      size={20}
                      color={colors.forest}
                    />
                  </View>
                  <View style={styles.addOptionBody}>
                    <Text style={styles.addOptionTitle}>Help request</Text>
                    <Text style={styles.addOptionSub}>
                      Ask for support from our team
                    </Text>
                  </View>
                  <Ionicons
                    name="chevron-forward"
                    size={18}
                    color={colors.muted}
                  />
                </TouchableOpacity>

                <TouchableOpacity
                  style={styles.addOption}
                  activeOpacity={0.7}
                  onPress={() => {
                    setAddOpen(false);
                    setPrayerOpen(true);
                  }}
                  accessibilityRole="button"
                >
                  <View style={[styles.addOptionIcon, styles.addPrayerIcon]}>
                    <Ionicons name="flame" size={20} color={colors.goldDark} />
                  </View>
                  <View style={styles.addOptionBody}>
                    <Text style={styles.addOptionTitle}>Prayer request</Text>
                    <Text style={styles.addOptionSub}>
                      Share what&apos;s on your heart with the community
                    </Text>
                  </View>
                  <Ionicons
                    name="chevron-forward"
                    size={18}
                    color={colors.muted}
                  />
                </TouchableOpacity>

                <TouchableOpacity
                  style={styles.addCancel}
                  activeOpacity={0.7}
                  onPress={() => setAddOpen(false)}
                >
                  <Text style={styles.addCancelText}>Cancel</Text>
                </TouchableOpacity>
              </View>
            </TouchableOpacity>
          </Modal>
        ) : null}

        {commentTarget ? (
          <CommentsModal
            itemId={commentTarget._id}
            title={commentTarget.category || "Prayer request"}
            getComments={communityApi.getRequestComments}
            addComment={communityApi.addRequestComment}
            deleteComment={communityApi.deleteRequestComment}
            onClose={() => setCommentTarget(null)}
            onCommentAdded={fetchPrayerRequests}
          />
        ) : null}
      </LinearGradient>
    </SafeAreaView>
  );
}

function RequestCardSkeleton() {
  return (
    <View style={styles.caseCard}>
      <View style={styles.caseEdge} />
      <View style={styles.caseInner}>
        <View style={styles.caseFilehead}>
          <SkeletonPulse style={{ width: 130, height: 12 }} />
          <SkeletonPulse style={{ width: 86, height: 24, borderRadius: 12 }} />
        </View>
        <View style={styles.casePerson}>
          <SkeletonPulse style={{ width: 52, height: 52, borderRadius: 26 }} />
          <SkeletonPulse style={{ width: "45%", height: 18 }} />
        </View>
        <View style={styles.casePills}>
          <SkeletonPulse style={{ width: 96, height: 26, borderRadius: 13 }} />
          <SkeletonPulse style={{ width: 64, height: 26, borderRadius: 13 }} />
        </View>
        <SkeletonPulse
          style={{
            width: "100%",
            height: 54,
            borderRadius: 8,
            marginBottom: 14,
          }}
        />
        <View style={styles.caseSteps}>
          <SkeletonPulse style={{ width: 28, height: 28, borderRadius: 14 }} />
          <SkeletonPulse style={{ flex: 1, height: 2, marginTop: 13 }} />
          <SkeletonPulse style={{ width: 28, height: 28, borderRadius: 14 }} />
          <SkeletonPulse style={{ flex: 1, height: 2, marginTop: 13 }} />
          <SkeletonPulse style={{ width: 28, height: 28, borderRadius: 14 }} />
        </View>
        <View style={[styles.caseDivider, { marginBottom: 12 }]} />
        <View style={styles.caseFooter}>
          <SkeletonPulse style={{ width: 120, height: 14 }} />
          <SkeletonPulse style={{ width: 130, height: 34, borderRadius: 17 }} />
        </View>
      </View>
    </View>
  );
}

function formatPrayerDate(value: string) {
  if (!value) return "";
  const d = new Date(value);
  if (isNaN(d.getTime())) return value;
  try {
    const dateStr = d.toLocaleDateString("en-ZA", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
    const timeStr = d.toLocaleTimeString("en-ZA", {
      hour: "2-digit",
      minute: "2-digit",
    });
    return `${dateStr} · ${timeStr}`;
  } catch {
    return value;
  }
}

/** Amber spark burst when someone prays for a request. */
function PrayerBurst() {
  const [parts] = useState(() =>
    Array.from({ length: 11 }, (_, i) => {
      const angle = (i / 11) * Math.PI * 2 + (Math.random() * 0.4 - 0.2);
      const dist = 26 + Math.random() * 22;
      return {
        angle,
        dist,
        char: "✦⋆•"[Math.floor(Math.random() * 3)],
        anim: new Animated.Value(0),
      };
    }),
  );

  useEffect(() => {
    const anims = parts.map((p) =>
      Animated.timing(p.anim, {
        toValue: 1,
        duration: 750 + Math.random() * 450,
        useNativeDriver: true,
      }),
    );
    Animated.parallel(anims).start();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <View pointerEvents="none" style={StyleSheet.absoluteFill}>
      {parts.map((p, i) => (
        <Animated.Text
          key={i}
          style={{
            position: "absolute",
            left: 4,
            top: 0,
            color: "#fbbf24",
            fontSize: 12,
            opacity: p.anim.interpolate({
              inputRange: [0, 0.15, 1],
              outputRange: [0, 1, 0],
            }),
            transform: [
              {
                translateX: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, Math.cos(p.angle) * p.dist],
                }),
              },
              {
                translateY: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, Math.sin(p.angle) * p.dist - 24],
                }),
              },
              {
                scale: p.anim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0.4, 1.15],
                }),
              },
            ],
          }}
        >
          {p.char}
        </Animated.Text>
      ))}
    </View>
  );
}

/** Candle-themed prayer request card (ported from Community → Prayer Requests). */
function PrayerRequestCard({
  item,
  isAdmin,
  onPray,
  onOpenComments,
  prayLoading,
  onDelete,
  deleteLoading,
}: {
  item: PrayerRequest;
  isAdmin: boolean;
  onPray: () => void;
  onOpenComments: () => void;
  prayLoading: boolean;
  onDelete: () => void;
  deleteLoading: boolean;
}) {
  const [fade] = useState(() => new Animated.Value(0));
  const [reduceMotion, setReduceMotion] = useState(false);
  const [burstKey, setBurstKey] = useState(0);
  const prevPrayed = useRef(item.prayedByMe);

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      fade.setValue(1);
      return;
    }
    Animated.timing(fade, {
      toValue: 1,
      duration: 550,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
  }, [fade, reduceMotion]);

  useEffect(() => {
    if (item.prayedByMe && !prevPrayed.current && !reduceMotion) {
      setBurstKey((k) => k + 1);
    }
    prevPrayed.current = item.prayedByMe;
  }, [item.prayedByMe, reduceMotion]);

  const prayedBy = item.prayedUsers || [];
  const shown = prayedBy.slice(0, 3);
  const message = item.description || item.text;
  const authorName = item.anonymous ? "Anonymous" : item.author || "?";

  return (
    <Animated.View
      style={{
        opacity: fade,
        transform: [
          {
            translateY: fade.interpolate({
              inputRange: [0, 1],
              outputRange: [18, 0],
            }),
          },
        ],
      }}
    >
      <View style={styles.prCard}>
        <View style={styles.prHeadRow}>
          <View style={styles.prPill}>
            <Ionicons name="pulse" size={12} color={colors.forestSoft} />
            <Text style={styles.prPillText} numberOfLines={1}>
              {item.category || "Prayer"}
            </Text>
          </View>
          <Text style={styles.prDate}>{formatPrayerDate(item.createdAt)}</Text>
        </View>

        <View style={styles.prPerson}>
          <View style={styles.prAvatar}>
            <Text style={styles.prAvatarText}>
              {authorName.charAt(0).toUpperCase()}
            </Text>
          </View>
          <View style={{ flex: 1 }}>
            <Text style={styles.prName} numberOfLines={1}>
              {authorName}
            </Text>
            <Text style={styles.prSub}>asks for prayer</Text>
          </View>
        </View>

        {message ? (
          <View style={styles.prQuote}>
            <Text style={styles.prQuoteMark}>“</Text>
            <Text style={styles.prQuoteText}>{message}</Text>
          </View>
        ) : null}

        <View style={styles.prDivider} />

        <View style={styles.prActions}>
          <TouchableOpacity
            style={styles.prAction}
            onPress={onOpenComments}
            activeOpacity={0.6}
            hitSlop={8}
            accessibilityLabel="View encouragements"
          >
            <Ionicons
              name="chatbubble-outline"
              size={21}
              color={colors.muted}
            />
            <Text style={styles.prActionCount}>{item.commentCount || 0}</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.prAction, prayLoading && styles.prActionBusy]}
            onPress={() => !prayLoading && onPray()}
            activeOpacity={0.6}
            disabled={prayLoading}
            hitSlop={8}
            accessibilityLabel={
              item.prayedByMe ? "Amen" : "Pray for this request"
            }
          >
            <View style={styles.prPrayIconWrap}>
              <MaterialCommunityIcons
                name="hands-pray"
                size={22}
                color={item.prayedByMe ? colors.gold : colors.muted}
              />
              {burstKey > 0 && <PrayerBurst key={burstKey} />}
            </View>
            <Text
              style={[
                styles.prActionCount,
                item.prayedByMe && styles.prActionCountOn,
              ]}
            >
              {item.prayCount || 0}
            </Text>
          </TouchableOpacity>

          {(item.isOwner || isAdmin) && (
            <View style={styles.prOwnerActions}>
              {deleteLoading ? (
                <ActivityIndicator size="small" color="#ef4444" />
              ) : (
                <TouchableOpacity
                  onPress={onDelete}
                  hitSlop={8}
                  style={styles.prOwnerBtn}
                >
                  <Ionicons name="trash-outline" size={18} color="#ef4444" />
                </TouchableOpacity>
              )}
            </View>
          )}
        </View>

        {prayedBy.length > 0 ? (
          <View style={styles.prPrayedRow}>
            <View style={styles.reqPrayerStack}>
              {shown.map((u, i) => (
                <View
                  key={u.id}
                  style={[
                    styles.reqPrayerAvatar,
                    { marginLeft: i === 0 ? 0 : -8 },
                  ]}
                >
                  {u.image ? (
                    <Image
                      source={{ uri: getOptimizedImageUrl(u.image, 160) }}
                      style={styles.reqPrayerAvatarImg}
                    />
                  ) : (
                    <Text style={styles.reqPrayerAvatarText}>
                      {(u.name || "?").charAt(0).toUpperCase()}
                    </Text>
                  )}
                </View>
              ))}
              {prayedBy.length > 3 ? (
                <View
                  style={[
                    styles.reqPrayerAvatar,
                    styles.reqPrayerMore,
                    { marginLeft: -8 },
                  ]}
                >
                  <Text style={styles.reqPrayerAvatarText}>
                    +{prayedBy.length - 3}
                  </Text>
                </View>
              ) : null}
            </View>
            <Text style={styles.prPrayedLabel}>
              {prayedBy.length} {prayedBy.length === 1 ? "prayer" : "prayers"}
            </Text>
          </View>
        ) : null}
      </View>
    </Animated.View>
  );
}

