import AsyncStorage from "@react-native-async-storage/async-storage";
import * as Crypto from "expo-crypto";
import { cleanScriptureText } from "@/lib/bible-queries";

const API_HOST = "api.youversion.com";

// Same 10s timeout the SDK's content client uses.
const VOTD_TIMEOUT_MS = 10_000;

const INSTALLATION_ID_KEY = "bible_installation_id";

let cachedInstallationId: string | null = null;

/** A stable, app-scoped installation id so VOTD calls carry a real id. */
async function getInstallationId(): Promise<string> {
  if (cachedInstallationId) return cachedInstallationId;
  try {
    const stored = await AsyncStorage.getItem(INSTALLATION_ID_KEY);
    if (stored) {
      cachedInstallationId = stored;
      return stored;
    }
  } catch {}
  const fresh = Crypto.randomUUID();
  cachedInstallationId = fresh;
  try {
    await AsyncStorage.setItem(INSTALLATION_ID_KEY, fresh);
  } catch {}
  return fresh;
}

export function getDayOfYear(): number {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now.getTime() - start.getTime();
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}

/** Credentials the SDK provider used to send — now resolved directly. */
type VotdCredentials = {
  appKey: string;
  apiHost: string;
  installationId: string;
};

async function getCredentials(): Promise<VotdCredentials> {
  return {
    appKey: process.env.EXPO_PUBLIC_YVP_APP_KEY || "",
    apiHost: API_HOST,
    installationId: await getInstallationId(),
  };
}

async function fetchVotdJson(
  credentials: VotdCredentials,
  path: string,
): Promise<Record<string, unknown> | null> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), VOTD_TIMEOUT_MS);
  try {
    const res = await fetch(`https://${credentials.apiHost}${path}`, {
      headers: {
        "X-YVP-App-Key": credentials.appKey,
        "X-YVP-Installation-Id": credentials.installationId,
      },
      signal: controller.signal,
    });
    if (!res.ok) return null;
    return (await res.json()) as Record<string, unknown>;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Fetches the YouVersion "Verse of the Day" passage id for a given day of the
 * year (1-based, matching the SDK's dayOfYear). Returns the USFM passage id
 * (e.g. "ISA.43.18-19") so the Home screen can deep-link into the reader.
 * Returns null on any failure so callers can paint a fallback.
 */
export async function fetchVotdPassageId(
  day: number,
): Promise<string | null> {
  const credentials = await getCredentials();
  const data = await fetchVotdJson(
    credentials,
    `/v1/verse_of_the_days/${day}`,
  );
  const passageId = (data as { passage_id?: string } | null)?.passage_id;
  return passageId ?? null;
}

type VotdVerse = {
  reference: string;
  text: string;
  passageId: string;
};

/**
 * Fetches the YouVersion "Verse of the Day" text for a given day and version.
 * Resolves the day's passage id, then fetches the plain-text passage content
 * (e.g. "Isaiah 43:18-19"). Returns null on any failure so callers can paint a
 * fallback rather than throw.
 */
export async function fetchVotdPassageText(
  versionId: number,
  day: number,
): Promise<VotdVerse | null> {
  const credentials = await getCredentials();
  const passageId = await fetchVotdPassageId(day);
  if (!passageId) return null;

  const data = await fetchVotdJson(
    credentials,
    `/v1/bibles/${versionId}/passages/${passageId}?format=text`,
  );
  const content = (data as { content?: string } | null)?.content;
  if (!content) return null;
  const reference = (data as { reference?: string } | null)?.reference ?? "";
  return { reference, text: cleanScriptureText(content), passageId };
}