import { useState } from "react";
import { StyleSheet, TextInput, type TextInputProps } from "react-native";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

/**
 * Multiline input that grows with its content so long agenda and minutes
 * entries stay fully readable without a fixed, cut-off box.
 */
export default function AutoGrowInput({
  minHeight = 38,
  maxHeight = 220,
  style,
  onContentSizeChange,
  ...props
}: TextInputProps & { minHeight?: number; maxHeight?: number }) {
  const [height, setHeight] = useState(minHeight);

  return (
    <TextInput
      multiline
      {...props}
      onContentSizeChange={(event) => {
        const next = Math.min(
          Math.max(event.nativeEvent.contentSize.height + 26, minHeight),
          maxHeight,
        );
        setHeight((current) => (Math.abs(current - next) < 1 ? current : next));
        onContentSizeChange?.(event);
      }}
      scrollEnabled={height >= maxHeight}
      style={[styles.input, { height }, style]}
    />
  );
}

const styles = StyleSheet.create({
  input: {
    borderWidth: 1,
    borderColor: colors.border,
    borderRadius: 12,
    paddingHorizontal: 12,
    paddingVertical: 11,
    fontSize: 14,
    lineHeight: 20,
    color: colors.ink,
    fontFamily: fonts.sans,
    backgroundColor: colors.white,
    textAlignVertical: "top",
  },
});
