import { cachedFetch } from "./cache";
import { isChatRealtimeConfigured, supabase } from "./chat-realtime";

const LAST_SEEN_TABLE = "user_last_seen";
const CACHE_TTL = 60_000;

type LastSeenRow = {
  user_id: string;
  last_seen_at: string;
};

type LastSeenCache = {
  at: number;
  data: Record<string, string>;
};

const cache = new Map<string, LastSeenCache>();

export async function touchLastSeen(): Promise<boolean> {
  try {
    const result = await cachedFetch<{ ok?: boolean }>("/api/presence/last-seen", {
      method: "POST",
      cacheTtl: 0,
    });
    return Boolean(result?.ok);
  } catch {
    return false;
  }
}

export async function fetchLastSeen(
  userIds: string[],
  forceRefresh = false,
): Promise<Record<string, string>> {
  const ids = [...new Set(userIds.map((id) => String(id)).filter(Boolean))];
  if (!isChatRealtimeConfigured || ids.length === 0) return {};

  const key = [...ids].sort().join("|");
  const cached = cache.get(key);
  if (!forceRefresh && cached && Date.now() - cached.at < CACHE_TTL) {
    return cached.data;
  }

  const { data, error } = await supabase()
    .from(LAST_SEEN_TABLE)
    .select("user_id,last_seen_at")
    .in("user_id", ids);

  if (error) return cached?.data ?? {};

  const result: Record<string, string> = {};
  for (const row of (data ?? []) as LastSeenRow[]) {
    if (row.user_id && row.last_seen_at) {
      result[row.user_id] = row.last_seen_at;
    }
  }
  cache.set(key, { at: Date.now(), data: result });
  return result;
}
