function formatDateTime(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("en-ZA", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function moment(value: string | null): number {
  if (!value) return 0;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? 0 : date.getTime();
}

/** Multi-day trainings stay upcoming until their latest day has ended. */
function endsAt(training: Training): number {
  const dated = (training.days ?? []).filter((day) =>
    /^\d{4}-\d{2}-\d{2}$/.test(day.date),
  );
  if (dated.length) {
    const last = dated.reduce((latest, day) =>
      day.date > latest.date ? day : latest,
    );
    const date = new Date(`${last.date}T${last.endTime || "23:59"}:00`);
    if (!Number.isNaN(date.getTime())) return date.getTime();
  }
  return moment(training.scheduledDate);
}

export default function TrainingsScreen() {
  const insets = useSafeAreaInsets();
  const [trainings, setTrainings] = useState<Training[]>([]);
  const [now, setNow] = useState(0);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      setError("");
      const res = await trainingsApi.list();
      setTrainings(res.data || []);
      setNow(Date.now());
    } catch (e: any) {
      setError(e?.message || "Failed to load trainings.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const upcoming = trainings
    .filter((item) => endsAt(item) >= now)
    .sort((a, b) => moment(a.scheduledDate) - moment(b.scheduledDate));
  const past = trainings
    .filter((item) => endsAt(item) < now)
    .sort((a, b) => endsAt(b) - endsAt(a));

  const open = (training: Training) =>
    router.push(`/admin/trainings/${training._id}` as any);

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <BoardHeader title="Trainings" />
        <ScrollView
          contentContainerStyle={[
            styles.content,
            { paddingBottom: 36 + insets.bottom },
          ]}
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => {
                setRefreshing(true);
                void load();
              }}
              tintColor={colors.goldDark}
              colors={[colors.goldDark]}
            />
          }
        >
          <Text style={styles.intro}>
            Officer and position training for the board. Plan multi-day sessions, mark your
            attendance and every admin is notified when a session is scheduled or changed.
          </Text>

          <View style={styles.sectionHead}>
            <Text style={styles.sectionTitle}>Upcoming trainings</Text>
            <TouchableOpacity
              onPress={() => router.push("/admin/trainings/new" as any)}
              accessibilityLabel="Create a training"
            >
              <Text style={s.addLink}>+ New training</Text>
            </TouchableOpacity>
          </View>

          {loading ? (
            <View style={s.center}>
              <ActivityIndicator color={colors.goldDark} size="large" />
            </View>
          ) : error ? (
            <View style={s.emptyBox}>
              <Ionicons name="warning-outline" size={24} color={colors.error} />
              <Text style={s.emptyTitle}>Couldn’t load trainings</Text>
              <Text style={s.emptyBody}>{error}</Text>
              <TouchableOpacity onPress={() => void load()} activeOpacity={0.85}>
                <Text style={[s.docLinkText, { marginTop: 6 }]}>Retry</Text>
              </TouchableOpacity>
            </View>
          ) : upcoming.length === 0 ? (
            <View style={s.emptyBox}>
              <Ionicons name="school-outline" size={22} color={colors.muted} />
              <Text style={s.emptyTitle}>No upcoming trainings</Text>
              <Text style={s.emptyBody}>
                Schedule the first session for your officers and positions.
              </Text>
            </View>
          ) : (
            upcoming.map((training) => (
              <TouchableOpacity
                key={training._id}
                style={styles.card}
                activeOpacity={0.9}
                onPress={() => open(training)}
                accessibilityLabel={`View ${training.title}`}
              >
                {training.imageUrl ? (
                  <Image
                    source={{
                      uri:
                        getOptimizedImageUrl(training.imageUrl, 900) ||
                        training.imageUrl,
                    }}
                    style={styles.cardImage}
                    contentFit="cover"
                    transition={150}
                  />
                ) : (
                  <View style={styles.imageFallback}>
                    <Ionicons name="school-outline" size={26} color={colors.goldDark} />
                  </View>
                )}
                <View style={styles.cardBody}>
                  <Text style={styles.cardDate}>
                    {formatDateTime(training.scheduledDate)}
                    {(training.days?.length ?? 0) > 1
                      ? ` · ${training.days.length} days`
                      : ""}
                  </Text>
                  <Text style={styles.cardTitle}>{training.title}</Text>
                  {training.location ? (
                    <View style={styles.metaRow}>
                      <Ionicons
                        name="location-outline"
                        size={14}
                        color={colors.goldDark}
                      />
                      <Text style={styles.metaText}>{training.location}</Text>
                    </View>
                  ) : null}
                  {training.description ? (
                    <Text style={styles.cardDesc} numberOfLines={2}>
                      {training.description}
                    </Text>
                  ) : null}
                  {training.counts?.total ? (
                    <View style={styles.metaRow}>
                      <Ionicons name="people-outline" size={14} color={colors.goldDark} />
                      <Text style={styles.metaText}>
                        {training.counts?.attending ?? 0} attending ·{" "}
                        {training.counts?.notAttending ?? 0} not attending
                      </Text>
                    </View>
                  ) : null}
                </View>
              </TouchableOpacity>
            ))
          )}

          {past.length > 0 ? (
            <>
              <View style={styles.sectionHead}>
                <Text style={styles.sectionTitle}>Past trainings</Text>
                <Text style={styles.sectionMeta}>{past.length}</Text>
              </View>
              <View style={styles.pastList}>
                {past.map((training) => (
                  <TouchableOpacity
                    key={training._id}
                    style={styles.pastRow}
                    activeOpacity={0.85}
                    onPress={() => open(training)}
                    accessibilityLabel={`View ${training.title}`}
                  >
                    <View style={{ flex: 1 }}>
                      <Text style={styles.pastTitle} numberOfLines={2}>
                        {training.title}
                      </Text>
                      <Text style={styles.pastMeta}>
                        {formatDateTime(training.scheduledDate)}
                      </Text>
                    </View>
                    <Ionicons name="chevron-forward" size={16} color={colors.muted} />
                  </TouchableOpacity>
                ))}
              </View>
            </>
          ) : null}
        </ScrollView>
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

