import { Ionicons } from "@expo/vector-icons";
import { useEffect, useRef, useState } from "react";
import {
  FlatList,
  KeyboardAvoidingView,
  Modal,
  Platform,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

export type CallChatMessage = {
  id: string;
  fromId: string;
  name: string;
  text: string;
  ts: number;
  local: boolean;
};

export default function CallChatSheet({
  visible,
  onClose,
  messages,
  localName,
  onSend,
}: {
  visible: boolean;
  onClose: () => void;
  messages: CallChatMessage[];
  localName: string;
  onSend: (text: string) => void;
}) {
  const insets = useSafeAreaInsets();
  const [draft, setDraft] = useState("");
  const listRef = useRef<FlatList<CallChatMessage>>(null);

  useEffect(() => {
    if (visible) {
      setTimeout(() => listRef.current?.scrollToEnd({ animated: false }), 80);
    }
  }, [visible, messages.length]);

  const send = () => {
    const text = draft.trim();
    if (!text) return;
    onSend(text);
    setDraft("");
  };

  const displayName = localName || "You";

  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={s.overlay}
      >
        <TouchableOpacity
          style={s.backdrop}
          activeOpacity={1}
          onPress={onClose}
        />
        <View style={[s.sheet, { paddingBottom: insets.bottom + 12 }]}>
          <View style={s.grabber} />
          <View style={s.header}>
            <Text style={s.title}>In-call chat</Text>
            <TouchableOpacity style={s.closeBtn} onPress={onClose} hitSlop={8}>
              <Ionicons name="close" size={20} color={colors.white} />
            </TouchableOpacity>
          </View>
          <Text style={s.ephemeral}>
            Messages disappear when the session ends
          </Text>

          <FlatList
            ref={listRef}
            data={messages}
            keyExtractor={(m) => m.id}
            style={s.list}
            contentContainerStyle={s.listContent}
            showsVerticalScrollIndicator={false}
            onContentSizeChange={() =>
              listRef.current?.scrollToEnd({ animated: true })
            }
            renderItem={({ item }) => (
              <View
                style={[
                  s.msgRow,
                  item.local ? s.msgRowLocal : s.msgRowOther,
                ]}
              >
                {!item.local && (
                  <Text style={s.msgName} numberOfLines={1}>
                    {item.name || "Guest"}
                  </Text>
                )}
                <View
                  style={[
                    s.bubble,
                    item.local ? s.bubbleLocal : s.bubbleOther,
                  ]}
                >
                  <Text
                    style={[s.msgText, item.local && s.msgTextLocal]}
                  >
                    {item.text}
                  </Text>
                </View>
              </View>
            )}
          />

          <View style={s.inputRow}>
            <TextInput
              style={s.input}
              placeholder="Message…"
              placeholderTextColor="#8b9bb0"
              value={draft}
              onChangeText={setDraft}
              onSubmitEditing={send}
              returnKeyType="send"
              multiline
              maxLength={500}
            />
            <TouchableOpacity
              style={[s.sendBtn, !draft.trim() && s.sendBtnDisabled]}
              onPress={send}
              disabled={!draft.trim()}
              activeOpacity={0.8}
            >
              <Ionicons name="send" size={18} color={colors.forestDark} />
            </TouchableOpacity>
          </View>
          <Text style={s.from}>Chatting as {displayName}</Text>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

const s = StyleSheet.create({
  overlay: { flex: 1, justifyContent: "flex-end" },
  backdrop: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "rgba(4,9,20,0.55)",
  },
  sheet: {
    backgroundColor: colors.forest,
    borderTopLeftRadius: 22,
    borderTopRightRadius: 22,
    paddingHorizontal: 18,
    paddingTop: 10,
    maxHeight: "75%",
  },
  grabber: {
    alignSelf: "center",
    width: 36,
    height: 4,
    borderRadius: 2,
    backgroundColor: "rgba(255,255,255,0.25)",
    marginBottom: 10,
  },
  header: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  },
  title: {
    color: colors.white,
    fontFamily: fonts.sansBold, fontWeight: "700",
    fontSize: 20,
  },
  closeBtn: {
    width: 30,
    height: 30,
    borderRadius: 15,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "rgba(255,255,255,0.12)",
  },
  ephemeral: {
    color: "rgba(255,255,255,0.45)",
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 11,
    marginTop: 2,
    marginBottom: 10,
  },
  list: { flexGrow: 0 },
  listContent: { paddingBottom: 12 },
  msgRow: {
    marginBottom: 10,
    maxWidth: "82%",
  },
  msgRowLocal: { alignSelf: "flex-end", alignItems: "flex-end" },
  msgRowOther: { alignSelf: "flex-start", alignItems: "flex-start" },
  msgName: {
    color: "rgba(255,255,255,0.55)",
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 10.5,
    marginBottom: 3,
    marginLeft: 12,
  },
  bubble: {
    paddingHorizontal: 12,
    paddingVertical: 8,
    borderRadius: 16,
  },
  bubbleLocal: {
    backgroundColor: colors.gold,
    borderBottomRightRadius: 4,
  },
  bubbleOther: {
    backgroundColor: "rgba(255,255,255,0.12)",
    borderBottomLeftRadius: 4,
  },
  msgText: {
    color: colors.white,
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 13.5,
    lineHeight: 18,
  },
  msgTextLocal: { color: colors.forestDark },
  inputRow: {
    flexDirection: "row",
    alignItems: "flex-end",
    gap: 8,
    marginTop: 4,
  },
  input: {
    flex: 1,
    backgroundColor: colors.forestDark,
    borderRadius: 14,
    color: colors.white,
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 13.5,
    paddingHorizontal: 14,
    paddingTop: 10,
    paddingBottom: 10,
    maxHeight: 96,
  },
  sendBtn: {
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: colors.gold,
    alignItems: "center",
    justifyContent: "center",
  },
  sendBtnDisabled: { opacity: 0.5 },
  from: {
    color: "rgba(255,255,255,0.4)",
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 10.5,
    marginTop: 6,
    textAlign: "center",
  },
});
