import { Ionicons } from "@expo/vector-icons";
import { Tabs, useRouter, usePathname } from "expo-router";
import { colors } from "@/constants/colors";
import { IS_WEB } from "@/services/config";
import {
  BackHandler,
  Dimensions,
  Pressable,
  StyleSheet,
  Text,
  View,
} from "react-native";
import { useEffect, useRef, useState } from "react";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import {
  setTabBarHidden,
  subscribeRequestsUnread,
  subscribeRequestsDetailOpen,
  subscribeDrawerOpen,
  subscribeTabBarHidden,
} from "@/services/unread";

const SCREEN_WIDTH = Dimensions.get("window").width;
const TAB_WIDTH = SCREEN_WIDTH * 0.9;

const TAB_ROUTES = new Set(["index", "community", "bible", "library", "store"]);

const tabs = [
  { name: "index", label: "Home", icon: "home-outline" },
  { name: "community", label: "Clubs", icon: "people-outline" },
  { name: "bible", label: "Bible", icon: "book-outline" },
  { name: "library", label: "Library", icon: "library-outline" },
  { name: "store", label: "Store", icon: "storefront-outline" },
];

const visibleTabs = IS_WEB ? tabs.filter((tab) => tab.name !== "bible") : tabs;

function CustomTabBar() {
  const router = useRouter();
  const pathname = usePathname();
  const insets = useSafeAreaInsets();
  const [requestsUnread, setRequestsUnread] = useState(0);
  const [detailOpen, setDetailOpen] = useState(false);
  const [drawerOpen, setDrawerOpenState] = useState(false);
  const [landingHidden, setLandingHidden] = useState(false);

  useEffect(() => subscribeRequestsUnread(setRequestsUnread), []);
  useEffect(() => subscribeRequestsDetailOpen(setDetailOpen), []);
  useEffect(() => subscribeDrawerOpen(setDrawerOpenState), []);
  // The home landing loader hides the floating tab bar while it's up.
  useEffect(() => subscribeTabBarHidden(setLandingHidden), []);

  const getCurrentTab = () => {
    if (pathname === "/") return "index";
    const segments = pathname.split("/").filter(Boolean);
    return segments[segments.length - 1] || "index";
  };

  const current = getCurrentTab();

  // The Bible reader is an immersive screen reached via "Read the Word";
  // a request detail hides the bar so it never covers the chat input; the
  // home landing loader hides it for a full-bleed welcome.
  if (current === "bible" || current === "requests" || detailOpen || drawerOpen || landingHidden) return null;

  return (
    <View style={[styles.tabBar, { bottom: insets.bottom + 12 }]}>
      {visibleTabs.map((tab) => {
        const focused =
          current === tab.name || (current === "" && tab.name === "index");
        return (
          <Pressable
            key={tab.name}
            onPress={() => {
              if (tab.name === "index") {
                router.replace("/(tabs)");
              } else {
                router.replace(`/(tabs)/${tab.name}` as any);
              }
            }}
            style={[styles.tabItem, focused && styles.tabItemActive]}
          >
            <View>
              <Ionicons
                name={tab.icon as any}
                size={20}
                color={focused ? colors.white : colors.muted}
              />
              {tab.name === "requests" && requestsUnread > 0 && (
                <View style={styles.badgeDot}>
                  <Text style={styles.badgeText}>
                    {requestsUnread > 9 ? "9+" : requestsUnread}
                  </Text>
                </View>
              )}
            </View>
            {!focused && (
              <Text
                style={styles.tabLabel}
                numberOfLines={1}
                adjustsFontSizeToFit
                minimumFontScale={0.7}
                maxFontSizeMultiplier={1.5}
              >
                {tab.label}
              </Text>
            )}
          </Pressable>
        );
      })}
    </View>
  );
}

export default function TabLayout() {
  const router = useRouter();
  const pathname = usePathname();
  const tabHistory = useRef<string[]>(["index"]);

  // Track tab visits so hardware back can return to the previous tab.
  useEffect(() => {
    const segments = pathname.split("/").filter(Boolean);
    const last = segments[segments.length - 1] || "index";
    if (!TAB_ROUTES.has(last)) return;
    const history = tabHistory.current;
    if (history[history.length - 1] !== last) {
      history.push(last);
      if (history.length > 6) history.shift();
    }
  }, [pathname]);

  // A cold start that lands outside Home must not inherit the welcome's
  // hidden bar (only Home knows when it's safe to show).
  useEffect(() => {
    const segments = pathname.split("/").filter(Boolean);
    const last = segments[segments.length - 1] || "index";
    if (last !== "index") setTabBarHidden(false);
  }, [pathname]);

  useEffect(() => {
    const onBackPress = () => {
      const segments = pathname.split("/").filter(Boolean);
      const last = segments[segments.length - 1] || "index";

      // A detail/modal screen is focused above the tabs: let the stack pop it
      // back to the previous screen instead of jumping to Home.
      if (!TAB_ROUTES.has(last)) return false;

      // Inside the tabs: go back to the previously visited tab.
      const history = tabHistory.current;
      if (history.length > 1) {
        history.pop();
        const prev = history[history.length - 1] || "index";
        router.replace(
          prev === "index" ? "/(tabs)" : (`/(tabs)/${prev}` as any),
        );
        return true;
      }

      // Already on the first tab: allow the default behaviour (exit app).
      return false;
    };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, [pathname, router]);

  return (
    <Tabs
      tabBar={() => <CustomTabBar />}
      screenOptions={{ headerShown: false }}
    >
      <Tabs.Screen name="index" />
      <Tabs.Screen name="community" />
      {!IS_WEB && <Tabs.Screen name="bible" />}
      <Tabs.Screen name="library" />
      <Tabs.Screen name="store" />
    </Tabs>
  );
}

const styles = StyleSheet.create({
  tabBar: {
    position: "absolute",
    alignSelf: "center",
    flex: 0,
    width: TAB_WIDTH,
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-around",
    elevation: 8,
    backgroundColor: "#d4eef5",
    borderRadius: 999,
    minHeight: 54,
    paddingHorizontal: 6,
    shadowColor: "#000",
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.15,
    shadowRadius: 16,
    overflow: "hidden",
  },
  tabItem: {
    flex: 1,
    minWidth: 0,
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: 6,
    paddingVertical: 8,
    borderRadius: 20,
  },
  tabItemActive: {
    backgroundColor: colors.gold,
    borderRadius: 20,
  },
  tabLabel: {
    fontSize: 11,
    fontWeight: "600",
    color: colors.muted,
    marginTop: 2,
  },
  badgeDot: {
    position: "absolute",
    top: -7,
    right: -9,
    minWidth: 17,
    height: 17,
    borderRadius: 9,
    paddingHorizontal: 4,
    backgroundColor: "#dc2626",
    alignItems: "center",
    justifyContent: "center",
  },
  badgeText: {
    fontSize: 10,
    fontWeight: "700",
    color: colors.white,
    fontFamily: "Poppins_700Bold",
  },
});
