import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  BackHandler,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import { router, useLocalSearchParams } from "expo-router";
import { colors } from "@/constants/colors";
import { getSession } from "@/services/auth";
import { helpApi } from "@/services/help-requests";
import { DEFAULT_PHONE_PREFIX, hasValidPhone } from "@/utils/phone";

const HELP_TYPES = [
  "Food & groceries",
  "Clothing",
  "Housing & shelter",
  "Medical & healthcare",
  "Education support",
  "Emotional & spiritual support",
  "Social support",
  "Other",
];

const URGENCY_OPTIONS = ["Urgent", "This week", "Not urgent"];
const WHO_FOR_OPTIONS = ["Myself", "A family member", "Someone I know"];
const CONTACT_METHOD_OPTIONS = ["WhatsApp", "Phone call", "Email"];
const AGE_GROUP_OPTIONS = ["Under 18", "18 - 30", "31 - 50", "50+"];

function AutoExpandingInput({ style, onChangeText, minHeight = 44, ...props }: any & { minHeight?: number }) {
  const [height, setHeight] = useState(minHeight);
  return (
    <TextInput
      style={[style, { height, minHeight }]}
      onChangeText={onChangeText}
      onContentSizeChange={(e) => {
        const newHeight = Math.max(minHeight, e.nativeEvent.contentSize.height + 8);
        setHeight(newHeight);
      }}
      {...props}
    />
  );
}

function ChipGroup({
  options,
  value,
  onSelect,
}: {
  options: string[];
  value: string;
  onSelect: (v: string) => void;
}) {
  return (
    <View style={styles.chipRow}>
      {options.map((o) => (
        <TouchableOpacity
          key={o}
          style={[styles.checkChip, value === o && styles.checkChipActive]}
          onPress={() => onSelect(o)}
          activeOpacity={0.7}
        >
          <Text
            style={[
              styles.checkChipText,
              value === o && styles.checkChipTextActive,
            ]}
          >
            {o}
          </Text>
        </TouchableOpacity>
      ))}
    </View>
  );
}

function SectionLabel({ children }: { children: string }) {
  return (
    <View style={styles.sectionLabelRow}>
      <Text style={styles.sectionLabel}>{children}</Text>
      <View style={styles.sectionLabelLine} />
    </View>
  );
}

export default function AskHelpScreen() {
  const { editId } = useLocalSearchParams<{ editId?: string }>();
  const isEdit = !!editId;
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [loadingEdit, setLoadingEdit] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState(DEFAULT_PHONE_PREFIX);
  const [area, setArea] = useState("");
  const [ageGroup, setAgeGroup] = useState("");
  const [contactMethod, setContactMethod] = useState("");
  const [urgency, setUrgency] = useState("");
  const [whoFor, setWhoFor] = useState("");
  const [helpType, setHelpType] = useState("");
  const [description, setDescription] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    const onBackPress = () => { router.back(); return true; };
    const sub = BackHandler.addEventListener("hardwareBackPress", onBackPress);
    return () => sub.remove();
  }, []);

  useEffect(() => {
    (async () => {
      const session = await getSession();
      if (!session?.user) {
        Alert.alert("Login Required", "Please log in to ask for help.", [
          {
            text: "OK",
            onPress: () =>
              router.replace({
                pathname: "/login",
                params: { next: "/ask-help" },
              }),
          },
        ]);
        return;
      }
      setCheckingAuth(false);

      if (editId) {
        setLoadingEdit(true);
        try {
          const res = await helpApi.get(editId);
          const req = res.data;
          if (req.status && req.status !== "open") {
            Alert.alert("Not Editable", "This request can no longer be edited.", [
              { text: "OK", onPress: () => router.back() },
            ]);
            return;
          }
          setName(req.name || "");
          setEmail(req.email || "");
          setPhone(req.phone || "");
          setArea(req.area || "");
          setAgeGroup(req.ageGroup || "");
          setContactMethod(req.contactMethod || "");
          setUrgency(req.urgency || "");
          setWhoFor(req.whoFor || "");
          setHelpType(req.helpType || "");
          setDescription(req.description || "");
        } catch {
          Alert.alert("Error", "Failed to load your request.", [
            { text: "OK", onPress: () => router.back() },
          ]);
        }
        setLoadingEdit(false);
      }
    })();
  }, [editId]);

  const handleSubmit = async () => {
    if (!name.trim()) {
      Alert.alert("Required", "Please enter your name.");
      return;
    }
    if (!helpType) {
      Alert.alert("Required", "Please select the kind of help you need.");
      return;
    }
    if (!description.trim()) {
      Alert.alert("Required", "Please tell us a little about what you need.");
      return;
    }
    if (!hasValidPhone(phone) && !email.trim()) {
      Alert.alert("Required", "Please provide a phone number or email so we can reach you.");
      return;
    }

    setSubmitting(true);
    try {
      const payload = {
        name: name.trim(),
        email: email.trim(),
        phone: phone.trim(),
        area: area.trim(),
        ageGroup,
        contactMethod,
        urgency,
        whoFor,
        helpType,
        description: description.trim(),
      };
      if (isEdit && editId) {
        await helpApi.update(editId, { field: payload });
      } else {
        await helpApi.create(payload);
      }
      setSuccess(true);
    } catch {
      Alert.alert(
        "Error",
        isEdit ? "Failed to update your request. Please try again." : "Failed to send your request. Please try again.",
      );
    }
    setSubmitting(false);
  };

  const firstName = name.trim().split(" ")[0] || "friend";

  if (checkingAuth || loadingEdit) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.safe} edges={["top"]}>
          <View style={styles.center}>
            <ActivityIndicator size="large" color={colors.gold} />
          </View>
        </SafeAreaView>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.safe} edges={["top"]}>
        <LinearGradient
          colors={["#f59e0b", "#fbbf24"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 0 }}
          style={styles.flameBar}
        />

        {success ? (
          <ScrollView
            contentContainerStyle={styles.successWrap}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
          >
            <View style={styles.successIcon}>
              <Ionicons name="heart" size={30} color="#f59e0b" />
            </View>
            <Text style={styles.successTitle}>
              {isEdit ? "Request updated" : "Your request is received"}
            </Text>
            <Text style={styles.successText}>
              Thank you, <Text style={styles.successName}>{firstName}</Text>.{" "}
              {isEdit
                ? "Your request has been updated."
                : "Your request has been shared with our support team and will be handled confidentially."}
            </Text>
            <TouchableOpacity style={styles.doneBtn} onPress={() => router.back()} activeOpacity={0.85}>
              <Text style={styles.doneBtnText}>Done</Text>
            </TouchableOpacity>
          </ScrollView>
        ) : (
          <>
            <View style={styles.header}>
              <View style={styles.headIcon}>
                <Ionicons name="heart" size={22} color="#f59e0b" />
              </View>
              <View style={styles.headerTextWrap}>
                <Text style={styles.title}>
                  {isEdit ? "Edit Request" : "Ask for Help"}
                </Text>
                <Text style={styles.sub}>
                  Tell us what you need — our support team will reach out to you
                  confidentially.
                </Text>
              </View>
              <TouchableOpacity
                style={styles.closeBtn}
                onPress={() => router.back()}
                disabled={submitting}
                accessibilityLabel="Close"
              >
                <Ionicons name="close" size={20} color={colors.muted} />
              </TouchableOpacity>
            </View>

            <KeyboardAvoidingView
              behavior={Platform.OS === "ios" ? "padding" : "height"}
              style={styles.flex}
            >
              <ScrollView
                contentContainerStyle={styles.form}
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode="none"
                showsVerticalScrollIndicator={false}
              >
                <SectionLabel>Personal Details</SectionLabel>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Full name <Text style={styles.req}>*</Text>
                  </Text>
                  <TextInput
                    style={styles.input}
                    placeholder="Your name"
                    placeholderTextColor="#a3aebc"
                    value={name}
                    onChangeText={setName}
                    maxLength={200}
                  />
                </View>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>City / Area</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="Where are you located?"
                    placeholderTextColor="#a3aebc"
                    value={area}
                    onChangeText={setArea}
                    maxLength={200}
                  />
                </View>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Age group</Text>
                  <ChipGroup
                    options={AGE_GROUP_OPTIONS}
                    value={ageGroup}
                    onSelect={setAgeGroup}
                  />
                </View>

                <SectionLabel>Contact Details</SectionLabel>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Phone</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="Phone number"
                    placeholderTextColor="#a3aebc"
                    value={phone}
                    onChangeText={setPhone}
                    keyboardType="phone-pad"
                  />
                </View>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Email</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="Email address"
                    placeholderTextColor="#a3aebc"
                    value={email}
                    onChangeText={setEmail}
                    keyboardType="email-address"
                    autoCapitalize="none"
                  />
                </View>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Preferred contact method</Text>
                  <ChipGroup
                    options={CONTACT_METHOD_OPTIONS}
                    value={contactMethod}
                    onSelect={setContactMethod}
                  />
                </View>

                <SectionLabel>Nature of Help</SectionLabel>
                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    What kind of help do you need? <Text style={styles.req}>*</Text>
                  </Text>
                  <ChipGroup
                    options={HELP_TYPES}
                    value={helpType}
                    onSelect={setHelpType}
                  />
                </View>

                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>
                    Describe the nature of help <Text style={styles.req}>*</Text>
                  </Text>
                  <AutoExpandingInput
                    style={[styles.input, styles.textArea]}
                    placeholder="Describe the help you are looking for..."
                    placeholderTextColor="#a3aebc"
                    value={description}
                    onChangeText={setDescription}
                    multiline
                    textAlignVertical="top"
                    minHeight={110}
                    maxLength={5000}
                  />
                </View>

                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>How urgent is this?</Text>
                  <ChipGroup
                    options={URGENCY_OPTIONS}
                    value={urgency}
                    onSelect={setUrgency}
                  />
                </View>

                <View style={styles.field}>
                  <Text style={styles.fieldLabel}>Who needs help?</Text>
                  <ChipGroup
                    options={WHO_FOR_OPTIONS}
                    value={whoFor}
                    onSelect={setWhoFor}
                  />
                </View>

                <TouchableOpacity
                  style={styles.submit}
                  onPress={handleSubmit}
                  disabled={submitting}
                  activeOpacity={0.85}
                >
                  {submitting ? (
                    <ActivityIndicator size="small" color={colors.forestDark} />
                  ) : (
                    <>
                      <Ionicons name="heart" size={16} color={colors.forestDark} />
                      <Text style={styles.submitText}>
                        {isEdit ? "Save Changes" : "Send Request"}
                      </Text>
                    </>
                  )}
                </TouchableOpacity>

                <Text style={styles.privacyNote}>
                  Your request is only visible to the support team and will be
                  handled confidentially.
                </Text>
              </ScrollView>
            </KeyboardAvoidingView>
          </>
        )}
      </SafeAreaView>
    </SafeAreaProvider>
  );
}

