import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import {
  ActivityIndicator,
  Alert,
  FlatList,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { Ionicons } from "@expo/vector-icons";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";
import { getSession } from "@/services/auth";
import { ASSET_CATEGORIES, assetsApi, type Asset } from "@/services/assets";

type IconName = React.ComponentProps<typeof Ionicons>["name"];

const ACCENT_GRADIENT = colors.gradients.accent as [string, string];

const CATEGORY_META: Record<string, { icon: IconName; tint: string }> = {
  Computer: { icon: "laptop-outline", tint: "#0284C7" },
  "Mobile phone": { icon: "phone-portrait-outline", tint: "#13c5dd" },
  Tablet: { icon: "tablet-portrait-outline", tint: "#0ea5e9" },
  Printer: { icon: "print-outline", tint: "#1E293B" },
  "Audio & visual": { icon: "videocam-outline", tint: "#f59e0b" },
  Furniture: { icon: "bed-outline", tint: "#10b981" },
  Vehicle: { icon: "car-outline", tint: "#f97316" },
  Tools: { icon: "construct-outline", tint: "#0fa3c4" },
  Other: { icon: "cube-outline", tint: "#64748B" },
};

const metaOf = (category: string) =>
  CATEGORY_META[category] ?? CATEGORY_META.Other;

type Draft = {
  name: string;
  category: string;
  description: string;
  year: string;
  model: string;
  serialNumber: string;
};

const EMPTY_DRAFT: Draft = {
  name: "",
  category: "Computer",
  description: "",
  year: "",
  model: "",
  serialNumber: "",
};

const draftOf = (asset: Asset): Draft => ({
  name: asset.name,
  category: asset.category || "Other",
  description: asset.description ?? "",
  year: asset.year ? String(asset.year) : "",
  model: asset.model ?? "",
  serialNumber: asset.serialNumber ?? "",
});

/**
 * Admin-only register of the equipment Relate World owns. Serial numbers are
 * optional — furniture and tools usually have none.
 */
export default function AssetsScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("All");

  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState<Draft>(EMPTY_DRAFT);
  const [formError, setFormError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    setError(null);
    try {
      const res = await assetsApi.list();
      setAssets(res.data ?? []);
    } catch (e: any) {
      setError(e?.message || "Couldn't load assets. Check your connection.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let active = true;
    getSession()
      .then((session) => {
        if (!active) return;
        if (session?.user?.role !== "admin") {
          router.back();
          return;
        }
        load();
      })
      .catch(() => {
        if (active) router.back();
      });
    return () => {
      active = false;
    };
  }, [router, load]);

  const categories = useMemo(() => {
    const present = new Set(assets.map((a) => a.category || "Other"));
    return ["All", ...ASSET_CATEGORIES.filter((c) => present.has(c))];
  }, [assets]);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return assets.filter((a) => {
      if (filter !== "All" && (a.category || "Other") !== filter) return false;
      if (!q) return true;
      return [a.name, a.model, a.serialNumber, a.description, a.category]
        .filter(Boolean)
        .some((field) => String(field).toLowerCase().includes(q));
    });
  }, [assets, query, filter]);

  const openCreate = () => {
    setEditingId(null);
    setDraft(EMPTY_DRAFT);
    setFormError(null);
    setShowForm(true);
  };

  const openEdit = (asset: Asset) => {
    setEditingId(asset._id);
    setDraft(draftOf(asset));
    setFormError(null);
    setShowForm(true);
  };

  const set = (key: keyof Draft, value: string) =>
    setDraft((prev) => ({ ...prev, [key]: value }));

  const save = async () => {
    const name = draft.name.trim();
    if (!name) {
      setFormError("Give the asset a name.");
      return;
    }
    const yearText = draft.year.trim();
    const year = yearText ? Number(yearText) : null;
    if (yearText && (!Number.isFinite(year) || (year as number) < 1900 || (year as number) > 2100)) {
      setFormError("Enter a year between 1900 and 2100, or leave it blank.");
      return;
    }

    setSaving(true);
    setFormError(null);
    const payload = {
      name,
      category: draft.category,
      description: draft.description.trim(),
      year: year === null ? null : Math.trunc(year as number),
      model: draft.model.trim(),
      serialNumber: draft.serialNumber.trim(),
    };
    try {
      if (editingId) {
        await assetsApi.update(editingId, payload);
      } else {
        await assetsApi.create(payload);
      }
      setShowForm(false);
      await load();
    } catch (e: any) {
      setFormError(e?.message || "Couldn't save this asset.");
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = (asset: Asset) => {
    Alert.alert("Delete asset", `Remove "${asset.name}" from the register?`, [
      { text: "Cancel", style: "cancel" },
      {
        text: "Delete",
        style: "destructive",
        onPress: async () => {
          try {
            await assetsApi.remove(asset._id);
            await load();
          } catch (e: any) {
            Alert.alert("Error", e?.message || "Couldn't delete the asset.");
          }
        },
      },
    ]);
  };

  const renderRow = ({ item }: { item: Asset }) => {
    const meta = metaOf(item.category);
    const details = [item.model, item.year ? String(item.year) : ""]
      .filter(Boolean)
      .join(" · ");
    return (
      <View style={s.card}>
        <View style={[s.cardIcon, { backgroundColor: `${meta.tint}1a` }]}>
          <Ionicons name={meta.icon} size={20} color={meta.tint} />
        </View>
        <View style={s.cardBody}>
          <Text style={s.cardTitle} numberOfLines={2}>
            {item.name}
          </Text>
          <View style={s.cardMetaRow}>
            <View style={[s.categoryChip, { backgroundColor: `${meta.tint}14` }]}>
              <Text style={[s.categoryChipText, { color: meta.tint }]}>
                {item.category || "Other"}
              </Text>
            </View>
            {details ? (
              <Text style={s.cardMeta} numberOfLines={1}>
                {details}
              </Text>
            ) : null}
          </View>
          {item.description ? (
            <Text style={s.cardDesc} numberOfLines={2}>
              {item.description}
            </Text>
          ) : null}
          <View style={s.serialRow}>
            <Ionicons
              name={item.serialNumber ? "barcode-outline" : "remove-circle-outline"}
              size={13}
              color={colors.muted}
            />
            <Text style={s.serialText} numberOfLines={1}>
              {item.serialNumber ? item.serialNumber : "No serial number"}
            </Text>
          </View>
        </View>
        <View style={s.cardActions}>
          <TouchableOpacity
            style={s.iconBtn}
            onPress={() => openEdit(item)}
            accessibilityLabel={`Edit ${item.name}`}
          >
            <Ionicons name="create-outline" size={18} color={colors.info} />
          </TouchableOpacity>
          <TouchableOpacity
            style={s.iconBtn}
            onPress={() => confirmDelete(item)}
            accessibilityLabel={`Delete ${item.name}`}
          >
            <Ionicons name="trash-outline" size={18} color={colors.error} />
          </TouchableOpacity>
        </View>
      </View>
    );
  };

  return (
    <View style={[s.safe, { paddingTop: insets.top }]}>
      <View style={s.header}>
        <TouchableOpacity
          style={s.backBtn}
          onPress={() => router.back()}
          accessibilityLabel="Back"
        >
          <Ionicons name="chevron-back" size={22} color={colors.forest} />
        </TouchableOpacity>
        <View style={{ flex: 1 }}>
          <Text style={s.headerTitle}>Assets</Text>
          <Text style={s.headerSub}>Equipment Relate World owns</Text>
        </View>
        <TouchableOpacity onPress={openCreate} activeOpacity={0.85}>
          <LinearGradient
            colors={ACCENT_GRADIENT}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.newBtn}
          >
            <Ionicons name="add" size={18} color={colors.forest} />
            <Text style={s.newBtnText}>New</Text>
          </LinearGradient>
        </TouchableOpacity>
      </View>

      <View style={s.toolbar}>
        <View style={s.searchWrap}>
          <Ionicons name="search" size={16} color={colors.muted} />
          <TextInput
            style={s.searchInput}
            placeholder="Search name, model or serial"
            placeholderTextColor={colors.muted}
            value={query}
            onChangeText={setQuery}
            returnKeyType="search"
          />
          {query ? (
            <TouchableOpacity onPress={() => setQuery("")} hitSlop={8}>
              <Ionicons name="close-circle" size={16} color={colors.muted} />
            </TouchableOpacity>
          ) : null}
        </View>
        {categories.length > 1 ? (
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={s.chipRow}
          >
            {categories.map((category) => {
              const active = filter === category;
              return (
                <TouchableOpacity
                  key={category}
                  style={[s.chip, active && s.chipActive]}
                  onPress={() => setFilter(category)}
                  activeOpacity={0.85}
                >
                  <Text style={[s.chipText, active && s.chipTextActive]}>
                    {category}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        ) : null}
        {!loading && !error ? (
          <Text style={s.countText}>
            {visible.length} of {assets.length} item{assets.length === 1 ? "" : "s"}
          </Text>
        ) : null}
      </View>

      {loading ? (
        <View style={s.list}>
          {[0, 1, 2, 3].map((i) => (
            <View key={i} style={[s.card, { marginBottom: 10 }]}>
              <View style={[s.cardIcon, { backgroundColor: colors.skeleton }]} />
              <View style={s.cardBody}>
                <View style={[s.skelLine, { width: "58%" }]} />
                <View style={[s.skelLine, { width: "40%", height: 10 }]} />
                <View style={[s.skelLine, { width: "70%", height: 10 }]} />
              </View>
            </View>
          ))}
        </View>
      ) : error ? (
        <View style={s.center}>
          <Ionicons name="cloud-offline-outline" size={36} color={colors.muted} />
          <Text style={s.centerText}>{error}</Text>
          <TouchableOpacity style={s.primaryBtn} onPress={load} activeOpacity={0.85}>
            <Text style={s.primaryBtnText}>Try again</Text>
          </TouchableOpacity>
        </View>
      ) : assets.length === 0 ? (
        <View style={s.center}>
          <Ionicons name="cube-outline" size={40} color={colors.muted} />
          <Text style={s.centerTitle}>No assets recorded</Text>
          <Text style={s.centerText}>
            Keep track of the computers, phones and other equipment Relate World owns.
          </Text>
          <TouchableOpacity style={s.primaryBtn} onPress={openCreate} activeOpacity={0.85}>
            <Ionicons name="add" size={18} color={colors.forest} />
            <Text style={s.primaryBtnText}>Add asset</Text>
          </TouchableOpacity>
        </View>
      ) : visible.length === 0 ? (
        <View style={s.center}>
          <Ionicons name="search-outline" size={36} color={colors.muted} />
          <Text style={s.centerTitle}>Nothing matches</Text>
          <Text style={s.centerText}>Try another search or category.</Text>
          <TouchableOpacity
            style={s.ghostBtn}
            onPress={() => {
              setQuery("");
              setFilter("All");
            }}
            activeOpacity={0.85}
          >
            <Text style={s.ghostBtnText}>Clear filters</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <FlatList
          style={{ flex: 1 }}
          data={visible}
          keyExtractor={(item) => item._id}
          renderItem={renderRow}
          contentContainerStyle={[s.list, { paddingBottom: insets.bottom + 24 }]}
          ItemSeparatorComponent={() => <View style={{ height: 10 }} />}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        />
      )}

      <Modal
        visible={showForm}
        animationType="slide"
        transparent
        statusBarTranslucent
        onRequestClose={() => setShowForm(false)}
      >
        <View style={s.modalBackdrop}>
          <KeyboardAvoidingView
            behavior={Platform.OS === "ios" ? "padding" : undefined}
            style={s.modalCard}
          >
            <View style={s.modalHead}>
              <View style={{ flex: 1 }}>
                <Text style={s.modalTitle}>
                  {editingId ? "Edit asset" : "New asset"}
                </Text>
                <Text style={s.modalSub}>
                  {editingId ? "Update the details below" : "Add it to the register"}
                </Text>
              </View>
              <TouchableOpacity
                style={s.iconBtn}
                onPress={() => setShowForm(false)}
                accessibilityLabel="Close"
              >
                <Ionicons name="close" size={18} color={colors.muted} />
              </TouchableOpacity>
            </View>

            <ScrollView
              contentContainerStyle={s.modalBody}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}
            >
              <Text style={s.label}>
                Name <Text style={s.req}>*</Text>
              </Text>
              <TextInput
                style={s.input}
                placeholder="e.g. Office laptop"
                placeholderTextColor={colors.muted}
                value={draft.name}
                onChangeText={(t) => set("name", t)}
              />

              <Text style={s.label}>Category</Text>
              <View style={s.categoryGrid}>
                {ASSET_CATEGORIES.map((category) => {
                  const meta = metaOf(category);
                  const active = draft.category === category;
                  return (
                    <TouchableOpacity
                      key={category}
                      style={[
                        s.categoryOption,
                        active && { borderColor: meta.tint, backgroundColor: `${meta.tint}12` },
                      ]}
                      onPress={() => set("category", category)}
                      activeOpacity={0.85}
                    >
                      <Ionicons
                        name={meta.icon}
                        size={16}
                        color={active ? meta.tint : colors.muted}
                      />
                      <Text
                        style={[s.categoryOptionText, active && { color: meta.tint }]}
                        numberOfLines={1}
                      >
                        {category}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              <Text style={s.label}>Description</Text>
              <TextInput
                style={[s.input, s.multiline]}
                placeholder="What it is, its condition, who uses it…"
                placeholderTextColor={colors.muted}
                value={draft.description}
                onChangeText={(t) => set("description", t)}
                multiline
                textAlignVertical="top"
              />

              <View style={s.fieldRow}>
                <View style={s.fieldHalf}>
                  <Text style={s.label}>Year</Text>
                  <TextInput
                    style={s.input}
                    placeholder="e.g. 2024"
                    placeholderTextColor={colors.muted}
                    value={draft.year}
                    onChangeText={(t) => set("year", t.replace(/[^\d]/g, "").slice(0, 4))}
                    keyboardType="number-pad"
                    maxLength={4}
                  />
                </View>
                <View style={s.fieldHalf}>
                  <Text style={s.label}>Model</Text>
                  <TextInput
                    style={s.input}
                    placeholder="e.g. ThinkPad E14"
                    placeholderTextColor={colors.muted}
                    value={draft.model}
                    onChangeText={(t) => set("model", t)}
                  />
                </View>
              </View>

              <Text style={s.label}>Serial number</Text>
              <TextInput
                style={s.input}
                placeholder="Optional — leave blank if it has none"
                placeholderTextColor={colors.muted}
                value={draft.serialNumber}
                onChangeText={(t) => set("serialNumber", t)}
                autoCapitalize="characters"
              />

              {formError ? (
                <View style={s.errorBanner}>
                  <Ionicons name="alert-circle" size={16} color={colors.error} />
                  <Text style={s.errorText}>{formError}</Text>
                </View>
              ) : null}
            </ScrollView>

            <View style={[s.modalFooter, { paddingBottom: insets.bottom + 12 }]}>
              <TouchableOpacity
                style={[s.ghostBtn, { marginTop: 0 }]}
                onPress={() => setShowForm(false)}
                activeOpacity={0.85}
              >
                <Text style={s.ghostBtnText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={s.saveWrap}
                onPress={save}
                disabled={saving}
                activeOpacity={0.85}
              >
                <LinearGradient
                  colors={ACCENT_GRADIENT}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={[s.saveBtn, saving && { opacity: 0.6 }]}
                >
                  {saving ? (
                    <ActivityIndicator size="small" color={colors.forest} />
                  ) : (
                    <Text style={s.saveBtnText}>
                      {editingId ? "Save changes" : "Add asset"}
                    </Text>
                  )}
                </LinearGradient>
              </TouchableOpacity>
            </View>
          </KeyboardAvoidingView>
        </View>
      </Modal>
    </View>
  );
}

