import { Suspense } from "react";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { SQLiteProvider, type SQLiteDatabase } from "expo-sqlite";
import { StatusBar } from "expo-status-bar";
import { colors } from "@/constants/colors";

/**
 * The bundled bible.db asset ships only the scripture text (verses + FTS). The
 * reader's own tables — settings, highlights, bookmarks, reading_progress and
 * the offline sync_queue — are NOT in the asset, and the bible screen only has
 * this database's handle (not the app's relate.db). Create them on open with the
 * same schema as the app database; without them every settings read strands the
 * reader on the loading screen and every highlight / bookmark / note write
 * throws "no such table", so those features silently do nothing.
 */
async function initBibleDb(db: SQLiteDatabase): Promise<void> {
  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL DEFAULT ''
    );

    CREATE TABLE IF NOT EXISTS highlights (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id TEXT NOT NULL,
      version_id INTEGER NOT NULL,
      book TEXT NOT NULL,
      chapter INTEGER NOT NULL,
      verse INTEGER NOT NULL,
      color TEXT NOT NULL DEFAULT '#FFD700',
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_highlights_user ON highlights(user_id, book, chapter);
    CREATE INDEX IF NOT EXISTS idx_highlights_verse ON highlights(user_id, version_id, book, chapter, verse);

    CREATE TABLE IF NOT EXISTS bookmarks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id TEXT NOT NULL,
      book TEXT NOT NULL,
      chapter INTEGER NOT NULL,
      verse INTEGER NOT NULL DEFAULT 0,
      note TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_bookmarks_user ON bookmarks(user_id, book, chapter);

    CREATE TABLE IF NOT EXISTS reading_progress (
      user_id TEXT NOT NULL,
      book TEXT NOT NULL,
      chapter INTEGER NOT NULL,
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (user_id)
    );

    CREATE TABLE IF NOT EXISTS sync_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      table_name TEXT NOT NULL,
      record_id TEXT NOT NULL,
      action TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      synced INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_sync_queue_pending ON sync_queue(synced, created_at);
  `);
}

function LoadingScreen({ label }: { label: string }) {
  return (
    <SafeAreaView style={styles.root} edges={["top", "bottom"]}>
      <StatusBar style="light" />
      <View style={styles.center}>
        <ActivityIndicator size="large" color={colors.gold} />
        <Text style={styles.text}>{label}</Text>
      </View>
    </SafeAreaView>
  );
}

export default function BibleDatabaseProvider({
  children,
  label = "Opening Bible…",
  fallback = <LoadingScreen label={label} />,
}: {
  children: React.ReactNode;
  label?: string;
  /** What to show while the database opens; pass `null` to show nothing. */
  fallback?: React.ReactNode;
}) {
  return (
    <Suspense fallback={fallback}>
      <SQLiteProvider
        databaseName="bible.db"
        useSuspense={true}
        assetSource={{ assetId: require("../../../assets/bible.db") }}
        onInit={initBibleDb}
      >
        {children}
      </SQLiteProvider>
    </Suspense>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: colors.forestDark,
  },
  center: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    gap: 14,
  },
  text: {
    fontFamily: undefined, fontWeight: "500",
    fontSize: 14,
    color: "rgba(255,255,255,0.6)",
  },
});