import { Ionicons } from "@expo/vector-icons";
import { useRouter, useSegments } from "expo-router";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { type DailyCall } from "@daily-co/react-native-daily-js";
import { communityApi } from "@/services/community";
import { colors } from "@/constants/colors";
import { fonts } from "@/constants/fonts";

export type CallInfo = {
  roomUrl: string;
  token?: string;
  userName: string;
  type: "audio" | "video";
  groupName: string;
  isOwner: boolean;
  accessCode?: string;
  groupId?: string;
  startedAt?: number;
  durationMs?: number;
};

/** Formats a remaining duration as m:ss (or h:mm:ss if 60+ minutes). */
function formatClock(ms: number) {
  const total = Math.max(0, Math.ceil(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  if (h > 0) {
    return `${h}:${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
  }
  return `${m}:${String(sec).padStart(2, "0")}`;
}

type CallContextValue = {
  call: DailyCall | null;
  info: CallInfo | null;
  participantCount: number;
  minimized: boolean;
  remainingMs: number | null;
  registerCall: (call: DailyCall, info: CallInfo) => void;
  clearCall: () => void;
  minimize: () => void;
  restore: () => void;
};

const CallContext = createContext<CallContextValue | null>(null);

export function useCallContext() {
  const ctx = useContext(CallContext);
  if (!ctx) throw new Error("useCallContext must be used within CallProvider");
  return ctx;
}

export function CallProvider({ children }: { children: ReactNode }) {
  const callRef = useRef<DailyCall | null>(null);
  const leftHandlerRef = useRef<(() => void) | null>(null);
  const [call, setCall] = useState<DailyCall | null>(null);
  const [info, setInfo] = useState<CallInfo | null>(null);
  const [participantCount, setParticipantCount] = useState(1);
  const [minimized, setMinimized] = useState(false);
  const [remainingMs, setRemainingMs] = useState<number | null>(null);
  const timeUpRef = useRef(false);

  useEffect(() => {
    if (!minimized) return;
    const update = () => {
      const c = callRef.current;
      if (!c) return;
      try {
        setParticipantCount(Object.keys(c.participants() || {}).length);
      } catch {}
    };
    update();
    const id = setInterval(update, 3000);
    return () => clearInterval(id);
  }, [minimized]);

  const registerCall = useCallback((c: DailyCall, i: CallInfo) => {
    callRef.current = c;
    timeUpRef.current = false;
    setCall(c);
    setInfo(i);
    const onLeft = () => {
      if (callRef.current === c) {
        callRef.current = null;
        setCall(null);
        setInfo(null);
        setMinimized(false);
      }
    };
    leftHandlerRef.current = onLeft;
    c.on("left-meeting", onLeft);
    try {
      setParticipantCount(Object.keys(c.participants() || {}).length);
    } catch {}
  }, []);

  const clearCall = useCallback(() => {
    const c = callRef.current;
    const handler = leftHandlerRef.current;
    leftHandlerRef.current = null;
    if (c && handler) {
      c.off("left-meeting", handler);
    }
    callRef.current = null;
    setCall(null);
    setInfo(null);
    setParticipantCount(1);
    setMinimized(false);
    setRemainingMs(null);
  }, []);

  // Count down the session's remaining time while minimized and end the call
  // when the 45-minute cap is hit (moderator also clears the group session).
  useEffect(() => {
    if (!call || !minimized || !info?.startedAt) return;
    const expires = info.startedAt + (info.durationMs || 45 * 60 * 1000);
    const tick = () => {
      const rem = Math.max(0, expires - Date.now());
      setRemainingMs(rem);
      if (rem <= 0) {
        clearInterval(id);
        if (timeUpRef.current) return;
        timeUpRef.current = true;
        if (info.isOwner && info.groupId) {
          try {
            communityApi.endGroupSession(info.groupId).catch(() => {});
          } catch {}
        }
        if (call) {
          try {
            call
              .leave()
              .then(() => call.destroy())
              .catch(() => call.destroy())
              .catch(() => {});
          } catch {}
        }
        clearCall();
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [call, minimized, info, clearCall]);

  const minimize = useCallback(() => setMinimized(true), []);
  const restore = useCallback(() => setMinimized(false), []);

  return (
    <CallContext.Provider
      value={{
        call,
        info,
        participantCount,
        minimized,
        remainingMs,
        registerCall,
        clearCall,
        minimize,
        restore,
      }}
    >
      {children}
    </CallContext.Provider>
  );
}

export function CallFloatingBubble() {
  const {
    call,
    info,
    participantCount,
    minimized,
    remainingMs,
    restore,
    clearCall,
  } = useCallContext();
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const segments = useSegments();
  const inCallScreen = segments.join("/") === "call";

  if (!minimized || inCallScreen || !call || !info) return null;

  const end = () => {
    const c = call;
    clearCall();
    if (c) {
      try {
        c.leave()
          .then(() => c.destroy())
          .catch(() => c.destroy())
          .catch(() => {});
      } catch {}
    }
  };

  const open = () => {
    restore();
    router.push({
      pathname: "/call" as any,
      params: {
        roomUrl: info.roomUrl,
        token: info.token || "",
        userName: info.userName,
        type: info.type,
        groupName: info.groupName,
        isOwner: info.isOwner ? "1" : "0",
        accessCode: info.accessCode || "",
        groupId: info.groupId || "",
        startedAt: info.startedAt ? String(info.startedAt) : String(Date.now()),
        durationMs: info.durationMs
          ? String(info.durationMs)
          : String(45 * 60 * 1000),
      },
    });
  };

  return (
    <View style={[s.bubbleWrap, { top: insets.top + 8 }]} pointerEvents="box-none">
      <View style={s.bubble}>
        <TouchableOpacity
          style={s.bubbleMain}
          onPress={open}
          activeOpacity={0.8}
          accessibilityLabel="Return to live session"
        >
          <View style={s.bubbleIcon}>
            <Ionicons name="call" size={16} color={colors.white} />
          </View>
          <View style={s.bubbleBody}>
            <Text style={s.bubbleTitle} numberOfLines={1}>
              {info.groupName}
            </Text>
            <Text style={s.bubbleSub}>
              {participantCount}{" "}
              {participantCount === 1 ? "participant" : "participants"}
              {remainingMs !== null && remainingMs > 0
                ? ` · ${formatClock(remainingMs)} left`
                : ""}
            </Text>
          </View>
        </TouchableOpacity>
        <TouchableOpacity
          style={s.bubbleEnd}
          onPress={end}
          hitSlop={10}
          accessibilityLabel="End call"
        >
          <Ionicons name="call" size={16} color={colors.white} />
        </TouchableOpacity>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  bubbleWrap: {
    position: "absolute",
    left: 0,
    right: 0,
    zIndex: 1000,
    alignItems: "center",
    paddingHorizontal: 12,
  },
  bubble: {
    flexDirection: "row",
    alignItems: "center",
    maxWidth: "100%",
    backgroundColor: colors.forestDark,
    borderRadius: 999,
    borderWidth: 1,
    borderColor: "rgba(19,197,221,0.5)",
    paddingLeft: 6,
    paddingRight: 4,
    paddingVertical: 6,
    shadowColor: "#000",
    shadowOpacity: 0.35,
    shadowRadius: 12,
    shadowOffset: { width: 0, height: 5 },
    elevation: 12,
  },
  bubbleMain: {
    flexDirection: "row",
    alignItems: "center",
    flexShrink: 1,
  },
  bubbleIcon: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: colors.gold,
    alignItems: "center",
    justifyContent: "center",
    marginRight: 8,
  },
  bubbleBody: { flexShrink: 1, maxWidth: 180 },
  bubbleTitle: {
    color: colors.white,
    fontFamily: fonts.sansBold, fontWeight: "700",
    fontSize: 14,
  },
  bubbleSub: {
    color: "rgba(255,255,255,0.65)",
    fontFamily: fonts.sans, fontWeight: "400",
    fontSize: 11,
    marginTop: 1,
  },
  bubbleEnd: {
    width: 30,
    height: 30,
    borderRadius: 15,
    backgroundColor: "#dc2626",
    alignItems: "center",
    justifyContent: "center",
    marginLeft: 8,
  },
});
