import { memo, useEffect, useRef, useState, type ReactNode } from "react";
import { Ionicons } from "@expo/vector-icons";
import {
  Pressable,
  ScrollView,
  StyleSheet,
  View,
  useWindowDimensions,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
} from "react-native";
import { colors } from "@/constants/colors";

const GAP = 12;

/**
 * Horizontal auto-advancing carousel that snaps one card per screen.
 * Each child is rendered at device width (minus layout padding) and the
 * interval advances the rail by one card. Pauses while the user drags.
 */
function AutoCarousel({
  children,
  intervalMs,
  dots = true,
  sidePadding = 16,
  controls = false,
}: {
  children: ReactNode[];
  intervalMs: number;
  dots?: boolean;
  /** Horizontal page padding of the container — each slide is width minus twice this. */
  sidePadding?: number;
  controls?: boolean;
}) {
  const { width } = useWindowDimensions();
  const cardWidth = width - sidePadding * 2;
  const count = children.length;

  const scrollRef = useRef<ScrollView>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const draggingRef = useRef(false);
  const [index, setIndex] = useState(0);
  const indexRef = useRef(0);
  const [paused, setPaused] = useState(false);
  const pausedRef = useRef(false);

  const step = cardWidth + GAP;

  useEffect(() => {
    indexRef.current = index;
  }, [index]);

  const clearTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  const startTimer = () => {
    clearTimer();
    if (count < 2 || pausedRef.current) return;
    timerRef.current = setInterval(() => {
      if (draggingRef.current) return;
      const next = (indexRef.current + 1) % count;
      scrollRef.current?.scrollTo({ x: next * step, animated: true });
    }, intervalMs);
  };

  const prevCount = useRef(count);
  useEffect(() => {
    if (prevCount.current !== count) {
      prevCount.current = count;
      const next = Math.min(indexRef.current, count - 1);
      setIndex(Math.max(0, next));
      scrollRef.current?.scrollTo({ x: next * step, animated: false });
    } else {
      prevCount.current = count;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [count]);

  useEffect(() => {
    startTimer();
    return clearTimer;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cardWidth, intervalMs, count]);

  const scrollToIndex = (next: number) => {
    const wrapped = (next + count) % count;
    setIndex(wrapped);
    indexRef.current = wrapped;
    scrollRef.current?.scrollTo({ x: wrapped * step, animated: true });
    startTimer();
  };

  const togglePaused = () => {
    const nextPaused = !pausedRef.current;
    pausedRef.current = nextPaused;
    setPaused(nextPaused);
    if (nextPaused) clearTimer();
    else startTimer();
  };

  const onMomentumScrollEnd = (
    e: NativeSyntheticEvent<NativeScrollEvent>,
  ) => {
    const next = Math.round(e.nativeEvent.contentOffset.x / step);
    setIndex(Math.max(0, Math.min(count - 1, next)));
    startTimer();
  };

  return (
    <View>
      <ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        snapToInterval={step}
        decelerationRate="fast"
        onMomentumScrollEnd={onMomentumScrollEnd}
        onScrollBeginDrag={() => {
          draggingRef.current = true;
          clearTimer();
        }}
        onScrollEndDrag={() => {
          draggingRef.current = false;
        }}
        contentContainerStyle={styles.rail}
      >
        {children.map((child, i) => (
          <View key={i} style={{ width: cardWidth }}>
            {child}
          </View>
        ))}
      </ScrollView>

      {dots && count > 1 && (
        <View style={styles.dots}>
          {children.map((_, i) => (
            <View
              key={i}
              style={[styles.dot, i === index && styles.dotActive]}
            />
          ))}
        </View>
      )}

      {controls && count > 1 && (
        <View style={styles.controls}>
          <Pressable
            onPress={() => scrollToIndex(indexRef.current - 1)}
            style={({ pressed }) => [
              styles.controlButton,
              pressed && styles.controlButtonPressed,
            ]}
            accessibilityRole="button"
            accessibilityLabel="Previous slide"
          >
            <Ionicons name="chevron-back" size={20} color={colors.muted} />
          </Pressable>
          <Pressable
            onPress={togglePaused}
            style={({ pressed }) => [
              styles.controlButton,
              pressed && styles.controlButtonPressed,
            ]}
            accessibilityRole="button"
            accessibilityLabel={paused ? "Play slideshow" : "Pause slideshow"}
          >
            <Ionicons
              name={paused ? "play" : "pause"}
              size={20}
              color={colors.muted}
            />
          </Pressable>
          <Pressable
            onPress={() => scrollToIndex(indexRef.current + 1)}
            style={({ pressed }) => [
              styles.controlButton,
              pressed && styles.controlButtonPressed,
            ]}
            accessibilityRole="button"
            accessibilityLabel="Next slide"
          >
            <Ionicons name="chevron-forward" size={20} color={colors.muted} />
          </Pressable>
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  rail: {
    gap: GAP,
    paddingRight: 32,
  },
  dots: {
    flexDirection: "row",
    justifyContent: "center",
    gap: 6,
    marginTop: 12,
  },
  dot: {
    width: 7,
    height: 7,
    borderRadius: 4,
    backgroundColor: "#c9d6e3",
  },
  dotActive: {
    backgroundColor: colors.goldDark,
    width: 18,
  },
  controls: {
    flexDirection: "row",
    justifyContent: "center",
    gap: 12,
    marginTop: 12,
  },
  controlButton: {
    width: 44,
    height: 44,
    alignItems: "center",
    justifyContent: "center",
    borderRadius: 22,
    borderWidth: 1,
    borderColor: "rgba(7, 16, 29, 0.08)",
    backgroundColor: "rgba(255, 255, 255, 0.72)",
  },
  controlButtonPressed: {
    opacity: 0.75,
    backgroundColor: colors.bg,
  },
});

export default memo(AutoCarousel);