import { cachedFetch } from "@/services/cache";

export type ReadingDays = string[];

function getDateKey(date?: Date): string {
  const d = date || new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(
    d.getDate(),
  ).padStart(2, "0")}`;
}

export async function fetchReadingDays(): Promise<ReadingDays> {
  const res = await cachedFetch<{ data?: unknown }>("/api/reading-streak", {
    cacheTtl: 60_000,
  }).catch(() => null);
  const days = res?.data;
  return Array.isArray(days)
    ? days.filter((day): day is string => typeof day === "string")
    : [];
}

export async function recordReadingDay(): Promise<ReadingDays> {
  const days = await fetchReadingDays();
  const today = getDateKey();
  if (days.includes(today)) return days;

  const updated = [...days, today];

  await cachedFetch(
    "/api/reading-streak",
    {
      method: "POST",
      body: JSON.stringify({ days: updated }),
    },
    ["/api/reading-streak"],
  ).catch(() => {});

  return updated;
}

export function calcReadingStreak(days: ReadingDays): number {
  const set = new Set(days);
  let streak = 0;
  const cursor = new Date();
  if (!set.has(getDateKey(cursor))) {
    cursor.setDate(cursor.getDate() - 1);
  }
  while (set.has(getDateKey(cursor))) {
    streak++;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}

export function isTodayRead(days: ReadingDays): boolean {
  return days.includes(getDateKey());
}