import { type SQLiteDatabase } from "expo-sqlite";
import { getLocalDb } from "./prayer-preferences";
import { API_BASE, IS_WEB } from "./config";
import { getRequestHeaders } from "./auth";
import { PrayerSounds, DEFAULT_SOUNDS } from "../constants/sounds";
import { PrayerName } from "./notifications";

function hasKeyValueSchema(db: SQLiteDatabase): boolean {
  try {
    db.getAllSync(
      `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'sounds'`,
    );
    return true;
  } catch {
    return false;
  }
}

function readSounds(db: SQLiteDatabase): string | null {
  if (hasKeyValueSchema(db)) {
    const row = db.getFirstSync<{ value: string }>(
      `SELECT value FROM prayer_preferences WHERE user_id = 'local' AND key = 'sounds'`,
    );
    return row?.value ?? null;
  }
  const row = db.getFirstSync<{ sounds: string }>(
    `SELECT sounds FROM prayer_preferences WHERE id = 1`,
  );
  return row?.sounds ?? null;
}

function writeSounds(db: SQLiteDatabase, value: string): void {
  if (hasKeyValueSchema(db)) {
    db.runSync(
      `INSERT OR REPLACE INTO prayer_preferences (user_id, key, value) VALUES ('local', 'sounds', ?)`,
      [value],
    );
    return;
  }
  db.runSync(`INSERT OR IGNORE INTO prayer_preferences (id) VALUES (1)`);
  db.runSync(`UPDATE prayer_preferences SET sounds = ? WHERE id = 1`, [value]);
}

export function getPrayerSoundsDb(db: SQLiteDatabase): PrayerSounds {
  const raw = readSounds(db);
  if (!raw) return { ...DEFAULT_SOUNDS };
  try {
    return { ...DEFAULT_SOUNDS, ...JSON.parse(raw) };
  } catch {
    return { ...DEFAULT_SOUNDS };
  }
}

export function setPrayerSoundDb(
  db: SQLiteDatabase,
  prayer: PrayerName,
  soundId: string,
): PrayerSounds {
  const current = getPrayerSoundsDb(db);
  const next = { ...current, [prayer]: soundId };
  writeSounds(db, JSON.stringify(next));
  syncToApi(next);
  return next;
}

export function setPrayerSoundsDb(db: SQLiteDatabase, sounds: PrayerSounds): void {
  writeSounds(db, JSON.stringify(sounds));
  syncToApi(sounds);
}

async function syncToApi(sounds: PrayerSounds) {
  try {
    const headers = await getRequestHeaders({ "Content-Type": "application/json" });
    if (!IS_WEB && !("Cookie" in headers) && !("cookie" in headers)) return;
    await fetch(`${API_BASE}/api/prayer-preferences`, {
      method: "PUT",
      headers,
      credentials: "include",
      body: JSON.stringify({ sounds }),
    });
  } catch {}
}

// Async API wrappers used by screens that don't hold a database context.
export async function getPrayerSounds(): Promise<PrayerSounds> {
  return getPrayerSoundsDb(getLocalDb());
}
export async function setPrayerSound(
  prayer: PrayerName,
  soundId: string,
): Promise<PrayerSounds> {
  return setPrayerSoundDb(getLocalDb(), prayer, soundId);
}
export async function setPrayerSounds(sounds: PrayerSounds): Promise<void> {
  setPrayerSoundsDb(getLocalDb(), sounds);
}
