type TaskDraft = {
  key: string;
  taskId?: string;
  description: string;
  assigneeId: string;
  dueDate: string;
};

type MinutesDraft = {
  meetingId: string;
  attendance: Record<string, "ATTENDING" | "APOLOGY">;
  attendanceReasons: Record<string, string>;
  sections: MinutesSection[];
  documentUrl: string;
  documentName: string;
  tasks: TaskDraft[];
};

function newTask(assigneeId: string): TaskDraft {
  return {
    key: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    description: "",
    assigneeId,
    dueDate: "",
  };
}

function fileNameFromUrl(url: string): string {
  if (!url) return "";
  const path = url.split("?")[0];
  const raw = path.substring(path.lastIndexOf("/") + 1);
  let name = raw;
  try {
    name = decodeURIComponent(raw);
  } catch {
    // A malformed %-escape in a pasted link must not break the whole screen.
  }
  return name || "Signed minutes on file";
}

function freshDraft(): MinutesDraft {
  return {
    meetingId: "",
    attendance: {},
    attendanceReasons: {},
    sections: [{ title: "", points: [""] }],
    documentUrl: "",
    documentName: "",
    tasks: [],
  };
}

function draftFromMinutes(minutes: BoardMinutes): MinutesDraft {
  return {
    meetingId: minutes.meetingId,
    attendance: {},
    attendanceReasons: {},
    sections: minutes.sections.length
      ? minutes.sections
      : [{ title: "", points: [""] }],
    documentUrl: minutes.minutesDocumentUrl,
    documentName: fileNameFromUrl(minutes.minutesDocumentUrl),
    tasks: minutes.actionItems.map((task) => ({
      key: task.taskId,
      taskId: task.taskId,
      description: task.taskDescription,
      assigneeId: task.assigneeId,
      dueDate: task.dueDate ? task.dueDate.slice(0, 10) : "",
    })),
  };
}

/**
 * A draft restored from storage may have been written before newer fields
 * (apology reasons, section points) existed. Fill every gap so the form always
 * renders against the current shape.
 */
function normalizeDraft(draft: Partial<MinutesDraft> | null | undefined): MinutesDraft {
  const sections = Array.isArray(draft?.sections)
    ? draft.sections.map((section) => ({
        title: section?.title ?? "",
        points: Array.isArray(section?.points)
          ? section.points.map((point) => (typeof point === "string" ? point : ""))
          : [],
      }))
    : [];
  const tasks = Array.isArray(draft?.tasks)
    ? draft.tasks.map((task, index) => ({
        key: task?.key || `stored-task-${index}`,
        taskId: task?.taskId,
        description: task?.description ?? "",
        assigneeId: task?.assigneeId ?? "",
        dueDate: task?.dueDate ?? "",
      }))
    : [];
  return {
    meetingId: draft?.meetingId ?? "",
    attendance: draft?.attendance ?? {},
    attendanceReasons: draft?.attendanceReasons ?? {},
    sections: sections.length ? sections : [{ title: "", points: [""] }],
    documentUrl: draft?.documentUrl ?? "",
    documentName: draft?.documentName ?? "",
    tasks,
  };
}

function shortDate(value: string | null): string {
  if (!value) return "Date to be confirmed";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

function parseDueDate(value: string): Date | null {
  if (!value) return null;
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return null;
  const date = new Date(year, month - 1, day);
  return Number.isNaN(date.getTime()) ? null : date;
}

function dueDateLabel(value: string): string {
  const date = parseDueDate(value);
  if (!date) return "Choose a due date";
  return date.toLocaleDateString("en-ZA", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

function isoDay(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${date.getFullYear()}-${month}-${day}`;
}

export default function SecretaryMinutesUploadForm({
  meetings,
  boardMembers,
  minutes,
  meeting,
  onSaved,
}: {
  meetings: BoardMeeting[];
  boardMembers: BoardMember[];
  minutes?: BoardMinutes | null;
  meeting?: BoardMeeting | null;
  onSaved: () => void;
}) {
  const editing = !!minutes;
  const [rawDraft, setDraft, clearDraft] = usePersistentFormState<MinutesDraft>(
    `board-minutes-draft:${minutes?._id ?? "new"}`,
    minutes ? draftFromMinutes(minutes) : freshDraft(),
  );
  const draft = normalizeDraft(rawDraft);
  const [uploading, setUploading] = useState(false);
  const [publishing, setPublishing] = useState(false);
  const [duePicker, setDuePicker] = useState("");

  const patch = (next: Partial<MinutesDraft>) => {
    setDraft((current) => ({ ...normalizeDraft(current), ...next }));
  };

  const selectedId = editing
    ? minutes?.meetingId ?? ""
    : draft.meetingId || meetings[0]?._id || "";
  const activeMeeting = editing
    ? meeting ?? null
    : meetings.find((m) => m._id === selectedId) ?? null;

  const statusFor = (memberId: string): "ATTENDING" | "APOLOGY" => {
    const chosen = draft.attendance[memberId];
    if (chosen) return chosen;
    const rsvp = activeMeeting?.rsvps.find((r) => r.userId === memberId);
    return rsvp?.status === "APOLOGY" ? "APOLOGY" : "ATTENDING";
  };

  const mark = (memberId: string, status: "ATTENDING" | "APOLOGY") => {
    patch({ attendance: { ...draft.attendance, [memberId]: status } });
  };

  const reasonFor = (memberId: string): string => {
    const typed = draft.attendanceReasons[memberId];
    if (typed !== undefined) return typed;
    const rsvp = activeMeeting?.rsvps.find((r) => r.userId === memberId);
    return rsvp?.reason || "";
  };

  const setReason = (memberId: string, reason: string) => {
    patch({
      attendanceReasons: { ...draft.attendanceReasons, [memberId]: reason },
    });
  };

  const pickDocument = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ["images"],
      quality: 0.85,
    });
    if (result.canceled || !result.assets?.length) return;
    const asset = result.assets[0];
    const ext = asset.mimeType === "image/png" ? "png" : "jpg";
    const name = asset.fileName || `board-minutes-${Date.now()}.${ext}`;

    setUploading(true);
    try {
      const uploaded = await boardApi.uploadMinutesDocument({ uri: asset.uri, name });
      patch({
        documentUrl: uploaded.url,
        documentName: uploaded.fileName || name,
      });
    } catch (e: any) {
      Alert.alert("Upload failed", e?.message || "Please try again.");
    } finally {
      setUploading(false);
    }
  };

  const updateTask = (key: string, taskPatch: Partial<TaskDraft>) => {
    patch({
      tasks: draft.tasks.map((task) =>
        task.key === key ? { ...task, ...taskPatch } : task,
      ),
    });
  };

  const removeTask = (key: string) => {
    patch({ tasks: draft.tasks.filter((task) => task.key !== key) });
  };

  const publish = async () => {
    if (!selectedId) {
      Alert.alert("Choose a meeting", "Pick the meeting these minutes belong to.");
      return;
    }
    if (!draft.documentUrl.trim()) {
      Alert.alert(
        "Attach the minutes",
        "Upload a photo of the signed minutes or paste a document link.",
      );
      return;
    }

    const sections = draft.sections
      .map((section) => ({
        title: section.title.trim(),
        points: section.points.map((point) => point.trim()).filter(Boolean),
      }))
      .filter((section) => section.title || section.points.length);

    if (!sections.length) {
      Alert.alert(
        "Record the decisions",
        "Add a section and at least one point from the meeting.",
      );
      return;
    }

    const filled = draft.tasks.filter(
      (task) => task.description.trim() || task.assigneeId,
    );
    const incomplete = filled.find(
      (task) => !task.description.trim() || !task.assigneeId,
    );
    if (incomplete) {
      Alert.alert(
        "Finish the action item",
        "Every action item needs a task and an assignee.",
      );
      return;
    }

    setPublishing(true);
    try {
      const actionItems = filled.map((task) => ({
        ...(task.taskId ? { taskId: task.taskId } : {}),
        assigneeId: task.assigneeId,
        taskDescription: task.description.trim(),
        dueDate: task.dueDate.trim() || null,
      }));
      const attendance = boardMembers.map((member) => {
        const status = statusFor(member.id);
        return {
          userId: member.id,
          status,
          ...(status === "APOLOGY"
            ? { reason: reasonFor(member.id).trim() }
            : {}),
        };
      });

      if (minutes) {
        await boardApi.updateMinutes(minutes._id, {
          sections,
          minutesDocumentUrl: draft.documentUrl.trim(),
          attendance,
          actionItems,
        });
        await clearDraft();
        Alert.alert(
          "Minutes updated",
          "The corrections are in the archive; action items keep their progress.",
        );
        onSaved();
      } else {
        await boardApi.publishMinutes({
          meetingId: selectedId,
          sections,
          minutesDocumentUrl: draft.documentUrl.trim(),
          attendance,
          actionItems,
        });
        await clearDraft();
        setDraft(freshDraft());
        Alert.alert(
          "Minutes published",
          "The board has been notified and action items are on their trackers.",
        );
        onSaved();
      }
    } catch (e: any) {
      Alert.alert(
        editing ? "Could not update" : "Could not publish",
        e?.message || "Please try again.",
      );
    } finally {
      setPublishing(false);
    }
  };

  if (!editing && !meetings.length) {
    return (
      <View style={s.emptyBox}>
        <Ionicons name="document-text-outline" size={22} color={colors.muted} />
        <Text style={s.emptyTitle}>No past meetings to minute</Text>
        <Text style={s.emptyBody}>
          Minutes are logged for meetings that have already taken place. Schedule one from
          the Meetings screen first.
        </Text>
      </View>
    );
  }

  const hasContent =
    draft.sections.some(
      (section) => section.title.trim() || section.points.some((point) => point.trim()),
    ) ||
    draft.tasks.some((task) => task.description.trim()) ||
    !!draft.documentUrl.trim();

  return (
    <View style={{ gap: 12 }}>
      <View style={[s.card, editing && styles.editingCard]}>
        <View style={s.cardHead}>
          <Ionicons
            name={editing ? "create-outline" : "document-attach-outline"}
            size={16}
            color={colors.goldDark}
          />
          <Text style={s.cardTitle}>
            {editing ? "Edit meeting minutes" : "Log meeting minutes"}
          </Text>
        </View>
        <Text style={s.cardSub}>
          {editing
            ? "Correct anything that was captured wrongly — the signed document, attendance and action items can all change."
            : "Minutes are due within 48 hours. Late logs are kept and flagged in the archive."}
        </Text>

        {editing ? (
          <View style={styles.meetingChip}>
            <Ionicons name="calendar-clear-outline" size={13} color={colors.goldDark} />
            <View style={{ flex: 1 }}>
              <Text style={styles.meetingName}>
                {minutes?.meetingTitle || meeting?.title || "Board meeting"}
              </Text>
              <Text style={styles.meetingDate}>
                {shortDate(minutes?.meetingDate ?? meeting?.scheduledDate ?? null)}
              </Text>
            </View>
          </View>
        ) : (
          <>
            <Text style={s.fieldLabel}>Meeting</Text>
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              keyboardShouldPersistTaps="handled"
              contentContainerStyle={s.choiceRow}
            >
              {meetings.map((entry) => {
                const on = entry._id === selectedId;
                return (
                  <TouchableOpacity
                    key={entry._id}
                    style={[s.choice, on && s.choiceOn]}
                    onPress={() => patch({ meetingId: entry._id })}
                    activeOpacity={0.85}
                  >
                    <Text
                      style={[s.choiceText, on && s.choiceTextOn]}
                      numberOfLines={1}
                    >
                      {entry.title}
                    </Text>
                    <Text style={[s.choiceText, { fontSize: 11, marginTop: 2 }]}>
                      {shortDate(entry.scheduledDate)}
                    </Text>
                  </TouchableOpacity>
                );
              })}
            </ScrollView>
          </>
        )}

        <Text style={s.fieldLabel}>Attendance register</Text>
        {boardMembers.map((member) => {
          const apology = statusFor(member.id) === "APOLOGY";
          return (
            <View key={member.id} style={styles.memberBlock}>
              <View style={[s.memberRow, styles.memberRowPlain]}>
                <Text style={s.memberName} numberOfLines={1}>
                  {member.name}
                </Text>
                {(["ATTENDING", "APOLOGY"] as const).map((status) => {
                  const on = statusFor(member.id) === status;
                  return (
                    <TouchableOpacity
                      key={status}
                      style={[
                        s.choice,
                        { minWidth: 78, paddingHorizontal: 8 },
                        on && (status === "APOLOGY" ? s.choiceApologyOn : s.choiceOn),
                      ]}
                      onPress={() => mark(member.id, status)}
                      activeOpacity={0.85}
                    >
                      <Text
                        style={[
                          s.choiceText,
                          { fontSize: 12 },
                          on &&
                            (status === "APOLOGY"
                              ? s.choiceTextApology
                              : s.choiceTextOn),
                        ]}
                      >
                        {status === "ATTENDING" ? "Present" : "Apology"}
                      </Text>
                    </TouchableOpacity>
                  );
                })}
              </View>
              {apology ? (
                <TextInput
                  style={[s.input, styles.reasonInput]}
                  placeholder="Reason for the apology (optional)"
                  placeholderTextColor={colors.muted}
                  value={reasonFor(member.id)}
                  onChangeText={(reason) => setReason(member.id, reason)}
                  maxLength={300}
                  multiline
                  textAlignVertical="top"
                />
              ) : null}
            </View>
          );
        })}

        <MinutesSectionsEditor
          value={draft.sections}
          onChange={(sections) => patch({ sections })}
        />

        <Text style={s.fieldLabel}>Signed minutes</Text>
        <TouchableOpacity
          style={s.pickBtn}
          onPress={pickDocument}
          disabled={uploading}
          activeOpacity={0.85}
        >
          {uploading ? (
            <ActivityIndicator color={colors.goldDark} />
          ) : (
            <>
              <Ionicons name="camera-outline" size={18} color={colors.goldDark} />
              <Text style={s.pickText}>
                {draft.documentName ? "Replace scan" : "Scan or choose a photo of the minutes"}
              </Text>
            </>
          )}
        </TouchableOpacity>
        {draft.documentName ? (
          <Text style={s.docName} numberOfLines={1}>
            {draft.documentName}
          </Text>
        ) : null}
        <Text style={s.hint}>
          PDF minutes into the portal from the web dashboard; on mobile a clear photo of the
          signed pages is accepted.
        </Text>
        <TextInput
          style={s.input}
          placeholder="…or paste a PDF / document link"
          placeholderTextColor={colors.muted}
          value={draft.documentUrl}
          onChangeText={(documentUrl) =>
            patch({ documentUrl, ...(documentUrl ? {} : { documentName: "" }) })
          }
          autoCapitalize="none"
          keyboardType="url"
        />

        {hasContent ? (
          <View style={styles.savedRow}>
            <Ionicons
              name="checkmark-circle-outline"
              size={12}
              color={colors.goldDark}
            />
            <Text style={styles.savedText}>
              Draft saved automatically — you can leave the app and come back.
            </Text>
          </View>
        ) : null}
      </View>

      <View style={s.card}>
        <View style={s.cardHead}>
          <Ionicons name="checkbox-outline" size={16} color={colors.goldDark} />
          <Text style={s.cardTitle}>Action items</Text>
        </View>
        <Text style={s.cardSub}>
          Assign each task to a board member; they can move it from pending to done on their
          tracker.
        </Text>

        {draft.tasks.map((task, index) => (
          <View key={task.key} style={s.taskCard}>
            <View style={s.taskHead}>
              <Text style={s.taskIndex}>TASK {index + 1}</Text>
              <TouchableOpacity
                onPress={() => removeTask(task.key)}
                accessibilityLabel="Remove action item"
              >
                <Text style={s.removeLink}>Remove</Text>
              </TouchableOpacity>
            </View>
            <TextInput
              style={s.input}
              placeholder="What must be done?"
              placeholderTextColor={colors.muted}
              value={task.description}
              onChangeText={(description) => updateTask(task.key, { description })}
              maxLength={600}
            />
            <Text style={s.fieldLabel}>Assignee</Text>
            <View style={s.choiceRow}>
              {boardMembers.map((member) => {
                const on = task.assigneeId === member.id;
                return (
                  <TouchableOpacity
                    key={member.id}
                    style={[s.choice, on && s.choiceOn]}
                    onPress={() => updateTask(task.key, { assigneeId: member.id })}
                    activeOpacity={0.85}
                  >
                    <Text style={[s.choiceText, on && s.choiceTextOn]} numberOfLines={1}>
                      {member.name}
                    </Text>
                  </TouchableOpacity>
                );
              })}
            </View>
            <Text style={s.fieldLabel}>Due date</Text>
            <View style={styles.dueRow}>
              <TouchableOpacity
                style={[styles.dueBtn, !task.dueDate && styles.dueBtnEmpty]}
                onPress={() =>
                  setDuePicker(duePicker === task.key ? "" : task.key)
                }
                activeOpacity={0.8}
                accessibilityLabel="Choose the due date"
              >
                <Ionicons name="calendar-outline" size={16} color={colors.goldDark} />
                <Text
                  style={[styles.dueText, !task.dueDate && styles.duePlaceholder]}
                  numberOfLines={1}
                >
                  {dueDateLabel(task.dueDate)}
                </Text>
              </TouchableOpacity>
              {task.dueDate ? (
                <TouchableOpacity
                  style={styles.dueClear}
                  onPress={() => updateTask(task.key, { dueDate: "" })}
                  accessibilityLabel="Clear the due date"
                >
                  <Ionicons name="close-circle" size={19} color={colors.muted} />
                </TouchableOpacity>
              ) : null}
            </View>
            {duePicker === task.key ? (
              <View style={styles.duePanel}>
                <InlineCalendar
                  value={parseDueDate(task.dueDate)}
                  onSelect={(date) => {
                    updateTask(task.key, { dueDate: isoDay(date) });
                    setDuePicker("");
                  }}
                />
              </View>
            ) : null}
          </View>
        ))}

        <TouchableOpacity
          style={s.secondaryBtn}
          onPress={() =>
            patch({ tasks: [...draft.tasks, newTask(boardMembers[0]?.id || "")] })
          }
          activeOpacity={0.85}
        >
          <Ionicons name="add-circle-outline" size={17} color={colors.goldDark} />
          <Text style={s.secondaryText}>Add action item</Text>
        </TouchableOpacity>
      </View>

      <TouchableOpacity
        style={[s.primaryBtn, publishing && s.busy]}
        onPress={publish}
        disabled={publishing || uploading}
        activeOpacity={0.9}
      >
        <GradientBox gradient="limeReversed" style={StyleSheet.absoluteFill} />
        {publishing ? (
          <ActivityIndicator color={colors.white} />
        ) : (
          <>
            <Ionicons
              name={editing ? "save-outline" : "cloud-upload-outline"}
              size={18}
              color={colors.white}
            />
            <Text style={s.primaryText}>
              {editing ? "Save changes" : "Publish minutes & notify board"}
            </Text>
          </>
        )}
      </TouchableOpacity>
    </View>
  );
}

