import { Ionicons } from "@expo/vector-icons";
import { useMemo, useState } from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { colors } from "@/constants/colors";
import type { ProgramCalendarEntry } from "@/services/program-calendar";

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

function parseDate(iso: string): Date {
  return new Date(`${iso}T00:00:00`);
}

/**
 * A club's year calendar, grouped by month. Tapping a date opens that date's
 * details (what happens, term, time, place) right under the row — the same
 * dates the web club page shows under Programs & Activities.
 */
export default function ProgramCalendar({
  entries,
  year,
  clubColor,
}: {
  entries: ProgramCalendarEntry[];
  year: number;
  clubColor: string;
}) {
  const [openId, setOpenId] = useState<string | null>(null);

  const months = useMemo(() => {
    const sorted = [...entries].sort(
      (a, b) =>
        a.date.localeCompare(b.date) || a.title.localeCompare(b.title),
    );
    const groups: { month: number; rows: ProgramCalendarEntry[] }[] = [];
    for (const entry of sorted) {
      const month = Number(entry.date.slice(5, 7)) - 1;
      const last = groups[groups.length - 1];
      if (last && last.month === month) last.rows.push(entry);
      else groups.push({ month, rows: [entry] });
    }
    return groups;
  }, [entries]);

  if (entries.length === 0) return null;

  return (
    <>
      {months.map((group) => (
        <View key={group.month}>
          <Text style={styles.month}>
            {MONTHS[group.month]} {year}
          </Text>
          <View style={styles.list}>
            {group.rows.map((entry) => {
              const when = parseDate(entry.date);
              const isOpen = openId === entry.id;
              const meta = [entry.time, entry.location, entry.setting]
                .filter(Boolean)
                .join(" · ");
              return (
                <View key={entry.id} style={styles.rowWrap}>
                  <TouchableOpacity
                    style={styles.row}
                    activeOpacity={0.75}
                    onPress={() => setOpenId(isOpen ? null : entry.id)}
                    accessibilityRole="button"
                    accessibilityState={{ expanded: isOpen }}
                    accessibilityLabel={`${entry.title} — ${when.toDateString()}`}
                  >
                    <View style={[styles.dateChip, { backgroundColor: `${clubColor}1a` }]}>
                      <Text style={styles.dateWeekday}>
                        {when.toLocaleDateString(undefined, { weekday: "short" })}
                      </Text>
                      <Text style={styles.dateDay}>{when.getDate()}</Text>
                    </View>
                    <View style={styles.body}>
                      <View style={styles.titleRow}>
                        <Text style={styles.title} numberOfLines={2}>
                          {entry.title}
                        </Text>
                        {entry.setting ? (
                          <View style={styles.chip}>
                            <Text style={styles.chipText}>{entry.setting}</Text>
                          </View>
                        ) : null}
                      </View>
                      {entry.description && !isOpen ? (
                        <Text style={styles.blurb} numberOfLines={2}>
                          {entry.description}
                        </Text>
                      ) : null}
                      {meta ? <Text style={styles.meta}>{meta}</Text> : null}
                    </View>
                    <Ionicons
                      name={isOpen ? "chevron-up" : "chevron-down"}
                      size={16}
                      color={colors.goldDark}
                      style={styles.chevron}
                    />
                  </TouchableOpacity>
                  {isOpen && entry.description ? (
                    <View style={styles.detail}>
                      {entry.term ? <Text style={styles.detailTerm}>{entry.term}</Text> : null}
                      <Text style={styles.detailText}>{entry.description}</Text>
                    </View>
                  ) : null}
                </View>
              );
            })}
          </View>
        </View>
      ))}
    </>
  );
}

