import { AppState } from "react-native";
import * as Notifications from "expo-notifications";
import { router } from "expo-router";
import { fetchMobileBadges } from "./mobile-badges";
import { getSession } from "./auth";
import { IS_WEB } from "./config";
import {
  setNotifUnread,
  getNotifUnread,
  setRequestsUnread,
  getRequestsUnread,
} from "./unread";

// No polling. The server pushes whenever a notification is created (help
// request, reply, assignment, status change, ...), so a push receipt is the
// real-time signal to refresh the unread counts. Pushes received while the app
// is backgrounded are redelivered by the OS when the app returns to the
// foreground, which re-fires the receipt handler and refreshes the badge — so
// there is no dedicated foreground-resume fetch (that would needlessly hit the
// unread endpoints on every resume even when nothing changed).
let running = false;
let role: "admin" | "user" | null = null;
let appActive = true;
let inFlight = false;
let lastRefreshAt = 0;
const REFRESH_MIN_GAP_MS = 30_000;
let appStateSub: { remove: () => void } | null = null;
let pushSub: { remove: () => void } | null = null;
let pushResponseSub: { remove: () => void } | null = null;
const PUSH_ROUTES = new Set(["/onboarding-induction", "/club-chat"]);
let handledResponseId: string | null = null;

function routeFromPushResponse(response: Notifications.NotificationResponse) {
  const data = response.notification.request.content.data as Record<
    string,
    unknown
  > | null;
  const route = typeof data?.route === "string" ? data.route : null;
  if (!route || !PUSH_ROUTES.has(route)) return;

  const notificationId = response.notification.request.identifier;
  if (handledResponseId === notificationId) return;
  handledResponseId = notificationId;

  const params: Record<string, string> = {};
  if (typeof data?.action === "string") params.action = data.action;
  if (typeof data?.submissionId === "string") {
    params.submissionId = data.submissionId;
  }
  if (typeof data?.status === "string") params.status = data.status;
  setTimeout(() => {
    router.push({ pathname: route, params } as any);
  }, 0);
}

function consumeInitialNotificationResponse() {
  try {
    const response = Notifications.getLastNotificationResponse();
    if (response) routeFromPushResponse(response);
  } catch {}
}

function ensureAppStateListener() {
  if (appStateSub) return;
  appStateSub = AppState.addEventListener("change", (state) => {
    // Track foreground/background so the push-received handler only refreshes
    // while the app is active. Pushes received in the background are redelivered
    // on foreground (Expo behavior), so leaving the refresh to that redelivery
    // keeps the badge correct without a redundant foreground-resume fetch.
    appActive = state === "active";
  });
}

// Pushes fire exactly when the server creates a notification, so a receipt is
// the real-time signal to refresh the badges.
function ensurePushListener() {
  if (pushSub) return;
  pushSub = Notifications.addNotificationReceivedListener((notification) => {
    if (!running || !appActive) return;
    // Local prayer-time alerts aren't server notifications — skip the refresh.
    const data = notification.request.content.data as Record<string, unknown> | null;
    if (data?.prayer) return;
    refreshCounts();
  });
  pushResponseSub = Notifications.addNotificationResponseReceivedListener((response) => {
    if (!running) return;
    // User tapped a push — make sure badges are current, then deep link.
    refreshCounts();
    routeFromPushResponse(response);
  });
}

async function refreshCounts() {
  // Skip overlapping refreshes (several pushes at once, or a push racing an
  // app-resume refresh) and bursty repeats (many pushes / rapid resumes) so
  // the unread endpoints aren't hammered more than once per gap.
  const now = Date.now();
  if (now - lastRefreshAt < REFRESH_MIN_GAP_MS) return;
  if (inFlight) return;
  lastRefreshAt = now;
  inFlight = true;
  try {
    const badges = await fetchMobileBadges({ cacheTtl: 0 }).catch(() => null);

    setNotifUnread(badges ? badges.data.unread : getNotifUnread());
    setRequestsUnread(
      badges
        ? role === "admin"
          ? badges.data.adminUnread
          : badges.data.userUnread
        : getRequestsUnread(),
    );
  } finally {
    inFlight = false;
  }
}

/** Starts push-driven live updates (no polling). Idempotent. */
export async function startLiveNotifications() {
  if (IS_WEB) return;
  if (running) return;
  try {
    const session = await getSession();
    role = session?.user?.role === "admin" ? "admin" : "user";
  } catch {
    role = "user";
  }
  running = true;
  ensureAppStateListener();
  ensurePushListener();
  consumeInitialNotificationResponse();
  await refreshCounts();
}

export function stopLiveNotifications() {
  if (IS_WEB) return;
  running = false;
  if (appStateSub) {
    appStateSub.remove();
    appStateSub = null;
  }
  if (pushSub) {
    pushSub.remove();
    pushSub = null;
  }
  if (pushResponseSub) {
    pushResponseSub.remove();
    pushResponseSub = null;
  }
  appActive = true;
}
